package com.bedalton.creatures.sprite.util

import com.bedalton.creatures.common.structs.GameVariant

fun dynamicToPaletteTransform(transform: dynamic): PaletteTransform? {
    if (transform == null) {
        return null
    }
    fun get(key: String): Any? {
        return if (jsTypeOf(transform[key]) != "undefined") {
            transform[key]
        } else {
            null
        }
    }

    val variant = get("variant")
        ?.let {
            GameVariant.fromString(it.unsafeCast<String>())
        }
        ?: throw Exception("Game variant ${get("variant")} is invalid or null")
    return PaletteTransform(
        gameVariant = variant,
        red = get("red") as? Int?,
        green = get("green") as Int?,
        blue = get("blue") as Int?,
        swap = get("swap") as Int?,
        rotation = get("rotation") as Int?
    )
}