package com.creaturesforge.application.state

import kotlinx.coroutines.CancellationException


internal sealed class EventAction: FAction()

internal sealed class CompileEggAction: EventAction()

internal sealed class EggCompileRunning: CompileEggAction()

internal data class CompileEggStartedAction(val outputFile: String): EggCompileRunning()

internal data class CompileEggCompletedAction(val outputFile: String): CompileEggAction()

internal data class CompileEggFailedAction(val message: String, val throwable: Throwable? = null): CompileEggAction() {
    init {
        if (throwable is CancellationException) {
            throw throwable
        }
    }
}

internal data class CompileEggProgress(val progress: Double?): EggCompileRunning(), DoNotLogThisAction

internal data object CompileEggCancelledAction: CompileEggAction()


@Suppress("unused")
internal data class ErrorAction(val title: String, val message: String, val throwable: Throwable? = null): EventAction()