@file:Suppress("unused", "MemberVisibilityCanBePrivate")

package com.bedalton.creatures.agents.pray.data

import com.bedalton.creatures.agents.pray.compiler.writeBlockHeader
import com.bedalton.creatures.agents.pray.exceptions.AgentFileDecompilerException
import com.bedalton.io.bytes.ByteStreamReader
import com.bedalton.io.bytes.ByteStreamWriter


class GLSTBlock(
    val commonName: String,
    val format: Int,
    override val blockTag: String,
    override val blockName: String,
    makeHistory: () -> Array<History>,
) : PrayBlock(blockTag, blockName) {

    private var mMakeHistory: (() -> Array<History>)? = makeHistory

    constructor(
        commonName: String,
        format: Int,
        blockTag: String,
        blockName: String,
        safe: Boolean,
        bytes: () -> ByteArray,
    ) : this(
        commonName,
        format,
        blockTag,
        blockName,
        historyParser(safe, bytes)
    )

    val historyBlocks by lazy {
        val make = mMakeHistory
            ?: throw AgentFileDecompilerException("Cannot write history blocks. Data block already closed")
        val result = try {
            make()
        } catch (e: Exception) {
            emptyArray()
        }
        mMakeHistory = null
        result
    }


    override fun write(writer: ByteStreamWriter, compress: Boolean) {
        val historyBlocks = historyBlocks
        writeBlockHeader(writer, this)
        writer.writeUInt32(if (format == GLST_FORMAT_DS) 0x27 else 0x0C)
        writer.writeUInt32(historyBlocks.size)
        for (history in historyBlocks) {
            writer.write(history)
        }
    }

    companion object {
        const val GLST_FORMAT_C3 = 1
        const val GLST_FORMAT_DS = 2

        private fun historyParser(safe: Boolean, data: () -> ByteArray): () -> Array<History> {
            return f@{
                ByteStreamReader.read(data()) {
                    val reader = this
                    val format = when (val firstChar = reader.uInt8()) {
                        0x27 -> GLST_FORMAT_DS
                        0x0C -> GLST_FORMAT_C3
                        else -> throw AgentFileDecompilerException("Could not determine GLST version from $firstChar")
                    }
                    reader.skip(3)
                    val numberOfMonikers = reader.uInt32()
                    val histories = (0 until numberOfMonikers).map {
                        val moniker = reader.string()
                        val name = reader.string()
                        val gender = reader.uInt32().toInt()
                        val genus = reader.uInt32().toInt()
                        val species = reader.uInt32().toInt()
                        val theEvents = (0 until reader.uInt32()).mapNotNull {
                            reader.readEvent(format, safe)
                        }.toTypedArray()
                        val pointsOfMutation = reader.uInt32().toInt()
                        val crossoverPoints = reader.uInt32().toInt()
                        if (format == GLST_FORMAT_DS) {
                            History(
                                format,
                                moniker,
                                name,
                                gender,
                                genus,
                                species,
                                theEvents,
                                pointsOfMutation,
                                crossoverPoints,
                                needsUploading = reader.uInt32().toInt(),
                                hasBeenInWarp = reader.uInt32() != 0L,
                                uploadedName = reader.string()
                            )
                        } else {
                            History(
                                format,
                                moniker,
                                name,
                                gender,
                                genus,
                                species,
                                theEvents,
                                pointsOfMutation,
                                crossoverPoints
                            )
                        }
                    }
                    histories.toTypedArray()
                }
            }
        }

        private fun ByteStreamReader.readEvent(format: Int, safe: Boolean = true): CreatureEvent {
            val eventNumber = uInt32().toInt()
            if (eventNumber >= 18 && !safe) {
                throw AgentFileDecompilerException("Invalid event type: $eventNumber")
            }
            val worldTimeInTicks = uInt32().toInt()
            val creatureAgeInTicks = uInt32().toInt()
            val timestamp = uInt32().toInt()
            val lifeStage = uInt32().toInt()
            val moniker1 = string(uInt32())
            val moniker2 = string(uInt32())
            val userText = string(uInt32())
            val photograph = string(uInt32())
            val worldName = string(uInt32())
            val worldUID = string(uInt32())
            val beforePosition = position()
            return if (format == GLST_FORMAT_DS) {
                try {
                    // conflicting information on how to read the DS block
                    CreatureEvent(
                        eventNumber,
                        worldTimeInTicks,
                        creatureAgeInTicks,
                        timestamp,
                        lifeStage,
                        moniker1,
                        moniker2,
                        userText,
                        photograph,
                        worldName,
                        worldUID,
                        string(uInt32()),
                        uInt32() == 1L,
                        string(uInt32())
                    )
                } catch (e: Exception) {
                    setPosition(beforePosition)
                    try {
                        CreatureEvent(
                            eventNumber,
                            worldTimeInTicks,
                            creatureAgeInTicks,
                            timestamp,
                            lifeStage,
                            moniker1,
                            moniker2,
                            userText,
                            photograph,
                            worldName,
                            worldUID,
                            string(uInt32()),
                            uInt32() != 0L,
                            null
                        ).apply {
                            uInt32()
                        }
                    } catch (e2: Exception) {
                        throw AgentFileDecompilerException("Neither format for DS GLST blocks proved valid")
                    }
                }
            } else {
                CreatureEvent(
                    eventNumber,
                    worldTimeInTicks,
                    creatureAgeInTicks,
                    timestamp,
                    lifeStage,
                    moniker1,
                    moniker2,
                    userText,
                    photograph,
                    worldName,
                    worldUID,
                    string(uInt32()),
                    uInt32() != 0L,
                    null
                )
            }
        }
    }

}


data class History(
    val format: Int,
    val moniker: String,
    val name: String,
    val gender: Int,
    val genus: Int,
    val species: Int,
    val events: Array<CreatureEvent>,
    val mutationPoints: Int,
    val crossoverPoints: Int,
    val needsUploading: Int? = null,
    val hasBeenInWarp: Boolean = false,
    val uploadedName: String? = null,

    ) {
    val typedEvents by lazy {
        events
            .mapNotNull {
                TypedCreatureEvent.fromEvent(it)
            }
            .toTypedArray()
    }

    override fun equals(other: Any?): Boolean {
        if (this === other) return true
        if (other !is History) return false

        if (format != other.format) return false
        if (moniker != other.moniker) return false
        if (name != other.name) return false
        if (gender != other.gender) return false
        if (genus != other.genus) return false
        if (species != other.species) return false
        if (!events.contentEquals(other.events)) return false
        if (mutationPoints != other.mutationPoints) return false
        if (crossoverPoints != other.crossoverPoints) return false
        if (needsUploading != other.needsUploading) return false
        if (hasBeenInWarp != other.hasBeenInWarp) return false
        if (uploadedName != other.uploadedName) return false

        return true
    }

    override fun hashCode(): Int {
        var result = format
        result = 31 * result + moniker.hashCode()
        result = 31 * result + name.hashCode()
        result = 31 * result + gender
        result = 31 * result + genus
        result = 31 * result + species
        result = 31 * result + events.contentHashCode()
        result = 31 * result + mutationPoints
        result = 31 * result + crossoverPoints
        result = 31 * result + (needsUploading ?: 0)
        result = 31 * result + hasBeenInWarp.hashCode()
        result = 31 * result + (uploadedName?.hashCode() ?: 0)
        return result
    }
}

data class CreatureEvent(
    val event: Int,
    val timeInTicks: Int,
    val creaturesAgeInTicks: Int,
    val unixTimestamp: Int,
    val lifeStage: Int,
    internal val moniker1: String,
    internal val moniker2: String,
    internal val userText: String?,
    val photBlockName: String?,
    val worldName: String,
    val worldUniqueId: String,
    val dockingStationUserID: String?, // fileVersion 0x27 only
    val dockingStationNeedsUploading: Boolean?, // fileVersion 0x27 only
    val dockingStationUploadedUserText: String?, // fileVersion 0x27 only
)

sealed class TypedCreatureEvent(
    val event: CreatureEvent,
) {
    abstract val type: Int
    val eventType: Int get() = event.event
    val timeInTicks: Int get() = event.timeInTicks
    val creaturesAgeInTicks: Int get() = event.creaturesAgeInTicks
    val unixTimestamp: Int get() = event.unixTimestamp
    val lifeStage: Int get() = event.lifeStage
    val photBlockName: String? get() = event.photBlockName
    val worldName: String get() = event.worldName
    val worldUniqueId: String get() = event.worldUniqueId
    val dockingStationUserID: String? get() = event.dockingStationUserID // fileVersion 0x27 only
    val dockingStationNeedsUploading: Boolean? get() = event.dockingStationNeedsUploading // fileVersion 0x27 only
    val dockingStationUploadedUserText: String? get() = event.dockingStationUploadedUserText // fileVersion 0x27 only


    companion object {
        fun fromEvent(event: CreatureEvent): TypedCreatureEvent? {
            return when (event.event) {
                CreatureEventType.CONCEIVED -> ConceptionEvent(event)
                CreatureEventType.SPLICED -> SplicedEvent(event)
                CreatureEventType.ENGINEERED -> EngineeredEvent(event)
                CreatureEventType.HATCHED -> HatchedEvent(event)
                CreatureEventType.LIFE_STAGE -> LifeStageEvent(event)
                CreatureEventType.EXPORTED -> ExportedEvent(event)
                CreatureEventType.IMPORTED -> ImportedEvent(event)
                CreatureEventType.DIED -> DiedEvent(event)
                CreatureEventType.GOT_PREGNANT -> GotPregnantEvent(event)
                CreatureEventType.GOT_SOMEONE_PREGNANT -> GotSomeonePregnantEvent(event)
                CreatureEventType.CHILD_BORN -> ChildBornEvent(event)
                CreatureEventType.MY_EGG_WAS_LAID -> MyEggWasLaidEvent(event)
                CreatureEventType.LAID_AN_EGG -> LaidEggEvent(event)
                CreatureEventType.PHOTO_TAKEN -> PhotoTakenEvent(event)
                CreatureEventType.I_WAS_CLONED -> IWasClonedEvent(event)
                CreatureEventType.CREATURE_CLONED_FROM_ME -> CreatureClonedFromMeEvent(event)
                CreatureEventType.DS_WARPED_OUT -> WarpedOutEvent(event)
                CreatureEventType.DS_WARPED_IN -> WarpedInEvent(event)
                else -> null
            }
        }
    }
}


