object CreatureEventType {
    const val CONCEIVED = 0
    const val SPLICED = 1
    const val ENGINEERED = 2
    const val HATCHED = 3
    const val LIFE_STAGE = 4
    const val EXPORTED = 5
    const val IMPORTED = 6
    const val DIED = 7
    const val GOT_PREGNANT = 8
    const val GOT_SOMEONE_PREGNANT = 9
    const val CHILD_BORN = 10
    const val MY_EGG_WAS_LAID = 11
    const val LAID_AN_EGG = 12
    const val PHOTO_TAKEN = 13
    const val I_WAS_CLONED = 14
    const val CREATURE_CLONED_FROM_ME = 15
    const val DS_WARPED_OUT = 16 // file version 0x27 only
    const val DS_WARPED_IN = 17 // file version 0x27 only
}

private fun ByteStreamReader.string(): String = string(uInt32())


private fun ByteStreamWriter.write(history: History) {
    string(history.moniker)
    string(history.name)
    writeUInt32(history.gender)
    writeUInt32(history.genus)
    writeUInt32(history.species)
    val events = history.events
    writeUInt32(events.size)
    for (event in events) {
        write(event, history.format)
    }
    writeUInt32(history.mutationPoints)
    writeUInt32(history.crossoverPoints)
    if (history.format == GLSTBlock.GLST_FORMAT_DS) {
        writeUInt32(history.needsUploading ?: 0)
        writeBool(history.hasBeenInWarp)
        string(history.uploadedName ?: "")
    }
}

private fun ByteStreamWriter.write(event: CreatureEvent, format: Int): ByteStreamWriter {
    writeUInt32(event.event)
    writeUInt32(event.timeInTicks)
    writeUInt32(event.creaturesAgeInTicks)
    writeUInt32(event.unixTimestamp)
    writeUInt32(event.lifeStage)
    string(event.moniker1)
    string(event.moniker2)
    string(event.userText ?: "")
    string(event.photBlockName ?: "")
    string(event.worldName)
    if (format == GLSTBlock.GLST_FORMAT_DS) {
        string(event.dockingStationUserID ?: "")
        writeUInt32(if (event.dockingStationNeedsUploading == true) 1 else 0)
        string(event.dockingStationUploadedUserText ?: "")
    }
    return this
}

private fun ByteStreamWriter.string(string: String): ByteStreamWriter {
    return writeUInt32(string.length)
        .writeStringWithCreaturesEncoding(string)
}

private fun ByteStreamWriter.writeBool(value: Boolean): ByteStreamWriter {
    return writeUInt32(if (value) 1 else 0)
}