@file:Suppress("unused")

package com.bedalton.creatures.common.util

import com.bedalton.creatures.common.structs.GameVariant
import com.bedalton.creatures.common.structs.isC1e

fun getGenusInt(genusString: String): Int {
    return when (genusString.lowercase()) {
        "n", "norn" -> 0
        "g", "grendel" -> 1
        "e", "ettin" -> 2
        "s", "shee", "geat" -> 3
        else -> throw Exception("Invalid genus type: $genusString;")
    }
}

fun getGenusString(genus: Int, variant: GameVariant? = null): String? {
    return when (genus) {
        0 -> "Norn"
        1 -> "Grendel"
        2 -> "Ettin"
        3 -> {
            if (variant?.isC1e == true) {
                "Shee"
            } else {
                "Geat"
            }
        }

        else -> null
    }
}

