package com.bedalton.vfs

import com.bedalton.common.exceptions.IOReadException

class FileNotFoundException(val file: String, message: String, throwable: Throwable? = null)
    : IOReadException(message, throwable) {
            constructor(file: String, throwable: Throwable? = null): this(
                file,
                "Failed to locate file: $file",
                throwable
            )
    }