package com.creaturesforge.application.state

import com.bedalton.common.util.formatted
import com.bedalton.log.Log
import kotlinx.coroutines.GlobalScope
import kotlinx.coroutines.launch

internal actual fun cacheAgentOpenDirectory(root: String) {
    GlobalScope.launch {
        try {
            ForgeConfig.setLastEggImportDirectory(root)
        } catch (e: Exception) {
            Log.e("Failed to setLastEggImportDirectory; ${e.formatted(true)}")
        }
    }
}