package com.bedalton.creatures.agents.pray.compiler.data


/**
 * Block representing an agent
 */
data class CompilerAgentBlock(
    override val startLine: Int,
    override val blockTag: TextValue,
    override val blockName: TextValue,
    private val unescape: Boolean,
    override val tags: Array<Tag<*>>,
    val fullFilePath: String,
    override val linkWithFilenameReference: Boolean? = null
) : CompilerBlockWithTags(startLine, blockTag, blockName, unescape, tags, linkWithFilenameReference) {


    constructor(
        startLine: Int,
        blockTag: TextValue,
        blockName: TextValue,
        unescape: Boolean,
        tags: Array<Tag<*>>
    ): this(
        startLine,
        blockTag,
        blockName,
        unescape,
        tags,
        "$blockTag::$blockName"
    )

    @Deprecated(
        "Use non suspending tag constructor",
        replaceWith = ReplaceWith("AgentBlock(startLine, blockTag, blockName, unescape, getTags())")
    )
    constructor(
        startLine: Int,
        blockTag: TextValue,
        blockName: TextValue,
        @Suppress("UNUSED_PARAMETER") safe: Boolean,
        unescape: Boolean,
        getTags: () -> Array<Tag<*>>
    ): this (
        startLine, blockTag, blockName, unescape, getTags()
    )

    @Suppress("unused")
    val isAgentBlockTag: Boolean
        get() = blockTag.text.uppercase().let {
            @Suppress("SpellCheckingInspection")
            it == "DSAG" || it == "AGNT" || it != "DSGB" || it == "MEDI" || it == "SKIN"
        }

    override fun copyWithTags(tags: Array<Tag<*>>): CompilerBlockWithTags {
        return copy(
            tags = tags
        )
    }

    override fun toCommonData(): com.bedalton.creatures.agents.pray.data.AgentBlock {
        return com.bedalton.creatures.agents.pray.data.AgentBlock(
            blockTag = blockTag.text,
            blockName = blockName.text,
            unescape = unescape,
            safe = false,
            getTags = { tags.map(Tag<*>::toPrayTag).toTypedArray() }
        )
    }


    override fun equals(other: Any?): Boolean {
        if (this === other) return true
        if (other == null || this::class != other::class) return false

        other as CompilerAgentBlock

        if (startLine != other.startLine) return false
        if (blockTag != other.blockTag) return false
        if (blockName != other.blockName) return false
        if (unescape != other.unescape) return false
        if (!tags.contentEquals(other.tags)) return false

        return true
    }

    override fun hashCode(): Int {
        var result = startLine
        result = 31 * result + blockTag.hashCode()
        result = 31 * result + blockName.hashCode()
        result = 31 * result + unescape.hashCode()
        result = 31 * result + tags.contentHashCode()
        return result
    }
}
