package com.bedalton.log

import kotlin.contracts.InvocationKind
import kotlin.contracts.contract


/**
 * Run log callback if mode is set to true
 */
inline fun Log.withLog(mode: String, callback: (mode: String) -> Unit) {
    contract {
        callsInPlace(callback, InvocationKind.AT_MOST_ONCE)
    }
    if (!silent && hasMode(mode)) {
        callback(mode)
    }
}

/**
 * Log info message if mode is set to true
 */
inline fun Log.iWith(mode: String, replace: Boolean = false, color: LoggerColor? = null, callback: () -> String) {
    contract {
        callsInPlace(callback, InvocationKind.AT_MOST_ONCE)
    }
    if (!silent && hasMode(mode)) {
        if (enableNamespaceLoggingInMain) {
            i(replace, color, "%$mode%${callback()}")
        }
        notifyNamespaceListeners(mode, callback, color)
    }
}

