package com.bedalton.creatures.agents.pray.compiler.data

import com.bedalton.creatures.agents.pray.compiler.CompilerOptionsDefault.LINK_WITH_FILENAME_REFERENCE_DEFAULT
import com.bedalton.creatures.agents.pray.compiler.internal.writeBlock
import com.bedalton.creatures.agents.util.RelativeFileSystem
import com.bedalton.io.bytes.ByteStreamWriter
import kotlinx.coroutines.CoroutineScope
import kotlin.js.JsName
import kotlin.reflect.KClass


/**
 * Represents block with tags such as EGGS, AGNT, DSAG, etc
 */
sealed class CompilerBlockWithTags(
    startLine: Int,
    blockTag: TextValue,
    blockName: TextValue,
    private val unescape: Boolean,
    open val tags: Array<Tag<*>>,
    open val linkWithFilenameReference: Boolean? = null
) : CompilerPrayBlock(startLine, blockTag, blockName) {


    @Deprecated(
        "Use non suspending tag constructor",
        replaceWith = ReplaceWith("BlockWithTags(startLine, blockTag, blockName, unescape, getTags())")
    )
    constructor(
        startLine: Int,
        blockTag: TextValue,
        blockName: TextValue,
        @Suppress("UNUSED_PARAMETER") safe: Boolean,
        unescape: Boolean,
        getTags: () -> Array<Tag<*>>
    ): this(
        startLine,
        blockTag,
        blockName,
        unescape,
        getTags()
    )

    // Combination of all tags for iteration
    // TODO see if this is ever needed
    @Deprecated(
        "use val tags instead",
        replaceWith = ReplaceWith(
            "tags"
        )
    )
    @JsName("getTags")
    fun tags(): Array<Tag<*>> = tags

    @JsName("getStringTags")
    @Deprecated(
        "use val stringTags instead",
        replaceWith = ReplaceWith(
            "stringTags"
        )
    )
    fun stringTags(): Array<Tag.StringTag> = stringTags

    val stringTags: Array<Tag.StringTag> by lazy {
        tags.filterIsInstance<Tag.StringTag>().toTypedArray()
    }

    @Deprecated(
        "use val intTags instead",
        replaceWith = ReplaceWith(
            "intTags"
        )
    )
    @JsName("getIntTags")
    fun intTags(): Array<Tag.IntTag> = intTags

    val intTags: Array<Tag.IntTag> by lazy {
        tags.filterIsInstance<Tag.IntTag>().toTypedArray()
    }


    /**
     * Gets the last tag with the tag name given
     */
    fun get(tag: String, last: Boolean = true): Tag<*>? {
        return if (last)
            tags.lastOrNull { it.tag.equals(tag, true) }
        else
            tags.firstOrNull { it.tag.equals(tag, true) }
    }

    /**
     * Gets a tag given a types class
     */
    internal inline fun <reified T : KClass<Tag<*>>> get(tag: String, last: Boolean = true): T? {
        return if (last)
            tags.filterIsInstance<T>().lastOrNull { (it as Tag<*>).tag.equals(tag, true) }
        else
            tags.filterIsInstance<T>().firstOrNull { (it as Tag<*>).tag.equals(tag, true) }
    }

    abstract fun copyWithTags(tags: Array<Tag<*>>): CompilerBlockWithTags

    override suspend fun write(coroutineScope: CoroutineScope, fs: RelativeFileSystem, writer: ByteStreamWriter, compression: Int) {
        writeBlock(coroutineScope, fs, writer, this, compression, unescape, linkWithFilenameReference ?: LINK_WITH_FILENAME_REFERENCE_DEFAULT)
    }
}


