package com.bedalton.creatures.agents.pray.compiler.pray.validators

import com.bedalton.common.util.like
import com.bedalton.common.util.nullIfEmpty
import com.bedalton.creatures.agents.pray.compiler.data.CompilerAgentBlock
import com.bedalton.creatures.agents.pray.compiler.data.Tag
import com.bedalton.creatures.agents.pray.compiler.pray.PrayValidationError
import com.bedalton.creatures.agents.util.internal.SPRITE_EXTENSIONS
import kotlinx.coroutines.CoroutineScope


private val agentAnimationStringRegex = "^([0-9]+\\s+)*[0-9]+$".toRegex()
private val agentAnimationInvalidChars = "([^0-9 ])".toRegex()

internal suspend fun validatePrayAgentBlock(
    coroutineScope: CoroutineScope,
    fullFilePath: String,
    fileExists: suspend (relativePath: String) -> Boolean,
    agentBlock: CompilerAgentBlock,
    errors: MutableList<PrayValidationError>,
) {
    val tags = agentBlock.tags
    val addError = addErrorLambda(fullFilePath, errors, agentBlock)
    // Validate that animation string is in expected format
    validateAnimationString(addError, tags)
    // Validate agent lists "Agent Type" 0
    validateHasAgentType0(addError, tags)
    // Ensure that first Image is numeric and non-negative
    validateSpriteFirstImage(addError, tags)
    // Ensure gallery does not have a file extension
    validateTagWithFileWithoutExtension(addError, "Agent Animation Gallery", SPRITE_EXTENSIONS, tags)
    // Ensure animation file does have sprite extension
    validateTagWithFileExtension(addError, "Agent Animation File", SPRITE_EXTENSIONS, tags)
    // Ensure link tags are valid
    validateLinkTags(coroutineScope, fileExists, addError, tags)
}


/**
 * Validates animation string for correctness
 * should be "0 1 2 3" | "0"
 * Invalid "[0 1 2 3]" | 0
 */
private fun validateAnimationString(
    addError: AddError,
    tags: Array<Tag<*>>,
) {

    // Find animation strings in tags
    val animationStringTags = tags.filter { it.tag.equals("Agent Animation String", true) }
        .nullIfEmpty()
        ?: return

    // Loop through animation tags and seek out int values
    for (tag in animationStringTags) {
        // Tag values should be strings not ints, even if the value is a single number
        if (tag is Tag.IntTag) {
            addError(tag.valueRange, "\"Agent Animation String\" tag should be string")
        }
    }

    // Validate all animation strings for correctness
    for (tag in animationStringTags.filterIsInstance<Tag.StringTag>()) {
        val animation = tag.value.trim().nullIfEmpty()
        // If animation string is empty, generate error and continue to next tag
        if (animation == null) {
            addError(
                tag.valueRange,
                "Animation string should not be blank"
            )
            continue
        }

        // Find if animation is valid
        if (agentAnimationStringRegex.matches(animation))
            continue

        // Animation is not valid, com.bedalton.creatures.pray.create error message
        val error = if (animation.startsWith('[') || animation.endsWith(']')) {
            // Animation uses illegal format of "[0 1 2 3]". There should be no square brackets
            "Agent animation string should not have opening and closing square brackets '[' ']'"
        } else {
            // Animation string is invalid, due to invalid chars that are not '[' or '\]'
            val invalidChars = agentAnimationInvalidChars.matchEntire(tag.value.trim())
                ?.groupValues
                ?.drop(1)
                ?.filterNot { it.isBlank() }
                .orEmpty()
                .toSet()
            // Determine error message based on number of invalid chars
            when (invalidChars.size) {
                // Not sure why the string did not match, throw generic message
                0 -> "Agent animation string format invalid should be frame numbers delimited by a space"
                // Only one invalid char was found
                1 -> "Agent animation should consist of numbers and spaces only. Found illegal char '${invalidChars.first()}'"
                // Multiple unique invalid chars found
                else -> "Agent animation should consist of numbers and spaces only. Found illegal char [${
                    invalidChars.joinToString(
                        ","
                    )
                }]"
            }
        }
        // Add an error using that generated error message
        addError(
            tag.valueRange,
            error
        )
    }
}


/**
 * Validate sprite first image is numeric
 */
private fun validateSpriteFirstImage(
    addError: AddError,
    tags: Array<Tag<*>>,
) {
    for (tag in tags.filter { it is Tag.StringTag && it.value like "Agent Sprite First Image" }) {
        if (tag is Tag.IntTag) {
            if (tag.value < 0) {
                addError(
                    tag.valueRange,
                    "\"Agent Sprite First Image\" value should not be negative"
                )
            }
        } else {
            addError(
                tag.valueRange,
                "\"Agent Sprite First Image\" value should be an integer value"
            )
        }
    }
}