package com.bedalton.creatures.agents.pray.compiler.caos2pray

import com.bedalton.common.structs.HasRange
import com.bedalton.creatures.agents.pray.compiler.data.TextValue

/**
 * Represents a CAOS2Command in a CAOS2Pray file
 *
 * @property command command used
 * @property lineNumber
 * @property startIndex
 * @property endIndex
 * @property values list of values for this command as parse tree values
 * @constructor Create empty Command value
 */
internal data class CommandValue(
    val command: Int,
    override val lineNumber: Int,
    override val startIndex: Int,
    override val endIndex: Int,
    val values: List<TextValue>,
) : HasRange {

    // Gets the command text used in CAOS2Pray comments
    @Suppress("MemberVisibilityCanBePrivate")
    val commandString by lazy {
        when (command) {
            Caos2PrayCommands.ATTACH -> "Attach"
            Caos2PrayCommands.DEPENDS -> "Depends"
            Caos2PrayCommands.INLINE -> "Inline"
            Caos2PrayCommands.LINK -> "Link"
            Caos2PrayCommands.RSCR -> "RSCR"
            else -> "UNKNOWN"
        }
    }

    override fun toString(): String {
        return "$commandString ${values.joinToString { "\"${it.text}\"" }}"
    }
}