@file:Suppress("unused")

package com.creaturesforge.application.ui.html

import org.w3c.dom.*
import org.w3c.dom.events.EventListener

internal fun <T : Node> NodeList.toList(): List<T> {
    return (0 until length).mapNotNull { i ->
        this[i]?.unsafeCast<T>()
    }
}

internal inline fun <N : Node, R> NodeList.map(work: (N) -> R): List<R> {
    val out = mutableListOf<R>()
    for (i in 0 until length) {
        val node = get(i)
            ?: continue
        out.add(work(node.unsafeCast<N>()))
    }
    return out
}

internal inline fun <R> NodeList.mapNotCast(work: (Node) -> R): List<R> {
    val out = mutableListOf<R>()
    for (i in 0 until length) {
        val node = get(i)
            ?: continue
        out.add(work(node))
    }
    return out
}

internal inline fun <R: Element> NodeList.forEach(work: (R) -> Unit) {
    for (i in 0 until length) {
        val node = get(i)?.unsafeCast<R?>()
            ?: continue
        work(node)
    }
}


internal fun <N : Node> NodeList.iteratorCasted(): Iterator<N> {
    var i = 0
    val end = length
    return object : Iterator<N> {
        override operator fun hasNext(): Boolean {
            return i < end
        }

        override operator fun next(): N {
            return get(i++).unsafeCast<N>()
        }
    }
}

internal operator fun NodeList.iterator(): Iterator<Node?> {
    var i = 0
    val end = length
    return object : Iterator<Node?> {
        override operator fun hasNext(): Boolean {
            return i < end
        }

        override operator fun next(): Node? {
            return get(i++)
        }
    }
}

internal fun NodeList.addEventListener(type: String, listener: EventListener) {
    for (i in 0 until length) {
        val node = get(i)
            ?.unsafeCast<HTMLElement>()
            ?: continue
        node.addEventListener(type, listener)
    }
}

internal fun NodeList.addEventListener(type: String, listener: EventListener, options: EventListenerOptions?) {
    for (i in 0 until length) {
        val node = get(i)
            ?: continue
        node.addEventListener(type, listener, options)
    }
}

internal fun NodeList.addEventListener(type: String, listener: EventListener, options: Boolean?) {
    for (i in 0 until length) {
        val node = get(i)
            ?: continue
        node.addEventListener(type, listener, options)
    }
}

internal inline fun NodeList.applyEach(init: HTMLElement.() -> Unit) {
    for (i in 0 until length) {
        val node = get(i)
            ?.unsafeCast<HTMLElement>()
            ?: continue
        node.init()
    }
}