package com.bedalton.creatures.caos.libs

import kotlin.js.JsExport
import kotlin.js.JsName


@JsExport
@JsName("getCommandsForLib")
fun getCommandsForLib(variant:String) : Commands {
    val lib = CaosLibs[variant]
    return Commands(
        commands = lib.commands.map { it.toVariantCommand(variant) }.toTypedArray(),
        lvalues = lib.lvalues.map { it.toVariantCommand(variant) }.toTypedArray(),
        rvalues = lib.rvalues.map { it.toVariantCommand(variant) }.toTypedArray()
    )
}

