@file:Suppress("unused")

package com.creaturesforge.application.ui.html

import com.bedalton.common.util.nullIfEmpty
import org.w3c.dom.Element


internal fun Element.getBoolean(name: String): Boolean? {
    return getAttribute(name).nullIfEmpty()?.toBooleanStrict()
}

internal fun Element.getBooleanSafe(name: String): Boolean? {
    return getAttribute(name).nullIfEmpty()?.toBooleanStrictOrNull()
}

internal fun Element.getBoolean(name: String, value: Boolean): Boolean {
    return getAttribute(name).nullIfEmpty()?.toBooleanStrict() ?: value
}

internal fun Element.getBooleanSafe(name: String, value: Boolean): Boolean {
    return getAttribute(name).nullIfEmpty()?.toBooleanStrictOrNull() ?: value
}

internal fun Element.getInt(name: String): Int? {
    return getAttribute(name).nullIfEmpty()?.toInt()
}

internal fun Element.getIntSafe(name: String): Int? {
    return getAttribute(name).nullIfEmpty()?.toIntOrNull()
}

internal fun Element.getInt(name: String, default: Int): Int {
    return getAttribute(name).nullIfEmpty()?.toInt() ?: default
}

internal fun Element.getIntSafe(name: String, default: Int): Int {
    return getAttribute(name).nullIfEmpty()?.toIntOrNull() ?: default
}

