internal fun Element.getLong(name: String, default: Long): Long {
    return getAttribute(name).nullIfEmpty()?.toLong() ?: default
}

internal fun Element.getLongSafe(name: String, default: Long?): Long? {
    return getAttribute(name).nullIfEmpty()?.toLongOrNull() ?: default
}


