package com.creaturesforge.application.interop

import JsObject
import com.bedalton.common.util.formatted
import com.bedalton.common.util.isNotNullOrBlank
import com.bedalton.log.Log
import com.creaturesforge.application.state.*
import com.bedalton.common.exceptions.rethrowCancellationException
import com.bedalton.log.iIf
import com.creaturesforge.application.util.asThrowable
import kotlinx.browser.window
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Job
import kotlinx.coroutines.launch
import org.w3c.dom.ErrorEvent
import tauri.UnlistenFn
import tauri.event.Event
import kotlin.js.Promise


internal object TauriEvents {

    private const val OPEN_EGG_EVENT = "open_egg"
    private const val OPEN_PROJECT_EVENT = "open_project"
    private const val RESET_VIEW_EVENT = "reset_view"

    private const val CLEAR_SAVED_PROJECT_SETTINGS_FOR_PROJECT = "clear_saved_project_settings_for_project"
    private const val CLEAR_SAVED_SETTINGS_FOR_ALL_PROJECTS = "clear_saved_settings_for_all_projects"
    private const val TOGGLE_DISABLE_PROJECT_SETTING_RELOAD = "toggle_disable_project_settings_reload"

    private const val CLEAR_PREVIOUS_GENOMES_LIST_FROM_PROJECT = "clear_previous_genomes_list_from_project"
    private const val CLEAR_ALL_PREVIOUS_GENOMES_FROM_ALL_TIME = "clear_all_previous_genomes_from_all_time"
    private const val TOGGLE_DISABLE_PREVIOUS_GENOME_LIST = "toggle_disable_genome_list_reload"

    private const val TOGGLE_EGG_MODE_EVENT = "toggle_egg_mode"
    private const val UPDATE_VIEW_MODE_EVENT = "update_view_mode_in_tauri"

    private const val TAURI_EVENT_WINDOW_FOCUS = "tauri://focus"

    /**
     * Adds listeners for events emitted by TAURI Rust backend
     */
    internal fun initTauriListeners() {

        window.addEventListener("unhandledrejection", ::logError)

        window.onerror = { message, file, line, col, error ->
            Log.e("Error[$file@$line:$col] -> $message")
            logError(error)
        }

        window.addEventListener("error", { e ->
            logError(e.asDynamic()?.error ?: e)
        })

        listen<OpenEggEvent>(OPEN_EGG_EVENT, false) { e ->
            val data = e.payload
            ForgeStore.dispatch(OpenEggAction(data.path))
        }


        listen<OpenProjectEvent>(OPEN_PROJECT_EVENT, false) { e ->
            val data = e.payload
            ForgeStore.dispatch(SetProjectRootAction(data.path))
        }

        listenAsync<Unit>(TAURI_EVENT_WINDOW_FOCUS, false) {
            console.log("Focused, ${it.windowLabel}")
            onTauriWindowFocus()
        }

        listenAsync<Unit>(UPDATE_VIEW_MODE_EVENT) {
            updateEggModeInTauri()
        }

        listen<Unit>(RESET_VIEW_EVENT) {
            ForgeStore.dispatch(ResetStateAction)
        }

        listen<Unit>(RESET_VIEW_EVENT) {
            ForgeStore.dispatch(ResetStateAction)
        }

        listenAsync<Boolean>(TOGGLE_EGG_MODE_EVENT) {
            toggleEggMode()
        }

        addSavedProjectSettingsInteropListeners()

        addPreviousGenomeListInteropListeners()

    }


    private fun addSavedProjectSettingsInteropListeners() {

        listen<Boolean>(CLEAR_SAVED_PROJECT_SETTINGS_FOR_PROJECT, global = false) {
            ForgeStore.dispatch(ResetProjectAndClearSavedSettings)
        }

        listen<Boolean>(CLEAR_SAVED_SETTINGS_FOR_ALL_PROJECTS, global = true) { e ->
            ForgeStore.dispatch(ClearSavedSettingsForAllProjects(e.isLocal()))
        }

        listen<Unit>(TOGGLE_DISABLE_PROJECT_SETTING_RELOAD, global = true) { e ->
            ForgeStore.dispatch(ToggleDisableProjectSettingsReload(e.isLocal()))
        }

    }

    private fun addPreviousGenomeListInteropListeners() {

        listen<Boolean>(CLEAR_PREVIOUS_GENOMES_LIST_FROM_PROJECT, global = false) {
            ForgeStore.dispatch(ClearPreviousGenomesListFromProject)
        }

        listen<Unit>(CLEAR_ALL_PREVIOUS_GENOMES_FROM_ALL_TIME, global = true) { e ->
            ForgeStore.dispatch(ClearAllPreviousGenomesFromAllTime(e.isLocal()))
        }

        listen<Unit>(TOGGLE_DISABLE_PREVIOUS_GENOME_LIST, global = true) { e ->
            ForgeStore.dispatch(ToggleDisablePreviousGenomesLists(e.isLocal()))
        }
    }

    private suspend fun onTauriWindowFocus() {
        ForgeConfig.forceReloadSync()
        pushStateToWindow()
    }

    /**
     * Listen to events specific to this window
     * @param eventName Event name
     * @param global whether to respond to all events regardless of window target
     * @param onEvent event listener
     */
    private fun <T> listen(eventName: String, global: Boolean = false, onEvent: (e: Event<T>) -> Unit): Promise<UnlistenFn> {
        return tauri.event.listen(eventName) listener@{ tauriEvent ->
            if (!global && tauriEvent.windowLabel != windowId) {
                Log.iIf(com.bedalton.log.LOG_VERBOSE) { "Window label not matching; Expected: $windowId; Found: ${tauriEvent.windowLabel}" }
                return@listener
            }
            try {
                onEvent(tauriEvent)
                Log.iIf(com.bedalton.log.LOG_VERBOSE) { "Completed listener[$eventName]; Global: $global; Async: false" }
            } catch (eRaw: dynamic) {
                val e = asThrowable(eRaw)
                Log.e("Failure in listener[$eventName]; Global: $global; Async: false; ${e.formatted(true)}")
            }
        }
    }

    /**
     * Listen to events specific to this window with suspending lambda
     * @param eventName Event name
     * @param global whether to respond to all events regardless of window target
     * @param on event listener
     */
    private fun <T> listenAsync(
        eventName: String,
        global: Boolean = false,
        on: suspend CoroutineScope.(e: Event<T>) -> Unit,
    ): Promise<UnlistenFn> {


        return tauri.event.listen(eventName) { event ->

            if (!global && event.windowLabel != windowId) {
                Log.iIf(com.bedalton.log.LOG_VERBOSE) {
                    "Window label not matching; Expected: $windowId; Found: ${event.windowLabel}"
                }
                return@listen
            }

            try {
                val coroutineScope = CoroutineScope(Job())
                coroutineScope.launch {
                    try {
                        coroutineScope.on(event)
                        Log.iIf(com.bedalton.log.LOG_VERBOSE) { "Completed listener[$eventName]; Global: $global; Async: true" }
                    } catch (e: Exception) {
                        Log.e("Failure in listener[$eventName]; Global: $global; Async: true; InCoroutine: true; ${e.formatted(true)}")
                    }
                }
            } catch (eRaw: dynamic) {
                val exception = asThrowable(eRaw)
                exception.rethrowCancellationException()
                Log.e { "Failure in listener[$eventName]; Global: $global; Async: true; InCoroutine: false; ${exception.formatted(true)}" }
            }
        }
    }

    private fun logError(e: dynamic) {
        @Suppress("USELESS_CAST")
        val message: String = when {
            e is String -> e as String
            e is Throwable -> {
                val exception = e.unsafeCast<Throwable>()
                e.message + exception.formatted(true)
            }
            e.error != null -> {
                val error = (e as ErrorEvent)
                var message = error.filename + "@${e.lineno}:${e.colno}->${e.message}"
                val stack = (e.error.asDynamic()?.stack ?: "") as String
                if (stack.isNotNullOrBlank()) {
                    message += "\n$stack"
                }
                message
            }

            e.message != null -> e.message as String
            else -> {
                JSON.stringify(e, JsObject.getOwnPropertyNames(e)) + "\n" + (Exception().stackTraceToString())
            }
        }
        Log.e(message)
    }

    private fun <T> Event<T>.isLocal(): Boolean {
        return windowLabel == windowId
    }

}


private external interface OpenEggEvent {
    @JsName("path")
    val path: String
}

private external interface OpenProjectEvent {
    @JsName("path")
    val path: String
}
