package com.creaturesforge.application.util

import com.bedalton.common.util.PathUtil

private val USER_PATH_REGEX =
    "^(?:.:\\|.:/|/[^/]+?)?users[\\\\/]([^\\\\/]+)[\\\\/]".toRegex(RegexOption.IGNORE_CASE)

private const val mMaxLabelLength = 34;

internal fun findShortestUniquePaths(paths: List<String>, maxLabelLength: Int = mMaxLabelLength): List<String> {
    // Get and cache components'


    val pathsWithoutUserPath = paths.map {
        it.replace(USER_PATH_REGEX, "~/")
    }

    if (pathsWithoutUserPath.all { it.length < maxLabelLength }) {
        return pathsWithoutUserPath
    }

    val componentsForPaths = pathsWithoutUserPath.map { path ->
        componentsReversed(path.lowercase())
    }

    if (componentsForPaths.all { it.size == 1}) {
        return pathsWithoutUserPath
    }

    val out = paths.map { PathUtil.getFileNameWithoutExtension(it) ?:  it.split("[/\\\\]".toRegex()).last() }
        .toMutableList()
    val done = mutableListOf<Int>()
    for ((index, pathComponents) in componentsForPaths.withIndex()) {
        val otherComponentIndices = componentsForPaths.indices.filterNot { it == index && it !in done }
        var sharedStart = otherComponentIndices
        done += index
        for (componentIndex in pathComponents.indices) {
            val pathSoFar = pathComponents.subList(0, componentIndex).joinToString("/")
            val indices = otherComponentIndices.filter { otherIndex ->
                componentsForPaths[otherIndex].size > componentIndex &&
                        componentsForPaths[otherIndex].subList(0, componentIndex + 1)
                            .joinToString("/")
                            .equals(pathSoFar, true)
            }

            if (indices.isNotEmpty()) {
                sharedStart = indices
                continue
            }

            sharedStart.forEach { otherIndex ->
                val otherComponents = componentsForPaths[otherIndex]
                out[otherIndex] = if (otherComponents.size <= componentIndex) {
                    otherComponents.asCopyReversed().joinToString("/")
                } else {
                    otherComponents.asCopyReversed().subList(0, componentIndex + 1).joinToString("/")
                }
            }

            out[index] = pathComponents.asCopyReversed().subList(0, componentIndex + 1).joinToString("/")

            done += sharedStart
            break
        }
    }
    return out
}

private fun componentsReversed(path: String): List<String> {
    return path.split("[\\\\/]+".toRegex())
        .filter { it.isNotBlank() }
        .reversed()
}