package com.creaturesforge.application.interop

import com.creaturesforge.application.state.ForgeStore
import com.creaturesforge.application.state.OpenEggAction
import com.creaturesforge.application.state.SetProjectRootAction
import kotlinx.browser.window


internal fun handleStartupRequests() {

    val requests: Array<dynamic> = (window.asDynamic().startupRequests as? Array<dynamic>?)
        .orEmpty()

    for (startupRequest in requests) {
        val request = StartupRequest.from(startupRequest)
        handleStartupRequest(request)
    }
}


private fun handleStartupRequest(request: StartupRequest) {
    when (request) {
        is OpenEggRequest -> ForgeStore.dispatch(OpenEggAction(request.path))
        is SetProjectRootRequest -> ForgeStore.dispatch(SetProjectRootAction(request.path))
    }
}

private sealed class StartupRequest {

    companion object {
        fun from(request: dynamic): StartupRequest {
            if (request.action == null) {
                throw IllegalArgumentException("Request action invalid. Requires action; ${stringify(request)}}")
            }
            return when (val action = request.action as String) {
                OpenEggRequest.ACTION -> OpenEggRequest.fromDynamic(request)
                SetProjectRootRequest.ACTION -> SetProjectRootRequest.fromDynamic(request)
                else -> throw NotImplementedError("Action <$action> is not handled by Kotlin; Data: ${stringify(request)}")
            }
        }
    }
}

private data class OpenEggRequest(
    val path: String,
): StartupRequest() {

    companion object {
        const val ACTION = "open_egg"
        fun fromDynamic(request: dynamic) = OpenEggRequest(request.path as String)
    }
}


private data class SetProjectRootRequest(
    val path: String,
): StartupRequest() {

    companion object {
        const val ACTION = "set_project_root"
        fun fromDynamic(request: dynamic) = SetProjectRootRequest(request.path as String)
    }
}


private fun stringify(request: dynamic, pretty: Boolean = false): String {
    return if (pretty) {
        JSON.stringify(request, null, 2)
    } else {
        JSON.stringify(request)
    }
}