package com.creaturesforge.application.state

import com.bedalton.common.util.PathUtil
import com.bedalton.common.util.nullIfEmpty
import com.creaturesforge.application.util.isAutoNameNullOrBlank
import kotlinx.serialization.Serializable


private var maxIndex = 0

@Serializable
internal data class EggData(
    val id: Int = maxIndex,
    val eggName: String? = null,
    val baseGenomeFile: GenomeFile? = null,
    val motherGenomeFile: GenomeFile? = null,
    val fatherGenomeFile: GenomeFile? = null,
) {

    val displayName by lazy {
        eggName?.let {
            return@lazy it
        }
        baseGenomeFile
            ?.filename
            ?.nullIfEmpty()
            ?.let {
                return@lazy inflect(it)
            }
        baseGenomeFile
            ?.filepath
            ?.let {
                inflect(PathUtil.getLastPathComponent(it) ?: it.split('/').last())
            }
            ?.let {
                return@lazy it
            }
        "Egg $id"
    }

    init {
        if (id >= maxIndex) {
            maxIndex = id + 1
        }
    }

    companion object {
        fun resetIdIndex(eggs: List<EggData>) {
            maxIndex = eggs.maxOfOrNull { it.id + 1 } ?: 0
        }
    }

}

private fun inflect(fileName: String): String {
    return fileName.replace("[\\-._]".toRegex(), " ")
        .replace("(norn|gre(n|ndel)?|ettn|ettin|geat)\\s+".toRegex(RegexOption.IGNORE_CASE), "")
        .replace("([A-Z]+)".toRegex(), " $1")
        .split(" ")
        .joinToString("")
}