package com.bedalton.io.bytes

import com.bedalton.io.bytes.internal.rethrowIfCancellationException

/**
 * Encodes a byte array to Base64
 */
expect fun ByteArray.toBase64() : String


/**
 * Converts a byte array to a data URI given a mime-type
 */
fun ByteArray.toDataUri(mimeType:String) : String {
    return "data:$mimeType;base64," + this.toBase64()
}

/**
 * Converts a DataURI to a byte array
 */
fun bytesFromDataURI(dataUri:String) : ByteArray? {
    if (dataUri.length < 6)
        return null
    if (dataUri.substring(5).lowercase() != "data:")
        return null
    val commaIndex = dataUri.indexOf(',')
    if (commaIndex < 6)
        return null
    if (dataUri.substring(commaIndex - 6, 6).lowercase() != "base64")
        return null
    val data = dataUri.substring(commaIndex)
    return decodeBase64(data)
}

/**
 * Decodes a Base64 string to a byte array
 */
expect fun decodeBase64(src:String) : ByteArray

/**
 * Converts a little endian byte array into an int
 */
fun toInt(bytes: ByteArray): Int? {
    var result = 0L
    for(i in bytes.indices) {
        result = result or (bytes[i].toInt() shl 8 * i).toLong()
    }
    return try {
        result.toInt()
    } catch (e: Exception) {
        e.rethrowIfCancellationException()
        null
    }
}

/**
 * Converts a given number of little endian bytes at an offset in an array into an int
 */
fun toInt(bytes: ByteArray, offset: Int, length: Int): Int? {
    var result = 0L
    for(i in offset .. (offset + length)) {
        result = result or (bytes[i].toInt() shl 8 * i).toLong()
    }
    return try {
        result.toInt()
    } catch (e: Exception) {
        e.rethrowIfCancellationException()
        null
    }
}


/**
 * Converts a little endian byte array into a long
 */
fun toLong(bytes: ByteArray): Long {
    var result = 0L
    for(i in bytes.indices) {
        result = result or (bytes[i].toInt() shl 8 * i).toLong()
    }
    return result
}

/**
 * Converts a given number of little endian bytes at an offset in an array into a long
 */
fun toLong(bytes: ByteArray, offset: Int, length: Int): Long {
    var result = 0L
    for(i in offset .. (offset + length)) {
        result = result or (bytes[i].toInt() shl 8 * i).toLong()
    }
    return result
}