package com.creaturesforge.application.state


internal object CompilerListeners: SingleArgumentListener<CompileEggAction>()

internal sealed class SingleArgumentListener<T> {
    private val mCompilerListeners = mutableSetOf<(T) -> Unit>()
    private var lastValue: T? = null

    fun addListener(listener: (T) -> Unit): () -> Unit {
        mCompilerListeners.add(listener)
        lastValue?.let {
            listener(it)
        }
        return {
            removeListener(listener)
        }
    }

    fun removeListener(listener: (T) -> Unit) {
        mCompilerListeners.remove(listener)
    }

    fun notify(value: T) {
        mCompilerListeners.forEach { it(value) }
    }

}