@file:Suppress("unused")

package com.bedalton.io.bytes


/**
 * Checks if the given int sequence occurs at the given offset of the current position
 */
fun ByteStreamReader.isNext(sequence: CharSequence): Boolean {
    val queryLength = sequence.length
    if (position() + queryLength >= size) {
        return false
    }
    repeat(queryLength) { i ->
        if (peakUInt8(i) != sequence[i].code) {
            return false
        }
    }
    return true
}

