/**
 * Checks if the given int sequence occurs at the given offset of the current position
 */
fun ByteStreamReader.isNextTokenInt(tokenInt: Int): Boolean {
    return peakToken(0) == tokenInt
}

/**
 * Checks if the given int sequence occurs at the given offset of the current position
 */
fun ByteStreamReader.isNextTokenInt(offset: Int, vararg tokenInts: Int): Boolean {
    return peakToken(offset)?.let { it in tokenInts }
        ?: return false
}