package com.bedalton.creatures.sprite.util

import korlibs.image.bitmap.Bitmap32
import korlibs.image.color.RGBA
import kotlin.math.ceil


/**
 * Scale an image, possibly smoothly
 */
fun Bitmap32.scaledBy(
    scale: Double,
    smooth: Boolean = false,
    blackIsTransparent: Boolean,
    keepBlack: Boolean = !blackIsTransparent,
    shrinkBlackBorder: Boolean = true
): Bitmap32 {

    val width = ceil(scale * width).toInt()
    val height = ceil(scale * height).toInt()
    return resizedTo(
        width = width,
        height = height,
        smooth = smooth,
        blackIsTransparent = blackIsTransparent,
        keepBlack = keepBlack,
        shrinkBlackBorder = shrinkBlackBorder
    )
}

fun Bitmap32.resizedTo(
    width: Int,
    height: Int,
    smooth: Boolean = false,
    blackIsTransparent: Boolean,
    keepBlack: Boolean = !blackIsTransparent,
    shrinkBlackBorder: Boolean = true
): Bitmap32 {

    // Ensure scaled image has size
    if (width == 0 || height == 0) {
        throw Exception("Image has zero length side after resize. Scaled: ($width, $height); Original: (${this.width}, ${this.height})")
    }

    // Shrink black before scaling
    val theImage = if (shrinkBlackBorder) {
        shrinkBlackBorder(blackIsTransparent)
    } else {
        this
    }

    // Combine a smooth scaled image on top of a nearest neighbor scaled image
    // this should prevent any soft pixels, or black pixels that are kept
    var base = theImage.scaled(width, height, false)

    // Get transparent black color
    val transparentBlack = if (keepBlack) opaqueBlack else transparentBlack

    // Get opaque mask of pure black and pure white (white is transparent)
    val maskScaled = mask(theImage, blackIsTransparent)
        .scaled(width, height, false)

    // If not smooth scaling, can return image as is
    if (smooth) {
        // Add a sort of fuzziness to the image before applying the mask
        base = base
            .expandBorder()

        // Apply smooth scaled image over base
        theImage.scaled(width, height, true)
            .copy(0, 0, base, 0, 0, width, height)
    }

    return base.applyMask(maskScaled, transparentBlack)
}


/**
 * Expand area around an image, averaging border color pixels
 * Used to prevent black edges when scaling image down
 */
private fun Bitmap32.expandBorder(): Bitmap32 {
    val out = clone()
    each { x, y ->
        val pixel = get(x, y)
        if (pixel.a <= trimBlackAlphaCutoff) {
            val surrounding = getSurrounding(x, y).opaqueOnly()
            if (surrounding.isNotEmpty()) {
                if (surrounding.size == 1) {
                    out[x, y] = surrounding[0]
                } else {
                    out[x, y] = surrounding.average()
                }
            }
        }
    }
    return out
}


/**
 * Get a mask of pure white and pure black, where white is opaque and black is transparent
 */
private fun mask(image: Bitmap32, isBlackTransparent: Boolean): Bitmap32 {
    val getMaskColor = getMaskColorFunction(isBlackTransparent)
    return image.transformCopy(getMaskColor)
}


/**
 * Get lambda for converting a pixel with alpha to black=transparent or white=opaque
 */
private fun getMaskColorFunction(isBlackTransparent: Boolean): (x: Int, y: Int, color: RGBA) -> RGBA {
    // Mask color function
    return if (isBlackTransparent) {
        { _: Int, _: Int, pixel: RGBA ->
            // Pure black is meant to be transparent
            if (pixel.a >= trimBlackAlphaCutoff && (pixel.r != 0 || pixel.g != 0 || pixel.b != 0)) {
                white
            } else {
                black
            }
        }
    } else {
        // Black is significant, so only mask on alpha
        { _: Int, _: Int, pixel: RGBA ->
            if (pixel.a >= trimBlackAlphaCutoff) {
                white
            } else {
                black
            }
        }
    }
}

/**
 * Applies transparency based on a b&w masking image where white is opaque and black is transparent
 */
private fun Bitmap32.applyMask(mask: Bitmap32, isBlackTransparent: Boolean): Bitmap32 {
    val transparentColor: RGBA = if (isBlackTransparent) {
        ColorPalette.TRANSPARENT_BLACK
    } else {
        ColorPalette.OPAQUE_BLACK
    }
    return applyMask(mask, transparentColor)
}

/**
 * Applies transparency based on a b&w masking image where white is opaque and black is transparent
 */
private fun Bitmap32.applyMask(mask: Bitmap32, transparentColor: RGBA): Bitmap32 {
    if (width != mask.width || height != mask.height) {
        throw Exception("Cannot apply mask to differently size images. Image: ($width, $height); Mask: (${mask.width}, ${mask.height})")
    }

    return transformCopy { x, y, color ->
        if (mask[x, y] != white) {
            transparentColor
        } else {
            color
        }
    }
}


private fun Bitmap32.getSurrounding(x: Int, y: Int): List<RGBA> {
    return listOfNotNull(
        // Above
        getSafe(x - 1, y - 1),
        getSafe(x, y - 1),
        getSafe(x + 1, y - 1),

        // Sides
        getSafe(x + 1, y),
        getSafe(x - 1, y),

        // Bottom
        getSafe(x - 1, y + 1),
        getSafe(x, y + 1),
        getSafe(x + 1, y + 1)
    )
}

private fun List<RGBA>.opaqueOnly(): List<RGBA> {
    return mapNotNull { it.nullIfTransparent() }
}

private fun Bitmap32.average(x: Int, y: Int): RGBA {
    val pixels = getSurrounding(x, y).opaqueOnly()
    return pixels.average()
}


private fun RGBA.nullIfTransparent(): RGBA? {
    return if (a < trimBlackAlphaCutoff) {
        null
    } else {
        this
    }
}