package com.bedalton.creatures.agents.pray.parser

import com.bedalton.creatures.agents.pray.compiler.REMOVER_SCRIPT_REGEX
import com.bedalton.creatures.agents.pray.compiler.SCRIPT_TAG_REGEX
import com.bedalton.creatures.agents.pray.compiler.data.*
import com.bedalton.common.util.*


internal fun constructPrayFile(
    fileName: String,
    namespace: String,
    blocks: List<CompilerPrayBlock>,
    outScripts: NonDuplicateScriptHolder,
    inlineScripts: Boolean,
): Pair<String, ByteArray> {
    val builder = StringBuilder()
    builder.append("\"en-GB\"\n")
    blocks.filterIsInstance<CompilerBlockWithTags>().forEach { block ->
        writeTagBlockAsPray(namespace, block, builder, outScripts, inlineScripts)
    }

    blocks.filter { it !is CompilerBlockWithTags }.map {
        val namespacedFileName = namespaceValue(
            namespace,
            it.blockTag,
            it.blockName,
            true
        )
        builder.append("inline ${it.blockTag} \"${it.blockName}\" \"$namespacedFileName\"\n")
    }
    val outName =
        namespace.nullIfEmpty()?.let { "$namespace${PathUtil.getFileNameWithoutExtension(fileName)}" } ?: fileName
    return "$outName.pray.txt" to builder.toString().encodeToByteArray()
}

private fun writeTagBlockAsPray(
    namespace: String,
    block: CompilerBlockWithTags,
    builder: StringBuilder,
    outScripts: NonDuplicateScriptHolder,
    inlineScripts: Boolean,
) {
    builder.append("\ngroup ${block.blockTag} \"${block.blockName}\"\n")

    val blockName = block.blockName.text
    block.tags
        .sortedBy { it.tag }.forEach each@{
            if ((it is Tag.StringTag || it is Tag.LinkTag) && SCRIPT_TAG_REGEX.matches(it.tag)) {
                return@each
            }
            builder.append("\"${it.tag}\"")
            if (it is Tag.StringTag || it is Tag.LinkTag) {

                val isRemovalScript = REMOVER_SCRIPT_REGEX.matches(it.tag)
                if (it is Tag.LinkTag || (isRemovalScript && !inlineScripts)) {
                    builder.append(" @ ")
                } else {
                    builder.append(' ')
                }
                builder.append(' ')
                if (it is Tag.LinkTag) {
                    builder.quote(it.value.escape())
                } else if (it is Tag.StringTag && isRemovalScript) {
                    if (inlineScripts) {
                        builder.appendScript(it.value)
                    } else {
                        val name = outScripts.add(namespace, blockName, it.value, true)
                        builder.quote(name)
                    }
                } else if (it is Tag.StringTag) {
                    builder.quote(superEscape(it.value))
                } else {
                    throw AgentFileDecompilerException("Failed to write tag of type ${it::className} as String tag")
                }
            } else if (it is Tag.IntTag) {
                builder.append(' ').append(it.value)
            } else {
                throw AgentFileDecompilerException(
                    "Invalid TAG type encountered in reconstruct pray file. " +
                            "Tag: ${it::className}; Tag: ${it.tag}; Value: ${it.value}"
                )
            }
            builder.appendLine()
        }

    if (inlineScripts) {
        block.scripts()
            .sortedBy { it.first }
            .forEach {(i, text) ->
                builder
                    .quote("Script $i")
                    .append(' ')
                    .appendScript(text)
                    .appendLine()
            }
    } else {
        block.scripts()
            .sortedBy { it.first }
            .forEach { (i, script) ->
                val name = outScripts.add(namespace, blockName, script, false)
                builder
                    .quote("Script $i")
                    .append(" @ ")
                    .quote(name)
                    .appendLine()
            }
    }
    builder.append("\n\n")
}


private fun StringBuilder.appendScript(text: String): StringBuilder {
    val script = text
        .replace("\\", "\\\\")
        .replace("\r\n", "\\r\\n")
        .replace("\r", "\\r")
        .replace("\n", "\\n")
        .replace("\"", "\\\"")
    return quote(script)
}