package com.bedalton.creatures.agents.pray.compiler

/**
 * Compiler options which include an optional overriding name.
 * Name is meant to override one set in a CAOS2Pray or CAOS2Cob file
 */
expect interface PrayCompileOptionsWithRecursiveJoin: PrayCompileOptions {
    /**
     * Name to use instead of the one supplied in the pray file
     */
    val recursiveJoins: Boolean?
}

internal expect val PrayCompileOptions.recursiveJoinsOrNull: Boolean?

internal val PrayCompileOptions.recursiveJoinsNotNull: Boolean get() {
    return recursiveJoinsOrNull ?: CompilerOptionsDefault.DEFAULT_RECURSIVE_JOINS
}