/**
 * Helper class to handle render offset for breed parts
 */
object RenderOffsetUtil {

    /**
     * Calculate the rendering offsets for each part in a given pose
     */
    @JvmStatic
    suspend fun <ImageT> getRenderOffsets(
        pose: Pose,
        parts: Map<Char, ParsedBodyPartRenderData<ImageT>>,
        nonIntersectingLimbs: Boolean,
        trueSize: ((ImageT) -> Size)? = null
    ): RenderOffsets<ImageT>? {
        return getRenderOffsets(
            coroutineContext = coroutineContext,
            pose = pose,
            parts = parts,
            nonIntersectingLimbs = nonIntersectingLimbs,
            trueSize = trueSize
        )
    }

    /**
     * Calculate the rendering offsets for each part in a given pose
     */
    @JvmStatic
    suspend fun <ImageT> getRenderOffsets(
        coroutineContext: CoroutineContext,
        pose: Pose,
        parts: Map<Char, ParsedBodyPartRenderData<ImageT>>,
        nonIntersectingLimbs: Boolean,
        trueSize: ((ImageT) -> Size)? = null
    ): RenderOffsets<ImageT>? {

        val poseData = parts.map {(key, data) ->
            coroutineContext.ensureActive()
            key.asChar() to data.dataForPose(pose, trueSize)
        }.toMap()

        return buildParts(
            variant = pose.variant,
            pose = pose,
            parts = poseData,
            nonIntersectLimbs = nonIntersectingLimbs,
        )
    }


    /**
     * Fetches the render information for a single part in a single pose
     */
    private suspend fun <ImageT> getPartData(
        pose: Pose,
        parts: Map<Char, ParsedBodyPartRenderData<ImageT>>,
        part: Char,
        nullable: Boolean = false,
        trueSize: ((ImageT) -> Size)? = null
    ): PoseRenderFrameData<ImageT>? {

        val data = parts[part]

        if (data == null) {
            if (nullable) {
                return null
            }
            throw PoseRenderException("Missing body part data for part <${part.asString()}>")
        }

        return data.dataForPose(pose, trueSize)
    }

    /**
     * Formats render data for a single pose, calculating offsets and required part z-order
     * Data from here is ready to be rendered
     */
    private fun <ImageT> buildParts(
        variant: GameVariant,
        pose: Pose,
        parts: Map<Char, PoseRenderFrameData<ImageT>>,
        nonIntersectLimbs: Boolean,
    ): RenderOffsets<ImageT>? {

        val body = parts[BODY]?.copy(
            offset = Point(0,0)
        ) ?: throw PoseRenderException("Part: $BODY does not exist in ${parts.keys}")
        val bodyAtt = body.attFileLine

        val head: PoseRenderFrameData<ImageT> = parts[HEAD]!!.withAttachedAt(bodyAtt[0])

        val leftEar: PoseRenderFrameData<ImageT>? = if (variant.isC2e && head.attFileLine.points.size > 3) {
            parts[LEFT_EAR]?.let { leftEar ->
                val headEarPoint = head.getOffsetPoint(2)
                leftEar.withAttachedAt(headEarPoint)
            }
        } else {
            null
        }

        val rightEar: PoseRenderFrameData<ImageT>? =  if (variant.isC2e && head.attFileLine.points.size > 3) {
            parts[RIGHT_EAR]?.let { rightEar ->
                val headEarPoint = head.getOffsetPoint(3)
                rightEar.withAttachedAt(headEarPoint)
            }
        } else {
            null
        }

        // Hair
        val hair: PoseRenderFrameData<ImageT>? =  if (variant.isC2e && head.attFileLine.points.size > 4) {
            parts[HAIR]?.let { part ->
                val headHairPoint = head.getOffsetPoint(4)
                part.withAttachedAt(headHairPoint)
            }
        } else {
            null
        }

        // Left Thigh
        val leftThigh: PoseRenderFrameData<ImageT> = parts[LEFT_THIGH]!!.let { part ->
            val attachAt = bodyAtt[1]
            part.withAttachedAt(attachAt)
        }

        // Left Shin
        val leftShin: PoseRenderFrameData<ImageT> = parts[LEFT_SHIN]!!.let { part ->
            val attachAt = leftThigh.getOffsetPoint(1)
            part.withAttachedAt(attachAt)
        }

        // Left Foot
        val leftFoot: PoseRenderFrameData<ImageT> = parts[LEFT_FOOT]!!.let { part ->
            val attachAt = leftShin.getOffsetPoint(1)
            part.withAttachedAt(attachAt)
        }

        // Right Thigh
        val rightThigh: PoseRenderFrameData<ImageT> = parts[RIGHT_THIGH]!!.let { part ->
            val attachAt = bodyAtt[2]
            part.withAttachedAt(attachAt)
        }

        // Right Shin
        val rightShin: PoseRenderFrameData<ImageT> = parts[RIGHT_SHIN]!!.let { part ->
            val attachAt = rightThigh.getOffsetPoint(1)
            part.withAttachedAt(attachAt)
        }

        // Right Foot
        val rightFoot: PoseRenderFrameData<ImageT> = parts[RIGHT_FOOT]!!.let { part ->
            val attachAt = rightShin.getOffsetPoint(1)
            part.withAttachedAt(attachAt)
        }

        // Left Upper Arm
        val leftUpperArm: PoseRenderFrameData<ImageT> = parts[LEFT_UPPER_ARM]!!.let { part ->
            val attachAt = bodyAtt[3]
            part.withAttachedAt(attachAt)
        }

        // Left Forearm
        val leftForearm: PoseRenderFrameData<ImageT> = parts[LEFT_FOREARM]!!.let { part ->
            val attachAt = leftUpperArm.getOffsetPoint(1)
            part.withAttachedAt(attachAt)
        }

        // Right Upper Arm
        val rightUpperArm: PoseRenderFrameData<ImageT> = parts[RIGHT_UPPER_ARM]!!.let { part ->
            val attachAt = bodyAtt[4]
            part.withAttachedAt(attachAt)
        }

        // Right Forearm
        val rightForearm: PoseRenderFrameData<ImageT> = parts[RIGHT_FOREARM]!!.let { part ->
            val attachAt = rightUpperArm.getOffsetPoint(1)
            part.withAttachedAt(attachAt)
        }

        val tail = if (pose.variant == GameVariant.C1) {
            val tailBase = parts[TAIL_TIP]?.let { part ->
                val attachAt = bodyAtt.getOrNull(5)
                    ?: return@let null
                part.withAttachedAt(attachAt)
            }

            val tailTip = if (tailBase != null) {
                parts[TAIL_BASE]?.let { part ->
                    val attachAt = tailBase.getOffsetPoint(1)
                    part.withAttachedAt(attachAt)
                }
            } else {
                null
            }
            // Tail layer
            listOfNotNull(
                tailBase,
                tailTip
            )
        } else {
            val tailBase = parts[TAIL_BASE]?.let { part ->
                val attachAt = bodyAtt.getOrNull(5)
                    ?: return@let null
                part.withAttachedAt(attachAt)
            }

            val tailTip = parts[TAIL_TIP]?.let { part ->
                if (tailBase != null) {
                    val attachAt = tailBase.getOffsetPoint(1)
                    part.withAttachedAt(attachAt)
                } else {
                    null
                }
            }
            // Tail layer
            listOfNotNull(
                tailBase,
                tailTip
            )
        }

        // Head layer
        val headParts: List<PoseRenderFrameData<ImageT>> = when (pose.headFacing) {
            PoseFacing.VIEWER_RIGHT -> listOfNotNull(
                leftEar,
                head,
                hair,
                rightEar
            )

            PoseFacing.VIEWER_LEFT -> listOfNotNull(
                rightEar,
                head,
                hair,
                rightEar
            )

            PoseFacing.BACK -> listOfNotNull(
                head,
                leftEar,
                rightEar,
                hair
            )

            else -> listOfNotNull(
                leftEar,
                rightEar,
                hair,
                head,
            )
        }

        // Left Leg Layer
        val leftLeg = listOf(
            leftThigh,
            leftShin,
            leftFoot
        )

        // Right leg layer
        val rightLeg = listOf(
            rightThigh,
            rightShin,
            rightFoot
        )

        // Left Arm layer
        val leftArm = listOf(
            leftUpperArm,
            leftForearm
        )

        // Right arm layer
        val rightArm: List<PoseRenderFrameData<ImageT>> = listOf(
            rightUpperArm,
            rightForearm
        )

        // Parts in order
        @Suppress("SpellCheckingInspection")
        val partsInOrder: List<PoseRenderFrameData<ImageT>> = (if (variant.isC1e) {
            // OLD VARIANTS
            when (pose.bodyFacing) {
                // l.libs[-1] tail[0] body[0] rlimbs[1] Head[3]
                PoseFacing.VIEWER_RIGHT -> if (nonIntersectLimbs) {
                    leftArm + leftLeg + body + tail + headParts + rightLeg + rightArm
                } else {
                    leftArm + leftLeg + body + tail + rightLeg + rightArm + headParts
                }
                //  r.limbs[-1]  tail[0] l.libs[1] Head[3]
                PoseFacing.VIEWER_LEFT -> if (nonIntersectLimbs) {
                    rightArm + rightLeg + body + tail + headParts + leftLeg + leftArm
                } else {
                    rightArm + rightLeg + body + tail + leftLeg + leftArm + headParts
                }
                // tail[-1] body[0] limbs[1] Head[3]
                PoseFacing.FRONT -> if (variant == GameVariant.C1) {
                    tail + leftLeg + rightLeg + body + leftArm + rightArm + headParts
                } else {
                    tail + leftLeg + rightLeg + body + leftArm + rightArm + headParts
                }
                //  body[0] (limbs|tail)[1] Head[3]
                PoseFacing.BACK -> if (variant == GameVariant.C1) {
                    body + leftArm + rightArm + leftLeg + rightLeg + tail + headParts
                } else {
                    leftArm + rightArm + leftLeg + rightLeg + body + tail + headParts
                }
                else -> null
            }
        } else if (nonIntersectLimbs) {
            // NEW VARIANTS
            when (pose.bodyFacing) {
                PoseFacing.VIEWER_RIGHT -> leftArm + leftLeg + tail.getOrNull(0) + body + tail.getOrNull(1) + headParts + rightLeg + rightArm
                PoseFacing.VIEWER_LEFT -> rightArm + rightLeg + tail.getOrNull(0) + body + tail.getOrNull(1) + headParts + leftLeg + leftArm
                PoseFacing.FRONT -> tail + leftLeg + rightLeg + leftUpperArm + rightUpperArm + body + leftForearm + rightForearm + headParts
                PoseFacing.BACK -> leftArm + rightArm + leftLeg + rightLeg + body + headParts + leftEar + rightEar + hair + tail
                else -> null
            }
        } else {
            // NEW VARIANTS
            when (pose.bodyFacing) {
                PoseFacing.VIEWER_RIGHT -> /* -2 */leftLeg[1] + /* -2 */leftArm[1] + /* -1 */leftLeg[0] + /* -1 */leftLeg[2] + /* -1 */ leftArm[0] + /* -1 */tail.getOrNull(0) + /* 0 */body + /* 0 */tail.getOrNull(1) + /* 1 */rightLeg[0] + /* 2 */headParts + /* 2 */rightLeg[1] + /* 2 */rightArm[0]+ /* 3 */rightLeg[2] + /* 3 */rightArm[1]
                PoseFacing.VIEWER_LEFT  -> /* -2 */rightLeg[1] + /* -2 */rightArm[1] +/* -1 */ rightLeg[0] + /* -1 */rightLeg[2] + /* -1 */rightArm[0] + /* -1 */tail.getOrNull(0) + /* 0 */body + /* 0 */tail.getOrNull(1) + /* 1 */leftLeg[0] + /* 2 */headParts + /* 2 */leftLeg[1] + /* 2 */leftArm[0]+ /* 3 */leftLeg[2] + /* 3 */leftArm[1]
                PoseFacing.FRONT -> /* -5 */ leftEar + rightEar + /* -4 */ hair +  /* -2 */tail.getOrNull(1) + /* -1 */ tail.getOrNull(0) + leftLeg[0] + rightLeg[0] + leftUpperArm + rightUpperArm + /*0*/ body + leftLeg[1] + rightLeg[1] + /* 1 */ leftLeg[2] + rightLeg[2] + leftForearm + rightForearm + /* 3 */ headParts[0]
                PoseFacing.BACK -> /* -3 */ leftLeg[2] + /* -3 */rightLeg[2] + /* -2 */leftLeg[1] + /* -2 */rightLeg[1] + /* -2 */leftArm[1] + /* -2 */rightArm[1] + /* -1 */leftLeg[0] + /* -1 */rightLeg[0] + /* -1 */leftArm[0] + /* -1 */rightArm[0] + /* 0 */ body  +  /* 1 */ headParts[0] + tail.getOrNull(0) + leftEar + rightEar + /* 2 */ tail.getOrNull(1) + hair
                else -> null
            }
        })?.filterNotNull()
            ?: return null

        val minX = partsInOrder.minOfOrNull { it.offset!!.x } ?: 0
        val minY = partsInOrder.minOfOrNull { it.offset!!.y } ?: 0
        val offset = Point(-minX, -minY)
        val partsAtOrigin = partsInOrder.map { part ->
            part.copy(
                offset = part.offset!! + offset,
            )
        }

        val maxX = partsAtOrigin.maxOfOrNull { it.offset!!.x + it.size.width } ?: 0
        val maxY = partsAtOrigin.maxOfOrNull { it.offset!!.y + it.size.height } ?: 0
        val size = Size(maxX, maxY)

        return RenderOffsets(parts = partsAtOrigin, size = size)
    }

}


operator fun <ImageT> PoseRenderFrameData<ImageT>?.plus(other: PoseRenderFrameData<ImageT>?): List<PoseRenderFrameData<ImageT>> {
    return listOfNotNull(this, other)
}

operator fun <ImageT> PoseRenderFrameData<ImageT>?.plus(other: List<PoseRenderFrameData<ImageT>?>?): List<PoseRenderFrameData<ImageT>> {
    if (other == null) {
        return listOfNotNull(this)
    }
    return listOfNotNull(this) + other.filterNotNull()
}


operator fun <ImageT> List<PoseRenderFrameData<ImageT>>.plus(other: PoseRenderFrameData<ImageT>?): List<PoseRenderFrameData<ImageT>> {
    if (other == null) {
        return this
    }
    return this + other.toListOf()
}