package com.bedalton.common.util

import com.bedalton.log.LOG_VERBOSE
import com.bedalton.log.Log
import com.bedalton.log.iIf
import kotlin.jvm.JvmStatic

enum class Platform {
    WINDOWS,
    MACOS,
    LINUX,
    JS,
    UNKNOWN;


    companion object {
        @JvmStatic
        fun isJs() = platform == JS

        @JvmStatic
        fun isWindows() = platform == WINDOWS

        @JvmStatic
        fun isMacOs() = platform == MACOS

        @JvmStatic
        fun isLinux() = platform == LINUX

        @JvmStatic
        fun isUnknown() = platform == UNKNOWN

        @JvmStatic
        fun isJVM() = com.bedalton.common.util.isJVM()
    }

}

expect val platform: Platform

internal expect fun isJVM(): Boolean




fun Collection<String>.sortedNice(): List<String> {
    var last: String? = null
    val current = mutableListOf<String>()
    val out = mutableListOf<String>()
    for (item in this) {
        val path = PathUtil.getWithoutLastPathComponent(item)?.lowercase()
        if (path != null && last == null) {
            last = path
        }

        if (path == last) {
            current.add(item)
            continue
        }

        out.addAll(current.sortedWith(sortedFilesNice))
        current.clear()
        // Start new line
        current.add(item)
        last = path
    }

    if (current.isNotEmpty()) {
        out.addAll(current.sortedWith(sortedFilesNice))
    }
    return out
}

private val leadingNumberRegex = "^(\\d+)(.+?)?(\\d+)?(\\..+$)?".toRegex()
private val trailingNumberRegex = "^(\\d+)?(.+?)?(\\d+)(\\..+$)?".toRegex()

/**
 * Sort string values by leading and trailing numbers
 */
private val sortedFilesNice: Comparator<String> = Comparator sort@{ aRaw: String, bRaw: String ->
    val a = (PathUtil.getLastPathComponent(aRaw) ?: aRaw).lowercase()
    val b = (PathUtil.getLastPathComponent(bRaw) ?: bRaw).lowercase()
    val aDirectory = PathUtil.getSelfOrParentDirectory(aRaw)?.lowercase()?.ensureNotEndsWith(a)
    val bDirectory = PathUtil.getSelfOrParentDirectory(bRaw)?.lowercase()?.ensureNotEndsWith(b)
    if (aDirectory != null && aDirectory != a && bDirectory != null && bDirectory != b) {
        val sort = aDirectory.compareTo(bDirectory)
        if (sort != 0) {
            return@sort 1
        }
    }
    val aMatchLeading = leadingNumberRegex
        .matchEntire(a)
        ?.groupValues
        ?.let {
            Pair(it[2], it[1].toInt())
        }
    val bMatchLeading = leadingNumberRegex
        .matchEntire(b)
        ?.groupValues
        ?.let {
            Pair(it[2], it[1].toInt())
        }

    if (aMatchLeading != null && bMatchLeading != null) {
        val numberA = aMatchLeading.second
        val numberB = bMatchLeading.second
        val numberSort = numberA - numberB
        if (numberSort != 0) {
            return@sort numberSort
        }

        val nameSort = aMatchLeading.first.compareTo(bMatchLeading.first)
        if (nameSort != 0) {
            return@sort nameSort
        }

    }


    // Get a parts with trailing number
    val aMatchTrailing = trailingNumberRegex
        .matchEntire(a)
        ?.groupValues
        ?.let { matches ->
            Pair(matches[2].let { name -> if (name.startsWith('.')) "" else name }, matches[3].toInt())
        }

    // Get b parts with trailing number
    val bMatchTrailing = trailingNumberRegex
        .matchEntire(b)
        ?.groupValues
        ?.let { matches ->
            Pair(matches[2].let { name -> if (name.startsWith('.')) "" else name }, matches[3].toInt())
        }

    // Compare the parts by their trailing number
    if (aMatchTrailing != null && bMatchTrailing != null) {
        val nameSort = aMatchTrailing.first.compareTo(bMatchTrailing.first)
        Log.iIf(LOG_VERBOSE)  { "Sorting ${aMatchTrailing.first}${aMatchTrailing.second}, ${bMatchTrailing.first}:${bMatchTrailing.second}" }
        if (nameSort != 0) {
            Log.iIf(LOG_VERBOSE)  { "Sorting ${aMatchTrailing.first}${aMatchTrailing.second}, ${bMatchTrailing.first}:${bMatchTrailing.second}" }
            return@sort nameSort
        }
        val numberA = aMatchTrailing.second
        val numberB = bMatchTrailing.second
        val sort = numberA - numberB
        if (sort != 0) {
            return@sort sort
        }
    }
    a.compareTo(b)
}