@file:Suppress("ClassName", "FunctionName")
import com.bedalton.creatures.caos.libs.GameVariant
import com.bedalton.creatures.caos.libs.caosJsonSerializer
import com.bedalton.creatures.caos.util.parseResultFromDynamic_JsApi
import kotlinx.serialization.json.encodeToDynamic


@JsExport
@JsName("validateCaos")
@Suppress("USELESS_CAST")
fun validateCaos_jsApi(variant: GameVariant, data: dynamic /* string | ParseResult*/, checkCancelled: () -> Unit = {}): dynamic /*Array<CaosParserItem.ErrorVal*/ {
    val errors = if (data is String) {
        com.bedalton.creatures.caos.validation.validateCaos(variant, data as String, checkCancelled)
    } else {
        val parseResult = parseResultFromDynamic_JsApi(data)
            ?: throw Exception("Invalid data passed to validateCaos. Expected string or ParseResult object")
        com.bedalton.creatures.caos.validation.validateCaosParseResult(parseResult, checkCancelled)
    }
    return caosJsonSerializer.encodeToDynamic(errors)

}
