package com.bedalton.creatures.agents.pray.compiler.pray

import com.bedalton.common.util.PathUtil
import com.bedalton.common.util.nullIfEmpty
import com.bedalton.creatures.agents.pray.compiler.data.*
import com.bedalton.creatures.agents.pray.compiler.data.CompilerPrayBlock.NotImplementedPrayBlock
import com.bedalton.creatures.agents.pray.compiler.internal.getInputDataForValidationOnly
import com.bedalton.creatures.agents.pray.compiler.pray.PrayValidationError.DuplicateAgentNameError
import com.bedalton.creatures.agents.pray.compiler.pray.PrayValidationError.InlineFileError
import com.bedalton.creatures.agents.pray.compiler.pray.validators.validatePrayAgentBlock
import com.bedalton.creatures.agents.pray.compiler.pray.validators.validatePrayEggBlock
import com.bedalton.creatures.agents.util.RelativeFileSystem
import com.bedalton.vfs.FileSystem
import kotlinx.coroutines.CoroutineScope
import kotlin.coroutines.CoroutineContext
import kotlin.coroutines.coroutineContext

object PrayDataValidator {



    @Deprecated(
        "use validate() with explicit CoroutineScope",
        replaceWith = ReplaceWith(
            "validate(CoroutineScope(coroutineContext), fs, absolutePath, text, subFoldersOnly)",
            imports = ["kotlin.coroutines.coroutineContext", "kotlinx.coroutines.CoroutineScope"]
        )
    )
    suspend fun validate(
        fs: FileSystem,
        absolutePath: String,
        text: String,
        subFoldersOnly: Boolean
    ): Array<PrayValidationError> {
        return validate(CoroutineScope(coroutineContext), fs, absolutePath, text, subFoldersOnly)
    }

    @Deprecated(
        "Use validate with explicit CoroutineScope",
        replaceWith = ReplaceWith(
            "validate(CoroutineScope(coroutineContext), fs, absolutePath, text, subFoldersOnly)",
            imports = ["kotlinx.coroutines.CoroutineScope"]
        )
    )
    suspend fun validate(
        coroutineContext: CoroutineContext,
        fs: FileSystem,
        absolutePath: String,
        text: String,
        subFoldersOnly: Boolean
    ): Array<PrayValidationError> {
        return validate(CoroutineScope(coroutineContext), fs, absolutePath, text, subFoldersOnly)
    }

    /**
     * Validates pray text for valid file paths and tags
     *
     * @param coroutineScope
     * @param fs
     * @param absolutePath
     * @param text
     * @param subFoldersOnly
     * @return
     */
    suspend fun validate(
        coroutineScope: CoroutineScope,
        fs: FileSystem,
        absolutePath: String,
        text: String,
        subFoldersOnly: Boolean
    ): Array<PrayValidationError> {
        val parentPath = PathUtil.combine(absolutePath, "..")
        val fileName = absolutePath.substring(parentPath.length + 1)
        val relativeFs = RelativeFileSystem(fs, parentPath, subFoldersOnly = subFoldersOnly)
        val parseResult = getInputDataForValidationOnly(coroutineScope, relativeFs, fileName, text)
        return validate(coroutineScope, absolutePath, parseResult.prayData, relativeFs)
    }

    /**
     * Validates pray data for valid paths and tags
     *
     * @param coroutineScope
     * @param fullFilePath
     * @param prayData
     * @param fs
     * @return
     */
    internal suspend fun validate(
        coroutineScope: CoroutineScope,
        fullFilePath: String,
        prayData: CompilerPrayData,
        fs: RelativeFileSystem,
    ): Array<PrayValidationError> {
        val errors = prayData.parseErrors.toMutableList()
        validateLanguage(fullFilePath, prayData.language, errors)
        val blockNamesLowercase = prayData.blocks.map { it.blockTag + ":" + it.blockName.text.lowercase() }
        prayData.blocks.forEach { block ->
            val blockNameLowercase = block.blockTag + ":" + block.blockName.text.lowercase()
            if (blockNamesLowercase.count { it == blockNameLowercase } > 1)
                errors.add(
                    DuplicateAgentNameError(
                        blockTag = block.blockTag.text,
                        blockName = block.blockName.text,
                        lineNumber = block.startLine,
                        startIndex = block.blockName.startIndex,
                        endIndex = block.blockName.endIndex,
                        fullFilePath = fullFilePath
                    )
                )
            errors.addAll(validateBlock(coroutineScope, fullFilePath, fs, block))
        }
        prayData.inlineFiles.forEach { inlineFile ->
            validateInlineFile(fullFilePath, errors, fs, inlineFile)
        }
        return errors.toTypedArray()
    }

    /**
     * Validate language value
     */
    private fun validateLanguage(fullFilePath: String, language: TextValue?, errors: MutableList<PrayValidationError>) {
        if (language?.text.isNullOrBlank()) {
            errors.add(
                PrayValidationError.InvalidLanguage(
                    null,
                    "Language cannot be null",
                    0,
                    startIndex = -1,
                    endIndex = -1,
                    fullFilePath = fullFilePath
                )
            )
        } else if (language?.text?.matches("[a-zA-Z]{2}-[a-zA-Z]{2}".toRegex()) != true) {
            errors.add(
                PrayValidationError.InvalidLanguage(
                    language?.text,
                    "Invalid language format",
                    lineNumber = language?.lineNumber ?: 0,
                    startIndex = language?.startIndex ?: -1,
                    endIndex = language?.endIndex ?: -1,
                    fullFilePath = fullFilePath
                )
            )
        }
    }

    /**
     * Validate a pray block
     */
    internal suspend fun validateBlock(
        coroutineScope: CoroutineScope,
        fullFilePath: String,
        fs: RelativeFileSystem,
        block: CompilerPrayBlock
    ): Array<PrayValidationError> {
        // Create list of errors
        val errors = mutableListOf<PrayValidationError>()

        // If block has tags, validate them
        if (block is CompilerBlockWithTags) {
            PrayTagsValidator.validateTags(fullFilePath, errors, block.blockTag, block.blockName, block.tags)
        }
        // Validate by block type
        when (block) {
            is NotImplementedPrayBlock -> errors.add(
                PrayValidationError.BlockNotImplementedError(
                    blockTag = block.blockTag,
                    blockName = block.blockName,
                    lineNumber = block.startLine,
                    startIndex = block.blockTag.startIndex,
                    endIndex = block.blockTag.endIndex,
                    fullFilePath = fullFilePath
                )
            )

            is CompilerEggBlock -> validatePrayEggBlock(fullFilePath, block, errors)
            is CompilerAgentBlock -> validatePrayAgentBlock(coroutineScope, fullFilePath, fs::fileExists, block, errors)
            is CompilerBlockWithTags -> {
            }

            is CompilerDataBlock -> {

            }

            is CompilerGLSTBlock -> {}
            is CompilerPhotBlock -> {}
            is CompilerREQUBlock -> {}
        }

        // Return errors list
        return errors.toTypedArray()
    }

    /**
     * Validates inline files
     */
    private suspend fun validateInlineFile(
        fullFilePath: String,
        validationErrors: MutableList<PrayValidationError>,
        fs: RelativeFileSystem,
        inlineFile: InlineFile,
    ) {
        if (inlineFile.inputFileName.text.isBlank()) {
            validationErrors.add(
                InlineFileError(
                    inlineFile,
                    inlineFile.inputFileName,
                    "Input file name cannot be blank",
                    inlineFile.containingFile.nullIfEmpty() ?: fullFilePath
                )
            )
        }
        if (inlineFile.outputFileName.text.isBlank()) {
            validationErrors.add(
                InlineFileError(
                    inlineFile,
                    inlineFile.outputFileName,
                    "Output file name cannot be blank",
                    inlineFile.containingFile.nullIfEmpty() ?: fullFilePath
                )
            )
        }
        if (!fs.fileExists(inlineFile.inputFileName.text)) {
            validationErrors.add(
                InlineFileError(
                    inlineFile,
                    inlineFile.inputFileName,
                    "Failed to locate inline file: '${inlineFile.inputFileName}' @ ${fs.path(inlineFile.inputFileName.text)}",
                    inlineFile.containingFile.nullIfEmpty() ?: fullFilePath
                )
            )
        }
    }

}

