    /**
     * Parses a sprite file given a name and byte information
     * File name is used to determine the kind of sprite being passed in
     * Allows for sprite progress callback with (last parsed sprite and total number of sprites)
     */
    fun parseToFile(
        fileName: String,
        bytesBuffer: ByteStreamReader,
        keepBlack: Boolean,
        paletteTransform: PaletteTransform? = null,
        progressChunkSize: Int = 1,
        progressCallback: ((current: Int, total: Int) -> Boolean?)? = null,
    ): SpriteFile {
        // Determine extension
        val extension = PathUtil.getExtension(fileName.lowercase())
        if (extension.isNullOrEmpty()) {
            throw Exception("ERR500: Invalid file extension. Extension cannot be blank")
        }
        // Return promise for parsing
        return when (extension) {
            "spr" -> SprSpriteFile(
                bytesBuffer,
                false,
                getC1NonNullPalette(null, keepBlack, paletteTransform),
                progressChunkSize,
                progressCallback
            )

            "s16" -> S16SpriteFile(bytesBuffer, keepBlack, paletteTransform, progressChunkSize, progressCallback)
            "c16" -> C16SpriteFile(bytesBuffer, keepBlack, paletteTransform, progressChunkSize, progressCallback)
            "back", "blk" -> BlkSpriteFile(
                bytesBuffer,
                progressChunkSize,
                progressCallback
            ) // Can get cell size separately
            else -> throw SpriteParserException("Invalid image file extension found")
        }
    }

