    fun imagesCount(
        fileName: String,
        bytes: ByteArray
    ): Int? {
        val extension = PathUtil.getExtension(fileName)
            ?.lowercase()
            ?: return null
        val offset = if (extension == "blk" || extension == "back") {
            8
        } else if (extension != "spr") {
            4
        } else {
            0
        }
        return try {
            bytes.uInt16(offset)
        } catch (e: Exception) {
            Log.eIf(LOG_DEBUG) {
                "Failed to get image count: ${e.className}: ${e.message}\n${e.stackTraceToString()}"
            }
            null
        }
    }

    /**
     * Gets the number of images inside a sprite file
     */
    fun imagesCount(fileName: String, bytesBuffer: ByteStreamReader): Int? {
        return try {
            val extension = PathUtil.getExtension(fileName)?.lowercase()
                ?: return null
            val offset = if (extension == "blk" || extension == "back") {
                8
            } else if (extension != "spr") {
                4
            } else {
                0
            }
            bytesBuffer.readAtPositionReturning(offset) {
                uInt16()
            }
        } catch (e: Exception) {
            Log.eIf(LOG_DEBUG) {
                "Failed to get image count: ${e.className}: ${e.message}\n${e.stackTraceToString()}"
            }
            null
        }
    }


    fun getBodySpriteVariant(
        fileName: String,
        spriteFile: ByteArray,
        defaultVariant: GameVariant?,
    ): GameVariant? {
        return getBodySpriteVariant(
            fileName,
            defaultVariant
        ) {
            imagesCount(fileName, spriteFile)
                ?: return defaultVariant
        }
    }

    fun getBodySpriteVariant(
        fileName: String,
        spriteFile: ByteStreamReader,
        defaultVariant: GameVariant?,
    ): GameVariant? {
        return getBodySpriteVariant(
            fileName,
            defaultVariant
        ) {
            imagesCount(fileName, spriteFile)
                ?: return defaultVariant
        }
    }


    private inline fun getBodySpriteVariant(
        fileName: String,
        defaultVariant: GameVariant?,
        getCount: () -> Int,
    ): GameVariant? {

        if (!BreedPartKey.isPartName(PathUtil.getFileNameWithoutExtension(fileName) ?: "")) {
            return defaultVariant
        }

        val extension = PathUtil.getExtension(fileName)?.lowercase()
            ?: defaultVariant

        if (extension !in setOf("spr", "s16", "c16")) {
            return defaultVariant
        }
        if (extension == "spr") {
            return GameVariant.C1
        }

        val part = fileName[0].lowercaseChar()

        val imageCount = try {
            getCount()
        } catch (e: Exception) {
            return defaultVariant
        }

        if (extension == "s16") {
            if (imageCount == 10 || imageCount == 120) {
                return GameVariant.C2
            }
        }
        if (defaultVariant == GameVariant.CV) {
            return GameVariant.CV
        }
        if (part == 'a') {
            if (imageCount > 192) {
                return GameVariant.CV
            }
        }
        return GameVariant.C3
    }

