package com.bedalton.creatures.agents.pray.compiler.caos2pray

import com.bedalton.common.util.PathUtil
import com.bedalton.common.util.like
import com.bedalton.creatures.agents.pray.compiler.GENERATED_TAGS_REGEX
import com.bedalton.creatures.agents.pray.compiler.PrayCompileOptions
import com.bedalton.creatures.agents.pray.compiler.caos2pray.internal.*
import com.bedalton.creatures.agents.pray.compiler.data.*
import com.bedalton.creatures.agents.pray.compiler.data.Tag.StringTag
import com.bedalton.creatures.agents.pray.compiler.internal.toUniqueArray
import com.bedalton.creatures.agents.pray.compiler.linkWithFilenameReferenceNotNull
import com.bedalton.creatures.agents.pray.compiler.linkWithFilenameReferenceOrNull
import com.bedalton.creatures.agents.pray.compiler.pray.PrayValidationError
import com.bedalton.creatures.agents.pray.compiler.pray.internal.mergeRscrFromTags
import com.bedalton.creatures.agents.util.RelativeFileSystem
import com.bedalton.creatures.agents.util.internal.tagsWithGeneratedRemovers
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.ensureActive


/**
 * Takes in the raw parts parsed by the CAOS2Pray parser and returns a com.bedalton.creatures.pray.PrayData object
 * Walker must process the directives in the CAOS2Pray file into their pray tag equivalents
 * i.e. Attach "file-1.c16" into -> ["Dependency 1" "file-1.c16", "Dependency Category 1" 2, inline FILE "file-1.c16" "file-1.c16" ]
 */
internal suspend fun walkerResultToPray(
    coroutineScope: CoroutineScope,
    fs: RelativeFileSystem,
    fullFilePath: String,
    agentNames: List<AgentName>,
    commands: List<CommandValue>,
    tagsIn: List<Tag<*>>,
    opts: PrayCompileOptions,
    errors: MutableList<PrayValidationError>,
    isJoin: Boolean
): CompilerPrayData {

    if (agentNames.isEmpty()) {
        if (tagsIn.isNotEmpty() || commands.any { it.command == Caos2PrayCommands.LINK || it.command == Caos2PrayCommands.RSCR } ) {
            throw Caos2PrayException("Agent name is required.")
        }
    }

    val tags: List<Tag<*>> = tagsIn
        .map { tag ->

            // Convert tag into official tag if using short/friendly tag
            // i.e. "desc" -> "Agent Description"
            val resolvedTag = resolveTag(tag.tag)
            if (resolvedTag == tag.tag) {
                tag
            } else {
                when (tag) {
                    is StringTag -> tag.copy(
                        tagRange = tag.tagRange.copy(
                            text = resolvedTag
                        )
                    )

                    is Tag.IntTag -> tag.copy(
                        tagRange = tag.tagRange.copy(
                            text = resolvedTag
                        )
                    )

                    is Tag.LinkTag -> tag.copy(
                        tagRange = tag.tagRange.copy(
                            text = resolvedTag
                        )
                    )
                }
            }
        } + // Adds an Agent type tag if not already defined
            (if (tagsIn.none { it.tag like "Agent Type" }) listOf(agentTypeTag) else emptyList())

    // Create necessary tags for dependencies
    // Keep result as a Dependency Count field is required
    val dependencies = processDependencies(tags.filterIsInstance<StringTag>(), commands)

    // Create removal script tags
    val removalScripts = commands
        .filter { it.command == Caos2PrayCommands.RSCR }
        .flatMap command@{ command ->
            processRscr(
                fs,
                fullFilePath,
                command,
                errors
            )
        }

    coroutineScope.ensureActive()

    // Get script tags and link commands and combine as necessary
    val scriptTags = processLinks(
        coroutineScope,
        fs = fs,
        fullFilePath = fullFilePath,
        commands = commands,
        tags = tags,
        mergeScripts = opts.mergeScripts,
        errors = errors,
        linkWithFilenameReference = opts.linkWithFilenameReferenceNotNull
    ).let { linkedScripts: List<StringTag> ->
        processScriptTag(opts.mergeScripts, linkedScripts)
    }

    // Some tags will be overwritten to be valid
    // So remove them now
    // i.e. "Script Count", "Dependency Count", "Dependency 1"
    val tagsWithoutGenerated = filterWillBeGeneratedTags(tags)

    // Combine all tags created
    var tagsOut: List<Tag<*>> = tagsWithoutGenerated +
            scriptTags +
            dependencies +
            removalScripts

    // If needed, auto-generate agent and or script removers
    if (opts.generateAgentRemovers || opts.generateScriptRemovers) {
        tagsOut = tagsWithGeneratedRemovers(tagsOut.toTypedArray(), opts).toList()
    }

    // Merge removal scripts if requested
    if (opts.mergeRscr) {
        tagsOut = mergeRscrFromTags(coroutineScope, fs, tagsOut + removalScripts)
    }

    // Create blocks with the tags
    val blocks = agentNames.map { agentName ->
        coroutineScope.ensureActive()
        CompilerAgentBlock(
            startLine = agentName.lineNumber,
            blockTag = agentName.agentTag,
            blockName = agentName.agentName,
            false,
            tags = tagsOut.toTypedArray(),
            fullFilePath = fullFilePath,
            linkWithFilenameReference = opts.linkWithFilenameReferenceOrNull
        )
    }

    // Joined CAOS2Pray agents files
    val joins = processJoins(coroutineScope, fs, fullFilePath, opts, commands, isJoin = isJoin)

    // Actual data from joins (it.first is the name of the file)
    val joinedData = joins.map { it.second }

    // All joined agent Blocks
    val otherBlocks = joinedData.flatMap { it.blocks.toList() }

    // Errors from all joined CAOS2Pray files
    val otherErrors = joinedData.flatMap { it.parseErrors.toList() }

    val rootDirectory = PathUtil.getDirname(fs.path(fullFilePath)) ?: ""

    // Inline Files
    val otherInlineFiles = joinedData.flatMap {

        val joinDirectory = PathUtil.getDirname(fs.path((it.fullFilePath)))
            ?: ""

        if (joinDirectory == rootDirectory) {
            it.inlineFiles.map { inlineFile ->
                InlineFile(
                    inlineFile.blockTag,
                    inlineFile.outputFileName,
                    inlineFile.inputFileName.copy(text = fs.path(inlineFile.inputFileName.text)),
                    inlineFile.lineNumber,
                    inlineFile.startIndex,
                    inlineFile.endIndex,
                    containingFile = inlineFile.containingFile
                )
            }
        } else {

            it.inlineFiles.map { inlineFile ->
                val path = PathUtil.combine(joinDirectory, inlineFile.inputFileName.text)
                var relativePath = PathUtil.relativePath(rootDirectory, path)
                    ?: inlineFile.inputFileName.text
                if (PathUtil.isAbsolute(relativePath) && !fs.fileExists(relativePath)) {
                    relativePath = relativePath.substring(1)
                }
                InlineFile(
                    inlineFile.blockTag,
                    inlineFile.outputFileName,
                    inlineFile.inputFileName.copy(text = fs.path(relativePath)),
                    inlineFile.lineNumber,
                    inlineFile.startIndex,
                    inlineFile.endIndex,
                    containingFile = inlineFile.containingFile
                )
            }
        }
    }

    val allInlineFiles = (processInline(commands, fullFilePath).plus(otherInlineFiles))
        .toUniqueArray()

    // Output pray data for validation or compiling
    return CompilerPrayData(
        language = TextValue(
            text = "en-GB",
            lineNumber = -1,
            startIndex = -1,
            endIndex = -1
        ),
        fullFilePath = fullFilePath,
        blocks = (blocks.plus(otherBlocks)).distinct().toTypedArray(),
        inlineFiles = allInlineFiles,
        joinedFiles = joins.toTypedArray(),
        parseErrors = (errors.plus(otherErrors)).toSet().toTypedArray(),
        unescape = false
    )
}


/**
 * Strip tags that will be auto generated by the script
 */
private fun filterWillBeGeneratedTags(tags: List<Tag<*>>): List<Tag<*>> {
    return tags.filterNot {
        GENERATED_TAGS_REGEX.matches(it.tag)
    }
}

private val agentTypeTag
    get() = Tag.IntTag(
        lineNumber = 0,
        startIndex = -1,
        endIndex = -1,
        tagRange = TextValue(
            text = "Agent Type",
            0,
            -1,
            -1
        ),
        value = TextValue(
            "0",
            0,
            -1,
            -1
        ),
        tagValue = 0
    )

