package com.bedalton.common.geometry


fun <T: IPoint> pointWithMinX(point: T, otherPoint: T): T {
    return if (point.x <= otherPoint.x)
        point
    else
        otherPoint
}

fun <T: IPoint> pointWithMaxX(point: T, otherPoint: T): T {
    return if (point.x >= otherPoint.x)
        point
    else
        otherPoint
}

fun <T: IPoint> pointWithMinY(point: T, otherPoint: T): T {
    return if (point.y <= otherPoint.y)
        point
    else
        otherPoint
}

fun <T: IPoint> pointWithMaxY(point: T, otherPoint: T): T {
    return if (point.y >= otherPoint.y)
        point
    else
        otherPoint
}

inline fun <T: IPoint> minPointWith(point: T, otherPoint: T, check: (p:T) -> Int): T {
    return if (check(point) <= check(otherPoint))
        point
    else
        otherPoint
}

inline fun <T: IPoint> maxPointWith(point: T, otherPoint: T, check: (p:T) -> Int): T {
    return if (check(point) >= check(otherPoint))
        point
    else
        otherPoint
}

inline fun <T: IPoint> pointOf(point: T, otherPoint: T, check: (p1:T, p2:T)->Boolean): T {
    return if (check(point, otherPoint))
        point
    else
        otherPoint
}



/**
 * Convenience function to subtract one point from another
 */
operator fun Point.minus(other: Point): Point {
    return Point(
        this.x - other.x,
        this.y - other.y
    )
}

/**
 * Convenience function to add one point to another
 */
operator fun Point.plus(other: Point): Point {
    return Point(
        this.x + other.x,
        this.y + other.y
    )
}