package com.bedalton.creatures.sprite.util

import korlibs.image.color.RGBA

internal fun swapAndRotateC2(
    encoding: ColorEncoding,
    black: RGBA,
    red: Int?,
    green: Int?,
    blue: Int?,
    swap: Int?,
    rotation: Int?
): ColorPalette {

    if (
        isDefaultColorValue(red) &&
        isDefaultColorValue(green) &&
        isDefaultColorValue(blue) &&
        isDefaultColorValue(swap) &&
        isDefaultColorValue(rotation)
    ) {
        return encoding.toRgbWithTables(black)
    }

    val redMap = remap(red ?: 128)
    val greenMap = remap(green ?: 128)
    val blueMap = remap(blue ?: 128)

    val out = Array(65536) { ColorPalette.OPAQUE_BLACK }
    val blackish = encoding.blackishRGBA

    // Rotation
    val colorRotation = rotation ?: 128
    val absoluteRotation = if (colorRotation >= 128) {
        colorRotation - 128
    } else {
        128 - colorRotation
    }
    val inverseRotation = 127 - absoluteRotation

    // Swap
    val colorSwap = swap ?: 128
    val absoluteSwap = if (colorSwap >= 128) {
        colorSwap - 128
    } else {
        128 - colorSwap
    }
    val inverseSwap = 127 - absoluteSwap

    var redIndex = 0
    var i = 0
    // Loop through the ints
    while (redIndex < 256) {
        var greenIndex = 0
        while (greenIndex < 256) {
            var blueIndex = 0
            while (blueIndex < 256) {
                val redTint = redMap[redIndex]
                val greenTint = greenMap[greenIndex]
                val blueTint = blueMap[blueIndex]

                var rotateRed: Int?
                var rotateGreen: Int?
                var rotateBlue: Int?
                if (colorRotation < 128) {
                    rotateRed = (absoluteRotation * blueTint + inverseRotation * redTint) shr 7
                    rotateGreen = (absoluteRotation * redTint + inverseRotation * greenTint) shr 7
                    rotateBlue = (absoluteRotation * greenTint + inverseRotation * blueTint) shr 7
                } else {
                    rotateRed = (absoluteRotation * greenTint + inverseRotation * redTint) shr 7
                    rotateGreen = (absoluteRotation * blueTint + inverseRotation * greenTint) shr 7
                    rotateBlue = (absoluteRotation * redTint + inverseRotation * blueTint) shr 7
                }

                val swapRed = (absoluteSwap * rotateBlue + inverseSwap * rotateRed) shr 7
                val swapBlue = (absoluteSwap * rotateRed + inverseSwap * rotateBlue) shr 7

                out[i++] = if (swapRed == 0 && rotateGreen == 0 && swapBlue == 0) {
                    blackish
                } else {
                    RGBA(swapRed, rotateGreen, swapBlue, 255)
                }

                blueIndex += 8
            }
            greenIndex += 4
        }
        redIndex += 8
    }
    out[0] = black
    return ColorPalette(encoding, out, true)
}
