private fun remap(value: Int): Array<Int> {
    val base = value - 128
    val b = 64 + ((20 * base) shr 7)
    val c = 128 + ((32 * base) shr 7)
    val d = 192 + ((20 * base) shr 7)
    val out = Array(256) { 0 }
    repeat(64) { i ->
        out[i] = 0 + (((b - 0) * i) shr 6)
        out[i + 64] = b + (((c - b) * i) shr 6)
        out[i + 128] = c + (((d - c) * i) shr 6)
        out[i + 192] = d + (((255 - d) * i) shr 6)
    }
    return out
}
