@file:Suppress("unused")

package com.bedalton.io.bytes

import com.bedalton.io.bytes.internal.writeStringWithWindowsCP1252Encoding
import okio.Buffer
import kotlin.math.max

class MemoryByteStreamWriter(
    buffer: Buffer,
    work: (ByteStreamWriter.()-> Unit)? = null
): ByteStreamWriter {

    private var mBuffer: Buffer? = buffer

    private val buffer: Buffer get() = mBuffer
        ?: throw Exception("Already disposed writer")

    var mPosition = 0

    override val position get() = mPosition


    override val size: Long get() = buffer.size

    override val bytes: ByteArray get() = if (size == 0L) {
        byteArrayOf()
    } else {
        buffer.copy().readByteArray()
    }

    constructor():this(Buffer())

    constructor(
        work: (ByteStreamWriter.()-> Unit)
    ): this (Buffer(), work)

    @Suppress("UNUSED_PARAMETER")
    @Deprecated("Initial size and buffer length are not longer needed",
        replaceWith = ReplaceWith(
            "MemoryByteStreamWriter()"
        )
    )
    constructor(
        initialSize: Int,
        buffer: Int? = null,
    ): this (Buffer())

    @Suppress("UNUSED_PARAMETER")
    @Deprecated("Initial size and buffer length are not longer needed",
        replaceWith = ReplaceWith(
            "MemoryByteStreamWriter(initialSize, buffer, work)"
        )
    )
    constructor(
        initialSize: Int = DEFAULT_INITIAL_SIZE,
        buffer: Int? = null,
        work: (ByteStreamWriter.()-> Unit)?
    ): this (Buffer(), work)

    init {
        if (work != null) {
            this.work()
        }
    }

    override fun writeUInt8(byte: Int): MemoryByteStreamWriter {
        mPosition++
        buffer.writeByte(byte)
        return this
    }

    override fun write(bytes: ByteArray): MemoryByteStreamWriter {
        mPosition += bytes.size
        buffer.write(bytes)
        return this
    }

    override fun writeUInt16(ushortArray: Array<Int>): MemoryByteStreamWriter {
        mPosition += ushortArray.size * 2
        ushortArray.forEach(buffer::writeShortLe)
        return this
    }

    override fun writeUInt16(valueIn: Int): MemoryByteStreamWriter {
        mPosition += 2
        buffer.writeShortLe(valueIn)
        return this
    }

    override fun writeUInt16BE(valueIn: Int): MemoryByteStreamWriter {
        mPosition += 2
        buffer.writeShort(valueIn)
        return this
    }

    override fun writeUInt32(valueIn: Int): MemoryByteStreamWriter {
        mPosition += 4
        buffer.writeIntLe(valueIn)
        return this
    }

    override fun writeUInt32BE(valueIn: Int): MemoryByteStreamWriter {
        mPosition += 4
        buffer.writeInt(valueIn)
        return this
    }

    override fun writeUInt64(valueIn: Long): MemoryByteStreamWriter {
        mPosition += 8
        buffer.writeLongLe(valueIn)
        return this
    }

    override fun writeUInt64BE(valueIn: Long): MemoryByteStreamWriter {
        mPosition += 8
        buffer.writeLong(valueIn)
        return this
    }

    override fun writeFloat(valueIn: Float): MemoryByteStreamWriter {
        mPosition += 4
        com.bedalton.io.bytes.internal.writeFloat(this, valueIn)
        return this
    }

    override fun writeDouble(valueIn: Double): MemoryByteStreamWriter {
        mPosition += 8
        com.bedalton.io.bytes.internal.writeDouble(this, valueIn)
        return this
    }

    override fun writeStringWithCreaturesEncoding(valueIn: String): MemoryByteStreamWriter {

        mPosition += valueIn.length
        writeStringWithWindowsCP1252Encoding(this, valueIn)
        return this
    }

    companion object {
        private const val DEFAULT_BUFFER = 500
        const val DEFAULT_INITIAL_SIZE = 1000
    }

}