package com.bedalton.creatures.agents.pray.compiler.pray

import com.bedalton.creatures.agents.pray.compiler.DEPENDENCY_CATEGORY_REGEX
import com.bedalton.creatures.agents.pray.compiler.DEPENDENCY_TAG_REGEX
import com.bedalton.creatures.agents.pray.compiler.data.BlockDependency
import com.bedalton.creatures.agents.pray.compiler.data.Tag


/**
 * Finds and combines Dependency tags
 */
internal fun getBlockDependencies(tags: Array<Tag<*>>): Array<BlockDependency> {

    // Find all file names from "Dependency (n)"...
    val fileNames: MutableList<Pair<Int, Tag<*>>> = tags.mapNotNull map@{
        val match = DEPENDENCY_TAG_REGEX.matchEntire(it.tag)?.groupValues?.lastOrNull()
            ?: return@map null
        match.toInt() to it
    }.toMutableList()

    // Find all categories from "Dependency Category (n)"...
    val categories: MutableList<Pair<Int, Tag<*>>> = tags.mapNotNull map@{
        val index = DEPENDENCY_CATEGORY_REGEX.matchEntire(it.tag)?.groupValues?.lastOrNull()
            ?: return@map null
        index.toInt() to it
    }.toMutableList()

    // Combine all category and file name indices so everything is covered
    val indices = fileNames.map { it.first }.toSet().union(categories.map { it.first }.toSet())
    // Create output array
    val out: MutableList<BlockDependency> = mutableListOf()

    // Loop through all dependency indices and build dependency object
    for (index in indices) {
        // Get Dependency Parts
        // These can be null if one is set and not the other
        val categoriesWithIndex = categories.filter { it.first == index }
        val category = categoriesWithIndex.firstOrNull()?.second
        val fileNamesWithIndex = fileNames.filter { it.first == index }
        val filename = fileNamesWithIndex.firstOrNull()?.second
        out.add(
                BlockDependency(
                index = index,
                fileName = filename,
                category = category,
            )
        )
        if (filename != null && category != null) {
            out.addAll(
                categoriesWithIndex.drop(1).map { (index, cat) ->
                    BlockDependency(
                        index = index,
                        fileName = filename,
                        category = cat,
                    )
                } + fileNamesWithIndex.drop(1).map { (index, file) ->
                    BlockDependency(
                        index = index,
                        fileName = file,
                        category = category,
                    )
                }
            )
        } else if (category != null) {
            out.addAll(
                categoriesWithIndex.drop(1).map { (index, cat) ->
                    BlockDependency(
                        index = index,
                        fileName = filename,
                        category = cat,
                    )
                }
            )
        } else if (filename != null) {
            out.addAll(
                fileNamesWithIndex.drop(1).map { (index, file) ->
                    BlockDependency(
                        index = index,
                        fileName = file,
                        category = category,
                    )
                }
            )
        }
    }
    return out.toTypedArray()
}

