@file:Suppress("unused")

package com.bedalton.creatures.agents.pray.compiler.data

import com.bedalton.creatures.agents.pray.compiler.SCRIPT_TAG_REGEX
import com.bedalton.creatures.agents.util.WHITESPACE


internal fun Array<Tag.StringTag>.notScript(): Array<Tag.StringTag> {
    return filter { tag ->
        !SCRIPT_TAG_REGEX.matches(tag.tag.trim())
    }.toTypedArray()
}

internal fun Array<Tag.StringTag>.scripts(): Array<Tag.StringTag> {
    return filter { tag ->
        SCRIPT_TAG_REGEX.matches(tag.tag.trim())
    }.toTypedArray()
}


internal val Array<Tag<*>>.stringTags: Array<Tag.StringTag>
    get() = this.filterIsInstance<Tag.StringTag>().toTypedArray()

internal fun TextValue.toInt(): Int {
    return text.toInt()
}

internal fun TextValue.toIntOrNull(): Int? {
    return text.toIntOrNull()
}

internal operator fun TextValue.plus(string: String): String {
    return this.text + string
}

internal operator fun Tag<*>.plus(string: String): String {
    return this.toString() + string
}

operator fun <T> Array<Tag<T>>.get(tagName: String): T? {
    return this.firstOrNull { it.tag == tagName }?.value
}

fun Array<Tag.StringTag>.getString(tagName: String, fuzzy: Boolean = false): String? {
    if (fuzzy) {
        val regex = tagName.replace(WHITESPACE, "\\s+").toRegex(RegexOption.IGNORE_CASE)
        return this.firstOrNull { regex.matches(it.tag) }?.value
    }
    return this.firstOrNull { it.tag == tagName }?.value
}

fun Array<Tag.IntTag>.getInt(tagName: String, fuzzy: Boolean = false): Int? {
    if (fuzzy) {
        val regex = tagName.replace(WHITESPACE, "\\s+").toRegex(RegexOption.IGNORE_CASE)
        return this.firstOrNull { regex.matches(it.tag) }?.value
    }
    return this.firstOrNull { it.tag == tagName }?.value
}