package com.bedalton.creatures.genetics.parser

import com.bedalton.creatures.genetics.gene.*
import com.bedalton.creatures.genetics.gene.GeneConstants.GENE_SUBTYPE_BIOCHEMICAL_EMITTER
import com.bedalton.creatures.genetics.gene.GeneConstants.GENE_SUBTYPE_BIOCHEMICAL_HALF_LIVES
import com.bedalton.creatures.genetics.gene.GeneConstants.GENE_SUBTYPE_BIOCHEMICAL_INITIAL_CONCENTRATION
import com.bedalton.creatures.genetics.gene.GeneConstants.GENE_SUBTYPE_BIOCHEMICAL_REACTION
import com.bedalton.creatures.genetics.gene.GeneConstants.GENE_SUBTYPE_BIOCHEMICAL_RECEPTOR
import com.bedalton.creatures.genetics.gene.GeneConstants.GENE_SUBTYPE_NEURO_CHEMICAL_EMITTER
import com.bedalton.io.bytes.ByteStreamReader


internal fun readBioChemicalGene(version: Int, reader: ByteStreamReader, geneIndex: Int): Gene {
    return when (val subType = reader.uInt8()) {
        GENE_SUBTYPE_BIOCHEMICAL_RECEPTOR -> BiochemicalReceptorGene.fromReader(version, reader, geneIndex)
        GENE_SUBTYPE_BIOCHEMICAL_EMITTER -> BiochemicalEmitterGene.fromReader(version, reader, geneIndex)
        GENE_SUBTYPE_BIOCHEMICAL_REACTION -> BiochemicalReactionGene.fromReader(version, reader, geneIndex)
        GENE_SUBTYPE_BIOCHEMICAL_HALF_LIVES -> BiochemicalHalfLivesGene.fromReader(version, reader, geneIndex)
        GENE_SUBTYPE_BIOCHEMICAL_INITIAL_CONCENTRATION -> BiochemicalInitialConcentrationGene.fromReader(version, reader, geneIndex)
        GENE_SUBTYPE_NEURO_CHEMICAL_EMITTER -> NeuroEmitterGene.fromReader(version, reader, geneIndex)
        else -> throw GenomeParseException("Failed to understand gene type: Biochemical(1)->[$subType]")
    }
}