package com.creaturesforge.application.ui.controls

import com.bedalton.state.simple.Dispatch
import com.creaturesforge.application.state.FAction
import com.creaturesforge.application.state.ForgeState
import com.creaturesforge.application.state.ForgeStore
import com.creaturesforge.application.state.SetGenomeGenus
import com.creaturesforge.application.ui.html.attribute
import com.creaturesforge.application.ui.html.getBoolean
import kotlinx.browser.document
import kotlinx.browser.window
import org.w3c.dom.HTMLOptionElement
import org.w3c.dom.HTMLSelectElement

internal class GenusSelect(private val genomeGenusSelect: HTMLSelectElement): Validatable {

    private lateinit var dispatch: Dispatch<FAction>

    private var updateOnBrowserEvents = true

    init {
        setGenusOptions(genomeGenusSelect)
        genomeGenusSelect.onchange = {
            if (updateOnBrowserEvents) {
                window.setTimeout(this@GenusSelect::onGenusChange, 5)
            }
        }
        ForgeStore.subscribe { state, dispatch ->
            this.dispatch = dispatch
            updateGenus(state)
        }

    }


    private fun onGenusChange() {
        if (updateOnBrowserEvents) {
            genomeGenusSelect.attribute("data-user-selected", true)
        }
        val thisEvents = updateOnBrowserEvents
        updateOnBrowserEvents = false
        dispatch(SetGenomeGenus(genomeGenusSelect.value.toInt()))
        updateOnBrowserEvents = thisEvents
    }


    private fun updateGenus(state: ForgeState) {
        if (genomeGenusSelect.getBoolean("data-user-selected", false)) {
            return
        }
        val thisEvents = updateOnBrowserEvents
        updateOnBrowserEvents = false
        if (genomeGenusSelect.value != state.genomeGenus.toString()) {
            genomeGenusSelect.value = state.genomeGenus.toString()
        }
        updateOnBrowserEvents = thisEvents || updateOnBrowserEvents
    }


    private fun setGenusOptions(select: HTMLSelectElement) {
        val genera = listOf(
            "0" to "Norn",
            "1" to "Grendel",
            "2" to "Ettin",
            "3" to "Geat"
        )
        for ((genusInt, label) in genera) {
            val option = (document.createElement("option") as HTMLOptionElement).apply {
                this.value = genusInt
                this.innerText = label
            }
            select.appendChild(option)
        }
        select.value = "0"
    }

    override fun isValid(): Boolean {
        return genomeGenusSelect.value.toIntOrNull() in 0 until 3
    }

    override fun highlightErrors() {
        if (isValid()) {
            return
        }
        genomeGenusSelect.closest(".validatable-input-container")?.setAttribute("data-is-value", "false")
    }

}