@file:Suppress("unused")

package com.bedalton.creatures.caos.collectors

import com.bedalton.common.ast.serialization.PositionSerializer
import com.bedalton.common.ast.structs.Position
import com.bedalton.common.ast.structs.RangeWithIndex
import com.bedalton.common.ast.structs.toPosition
import com.bedalton.creatures.caos.utils.token
import kotlinx.serialization.Serializable
import org.antlr.v4.kotlinruntime.Token
import kotlin.js.JsExport
import kotlin.js.JsName


@JsExport
@JsName("BlockRange")
@Serializable
data class BlockRange(
    @JsName("startToken")
    val startToken:String?,
    @JsName("endToken")
    val endToken:String?,
    override val startIndex: Int,
    override val endIndex: Int,
    @Serializable(with = PositionSerializer::class)
    override val start: Position,
    @Serializable(with = PositionSerializer::class)
    override val end: Position,
    override val parserIndex: Int?,
    val depth:Int,
) : RangeWithIndex {

    val startTok:Int? by lazy {
        startToken?.let { token(it) }
    }

    val endTok:Int? by lazy {
        endToken?.let { token(it) }
    }

    @JsName("rangeWithStartEndToken")
    internal constructor(startToken:String?, endToken:String?, start: Token, end: Token, parserIndex: Int?, depth: Int) : this(
        startToken = startToken,
        endToken = endToken,
        startIndex = start.startIndex,
        endIndex = end.stopIndex + 1,
        start = start.toPosition(),
        end = end.toPosition(),
        parserIndex,
        depth = depth
    )
    @JsName("rangeWithStartEndRange")
    internal constructor(
        startToken: String?,
        endToken: String?,
        start: RangeWithIndex,
        end: RangeWithIndex,
        parserIndex: Int?,
        depth: Int
    ) : this(
        startToken = startToken,
        endToken = endToken,
        startIndex = start.startIndex,
        endIndex = end.endIndex + 1,
        start = start.start,
        end = end.end,
        parserIndex,
        depth = depth
    )

    internal constructor(startToken: String?, endToken: String?, range: RangeWithIndex, parserIndex: Int?, depth: Int): this(
        startToken = startToken?.lowercase(),
        endToken = endToken?.lowercase(),
        startIndex = range.startIndex,
        endIndex = range.endIndex,
        start = range.start,
        end = range.end,
        parserIndex,
        depth = depth
    )
}

