package com.creaturesforge.application.state

import com.bedalton.common.structs.DataCache
import com.bedalton.common.util.PathUtil
import com.bedalton.common.util.nullIfEmpty
import com.bedalton.creatures.common.structs.BreedKey
import com.creaturesforge.application.compile.CompileData
import korlibs.io.concurrent.atomic.KorAtomicInt
import korlibs.io.concurrent.atomic.incrementAndGet
import korlibs.io.concurrent.atomic.korAtomic
import kotlinx.serialization.Serializable
import kotlinx.serialization.Transient

@Serializable
internal data class ForgeState(
    val virtual: Boolean = false,
    val projectFolder: String? = null,
    val lastFileName: String? = null,
    val lastSaveDirectory: String? = null,
    val breedSlot: BreedSlot? = null,
    val eggs: List<EggData> = listOf(EggData()),
    val genomeGenus: Int = 0,
    val maleGlyph: Glyph? = null,
    val femaleGlyph: Glyph? = null,
    val outputFile: String? = null,
    val lastGenomePath: String? = null,
    val spriteRoot: String? = null,
    val spriteSlot: BreedSlot? = null,
    val spriteFiles: List<String>? = null,
    val attRoot: String? = null,
    val attFiles: List<String>? = null,
    val attSlot: BreedSlot? = null,
    val selectedEgg: EggData = eggs[0],
    val eggMode: EggMode = EggMode.SINGLE,
    val additionalGenomes: Map<String, String> = emptyMap(),
    @Transient
    val lastStateId: KorAtomicInt = korAtomic(0),
) {

    val stateId: Int by lazy {
        lastStateId.incrementAndGet()
    }

    private val isSingleEggMode: Boolean get() = eggMode == EggMode.SINGLE

    internal val outputBreedSlot: BreedSlot? by lazy {
        if (isSingleEggMode) {
            spriteSlot ?: breedSlot
        } else {
            breedSlot ?: spriteSlot
        }
    }

    internal val spriteBreedSlot: BreedSlot? by lazy {
        if (isSingleEggMode) {
            spriteSlot ?: breedSlot
        } else {
            spriteSlot ?: breedSlot
        }
    }

    internal val attBreedSlot: BreedSlot? by lazy {
        if (isSingleEggMode) {
            spriteSlot ?: attSlot ?: breedSlot
        } else {
            attSlot ?: spriteSlot ?: breedSlot
        }
    }

    @Transient
    private var mCompileData: CompileData? = null

    fun getAvailableSpriteSlots(): Set<BreedSlot> {
        return getAvailableBreedSlots(spriteFiles)
    }

    fun getAvailableAttSlots(): Set<BreedSlot> {
        return getAvailableBreedSlots(attFiles)
    }

    internal fun toCompileData(glyphsNotNull: Boolean = true, outputFile: String): CompileData {
        mCompileData?.also {
            return if (it.outputFile == outputFile) {
                it
            } else {
                it.copy(outputFile = outputFile)
            }
        }
        return CompileData.create(this, glyphsNotNull, outputFile).also {
            mCompileData = it
        }
    }

    fun fileNameOrDefault(): String? {
        lastFileName?.let {
            return it
        }
        val allNames = eggs.mapNotNull { it.eggName }
            .nullIfEmpty()
            ?: return null
        allNames.singleOrNull()?.let {
            return it + " Eggs"
        }
        val namesWithoutBase = allNames.map(AutoNamesHelper::stripGenomeInitials)

        namesWithoutBase.singleOrNull()?.let {
            return it + " Eggs"
        }

        return (mostSimilarName(allNames)
            ?: mostSimilarName(namesWithoutBase))?.let {
            it + " Eggs"
        }
    }

    private fun mostSimilarName(names: List<String>, forward: Boolean = true): String? {
        if (names.isEmpty()) {
            return null
        }
        var out = ""
        val base = names.first()
        if (forward) {
            for (char in base) {
                if (!names.all { it.startsWith(out + char) }) {
                    break
                }
                out += char
            }
        } else {
            for (char in base) {
                if (!names.all { it.endsWith(char + out) }) {
                    break
                }
                out = char + out
            }
        }

        val minimumLength = names.minOf { it.length } * 0.6
        return if (out.length > minimumLength) {
            out
        } else if (forward) {
            mostSimilarName(names, false)
        } else {
            null
        }
    }

    fun ensureEgg(): ForgeState {
        if (eggs.isNotEmpty()) {
            return this
        }
        val egg = selectedEgg
        return copy(
            eggs = listOf(egg)
        )
    }

    val stats: DataCache<List<CompileData.AgeGenderStats>> by lazy {
        DataCache {
            StatsUtil.getStats(this)
        }
    }

    companion object {

        fun getAvailableBreedSlots(files: List<String>?): Set<BreedSlot> {

            if (files.isNullOrEmpty()) {
                return emptySet()
            }

            return files
                .mapNotNull {
                    BreedKey.fromFileName(PathUtil.getFileNameWithoutExtension(it) ?: it)
                        ?.copyWithAgeGroup(null)
                        ?.copyWithGender(null)
                }
                .distinct()
                .mapNotNull map@{
                    val genus = it.genus
                        ?: return@map null
                    val breed = it.breed
                        ?: return@map null
                    BreedSlot(genus, breed)
                }
                .toSet()
        }
    }
}