@file:Suppress("unused")

package com.bedalton.creatures.sprite.compilers

import com.bedalton.creatures.common.structs.GameVariant
import com.bedalton.creatures.sprite.util.ColorEncoding
import com.bedalton.creatures.sprite.util.ColorPalette
import com.bedalton.creatures.sprite.util.ColorPalette.Companion.C1OpaqueBlack
import com.bedalton.creatures.sprite.util.ColorPalette.Companion.C1TransparentBlack
import com.bedalton.creatures.sprite.util.PaletteTransform
import com.bedalton.io.bytes.ByteStreamWriter
import korlibs.image.bitmap.Bitmap32
import korlibs.image.color.RGBA

@Suppress("MemberVisibilityCanBePrivate")
object SprCompiler : SpriteCompiler {
    private const val HEADER_NUM_IMAGES_SIZE = 2
    private const val IMAGE_HEADER_SIZE = 8
    private const val PERFECT_WHITE = 10

    private val solidBlack by lazy {
        (1..255).first { i ->
            C1TransparentBlack[i].let {
                it.r == 0 && it.g == 0 && it.b == 0
            }
        }
    }


    @Deprecated("Use with keepBlack parameter", ReplaceWith("compileSpriteFromImageBytes(images, false, colorEncoding, callback"))
    override fun compileSpriteFromImageBytes(images: List<Pair<String, ByteArray>>, colorEncoding: ColorEncoding?, callback: ((pass: Int, current: Int, total: Int) -> Boolean?)?): ByteArray {
        return compileSpriteFromImageBytes(images, false, colorEncoding, callback)
    }

    @Deprecated("Use with keepBlack parameter", ReplaceWith("compileSpriteFromImageBytes(images, false, colorEncoding, callback"))
    override fun compileSpriteFromLoadedImages(images: List<Bitmap32>, colorEncoding: ColorEncoding?, callback: ((current: Int, total: Int) -> Boolean?)?): ByteArray {
        return compileSpriteFromLoadedImages(images, false, colorEncoding, callback)
    }

    private fun compareColors(colorA: RGBA, red: Int, green: Int, blue: Int): Int {
        return (red - colorA.r)*(red - colorA.r) +
                (green - colorA.g) * (green - colorA.g) +
                (blue - colorA.b) * (blue - colorA.b)
    }

    internal fun getColorIndex(palette: ColorPalette, red: Int, green: Int, blue: Int, allowBlack: Boolean): Int {
        var selectedColor = 0
        var deviation: Int = Int.MAX_VALUE

        if (red > 248 && green > 248 && blue > 248) {
            return PERFECT_WHITE
        }
        if (red == 0 && green == 0 && blue == 0) {
            return if (allowBlack) {
                solidBlack
            }else {
                0
            }
        }
        for (i in 1 until 236) {
            val currentDeviation = compareColors(palette[i], red, green, blue)
            if (currentDeviation < deviation) {
                deviation = currentDeviation
                selectedColor = i
            }
        }
        return selectedColor
    }

    override fun compileSpriteFromImageBytes(
        images: List<Pair<String, ByteArray>>,
        keepBlack: Boolean,
        colorEncoding: ColorEncoding?,
        paletteTransform: PaletteTransform?,
        callback: ((pass: Int, current: Int, total: Int) -> Boolean?)?,
    ): ByteArray {
        val bitmaps = ImageLoader.loadMany(images) { current, total ->
            if (callback?.invoke(1, current, total) == false) {
                throw SpriteCompilerCancelledException("Cancelled SPR compilation during image loading phase")
            }
            true
        }
        return compileSpriteFromLoadedImages(bitmaps, keepBlack, colorEncoding, paletteTransform) { current, total ->
            callback?.invoke(2, current, total)
        }
    }

    override fun compileSpriteFromLoadedImages(
        images: List<Bitmap32>,
        keepBlack: Boolean,
        colorEncoding: ColorEncoding?,
        paletteTransform: PaletteTransform?,
        callback: ((current: Int, total: Int) -> Boolean?)?,
    ): ByteArray {
        var palette = if (keepBlack) C1OpaqueBlack else C1TransparentBlack
        if (paletteTransform != null) {
            palette = palette.transform(paletteTransform.copy(gameVariant = GameVariant.C1), ColorEncoding.ENCODING_DEFAULT)
        }
        return compileSpriteFromLoadedImages(palette, images, keepBlack, callback)
    }

    fun compileSpriteFromLoadedImages(
        palette: ColorPalette,
        images: List<Bitmap32>,
        keepBlack: Boolean,
        callback: ((current: Int, total: Int) -> Boolean?)?,
    ): ByteArray {
        val actualCallback: ((current: Int, total: Int) -> Boolean?)? = callback?.let { it ->
            { current: Int, total: Int ->
                if (it(current, total) == false) {
                    throw SpriteCompilerCancelledException("SPR compilation cancelled during compiler phase")
                }
                true
            }
        }

        return ByteStreamWriter.writeBytes {
            var imageOffset = HEADER_NUM_IMAGES_SIZE + (images.size * IMAGE_HEADER_SIZE)
            writeUInt16(images.size)
            for (image in images) {
                writeUInt32(imageOffset)
                val width = image.width
                val height = image.height
                writeUInt16(width)
                writeUInt16(height)
                imageOffset += width * height
            }
            val imagesCount = images.size
            actualCallback?.invoke(0, imagesCount)
            var i = 0
            for (image in images) {
                writeCompiledImage(palette, image, keepBlack, this)
                actualCallback?.invoke(++i, imagesCount)
            }
//            writeUInt8(0)
        }
    }

    fun writeCompiledImage(image: Bitmap32, keepBlack: Boolean, buffer: ByteStreamWriter) {
        val palette = C1TransparentBlack
        return writeCompiledImage(palette, image, keepBlack, buffer)
    }

    fun writeCompiledImage(palette: ColorPalette, image: Bitmap32, keepBlack: Boolean, buffer: ByteStreamWriter) {
        val alphaCutoff = programAlphaCutoff
        val width = image.width
        val height = image.height
        val black = if (keepBlack) {
            solidBlack
        } else {
            0
        }
        for (y in 0 until height) {
            for (x in 0 until width) {
                val pixel = image[x, y]
                val alpha: Int = pixel.a
                if (alpha < alphaCutoff) {
                    buffer.writeUInt8(0)
                } else {
                    val red: Int = pixel.r
                    val green: Int = pixel.g
                    val blue: Int = pixel.b
                    val color = if (red + green + blue == 0)
                        black
                    else {
                        val subFrom: Int = maxOf(0,arrayOf(255 - alpha, red - 2, green - 2, blue - 2).minOrNull()!!)
                        getColorIndex(palette, red - subFrom, green - subFrom, blue - subFrom, keepBlack)
                    }
                    buffer.writeUInt8(color)
                }
            }
        }
    }
}