package com.creaturesforge.application.ui.html

import kotlinx.browser.document
import org.w3c.dom.Element

internal inline fun <T: Element> element(tag: String, init: T.()->Unit): T {
    val t = document.createElement(tag).unsafeCast<T>()
    t.init()
    return t
}

val body by lazy {
    document.body!!
}