@file:Suppress("unused")

package com.bedalton.creatures.agents.pray.data

import com.bedalton.creatures.agents.pray.internal.SCRIPT_TAG_REGEX


/**
 * Gets the agents default description if any
 */
val BlockWithTags.description: String? get() = stringTags.getString("Agent Description", true)

/**
 * Attempts to get a description by its language code
 * Returns null if it does not exist
 */
fun BlockWithTags.localizedDescription(languageCode: String): String? =
    stringTags.getString("Agent Description-$languageCode", true)


// Regex for descriptions with or without localization
private val descriptionRegex = "^Agent Description(-[A-Za-z]{2})?$".toRegex()

/**
 * Gets all localized and default description
 */
val BlockWithTags.localizedDescriptions: Map<String, String>
    get() = stringTags
        .mapNotNull map@{
            val groups = descriptionRegex
                .matchEntire(it.tag)
                ?.groupValues
                ?: return@map null
            (groups.getOrNull(1)?.lowercase() ?: "en") to it.value
        }
        .toMap()

val BlockWithTags.scriptCount: Int get() = stringTags.scripts().size

/**
 * Gets all scripts paired with their tag index
 */
val BlockWithTags.scripts: List<Pair<Int, String>>
    get() = stringTags
        .scripts()
        .mapNotNull {
            try {
                SCRIPT_TAG_REGEX.matchEntire(it.tag)!!.groupValues[1].toInt() to it.value
            } catch (e: Exception) {
                null
            }
        }

/**
 * Gets a specific script in this agent
 */
fun AgentBlock.getScript(index: Int): String? {
    val key = "[Ss]cript\\s+$index".toRegex()
    return stringTags.firstOrNull { key.matches(it.tag) }?.value
}

/**
 * Gets dependency count if any, or 0 if tag is missing
 */
val BlockWithTags.dependencyCount: Int
    get() {
        return intTags.getInt("Dependency Count") ?: 0
    }

/**
 * Attempts to get all dependencies indexed
 */
val BlockWithTags.dependencies: Map<Int, Pair<String?, Int?>>
    get() {
        val count = dependencyCount
        if (count == 0) {
            return emptyMap()
        }
        return (1..count).associateWith { i ->
            val category = intTags.getInt("Dependency Category $i")
            val name = stringTags.getString("Dependency $i")
            (name to category)
        }
    }

/**
 * Attempts to get a dependency by index
 */
fun BlockWithTags.getDependency(i: Int): Pair<String?, Int?>? {
    val category = intTags.getInt("Dependency Category $i")
    val name = stringTags.getString("Dependency $i")
    if (category == null && name == null) {
        return null
    }
    return name to category
}

val AgentBlock.removeScript: String?
    get() = stringTags.getString("Remove script", fuzzy = true)

/**
 * Gets the file used for the animation of the agent on the C3 Creator/DS injector
 */
val AgentBlock.agentAnimationFile: String?
    get() = stringTags.getString("Agent Animation File")

/**
 * Gets the filename (excluding extension) used for the
 * animation of the agent on the C3 Creator/DS injector
 */
val AgentBlock.agentAnimationGallery: String?
    get() = stringTags.getString("Agent Animation Gallery")

/**
 *
 */
val AgentBlock.agentAnimationFirstImage: Int?
    get() = intTags.getInt("Animation Sprite First Image")

val AgentBlock.agentAnimationString: String?
    get() = stringTags.getString("Agent Animation String")