package com.bedalton.creatures.agents.pray.compiler.caos2pray.internal

import com.bedalton.common.coroutines.BackgroundDispatcher
import com.bedalton.common.structs.HasRange
import com.bedalton.creatures.agents.pray.compiler.NEWLINE_REGEX
import com.bedalton.creatures.agents.pray.compiler.SCRIPT_TAG_REGEX
import com.bedalton.creatures.agents.pray.compiler.caos2pray.Caos2PrayCommands
import com.bedalton.creatures.agents.pray.compiler.caos2pray.CommandValue
import com.bedalton.creatures.agents.pray.compiler.data.Tag
import com.bedalton.creatures.agents.pray.compiler.data.TextValue
import com.bedalton.creatures.agents.pray.compiler.getLinkFilenameReferenceFromCaosText
import com.bedalton.creatures.agents.pray.compiler.getLinkFilenameReferenceText
import com.bedalton.creatures.agents.pray.compiler.pray.PrayValidationError
import com.bedalton.creatures.agents.util.RelativeFileSystem
import com.bedalton.log.LOG_PROGRESS
import com.bedalton.log.Log
import com.bedalton.log.iWith
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.async
import kotlinx.coroutines.awaitAll


/**
 * Process Scripts and links and return
 */
internal suspend fun processLinks(
    coroutineScope: CoroutineScope,
    fs: RelativeFileSystem,
    fullFilePath: String,
    commands: List<CommandValue>,
    tags: List<Tag<*>>,
    mergeScripts: Boolean,
    errors: MutableList<PrayValidationError>,
    linkWithFilenameReference: Boolean
): List<Tag.StringTag> {
    var index = 1

    // Get all link commands
    val links = commands
        .filter { it.command == Caos2PrayCommands.LINK }
        .flatMap { command ->
            command.values.map {
                Pair(command, it)
            }
        }

    // Get all script tags
    val scriptTagCount = tags.filterIsInstance<Tag.StringTag>()
        .count { SCRIPT_TAG_REGEX.matches(it.tag) }


    // Determine total number of script tags to process
    val linksCount = links.size + scriptTagCount

    // Logger for Progress if needed by calling app
    val log: (index: Int, fileName: String) -> Unit = if (Log.hasMode(LOG_PROGRESS)) {
        { i, fileName ->
            Log.iWith(LOG_PROGRESS, replace = true) { "Linking file $i of $linksCount -> $fileName" }
        }
    } else {
        { _, _ -> }
    }

    // Get re-indexed script files
    val indexedScripts = tags.filterIsInstance<Tag.StringTag>()
        .filter { SCRIPT_TAG_REGEX.matches(it.tag) }
        .map { tag ->
            updateScriptIndexInTagName(
                fs,
                tag,
                index++,
                mergeScripts,
                log,
            )
        }.apply {
            Log.iWith(LOG_PROGRESS, replace = true) { "Linked $index CAOS script files\n" }
        }

    // Get scripts from all linked files
    val linked = links
        .asSequence()
        .map out@{ (command, fileName) ->
            coroutineScope.async(BackgroundDispatcher) {
                link(fs, fullFilePath, mergeScripts, fileName, command, errors, linkWithFilenameReference)
                    ?.apply {
                        log(++index, fileName.text)
                    }
            }
        }
        .toList()
        .awaitAll()
        .filterNotNull()

    // Get non-link, non-script tags
    val rawTags = tags.filterIsInstance<Tag.LinkTag>()
        .asSequence()
        .map out@{ tag ->
            coroutineScope.async(BackgroundDispatcher) {
                link(fs, fullFilePath, mergeScripts, tag.valueRange, tag, errors, linkWithFilenameReference)?.apply {
                    log(++index, tag.value)
                }
            }
        }
        .toList()
        .awaitAll()
        .filterNotNull()


    // Return all reformatted string tags
    return indexedScripts + linked + rawTags
}

private suspend fun link(
    fs: RelativeFileSystem,
    fullFilePath: String,
    mergeScripts: Boolean,
    fileName: TextValue?,
    errorRange: HasRange,
    errors: MutableList<PrayValidationError>,
    linkWithFilenameReference: Boolean
): Tag.StringTag? {
    if (fileName == null) {
        val errorMessage = "@ link file name was blank"
        val error = PrayValidationError.CommandError(
            command = "@",
            commandRange = errorRange,
            message = errorMessage,
            errorRange = errorRange,
            fullFilePath = fullFilePath,
        )
        errors.add(error)
        return null
    }
    if (!fs.fileExists(fileName.text)) {
        val errorMessage = "Linked CAOS file: ${fs.path(fileName.text)} does not exist"
        val error = PrayValidationError.CommandError(
            command = "LINK",
            commandRange = errorRange,
            message = errorMessage,
            errorRange = fileName,
            fullFilePath = fullFilePath,
        )
        errors.add(error)
        return null
    }
    val text = (fs.readAsText(fileName.text)).replace(
        NEWLINE_REGEX, "\n"
    )
    val prefix = if (mergeScripts) {
        "* Link \"${fileName.text}\"\n"
    } else if (linkWithFilenameReference && getLinkFilenameReferenceFromCaosText(text) == null) {
        getLinkFilenameReferenceText(fileName.text)
    } else {
        ""
    }
    return Tag.StringTag(
        lineNumber = errorRange.lineNumber,
        startIndex = errorRange.startIndex,
        endIndex = errorRange.endIndex,
        tagRange = TextValue(
            text = "Script ???",
            lineNumber = fileName.lineNumber,
            startIndex = fileName.startIndex,
            endIndex = fileName.endIndex
        ),
        value = TextValue(
            text = prefix + text,
            lineNumber = fileName.lineNumber,
            startIndex = fileName.startIndex,
            endIndex = fileName.endIndex,
        )
    )
}


/**
 * Update script index if supplied explicitly
 *
 * @param fs file system for reading files
 * @param tag pray script string tag
 * @param index script index
 * @param mergeScripts whether to merge scripts
 * @param log logging function
 * @return script string tag with updated script number (i.e. "Script 2")
 */
private suspend fun updateScriptIndexInTagName(
    fs: RelativeFileSystem,
    tag: Tag.StringTag,
    index: Int,
    mergeScripts: Boolean,
    log: (index: Int, tag: String) -> Unit,
): Tag.StringTag {
    return if (tag.tag == "Script 99999999") {
        Tag.StringTag(
            lineNumber = tag.lineNumber,
            startIndex = tag.startIndex,
            endIndex = tag.endIndex,
            tagRange = TextValue(
                "Script $index",
                lineNumber = tag.lineNumber,
                startIndex = tag.startIndex,
                endIndex = tag.endIndex
            ),
            value = tag.valueRange
                .copy(
                    text = tag.valueRange.text.replace(NEWLINE_REGEX, "\n")
                )
        )
    } else {
        val scriptHeader = if (mergeScripts)
            "* Script ${SCRIPT_TAG_REGEX.matchEntire(tag.tag)!!.groupValues[1]} @ \"${tag.value}\"\n"
        else
            ""
        log(index, tag.value)
        val text = (scriptHeader + fs.readAsText(tag.value)).replace(NEWLINE_REGEX, "\n")
        Tag.StringTag(
            lineNumber = tag.lineNumber,
            startIndex = tag.startIndex,
            endIndex = tag.endIndex,
            tagRange = TextValue(
                "Script $index",
                lineNumber = tag.lineNumber,
                startIndex = tag.startIndex,
                endIndex = tag.endIndex,
            ),
            value = tag.valueRange
                .copy(
                    text = text
                )
        )
    }
}