package com.bedalton.creatures.agents.pray.compiler.caos2pray

import com.bedalton.creatures.agents.pray.compiler.data.TextValue

/**
 * Represents an agent name in CAOS2Pray or standard Pray files
 *
 * @param lineNumber the number in file on which this agent name is defined
 * @param agentTag block name for this agent name. (i.e. AGNT, DSAG, EGGS)
 * @param agentName name of agent for block
 */
internal data class AgentName(
    val lineNumber: Int,
    val agentTag: TextValue,
    val agentName: TextValue,
)