package com.creaturesforge.application.ui.html

import com.bedalton.common.util.toFixed
import kotlinx.html.*


internal var Tag.id: String?
    get() = attributes["id"]
    set(value) {
        if (value == null) {
            attributes.remove("id")
        } else {
            attributes["id"] = value
        }
    }


internal fun Tag.attribute(attribute: String, value: String?) {
    if (value == null) {
        attributes.remove(attribute)
    } else {
        attributes[attribute] = value
    }
}

internal fun Tag.attribute(attribute: String, value: Boolean?) {
    if (value == null) {
        attributes.remove(attribute)
    } else {
        attributes[attribute] = value.toString()
    }
}


internal fun Tag.attribute(attribute: String, value: Int?) {
    if (value == null) {
        attributes.remove(attribute)
    } else {
        attributes[attribute] = value.toString()
    }
}

internal fun Tag.attribute(attribute: String, value: Long?) {
    if (value == null) {
        attributes.remove(attribute)
    } else {
        attributes[attribute] = value.toString()
    }
}

internal fun Tag.attribute(attribute: String, value: Float?, precision: Int? = null) {
    if (value == null) {
        attributes.remove(attribute)
    } else if (precision != null) {
        attributes[attribute] = value.toFixed(precision)
    } else {
        attributes[attribute] = value.toString()
    }
}

internal fun Tag.attribute(attribute: String, value: Double?, precision: Int? = null) {
    if (value == null) {
        attributes.remove(attribute)
    } else if (precision != null) {
        attributes[attribute] = value.toFixed(precision)
    } else {
        attributes[attribute] = value.toString()
    }
}




internal var Tag.ariaLabelledBy: String?
    get() = attributes["aria-labelledby"]
    set(value) { attribute("aria-labelledby", value) }



internal var Tag.ariaLabel: String?
    get() = attributes["aria-label"]
    set(value) { attribute("aria-label", value) }


internal var Tag.ariaHidden: Boolean?
    get() = attributes["aria-hidden"]?.toBooleanStrictOrNull()
    set(value) { attribute("aria-label", value) }


internal fun TH.columnHeader() {
    role = "columnheader"
    scope = ThScope.col
}

internal fun TH.rowheader() {
    role = "rowheader"
    scope = ThScope.row
}

internal fun TR.row() {
    role = "row"
}