@file:Suppress("ClassName", "FunctionName")

import com.bedalton.common.ast.formatter.CaosFormatterOptions
import com.bedalton.common.ast.serialization.CaosFormatterOptionsSerializer
import com.bedalton.creatures.caos.libs.caosJsonSerializer
import kotlinx.serialization.json.decodeFromDynamic
import kotlinx.serialization.json.encodeToDynamic


/**
 * Formats a CAOS document using variant and options
 */
@JsName("formatCaos")
@JsExport
fun formatCaos_JsApi(
    variant: String,
    text: String,
    options: dynamic = null,
): dynamic /*FormatResult*/ {
    val opts = asFormatterOptions(options)
    val result = com.bedalton.creatures.caos.formatter.format(variant, text, opts)
    return caosJsonSerializer.encodeToDynamic(result)
}


private fun asFormatterOptions(options: dynamic): CaosFormatterOptions? {
    if (options == null) {
        return null
    }
    return when (options) {
        is CaosFormatterOptions -> return options.unsafeCast<CaosFormatterOptions>()
        else -> caosJsonSerializer.decodeFromDynamic(CaosFormatterOptionsSerializer, options)
    }
}