package com.bedalton.vfs

import com.bedalton.common.util.expandTilde


/**
 * Checks if a file is a linux file system support file beginning with "._"
 */
@Suppress("PrivatePropertyName")
private val UNIX_FILE_SYSTEM_FILE_REGEX = ".*/\\._.*".toRegex()


/**
 * Simple test to see if a file is a file system support file that should not be read
 */
private fun isOSFileSystemFileInformationFile(file: String): Boolean {
    return file.endsWith("/.DS_Store") || file == ".DS_Store" || file.matches(UNIX_FILE_SYSTEM_FILE_REGEX)
}

/**
 * Filters out file system support files like .DS_Store on macOS, or ._{filename} on linux
 */
fun filterFileSystemFileInformationFiles(files: List<String>): List<String> {
    return files.filterNot(::isOSFileSystemFileInformationFile)
}

fun String.expandTildeIfNecessary(): String {
    return if (this.startsWith("~/")) {
        expandTilde(this)
    } else {
        this
    }
}