package com.bedalton.creatures.caos.utils

import com.bedalton.common.ast.hints.InlayHintImpl
import com.bedalton.common.ast.serialization.*
import com.bedalton.common.ast.structs.*
import com.bedalton.creatures.caos.collectors.*
import kotlinx.serialization.SerializationStrategy
import kotlinx.serialization.modules.SerializersModule
import kotlinx.serialization.modules.SerializersModuleBuilder
import kotlinx.serialization.modules.polymorphic
import kotlinx.serialization.modules.subclass

val caosSerializersModule = SerializersModule {
    argument()
    range()
    point()
    textWithRange()
    hasRange()
    documentSymbol()
    inlayHint()
}


private fun SerializersModuleBuilder.argument() {

    polymorphicDefaultSerializer(Argument::class) {
        @Suppress("UNCHECKED_CAST")
        when(it) {
            is CommandCallJs -> CommandCallJs.serializer() as SerializationStrategy<Argument>
            is CommandCall -> CommandCall.serializer() as SerializationStrategy<Argument>
            is EqualityStatement -> EqualityStatement.serializer() as SerializationStrategy<Argument>
            is ParserItemArgument -> ParserItemArgument.serializer() as SerializationStrategy<Argument>
            is CaosParserItem.EqOp -> CaosParserItem.EqOp.serializer() as SerializationStrategy<Argument>
            else -> null
        }
    }
    polymorphic(Argument::class) {
        subclass(CommandCallJs::class)
        subclass(CommandCall::class)
        subclass(EqualityStatement::class)
        subclass(ParserItemArgument::class)
        subclass(CaosParserItem.EqOp::class)
    }
}

private fun SerializersModuleBuilder.range() {

    polymorphicDefaultSerializer(Range::class) { instance ->
        @Suppress("UNCHECKED_CAST")
        when(instance) {
            is BlockRange -> BlockRange.serializer() as SerializationStrategy<Range>
            is RangeWithIndexImpl -> RangeWithIndexImpl.serializer() as SerializationStrategy<Range>
            is RangeWithIndex -> RangeWithIndexSerializer as SerializationStrategy<Range>
            else -> null
        }
    }
    polymorphic(Range::class) {
        subclass(BlockRange::class)
        subclass(RangeWithIndexImpl::class)
        this.defaultDeserializer {
            RangeSerializer
        }
    }
}

private fun SerializersModuleBuilder.hasRange() {
    polymorphicDefaultSerializer(HasRange::class) { instance ->
        @Suppress("UNCHECKED_CAST")
        when (instance) {
            is CommandCallJs -> CommandCallJs.Companion.serializer() as SerializationStrategy<HasRange>
            is CommandCall -> CommandCall.serializer() as SerializationStrategy<HasRange>
            is EqualityStatement -> EqualityStatement.serializer() as SerializationStrategy<HasRange>
            is TextWithRangeImpl -> TextWithRangeImpl.serializer() as SerializationStrategy<HasRange>
            is TextWithRange -> TextWithRangeSerializer as SerializationStrategy<HasRange>
            is HasRangeImpl -> HasRangeImpl.serializer() as SerializationStrategy<HasRange>
            is ParserItemArgument -> ParserItemArgument.serializer() as SerializationStrategy<HasRange>
            is CaosParserItem -> CaosParserItem.serializer() as SerializationStrategy<HasRange>
            else -> null
        }
    }
    polymorphic(HasRange::class) {
        subclass(CommandCallJs::class)
        subclass(CommandCall::class)
        subclass(EqualityStatement::class)
        subclass(TextWithRangeImpl::class)
        subclass(ParserItemArgument::class)
        this.defaultDeserializer {
            HasRangeSerializer
        }
    }
}

private fun SerializersModuleBuilder.point() {
    polymorphicDefaultSerializer(Position::class) { instance ->
        @Suppress("UNCHECKED_CAST")
        when (instance) {
            is PositionImpl -> PositionImpl.serializer() as SerializationStrategy<Position>
            else -> null
        }
    }
    polymorphic(Position::class) {
        subclass(PositionImpl::class)
        this.defaultDeserializer {
            PositionSerializer
        }
    }
}

private fun SerializersModuleBuilder.textWithRange() {

    polymorphic(TextWithRange::class) {
        defaultDeserializer {
            TextWithRangeSerializer
        }
    }
}

private fun SerializersModuleBuilder.documentSymbol() {
    polymorphic(DocumentSymbol::class) {
        subclass(DocumentSymbolImpl::class)
        defaultDeserializer {
            DocumentSymbolImpl.serializer()
        }
    }
}

private fun SerializersModuleBuilder.inlayHint() {
    polymorphic(InlayHint::class) {
        subclass(InlayHintImpl::class)
        defaultDeserializer {
            InlayHintSerializer
        }
    }
}