package com.bedalton.creatures.breed.render.support.render

import com.bedalton.common.structs.HasSize
import com.bedalton.common.structs.Size
import com.bedalton.creatures.breed.render.support.att.AttFileData
import com.bedalton.creatures.breed.render.support.att.PoseToAttLine
import com.bedalton.creatures.breed.render.support.pose.Pose
import com.bedalton.creatures.breed.render.support.pose.PoseRenderException


/**
 * Parsed Sprite and ATT data needed to render a part at any pose
 */
data class ParsedBodyPartRenderData<ImageT>(
    val part: Char,
    val frameInfo: List<HasSize>,
    val attData: AttFileData,
    var visibility: PartVisibility? = null,
    var onDispose: (() -> Unit)? = null,
    var get: (suspend (Int) -> ImageT?)?
) {

    @Suppress("unused")
    constructor(
        part: Char,
        frameInfo: List<HasSize>,
        attData: AttFileData,
        visibility: PartVisibility? = null,
        get: (suspend (Int) -> ImageT?)?
    ): this(
        part = part,
        frameInfo = frameInfo,
        attData = attData,
        visibility = visibility,
        onDispose = null,
        get = get
    )

    constructor(
        part: Char,
        images: List<ImageT>,
        frameInfo: List<HasSize>,
        attData: AttFileData,
        visibility: PartVisibility? = null
    ): this (
        part = part,
        frameInfo = frameInfo,
        attData = attData,
        visibility = visibility,
        onDispose = null,
        get = images::get
    )

    @Suppress("unused")
    constructor(
        part: Char,
        images: List<ImageT>,
        frameInfo: List<HasSize>,
        attData: AttFileData,
        dispose: (() -> Unit)? = null,
        visibility: PartVisibility? = null
    ): this (
        part = part,
        frameInfo = frameInfo,
        attData = attData,
        visibility = visibility,
        onDispose = dispose,
        get = images::get
    )

    suspend fun dataForPose(pose: Pose, trueSize: ((image: ImageT) -> Size)? = null): PoseRenderFrameData<ImageT> {

        val attLine = PoseToAttLine.getAttLine(pose, part, attData)
            ?: throw PoseRenderException("Cannot render without ATT line for part <${part}>")

        val poseSpriteIndex = pose.spriteIndex(part)
            ?: throw PoseRenderException("Cannot render without pose sprite index for part <${part}>")

        val get = get
            ?: throw PoseRenderException("Image getter already disposed")

        val image = get(poseSpriteIndex)
            ?: throw PoseRenderException("Missing image data for part <${part}>")


        val size = trueSize?.invoke(image) ?: frameInfo.getOrNull(poseSpriteIndex)
            ?: throw PoseRenderException("Cannot get render data without frame size for part <$part>")

        return PoseRenderFrameData(
            part = part,
            image = image,
            attFileLine = attLine,
            size = size,
            visibility = visibility,
        )
    }


    @Suppress("unused")
    fun dispose() {
        onDispose?.invoke()
        onDispose = null
        get = null
    }
}