/**
 * Gets the agents default description if any
 */
fun CompilerBlockWithTags.description(): String? = stringTags.getString("Agent Description", true)

/**
 * Attempts to get a description by its language code
 * Returns null if it does not exist
 */
fun CompilerBlockWithTags.localizedDescription(languageCode: String): String? =
    stringTags.getString("Agent Description-$languageCode", true)


// Regex for descriptions with or without localization
private val descriptionRegex = "^Agent Description(-[A-Za-z]{2})?$".toRegex()

/**
 * Gets all localized and default description
 */
fun CompilerBlockWithTags.localizedDescriptions(): Map<String, String> = stringTags
    .mapNotNull map@{
        val groups = descriptionRegex
            .matchEntire(it.tag)
            ?.groupValues
            ?: return@map null
        (groups.getOrNull(1)?.lowercase() ?: "en") to it.value
    }
    .toMap()

fun CompilerBlockWithTags.scriptCount(): Int = stringTags.scripts().size

/**
 * Gets all scripts paired with their tag index
 */
fun CompilerBlockWithTags.scripts(): List<Pair<Int, String>> = stringTags
    .scripts()
    .mapNotNull {
        try {
            SCRIPT_TAG_REGEX.matchEntire(it.tag)!!.groupValues[1].toInt() to it.value
        } catch (e: Exception) {
            // Do not hold onto cancellation exceptions
            e.rethrowIfCancellationException()
            null
        }
    }

/**
 * Gets all scripts paired with their tag index
 */
fun CompilerBlockWithTags.getScriptsNamespaced(prefix: String): List<Pair<String, Tag.StringTag>> {
    return stringTags
        .scripts()
        .mapNotNull {
            try {
                namespaceScript(prefix, it.tag) to it
            } catch (e: Exception) {
                // Do not hold onto cancellation exceptions
                e.rethrowIfCancellationException()
                null
            }
        }
}

/**
 * Gets a specific script in this agent
 */
fun CompilerAgentBlock.getScript(index: Int): String? {
    val key = "[Ss]cript\\s+$index".toRegex()
    return stringTags.firstOrNull { key.matches(it.tag) }?.value
}

/**
 * Gets a specific script in this agent
 */
fun CompilerBlockWithTags.getScriptNamespaced(prefix: String, tag: String): String? {
    return stringTags.firstOrNull { tag like namespaceValue(
        prefix,
        this.blockTag.text,
        it.tag
    )
    }?.value
}

internal fun CompilerPrayBlock.namespaceScript(prefix: String, tag: String): String {
    return namespaceValue(
        prefix,
        this.blockTag.text,
        this.blockName.text + '.' + tag + ".cos"
    )
}

/**
 * Gets dependency count if any, or 0 if tag is missing
 */
fun CompilerBlockWithTags.dependencyCount(): Int {
    return intTags.getInt("Dependency Count") ?: 0
}

/**
 * Attempts to get all dependencies indexed
 */
fun CompilerBlockWithTags.dependencies(): Map<Int, Pair<String?, Int?>> {
    val count = dependencyCount()
    if (count == 0) {
        return emptyMap()
    }
    return (1..count).associateWith { i ->
        val category = intTags.getInt("Dependency Category $i")
        val name = stringTags.getString("Dependency $i")
        (name to category)
    }
}

/**
 * Attempts to get a dependency by index
 */
fun CompilerBlockWithTags.getDependency(i: Int): Pair<String?, Int?>? {
    val category = intTags.getInt("Dependency Category $i")
    val name = stringTags.getString("Dependency $i")
    if (category == null && name == null) {
        return null
    }
    return name to category
}

fun CompilerAgentBlock.removeScript(): String? = stringTags.getString("Remove script", fuzzy = true)

/**
 * Gets the file used for the animation of the agent on the C3 Creator/DS injector
 */
fun CompilerAgentBlock.agentAnimationFile(): String? = stringTags.getString("Agent Animation File")

/**
 * Gets the filename (excluding extension) used for the
 * animation of the agent on the C3 Creator/DS injector
 */
fun CompilerAgentBlock.agentAnimationGallery(): String? = stringTags.getString("Agent Animation Gallery")

/**
 *
 */
fun CompilerAgentBlock.agentAnimationFirstImage(): Int? = intTags.getInt("Animation Sprite First Image")

fun CompilerAgentBlock.agentAnimationString(): String? = stringTags.getString("Agent Animation String")


fun namespaceValue(prefix: String, blockTag: String, value: String, isData: Boolean = false): String {
    if (value.isBlank()) {
        throw AgentFileDecompilerException("Cannot namespace empty value")
    }
    if (blockTag.isBlank() || isData || tok(blockTag) in NON_AGENT_TAG_BLOCKS) {
        return prefix + value
    }
    val blocked = "$blockTag.$value"
//        .replace("[^\\p{L}\\p{M}.\\-\\d]+".toRegex(), "-")
        .replace(WHITESPACE, "-")
        .replace("[\\-_.]+\\.".toRegex(), ".")
        .trim('.', '-', ' ')
    return prefix + blocked
}

fun namespaceValue(prefix: String, blockTag: TextValue, value: String, isData: Boolean = false): String {
    return namespaceValue(
        prefix,
        blockTag.text,
        value,
        isData
    )
}

fun namespaceValue(prefix: String, blockTag: TextValue, value: TextValue, isData: Boolean = false): String {
    return namespaceValue(
        prefix,
        blockTag.text,
        value.text,
        isData
    )
}