package com.creaturesforge.application.state

import com.bedalton.common.util.formatted
import com.bedalton.log.Log
import com.bedalton.state.simple.Dispatch

internal val alterSettingsMiddleware = alwaysNextMiddleware {
    state: ForgeState,
    action: FAction,
    dispatch: Dispatch< FAction> ->

    if (action !is AlterSettingsAction) {
        return@alwaysNextMiddleware
    }

    when (action) {

        is ClearAllPreviousGenomesFromAllTime -> {
            if (action.initiator) {
                ForgeConfig.clearAllPreviousGenomes()
            }
        }

        is SetDisablePreviousGenomeCaching -> {
            if (action.initiator) {
                ForgeConfig.setPreviousGenomeListDisabled(action.disable)
            }
        }

        is ToggleDisablePreviousGenomesLists -> {
            val disabled = ForgeConfig.isPreviousGenomeListDisabled()
            dispatch(SetDisablePreviousGenomeCaching(!disabled, action.initiator))
        }

        is SetDisableProjectDataCaching -> {
            if (action.initiator) {
                ForgeConfig.setProjectSettingsCacheDisabled(action.disable)
            }
        }

        is ToggleDisableProjectSettingsReload -> {
            val disabled = ForgeConfig.isProjectSettingsCacheDisabled()
            dispatch(SetDisableProjectDataCaching(!disabled, action.initiator))
        }


        is ClearSavedSettingsForAllProjects ->{
            if (!action.initiator) {
                return@alwaysNextMiddleware
            }
            ForgeConfig.clearCachedSettingsForAllProjects()
            dispatchProjectReset(state, dispatch)
        }


        is ResetProjectAndClearSavedSettings -> {
            val projectRoot = state.projectFolder
                ?: return@alwaysNextMiddleware

            try {
                ForgeConfig.clearProjectData(projectRoot)
            } catch (e: Exception) {
                Log.e("Failed to clear project data; ${e.formatted()}")
            }

            dispatchProjectReset(state, dispatch)
        }

        ClearPreviousGenomesListFromProject -> {
            ForgeConfig.clearProjectGenomes(state.projectFolder)
        }
    }
}


private fun dispatchProjectReset(state: ForgeState, dispatch: Dispatch<FAction>) {
    dispatch(
        SetStateAction(
            ForgeState(
                projectFolder = state.projectFolder
            )
        )
    )
}