package com.bedalton.vfs

import kotlinx.coroutines.await

actual suspend fun getCurrentWorkingDirectory(): String? {
    return tauri.path.runtimeDir().await().replace('\\', '/')
}

actual suspend fun getExecutableDirectory(): String? {
    return tauri.path.executableDir().await()
}

actual suspend fun applicationPath(): String? {
    return tauri.path.appDir().await()
}

suspend fun resourcePathOrPath(path: String): String {
    return if (path.trim().lowercase().startsWith("resource:")) {
        tauri.path.resolveResource(path.trim().replace("^resource:/?".toRegex(RegexOption.IGNORE_CASE), "")).await()
    } else {
        path
    }
}