@file:Suppress("unused")

package com.bedalton.creatures.breed.render.files

import com.bedalton.common.util.orFalse
import com.bedalton.creatures.breed.render.renderer.RenderValueOutOfRangeException
import com.bedalton.creatures.breed.render.support.pose.PoseRenderException
import com.bedalton.creatures.common.structs.GameVariant
import com.bedalton.creatures.common.structs.isC3DS
import com.bedalton.creatures.sprite.util.PaletteTransform
import kotlin.collections.set


data class BreedFiles(
    val gameVariant: GameVariant,
    val allFiles: Set<BreedFileData>,
    val spriteRoot: String? = null,
    val attRoot: String? = null,
    val paletteTransform: PaletteTransform? = null,
    val closeMatchOnly: Boolean?,
) {

    private var mPartFiles: MutableMap<Char, BreedPartFiles> = mutableMapOf()

    private val fileTypes by lazy {
        FileTypes(
            gameVariant,
            allFiles
        )
    }

    internal fun assertHasSpritesAndAtts() {
        fileTypes.assertHasSpritesAndAtts()
    }

    operator fun get(part: Char): BreedPartFiles {
        val partLower = part.lowercaseChar()
        if (partLower !in 'a'..'q') {
            throw RenderValueOutOfRangeException(
                "Invalid part char <$part> in get breed files",
                "part",
                part,
                "a", "q"
            )
        }
        mPartFiles[partLower]?.let {
            return it
        }
        val filesList = allFiles.filter {
            it.part == partLower
        }
        return BreedPartFiles(
            gameVariant,
            part,
            filesList,
            spriteRoot,
            attRoot,
            paletteTransform,
            closeMatchOnly
        ).also { files ->
            mPartFiles[partLower] = files
        }
    }

    fun withPaletteTransform(
        paletteTransform: PaletteTransform?,
    ): BreedFiles {
        val parent = this
        return copy().apply {
            this.mPartFiles = parent.mPartFiles
                .entries
                .associate {
                    it.key to it.value.withPaletteTransform(
                        paletteTransform
                    )
                }
                .toMutableMap()
        }
    }

    fun withAttRoot(
        attRoot: String?,
    ): BreedFiles {
        return withRoots(
            spriteRoot = this.spriteRoot,
            attRoot = attRoot
        )
    }

    fun withSpriteRoot(
        spriteRoot: String?,
    ): BreedFiles {
        return withRoots(
            spriteRoot = spriteRoot,
            attRoot = this.attRoot
        )
    }

    @Suppress("MemberVisibilityCanBePrivate")
    fun withRoots(
        spriteRoot: String? = this.spriteRoot,
        attRoot: String? = this.attRoot,
    ): BreedFiles {
        val parent = this
        return copy(
            attRoot = attRoot,
            spriteRoot = spriteRoot
        ).apply {
            this.mPartFiles = parent.mPartFiles
                .entries
                .associate {
                    it.key to it.value.withRoots(
                        spriteRoot = spriteRoot,
                        attRoot = attRoot
                    )
                }
                .toMutableMap()
        }
    }

    operator fun plus(other: BreedFiles): BreedFiles {
        if (other.gameVariant != this.gameVariant) {
            if (!other.gameVariant.isC3DS || !this.gameVariant.isC3DS) {
                throw PoseRenderException("Cannot combine breed files with dissimilar game variants; This: <${this.gameVariant}>; Other: <${other.gameVariant}>")
            }
        }
        val out = BreedFiles(
            gameVariant = other.gameVariant,
            allFiles = this.allFiles + other.allFiles,
            spriteRoot = other.spriteRoot,
            attRoot = other.attRoot,
            paletteTransform = other.paletteTransform ?: this.paletteTransform,
            closeMatchOnly = if (other.closeMatchOnly != null) {
                other.closeMatchOnly || this.closeMatchOnly.orFalse()
            } else {
                this.closeMatchOnly
            }
        )
        val keys = (this.mPartFiles.keys + other.mPartFiles.keys).distinct()
        for (key in keys) {
            val thisPart = this.mPartFiles[key]
            val otherPart = other.mPartFiles[key]
            val combined = thisPart?.plus(otherPart)
                ?: otherPart?.copy()
                ?: continue
            out.mPartFiles[key] = combined
        }

        return out
    }
}