@file:Suppress("unused")

package com.bedalton.creatures.caos.collectors

import com.bedalton.common.ast.structs.RangeWithIndex
import com.bedalton.creatures.caos.collectors.internal.scriptOffsetsToScriptsArray
import kotlinx.serialization.Serializable
import kotlin.js.JsExport
import kotlin.js.JsName


@JsExport
@JsName("ParseResult")
@Serializable
data class ParseResult(
    @JsName("variant")
    val variant: String,
    @JsName("originalText")
    val originalText: String,
    @JsName("items")
    val items: Array<CaosParserItem>,
    @JsName("whitespace")
    val whitespaceItems: Array<CaosParserItem>,
    @JsName("errors")
    val controlStatementErrors: Array<CaosParserItem.ErrorVal>,
    @JsName("scripts")
    val scripts: Array<Script>,
    @JsName("equalityStatements")
    val equalityStatements: Array<EqualityStatement>,
    @JsName("equalityStatementRanges")
    val equalityStatementRanges: Array<RangeWithIndex>,
    @JsName("commandCalls")
    val commandCalls: Array<CommandCall>,
    @JsName("comments")
    val comments: Array<CaosParserItem.Comment>,
    @JsName("caos2Comments")
    val caos2Comments: Array<CaosParserItem.Caos2Comment>,
    @JsName("looseTokens")
    val looseTokens: Array<CaosParserItem>,
) {

    @JsName("withScriptOffsets")
    internal constructor(
        variant: String,
        originalText: String,
        items: Array<CaosParserItem>,
        whitespaceItems: Array<CaosParserItem>,
        controlStatementErrors: Array<CaosParserItem.ErrorVal>,
        scriptOffsets: Array<BlockRange>,
        equalityStatements: Array<EqualityStatement>,
        equalityStatementRanges: Array<RangeWithIndex>,
        commandCalls: Array<CommandCall>,
        comments: Array<CaosParserItem.Comment>,
        caos2Comments: Array<CaosParserItem.Caos2Comment>,
        looseTokens: Array<CaosParserItem>,
    ) : this(
        variant = variant,
        originalText = originalText,
        items = items,
        whitespaceItems = whitespaceItems,
        controlStatementErrors = controlStatementErrors,
        scripts = scriptOffsetsToScriptsArray(scriptOffsets, items),
        equalityStatements,
        equalityStatementRanges,
        commandCalls,
        comments,
        caos2Comments,
        looseTokens
    )

    override fun equals(other: Any?): Boolean {
        if (this === other) return true
        if (other !is ParseResult) return false

        if (!items.contentEquals(other.items)) return false
        if (!scripts.contentEquals(other.scripts)) return false

        return true
    }

    override fun hashCode(): Int {
        var result = items.contentHashCode()
        result = 31 * result + scripts.contentHashCode()
        return result
    }
}
