package com.bedalton.creatures.caos.libs

import com.bedalton.creatures.caos.utils.token
import kotlinx.serialization.Serializable
import kotlin.js.JsExport

/**
 * 32-bit uint descriptors of the type of parser token represented
 */
@Suppress("SpellCheckingInspection")
@JsExport
@Serializable
object TypeTokens {
    val FLOAT = token("flot")
    val INT = token("int_")
    val CHAR = token("char")
    val BINARY = token("bina")
    val BYTE_STRING = token("byte")
    val QUOTE_STRING = token("qstr")
    val BRACKET_STRING = token("bstr")
    val TOKEN = token("tokn")
    val EQ_JOIN = token("eqjn")
    val EQ_OP = token("eqop")
    val PICT_DIMENSION = token("pict")
    val ERROR = token("errr")
    val INDEXED_VARIABLE = token("var_")
    val COMMAND_TOKEN = token("cmnd")
    val PLACEHOLDER_TOKEN = token("plch")
    val COMMENT = token("****")
    val CAOS2_COMMENT = token("*###")
    val NEWLINE = token("\\r\\n")
    val SPACES = token("_WS_")

    @Suppress("unused")
    fun nameOf(value: Int): String? {
        return when (value) {
            FLOAT -> "float"
            INT -> "int"
            CHAR -> "char"
            BINARY -> "binary"
            BYTE_STRING -> "byte_string"
            QUOTE_STRING -> "quote_string"
            BRACKET_STRING -> "bracket_string"
            TOKEN -> "token"
            EQ_JOIN -> "eq_join"
            EQ_OP -> "eq_op"
            PICT_DIMENSION -> "pict_dimension"
            ERROR -> "error"
            INDEXED_VARIABLE -> "indexed_variable"
            COMMAND_TOKEN -> "command_token"
            PLACEHOLDER_TOKEN -> "placeholder_token"
            COMMENT -> "comment"
            CAOS2_COMMENT -> "caos2_comment"
            NEWLINE -> "newline"
            SPACES -> "spaces"
            else -> null
        }
    }
}