import com.bedalton.creatures.breed.render.files.*
import com.bedalton.creatures.common.structs.GameVariant


private val validPartRange = 'a' .. 'q'

/**
 * Gets breeds for the list of parts given.
 * Parts are a list of chars inside a string without spaces
 */
@JsExport
fun getBreedsForParts(
    variantString: String,
    files: Array<String>,
    partsString: String,
    optionalPartsString: String,
    root: String? = null
): Array<BreedParts> {
    val variant = GameVariant.fromString(variantString)
        ?: throw Exception("Invalid variant code '$variantString' in getBreedsForParts")
    val parts = partsString.toCharArray().filter { it in validPartRange }.toSet()
    val optional = optionalPartsString.toCharArray().filter { it in validPartRange }.toSet()
    val fileData = files.mapNotNull { BreedFileData.fromPath(it) }
    return BreedFileUtil.getBreedsForPartsInGroups(
        variant,
        fileData,
        parts,
        optional,
        root,
    ).entries.map {
        BreedParts(it.key.toJsBreedKey(), it.value.toTypedArray())
    }.toTypedArray()
}


/**
 * Simple container for mapping a breed key to a list of sprites and atts
 */
@JsExport
data class BreedParts(
    val key: JsBreedKey,
    @Suppress("NON_EXPORTABLE_TYPE")
    val parts: Array<SpriteAndAtt>
) {
    override fun equals(other: Any?): Boolean {
        if (this === other) return true
        if (other == null || this::class.js != other::class.js) return false

        other as BreedParts

        if (key != other.key) return false
        if (!parts.contentEquals(other.parts)) return false

        return true
    }

    override fun hashCode(): Int {
        var result = key.hashCode()
        result = 31 * result + parts.contentHashCode()
        return result
    }
}