package com.bedalton.creatures.agents.pray.compiler.internal

import com.bedalton.common.coroutines.checkCancelled
import com.bedalton.creatures.agents.pray.compiler.NEWLINE_REGEX
import com.bedalton.creatures.agents.pray.compiler.REMOVER_SCRIPT_REGEX
import com.bedalton.creatures.agents.pray.compiler.SCRIPT_TAG_REGEX
import com.bedalton.creatures.agents.pray.compiler.data.CompilerBlockWithTags
import com.bedalton.creatures.agents.pray.compiler.data.Tag
import com.bedalton.creatures.agents.util.RelativeFileSystem
import com.bedalton.creatures.agents.util.internal.PRAY_BLOCK_COMPRESS_FLAG
import com.bedalton.io.bytes.ByteStreamWriter
import com.bedalton.io.bytes.Compressor
import com.bedalton.io.bytes.MemoryByteStreamWriter
import korlibs.io.util.unescape
import kotlinx.coroutines.CoroutineScope

/**
 * Write a block with tags and data to the common byte writer
 */
internal suspend fun writeBlock(
    coroutineContext: CoroutineScope,
    loader: RelativeFileSystem,
    writer: ByteStreamWriter,
    block: CompilerBlockWithTags,
    compression: Int?,
    unescape: Boolean,
    linkWithFilenameReference: Boolean
) {

    coroutineContext.checkCancelled()

    writeBlockHeader(writer, block)
    val contentBytes = MemoryByteStreamWriter()
    val tags = block.tags.map {
        if (it is Tag.LinkTag) {
            it.toStringTag(loader, linkWithFilenameReference)
        } else if (it is Tag.StringTag && (it.value.contains("\\") || it.value.contains("\n")) && unescape) {
            it.copy(
                value = it.value.unescape()
            )
        } else {
            it
        }
    }
    val intTags = stripDuplicateTags(tags.filterIsInstance<Tag.IntTag>())
        .sortedBy { it.tag }
    contentBytes.writeUInt32(intTags.size)
    for (tag in intTags) {
        contentBytes.writeUInt32(tag.tag.length)
        contentBytes.writeStringWithCreaturesEncoding(tag.tag)
        contentBytes.writeUInt32(tag.value)
    }
    val stringTags = stripDuplicateTags(tags.filterIsInstance<Tag.StringTag>())
        .sortedBy { it.tag }
    contentBytes.writeUInt32(stringTags.size)
    for (tag in stringTags) {
        contentBytes.writeUInt32(tag.tag.length)
        contentBytes.writeStringWithCreaturesEncoding(tag.tag)
        val value = when {
            SCRIPT_TAG_REGEX.matches(tag.tag) -> stripCAOS2Tags(tag.value)
            REMOVER_SCRIPT_REGEX.matches(tag.tag) -> stripCAOS2Tags(tag.value)
            else -> tag.value
        }
        contentBytes.writeUInt32(value.length)
        contentBytes.writeStringWithCreaturesEncoding(value)
    }
    writeBlockBytes(writer, contentBytes.bytes, compression)
}

internal fun writeBlockBytes(writer: ByteStreamWriter, contentBytes: ByteArray, compression: Int?) {
    val contentsFullLength = contentBytes.size
    val compressed = if (compression != null && compression != 0) {
        Compressor.compress(contentBytes, compression)
    } else {
        null
    }
    val compressedLength = compressed?.size ?: contentsFullLength
    // write compressed length
    writer.writeUInt32(compressedLength)
    // Write uncompressed file length
    writer.writeUInt32(contentsFullLength)
    // Write 1 if compressed
    writer.writeUInt32(if (compressed != null) PRAY_BLOCK_COMPRESS_FLAG else 0)
    // Write bytes
    writer.write(compressed ?: contentBytes)
}


/**
 * Strip duplicate tags keeping only the last one as the official PrayBuilder.exe does
 */
private inline fun <reified T : Tag<*>> stripDuplicateTags(tags: List<T>): Array<T> {
    val keys = tags.map { it.tag }.toSet()
    val out: List<T> = keys.map { key ->
        tags.last { tag -> tag.tag == key }
    }
    return out.toTypedArray()
}


private fun stripCAOS2Tags(script: String): String {
    return script.split(NEWLINE_REGEX)
        .filter {
            val line = it.trim()
            if (line.length < 2)
                true
            else if (line[0] != '*')
                true
            else {
                line[1] != '#' && (line[1] != '*' || !line.lowercase().startsWith("**caos2pray"))
            }
        }
        .joinToString("\r\n")
}