@file:Suppress("unused", "FunctionName","PackageDirectoryMismatch")

package libs

import com.bedalton.creatures.caos.libs.GameVariant
import com.bedalton.creatures.caos.libs.caosJsonSerializer
import kotlinx.serialization.json.encodeToDynamic


/**
 * Returns an object containing the commands, lvalues and rvalues for a given variant
 * @param variant
 */
@JsExport
@JsName("getCommandsForVariant")
fun getCommandsForVariant_JsApi(variant: GameVariant): /*Commands*/ dynamic {
    val result = com.bedalton.creatures.caos.libs.getCommandsForLib(variant)
    return caosJsonSerializer.encodeToDynamic(result)
}

/**
 * Gets the values list for a given values list id
 * @param id
 */
@JsExport
@JsName("getValuesList")
fun getValuesList_JsApi(id: Int): dynamic/*CaosValuesList?*/ {
    val valuesList = com.bedalton.creatures.caos.libs.getValuesList(id)
    return caosJsonSerializer.encodeToDynamic(valuesList)
}

/**
 * Gets all values lists for a given variant
 * @param variant
 */
@JsExport
@JsName("getAllValuesLists")
fun getAllValuesLists_JsApi(variant: GameVariant): dynamic/*CaosValuesList[]?*/ {
    val valuesLists = com.bedalton.creatures.caos.libs.CaosLibs[variant].valuesLists
    return caosJsonSerializer.encodeToDynamic(valuesLists)
}

/**
 * Get the printable name of the value type with the given id
 * I.e. "String", "Integer", "Variable", "Agent"
 * @param typeId
 */
@JsExport
@JsName("getValueTypeName")
fun getValueTypeName_JsApi(typeId: Int): String? {
    return com.bedalton.creatures.caos.libs.getValueTypeName(typeId)
}