package com.bedalton.creatures.agents.pray.parser

import com.bedalton.common.coroutines.rethrowIfCancellationException
import com.bedalton.common.exceptions.IOException
import com.bedalton.common.util.PathUtil
import com.bedalton.creatures.agents.pray.compiler.data.CompilerDataBlock
import com.bedalton.creatures.agents.pray.compiler.data.CompilerPrayBlock
import com.bedalton.creatures.agents.pray.compiler.data.namespaceValue
import com.bedalton.creatures.agents.util.RelativeFileSystem
import com.bedalton.log.Log
import kotlinx.coroutines.CoroutineScope
import kotlin.coroutines.CoroutineContext
import kotlin.coroutines.coroutineContext

data class PrayAgentParseResult(
    val containingFileName: String,
    val prefix: String?,
    val blocks: List<CompilerPrayBlock>,
    private val filesWriter: RelativeFileSystem,
    private val inlineScripts: Boolean
) {

    private var wroteBlocks = false

    private var mFiles: List<String>? = null

    @Deprecated(
        "Use files() with explicit CoroutineScope",
        replaceWith = ReplaceWith(
            "files(CoroutineScope(coroutineContext)",
            imports = ["kotlinx.coroutines.CoroutineScope"]
        )
    )
    suspend fun files(coroutineContext: CoroutineContext): List<String> = mFiles ?: write(CoroutineScope(coroutineContext)).apply {
        mFiles = this
    }

    suspend fun files(coroutineScope: CoroutineScope): List<String> = mFiles ?: write(coroutineScope).apply {
        mFiles = this
    }
    @Deprecated("Use write(coroutineContext)",
        replaceWith = ReplaceWith(
            "write(CoroutineScope(coroutineContext))",
            imports = ["kotlin.coroutines.coroutineContext", "kotlinx.coroutines.CoroutineScope"]
        )
    )
    suspend fun write(): List<String> {
        return write(CoroutineScope(coroutineContext))
    }

    @Deprecated("Use write(coroutineContext)",
        replaceWith = ReplaceWith(
            "write(CoroutineScope(coroutineContext))",
            imports = ["kotlin.coroutines.coroutineContext", "kotlinx.coroutines.CoroutineScope"]
        )
    )
    suspend fun write(coroutineContext: CoroutineContext): List<String> {
        return write(CoroutineScope(coroutineContext))
    }

    suspend fun write(coroutineScope: CoroutineScope): List<String> {
        if (wroteBlocks) {
            return mFiles!!
        }
        wroteBlocks = true
        val namespace = prefix
            ?: if (containingFileName.isEmpty()) {
                ""
            } else {
                "${PathUtil.getFileNameWithoutExtension(containingFileName) ?: containingFileName}-"
            }
        val outScripts = NonDuplicateScriptHolder()
        val caos2Pray = constructCaos2PrayFile(namespace, blocks, filesWriter, outScripts, inlineScripts)
        val prayFileName = constructPrayFile(
            containingFileName,
            namespace,
            blocks,
            outScripts,
            inlineScripts
        ).let { (fileName, bytes) ->
            filesWriter.write(fileName, bytes)
            fileName
        }
        val dataFileNames = blocks.filterIsInstance<CompilerDataBlock>()
            .map each@{
                val data = it.data()!!
                val fileName = namespaceValue(
                    namespace,
                    it.blockTag,
                    it.blockName,
                    true
                )
                filesWriter.write(fileName, data)
                fileName
            }


        // Write pray file scripts
        val scripts = try {
            outScripts.write(coroutineScope, filesWriter)
        } catch (e: Exception) {
            // Do not hold onto cancellation exceptions
            e.rethrowIfCancellationException()
            Log.e { "Failed to write scripts.${e.message}" }
            emptyList()
        }
        val files = (caos2Pray + prayFileName + dataFileNames + scripts)
        mFiles = files
        return files
    }

    @Deprecated("Use get with explicit CoroutineScope",
        replaceWith = ReplaceWith(
            "get(CoroutineScope(coroutineContext), file)",
            imports = ["kotlin.coroutines.coroutineContext", "kotlinx.coroutines.CoroutineScope"]
        )
    )
    suspend fun get(file: String): ByteArray {
        return get(CoroutineScope(coroutineContext), file)
    }

    @Deprecated("Use get with explicit CoroutineScope",
        replaceWith = ReplaceWith(
            "get(CoroutineScope(coroutineContext), file)",
            imports = ["kotlinx.coroutines.CoroutineScope"]
        )
    )
    suspend fun get(coroutineContext: CoroutineContext, file: String): ByteArray {
        return get(CoroutineScope(coroutineContext), file)
    }

    suspend fun get(coroutineScope: CoroutineScope, file: String): ByteArray {
        val filesReader = filesWriter
        if (file !in files(coroutineScope)) {
            throw IOException("Tried to access file not created in pray parse")
        }
        if (!filesReader.fileExists(file)) {
            throw IOException("Output file $file could not be found")
        }
        try {
            return filesReader.read(file)
        } catch (e: Exception) {
            // Do not hold onto cancellation exceptions
            e.rethrowIfCancellationException()

            throw IOException("Failed to read file after initial checks. Error: ${e.message}", e)
        }
    }

}