/**
 * Get all CAOS2Pray comment in the caos file text contents
 */
@JsExport
@JsName("getCaos2PrayComments")
fun getCaos2PrayComments_JsApi(text: String): dynamic /*Array<ParserItem.Caos2Comment>*/ {
    val comments = com.bedalton.creatures.caos.collectors.getCaos2PrayComments(text)
    return caosJsonSerializer.encodeToDynamic(comments)
}


/**
