@JsExport
@JsName("parseTokens")
fun parseTokens_JsApi(
    variant: GameVariant,
    text: String,
    items: Array<CaosParserItem>,
    scriptOffsets: Array<BlockRange> = emptyArray(),
    checkErrors: Boolean? = null,
    checkDelay: Int? = null,
    keepGoing: (() -> Boolean)? = null,
): /* ParseResult */ dynamic {
    val itemsKt = caosJsonSerializer.decodeFromDynamic<Array<CaosParserItem>>(items)
    val result = com.bedalton.creatures.caos.collectors.parseTokens(
        variant, text, itemsKt, scriptOffsets, checkErrors, checkDelay, keepGoing
    )
    return caosJsonSerializer.encodeToDynamic(result)
}

