typealias PrayBlockCallback = (pass: Int, index: Int, total: Int, blockTag: String, blockName: String) -> Unit

internal const val DEFAULT_INLINE_SCRIPTS: Boolean = false
private val magic by lazy { "PRAY".encodeToByteArray() }

private const val MIN_BLOCK_SIZE = 4 + 128 + 4 + 4 + 4 // Block tag, block name, byte length 1&2, flags


