/**
 * Parses a compiled PRAY file from stream
 * @throws AgentFileDecompilerException
 */
suspend fun parsePrayAgentBlocks(
    scope: CoroutineScope,
    reader: ByteStreamReader,
    whitelist: String,
    callback: PrayBlockCallback? = null,
): List<CompilerPrayBlock> = reader.readAtCurrentPosition {

    if (!magic.contentEquals(bytes(4))) {
        throw AgentFileDecompilerException("Not a pray file. Header does not match")
    }
    val shouldAdd: (blockName: CompilerPrayBlock) -> Boolean = if (whitelist.uppercase() in listOf("ALL", "*")) {
        { true }
    } else if (whitelist.uppercase() in listOf("NONE", "", "!")) {
        { false }
    } else {
        val regex = whitelist.uppercase().split("[\\s,;]+".toRegex())
            .filter { it.isNotBlank() }
            .joinToString("|")
            .let {
                "($it)".toRegex(RegexOption.IGNORE_CASE)
            };
        { block ->
            /*block is CompilerBlockWithTags ||*/ regex.matches(block.blockTag.text)
        }
    }
    val blocks = mutableListOf<Deferred<CompilerPrayBlock>>()
    val total = KorAtomicInt(0)
    val soFar = KorAtomicInt(0)
    callback?.invoke(0, 0, -1, "", "")
    while (hasBytes(MIN_BLOCK_SIZE)) {
        val i = total.incrementAndGet()
        callback?.invoke(0, i, -1, "", "")
        val block = parseBlock(scope, i, total, soFar, this, callback)
        blocks.add(block)
    }

    blocks.forEach { block ->
        block.start()
    }

    blocks.awaitAll().filter(shouldAdd)
}


private suspend fun parseBlock(
    scope: CoroutineScope,
    index: Int,
    total: KorAtomicInt,
    soFar: KorAtomicInt,
    reader: ByteStreamReader,
    callback: PrayBlockCallback?,
): Deferred<CompilerPrayBlock> {
    val startPosition = reader.position()
    val blockTag = reader.string(4)
    val blockTagInt = tok(blockTag)
    val name = reader.string(128).substringBefore(0x00.toChar())
    val actualLength = reader.int32()
    val decompressedLength = reader.int32()
    val flags = reader.uInt32()
    val isCompressed = flags hasFlag PRAY_BLOCK_COMPRESS_FLAG
    if (!reader.hasBytes(actualLength)) {
        throw AgentFileDecompilerException("Not enough bytes left to read PRAY block. Expected $actualLength; Found: ${reader.size - reader.position()}")
    }
    if (reader.position() != startPosition + 144) {
        throw AgentFileDecompilerException("Reader has not incremented position properly. Start: $startPosition; Expected: ${startPosition + 144}; Found: ${reader.position()}")
    }
    // Get byte start end
    val start = reader.position()
    val end = start + actualLength

    // Skip bytes so they are not double read
    reader.skip(actualLength)

    if (reader.position() != startPosition + 144 + actualLength) {
        throw AgentFileDecompilerException("Skipped bytes for delayed read, but position does not match expected. Start: $startPosition; ActualLength: $actualLength; Expected: ${startPosition + 144L + actualLength}; Actual: ${reader.position()}")
    }

    return scope.async(BackgroundDispatcher, start = CoroutineStart.LAZY) {
        val bytesNow: suspend () -> ByteArray = {
            val copy = reader.copyAsOpened()
            val compressed = (copy ?: reader).copyOfBytes(start, end)
            copy?.close()
            if (compressed.size != actualLength) {
                throw Exception("Failed to read required number of bytes for [$blockTag]->$name")
            }
            val decompressed = if (flags hasFlag PRAY_BLOCK_COMPRESS_FLAG) {
                Compressor.decompress(compressed)?.apply {
                    if (this.size != decompressedLength) {
                        throw AgentFileDecompilerException("Decompressed data block size differs from expected in [$blockTag]->\"$name\"; Expected: $decompressedLength; Actual: ${this.size}")
                    }
                }
            } else {
                null
            }
            decompressed ?: compressed
        }

        val blockNow: suspend () -> CompilerPrayBlock = {
            CompilerDataBlock(
                commonName = blockTag,
                blockTag = blockTag.textValue(),
                blockName = name.textValue(),
                stream = reader.copyAsOpened() ?: reader,
                byteStart = start,
                byteEnd = end,
                compressed = isCompressed,
                cacheBytes = false
            )
        }
        (if (blockTagInt in UNSUPPORTED_BLOCKS || blockTagInt in FILE_BLOCKS) {
            blockNow()
        } else {
            try {
                parseTagBlock(blockTag, name, start, bytesNow)
            } catch (e: Exception) {
                // Do not hold onto cancellation exceptions
                e.rethrowIfCancellationException()
                blockNow()
            }
        }).apply {
            val i = soFar.incrementAndGet()
            if (callback != null) {
                callback(1, i, total.value, blockTag, "Block[$index]: $name")
            }
        }
    }
}

private suspend fun parseTagBlock(
    blockTag: String,
    blockName: String,
    startOffset: Long,
    data: suspend () -> ByteArray,
): CompilerPrayBlock {

    val tags = getTags(blockTag, blockName, startOffset, data)

    return makePrayBlock(
        startLine = -1,
        blockTag = blockTag.textValue(),
        blockName = blockName.textValue(),
        false,
        tags = tags,
        linkWithFilenameReference = false
    )
}

private suspend fun getTags(
    blockTag: String,
    blockName: String,
    startOffset: Long,
    data: suspend () -> ByteArray,
): Array<Tag<*>> {
    val bytes = try {
        data()
    } catch (e: Exception) {
        // Do not hold onto cancellation exceptions
        e.rethrowIfCancellationException()

        Log.e { "Failed to get bytes for $blockTag[$blockName] at $startOffset. ${e.className}: ${e.message};\n${e.stackTraceToString()}" }
        return emptyArray()
    }
    // Create reader for this block of data bytes
    return ByteStreamReader.read(bytes) read@{

        // Read int tag count
        val intTagsCount = uInt32()
        if (intTagsCount > 1000) {
            return@read emptyArray()
        }
        // Read int tags
        val intTags = (0 until intTagsCount).map { i ->
            val length = uInt32()
            if (length > bytes.size) {
                Log.e { "Invalid string length <$length> for int tag $i in $blockTag[$blockName] at ${startOffset + position() - 4}" }
                return@read emptyArray()
            }
            Tag.IntTag(
                try {
                    string(length)
                } catch (e: Exception) {
                    // Do not hold onto cancellation exceptions
                    e.rethrowIfCancellationException()

                    Log.e { "Failed to read int tag $i in $blockTag[$blockName" }
                    return@read emptyArray()
                },
                uInt32().toInt()
            )
        }

        // Read string tag count
        val stringTagCount = uInt32()
        if (stringTagCount > 1500) {
            Log.e { "Too many string tags. Expecting $stringTagCount string tags" }
            return@read emptyArray()
        }

        // Read string tags
        val stringTags = (0 until stringTagCount).map { i ->
            Tag.StringTag(
                try {
                    string(uInt32())
                } catch (e: Exception) {
                    // Do not hold onto cancellation exceptions
                    e.rethrowIfCancellationException()

                    Log.e { "Invalid string length for int tag $i in $blockTag[$blockName]" }
                    return@read emptyArray()
                },
                try {
                    string(uInt32())
                } catch (e: Exception) {
                    // Do not hold onto cancellation exceptions
                    e.rethrowIfCancellationException()

                    Log.e { "Invalid string length for string value in tag $i in $blockTag[$blockName]" }
                    return@read emptyArray()
                },
            )
        }
        (intTags + stringTags).toTypedArray()
    }
}

private fun String.textValue(): TextValue = TextValue(
    this,
    -1,
    -1,
    -1
)


private class FileWriterWithFileNames(private val writer: FileSystem) : OutsideFileWriter {
    val fileNames = mutableSetOf<String>()

    override suspend fun delete(path: String): Boolean {
        if (writer.delete(path)) {
            fileNames.remove(path)
            return true
        }
        return false
    }

    override suspend fun fileExists(path: String): Boolean {
        return writer.fileExists(path)
    }

    override suspend fun isDirectory(path: String): Boolean {
        return writer.isDirectory(path)
    }

    override suspend fun write(path: String, data: ByteArray, append: Boolean) {
        writer.write(path, data, append)
        fileNames.add(path)
    }
}