@file:Suppress("unused")

package com.bedalton.app

import com.bedalton.log.*
import kotlin.js.JsExport
import kotlin.js.JsName

/**
 * Actual process termination for each multi-platform process
 */
internal expect fun exitNativeInternal(code: Int): Nothing

/**
 * Exits from calling function by calling process exit on CLI or
 * throwing an exception otherwise
 */
fun exitNative(code: Int, createThrowableFromCode: (code: Int) -> Exception?): Nothing {
    if (isCLI) {
        exitNativeInternal(code)
    } else {
        // Create the appropriate throwable from code
        // Exception is throw to exit code flow, but allow the caller to
        // handle the termination in cases where this is called from a non-cli (re-App) context
        throw createThrowableFromCode(code)
            ?: if (code == 0) {
                AppRequestTermination.AppRequestTerminationOK(0)
            } else {
                AppRequestTermination.AppRequestTerminationError(code)
            }
    }
}

/**
 * Exits from calling function by calling process exit on CLI or
 * throwing an exception otherwise
 */
fun exitNative(code: Int): Nothing {
    exitNative(code) { it: Int ->
        if (it == 0) {
            throw AppRequestTermination.AppRequestTerminationOK(0)
        } else {
            throw AppRequestTermination.AppRequestTerminationError(it)
        }
    }
}

/**
 * Exits from calling function by calling process exit on CLI or
 * throwing an exception otherwise
 */
fun exitNativeWithError(code: Int, errorMessage: () -> String): Nothing {
    exitNativeWithError(code, errorMessage())
}

/**
 * Exits from calling function by calling process exit on CLI or
 * throwing an exception otherwise
 */
fun exitNativeWithError(code: Int, errorMessage: String): Nothing {
    if (isCLI) {
        Log.e { errorMessage }
        exitNative(code)
    } else {
        throw AppRequestTermination.AppRequestTerminationError(errorMessage, code)
    }
}

/**
 * Exits from calling function by calling process exit on CLI or
 * throwing an exception otherwise
 */
fun exitNativeOk(message: String? = null): Nothing {
    if (isCLI) {
        if (message != null) {
            Log.e { message }
        }
        exitNative(0)
    } else {
        throw AppRequestTermination.AppRequestTerminationOK(message, 0)
    }
}

/**
 * Exits from calling function by calling process exit on CLI or
 * throwing an exception otherwise
 */
fun exitNativeOk(message: () -> String): Nothing {
    if (isCLI) {
        Log.e { message() }
        exitNative(0)
    } else {
        throw AppRequestTermination.AppRequestTerminationOK(message(), 0)
    }
}


/**
 * Exceptions used to signal the end of a called task
 * Used to differentiate a need to end the process or to allow calling code to continue
 */
@Suppress("NON_EXPORTABLE_TYPE")
@JsExport
sealed class AppRequestTermination(message: String?, val code: Int, throwable: Throwable? = null) :
    Exception(message, throwable) {
    class AppRequestTerminationOK(message: String? = null, code: Int? = null, throwable: Throwable? = null) :
        AppRequestTermination(message, code ?: 0, throwable) {
        @JsName("constructWithoutMessage")
        constructor(code: Int? = null, throwable: Throwable? = null) : this(null, code, throwable)
    }

    class AppRequestTerminationError(message: String?, code: Int, throwable: Throwable? = null) :
        AppRequestTermination(message, code, throwable) {
        @JsName("constructWithoutMessage")
        constructor(code: Int, throwable: Throwable? = null) : this(null, code, throwable)
    }
}
