@file:Suppress("NON_EXPORTABLE_TYPE")

package com.bedalton.creatures.caos.collectors

import com.bedalton.common.ast.structs.RangeWithIndex
import com.bedalton.creatures.caos.libs.ValueType
import com.bedalton.creatures.caos.libs.VariantCaosParameter
import kotlinx.serialization.SerialName
import kotlinx.serialization.Serializable
import kotlin.js.JsExport
import kotlin.js.JsName

@JsExport
@Serializable
data class EqualityStatement(
    /**
     * The entire range of this equality statement
     */
    override var textRange: RangeWithIndex,
    /**
     * The first/left side argument
     */
    @JsName("first")
    var first: Argument?,
    /**
     * The last/right side argument
     */
    @JsName("second")
    var second: Argument?,

    /**
     * The equality operator token
     */
    @JsName("eqToken")
    var eqToken: CaosParserItem.EqOp?,

    override val containingCommand: CommandReference?,

    override val parameter: VariantCaosParameter,

    override val text: String,
) : Argument {

    @SerialName("typeId")
    override val type: Int = ValueType.CONDITION.value

    override val inEqualityExpression: Boolean = true

    override val parserItem: CaosParserItem? = first?.parserItem
            ?: eqToken
            ?: second?.parserItem

    val arguments: List<Argument> = listOfNotNull(first, eqToken, second)

    override val parserIndexStart: Int? = first?.parserIndexStart ?: eqToken?.parserIndexStart ?: second?.parserIndexStart

    override val parserIndexEnd: Int? = second?.parserIndexEnd ?: eqToken?.parserIndexEnd ?: eqToken?.parserIndexStart

    init {
        eqToken?.containingCommand = containingCommand
    }
}