package com.creaturesforge.application.state

import com.bedalton.common.util.nullIfEmpty
import kotlin.contracts.contract

internal object EggFileNameUtil {

    internal fun fillInMissingGenomeFileNames(eggs: List<EggData>): List<EggData> {
        val fileNamesToGenomeNames = mapGenomePathsLowercaseToFileNames(eggs.reversed())
        return eggs.map map@{ egg ->
            fillInGenomeOutputFileNames(egg, fileNamesToGenomeNames)
        }
    }

    private fun allGenomes(eggs: List<EggData>): List<GenomeFile> {
        return eggs
            .flatMap {
                listOfNotNull(it.baseGenomeFile, it.motherGenomeFile, it.fatherGenomeFile)
            }
    }

    fun mapGenomePathsLowercaseToFileNames(eggs: List<EggData>): Map<String, String> {
        return allGenomes(eggs)
            .mapNotNull map@{ genomeFile ->

                if (genomeFile.filename.trim().startsWith(':')) {
                    return@map null
                }

                val outputFileName = genomeFile
                    .filename
                    .trim(' ', '\t', '\n', ':')
                    .trimEnd()
                    .nullIfEmpty()
                    ?: return@map null


                val filePath = genomeFile
                    .filepath
                    .nullIfEmpty()
                    ?.lowercase()
                    ?: return@map null

                filePath to outputFileName
            }.toMap()
    }

    private fun fillInGenomeOutputFileNames(egg: EggData, fileNames: Map<String, String>): EggData {
        if (!needsFillIn(egg)) {
            return egg
        }
        return egg.copy(
            baseGenomeFile = fillInEggFileName(egg.baseGenomeFile, fileNames),
            motherGenomeFile = fillInEggFileName(egg.motherGenomeFile, fileNames),
            fatherGenomeFile = fillInEggFileName(egg.fatherGenomeFile, fileNames)
        )
    }

    private fun fillInEggFileName(genomeFile: GenomeFile?, fileNames: Map<String, String>): GenomeFile? {

        if (!needsFillIn(genomeFile)) {
            return genomeFile
        }

        val filename = fileNames[genomeFile.filepath.lowercase()]
            ?: return genomeFile

        return genomeFile.copy(filename = ":$filename")
    }

    private fun needsFillIn(egg: EggData): Boolean {
        return needsFillIn(egg.baseGenomeFile) || needsFillIn(egg.motherGenomeFile) || needsFillIn(egg.fatherGenomeFile)
    }

    private fun needsFillIn(genomeFile: GenomeFile?): Boolean {
        contract {
            returns(true) implies (genomeFile != null)
        }
        return genomeFile != null && genomeFile.filepath.isBlank() && genomeFile.filename.isBlank()
    }

}