package com.bedalton.creatures.agents.pray.compiler

/**
 * Concrete implementation of the Pray compiler options interface
 */
data class PrayCompileOptionsImpl(
    /**
     * Merge all scripts in pray files into one giant script
     */
    override val mergeScripts: Boolean = false,

    /**
     * Merge all removal scripts from all files into a single removal script
     */
    override val mergeRscr: Boolean = false,

    /**
     * Automatically generate script removers for all scripts in pray file
     */
    override val generateScriptRemovers: Boolean = false,

    /**
     * Create removers for all created agent classifiers
     * Parses new: (simp|comp|*) creation statements and generates a remover for that class
     */
    override val generateAgentRemovers: Boolean = false,

    /**
     * Whether to validate syntax and existence of inline files
     */
    override val validate: Boolean = true,

    /**
     * PRAY source files for agents to be inlined into a single multi-agent bundle
     */
    override val joins: Array<String> = emptyArray(),

    /**
     * Whether this agent is meant to be joined into a multi-agent bundle
     */
    override val isJoin: Boolean = false,

    /**
     * Level of GZIP compression to apply [0-9]; 0=None; 9=Max
     */
    override val compressionLevel: Int? = null,

    /**
     * Name to use instead of the one supplied in the CAOS2Pray/CAOS2Cob file
     */
    override val overrideAgentName: String? = null,

    /**
     * Prefix linked CAOS files with their original file name
     */
    override val linkWithFilenameReference: Boolean? = null,

    /**
     * Add CAOS2Pray joins recursively from other joins
     */
    override val recursiveJoins: Boolean? = null

) : PrayCompileOptionsWithOverrideName, PrayCompileOptionsWithRecursiveJoin, PrayCompileOptionsWithLinkWithFileName {

    override fun asJoin(): PrayCompileOptionsImpl {
        return copy(isJoin = true)
    }

    override fun withJoins(joins: Array<String>): PrayCompileOptionsImpl {
        return copy(joins = joins)
    }
}