package com.bedalton.vfs

import com.bedalton.common.util.randomString
import kotlinx.coroutines.await
import tauri.fs.BaseDirectories
import tauri.fs.FsOptions
import tauri.fs.exists

actual suspend fun makeTempFile(prefix: String, suffix: String?): String? {
    val opts = js("{}").unsafeCast<FsOptions>()
    opts.dir = BaseDirectories.TEMP
    var path: String
    do {
        path = prefix.ifBlank { "tmp." } + randomString(8)
    } while(exists(path, opts).await())
    return path
}