@file:Suppress("unused")

package com.creaturesforge.application.ui.html

import com.bedalton.common.util.toFixed
import org.w3c.dom.Element


internal fun Element.attribute(attribute: String, value: String?) {
    if (value == null) {
        removeAttribute(attribute)
    } else {
        setAttribute(attribute, value)
    }
}

internal fun Element.attribute(attribute: String, value: Boolean?) {
    if (value == null) {
        removeAttribute(attribute)
    } else {
        setAttribute(attribute, value.toString())
    }
}


internal fun Element.attribute(attribute: String, value: Int?) {
    if (value == null) {
        removeAttribute(attribute)
    } else {
        setAttribute(attribute, value.toString())
    }
}

internal fun Element.attribute(attribute: String, value: Long?) {
    if (value == null) {
        removeAttribute(attribute)
    } else {
        setAttribute(attribute, value.toString())
    }
}

internal fun Element.attribute(attribute: String, value: Float?, precision: Int? = null) {
    if (value == null) {
        removeAttribute(attribute)
    } else if (precision != null) {
        setAttribute(attribute, value.toFixed(precision))
    } else {
        setAttribute(attribute, value.toString())
    }
}

internal fun Element.attribute(attribute: String, value: Double?, precision: Int? = null) {
    if (value == null) {
        removeAttribute(attribute)
    } else if (precision != null) {
        setAttribute(attribute, value.toFixed(precision))
    } else {
        setAttribute(attribute, value.toString())
    }
}
