package com.bedalton.io.bytes

import com.bedalton.common.exceptions.IOException
import com.bedalton.io.bytes.internal.rethrowIfCancellationException
import kotlin.coroutines.cancellation.CancellationException

/**
 * Tries to find next occurrence of a byte sequence
 * Returns FALSE if an occurrence was not found or a seek error occurred
 */
fun ByteStreamReader.seekToNextOrFalse(expectedBytes: ByteArray): Boolean {
    return try {
        seekToNextOrThrow(expectedBytes)
        true
    } catch (e: Exception) {
        e.rethrowIfCancellationException()
        false
    }
}

