/**
 * Tries to find next occurrence of an int sequence
 * Returns false if seek failed
 */
fun ByteStreamReader.seekToNextTokenOrFalse(vararg tokenInts: Int): Boolean {
    val index = absolutePositionOfNextTokenOrNull(*tokenInts)
        ?: return false
    return try {
        setPosition(index)
        true
    } catch (e: Exception) {
        e.rethrowIfCancellationException()
        false
    }
}

/**
 * Tries to find next occurrence an int sequence
 * Throwing a [NotEnoughBytesException] if the sequence is not found
 */
@Throws(NotEnoughBytesException::class, CancellationException::class)
fun ByteStreamReader.seekToNextOrThrow(expectedInts: List<Int>): ByteStreamReader {
    val bytesLeft = size - position()
    val queryLength = expectedInts.size
    if (bytesLeft <= queryLength) {
        throw NotEnoughBytesException("Not enough bytes to find byte sequence of length: $queryLength; Bytes Left: $bytesLeft")
    }

    val check: (index: Int) -> Boolean = check@{ index: Int ->
        repeat(queryLength) rep@{ j ->
            val next = index + j
            if (this.peakUInt8(next) != expectedInts[j]) {
                return@check false
            }
        }
        return@check true
    }

    var i = 0
    while ((bytesLeft - i) > queryLength) {
        if (check(i)) {
            return skip(i)
        }
        i++
    }
    throw NotEnoughBytesException("Byte sequence of length: $queryLength was not found in remaining $bytesLeft bytes")
}


