/**
 * Tries to find next occurrence of one of the given tokens
 * Throwing a [NotEnoughBytesException] if the sequence is not found
 */
@Throws(NotEnoughBytesException::class, CancellationException::class)
fun ByteStreamReader.seekToNextTokenOrThrow(vararg tokenInts: Int): ByteStreamReader {
    val index = absolutePositionOfNextTokenOrThrow(*tokenInts)
    return setPosition(index)
}

private fun rotateToken(by: Int, bytes: IntArray): Int {
    return when (by) {
        0 -> (bytes[0] shl 24) or (bytes[1] shl 16) or (bytes[2] shl 8) or bytes[3]
        1 -> (bytes[1] shl 24) or (bytes[2] shl 16) or (bytes[3] shl 8) or bytes[0]
        2 -> (bytes[2] shl 24) or (bytes[3] shl 16) or (bytes[0] shl 8) or bytes[1]
        3 -> (bytes[3] shl 24) or (bytes[0] shl 16) or (bytes[1] shl 8) or bytes[2]
        else -> throw IOException("ByteStreamReader implementation error; Unhandled byte rotation")
    }
}

