fun ByteStreamReader.absolutePositionOfNextTokenOrNull(vararg tokens: Int): Long? {
    val offset = offsetToNextTokenOrNull(*tokens)
        ?: return null
    return position() + offset
}

fun ByteStreamReader.offsetToNextTokenOrNull(vararg tokens: Int): Long? {
    return try {
        offsetToNextTokenOrThrow(*tokens)
    } catch (e: Exception) {
        e.rethrowIfCancellationException()
        null
    }
}

fun ByteStreamReader.offsetToNextTokenOrThrow(vararg tokens: Int): Long {
    if (tokens.isEmpty()) {
        throw IOException("Cannot find next token without token")
    }
    val bytesLeft = size - position()
    if (bytesLeft < 4) {
        throw NotEnoughBytesException("Not enough bytes to find token; Bytes Left: $bytesLeft")
    }
    var i = 0
    val bytes = IntArray(4) {
        peakUInt8(i++)
            ?: throw IOException("Failed to read next byte for seekToNextToken")
    }

    while (i <= bytesLeft) {
        val mod = i % 4
        val token: Int = rotateToken(mod, bytes)
        if (token in tokens) {
            return (i - 4).toLong()
        }
        val byte = peakUInt8(i++)
            ?: throw NotEnoughBytesException("Not enough bytes to find token; Bytes Left: $bytesLeft")
        bytes[(i - 1) % 4] = byte
    }
    throw throw NotEnoughBytesException("Failed to find token in remaining $bytesLeft bytes")
}

fun ByteStreamReader.absolutePositionOfNextTokenOrThrow(vararg tokens: Int): Long {
    val offset = offsetToNextTokenOrThrow(*tokens)
    return position() + offset
}

/**
 * Takes a CAOS word token, and converts it back to a string
 */
private fun token(token: Int): String {
    return "${(token shr 24).toChar()}${((token shr 16) and 0xFF).toChar()}${((token shr 8) and 0xFF).toChar()}${(token and 0xFF).toChar()}"
}