@file:Suppress("UNUSED_VARIABLE")

package com.bedalton.creatures.breed.render.support.util

import com.bedalton.common.util.nullIfEmpty

private var charValuePropertyName: String? = null

@Suppress("UNUSED_PARAMETER") // Parameter is used in js({}) block
private fun getCharValuePropertyName(char: dynamic): String {
    charValuePropertyName?.let {
        return it
    }
    val keys = (js("Object.keys(char)") as Array<String>)
        .nullIfEmpty()
        ?: throw NullPointerException("Failed to find js char value property name")
   val key = keys
        .singleOrNull()
        ?: keys.firstOrNull { it.startsWith("value_") }
        ?: keys.firstOrNull { it.startsWith("value") }
        ?: keys.firstOrNull { it.startsWith("value") }
        ?: keys.first()
    charValuePropertyName = key
    return key
}

/**
 * Needed because Kotlin JS does not handle chars differently than other platforms
 *
 * @return
 */
actual fun Char.asString(): String {
    if (jsTypeOf(this) == "string") {
        return this.unsafeCast<String>()
    }
    val code = getCharCode(this)
    return js("String.fromCharCode(code)") as String
}

/**
 * Needed because Kotlin JS does not handle chars differently than other platforms
 *
 * @return
 */
actual fun Char.asChar(): Char {
    return getCharCode(this).toChar()
}

private fun getCharCode(char: dynamic): Int {
    return when(val type = jsTypeOf(char)) {
        "number" -> char as Int
        "object" -> {
            val propertyName = getCharValuePropertyName(char)
            var code = js("char[propertyName]")
                ?: throw NullPointerException("Failed to find property name '$propertyName' in char")
            var tries = 4
            while (tries-- > 0 && jsTypeOf(code) == "object") {
                code = js("code[propertyName]")
            }
            if (jsTypeOf(code) != "number") {
                throw ClassCastException("Code returned from get charcode was ${jsTypeOf(code)}")
            }
            code as Int
        }
        "string" -> (char as String).single().code
        else -> throw ClassCastException("Cannot get charcode for js value of type $type")
    }
}