package com.creaturesforge.application.state

import com.bedalton.common.util.equalIgnoringOrder

internal fun setSpriteFiles(state: ForgeState, action: SetSpriteFilesAction): ForgeState {

    val spriteFiles = action.files

    if (state.spriteFiles != null && spriteFiles.equalIgnoringOrder(state.spriteFiles)) {
        return state
    }

    var out = state.copy(
        spriteFiles = spriteFiles,
    )

    val spriteSlot = if (state.eggMode == EggMode.MULTI && state.spriteSlot != null) {
        state.spriteSlot
    } else {
        state.breedSlot
    } ?: ForgeConfig.getCachedProjectData(state.projectFolder)
        ?.spriteSlot


    if (spriteFiles.isEmpty() || !hasSlot(spriteFiles, spriteSlot)) {
        out = out.copy(
            spriteSlot = null
        )

        if (out.maleGlyph?.manual != true) {
            out = out.copy(
                maleGlyph = null
            )
        }

        if (out.femaleGlyph?.manual != true) {
            out = out.copy(
                femaleGlyph = null
            )
        }

    }

    if (spriteSlot == null || !hasSlot(spriteFiles, spriteSlot)) {
        val slot = out.getAvailableSpriteSlots().singleOrNull()
        if (slot != null) {
            out = setSpriteBreedSlot(out, SetSpriteSlotAction(slot))
        }
    } else {
        out = setSpriteBreedSlot(out, SetSpriteSlotAction(spriteSlot))
    }

    if (out.breedSlot == out.spriteSlot) {
        out = out.copy(breedSlot = null)
    }

    if (out.attSlot == out.spriteSlot) {
        out = out.copy(attSlot = null)
    }

    return out
}
