package com.creaturesforge.application.state

import com.bedalton.common.util.PathUtil
import com.bedalton.common.util.equalIgnoringOrder
import com.bedalton.common.util.formatted
import com.bedalton.log.Log
import com.bedalton.state.simple.Dispatch
import com.bedalton.vfs.FileSystem
import com.bedalton.common.exceptions.rethrowCancellationException
import kotlinx.coroutines.CancellationException


internal suspend fun spriteFileMiddleware(
    state: ForgeState,
    action: FAction,
    dispatch: Dispatch<FAction>,
) {

    val isSpriteAction = action is SetProjectRootAction ||
            action is SetSpriteRootAction ||
            action is SetSpriteFilesAction ||
            action is RequestRefreshAction ||
            action is RequestSpriteFileListRefresh

    if (!isSpriteAction) {
        return
    }

    val hasRoot = state.spriteRoot != null ||
            state.projectFolder != null ||
            action is SetSpriteRootAction ||
            action is SetProjectRootAction

    if (!hasRoot) {
        return
    }

    dispatchSpriteRootActions(state, action, dispatch)
}

private suspend fun dispatchSpriteRootActions(state: ForgeState, action: FAction, dispatch: Dispatch<FAction>) {
    val fs = vfs

    val root = getSpriteRoot(fs, state, action)
        ?: return

    dispatchSetSpriteRootActionIfNeeded(state, action, root, dispatch)
    dispatchSetSpriteFilesActionIfNeeded(fs, state, action, root, dispatch)
}

private fun dispatchSetSpriteRootActionIfNeeded(
    state: ForgeState,
    action: FAction,
    spriteRoot: String,
    dispatch: Dispatch<FAction>,
) {
    if (action is SetSpriteRootAction) {
        return
    }
    if (state.spriteRoot == spriteRoot) {
        return
    }
    dispatch(SetSpriteRootAction(spriteRoot))
}

private suspend fun dispatchSetSpriteFilesActionIfNeeded(
    fs: FileSystem,
    state: ForgeState,
    action: FAction,
    spriteRoot: String,
    dispatch: Dispatch<FAction>,
) {
    if (action is SetSpriteFilesAction) {
        return
    }

    if (action is SetSpriteRootAction && action.path == spriteRoot && state.spriteFiles != null) {
        return
    }

    val files = getSpriteFilesInRoot(fs, spriteRoot)
    if (state.spriteFiles != null && state.spriteFiles.equalIgnoringOrder(files)) {
        return
    }

    dispatch(SetSpriteFilesAction(files))
}

private suspend fun getSpriteFilesInRoot(fs: FileSystem, spritePath: String): List<String> {
    val files = fs.listAllFiles(
        spritePath,
        recursive = false,
    ) {
        PathUtil.getExtension(it)?.lowercase() == "c16"
    }
    return files
}

private suspend fun getSpriteRoot(fs: FileSystem?, state: ForgeState, action: FAction): String? {

    if (action is SetSpriteRootAction) {
        return action.path
    }

    val projectRoot = when {
        action is SetProjectRootAction -> action.path
        state.spriteRoot != null -> return state.spriteRoot
        state.projectFolder != null -> state.projectFolder
        else -> null
    } ?: return null

    val fsNotNull = fs ?: vfs

    return getSpriteFolder(fsNotNull, projectRoot)
}

@Suppress("USELESS_CAST")
internal suspend fun getSpriteFolder(fs: FileSystem, projectFolder: String): String {
    val paths = listOf(
        PathUtil.combine(projectFolder, "Sprites"),
        PathUtil.combine(projectFolder, "Images"),
        PathUtil.combine(projectFolder),
    )
    return try {
        var throwable: Throwable? = null
        val path = paths.firstOrNull { spritePath ->
            try {
                fs.fileExists(spritePath) && fs.isDirectory(spritePath)
            } catch (e: Throwable) {
                e.rethrowCancellationException()
                if (throwable == null || e is CancellationException) {
                    throwable = e
                }
                false
            }
        }

        if (path != null) {
            return path
        }

        throwable?.let {
            throw it
        }

        return projectFolder
    } catch (e: dynamic) {
        if (e is String) {
            val error = (e as String).trim()
            if (!error.contains("path not allowed on the configured scope") || !error.contains(projectFolder)) {
                Log.e { "Failed to get project files; Tauri FS scope error\n$error" }
            } else {
                Log.e(error)
            }
        } else if (e is Throwable) {
            val error = e as Throwable
            error.rethrowCancellationException()
            Log.e("Failed to get sprite folder path; ${error.formatted()}")
        }
        projectFolder
    } catch (e: Throwable) {
        e.rethrowCancellationException()
        projectFolder
    } catch (e: Exception) {
        e.rethrowCancellationException()
        Log.e { "Get sprite files fell through to exception; ${e.formatted(true)}" }
        projectFolder
    } catch (e: Error) {
        e.rethrowCancellationException()
        Log.e { "Get sprite files fell through to error; ${e.formatted(true)}" }
        projectFolder
    }
}
