@file:Suppress("unused")

package com.bedalton.creatures.sprite.compilers

import com.bedalton.creatures.sprite.util.ColorEncoding
import com.bedalton.creatures.sprite.util.ColorEncoding.Companion.ENCODING_DEFAULT
import com.bedalton.creatures.sprite.util.PaletteTransform
import com.bedalton.creatures.sprite.util.RgbToInt
import com.bedalton.creatures.sprite.util.nullIfDefault
import com.bedalton.io.bytes.MemoryByteStreamWriter
import korlibs.image.bitmap.Bitmap32

@Suppress("MemberVisibilityCanBePrivate")
object C16Compiler : SpriteCompiler {

    private const val SPRITE_HEADER_SIZE = 6 // 4 = format, 2 = Num images
    private const val IMAGE_HEADER_SIZE = 8 // 4 = offset to start of data, 2 = width, 2 = height


    @Deprecated(
        "Use with keepBlack parameter",
        ReplaceWith("compileSpriteFromImageBytes(images, false, colorEncoding, callback")
    )
    override fun compileSpriteFromImageBytes(
        images: List<Pair<String, ByteArray>>,
        colorEncoding: ColorEncoding?,
        callback: ((pass: Int, current: Int, total: Int) -> Boolean?)?,
    ): ByteArray {
        return compileSpriteFromImageBytes(images, false, colorEncoding, callback)
    }

    @Deprecated(
        "Use with keepBlack parameter",
        ReplaceWith("compileSpriteFromImageBytes(images, false, colorEncoding, callback")
    )
    override fun compileSpriteFromLoadedImages(
        images: List<Bitmap32>,
        colorEncoding: ColorEncoding?,
        callback: ((current: Int, total: Int) -> Boolean?)?,
    ): ByteArray {
        return compileSpriteFromLoadedImages(images, false, colorEncoding, callback)
    }

    override fun compileSpriteFromImageBytes(
        images: List<Pair<String, ByteArray>>,
        keepBlack: Boolean,
        colorEncoding: ColorEncoding?,
        paletteTransform: PaletteTransform?,
        callback: ((pass: Int, current: Int, total: Int) -> Boolean?)?,
    ): ByteArray {
        val bitmaps = ImageLoader.loadMany(images) { current, total ->
            if (callback?.invoke(1, current, total) == false) {
                throw SpriteCompilerCancelledException("Cancelled compilation of C16 during image read")
            }
            true
        }
        return compileSpriteFromLoadedImages(bitmaps, keepBlack, colorEncoding, paletteTransform) { current, total ->
            callback?.invoke(2, current, total)
        }
    }

    override fun compileSpriteFromLoadedImages(
        images: List<Bitmap32>,
        keepBlack: Boolean,
        colorEncoding: ColorEncoding?,
        paletteTransform: PaletteTransform?,
        callback: ((current: Int, total: Int) -> Boolean?)?,
    ): ByteArray {

        var imageOffset = SPRITE_HEADER_SIZE + (images.size * IMAGE_HEADER_SIZE)

        val buffer = MemoryByteStreamWriter()

        val encoding = (colorEncoding ?: ENCODING_DEFAULT)

        val flags = if (encoding != ColorEncoding.X_555) 3 else 2

        val toIntRaw = paletteTransform
            .nullIfDefault()
            ?.transform(encoding, keepBlack = keepBlack)
            ?.toInt(keepBlack = keepBlack)

        val toInt = toIntRaw ?: encoding.toInt

        buffer.writeUInt32(flags)
        buffer.writeUInt16(images.size)
        for (image in images) {
            imageOffset += (image.height - 1) * 4
        }
        var out = ByteArray(0)
        val total = images.size
        var frame = 0

        val actualCallback: ((current: Int, total: Int) -> Boolean?)? = callback?.let { it ->
            { current: Int, total: Int ->
                if (it(current, total) == false) {
                    throw SpriteCompilerCancelledException("S16 compilation cancelled during compiler phase")
                }
                true
            }
        }
        actualCallback?.invoke(frame, total)
        for (image in images) {
            buffer.writeUInt32(imageOffset)
            buffer.writeUInt16(image.width)
            buffer.writeUInt16(image.height)
            val (bytes, lineOffsets) = writeCompiledImage(image, keepBlack, toInt)
            if (lineOffsets.size != image.height - 1) {
                throw SpriteCompileException("Compiler returned invalid line offset information. Expected: ${image.height - 1}; Found: ${lineOffsets.size}")
            }
            repeat(image.height - 1) { i ->
                buffer.writeUInt32(imageOffset + lineOffsets[i])
            }
            imageOffset += bytes.size
            out += bytes
            actualCallback?.invoke(++frame, total)
        }
        buffer.write(out)
        return buffer.bytes
    }

    private fun writeCompiledImage(
        image: Bitmap32,
        keepBlack: Boolean,
        rgbToInt: RgbToInt,
    ): Pair<ByteArray, List<Int>> {
        val alphaCutoff = programAlphaCutoff
        val width = image.width
        val height = image.height
        val lineOffsets: MutableList<Int> = mutableListOf()
        val thisBuffer = MemoryByteStreamWriter()
        val runColorData: MutableList<Int> = mutableListOf()
        var runLength: Int
        // Open buffer for writing. Attempts to make write operation atomic, but we will see

        for (y in 0 until height) {
            if (y != 0) {
                lineOffsets.add(thisBuffer.size.toInt())
            }
            runLength = 0
            runColorData.clear()
            var wasTransparent: Boolean? = null
            fun write(transparentRun: Boolean) {
                var run = runLength shl 1
                if (transparentRun) {
                    thisBuffer.writeUInt16(run)
                } else {
                    run = run or 1
                    thisBuffer.writeUInt16(run)
                    thisBuffer.writeUInt16(runColorData.toTypedArray())
                    runColorData.clear()
                }
                runLength = 0
            }
            for (x in 0 until width) {
                val pixelRGB = image[x, y]
                val alpha: Int = pixelRGB.a
                val transparent = alpha < alphaCutoff
                        || (!keepBlack && pixelRGB.r == 0 && pixelRGB.g == 0 && pixelRGB.b == 0)
                val red: Int = pixelRGB.r
                val green: Int = pixelRGB.g
                val blue: Int = pixelRGB.b
                val pixelInt = rgbToInt(red, green, blue)
                if (transparent != wasTransparent || runLength > 32767) {
                    //end the run if this isn't the first run
                    if (wasTransparent != null) {
                        write(wasTransparent)
                    }

                    wasTransparent = transparent

                    // Start new run
                    if (transparent) {
                        runColorData.clear()
                    } else {
                        runColorData.add(pixelInt)
                    }
                    runLength = 1
                } else {
                    if (!wasTransparent) {
                        runColorData.add(pixelInt)
                    }
                    runLength++
                }

            } // end x loop\

            if (wasTransparent != null) {
                write(wasTransparent)
            }
            thisBuffer.writeUInt16(0)
        } // end y loop
        thisBuffer.writeUInt16(0)
        return Pair(thisBuffer.bytes, lineOffsets)
    }

}