@file:Suppress("unused")

package com.bedalton.common.coroutines

import kotlinx.coroutines.*
import kotlin.coroutines.CoroutineContext

fun CoroutineContext.launch(
    start: CoroutineStart = CoroutineStart.DEFAULT,
    block: suspend (scope: CoroutineScope) -> Unit,
): Job {
    return CoroutineScope(this).launch(start = start, block = block)
}

fun <T> CoroutineContext.async(
    start: CoroutineStart = CoroutineStart.DEFAULT,
    block: suspend (scope: CoroutineScope) -> T,
): Deferred<T> {
    return CoroutineScope(this).async(start = start, block = block)
}