package com.bedalton.creatures.sprite.parsers

import com.bedalton.creatures.sprite.util.ColorPalette.Companion.C1OpaqueBlack
import com.bedalton.common.util.PathUtil
import com.bedalton.io.bytes.*
import korlibs.image.bitmap.Bitmap32
import korlibs.image.format.PNG
import kotlin.js.JsExport

const val ALBUM_PARSER_LOG_MODE = "sprite.ALBUM.log"
private val palette = C1OpaqueBlack
@JsExport
data class PhotoAlbum(
    val photos: Array<AlbumPhoto>,
    val moniker: String? = null,
) {
    override fun equals(other: Any?): Boolean {
        if (this === other) return true
        if (other !is PhotoAlbum) return false

        if (!photos.contentEquals(other.photos)) return false
        if (moniker != other.moniker) return false

        return true
    }

    override fun hashCode(): Int {
        var result = photos.contentHashCode()
        result = 31 * result + (moniker?.hashCode() ?: 0)
        return result
    }

    companion object {

        fun creaturesHexMonikerToToken(hexMoniker: String?): String? {
            if (hexMoniker == null || hexMoniker.length != 8) {
                return null
            }
            val out = StringBuilder()
            for (i in 0..3) {
                val charHex = hexMoniker.substring(i * 2, (i * 2) + 2)
                val charCode = charHex.toInt(16)
                out.append(charCode.toChar())
            }
            return out.reverse().toString()
        }
    }
}

internal fun parsePhotoAlbumInternal(
    stream: ByteStreamReader,
    progressChunkSize: Int = 1,
    progressCallback: ((i: Int, total: Int) -> Boolean?)? = null,
): PhotoAlbum? {
    return parsePhotoAlbumInternal(
        null,
        stream,
        progressChunkSize,
        progressCallback
    )
}

internal fun parsePhotoAlbumInternal(
    fileName: String?,
    stream: ByteStreamReader,
    progressChunkSize: Int = 1,
    progressCallback: ((i: Int, total: Int) -> Boolean?)? = null,
): PhotoAlbum? {
    val moniker = if (fileName != null) {
        PhotoAlbum.creaturesHexMonikerToToken(PathUtil.getFileNameWithoutExtension(fileName))
    } else {
        null
    }
    val imagesCount = stream.uInt16()
    progressCallback?.invoke(0, imagesCount)

    val photos = (0 until imagesCount).map { i ->
        val image = readPhotoAlbumImage(
            i,
            stream,
            imagesCount > 1
        )

        if (i % progressChunkSize == 0) {
            if (progressCallback?.invoke(i + 1, imagesCount) == false) {
                return null
            }
        }
        image
    }
    return PhotoAlbum(photos.toTypedArray(), moniker)
}

private fun readPhotoAlbumImage(i: Int, reader: ByteStreamReader, isOneOfMany: Boolean): AlbumPhoto {
    val timestamp = reader.sfcString()
    val paddedWidth = reader.uInt32().toInt()
    if (paddedWidth > 500) {
        throw SpriteParserException("Photo[$i] width is too great at $paddedWidth")
    }
    // Get and check height
    val height = reader.uInt32().toInt()
    if (height > 500) {
        throw SpriteParserException("Photo[$i] height is too great at $height")
    }

    // Get and check true width
    val trueWidth = reader.uInt32().toInt()
    if (trueWidth > 500) {
        throw SpriteParserException("Photo[$i] true width is too great at $trueWidth")
    }

    val bitmap = Bitmap32(trueWidth, height, false)
    val readAndSetPixel: ((x: Int, y: Int) -> Unit) = if (paddedWidth != trueWidth) {
        set@{ x: Int, y: Int ->
            val pixelInt = reader.uInt8()
            if (x >= trueWidth) {
                return@set
            }
            val color = palette[pixelInt]
            bitmap[x, y] = color
        }
    } else {
        { x: Int, y: Int ->
            val pixelInt = reader.uInt8()
            val color = palette[pixelInt]
            bitmap[x, y] = color
        }
    }
    repeat(height) { y ->
        repeat(paddedWidth) x@{ x ->
            if (isOneOfMany && y == height - 1 && x >= paddedWidth - 2) {
                return@x
            }
            readAndSetPixel(x, height - y - 1)
        }
    }

    val comment = if (reader.hasBytes(1) && reader.peakUInt8() == 0) {
        reader.sfcString()
    } else {
        ""
    }

    if (isOneOfMany) {
        if (reader.hasBytes(1) && reader.peakUInt8() == 0) {
            reader.skip(1)
        }
    }
    return AlbumPhoto(
        bitmap,
        timestamp,
        comment
    )
}

@Suppress("unused")
@JsExport
class AlbumPhoto(
    @Suppress("NON_EXPORTABLE_TYPE")
    internal val bitmap32: Bitmap32,
    val timestamp: String,
    val comment: String?,
) {

    val unixDate by lazy {
        com.bedalton.creatures.common.util.creaturesDateToUnixTime(timestamp)
    }

    val pngBytes: ByteArray by lazy {
        PNG.encode(image)
    }
}

/**
 * Get usable Bitmap32 image for this album photo
 * Accessor function to allow non-JS platforms to access a bitmap image
 */
val AlbumPhoto.image get() = bitmap32


