internal class GenomeControl(private val element: HTMLElement) : Validatable {

    private var showedGenomeError = true
    private var lastStateId: Int? = null
    private var projectPathIsSame = false
    private var projectRoot: String? = null
    private var lastProjectPath: String? = null
    private lateinit var placeholder: String
    private var genomeFile: GenomeFile? = null
    private var outputGenus: Int? = null
    private var manualName = false

    private val allOptionsList = mutableListOf<HTMLOptionElement>()

    private val mIsOptional by element.dataBoolean("genome-optional")

    private val isOptional
        get() = mIsOptional
            ?: throw Exception("Genome input has not been marked as optional")

    private val updateOnBrowserEvents: Boolean
        get() = blockingCount.value == 0

    private var lastGenomeSelection = ""
    private var lastGenomeFolderPath: String? = null

    private lateinit var dispatch: Dispatch<FAction>

    private var changed = false

    private var blockingCount = atomic(0)

    private var groups = mutableMapOf<Int, HTMLOptGroupElement>()

    private val defaultGenomes = mapOf(
        "0::Select Base Genome" to "",
        "1::Stock Astro (ex48)" to "$GENOME_DIRECTORY/norn.ex48.gen",
        "1::CFE (Creatures Full of Edits)" to "$GENOME_DIRECTORY/norn.cfe.gen",
        "1::TWB (v3) (True Warm Blood)" to "$GENOME_DIRECTORY/norn.twb.gen",
        "2::Grendel (46g)" to "$GENOME_DIRECTORY/gren.46g.gen",
        "2::Grendel TCB (v3 rev) (True Cold Blood)" to "$GENOME_DIRECTORY/gren.tcb.gen",
        "3::Ettin (46e)" to "$GENOME_DIRECTORY/ettin.46e.gen",
        "3::Ettin TWB (v3) (True Warm Blood)" to "$GENOME_DIRECTORY/ettin.twb.gen",
        "5::Select From Disk" to DISK_SELECT
    )

    private var additionalGenomes: List<String> = emptyList()

    private var pendingSelection: String? = null


    private val genomeGender
        get() = element.getAttribute("data-genome-gender")?.toInt()
            ?: throw Exception("Failed to get genome gender attribute")


    private val baseGenomeSelect = (element.querySelector("[data-role='genome-select']") as HTMLSelectElement).apply {
        setInitialGenomeOptions(this)
    }

    private val outputGenomeName =
        (element.querySelector("[data-role='output-genome-name']") as HTMLInputElement).apply {
            this.placeholder = this.getAttribute("placeholder") ?: "Output genome filename"
        }


    init {

        ForgeStore.subscribe { state, dispatch ->
            this.dispatch = dispatch
            outputGenus = state.genomeGenus
            projectRoot = state.projectFolder
            CoroutineScope(Job()).launch {
                projectPathIsSame = projectRoot == lastProjectPath && state.stateId == lastStateId
                if (!projectPathIsSame) {
                    lastStateId = state.stateId
                    lastProjectPath = state.projectFolder
                }
                runBlockingEvents {
                    try {
                        if (!projectPathIsSame && !state.virtual) {
                            additionalGenomes = additionalGenomes.filter { !it.lowercase().startsWith(agentScheme.lowercase()) }
                        }
                        if (!contentEquals(additionalGenomes, state.additionalGenomes.values) ||  !state.virtual) {
                            setAdditionalGenomes(state.additionalGenomes)
                        }
                        updateGenomeList(state.genomeGenus)
                        updateGenome(state.selectedEgg)
                    } catch (e: Exception) {
                        Log.e("GenomeControl::ForgeState.subscribe() failed; ${e.formatted(true)}")
                    }
                }
            }
        }

        initListeners()

    }

    private suspend fun setAdditionalGenomes(additionalGenomes: Map<String, String>) {
        for (option in baseGenomeSelect.optionsList()) {
            if (isAgentScheme(option.value)) {
                if (option.selected) {
                    baseGenomeSelect.value = ""
                }
                option.remove()
            }
        }
        ensureGenomeOptions(additionalGenomes)
    }


    private fun initListeners() {
        initOutputGenomeNameListeners()
        initBaseGenomeSelectListeners()
    }

    private fun initOutputGenomeNameListeners() {
        outputGenomeName.onblur = blur@{
            if (updateOnBrowserEvents) {
                window.setTimeout(this@GenomeControl::dispatchGenomeNameChange, 5)
            }

            runBlockingEvents {
                if (!manualName) {
                    outputGenomeName.value = ""
                    return@blur Unit
                }

                if (outputGenomeName.value.isBlank()) {
                    outputGenomeName.value = ""
                }
            }
        }
        outputGenomeName.onkeyup = {
            if (updateOnBrowserEvents) {
                if (it.key.lowercase() == "enter") {
                    window.setTimeout(this@GenomeControl::dispatchGenomeNameChange, 5)
                } else {
                    changed = changed || (genomeFile?.filename != outputGenomeName.value)
                }
            }
            manualName = outputGenomeName.value.isNotBlank()
            Unit
        }
        outputGenomeName.oninput = {
            changed = changed || (genomeFile?.filename != outputGenomeName.value)
            manualName = outputGenomeName.value.isNotBlank()
            Unit
        }
        outputGenomeName.onfocus = {
            runBlockingEvents {
                if (outputGenomeName.value.isBlank() && outputGenomeName.placeholder.isNotNullOrBlank()) {
                    outputGenomeName.value = outputGenomeName.placeholder
                        .ensureNotStartsWith("auto:")
                        .trim()
                        .trimStart(':')
                        .trim()
                }
            }
        }
    }

    private fun initBaseGenomeSelectListeners() {
        baseGenomeSelect.onchange = {
            changed = changed || (baseGenomeSelect.value != genomeFile?.filepath)
            if (updateOnBrowserEvents) {
                window.setTimeout(this@GenomeControl::onBaseGenomeChange, 5)
            }
        }
    }

    private fun updateGenome(egg: EggData) {
        val genome = getEggGenome(egg)
        updateGenome(genome)
    }

    private fun getEggGenome(egg: EggData): GenomeFile? {
        return when (genomeGender) {
            0 -> egg.baseGenomeFile
            1 -> egg.fatherGenomeFile
            2 -> egg.motherGenomeFile
            else -> throw Exception("Invalid egg genome index")
        }
    }

    private inline fun runBlockingEvents(work: () -> Unit) {
        enableDisableBrowserEvents(false)
        try {
            work()
        } finally {
            enableDisableBrowserEvents(true)
        }
    }

    private fun enableDisableBrowserEvents(enable: Boolean) {
        if (enable) {
            blockingCount.getAndUpdate { max((it - 1), 0) }
        } else {
            blockingCount.incrementAndGet()
        }
    }

    private fun updateGenome(file: GenomeFile?) {
        if (file?.filepath == DISK_SELECT) {
            return
        }
        runBlockingEvents {

            genomeFile = file

            if (!projectPathIsSame && genomeFile == null) {
                baseGenomeSelect.value = ""
                outputGenomeName.value = ""
                return
            }

            val notEmptyFilePathOrName = file?.filepath?.nullIfEmpty()
                ?: baseGenomeSelect.value.nullIfEmpty()
                ?: outputGenomeName.value.trim().nullIfEmpty()

            if (notEmptyFilePathOrName == null) {
                outputGenomeName.placeholder = ""
                if (genomeFile != null) {
                    dispatch(SetGenomeAction(genomeGender, null))
                }
                return
            }

            if (file == null) {
                val baseGenome = baseGenomeSelect
                    .value
                    .nullIfEmpty()
                if (genomeFile == null) {
                    return
                }
                updateGenome(
                    GenomeFile(
                        outputGenomeName.value,
                        baseGenome ?: ""
                    )
                )
                return
            }
            if (file.filename.trim().startsWith(':')) {
                this.outputGenomeName.setAttribute("placeholder", "auto: " + file.filename.substring(1))
                this.outputGenomeName.value = ""
            } else {
                if (this::placeholder.isInitialized) {
                    this.outputGenomeName.setAttribute("placeholder", placeholder)
                }
                if (this.outputGenomeName.value != file.filename) {
                    this.outputGenomeName.value = file.filename
                }

            }
            if (!selectGenomeInSelect(file.filepath)) {
                Log.e(
                    "Failed to locate genome for select; Expected ${file.filepath}; Available: " + baseGenomeSelect.optionsList()
                        .joinToString(",") { it.value })
            } else {
                showedGenomeError = false
            }
        }
    }

    private fun selectGenomeInSelect(filepath: String): Boolean {
        if (this.baseGenomeSelect.value == filepath) {
            return true
        }

        baseGenomeSelect.value = filepath

        if (baseGenomeSelect.value == filepath) {
            return true
        }

        val filepathLower = filepath.lowercase()

        val optionsList = baseGenomeSelect.optionsList()

        // Select value case insensitive
        for (option in optionsList) {
            if (option.value.lowercase() != filepathLower) {
                continue
            }
            option.value = filepath
            option.selected = true
            baseGenomeSelect.value = filepath
            return true
        }

        if (!showedGenomeError && projectPathIsSame) {
            showedGenomeError = true
            launchMain(capture = true) {
                try {
                    showMessageAndWait("Failed to locate genome previously set")
                    Log.i("Failed to locate genome previously set")
                } catch (e: Exception) {
                    Log.e("Failed to show message and wait when genome select failed; ${e.formatted(true)}")
                }
            }
            runBlockingEvents {
                baseGenomeSelect.value = ""
            }
        }
        return false
    }

    private suspend fun ensureGenomeOptions(paths: Map<String, String>) {
        for ((label, path) in paths) {
            ensureGenomeOption(label, path)
        }
        selectPending()
    }

    private fun selectPending() {
        runBlockingEvents {
            val pendingSelection = pendingSelection
            if (pendingSelection != null) {
                baseGenomeSelect.value = pendingSelection
                if (baseGenomeSelect.value == pendingSelection) {
                    this.pendingSelection = null
                }
            }
        }
    }

    private fun updateGenomeList(targetGenus: Int?) {


        groups[1]?.remove()
        groups[2]?.remove()
        groups[3]?.remove()

        if (targetGenus !in 1..3) {
            baseGenomeSelect.append(groups[1])
            baseGenomeSelect.append(groups[2])
            baseGenomeSelect.append(groups[3])
        }

        val keys = groups.keys.sortedBy {
            when (it) {
                -1 -> -1
                0 -> 0
                targetGenus -> 1
                else -> it + 10
            }
        }

        for (genusInt in keys) {
            val option = groups[genusInt]!!
            baseGenomeSelect.append(option)
        }
    }

    private suspend fun ensureGenomeOption(label: String, path: String) {

        if (!vfs.fileExists(path)) {
            return
        }
        val options = baseGenomeSelect.optionsList()

        if (options.any { it.value == path }) {
            return
        }


        val newOption = (document.createElement("option") as HTMLOptionElement).apply {
            value = path
            innerText = label
        }

        val before = groups[groups.keys.sorted().firstOrNull() ?: 0]
        if (before != null) {
            baseGenomeSelect.insertBefore(newOption, before)
        } else {
            baseGenomeSelect.appendChild(newOption)
        }
