    private suspend fun pushGenome(path: String) {
        addFile(path)
        val allPaths = additionalGenomes + path
        val label = findShortestUniquePaths(allPaths).last()

        ensureGenomeOption(label, path)
    }

    private fun onBaseGenomeChange() = runBlockingEvents {
            val selection = baseGenomeSelect.value

            // If requesting new genome
            if (selection == DISK_SELECT) {
                Log.i { "Selecting genome from disk" }
                launchMain launch@{
                    try {
                        selectGenomeFromDisk()
                    } catch (e: Exception) {
                        Log.e("Failed to selecte genome from disk; ${e.formatted(true)}")
                    }
                }
                return
            }

            if (!changed) {
                return
            }

            val genomeFile = genomeFile?.copy(
                filepath = selection
            ) ?: GenomeFile(
                outputGenomeName.value,
                selection,
            )
            dispatch(SetGenomeAction(genomeGender, genomeFile))
    }

    private suspend fun selectGenomeFromDisk() {
        runBlockingEvents run@{
            val defaultPath = lastGenomeFolderPath
                ?: ForgeConfig.getLastGeneticsDirectory(projectRoot)
                ?: if (platform().await() == "linux") {
                    "~/"
                } else {
                    null
                }

            val file = openSingle {
                this.title = "Select Genome"
                this.defaultPath = defaultPath
                this.filters = arrayOf(
                    jsOb {
                        this.name = "Genomes"
                        this.extensions = arrayOf("gen")
                    }
                )
            }

            if (file == null) {
                baseGenomeSelect.value = lastGenomeSelection
                    .ifEmpty { genomeFile?.filepath.orEmpty() }
                return
            }
            pendingSelection = file
            pushGenome(file)
            dispatch(AddGenomeOptionAction(file))
            val lastFolder = PathUtil.getWithoutLastPathComponent(file)
            lastGenomeFolderPath = lastFolder
            setLastGeneticsDirectory(projectRoot, lastFolder ?: file)
            selectPending()
            lastGenomeSelection = file
        }
    }

    private fun dispatchGenomeNameChange() {
        if (!changed) {
            return
        }
        runBlockingEvents {
            val genomeFile = genomeFile?.copy(
                filename = outputGenomeName.value
            ) ?: GenomeFile(
                outputGenomeName.value,
                baseGenomeSelect.value,
            )
            this.genomeFile = genomeFile
            dispatch(SetGenomeAction(genomeGender, genomeFile))
        }

    }

    private fun setInitialGenomeOptions(select: HTMLSelectElement) {
        initGenomeGroups()

        val keys = defaultGenomes.keys.map {
            getGenomeComponents(it).first
        }.toSet().sortedBy { it ?: 1000 }

        val defaultGenomes = defaultGenomes
        for (key in keys) {
            val filter: (Map.Entry<String, String>)->Boolean = if (key == null) {
                {
                    !it.key.contains("::")
                }
            } else {
                {
                    it.key.startsWith("$key::")
                }
            }

            val genomes = defaultGenomes.filter(filter)

            val optgroup = if (key != null) {
                groups[key]
            } else {
                null
            }

            for ((labelRaw, file) in genomes) {
                val (optgroupIndex, label) = getGenomeComponents(labelRaw)

                val option = (document.createElement("option") as HTMLOptionElement).apply {
                    this.innerText = if (file == "" && isOptional) {
                        NONE_OPTION
                    } else {
                        label
                    }

                    this.setAttribute("data-genus", "" + optgroupIndex)

                    this.value = file
                    if (file == "") {
                        this.selected = true
                        this.hidden = !isOptional
                        this.disabled = !isOptional
                    }
                }

                if (optgroup != null) {
                    optgroup.append(option)
                } else {
                    select.append(option)
                }
                allOptionsList.add(option)
            }
        }


    }

    private fun getGenomeComponents(label: String): Pair<Int?, String> {
        val components = label.split("::", limit = 2)
        return if (components.size == 2) {
            Pair(components[0].toIntOrNull(), components[1])
        } else {
            Pair(null, label)
        }
    }

    private fun initGenomeGroups() {
        val keys = defaultGenomes.keys.mapNotNull {
            getGenomeComponents(it).first
        }.toSet().sorted()

        for (optgroupIndex in keys) {

            if (optgroupIndex !in 1..3) {
                continue
            }

            val genusName = when (optgroupIndex) {
                1 -> "Norn"
                2 -> "Grendel"
                3 -> "Ettin"
                4 -> "Geat"
                else -> throw IndexOutOfBoundsException("Invalid genus int")
            }
            val optgroup = document.createElement("optgroup").unsafeCast<HTMLOptGroupElement>()
            optgroup.setAttribute("label", genusName)
            optgroup.setAttribute("data-genus", "" + optgroupIndex)
            groups[optgroupIndex] = optgroup
        }
    }

    override fun highlightErrors() {
        if (isValid()) {
            return
        }
        if (genomeFile?.filepath.isNullOrBlank()) {
            baseGenomeSelect.closest(".validatable-input-container")?.setAttribute("data-is-valid", "false")
        }
        if (genomeFile?.filename.isNullOrBlank()) {
            outputGenomeName.closest(".validatable-input-container")?.setAttribute("data-is-valid", "false")
        }
    }

    override fun isValid(): Boolean {
        val file = genomeFile
            ?: return isOptional
        return file.filepath.isNotNullOrBlank() && file.filename.isNotNullOrBlank()
    }

    companion object {
        private const val DISK_SELECT = "::$$$\$DISK$$$$::"
        private const val GENOME_DIRECTORY = "resource:genomes"
        private const val NONE_OPTION = "None"
    }

    private fun contentEquals(collection: Collection<String>, other: Collection<String>): Boolean {
        return collection.toSet().toTypedArray().contentEquals(other.toSet().toTypedArray())
    }
}