package com.bedalton.common.structs

open class CaselessMap<V>(): Map<String, V> {


    protected val map = mutableMapOf<String, V>()

    override val entries: MutableSet<MutableMap.MutableEntry<String, V>>
        get() = map.entries

    override val keys: MutableSet<String>
        get() = map.keys

    override val size: Int
        get() = map.size

    override val values: MutableCollection<V>
        get() = map.values

    constructor(original: Map<String, V>): this() {
        this.map.putAll(original)
    }

    override fun isEmpty(): Boolean = map.isEmpty()

    override fun get(key: String): V? {
        map[key]?.let {
            return it
        }
        val actualKey = getKey(key)
            ?: return null
        return map[actualKey]
    }

    override fun containsValue(value: V): Boolean {
        return map.containsValue(value)
    }

    override fun containsKey(key: String): Boolean {
        if (map.containsKey(key)) {
            return true
        }
        val keyLower = key.lowercase()
        return keys.any { it.lowercase() == keyLower }
    }

    protected fun getKey(key: String): String? {
        val keyLower = key.lowercase()
        return keys.firstOrNull { it.lowercase() == keyLower }
    }
}