package com.bedalton.creatures.caos.validation.internal

import com.bedalton.creatures.caos.collectors.CaosParserItem
import com.bedalton.creatures.caos.libs.CaosVariant
import com.bedalton.creatures.caos.libs.ErrorTypes


internal fun addEqErrors(
    variant: CaosVariant,
    items: Array<CaosParserItem>,
    errors: MutableList<CaosParserItem.ErrorVal>,
    checkCancelled: () -> Unit,
) {
    val eqOps = items.filterIsInstance<CaosParserItem.EqOp>()
    val validRegex = if (variant.isOld) {
        "EQ|NE|GT|GE|LT|LE|BT|BF".toRegex(RegexOption.IGNORE_CASE)
    } else {
        "EQ|NE|GT|GE|LT|LE|(<=)|(>=)|(<>)|<|>|=".toRegex(RegexOption.IGNORE_CASE)
    }
    for (op in eqOps) {
        checkCancelled()
        if (validRegex.matches(op.value))
            continue
        errors.add(
            CaosParserItem.ErrorVal(
                op.textRange,
                if (op.value == "!=") "Eq op '!=' is invalid. Use '<>' or 'ne' instead" else "EqOp '${op.value}' is invalid in $variant",
                type = ErrorTypes.OUT_OF_VARIANT,
                text = op.text
            )
        )
    }
    if (variant.isOld) {
        for (join in items.filterIsInstance<CaosParserItem.EqJoin>()) {
            errors.add(
                CaosParserItem.ErrorVal(
                    textRange = join.textRange,
                    message = "Equality joins are only available in CV+",
                    type = ErrorTypes.OUT_OF_VARIANT,
                    text = join.text
                )
            )
        }
    }
}