@file:Suppress("unused")

package com.bedalton.common.util

import kotlin.math.abs

infix fun Int.hasFlag(other:Int) : Boolean {
    return this and other == other
}

infix fun Int.doesNotHaveFlag(other:Int) : Boolean {
    return this and other == 0
}

infix fun Long.hasFlag(other:Int) : Boolean {
    val otherLong = other.toLong()
    return this and otherLong == otherLong
}

infix fun Long.doesNotHaveFlag(other:Int) : Boolean {
    val otherLong = other.toLong()
    return this and otherLong != otherLong
}

private const val comparisonTolerance = 0.0001
private val errorToleranceRange = -comparisonTolerance..comparisonTolerance

/**
 * Check that a float is near to zero within a given error tolerance
 */
val Float.zeroish get() = this in errorToleranceRange

/**
 * Check that a float is not near zero within a given error tolerance
 */
val Float.nonzero get() = this !in errorToleranceRange
/**
 * Check that a double is near to zero within a given error tolerance
 */
val Double.zeroish get() = this in errorToleranceRange
/**
 * Check that a double is not near zero within a given error tolerance
 */
val Double.nonzero get() = this !in errorToleranceRange

/**
 * Checks that a float is equal to another number within a given tolerance
 */
infix fun Float.eq(other: Float): Boolean {
    return abs(this - other) in errorToleranceRange
}
/**
 * Checks that a float is equal to another number within a given tolerance
 */
infix fun Float.eq(other: Double): Boolean {
    return abs(this - other) in errorToleranceRange
}

/**
 * Checks that a double is equal to another number within a given tolerance
 */
infix fun Double.eq(other: Double): Boolean {
    return abs(this - other) in errorToleranceRange
}

/**
 * Checks that a double is equal to another number within a given tolerance
 */
infix fun Double.eq(other: Float): Boolean {
    return abs(this - other) in errorToleranceRange
}

/**
 * Checks that a float is equal to another number within a given tolerance
 */
infix fun Float.ne(other: Float): Boolean {
    return abs(this - other) !in errorToleranceRange
}
/**
 * Checks that a float is equal to another number within a given tolerance
 */
infix fun Float.ne(other: Double): Boolean {
    return abs(this - other) !in errorToleranceRange
}

/**
 * Checks that a double is equal to another number within a given tolerance
 */
infix fun Double.ne(other: Double): Boolean {
    return abs(this - other) !in errorToleranceRange
}

/**
 * Checks that a double is equal to another number within a given tolerance
 */
infix fun Double.ne(other: Float): Boolean {
    return abs(this - other) !in errorToleranceRange
}


/**
 * Sets the number of decimal places equal to the number given
 */
expect fun Float.toFixed(decimalPlaces:Int) : String
/**
 * Sets the number of decimal places equal to the number given
 */
internal fun Float.toFixedFallback(decimalPlaces:Int) : String {
    return toString().toFixedFallback(decimalPlaces)
}

/**
 * Sets the number of decimal places equal to the number given
 */
expect fun Double.toFixed(decimalPlaces:Int) : String

/**
 * Sets the number of decimal places equal to the number given
 */
internal fun Double.toFixedFallback(decimalPlaces:Int) : String {
    return toString().toFixedFallback(decimalPlaces)
}

/**
 * Takes what is expected to be a string of a floating point number
 * and returns it with a fixed number of decimal places
 */
private fun String.toFixedFallback(decimal:Int) : String {
    val decimalIndex = this.indexOf('.')
    if (decimalIndex < 0)
        return this
    val parts = this.split('.')
    val tail = parts.last().let { last ->
        if (last.length == decimal)
            last
        else if (last.length < decimal)
            last.padEnd(decimal, '0')
        else
            last.substring(0, decimal)
    }
    return parts[0] + "." + tail
}