@JsExport
@Serializable
@SerialName("GeneFlags")
data class GeneFlags(
    //! @ProtoNumber(1)
    @SerialName("mutable")
    val mutable: Boolean = true,
    //! @ProtoNumber(2)
    @SerialName("duplicable")
    val duplicable: Boolean = true,
    //! @ProtoNumber(3)
    @SerialName("deletable")
    val deletable: Boolean = true,
    //! @ProtoNumber(4)
    @SerialName("male_only")
    val maleOnly: Boolean = false,
    //! @ProtoNumber(5)
    @SerialName("female_only")
    val femaleOnly: Boolean = false,
    //! @ProtoNumber(6)
    @SerialName("not_expressed")
    val notExpressed: Boolean = false,
    //! @ProtoNumber(7)
    @SerialName("reserved1")
    val reserved1: Boolean = false,
    //! @ProtoNumber(8)
    @SerialName("reserved2")
    val reserved2: Boolean = false,
) {

    val flag by lazy {
        var out = 0
        if (mutable) {
            out += 1
        }
        if (duplicable) {
            out += 2
        }
        if (deletable) {
            out += 4
        }
        if (maleOnly) {
            out += 8
        }
        if (femaleOnly) {
            out += 16
        }
        if (notExpressed) {
            out += 32
        }
        if (reserved1) {
            out += 64
        }
        if (reserved2) {
            out += 128
        }
        out
    }

    internal constructor(flag: Int) : this(
        mutable = flag hasFlag 1,
        duplicable = flag hasFlag 2,
        deletable = flag hasFlag 4,
        maleOnly = flag hasFlag 8,
        femaleOnly = flag hasFlag 16,
        notExpressed = flag hasFlag 32,
        reserved1 = flag hasFlag 64,
        reserved2 = flag hasFlag 128
    )

    fun withMutable(newValue: Boolean): GeneFlags {
        if (mutable == newValue) {
            return this
        }
        return this.copy(
            mutable = newValue
        )
    }

    fun withDuplicable(newValue: Boolean): GeneFlags {
        if (duplicable == newValue) {
            return this
        }
        return this.copy(
            duplicable = newValue
        )
    }

    fun withOnlyGender(gender: Int): GeneFlags {
        return when (gender) {
            0, 3 -> withEitherGender()
            1 -> withMaleOnly()
            2 -> withFemaleOnly()
            else -> {
                throw GeneException("Cannot set expressed gender to a value other than 0 (either), 1 (male) or 2(female). Found: <$gender>")
            }
        }
    }

    fun withMaleOnly(): GeneFlags {
        if (!femaleOnly && maleOnly) {
            return this
        }
        return copy(
            femaleOnly = false,
            maleOnly = true
        )
    }

    fun withFemaleOnly(): GeneFlags {
        if (femaleOnly && !maleOnly) {
            return this
        }
        return copy(
            femaleOnly = true,
            maleOnly = false
        )
    }

    fun withEitherGender(): GeneFlags {
        if (femaleOnly && maleOnly) {
            return this
        }
        return copy(
            femaleOnly = false,
            maleOnly = false
        )
    }

    fun withNotExpressed(newValue: Boolean): GeneFlags {
        if (notExpressed == newValue) {
            return this
        }
        return copy(
            notExpressed = newValue
        )
    }

    fun withReserved1(newValue: Boolean): GeneFlags {
        if (reserved1 == newValue) {
            return this
        }
        return copy(
            reserved1 = newValue
        )
    }


    fun withReserved2(newValue: Boolean): GeneFlags {
        if (reserved2 == newValue) {
            return this
        }
        return copy(
            reserved2 = newValue
        )
    }


    fun withDeletable(newValue: Boolean): GeneFlags {
        if (deletable == newValue) {
            return this
        }
        return this.copy(
            deletable = newValue
        )
    }

    internal fun write(writer: ByteStreamWriter): ByteStreamWriter {
        writer.writeUInt8(flag)
        return writer
    }

    companion object {
        internal fun fromReader(reader: ByteStreamReader): GeneFlags {
            return GeneFlags(reader.uInt8())
        }
    }
}

@JsExport
@Serializable
@SerialName("GeneHeader")
data class GeneHeader(
    //! @ProtoNumber(1)
    @SerialName("game_version")
    var gameVersion: Int,
    //! @ProtoNumber(2)
    @SerialName("flags")
    var flags: GeneFlags = GeneFlags(),
    //! @ProtoNumber(3)
    @SerialName("generation")
    var generation: Int = 0,
    //! @ProtoNumber(4)
    @SerialName("switch_on_time_int")
    var switchOnTimeInt: Int = 0,
    //! @ProtoNumber(5)
    @SerialName("mutation_weighting")
    var mutationWeighting: Int? = if (gameVersion > 1) 255 else null,
    //! @ProtoNumber(6)
    @SerialName("gene_variant")
    var geneVariant: Int? = if (gameVersion > 2) 0 else null
) {

    val mutable: Boolean get() = flags.mutable
    val duplicable: Boolean get() = flags.duplicable
    val deletable: Boolean get() = flags.deletable
    val maleOnly: Boolean get() = flags.maleOnly
    val femaleOnly: Boolean get() = flags.femaleOnly
    val notExpressed: Boolean get() = flags.notExpressed
    val reserved1: Boolean get() = flags.reserved1
    val reserved2: Boolean get() = flags.reserved2


    fun withGeneFlags(flags: GeneFlags): GeneHeader {
        return copy(flags = flags)
    }

    fun withGeneration(newGeneration: Int): GeneHeader {
        if (newGeneration == generation) {
            return this
        }
        return copy(
            generation = newGeneration
        )
    }


    fun withSwitchOnTime(newValue: Int): GeneHeader {
        if (switchOnTimeInt == newValue) {
            return this
        }
        return copy(
            switchOnTimeInt = newValue
        )
    }


    fun withMutationWeighting(newValue: Int): GeneHeader {
        if (mutationWeighting == newValue) {
            return this
        }
        return copy(
            mutationWeighting = newValue
        )
    }


    fun withGeneVariant(newValue: Int): GeneHeader {
        if (geneVariant == newValue) {
            return this
        }
        return copy(
            geneVariant = newValue
        )
    }

    internal fun write(writer: ByteStreamWriter): ByteStreamWriter {
        writer.writeUInt8(generation)
        writer.writeUInt8(switchOnTimeInt)
        flags.write(writer)
        if (gameVersion > 1) {
            writer.writeUInt8(mutationWeighting ?: 255)
        }
        if (gameVersion > 2) {
            writer.writeUInt8(geneVariant ?: 0)
        }
        return writer
    }

    companion object {
        internal fun fromReader(version: Int, reader: ByteStreamReader): GeneHeader {
            return GeneHeader(
                gameVersion = version,
                generation = reader.uInt8(),
                switchOnTimeInt = reader.uInt8(),
                flags = GeneFlags.fromReader(reader),
                mutationWeighting = if (version > 1) reader.uInt8() else null,
                geneVariant = if (version > 2) reader.uInt8() else null
            )
        }
    }

}


@JsExport
@Serializable
@SerialName("GeneNote")
data class GeneNote(
    //! @ProtoNumber(1)
    @SerialName("description")
    val description: String = "",
    //! @ProtoNumber(2)
    @SerialName("comments")
    val comments: String = "",
    //! @ProtoNumber(3)
    @SerialName("which")
    val which: Int = 0
)


@JsExport
@Serializable
@SerialName("Gene")
sealed class Gene {
    //! @ProtoNumber(1)
    @SerialName("versions")
    abstract val version: Int

    //! @ProtoNumber(2)
    @SerialName("gene_type")
    abstract val geneType: Int

    //! @ProtoNumber(3)
    @SerialName("gene_sub_type")
    abstract val geneSubType: Int

    //! @ProtoNumber(4)
    @SerialName("type_name")
    abstract val typeName: String

    //! @ProtoNumber(5)
    @SerialName("subtype_name")
    abstract val subtypeName: String

    //! @ProtoNumber(6)
    @SerialName("gene_index")
    abstract val geneIndex: Int

    //! @ProtoNumber(7)
    @SerialName("gene_index_of_type")
    abstract var geneIndexOfType: Int?

    //! @ProtoNumber(8)
    @SerialName("gene_header")
    abstract val geneHeader: GeneHeader

    //! @ProtoNumber(9)
    @SerialName("note")
    abstract val note: GeneNote?

    //! @ProtoNumber(10)
    @SerialName("description")
    abstract val description: String?

    //! @ProtoNumber(11)
    @SerialName("unexpected_invalid_trailing_data")
    internal var unexpectedInvalidTrailingData: List<ByteArray>? = null

    val geneVariant: Int? get() = geneHeader.geneVariant

    fun isGeneVariant(variant: Int?): Boolean {
        return variant == null || variant == 0 || geneVariant?.let { it == 0 || it == variant } != false
    }

    abstract fun withNote(newValue: GeneNote): Gene

    abstract fun withGeneHeader(newHeader: GeneHeader): Gene

    internal abstract fun writeData(writer: ByteStreamWriter)

    abstract fun toJSON(): String

    companion object {
        internal val json get() = Genome.json
    }
}


/**
 * Gene extension which adds optional data to genes
 */
@JsExport
@Serializable
@SerialName("GeneExtension")
sealed class GeneExtension

interface HasGeneExtension<ExtensionT : GeneExtension> {
    val extensionData: ExtensionT?
}