package com.creaturesforge.application.util

import com.bedalton.common.util.PathUtil
import com.bedalton.common.util.pathSeparatorChar
import com.bedalton.creatures.common.structs.BreedKey

internal fun pathSeparator(path: String): Char {
    return if (path.contains(pathSeparatorChar)) {
        pathSeparatorChar
    } else if (path.contains('/')) {
        '/'
    } else if (path.contains('\\')) {
        '\\'
    } else {
        pathSeparatorChar
    }
//!NOBACKSLASH    return '/'
}


internal fun isAttFile(filePath: String, breedKey: BreedKey? = null): Boolean {

    val fileName = (PathUtil.getLastPathComponent(filePath) ?: filePath)

    if (!fileName.lowercase().endsWith(".att")) {
        return false
    }

    if (breedKey == null) {
        return true
    }

    val fileBreedKey = BreedKey.fromFileName(fileName)
        ?: return false

    return fileBreedKey
        .copyWithAgeGroup(null)
        .copyWithGender(null)
        .isGenericMatchFor(breedKey)
}


internal expect suspend fun pushAttRootToFileScope(attDirectory: String?): Boolean