@file:Suppress("unused")

package com.bedalton.creatures.agents.util.internal

import com.bedalton.creatures.agents.pray.compiler.data.TextValue
import org.antlr.v4.kotlinruntime.ParserRuleContext


internal val ParserRuleContext.line get() = start!!.line
internal val ParserRuleContext.startIndex get() = start!!.startIndex
internal val ParserRuleContext.stopIndex get() = stop!!.stopIndex

internal fun ParserRuleContext.toCommandValueValue(): TextValue {
    return TextValue(
        lineNumber = line,
        startIndex = startIndex,
        endIndex = stopIndex,
        text = originalStringValue!!
    )
}