@file:Suppress("unused")

package com.bedalton.creatures.common.structs
import com.bedalton.creatures.common.structs.GameVariant.*
import kotlin.js.JsExport
import kotlin.js.JsName
import com.bedalton.common.util.nullIfEmpty
import kotlinx.serialization.*
import kotlinx.serialization.SerializationException
import kotlinx.serialization.descriptors.SerialDescriptor
import kotlinx.serialization.descriptors.buildClassSerialDescriptor
import kotlinx.serialization.descriptors.element
import kotlinx.serialization.encoding.CompositeDecoder
import kotlinx.serialization.encoding.Decoder
import kotlinx.serialization.encoding.Encoder
import kotlin.jvm.JvmStatic

@Serializable(with = GameVariantSerializer::class)
@JsExport
sealed class GameVariant(val code: String, val baseString: String? = null) {

    @JsName("C1")
    object C1 : GameVariant("C1")
    @JsName("C2")
    object C2 : GameVariant("C2")
    @JsName("CV")
    object CV : GameVariant("CV")
    @JsName("C3")
    object C3 : GameVariant("C3")
    @JsName("DS")
    object DS : GameVariant("DS")
    @JsName("SM")
    object SM : GameVariant("SM")

    private var mBase: GameVariant? = null

    @JsName("base")
    val base: GameVariant? get() {
        mBase?.let {
            return it
        }
        if (baseString == null) {
            return null
        }
        val out = fromString(baseString)
            ?: others.firstOrNull { it.code == baseString }
        mBase = out
        return out
    }

    class OtherVariant(code: String, base: String?): GameVariant(code, base) {

        init {
            if (this !in others) {
                others.add(this)
            }
        }

        override fun equals(other: Any?): Boolean {
            if (other === this) {
                return true
            }
            if (other !is GameVariant) {
                return false
            }
            return this.code == other.code
        }

        override fun hashCode(): Int {
            var result = code.hashCode()
            result = 31 * result + (base?.hashCode() ?: 0)
            return result
        }
    }

    override fun toString(): String {
        return code
    }

    override fun equals(other: Any?): Boolean {
        if (other === this) {
            return true
        }
        if (other !is GameVariant) {
            return false
        }
        return this.code == other.code
    }

    override fun hashCode(): Int {
        var result = code.hashCode()
        result = 31 * result + (base?.hashCode() ?: 0)
        return result
    }


    companion object {

        @JvmStatic
        fun fromString(value: String): GameVariant? {
            return when (value.uppercase()) {
                "C1" -> C1
                "C2" -> C2
                "CV" -> CV
                "C3" -> C3
                "DS" -> DS
                "SM" -> SM
                else -> null
            }
        }

        @JvmStatic
        val values get() = allGameVariants

        @Transient
        private val others = mutableListOf<OtherVariant>()
    }

}

val allGameVariants by lazy {
    arrayOf(
        C1,
        C2,
        CV,
        C3,
        DS,
        SM
    )
}


infix fun GameVariant?.like(aCode: String): Boolean {
    if (this == null) {
        return false
    }
    if ((aCode == code) || (this == C3 && aCode == "DS") || (this == DS && aCode == "C3")) {
        return true
    }
    return this.base != null && this.baseString.equals(code, ignoreCase=true)
}

infix fun String.like(variant: GameVariant?): Boolean {
    if (variant == null) {
        return false
    }
    val upper = this.uppercase()
    return (upper == variant.code)
            || (variant == C3 && upper == "DS")
            || (variant == DS && upper == "C3")
            || (this like variant.base)
}

infix fun GameVariant?.like(otherGameVariant: GameVariant?): Boolean {
    if (this == null || otherGameVariant == null) {
        return false
    }
    return  (this == otherGameVariant)
            || (otherGameVariant == C3 && this == DS)
            || (otherGameVariant == DS && this == C3)
            || (this like otherGameVariant.base)
}

infix fun GameVariant.notLike(code: String): Boolean {
    return !(this like code)
}

infix fun String.notLike(variant: GameVariant): Boolean {
    return !(this like variant)
}

infix fun GameVariant?.notLike(otherGameVariant: GameVariant): Boolean {
    return  !(this like otherGameVariant)
}

val GameVariant.isC1e: Boolean get() {
    return when(this) {
        C1 -> true
        C2 -> true
        else -> false
    }
}
val GameVariant.isC2e: Boolean get() {
    return when(this) {
        C1 -> false
        C2 -> false
        else -> true
    }
}

val GameVariant.isC3DS: Boolean get() = this like C3 || this like DS



@OptIn(kotlinx.serialization.ExperimentalSerializationApi::class)
object GameVariantSerializer: KSerializer<GameVariant> {
    override val descriptor: SerialDescriptor by lazy {
        buildClassSerialDescriptor("game-variant") {
            element<String>("code", isOptional = false)
            element<List<String>>("base", isOptional = true)
        }
    }

    override fun deserialize(decoder: Decoder): GameVariant {
        val descriptor = descriptor
        val ob = decoder.beginStructure(descriptor)
        var code: String? = null
        var base: String? = null
        var index: Int
        while (ob.decodeElementIndex(descriptor).also { index = it} != CompositeDecoder.DECODE_DONE) {
            when (index) {
                0 -> code = ob.decodeStringElement(descriptor, 0)
                1 -> base = ob.decodeStringElement(descriptor, 1)
                    .nullIfEmpty()
            }
        }
        ob.endStructure(descriptor)
        if (code == null) {
            throw SerializationException("Game variant is missing `code` property")
        }
        return when (code.uppercase()) {
            "C1" -> C1
            "C2" -> C2
            "CV" -> CV
            "C3" -> C3
            "DS" -> DS
            "SM" -> SM
            else -> OtherVariant(code, base)
        }
    }

    override fun serialize(encoder: Encoder, value: GameVariant) {
        val descriptor = descriptor
        val ob = encoder.beginStructure(descriptor)
        ob.encodeStringElement(descriptor, 0, value.code)
        if (value is OtherVariant && value.baseString != null) {
            ob.encodeStringElement(descriptor, 1, value.baseString)
        }
        ob.endStructure(descriptor)
    }

}