@file:Suppress("unused")

package com.bedalton.vfs

import com.bedalton.common.exceptions.rethrowCancellationException
import com.bedalton.common.util.*
import com.bedalton.io.bytes.ByteStreamReader
import com.bedalton.io.bytes.MemoryByteStreamReader
import com.bedalton.io.bytes.decodeToWindowsCP1252
import com.bedalton.log.LOG_DEBUG
import com.bedalton.log.Log
import com.bedalton.vfs.VfsSwitches.pathsMustBeAbsolute
import kotlin.js.JsName

/**
 * A file system that allows selected certain input files by file name over actual paths
 */
class FileSystemWithInputFiles(
    private var fileSystem: FileSystem,
    files: Map<String, File>,
    private var matchFileNameOnly: Boolean? = null,
    schema: String = MEMORY_SCHEMA,
    private val disposeExistingOnSet: Boolean = DISPOSE_EXISTING_DEFAULT
) : FileSystem {

    private val schema = schema.ensureEndsWith('/')

    // In the pair, the boolean is whether to ignore path and simply use file name
    private val files: MutableMap<String, Pair<Boolean?, File>> =
        files.mapValues { Pair(null, it.value) }.toMutableMap()

    private val written: MutableMap<String, File> = mutableMapOf()

    @JsName("constructWithFileSystemAndMatchType")
    constructor(fs: FileSystem, matchFileNameOnly: Boolean? = null) : this(fs, mapOf(), matchFileNameOnly)


    fun getVirtualFileList(): List<String> {
        return (files.keys + written.keys).distinct()
    }

    @JsName("setFileWithFilenameMatchType")
    operator fun set(fileName: String, disposeExisting: Boolean = disposeExistingOnSet, bytes: ByteArray, matchFileNameOnly: Boolean): FileSystemWithInputFiles {
        val path = makeMemoryVFSPath(fileName, schema)
        if (disposeExisting) {
            files[path]?.second?.dispose()
            written[path]?.dispose()
        }
        writeInternal(path, bytes, matchFileNameOnly)
        return this
    }

    operator fun set(fileName: String, disposeExisting: Boolean = disposeExistingOnSet, bytes: ByteArray): FileSystemWithInputFiles {
        val path = makeMemoryVFSPath(fileName, schema)
        if (disposeExisting) {
            files[path]?.second?.dispose()
            written[path]?.dispose()
        }
        writeInternal(path, bytes, matchFileNameOnly)
        return this
    }


    @JsName("setFileWithVirtualFile")
    operator fun set(fileName: String, disposeExisting: Boolean = disposeExistingOnSet, file: File): FileSystemWithInputFiles {
        val path = makeMemoryVFSPath(fileName, schema)
        if (disposeExisting) {
            files[path]?.second?.dispose()
            written[path]?.dispose()
        }
        files[path] = Pair(null, file)
        written[path] = file
        return this
    }


    @JsName("setFileWithMemoryFile")
    operator fun set(filePath: String, disposeExisting: Boolean = disposeExistingOnSet, file: MemoryFile) {
        val path = makeMemoryVFSPath(filePath, schema)
        if (disposeExisting) {
            files[path]?.second?.dispose()
            written[path]?.dispose()
        }
        files[path] = Pair(null, file)
        written[path] = file
    }


    suspend fun get(fileName: String): ByteArray {
        return read(fileName)
    }

    override suspend fun fileExists(path: String): Boolean {
        val memoryFilePath = makeMemoryVFSPath(path, schema)
        if (files.containsKey(memoryFilePath)) {
            return true
        }
        return (!pathsMustBeAbsolute || PathUtil.isAbsolute(path)) && fileSystem.fileExists(path)
    }

    override suspend fun isDirectory(path: String): Boolean {
        val directoryNormalize = makeMemoryVFSPath(path.normalized(), schema).ensureEndsWith('/')
        val directory = ("^$directoryNormalize.+").toRegex()
        if ((files.keys + written.keys).distinct().any { it.matches(directory) }) {
            return true
        }

        return (!pathsMustBeAbsolute || PathUtil.isAbsolute(path)) && fileSystem.isDirectory(path)
    }

    override suspend fun getChildrenNonRecursive(directory: String): List<String> {
        val prefix = makeMemoryVFSPath(directory, schema).ensureEndsWith('/')
        val memorySchemaLength = MEMORY_SCHEMA.length
        val memoryFiles: List<String> = (files.keys + written.keys).map {
            if (it.startsWith(MEMORY_SCHEMA)) {
                it.substring(memorySchemaLength)
            } else {
                it
            }
        }.distinct()
        val regex = (prefix.normalized() + "[^/]+").toRegex(RegexOption.IGNORE_CASE)
        return memoryFiles.filter { it.matches(regex) } + fileSystem.getChildrenNonRecursive(directory).orEmpty()
    }

    override suspend fun read(path: String): ByteArray {
        readAliasedFileOrNull(path)?.let {
            return it
        }
        if (pathsMustBeAbsolute && !isResourcePath(path)) {
            throw PathNotAbsoluteException(path)
        }
        return fileSystem.read(path)
    }

    private suspend fun readAliasedFileOrNull(path: String): ByteArray? {
        val file = getAliasedFileOrNull(path)
            ?: return null
        return try {
            file.read()
        } catch (e: Throwable) {
            e.rethrowCancellationException()
            if (Log.hasMode(LOG_DEBUG)) {
                Log.e {
                    "Failed to read file $path; ${e.className}: ${e.message}\n${e.stackTraceToString()}"
                }
            }
            null
        }
    }

    private fun getAliasedFileOrNull(path: String): File? {
        val memoryVFSPath = makeMemoryVFSPath(path, schema)
        files[memoryVFSPath]?.second?.let {
            return it
        }
        val fileName = (PathUtil.getLastPathComponent(path) ?: path).lowercase()
        return if (matchFileNameOnly == true) {
            files.values
                .firstOrNull {
                    it.second.name.lowercase() == fileName
                }?.second
        } else {
            return files.values
                .firstOrNull {
                    it.first == true && it.second.name.lowercase() == fileName
                }?.second
        }
    }

    override suspend fun write(path: String, data: ByteArray, append: Boolean) {

        val bytes = if (append) {
            readAliasedFileOrNull(path)?.let {
                it + data
            } ?: data
        } else {
            data
        }
        writeInternal(path, bytes, matchFileNameOnly)

        if (PathUtil.isAbsolute(path)) {
            fileSystem.write(path, data)
        }

    }

    private fun writeInternal(path: String, data: ByteArray, matchFileNameOnly: Boolean?) {
        val file = BinaryFile(
            PathUtil.getLastPathComponent(path) ?: path,
            data
        )
        val memoryPath = makeMemoryVFSPath(path, schema)
        set(memoryPath, disposeExistingOnSet, file)
        files[memoryPath] = Pair(matchFileNameOnly, file)
    }

    override suspend fun makeDirectory(path: String, recursive: Boolean): Boolean {
        if (PathUtil.isAbsolute(path)) {
            fileSystem.makeDirectory(path, recursive)
        }
        return true
    }

    override suspend fun delete(path: String): Boolean {
        val memoryPath = makeMemoryVFSPath(path, schema)
        files.remove(memoryPath)?.apply {
            second.dispose()
        }
        written.remove(memoryPath)?.apply {
            dispose()
        }
        if (PathUtil.isAbsolute(path) && fileSystem.fileExists(path)) {
            fileSystem.delete(path)
        }
        return true
    }

    override suspend fun canDeleteDirectory(path: String): Boolean {
        return false
    }

    override suspend fun deleteDirectory(path: String): Boolean {
        deleteDirectoryFilePairs(path, files)
        deleteDirectoryFileMap(path, written)
        if (PathUtil.isAbsolute(path) && canDeleteDirectory(path)) {
            fileSystem.deleteDirectory(path)
        }
        return true
    }

    private fun deleteDirectoryFilePairs(directory: String, files: MutableMap<String, Pair<Boolean?, File>>) {
        val directoryNormalized = makeMemoryVFSPath(directory, schema).ensureEndsWith('/')
        val keysToRemove = files.keys.filter { it.startsWith(directoryNormalized) }
        for (key in keysToRemove) {
            files[key]?.second?.dispose()
            files.remove(key)
        }
    }

    private fun deleteDirectoryFileMap(directory: String, files: MutableMap<String, File>) {
        val directoryNormalized = makeMemoryVFSPath(directory, schema).ensureEndsWith('/')
        val keysToRemove = files.keys.filter { it.startsWith(directoryNormalized) }
        for (key in keysToRemove) {
            files[key]?.dispose()
            files.remove(key)
        }
    }

    override suspend fun canMakeDirectories(): Boolean {
        return true
    }

    @Suppress("MemberVisibilityCanBePrivate")
    fun clearWritten() {
        written.clear()
    }

    fun clearCached(dispose: Boolean) {
        if (dispose) {
            files.values.forEach {
                it.second.dispose()
            }
        }
        files.clear()
        clearWritten()
    }

    fun getWritten(): Array<File> {
        return written.values.toTypedArray()
    }

    override suspend fun moveFile(fromFile: String, toFile: String, overwrite: Boolean): Int {
        val fromPathNormalize = makeMemoryVFSPath(fromFile, schema)
        val toPathNormalize = makeMemoryVFSPath(toFile, schema)
        if (!overwrite && files.containsKey(fromPathNormalize)) {
            return MOVED__TO_FILE_ALREADY_EXISTS
        }
        val file = files.remove(fromPathNormalize)
            ?: return MOVED__FROM_FILE_DOES_NOT_EXIST
        files[toPathNormalize] = file
        written.remove(fromPathNormalize)
        written[toPathNormalize] = file.second
        return MOVED__OK
    }

    fun makeTempFile(prefix: String, suffix: String?): String? {
        val suffixNonNull = suffix?.let { "-$it" } ?: ""
        var knocks = 20
        while (knocks-- > 0) {
            val tempFile = "/tmp/." + prefix + randomString(6) + suffixNonNull
            if (!files.containsKey(makeMemoryVFSPath(tempFile, schema))) {
                return tempFile
            }
        }
        return null
    }

    @Deprecated(
        "Root directory scopes are no longer checked",
        replaceWith = ReplaceWith("true")
    )
    override suspend fun accept(path: String): Boolean {
        return true
    }

    override suspend fun md5(path: String): String? {
        return try {
            MD5.compute(get(path)).toHexString()
        } catch (e: Throwable) {
            e.rethrowCancellationException()
            null
        }
    }

    override suspend fun read(path: String, offset: Long, length: Long): ByteArray? {
        return try {
            val bytes = get(path)
            bytes.sliceArray(offset.toInt()..(offset + length).toInt())
        } catch (e: Throwable) {
            e.rethrowCancellationException()
            null
        }
    }

    override suspend fun readAsStreamReader(path: String): ByteStreamReader {
        val bytes = get(path)
        return MemoryByteStreamReader(bytes)
    }

    override suspend fun readTextUTF8(path: String): String {
        return read(path).decodeToString()
    }

    override suspend fun readTextWindowsCP1252(path: String): String {
        return read(path).decodeToWindowsCP1252()
    }

    override fun isVirtualFileSystem(): Boolean {
        return true
    }

    internal fun getVirtual(): Map<String, File> {
        return files.mapValues { it.value.second }
    }

    fun withFiles(other: FileSystemWithInputFiles) {
        files.putAll(other.files)
    }

    fun withFiles(other: MemoryFileSystem) {
        for ((path, file) in other.getVirtual()) {
            this[path] = file
        }
    }

    companion object {
        private const val MAP_FILE_NAME_ONLY_DEFAULTS = true
    }
}