@file:Suppress("unused")

package com.bedalton.creatures.breed.render.renderer

import com.bedalton.creatures.breed.render.support.pose.PoseRenderException
import kotlin.js.JsExport
import kotlin.js.JsName

@JsExport
open class InvalidRenderValueException(
    message: String,
    val property: String,
    val value: Any?,
    val validValues: String? = null,
    throwable: Throwable? = null
)
    : PoseRenderException(message, throwable)

@JsExport
open class NotSingleCharException(
    message: String,
    property: String,
    value: Any?,
    throwable: Throwable? = null
): InvalidRenderValueException(message, property, value, "single char", throwable)


@JsExport
open class RenderValueOutOfRangeException(
    message: String,
    property: String,
    value: Any?,
    start: String,
    end: String,
    throwable: Throwable? = null
): InvalidRenderValueException(message, property, value, "[$start-$end]", throwable)

@JsExport
class MissingRenderValueException(
    message: String,
    val property: String,
    val missing: Array<String>,
    throwable: Throwable? = null
)
    : PoseRenderException(message, throwable) {
        internal constructor(message: String, property: String, missing: String, throwable: Throwable? = null):
                this(message, property, arrayOf(missing), throwable)
    }

@JsExport
class MissingPartBreedsException(message: String, val missing: Array<String>, throwable: Throwable? = null)
    : PoseRenderException(message, throwable)
