@file:Suppress("unused")

package com.bedalton.common.coroutines

import kotlinx.coroutines.*
import kotlin.coroutines.CoroutineContext
import kotlin.coroutines.coroutineContext

fun Throwable.rethrowIfCancellationException() {
    if (this is CancellationException || this is kotlin.coroutines.cancellation.CancellationException) {
        throw this
    }
}


suspend fun checkCancelled() {
    // Make sure coroutine has not been cancelled
    coroutineContext.ensureActive()
    if (!coroutineContext.isActive) {
        throw CancellationException("Coroutine was cancelled")
    }
}

fun CoroutineContext.checkCancelled() {
    ensureActive()
    if (!isActive) {
        throw CancellationException("Coroutine was cancelled")
    }
}

fun CoroutineScope.checkCancelled() {
    ensureActive()
    if (!isActive) {
        throw CancellationException("Coroutine was cancelled")
    }
}


fun Job.cancelIfRunning(cause: CancellationException? = null) {
    if (!isActive) {
        return
    }
    cancel(cause)
}

fun Job.cancelIfRunning(cause: String) {
    if (!isActive) {
        return
    }
    cancel(cause)
}


fun CoroutineScope.cancelIfRunning(cause: CancellationException? = null) {
    if (!isActive) {
        return
    }
    cancel(cause)
}

fun CoroutineScope.cancelIfRunning(cause: String) {
    if (!isActive) {
        return
    }
    cancel(cause)
}


fun CoroutineContext.cancelIfRunning(cause: CancellationException? = null) {
    if (!isActive) {
        return
    }
    cancel(cause)
}

fun CoroutineContext.cancelIfRunning(cause: String) {
    if (!isActive) {
        return
    }
    cancel(CancellationException(cause))
}

fun CoroutineContext.cancelIfRunning(cause: String, throwable: Throwable?) {
    if (!isActive) {
        return
    }
    cancel(CancellationException(cause, throwable))
}