@file:Suppress("unused")

package com.creaturesforge.application.interop

import com.creaturesforge.application.util.asThrowable
import com.creaturesforge.application.util.jsOb
import kotlinx.coroutines.await
import kotlin.js.Promise

internal fun <R> tauriInvoke(event: String, init: dynamic.() -> Unit = {}): Promise<R> {
    val payload = jsOb(init)
    try {
        return tauri.tauri.invoke(event, payload)
    } catch (e: dynamic) {
        throw asThrowable(e)
    }
}

internal fun <T, R> tauriInvokeTyped(event: String, init: T.() -> Unit = {}): Promise<R> {
    val payload = jsOb(init)
    try {
        return tauri.tauri.invoke(event, payload)
    } catch (e: dynamic) {
        throw asThrowable(e)
    }
}

internal suspend fun <R> tauriAsync(event: String, init: dynamic.() -> Unit = {}): R {
    val payload = jsOb(init)
    try {
        return tauri.tauri.invoke<dynamic, R>(event, payload).await()
    } catch (e: dynamic) {
        throw asThrowable(e)
    }
}

internal suspend fun <T,R> tauriAsyncTyped(event: String, init: T.() -> Unit = {}): R {
    val payload = jsOb(init)
    try {
        return tauri.tauri.invoke<T, R>(event, payload).await()
    } catch (e: dynamic) {
        throw asThrowable(e)
    }
}
