@file:Suppress("FunctionName")

package com.bedalton.creatures.caos.util

import com.bedalton.creatures.caos.collectors.ParseResult
import com.bedalton.creatures.caos.libs.caosJsonSerializer
import kotlinx.serialization.json.decodeFromDynamic

/**
 * Convert JS dynamic to Kotlin ParseResult
 *
 * @param parseResultDynamic
 * @return
 */
fun parseResultFromDynamic_JsApi(parseResultDynamic: dynamic): ParseResult? {
    return when {
        parseResultDynamic is ParseResult -> parseResultDynamic as? ParseResult
        parseResultDynamic != null -> caosJsonSerializer.decodeFromDynamic<ParseResult>(parseResultDynamic)
        else -> null
    }
}
