package com.bedalton.creatures.genetics.genome


import com.bedalton.creatures.genetics.gene.Gene
import com.bedalton.io.bytes.ByteStreamWriter
import kotlin.math.ceil

@Suppress("MemberVisibilityCanBePrivate", "unused")
object GenomeCompiler {

    private const val DEFAULT_WRITE_UNEXPECTED_TRAILING_DATA = false
    private val geneHeaderBytes = "gene".encodeToByteArray()
    private val genomeEndBytes = "gend".encodeToByteArray()

    fun compile(genome: Genome, pad: Boolean = genome.version != 3): ByteArray {
        return ByteStreamWriter.writeBytes {
            compile(genome, this, pad, writeUnexpectedTrailingData = null)
        }
    }

    fun compile(genome: Genome, pad: Boolean = genome.version != 3, writeUnexpectedTrailingData: Boolean? = null): ByteArray {
        return ByteStreamWriter.writeBytes {
            compile(genome, this, pad, writeUnexpectedTrailingData)
        }
    }

    fun compile(genome: Genome, writer: ByteStreamWriter, pad: Boolean = true, writeUnexpectedTrailingData: Boolean? = null): ByteStreamWriter {
        return compile(genome.version, genome.genes, writer, if (pad) (genome.originalSize ?: 1) else null, writeUnexpectedTrailingData)
    }

    internal fun compile(
        version: Int,
        genes: Array<Gene>,
        originalSize: Int? = null,
    ): ByteArray {
        return ByteStreamWriter.writeBytes {
            compile(version, genes, this, originalSize)
        }
    }

    internal fun compile(
        version: Int,
        genes: Array<Gene>,
        writer: ByteStreamWriter,
        originalSize: Int? = null,
        writeUnexpectedTrailingData: Boolean? = null
    ): ByteStreamWriter {
        if (version !in 1..3) {
            throw Exception("Genome version is invalid. Expected integer 1..3; Found: <$version>")
        }
        if (version > 1) {
            writer.writeStringWithCreaturesEncoding("dna$version")
        }
        writeGenes(genes, writer, writeUnexpectedTrailingData)
        writer.write(genomeEndBytes)
        if (originalSize != null) {
            pad(version, originalSize, writer)
        }
        return writer
    }

    private fun pad(genome: Genome, writer: ByteStreamWriter) {
        val currentSize = writer.size.toInt()
        val staticGeneLength = calculateStaticSize(genome.version, genome.originalSize, currentSize)
        if (staticGeneLength > currentSize) {
            val padding = ByteArray(staticGeneLength - currentSize) { 0 }
            writer.write(padding)
        }
    }

    private fun pad(version:Int, originalSize: Int?, writer: ByteStreamWriter) {
        val currentSize = writer.size.toInt()
        val staticGeneLength = calculateStaticSize(version, originalSize, currentSize)
        if (staticGeneLength > currentSize) {
            val padding = ByteArray(staticGeneLength - currentSize) { 0 }
            writer.write(padding)
        }
    }

    private fun calculateStaticSize(version:Int, originalSize: Int?, currentSize: Int): Int {
        var staticGeneLength = originalSize ?: (if (version == 1) 10001 else 36001)
        if (staticGeneLength > currentSize) {
            return staticGeneLength
        }
        var i = 1
        while(staticGeneLength <= currentSize) {
            when (i++) {
                1 -> staticGeneLength = 10001
                2 -> staticGeneLength = 20001
                3 -> staticGeneLength = 36001
                4 -> staticGeneLength = 48001
                5 -> staticGeneLength = 52001
                6 -> (ceil(currentSize / 1000.0) * 1000).toInt() + 1
            }
        }
        return staticGeneLength
    }

    private fun writeGenes(genes: Array<Gene>, writer: ByteStreamWriter, writeUnexpectedTrailingData: Boolean?) {
        val indexOfType = mutableMapOf<String, Int>()
        genes.forEach { gene ->
            val index: Int = indexOfType["${gene.geneType}:${gene.geneSubType}"]?.let { it + 1 } ?: 0
            indexOfType["${gene.geneType}:${gene.geneSubType}"] = index
            writeGene(writer, gene.geneIndexOfType ?: index, gene, writeUnexpectedTrailingData)
        }
    }

    fun writeGenesBytePairs(genes: Collection<Gene>): List<GeneBytePair> {
        val indexOfType = mutableMapOf<String, Int>()
        return genes.map { gene ->
            val index: Int = indexOfType["${gene.geneType}:${gene.geneSubType}"]?.let { it + 1 } ?: 0
            indexOfType["${gene.geneType}:${gene.geneSubType}"] = index
            GeneBytePair.fromGene(gene, index)
        }
    }

    private fun writeGene(writer: ByteStreamWriter, newGeneNumber: Int, gene: Gene, writeUnexpectedTrailingData: Boolean?) {
        writer
            .write(geneHeaderBytes)
            .writeUInt8(gene.geneType)
            .writeUInt8(gene.geneSubType)
            .writeUInt8(newGeneNumber)
        gene.geneHeader.write(writer)
        gene.writeData(writer)
        if (writeUnexpectedTrailingData ?: DEFAULT_WRITE_UNEXPECTED_TRAILING_DATA) {
            gene.unexpectedInvalidTrailingData?.forEach { writer.write(it) }
        }
    }
}

