@file:Suppress("unused")

package com.bedalton.common.util


val Any?.className: String?
    get() = this?.let { it::class.simpleName }


fun <T> T?.orElse(other: T): T {
    return this ?: other
}

fun Boolean?.orFalse(): Boolean {
    return this ?: false
}

fun Boolean?.orTrue(): Boolean {
    return this ?: false
}