@file:Suppress("unused")

package com.bedalton.io.bytes

import com.bedalton.io.bytes.internal.decodeToWindowsCP1252EncodingFallback
import org.khronos.webgl.ArrayBuffer
import org.khronos.webgl.DataView

// Temporary byte holder to run JS native function to get float or double values
private val readBuffer = DataView(ArrayBuffer(8))

/**
 * Reads a float from this stream reader
 */
actual fun float(reader: ByteStreamReader): Float {
        val bytes = reader.bytes(4)
        bytes.mapIndexed { i, byte ->
            readBuffer.setInt8(i, byte)
        }

        return readBuffer.getFloat32(0, true)
    }


/**
 * Reads a double from this stream reader
 */
actual fun double(reader: ByteStreamReader): Double {
        val bytes = reader.bytes(8)
        bytes.mapIndexed { i, byte ->
            readBuffer.setInt8(i, byte)
        }
        return readBuffer.getFloat64(0, true)
    }

/**
 * Decode a CP1252 encoded string from its bytes
 */
actual fun ByteArray.decodeToWindowsCP1252(start: Int, endExclusive: Int?): String {
    return decodeToWindowsCP1252EncodingFallback(start, endExclusive)
}
