@JsExport
@Serializable
@SerialName("BiochemicalReactionGene")
data class BiochemicalReactionGene(
    // @ProtoNumber(1)
    @SerialName("version")
    override val version: Int,
    // @ProtoNumber(6)
    @SerialName("gene_index")
    override val geneIndex: Int,
    // @ProtoNumber(7)
    @SerialName("gene_index_of_type")
    override var geneIndexOfType: Int?,
    // @ProtoNumber(8)
    @SerialName("gene_header")
    override val geneHeader: GeneHeader = GeneHeader(version),
    //! @ProtoNumber(12)
	@SerialName("from")
	val from: Array<ChemicalAmount> = Array(REACTANTS_COUNT) { ChemicalAmount(reverse = true) },
    //! @ProtoNumber(13)
	@SerialName("to")
	val to: Array<ChemicalAmount> = Array(OUTPUT_COUNTS) { ChemicalAmount(reverse = true) },
    //! @ProtoNumber(14)
	@SerialName("rate")
	val rate: Int = 0,
    // @ProtoNumber(9)
    @SerialName("node")
    override val note: GeneNote? = null,
) : Gene() {

    override val geneType: Int
        get() = GENE_TYPE_BIOCHEMICAL

    override val geneSubType: Int
        get() = GENE_SUBTYPE_BIOCHEMICAL_REACTION

    override val typeName: String
        get() = GENE_TYPE_NAME_BIOCHEMICAL

    override val subtypeName: String
        get() = GENE_SUBTYPE_NAME_BIOCHEMICAL_REACTION

    override val description: String? get() = null


    init {
        assertValid()
    }

    override fun withGeneHeader(newHeader: GeneHeader): BiochemicalReactionGene {
        return copy(
            geneHeader = newHeader
        )
    }

    override fun withNote(newValue: GeneNote): BiochemicalReactionGene {
        return copy(
            note = newValue
        )
    }

    fun withReactantAtIndex(index: Int, chemical: Int, amount: Int): BiochemicalReactionGene {
        if (index !in 0..REACTANTS_COUNT) {
            throw GeneFormatException("Cannot set from reactant outside of range 0..${REACTANTS_COUNT}; Found: $index")
        }
        if (chemical !in 0..255) {
            throw GeneFormatException("Cannot set reactant to chemical outside valid range of 0..255; Found: $chemical")
        }
        if (amount !in 0..255) {
            throw GeneFormatException("Cannot set reactant to chemical amount outside valid range of 0..255; Chemical: $chemical; Amount: $amount")
        }
        return copy(
            from = from.copyOf().apply {
                this[index] = ChemicalAmount(chemical, amount)
            }
        )
    }

    fun withOutputAtIndex(index: Int, chemical: Int, amount: Int): BiochemicalReactionGene {
        if (index !in 0..OUTPUT_COUNTS) {
            throw GeneFormatException("Cannot set from reaction output outside of range 0..${REACTANTS_COUNT}; Found: $index")
        }
        if (chemical !in 0..255) {
            throw GeneFormatException("Cannot set reaction output to chemical outside valid range of 0..255; Found: $chemical")
        }
        if (amount !in 0..255) {
            throw GeneFormatException("Cannot set reaction output to chemical amount outside valid range of 0..255; Chemical: $chemical; Amount: $amount")
        }
        return copy(
            to = to.copyOf().apply {
                this[index] = ChemicalAmount(chemical, amount)
            }
        )
    }

    fun withRate(newValue: Int): BiochemicalReactionGene {
        return copy(
            rate = newValue
        )
    }

    private fun assertValid() {
        if (from.size != REACTANTS_COUNT) {
            throw GeneFormatException("Invalid reactants count. Expected: $REACTANTS_COUNT; Found: ${from.size}")
        }
        if (to.size != OUTPUT_COUNTS) {
            throw GeneFormatException("Invalid output count. Expected: $OUTPUT_COUNTS; Found: ${to.size}")
        }
    }

    override fun writeData(writer: ByteStreamWriter) {
        from.forEach {
            it.write(writer)
        }
        to.forEach {
            it.write(writer)
        }
        writer.writeUInt8(rate)
    }


    override fun toJSON(): String {
        return json.encodeToString(serializer(), this)
    }

    override fun equals(other: Any?): Boolean {
        if (this === other) return true
        if (other == null || this::class != other::class) return false

        other as BiochemicalReactionGene

        if (version != other.version) return false
        if (geneIndex != other.geneIndex) return false
        if (geneIndexOfType != other.geneIndexOfType) return false
        if (geneHeader != other.geneHeader) return false
        if (!from.contentEquals(other.from)) return false
        if (!to.contentEquals(other.to)) return false
        if (rate != other.rate) return false
        return note == other.note
    }

    override fun hashCode(): Int {
        var result = version
        result = 31 * result + geneIndex
        result = 31 * result + (geneIndexOfType ?: 0)
        result = 31 * result + geneHeader.hashCode()
        result = 31 * result + from.contentHashCode()
        result = 31 * result + to.contentHashCode()
        result = 31 * result + rate
        result = 31 * result + (note?.hashCode() ?: 0)
        return result
    }

    companion object {
        internal const val REACTANTS_COUNT = 2
        internal const val OUTPUT_COUNTS = 2


        internal fun fromReader(version: Int, reader: ByteStreamReader, geneIndex: Int) = BiochemicalReactionGene(
            version,
            geneIndex = geneIndex,
            geneIndexOfType = reader.uInt8(),
            geneHeader = GeneHeader.fromReader(version, reader),
            Array(REACTANTS_COUNT) { chemicalAmountFromReader(reader, true) },
            Array(OUTPUT_COUNTS) { chemicalAmountFromReader(reader, true) },
            reader.uInt8()
        )
    }
}

