    fun withLobeNeurons(neurons: Array<LobeNeuron>, copyArray: Boolean = true): NeuroEmitterGene {
        if (neurons.size != LOBE_NEURON_COUNT) {
            throw GeneFormatException("Cannot set lobe neurons to array with a size != $LOBE_NEURON_COUNT; Found: ${neurons.size}")
        }
        return copy(
            lobeNeuron = if (copyArray) neurons.copyOf() else neurons
        )
    }

    fun withRate(newValue: Int): NeuroEmitterGene {
        return copy(
            rate = newValue
        )
    }

    fun withChemicalAmountAt(index: Int, chemical: Int, amount: Int): NeuroEmitterGene {
        return withChemicalAmountAt(index, ChemicalAmount(chemical, amount))
    }

    fun withChemicals(chemicals: Array<ChemicalAmount>, copyArray: Boolean = true): NeuroEmitterGene {
        if (chemicals.size != CHEMICAL_COUNT) {
            throw GeneFormatException("Cannot set lobe neuron chemicals to array with a size != $CHEMICAL_COUNT; Found: ${chemicals.size}")
        }
        return copy(
            chemicals = if (copyArray) chemicals.copyOf() else chemicals
        )
    }

    @JsName("withChemicalAmountObjectAt")
    fun withChemicalAmountAt(index: Int, amount: ChemicalAmount): NeuroEmitterGene {
        if (index !in 0..CHEMICAL_COUNT) {
            throw GeneFormatException("Cannot set chemical at an index outside the valid range of 0..$CHEMICAL_COUNT; Found: $index")
        }
        return copy(
            chemicals = chemicals.copyOf().apply {
                this[index] = amount
            }
        )
    }

    override val geneType: Int
        get() = GENE_TYPE_BIOCHEMICAL

    override val typeName: String
        get() = GENE_TYPE_NAME_BIOCHEMICAL

    override val geneSubType: Int
        get() = GENE_SUBTYPE_NEURO_CHEMICAL_EMITTER

    override val subtypeName: String
        get() = GENE_SUBTYPE_NAME_NEURO_CHEMICAL_EMITTER

    override val description: String? get() = null

    override fun writeData(writer: ByteStreamWriter) {
        writer
            .write(lobeNeuron) {
                writeUInt8(it.lobe)
                writeUInt8(it.neuron)
            }
            .writeUInt8(rate)
            .write(chemicals) {
                it.write(this)
            }
    }

    private fun assertValid() {
        if (lobeNeuron.size != LOBE_NEURON_COUNT) {
            throw GeneFormatException("NeuroEmitter expects $LOBE_NEURON_COUNT lobe neuron pairs. Found: ${lobeNeuron.size}")
        }
        if (chemicals.size != CHEMICAL_COUNT) {
            throw GeneFormatException("NeuroEmitter expects $CHEMICAL_COUNT chemical amounts. Found: ${chemicals.size}")
        }
    }

    override fun toJSON(): String {
        return json.encodeToString(serializer(), this)
    }

    override fun equals(other: Any?): Boolean {
        if (this === other) return true
        if (other == null || this::class != other::class) return false

        other as NeuroEmitterGene

        if (version != other.version) return false
        if (geneIndex != other.geneIndex) return false
        if (geneIndexOfType != other.geneIndexOfType) return false
        if (geneHeader != other.geneHeader) return false
        if (!lobeNeuron.contentEquals(other.lobeNeuron)) return false
        if (rate != other.rate) return false
        if (!chemicals.contentEquals(other.chemicals)) return false
        return note == other.note
    }

    override fun hashCode(): Int {
        var result = version
        result = 31 * result + geneIndex
        result = 31 * result + (geneIndexOfType ?: 0)
        result = 31 * result + geneHeader.hashCode()
        result = 31 * result + lobeNeuron.contentHashCode()
        result = 31 * result + rate
        result = 31 * result + chemicals.contentHashCode()
        result = 31 * result + (note?.hashCode() ?: 0)
        return result
    }


    companion object {
        private const val LOBE_NEURON_COUNT = 3
        private const val CHEMICAL_COUNT = 4

        internal fun fromReader(version: Int, reader: ByteStreamReader, geneIndex: Int) = NeuroEmitterGene(
            version,
            geneIndex = geneIndex,
            geneIndexOfType = reader.uInt8(),
            geneHeader = GeneHeader.fromReader(version, reader),
            Array(3) { LobeNeuron.fromReader(reader) },
            reader.uInt8(),
            Array(4) { chemicalAmountFromReader(reader) }
        )
    }
}

@JsExport
@Serializable
@SerialName("LobeNeuron")
data class LobeNeuron(
    //! @ProtoNumber(1)
	@SerialName("lobe")
	val lobe: Int = 0,
    //! @ProtoNumber(2)
	@SerialName("neuron")
	val neuron: Int = 0,
) {


    fun withLobe(newValue: Int): LobeNeuron {
        return copy(
            lobe = newValue
        )
    }

    fun withNeuron(newValue: Int): LobeNeuron {
        return copy(
            neuron = newValue
        )
    }


    internal fun write(writer: ByteStreamWriter) {
        writer
            .writeUInt8(lobe)
            .writeUInt8(neuron)
    }

    companion object {
        internal fun fromReader(reader: ByteStreamReader) = LobeNeuron(
            reader.uInt8(),
            reader.uInt8()
        )
    }
}

internal fun chemicalAmountFromReader(reader: ByteStreamReader, reverse: Boolean = false) = ChemicalAmount(
    if (reverse) {
        reader.peakUInt8(1)!!
    } else {
        reader.uInt8()
    },
    if (reverse) {
        reader.uInt8().apply { reader.skip(1) }
    } else {
        reader.uInt8()
    },
    reverse
).apply {
    if (chemical !in 0..255) {
        throw GeneFormatException("Cannot set chemical outside of valid range 0..255; Found: $chemical")
    }
}



internal fun ChemicalAmount.write(writer: ByteStreamWriter) {
    if (reverse) {
        writer.writeUInt8(amount)
        writer.writeUInt8(chemical)
    } else {
        writer.writeUInt8(chemical)
        writer.writeUInt8(amount)
    }
}