package com.creaturesforge.application.ui

import com.bedalton.common.util.nullIfEmpty
import com.creaturesforge.application.util.jsOb
import com.bedalton.common.exceptions.rethrowCancellationException
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Job
import kotlinx.coroutines.await
import kotlinx.coroutines.launch
import kotlinx.html.*
import org.w3c.dom.HTMLButtonElement
import org.w3c.dom.HTMLElement
import org.w3c.dom.events.Event
import tauri.dialog.DialogFilter
import tauri.dialog.save

internal class FileInput(
    val folder: Boolean,
    val isOpenInput: Boolean,
    initialValue: String?,
    parent: FlowContent,
) {

    var title: String? = null
    var filters: MutableList<DialogFilter> = mutableListOf()

    private var mValue = initialValue

    private val changeHandlers = mutableListOf<(String?)->Unit>()

    var value: String?
        get() = mValue
        set(value) {
            if (mValue == value) {
                return
            }
            mValue = value
            pathLabel.innerText = value ?: ""
            changeHandlers.forEach { it(value) }
        }

    val fileOrFolderLabel get() = if (folder) "Folder" else "File"

    val inputElement: HTMLElement = create(parent, initialValue)

    val pathLabel: HTMLElement by lazy {
        inputElement.querySelector(".path-label") as HTMLElement
    }

    val inputButton: HTMLButtonElement by lazy {
        (inputElement.querySelector("button") as HTMLButtonElement)
            .apply {
                addEventListener("click", ::onInputButtonClicked)
            }
    }

    fun getValue(): String? {
        return pathLabel.innerText.nullIfEmpty()
    }

    private fun onInputButtonClicked(@Suppress("UNUSED_PARAMETER") e: Event?) {
        CoroutineScope(Job()).launch {
            try {
                if (isOpenInput) {
                    open()
                } else {
                    save()
                }
            } catch (e: Exception) {
                e.rethrowCancellationException()
            }
        }
    }

    private suspend fun open() {
        val title = title
        val filters = filters.toTypedArray()
        val selection = openSingle {
            this.filters = filters
            this.title = title
            this.defaultPath = value
            this.directory = folder
            this.multiple = false
            this.recursive = folder
        } ?: return
        value = fileOf(selection)
    }

    private suspend fun save() {
        val title = title
        val filters = filters.toTypedArray()
        val selection = save(jsOb {
            this.title = title
            this.filters = filters
            this.defaultPath = value
        }).await()
        value = fileOf(selection)
    }

    private fun create(parent: FlowContent, initialValue: String?): HTMLElement {
        var out: TagConsumer<*>? = null
        parent.div {
            out = this.consumer
            this.classes += "file-input"
            p {
                this.classes += "path-label"
                +(initialValue?: "")
            }
            button {
                +"Select $fileOrFolderLabel"
            }
        }
        return out!!.finalize() as HTMLElement
    }

    fun onChange(handler: (file:String?) -> Unit): () -> Unit {
        if (!changeHandlers.contains(handler)) {
            changeHandlers.add(handler)
        }
        return {
            changeHandlers.remove(handler)
        }
    }
}


@HtmlTagMarker
internal fun FlowContent.inputFile(isOpenInput: Boolean, initialValue: String? = null, init: FileInput.()->Unit = {}): FileInput {
    return FileInput(folder = false, isOpenInput, initialValue, this).apply {
        init()
    }
}
@HtmlTagMarker
internal fun FlowContent.inputFolder(isOpenInput: Boolean, initialValue: String? = null, init: FileInput.()->Unit = {}): FileInput {
    return FileInput(folder = true, isOpenInput, initialValue, this).apply {
        init()
    }
}