package com.bedalton.creatures.agents.pray.compiler

import com.bedalton.common.util.JsExport

/**
 * Compile result object holding the com.bedalton.creatures.pray.path to written .agents file as well as the compiled bytes
 */
@JsExport
data class CompileResult(
    val outputFile: String?,
    val bytes: ByteArray,
) {
    override fun equals(other: Any?): Boolean {
        if (this === other) return true
        if (other !is CompileResult) return false

        if (outputFile != other.outputFile) return false
        if (!bytes.contentEquals(other.bytes)) return false

        return true
    }

    override fun hashCode(): Int {
        var result = outputFile.hashCode()
        result = 31 * result + bytes.contentHashCode()
        return result
    }
}