const val WINDOWS_ABSOLUTE_DRIVE_PREFIX_STRING = "^[a-zA-Z]:[\\\\/]{1,2}"

val WINDOWS_DRIVE_ROOT = "${WINDOWS_ABSOLUTE_DRIVE_PREFIX_STRING}$".toRegex()

val WINDOWS_ABSOLUTE_PATH_PREFIX = "^[a-zA-Z]:[\\\\/]{1,2}.*".toRegex()

internal fun pathSeparator(@Suppress("UNUSED_PARAMETER") path: String): Char {
//!BACKSLASH    return if (path.contains(pathSeparatorChar)) {
