@file:Suppress("unused")

package com.bedalton.vfs

import com.bedalton.common.exceptions.IOReadException
import com.bedalton.common.structs.mutableCaselessMapOf
import com.bedalton.common.structs.toMutableCaselessMap
import com.bedalton.common.util.*
import com.bedalton.io.bytes.ByteStreamReader
import com.bedalton.io.bytes.MemoryByteStreamReader
import com.bedalton.io.bytes.decodeToWindowsCP1252
import com.bedalton.common.exceptions.rethrowCancellationException

class MemoryFileSystem(
    files: Map<String, File>,
    private val disposeExistingOnSet: Boolean = DISPOSE_EXISTING_DEFAULT,
) : FileSystem {

    private val files: MutableMap<String, File> = files.toMutableCaselessMap()

    private val written: MutableMap<String, File> = mutableCaselessMapOf()

    constructor() : this(mapOf())

    operator fun set(
        fileName: String,
        disposeExisting: Boolean = disposeExistingOnSet,
        bytes: ByteArray
    ): MemoryFileSystem {
        val path = makeMemoryVFSPath(fileName)
        if (disposeExisting) {
            files[path]?.dispose()
        }
        writeInternal(path, bytes)
        return this
    }

    operator fun set(fileName: String, disposeExisting: Boolean = disposeExistingOnSet, file: File): MemoryFileSystem {
        val path = makeMemoryVFSPath(fileName)
        if (disposeExisting) {
            files[path]?.dispose()
        }
        files[path] = file
        written[path] = file
        return this
    }

    operator fun set(filePath: String, disposeExisting: Boolean = disposeExistingOnSet, file: MemoryFile) {
        val path = makeMemoryVFSPath(filePath)
        if (disposeExisting) {
            files[path]?.dispose()
        }
        files[path] = file
        written[path] = file
    }

    suspend fun get(fileName: String): ByteArray {
        val file = files[makeMemoryVFSPath(fileName)]
            ?: throw FileNotFoundException(fileName)
        return file.read()
    }

    override suspend fun fileExists(path: String): Boolean {
        return files.containsKey(makeMemoryVFSPath(path))
    }

    override suspend fun isDirectory(path: String): Boolean {
        val directoryNormalize = makeMemoryVFSPath(path.normalized().ensureEndsWith('/'))
        val directory = ("^$directoryNormalize.+").toRegex()
        return (files.keys + written.keys).distinct().any { it.matches(directory) }
    }

    override suspend fun getChildrenNonRecursive(directory: String): List<String> {
        val prefix = makeMemoryVFSPath(directory).ensureEndsWith('/')
        val children = (files.keys + written.keys).distinct().filter {
            it.startsWith(prefix)
        }
        val regex = (prefix.normalized() + "[^/]+").toRegex(RegexOption.IGNORE_CASE)
        return children.filter { it.normalized().matches(regex) }
    }

    override suspend fun read(path: String): ByteArray {
        val absolutePath = makeMemoryVFSPath(path)
        return files[absolutePath]?.read()
            ?: throw IOReadException("Failed to read memory file: $path")
    }

    private suspend fun readInternal(path: String): ByteArray? {
        val absolutePath = makeMemoryVFSPath(path)
        return files[absolutePath]?.read()
    }

    override suspend fun write(path: String, data: ByteArray, append: Boolean) {
        val bytes = if (append) {
            readInternal(path)?.let {
                it + data
            } ?: data
        } else {
            data
        }
        val file = BinaryFile(
            PathUtil.getLastPathComponent(path) ?: path,
            bytes
        )
        set(path, disposeExistingOnSet, file)
    }

    private fun writeInternal(path: String, data: ByteArray) {
        val file = BinaryFile(
            PathUtil.getLastPathComponent(path) ?: path,
            data
        )
        set(path, disposeExistingOnSet, file)
    }

    override suspend fun makeDirectory(path: String, recursive: Boolean): Boolean {
        return true
    }

    override suspend fun delete(path: String): Boolean {
        files.remove(makeMemoryVFSPath(path))?.apply {
            dispose()
        }
        written.remove(makeMemoryVFSPath(path))?.apply {
            dispose()
        }
        return true
    }

    override suspend fun canDeleteDirectory(path: String): Boolean {
        return true
    }

    override suspend fun deleteDirectory(path: String): Boolean {
        deleteDirectory(path, files)
        deleteDirectory(path, written)
        return true
    }

    private fun deleteDirectory(directory: String, files: MutableMap<String, File>) {
        val directoryNormalized = makeMemoryVFSPath(directory).ensureEndsWith('/')
        val keysToRemove = files.keys.filter { it.startsWith(directoryNormalized) }
        for (key in keysToRemove) {
            files[key]?.dispose()
            files.remove(key)
        }
    }

    override suspend fun canMakeDirectories(): Boolean {
        return true
    }

    fun clearWritten() {
        written.clear()
    }

    fun getWritten(): Array<File> {
        return written.values.toTypedArray()
    }

    override suspend fun moveFile(fromFile: String, toFile: String, overwrite: Boolean): Int {
        val fromPathNormalize = makeMemoryVFSPath(fromFile)
        val toPathNormalize = makeMemoryVFSPath(toFile)
        if (!overwrite && files.containsKey(fromPathNormalize)) {
            return MOVED__TO_FILE_ALREADY_EXISTS
        }
        val file = files.remove(makeMemoryVFSPath(fromPathNormalize))
            ?: return MOVED__FROM_FILE_DOES_NOT_EXIST
        files[toPathNormalize] = file
        written.remove(fromPathNormalize)
        written[toPathNormalize] = file
        return MOVED__OK
    }

    fun makeTempFile(prefix: String, suffix: String?): String? {
        val suffixNonNull = suffix?.let { "-$it" } ?: ""
        var knocks = 20
        while (knocks-- > 0) {
            val tempFile = "/tmp/." + prefix + randomString(6) + suffixNonNull
            if (!files.containsKey(makeMemoryVFSPath(tempFile))) {
                return tempFile
            }
        }
        return null
    }

    @Deprecated(
        "Root directory scopes are no longer checked",
        replaceWith = ReplaceWith("true")
    )
    override suspend fun accept(path: String): Boolean {
        return true
    }

    override suspend fun md5(path: String): String? {
        return try {
            MD5.compute(get(path)).toHexString()
        } catch (e: Throwable) {
            e.rethrowCancellationException()
            null
        }
    }

    override suspend fun read(path: String, offset: Long, length: Long): ByteArray? {
        return try {
            val bytes = get(path)
            bytes.sliceArray(offset.toInt()..(offset + length).toInt())
        } catch (e: Throwable) {
            e.rethrowCancellationException()
            null
        }
    }

    override suspend fun readAsStreamReader(path: String): ByteStreamReader {
        val bytes = get(path)
        return MemoryByteStreamReader(bytes)
    }

    override suspend fun readTextWindowsCP1252(path: String): String {
        return read(path).decodeToWindowsCP1252()
    }

    override suspend fun readTextUTF8(path: String): String {
        return read(path).decodeToString()
    }

    override fun isVirtualFileSystem(): Boolean {
        return true
    }

    internal fun getVirtual(): Map<String, File> {
        return files.toMap()
    }

    fun withFiles(other: MemoryFileSystem) {
        files.putAll(other.files)
    }

    fun withFiles(other: FileSystemWithInputFiles) {
        files.putAll(other.getVirtual())
    }
}


internal const val MEMORY_SCHEMA = "memory:"

internal const val DISPOSE_EXISTING_DEFAULT = false

internal fun makeMemoryVFSPath(fileName: String, schema: String = MEMORY_SCHEMA): String {
    return if (fileName.startsWith(schema))
        fileName
    else if (fileName.startsWith('/')) {
        if (schema.endsWith('/')) {
            schema + fileName.substring(1)
        } else {
            schema + fileName
        }
    } else if (schema.endsWith('/')) {
        schema + fileName
    } else {
        "$schema/$fileName"
    }
}


