package com.bedalton.creatures.caos.libs

import kotlinx.serialization.Serializable
import kotlin.js.JsExport
import kotlin.js.JsName

/**
 * A documentation object for a CAOS command
 */
@JsExport
@JsName("ICaosCommand")
@Serializable
data class VariantCaosCommand(
    /**
     * The command word or words
     */
    @JsName("command")
    val command: String,

    /**
     * The list of parameters as documentation objects
     */
    @JsName("parameters")
    val parameters: Array<VariantCaosParameter>,

    /**
     * Whether this command can function as an lvalue
     */
    @JsName("isLvalue")
    val isLvalue: Boolean,

    /**
     * Whether this command can function as an rvalue
     */
    @JsName("isRvalue")
    val isRvalue: Boolean,

    /**
     * Whether this command is block level and cannot be used as an r/l value
     */
    @JsName("isCommand")
    val isCommand: Boolean = !(isRvalue || isLvalue),

    /**
     * The internal type id for what this command returns.
     * Returns 8 for non-r/l values
     */

    @JsName("returnTypeId")
    val returnTypeId: Int,

    /**
     * The human-readable name for the return type such as "integer", "float", "string"
     */
    @JsName("returnTypeName")
    val returnTypeName: String,

    /**
     * Which variants this specific implementation of this command is valid for
     * Some commands have the same command word, but different parameters or meaning
     */
    @JsName("variants")
    val variants: Array<String>,

    /**
     * A description of what this command does
     */
    @JsName("description")
    val description: String?,

    /**
     * The name for the value that follows this in SETV when used as lvalue
     */
    @JsName("lvalueName")
    val lvalueName: String? = null,

    /**
     * Values list associated with this command scoped by variant
     */
    @JsName("returnValuesListIds")
    val returnValuesListIds: VariantData<Int>? = null,

    /**
     * Whether this command requires an owner object
     */
    @JsName("requiresOwnr")
    val requiresOwnr: Int = 0,

    /**
     * The group this command is associated with such as "physics", "creatures", "sprites"
     */
    @JsName("commandGroup")
    val commandGroup: String,

    /**
     * The format to use when folding a doif equality statement into easier to understand text
     */
    @JsName("doifFormat")
    val doifFormat: String? = null,

    /**
     * Whether this command must be used in the context of a Creature owner
     */
    @JsName("requiresCreatureOwnr")
    val requiresCreatureOwnr: Boolean = false,
) {

    /**
     * Get the return values list for this variant
     */
    @Suppress("unused")
    @JsName("returnValuesList")
    fun returnValuesList(variant: String): CaosValuesList? {
        val listId = returnValuesListIds?.get(variant)
            ?: return null
        return getValuesList(listId)
    }

    /**
     * Custom equals to deal with the arrays parameter
     */
    override fun equals(other: Any?): Boolean {
        if (this === other) return true
        if (other !is VariantCaosCommand) return false

        if (command != other.command) return false
        if (!parameters.contentEquals(other.parameters)) return false
        if (isLvalue != other.isLvalue) return false
        if (isRvalue != other.isRvalue) return false
        if (isCommand != other.isCommand) return false
        if (returnTypeId != other.returnTypeId) return false
        if (returnTypeName != other.returnTypeName) return false
        if (!variants.contentEquals(other.variants)) return false
        if (description != other.description) return false
        if (lvalueName != other.lvalueName) return false
        if (returnValuesListIds != other.returnValuesListIds) return false
        if (requiresOwnr != other.requiresOwnr) return false
        if (commandGroup != other.commandGroup) return false
        if (doifFormat != other.doifFormat) return false
        if (requiresCreatureOwnr != other.requiresCreatureOwnr) return false

        return true
    }

    /**
     * Custom hashcode implementation to handle array values in object
     */
    override fun hashCode(): Int {
        var result = command.hashCode()
        result = 31 * result + parameters.contentHashCode()
        result = 31 * result + isLvalue.hashCode()
        result = 31 * result + isRvalue.hashCode()
        result = 31 * result + isCommand.hashCode()
        result = 31 * result + returnTypeId
        result = 31 * result + returnTypeName.hashCode()
        result = 31 * result + variants.contentHashCode()
        result = 31 * result + (description?.hashCode() ?: 0)
        result = 31 * result + (lvalueName?.hashCode() ?: 0)
        result = 31 * result + (returnValuesListIds?.hashCode() ?: 0)
        result = 31 * result + requiresOwnr
        result = 31 * result + commandGroup.hashCode()
        result = 31 * result + (doifFormat?.hashCode() ?: 0)
        result = 31 * result + requiresCreatureOwnr.hashCode()
        return result
    }

}