@file:Suppress("unused")

package com.bedalton.creatures.sprite.compilers

import com.bedalton.common.util.PathUtil
import korlibs.image.bitmap.Bitmap32
import korlibs.image.format.*

object ImageLoader {

    @Suppress("MemberVisibilityCanBePrivate")
    val supportedFormats by lazy {
        mapOf(
            "PNG" to PNG,
            "BMP" to BMP,
            "GIF" to GIF
        )
    }

    val supportedExtensions by lazy {
        supportedFormats.keys
    }

    private fun getDecoder(extension: String): ImageFormat? {
        val extensionUpper = extension.uppercase()
        return supportedFormats[extensionUpper]
            ?: (if (extensionUpper == "PSD") PSD else null)
    }

    fun load(fileExtension: String, imageBytes: ByteArray): Bitmap32 {
        val decoder = getDecoder(fileExtension)
            ?: throw Exception("File type for extension: '$fileExtension' is not supported")
        return decoder.decode(imageBytes).toBMP32IfRequired()
    }

    fun supported(extension: String): Boolean {
        return extension.uppercase() in supportedFormats
    }

    internal fun loadMany(images: List<Pair<String, ByteArray>>, callback: ((current: Int, total: Int) -> Boolean?)?): List<Bitmap32> {
        val errors = mutableListOf<Pair<String, String>>()
        val total = images.size
        val bitmaps = images.mapIndexedNotNull load@{ i, (fileName, bytes) ->
            callback?.invoke(i, total)
            try {
                val fileExtension = PathUtil.getExtension(fileName)
                if (fileExtension.isNullOrBlank()) {
                    errors.add(Pair(fileName, "Unsupported file extension: '$fileExtension' for file '$fileName'"))
                    return@load null
                }
                load(fileExtension, bytes).apply {
                    callback?.invoke(i, total)
                }

            } catch (e: Exception) {
                val errorClass = e::class.simpleName
                val message = if (errorClass.equals("Exception", ignoreCase = true))
                    "Error: ${e.message}"
                else
                    "$errorClass: ${e.message}"

                errors.add(Pair(fileName, "Failed to load image '$fileName'; $message"))
                null
            }
        }
        callback?.invoke(total, total)
        if (errors.isNotEmpty())
            throw LoadManyException(errors)
        return bitmaps
    }

}

@Suppress("MemberVisibilityCanBePrivate")
internal class LoadManyException(
    internal val errors: List<Pair<String, String>>,
    message: String = "Failed to load all image files. Errors loading: ${errors.map { it.first }}]",
    throwable: Throwable? = null
): Exception(message, throwable)