@file:OptIn(DelicateCoroutinesApi::class)

import com.bedalton.creatures.sprite.parsers.BlkParser
import com.bedalton.creatures.sprite.parsers.SprSetDecompiler
import com.bedalton.creatures.sprite.parsers.SpriteParser
import com.bedalton.creatures.sprite.util.dynamicToPaletteTransform
import com.bedalton.io.bytes.MemoryByteStreamReader
import korlibs.image.format.PNG
import kotlinx.coroutines.DelicateCoroutinesApi
import kotlinx.coroutines.GlobalScope
import kotlinx.coroutines.asPromise
import kotlinx.coroutines.async
import kotlin.js.Promise


@JsExport
fun parseSpriteWithTransparency(
    fileName: String,
    bytes: ByteArray,
    progressChunkSize: Int = 1,
    progressCallback: ((current: Int, total: Int) -> Boolean)? = null,
): Promise<Array<ByteArray>> {
    return GlobalScope.async {
        parseSprite(fileName, bytes, false, progressChunkSize, progressCallback)
    }.asPromise()
}

@JsExport
fun parseSpriteKeepingBlack(
    fileName: String,
    bytes: ByteArray,
    progressChunkSize: Int = 1,
    progressCallback: ((current: Int, total: Int) -> Boolean)? = null,
): Promise<Array<ByteArray>> {
    return GlobalScope.async {
        parseSprite(fileName, bytes, true, progressChunkSize, progressCallback)
    }.asPromise()
}

private suspend fun parseSprite(
    fileName: String,
    bytes: ByteArray,
    keepBlack: Boolean,
    progressChunkSize: Int = 1,
    progressCallback: ((current: Int, total: Int) -> Boolean?)? = null,
): Array<ByteArray> {
    return SpriteParser
        .parseAsync(fileName, MemoryByteStreamReader(bytes), keepBlack, progressChunkSize, progressCallback)
        .map {
            PNG.encode(it)
        }
        .toTypedArray()
}

private fun parseSpriteWithColorTransform(
    fileName: String,
    bytes: ByteArray,
    transform: dynamic,
    keepBlack: Boolean,
    progressChunkSize: Int = 1,
    progressCallback: ((current: Int, total: Int) -> Boolean?)? = null,
): Array<ByteArray> {
    return SpriteParser.parse(
        fileName,
        MemoryByteStreamReader(bytes),
        keepBlack,
        dynamicToPaletteTransform(transform),
        progressChunkSize,
        progressCallback
    )
        .map {
            PNG.encode(it)
        }
        .toTypedArray()
}

@JsExport
fun stitchBlkToPng(
    blkBytes: ByteArray,
    progressCallback: ((pass: Int, index: Int, cellsCount: Int) -> Boolean?)? = null,
): Promise<ByteArray> {
    return GlobalScope.async {
        val stitched = BlkParser.parse(MemoryByteStreamReader(blkBytes), 5, progressCallback)
        PNG.encode(stitched)
    }.asPromise()
}

@JsExport
fun stitchBlkToPngAsync(
    blkBytes: ByteArray,
    progressChunkSize: Int,
    progressCallback: ((pass: Int, index: Int, cellsCount: Int) -> Boolean?)? = null,
): Promise<ByteArray> {
    return GlobalScope.async {
        val stitched = BlkParser.parse(MemoryByteStreamReader(blkBytes), progressChunkSize, progressCallback)
        PNG.encode(stitched)
    }.asPromise()
}


/**
 * Parse a short format SPR file
 * Could be multi-sprite SPR file or single short-format SPR
 */
@JsExport
fun decompileSprSet(
    bytes: ByteArray,
    keepBlack: Boolean,
    progressChunkSize: Int? = null,
    progressCallback: ((pass: Int, index: Int, cellsCount: Int) -> Boolean?)? = null,
): Promise<Array<Array<ByteArray>>?> {
    return GlobalScope.async {
        val sets = SprSetDecompiler.decompileSets(
            MemoryByteStreamReader(bytes),
            keepBlack,
            progressChunkSize = progressChunkSize,
            progressCallback
        )

        val list: List<Array<ByteArray>>? = sets?.map { spriteFile ->
            spriteFile.frames()
                .map { PNG.encode(it) }
                .toTypedArray()
        }

        list?.toTypedArray()
    }.asPromise()
}
