package com.bedalton.creatures.genetics.parser

import com.bedalton.creatures.genetics.gene.*
import com.bedalton.creatures.genetics.gene.GeneConstants.GENE_SUBTYPE_BRAIN_LOBE
import com.bedalton.creatures.genetics.gene.GeneConstants.GENE_SUBTYPE_BRAIN_ORGAN
import com.bedalton.creatures.genetics.gene.GeneConstants.GENE_SUBTYPE_BRAIN_TRACT
import com.bedalton.creatures.genetics.gene.GeneConstants.GENE_TYPE_BRAIN
import com.bedalton.io.bytes.ByteStreamReader


internal fun readBrainGene(version: Int, reader: ByteStreamReader, geneIndex: Int): Gene {

    return when (val subType = reader.uInt8()) {
        GENE_SUBTYPE_BRAIN_LOBE -> readBrainLobe(version, reader, geneIndex)
        GENE_SUBTYPE_BRAIN_ORGAN -> OrganGene.fromReader(version, GENE_TYPE_BRAIN, subType, reader, geneIndex)
        GENE_SUBTYPE_BRAIN_TRACT -> BrainTractGene.fromReader(version, reader, geneIndex)
        else -> throw GenomeParseException("Failed to understand gene type: Brain(0)->[$subType]")
    }
}


internal fun readBrainLobe(version: Int, reader: ByteStreamReader, geneIndex: Int): BrainLobeGene {
    return if (version < 3) {
        OldBrainLobeGene.fromReader(version, reader, geneIndex)
    } else {
        NewBrainLobeGene.fromReader(version, reader, geneIndex)
    }
}
