package com.creaturesforge.application.state

import com.bedalton.common.util.PathUtil
import com.bedalton.common.util.formatted
import com.bedalton.log.*
import com.creaturesforge.application.util.*
import kotlinx.coroutines.await
import tauri.fs.BaseDirectories
import tauri.fs.FsOptions
import com.bedalton.common.exceptions.rethrowCancellationException


internal actual object ConfigLoader {


    private const val CONFIG_FILE_NAME = "eggforge.config.json"

    private var config: ForgeConfigData? = null
    private var lastSerialized: String = ""
    private var mFullPath: String? = null
    private val emptyConfig = ForgeConfigData()

    private var mLoadedOnce = false
    internal actual val loadedOnce get() = mLoadedOnce

    private val tauriFsOptions: FsOptions = jsOb {
        val directory = BaseDirectories.APPCONFIG
        this.dir = directory
    }

    actual suspend inline fun saveConfig(config: ForgeConfigData): Boolean {

        if (config == emptyConfig) {
            return true
        }

        ensureConfigDirectory()

        val fullPath = getFullPath()

        val configJSON = try {
            json.encodeToString(ForgeConfigData.serializer(), config)
        } catch (e: Throwable) {
            e.rethrowCancellationException()

            Log.e(LOG_DEBUG) {
                "Failed to convert config to JSON for serialization; ${e.formatted(true)}"
            }

            Log.eWith(LOG_CONSOLE) { "Failed to convert config to JSON for serialization; ${e.formatted(true)}" }
            return false
        }


        val thisSerialized = try{
            jsonNoDefaults.encodeToString(ForgeConfigData.serializer(), config)
                .replace("[\r\n\t]+".toRegex(), " ")
        } catch (e: Throwable){
            e.rethrowCancellationException()
            Log.e("Error serializing settings without defaults; ${e.formatted(true)}")
            configJSON
        }


        if (this.lastSerialized == thisSerialized) {
            return true
        }

        this.lastSerialized = thisSerialized

        try {
            tauri.fs.writeTextFile(CONFIG_FILE_NAME, configJSON, tauriFsOptions)
            this.config = config
            return true
        } catch (e: Throwable) {
            e.rethrowCancellationException()
            Log.eIf(LOG_DEBUG) {
                "Failed to save config to$fullPath; ${e.formatted(true)}"
            }
            return false
        }
    }

    actual suspend inline fun getConfigLoading(cached: Boolean): ForgeConfigData {
        if (cached) {
            config?.let {
                return it
            }
        }
        ensureConfigDirectory()
        val dataJson: String = try {
            if (tauri.fs.exists(CONFIG_FILE_NAME, tauriFsOptions).await()) {
                tauri.fs.readTextFile(CONFIG_FILE_NAME, tauriFsOptions).await()
            } else {
                null
            }
        } catch (e: Throwable) {
            e.rethrowCancellationException()
            Log.eWith(LOG_CONSOLE) { "Failed to read config; ${e.formatted(true)}" }
            null
        } ?: return ForgeConfigData().also {
            mLoadedOnce = true
        }



        return try {
            json.decodeFromString(ForgeConfigData.serializer(), dataJson).also {
                mLoadedOnce = true
                config = it
            }
        } catch (e: Throwable) {
            e.rethrowCancellationException()
            Log.e { "Failed to load existing config; ${e.formatted(true)}" }
            Log.eWith(LOG_CONSOLE) { "Failed to load existing config; ${e.formatted(true)}" }
            ForgeConfigData().also {
                mLoadedOnce = true
            }
        }
    }

    private suspend fun ensureConfigDirectory(): Boolean {
        val appConfigDirectory = tauri.path.appConfigDir().await()
        tauri.fs.createDir(appConfigDirectory, jsOb { recursive = true }).await()
        return true
    }

    private suspend fun getFullPath(): String {
        mFullPath?.let {
            return it
        }
        val dir = tauri.path.appConfigDir().await()
        val path = PathUtil.combine(dir, CONFIG_FILE_NAME)
        mFullPath = path
        return path
    }
}