package com.creaturesforge.application.ui

import com.creaturesforge.application.ui.ModalManager.getDialog
import com.creaturesforge.application.ui.html.*
import kotlinx.browser.document
import org.w3c.dom.HTMLDialogElement
import org.w3c.dom.HTMLElement
import org.w3c.dom.events.Event
import org.w3c.dom.events.KeyboardEvent

internal object ModalManager {

    private val modals = mutableListOf<Pair<HTMLDialogElement, Boolean>>()

    private var hasOpenModals by BooleanAttributeOf("data-open-modal", document.body!!)

    init {
        document.body!!.addEventListener("keyup", this::onKeyUp, true)
    }

    fun close(modal: HTMLDialogElement) {
        modal.close()
        remove(modal)
    }

    fun show(modal: HTMLDialogElement, isModal: Boolean) {
        val existing = modals.filter { it.first == modal }
        existing.forEach {
            modals.remove(it)
            it.first.removeEventListener("close", this::onClose)
        }
        modals.forEach { it.first.removeAttribute("data-active-modal") }
        modals.add(Pair(modal, isModal))
        if (existing.isEmpty()) {
            modal.addEventListener("close", this::onClose)
            modal.attribute("data-active-modal", true)
            modal.attribute("data-is-modal", isModal)
        }
        modal.show()
        modal.unhide()
        modal.ariaHidden = false
    }

    private fun onKeyUp(e: Event): dynamic {
        val key = (e as KeyboardEvent).key.lowercase()
        val shouldCancel = if (key == "escape") {
            !pop(false)
        } else {
            false
        }
        if (shouldCancel && e.getDialog() != null) {
            e.preventDefault()
            e.stopPropagation()
            return false
        }
        return e
    }


    private fun Event.getDialog(): HTMLDialogElement? {
        val target = target as HTMLElement
        val element = if (target.tagName.lowercase() == "dialog") {
            target
        } else {
            target.closest("dialog")
        } ?: return null

        return element as HTMLDialogElement
    }

    private fun pop(force: Boolean = true): Boolean {
        val modal = this.modals.removeLastOrNull()
            ?: return true
        return if (!modal.second || force) {
            close(modal.first)
            true
        } else {
            false
        }
    }

    private fun onClose(e: Event) {
        val modal = e.getDialog()
            ?: return
        remove(modal)
    }

    private fun remove(modal: HTMLDialogElement) {
        modals.removeAll { it.first == modal }
        modal.removeEventListener("close", this::onClose)
        modal.hide()
        modal.ariaHidden = true
        val isActiveModal = modal.getBoolean("data-active-modal", false)
        modal.attribute("data-active-modal", false)
        if (isActiveModal) {
            modals.lastOrNull()?.first?.attribute("data-active-modal", true)
        }
        hasOpenModals = modals.isNotEmpty()
    }

}