package com.bedalton.creatures.agents.pray.compiler

import kotlin.js.JsExport
import kotlin.js.JsName

@JsExport
open class PrayCompilerOptionsBuilder(
    private val pure: Boolean = false,
) : PrayCompileOptions,
    PrayCompileOptionsWithOverrideName,
    PrayCompileOptionsWithRecursiveJoin,
    PrayCompileOptionsWithLinkWithFileName
{

    @Suppress("NON_EXPORTABLE_TYPE")
    @JsName("fromCompilerTask")
    constructor(task: PrayCompileOptions, pure: Boolean = false) : this(pure) {
        this.mMergeScripts = task.mergeScripts
        this.mMergeRscr = task.mergeRscr
        this.mJoins = task.joins.copyOf()
        this.mGenerateScriptRemovers = task.generateScriptRemovers
        this.mGenerateAgentRemovers = task.generateAgentRemovers
        this.mValidate = task.validate
        this.mIsJoin = task.isJoin
        this.mCompressionLevel = task.compressionLevel
        this.mRecursiveJoins = task.recursiveJoinsOrNull
        this.mOverrideAgentName = task.overrideAgentNameOrNull
    }

    // ===================== //
    // === Merge Scripts === //
    // ===================== //

    protected var mMergeScripts: Boolean? = null

    /**
     * Whether to merge all scripts into one script
     */
    override val mergeScripts: Boolean
        get() = this.mMergeScripts ?: CompilerOptionsDefault.DEFAULT_MERGE_SCRIPTS

    /**
     * Whether to merge all scripts into one script
     */
    fun withMergeScripts(merge: Boolean?): PrayCompilerOptionsBuilder {
        return copy {
            this.mMergeScripts = merge
        }
    }

    // ================ //
    // === VALIDATE === //
    // ================ //
    protected var mValidate: Boolean? = null

    /**
     * Whether to validate the syntax and links in a pray file
     */
    fun withValidate(validate: Boolean?): PrayCompilerOptionsBuilder {
        return copy {
            this.mValidate = validate
        }
    }

    /**
     * Whether to validate the syntax and links in a pray file
     */
    override val validate: Boolean
        get() = this.mValidate ?: CompilerOptionsDefault.DEFAULT_VALIDATE

    // === Is Join === //
    protected var mIsJoin: Boolean? = null

    /**
     * Whether this agent is meant to be merged into a multi-agent bundle
     */
    override val isJoin: Boolean get() = mIsJoin ?: CompilerOptionsDefault.DEFAULT_IS_JOIN

    /**
     * Whether this agent is meant to be merged into a multi-agent bundle
     */
    fun withIsJoin(join: Boolean?): PrayCompilerOptionsBuilder {
        return copy {
            this.mIsJoin = join
        }
    }

    /**
     * Mark this agent as needing to be merged into a multi-agent bundle
     */
    override fun asJoin(): PrayCompilerOptionsBuilder {
        return copy {
            this.mIsJoin = true
        }
    }

    // ===================== //
    // ======= JOINS ======= //
    // ===================== //

    protected var mJoins: Array<String> = emptyArray()

    /**
     * Array of PRAY files for agents that should be merged into a single agent bundle
     */
    override val joins: Array<String>
        get() = mJoins


    /**
     * Array of PRAY files for agents that should be merged into a single agent bundle
     */
    override fun withJoins(joins: Array<String>): PrayCompilerOptionsBuilder {
        return copy {
            this.mJoins = joins
        }
    }

    // ================================ //
    // === Generate Script Removers === //
    // ================================ //
    protected var mGenerateScriptRemovers: Boolean? = null

    /**
     * Whether to automatically generate removers for all event scripts in PRAY source
     */
    override val generateScriptRemovers: Boolean
        get() = mGenerateScriptRemovers ?: CompilerOptionsDefault.DEFAULT_GENERATE_SCRIPT_REMOVERS

    /**
     * Whether to automatically generate removers for all event scripts in PRAY source
     */
    fun withGenerateScriptRemovers(generate: Boolean?): PrayCompilerOptionsBuilder {
        return copy {
            this.mGenerateScriptRemovers = generate
        }
    }

    // =============================== //
    // === Generate Agent Removers === //
    // =============================== //
    protected var mGenerateAgentRemovers: Boolean? = null

    /**
     * Create removers for all created agent classifiers
     * Parses new: (simp|comp|*) creation statements and generates a remover for that class
     */
    override val generateAgentRemovers: Boolean
        get() = this.mGenerateAgentRemovers ?: CompilerOptionsDefault.DEFAULT_GENERATE_AGENT_REMOVERS

    /**
     * Create removers for all created agent classifiers
     * Parses new: (simp|comp|*) creation statements and generates a remover for that class
     */
    fun withGenerateAgentRemovers(generate: Boolean?): PrayCompilerOptionsBuilder {
        return copy {
            this.mGenerateAgentRemovers = generate
        }
    }

    // ================== //
    // === Merge RSCR === //
    // ================== //

    protected var mMergeRscr: Boolean? = null

    /**
     * Whether to merge all removal scripts into a single massive removal script
     */
    override val mergeRscr: Boolean
        get() = mMergeRscr ?: CompilerOptionsDefault.DEFAULT_MERGE_RSCR

    /**
     * Whether to merge all removal scripts into a single massive removal script
     */
    fun withMergeRscr(merge: Boolean?): PrayCompilerOptionsBuilder {
        return copy {
            this.mMergeRscr = merge
        }
    }

    // ========================== //
    // === JOIN KEEP FILENAME === //
    // ========================== //
    protected var mLinkFilenameWithReference: Boolean? = null

    /**
     * Whether to add a comment at start of linked script with filename
     */
    override val linkWithFilenameReference: Boolean? get() = mLinkFilenameWithReference

    /**
     * Whether to add a comment at start of linked script with filename
     */
    fun withLinkWithFilenameReference(link: Boolean?): PrayCompilerOptionsBuilder {
        mLinkFilenameWithReference = link
        return this
    }

    // ================== //
    // ==  Compression == //
    // ================== //


    protected var mCompressionLevel: Int? = null

    /**
     * Level of GZIP compression to apply [0-9]; 0=None; 9=Max
     */
    override val compressionLevel: Int?
        get() = mCompressionLevel

    /**
     * Level of GZIP compression to apply [0-9]; 0=None; 9=Max
     */
    fun withCompressionLevel(level: Int?): PrayCompilerOptionsBuilder {
        return this.copy {
            this.mCompressionLevel = level
        }
    }

    // ====================== //
    // ==  Recursive Joins == //
    // ====================== //

    protected var mRecursiveJoins: Boolean? = null

    override val recursiveJoins: Boolean? get() = mRecursiveJoins

    fun withRecursiveJoins(recursive: Boolean?): PrayCompilerOptionsBuilder {
        mRecursiveJoins = recursive
        return this
    }


    // ====================== //
    // ==  Recursive Joins == //
    // ====================== //
    protected var mOverrideAgentName: String? = null
    override val overrideAgentName: String?
        get() = mOverrideAgentName

    fun setOverrideAgentName(value: String?): PrayCompilerOptionsBuilder {
        this.mOverrideAgentName = value
        return this
    }


    // ================== //
    // === Copy === //
    // ================== //

    open fun copy(pure: Boolean = this.pure): PrayCompilerOptionsBuilder {
        val out = PrayCompilerOptionsBuilder(pure)
        out.mMergeRscr = mMergeRscr
        out.mMergeScripts = mMergeScripts
        out.mIsJoin = mIsJoin
        out.mJoins = mJoins.copyOf()
        out.mGenerateAgentRemovers = mGenerateAgentRemovers
        out.mGenerateScriptRemovers = mGenerateScriptRemovers
        out.mValidate = mValidate
        out.mCompressionLevel = mCompressionLevel
        return out
    }

    @JsName("__private_copy_with_builder")
    protected fun copy(work: PrayCompilerOptionsBuilder.() -> Unit): PrayCompilerOptionsBuilder {
        return (if (pure) copy() else this).apply {
            this.work()
        }
    }

}