@file:Suppress("unused")

package com.bedalton.creatures.agents.pray.data

import com.bedalton.creatures.agents.pray.compiler.writeBlockHeader
import com.bedalton.creatures.sprite.compilers.S16Compiler
import com.bedalton.creatures.sprite.parsers.SpriteParser
import com.bedalton.io.bytes.ByteStreamWriter
import com.bedalton.io.bytes.MemoryByteStreamReader
import korlibs.image.bitmap.Bitmap32
import korlibs.image.format.PNG


class PhotBlock(
    blockTag: String,
    blockName: String,
    private val bytes: () -> ByteArray
) : PrayBlock(blockTag, blockName) {

    private val mFile by lazy {
        SpriteParser.parse("PHOT.s16", MemoryByteStreamReader(bytes()), true)[0]
    }

    @Suppress("MemberVisibilityCanBePrivate")
    fun toBMP32(): Bitmap32 {
        return mFile
    }

    fun toPNG(): ByteArray {
        return PNG.encode(toBMP32())
    }

    override fun write(writer: ByteStreamWriter, compress: Boolean) {
        writeBlockHeader(writer, this)
        writer.write(
            S16Compiler.compileSpriteFromLoadedImages(listOf(toBMP32()), keepBlack = true)
        )
    }
}

