package com.creaturesforge.application.state

import com.bedalton.state.simple.Dispatch
import com.bedalton.state.simple.Next

internal fun defaultsMiddleware(
    state: ForgeState,
    action: FAction,
    dispatch: Dispatch<FAction>,
    next: Next<ForgeState, FAction>
): FAction {

    val defaultSlot = state
        .spriteSlot
        ?: state.getAvailableSpriteSlots()
            .singleOrNull()

    if (action !is SetBreedSlotAction && state.breedSlot == null && defaultSlot != null) {
        dispatch(SetBreedSlotAction(defaultSlot))
    }

    if (action !is SetSpriteSlotAction && state.spriteSlot == null && defaultSlot != null) {
        dispatch(SetSpriteSlotAction(defaultSlot))
    }

    if (action !is SetAttSlotAction && state.attRoot != null && state.attSlot == null) {
        state.getAvailableAttSlots().singleOrNull()?.let { slot ->
            dispatch(SetAttSlotAction(slot))
        }
    }

    return next(state, action, dispatch)
}
