package com.bedalton.creatures.breed.render.renderer

import com.bedalton.common.exceptions.rethrowCancellationException
import com.bedalton.creatures.breed.render.files.BodyPartFiles
import com.bedalton.creatures.breed.render.internal.commonLibSize
import com.bedalton.creatures.breed.render.support.pose.Pose
import com.bedalton.creatures.breed.render.support.render.ParsedBodyPartRenderData
import com.bedalton.creatures.breed.render.support.render.PartVisibility
import com.bedalton.creatures.breed.render.support.render.RenderOffsets
import com.bedalton.log.LOG_VERBOSE
import com.bedalton.log.Log
import com.bedalton.log.iIf
import com.bedalton.vfs.FileSystem
import korlibs.image.bitmap.Bitmap32
import korlibs.image.color.RGBA
import kotlin.coroutines.CoroutineContext
import kotlin.coroutines.coroutineContext
import kotlin.math.ceil

/**
 * Renders part data into a bitmap32
 */
object Renderer {

    private const val GHOST_ALPHA_DEFAULT = 0.5
    const val DEFAULT_NON_INTERSECTING_LIMBS = false
    const val DEFAULT_TRIM = false


    /**
     * Renders a creature from a list of BreedPartData
     * @param nonIntersectingLimbs this determines whether to use actual game z-order where limb z-orders intersect
     *  Or to use a more natural order where each limb is on its own plane that does not intersect
     */
    internal suspend fun render(
        coroutineContext: CoroutineContext,
        fs: FileSystem,
        pose: Pose,
        data: List<BodyPartFiles>,
        nonIntersectingLimbs: Boolean?,
        trim: Boolean?,
        zoom: Double = 1.0,
        padding: Int = 0,
        ghostAlpha: Double? = null,
        opaqueWins: Boolean? = null
    ): Bitmap32? {
        val offsets = DataToOffsets.getOffset(
            coroutineContext,
            fs,
            pose,
            data,
            nonIntersectingLimbs ?: DEFAULT_NON_INTERSECTING_LIMBS
        )
            ?: return null
        return render(offsets, zoom, padding, trim, ghostAlpha, opaqueWins)
    }

    /**
     * Renders a creature from a list of ParsedBodyPartRenderData
     * @param nonIntersectingLimbs this determines whether to use actual game z-order where limb z-orders intersect
     *  Or to use a more natural order where each limb is on its own plane that does not intersect
     */
    suspend fun render(
        pose: Pose,
        data: List<ParsedBodyPartRenderData<Bitmap32>>,
        nonIntersectingLimbs: Boolean?,
        trim: Boolean?,
        zoom: Double = 1.0,
        padding: Int = 0,
        ghostAlpha: Double? = null,
        opaqueWins: Boolean? = null,
    ): Bitmap32? {
        return render(
            context = coroutineContext,
            pose = pose,
            data = data,
            nonIntersectingLimbs = nonIntersectingLimbs,
            trim = trim,
            zoom = zoom,
            padding = padding,
            ghostAlpha = ghostAlpha,
            opaqueWins = opaqueWins
        )
    }

    /**
     * Renders a creature from a list of ParsedBodyPartRenderData
     * @param nonIntersectingLimbs this determines whether to use actual game z-order where limb z-orders intersect
     *  Or to use a more natural order where each limb is on its own plane that does not intersect
     */
    suspend fun render(
        context: CoroutineContext,
        pose: Pose,
        data: List<ParsedBodyPartRenderData<Bitmap32>>,
        nonIntersectingLimbs: Boolean?,
        trim: Boolean?,
        zoom: Double = 1.0,
        padding: Int = 0,
        ghostAlpha: Double? = null,
        opaqueWins: Boolean? = null,
    ): Bitmap32? {
        val offsets = DataToOffsets.getOffset(
            context = context,
            pose = pose,
            data = data,
            nonIntersectLimbs = nonIntersectingLimbs ?: DEFAULT_NON_INTERSECTING_LIMBS
        )
            ?: return null
        return render(offsets, zoom, padding, trim, ghostAlpha, opaqueWins)
    }

    /**
     * Renders a creature from a list of already mapped part char to body part
     *  @param nonIntersectingLimbs this determines whether to use actual game z-order where limb z-orders intersect
     *  Or to use a more natural order where each limb is on its own plane that does not intersect
     *  @param ghostAlpha Determines how transparent a ghost limb should be
     *  @param padding How much empty space to add around the rendered image
     *  @param opaqueWins Whether to make a transparent pixel opaque, if it is overlaid on an opaque pixel
     *      if not, the pixel has an averaged transparency
     *  @param trim whether to trim the visible parts of the image and then apply padding
     *      Som
     */
    suspend fun render(
        pose: Pose,
        data: Map<Char, ParsedBodyPartRenderData<Bitmap32>>,
        nonIntersectingLimbs: Boolean?,
        trim: Boolean?,
        zoom: Double = 1.0,
        padding: Int = 0,
        ghostAlpha: Double? = null,
        opaqueWins: Boolean? = null,
    ): Bitmap32? {
        return render(
            coroutineContext,
            pose,
            data,
            nonIntersectingLimbs,
            trim,
            zoom,
            padding,
            ghostAlpha,
            opaqueWins
        )
    }

    /**
     * Renders a creature from a list of already mapped part char to body part
     * @param nonIntersectingLimbs this determines whether to use actual game z-order where limb z-orders intersect
     *  Or to use a more natural order where each limb is on its own plane that does not intersect
     *  @param ghostAlpha Determines how transparent a ghost limb should be
     *  @param padding How much empty space to add around the rendered image
     *  @param opaqueWins Whether to make a transparent pixel opaque, if it is overlaid on an opaque pixel
     *      if not, the pixel has an averaged transparency
     *  @param trim whether to trim the visible parts of the image and then apply padding
     *      Som
     */
    suspend fun render(
        context: CoroutineContext,
        pose: Pose,
        data: Map<Char, ParsedBodyPartRenderData<Bitmap32>>,
        nonIntersectingLimbs: Boolean?,
        trim: Boolean?,
        zoom: Double = 1.0,
        padding: Int = 0,
        ghostAlpha: Double? = null,
        opaqueWins: Boolean? = null,
    ): Bitmap32? {
        val offsets = DataToOffsets
            .getOffset(
                context = context,
                pose = pose,
                data = data,
                nonIntersectLimbs = nonIntersectingLimbs ?: DEFAULT_NON_INTERSECTING_LIMBS,
                Bitmap32::commonLibSize
            )
            ?: return null
        return render(
            offsets,
            zoom,
            padding,
            trim,
            ghostAlpha,
            opaqueWins
        )
    }

    fun render(
        data: RenderOffsets<Bitmap32>,
        zoom: Double,
        padding: Int,
        trim: Boolean?,
        ghostAlpha: Double? = null,
        opaqueWins: Boolean? = null,
    ): Bitmap32? {
        return try {
            renderUnsafe(data, zoom, padding, trim, ghostAlpha, opaqueWins)
        } catch (e: Exception) {
            e.rethrowCancellationException()
            null
        }
    }

    fun renderUnsafe(
        data: RenderOffsets<Bitmap32>,
        zoom: Double,
        padding: Int,
        trim: Boolean?,
        ghostAlpha: Double? = null,
        opaqueWins: Boolean? = null,
    ): Bitmap32 {
        val size = data.size
        val truePadding = if (trim ?: DEFAULT_TRIM) {
            0
        } else {
            padding
        }
        val out = Bitmap32(
            width = ceil(size.width * zoom).toInt() + (truePadding * 2),
            height = ceil(size.height * zoom).toInt() + (truePadding * 2),
            premultiplied = false
        )
        out.fill(RGBA(0, 0, 0, 0), 0, 0, out.width, out.height)
        val ghostAlphaNotNull = ghostAlpha ?: GHOST_ALPHA_DEFAULT
        for (part in data.parts) {
            if (part.visibility == PartVisibility.HIDDEN) {
                continue
            }
            val (x, y) = part.offset
                ?: continue
            val image = if (zoom > 1) {
                part.image.scaled((part.image.width * zoom).toInt(), (part.image.height * zoom).toInt(), smooth = true)
            } else {
                part.image
            }
            val alpha = if (part.visibility == PartVisibility.GHOST) {
                ceil(ghostAlphaNotNull * 255).toInt()
            } else {
                255
            }
            Combinator.overlay(
                main = out,
                other = image,
                x = (x * zoom).toInt() + padding,
                y = (y * zoom).toInt() + padding,
                alpha = alpha,
                opaqueWins = opaqueWins
            )
        }
        if (!(trim ?: DEFAULT_TRIM)) {
            Log.iIf(LOG_VERBOSE) { "Trim is set to false" }
            return out
        }
        var minX: Int = Int.MAX_VALUE
        var maxX = 0
        var minY: Int = Int.MAX_VALUE
        var maxY = 0
        var isFullyTransparent = true
        for (x in 0 until out.width) {
            for (y in 0 until out.height) {
                if (out[x, y].a > 127) {
                    if (isFullyTransparent) {
                        isFullyTransparent = false
                    }
                    if (x < minX) {
                        minX = x
                    }
                    if (x > maxX) {
                        maxX = x
                    }
                    if (y < minY) {
                        minY = y
                    }
                    if (y > maxY) {
                        maxY = y
                    }
                }
            }
        }

        val width = maxX - minX
        val height = maxY - minY

        val paddedWidth = width + (padding * 2)
        val paddedHeight = height + (padding * 2)

        // Image is already trimmed
        if (isFullyTransparent || (minX == 0 && minY == 0 && maxX == out.width && maxY == out.height)) {

            if (padding == 0) {
                Log.iIf(LOG_VERBOSE) { "No trim needed; IsFullyTransparent: $isFullyTransparent; No Padding" }
                return out
            }
            Log.iIf(LOG_VERBOSE) { "No trim needed; IsFullyTransparent: $isFullyTransparent; Has Padding: $padding" }
            return Bitmap32(paddedWidth, paddedHeight, false).apply {
                out.copy(0, 0, this, padding, padding, width, height)
            }
        }
        Log.iIf(LOG_VERBOSE) { "Trim needed; FullWidth: ${out.width}; TrimmedWidth: $width; FullHeight: ${out.height}; TrimmedHeight: $height" }
        return Bitmap32(paddedWidth, paddedHeight, false).apply {
            Bitmap32.copyRect(out, minX, minY, this, padding, padding, width, height)
        }
    }

}