package com.bedalton.creatures.agents.pray.internal

import com.bedalton.creatures.agents.pray.exceptions.PrayDataBlockDecompressionException
import com.bedalton.io.bytes.ByteStreamReader
import com.bedalton.io.bytes.Compressor

internal fun bytesToStreamSimple(data: ByteArray?, compressed: Boolean): () -> ByteArray? {
    if (data == null) {
        return { null }
    }
    var bytes: ByteArray? = null
    return func@{
        bytes?.let {
            return@func it
        }
        val byteTemp = if (compressed) {
            Compressor.decompress(data)
        } else {
            data
        }
        bytes = byteTemp
        byteTemp
    }
}

internal fun getBytesFromStream(
    stream: ByteStreamReader,
    start: Int,
    end: Int,
    decompressedLength: Int,
    compressed: Boolean,
    cache: Boolean,
): () -> ByteArray {
    var cachedBytes: ByteArray? = null
    return func@{
        cachedBytes?.let {
            return@let it
        }
        val copy = stream.copyAsOpened()
        val tempBytes = (copy ?: stream).copyOfBytes(start.toLong(), end.toLong())
        copy?.close()
        val outBytes: ByteArray = if (compressed) {
            Compressor.decompress(tempBytes)
                ?: throw PrayDataBlockDecompressionException(
                    "Failed to decompress bytes",
                    tempBytes,
                    expectedDecompressedSize = decompressedLength,
                )
        } else {
            tempBytes
        }
        if (cache) {
            cachedBytes = outBytes
        }
        outBytes
    }
}

