package com.bedalton.creatures.caos.libs

import kotlinx.serialization.Serializable
import kotlin.js.JsExport
import kotlin.js.JsName

/**
 * A concrete holder for data associated with a variant
 * Using a MAP failed under JS
 */
@Suppress("PropertyName")
@JsExport
@Serializable
data class VariantData<T>(
    @JsName("C1")
    val C1: T? = null,
    @JsName("C2")
    val C2: T? = null,
    @JsName("CV")
    val CV: T? = null,
    @JsName("C3")
    val C3: T? = null,
    @JsName("DS")
    val DS: T? = null,
    @JsName("SM")
    val SM: T? = null
) {

    /**
     * Constructs an object using a MAP indexed by CAOS variant codes
     */
    internal constructor(map: Map<String, T>): this(
        C1 = map["C1"],
        C2 = map["C2"],
        CV = map["CV"],
        C3 = map["C3"],
        DS = map["DS"],
        SM = map["SM"]
    )

    @Suppress("unused")
    @JsName("copyWithValueForVariantEnum")
    fun copyWithValue(variant: CaosVariant, value: T?): VariantData<T> {
        return when(variant) {
            CaosVariant.C1 -> copy(C1 = value)
            CaosVariant.C2 -> copy(C2 = value)
            CaosVariant.CV -> copy(CV = value)
            CaosVariant.C3 -> copy(C3 = value)
            CaosVariant.DS -> copy(DS = value)
            CaosVariant.SM -> copy(SM = value)
            else -> throw Exception("Invalid variant")
        }
    }


    @Suppress("unused")
    fun copyWithValue(variant: String, value: T?): VariantData<T> {
        return when(variant.uppercase()) {
            "C1" -> copy(C1 = value)
            "C2" -> copy(C2 = value)
            "CV" -> copy(CV = value)
            "C3" -> copy(C3 = value)
            "DS" -> copy(DS = value)
            "SM" -> copy(SM = value)
            else -> throw Exception("Invalid variant: $variant")
        }
    }


    /**
     * Gets the value given a caos variant object
     */
    @JsName("valueForVariant")
    operator fun get(variant: CaosVariant): T? {
        return when(variant) {
            CaosVariant.C1 -> C1
            CaosVariant.C2 -> C2
            CaosVariant.CV -> CV
            CaosVariant.C3 -> C3
            CaosVariant.DS -> DS
            CaosVariant.SM -> SM
            else -> null
        }
    }

    /**
     * Get value for given variant string
     */
    operator fun get(variant: String): T? {
        return when(variant.uppercase()) {
            "C1" -> C1
            "C2" -> C2
            "CV" -> CV
            "C3" -> C3
            "DS" -> DS
            "SM" -> SM
            else -> null
        }
    }
}