package com.bedalton.vfs

import com.bedalton.io.bytes.ByteStreamReader
import com.bedalton.vfs.internal.FileSystemActions
import com.bedalton.vfs.internal.FileSystemActionsBase
import kotlin.jvm.JvmStatic

open class FileSystemActionsSurrogate {

    suspend fun readAsStreamReader(path: String): ByteStreamReader {
        return FileSystemActionsBase.readAsStreamReader(path)
    }

    suspend fun delete(path: String): Boolean {
        return FileSystemActionsBase.delete(path)
    }

    suspend fun fileExists(path: String): Boolean {
        return FileSystemActionsBase.fileExists(path)
    }

    suspend fun isDirectory(path: String): Boolean {
        return FileSystemActionsBase.isDirectory(path)
    }

    suspend fun md5(path: String): String? {
        return FileSystemActionsBase.md5(path)
    }

    suspend fun readBytes(path: String): ByteArray {
        return FileSystemActionsBase.readBytes(path)
    }

    suspend fun readBytes(path: String, offset: Long, length: Long): ByteArray {
        return FileSystemActionsBase.readBytes(path, offset, length)
    }

    suspend fun readTextWithWindowsCP1252Encoding(path: String): String {
        return FileSystemActionsBase.readTextWithWindowsCP1252Encoding(path)
    }

    suspend fun readTextWithUTF8Encoding(path: String): String {
        return FileSystemActionsBase.readTextWithUTF8Encoding(path)
    }

    suspend fun write(path: String, data: ByteArray, append: Boolean) {
        return FileSystemActionsBase.write(path, data, append)
    }

    suspend fun makeDirectory(path: String, recursive: Boolean): Boolean {
        return FileSystemActionsBase.makeDirectory(path, recursive)
    }

    suspend fun deleteDirectory(path: String): Boolean {
        return FileSystemActionsBase.deleteDirectory(path)
    }


    suspend fun getChildrenNonRecursive(directory: String): List<String>? {
        return FileSystemActionsBase.getChildrenNonRecursive(directory)
    }

    companion object {
        @JvmStatic
        fun setFileActionsSurrogate(surrogate: FileSystemActionsSurrogate) {
            FileSystemActions.setSurrogate(surrogate)
        }
    }
}
