package com.bedalton.creatures.caos.validation.internal

import com.bedalton.creatures.caos.collectors.CaosParserItem
import com.bedalton.creatures.caos.collectors.CommandCall
import com.bedalton.creatures.caos.libs.CaosVariant
import com.bedalton.creatures.caos.libs.ErrorTypes
import com.bedalton.creatures.caos.libs.ValueType

/**
 * Adds errors for invalid TOKEN value formats
 * i.e. non-4-char tokens in C1e or leading-number in C2e
 *
 * @param variant
 * @param commandCalls
 * @param errors
 * @param checkCancelled
 * @receiver
 */
internal fun addTokenFormatErrors(
    variant: CaosVariant,
    commandCalls: Array<CommandCall>,
    errors: MutableList<CaosParserItem.ErrorVal>,
    checkCancelled: () -> Unit,
) {
    val tokens = mutableListOf<CaosParserItem.TokenVal>()
    if (variant.isOld) {
        commandCalls.forEach {
            checkCancelled()
            tokenArguments(it, tokens)
        }
        validateTokensC1e(tokens, errors)
    } else {
        commandCalls.forEach each@{
            checkCancelled()
            val command = it.command.command
            if (command != "GSUB" && command != "SUBR" && command != "GOTO") {
                return@each
            }
            val parserItem = (it.arguments.getOrNull(0)?.parserItem as? CaosParserItem.TokenVal?)
                ?: return@each
            tokens.add(parserItem)
        }
        validateTokensC2e(tokens, errors)
    }
}

private fun tokenArguments(
    command: CommandCall,
    tokenItems: MutableList<CaosParserItem.TokenVal>
) {
    for (argument in command.arguments) {
        if (argument is CommandCall) {
            tokenArguments(argument, tokenItems)
        } else if (argument.parameter?.typeId == ValueType.TOKEN.value) {
            val item = argument.parserItem
                ?: continue
            if (item is CaosParserItem.TokenVal) {
                tokenItems.add(item)
            }
        }
    }
}


private fun validateTokensC1e(tokens: List<CaosParserItem.TokenVal>, errors: MutableList<CaosParserItem.ErrorVal>) {
    for (token in tokens) {
        if (token.value.length != 4) {
            errors.add(
                CaosParserItem.ErrorVal(
                    token.textRange,
                    "Tokens must be exactly 4 characters long",
                    type = ErrorTypes.GENERAL,
                    token.text
                )
            )
        }
    }
}

private fun validateTokensC2e(tokens: List<CaosParserItem.TokenVal>, errors: MutableList<CaosParserItem.ErrorVal>) {
    for (token in tokens) {
        if (token.value[0] !in 'a'..'z' && token.value[0] !in 'A'..'Z') {
            errors.add(
                CaosParserItem.ErrorVal(
                    token.textRange,
                    "Tokens should begin with a letter",
                    type = ErrorTypes.GENERAL,
                    token.text
                )
            )
        }
    }
}
