package com.creaturesforge.application.state

import com.bedalton.common.util.PathUtil

internal fun compilerReducer(state: ForgeState, action: FAction): ForgeState = when (action) {
    is RequestCompileAction -> {
        state.copy(
            lastFileName = PathUtil.getLastPathComponent(action.outputFile) ?: action.outputFile,
            lastSaveDirectory = PathUtil.getWithoutLastPathComponent(action.outputFile),
            outputFile = action.outputFile
        ).also {
            ForgeConfig.pushProjectState(it, true)
        }
    }
    else -> state
}