private const val AUTHOR_PLACEHOLDER = "*{AUTHOR}*"

/**
 * Create a CAOS2Cob file, and filename->byte tuples from parsed COB blocks
 */
fun constructCAOS2CobFile(
    prefix: String,
    filename: String,
    variant: CaosVariant,
    blocks: List<CobBlock>
): List<Pair<String, ByteArray>> {
    return when (variant) {
        CaosVariant.C1 -> constructC1CobFiles(prefix, filename, blocks)?.toListOf() ?: emptyList()
        CaosVariant.C2 -> constructC2CobFiles(prefix, filename, blocks)
        else -> throw AgentFileDecompilerException("COB files are only for variants [C1,C2]; Found: $variant")
    }
}

/**
 * Construct files from C1 COB
 */
private fun constructC1CobFiles(prefix: String, filename: String, blocks: List<CobBlock>): Pair<String, ByteArray>? {
    if (blocks.isEmpty()) {
        return null
    }
    val block = blocks.singleOrNull()
        ?: throw AgentFileDecompilerException("C1 COB does not contain exactly one block; Found: ${blocks.size}")
    if (block !is AgentBlock) {
        throw AgentFileDecompilerException("C1 COB block is not an agent block; Found: ${block.className}")
    }

    val fileText = constructAgentFile(prefix, filename, "C1", block, false, emptySet())
        .replace(AUTHOR_PLACEHOLDER + '\n', "")

    return Pair("$filename.caos2cob.cos", fileText.encodeToByteArray())

}


/**
 * Generate CAOS2Cob text file as bytes, and create (filename, ByteArray) tuples for C2 COB
 * @param prefix prefix to add to all generated file names
 * @param filename name of output file to create
 * @param blocks blocks containing COB data; i.e. Agent, File, Author
 */
private fun constructC2CobFiles(
    prefix: String,
    filename: String,
    blocks: List<CobBlock>
): List<Pair<String, ByteArray>> {

    val agents = blocks.filterIsInstance<AgentBlock>()

    val multipleAgents = agents.size > 1

    // All file blocks in the COB
    val attachments = blocks.filterIsInstance<CobBlock.FileBlock>()

    // Names of all files in this COB
    val attachmentNames = attachments.map { it.fileName }

    // Construct the CAOS2Cob statements for this Author Block
    val authorText = blocks.filterIsInstance<AuthorBlock>()
        .joinToString("\n") { block ->
            constructAuthorText(block)
        }

    // If Multiple agents, only list author text on main file
    val authorTextReplacement = if (multipleAgents) {
        ""
    } else {
        authorText
    }

    // If there is only one agent
    val singleAgent = agents.size == 1

    // Find files shared by multiple agents, so only include them once
    val sharedAttachments: List<String> = if (singleAgent) {
        emptyList()
    } else {
        attachments.filter {
            attachments.count {
                it.fileName like it.fileName.lowercase()
            } > 1
        }.map {
            it.fileName.lowercase()
        }
    }

    // Convert agent blocks into CAOS2Cob filename,content bytes tuple
    val agentsFiles = agents.flatMap { block ->
        val agentFile = constructAgentFile(
            prefix = prefix,
            filename = filename,
            variant = "C2",
            block = block,
            multiple = multipleAgents,
            attached = attachmentNames.filter { it.lowercase() !in sharedAttachments }.toSet()
        )
            .replace(AUTHOR_PLACEHOLDER, authorTextReplacement)
            .trimDoubleCaos2Prefix()

        // Create file name, byte pair for CAOS2Cob file string contents
        val agentFileData = Pair(prefix + block.name + ".caos2cob.cos", agentFile.encodeToByteArray())

        // Generate thumbnail image from block
        val thumbnail = block.image?.let { thumbnail ->
            val thumbnailName = getThumbnailFileName(prefix, agentName = block.name)
            val bytes = PNG.encode(thumbnail, ImageEncodingProps(filename = thumbnailName, quality = 10.0))
            Pair(thumbnailName, bytes)
        }

        // Add agent and thumbnail if any
        listOfNotNull(agentFileData, thumbnail)
    }

    // Create list of all blocks, file and agent
    val files = attachments.map {
        Pair(prefix + it.fileName, it.contents)
    } + agentsFiles

    // If there is 1 or fewer agents, return now
    if (!multipleAgents) {
        return files
    }

    // Get list of all dependencies across all files
    val dependencies = agents.flatMap { it.dependencies }.map { it.fileName.lowercase() }

    // Files included but not listed as dependencies
    // If listed in dependencies, they would be attachments
    val inlineFiles = attachmentNames.filter { it.lowercase() !in dependencies }

    // Build parent CAOS2Cob file
    val mainFile = buildMainFile(
        prefix = prefix,
        filename = filename,
        caos2FileNames = agentsFiles.map { it.first },
        inlineFiles = inlineFiles,
        authorText = authorText
    )

    return files + mainFile
}

/**
 * Build a CAOS2Cob file to handle multi-agent COB files
 * @param prefix prefix to add to all file names
 * @param filename output filename to put in COB
 * @param caos2FileNames Names of agent files to use in Join statements
 * @param inlineFiles files to inline, but not depend on
 * @param authorText author tags to add to main file
 */
private fun buildMainFile(
    prefix: String,
    filename: String,
    caos2FileNames: List<String>,
    inlineFiles: List<String>,
    authorText: String,
): Pair<String, ByteArray> {
    val out = StringBuilder("**CAOS2Cob C2")
        .appendLine()
        .append("*#")
        .append(authorText)
        .append("*#")

    for (file in inlineFiles) {
        out.command("Inline", file)
    }

    if (caos2FileNames.size > 1) {
        out.appendLine("* == Joins ==")
        for (file in caos2FileNames) {
            out.command("Join", file)
        }
    }

    return Pair("$prefix$filename.caos2pray.cos", out.toString().encodeToByteArray())
}

/**
 * Construct the file text for an agent file
 * @param prefix prefix to add to file names
 * @param filename the output name for this agent
 * @param variant the game variant this agent is for
 * @param block the agent data block to create CAOS2Cob file for
 * @param multiple whether this agent is part of a multi-agent COB
 * @param attached files attached to this Agent (include bytes and add dependency)
 */
private fun constructAgentFile(
    prefix: String,
    filename: String,
    variant: String,
    block: AgentBlock,
    multiple: Boolean,
    attached: Set<String>
): String {
    val out = StringBuilder("**CAOS2Cob $variant")
    if (multiple) {
        out.append(" Join\n")
    } else {
        out
            .appendLine()
            .command("Cob-File", filename)
    }

    out.command("$variant-Name", block.name)

    if (block.image != null) {
        out.tag("Thumbnail", getThumbnailFileName(prefix, agentName = block.name))
    }

    out
        .tagNotEmpty("Agent Description", block.description)
        .tag("Expiry Date", block.expiry)
        .tag("Quantity Available", block.quantityAvailable)
        .tagNotZero("Quantity Used", block.quantityUsed)
        .tagNotZero("Reuse Interval", block.useInterval)
        .tagNotZero("Last Usage Date", block.lastUsageDate)
        .appendLine("*#")
        .appendLine(AUTHOR_PLACEHOLDER)
        .appendLine("*#")

    val allDependencies = block.dependencies.map {
        it.fileName
    }.toSet()

    val dependencies = block
        .dependencies
        .filter { it.fileName notLikeAny attached }

    val needsAttach = attached
        .filter { it.lowercase() in allDependencies }

    val needsInline = if (multiple) {
        emptyList()
    } else {
        attached.filter { it notLikeAny allDependencies }
    }

    for (file in needsAttach) {
        out.command("Attach", file)
    }

    for (file in dependencies) {
        out.command("Depend", file.fileName)
    }

    for (file in needsInline) {
        out.command("Inline", file)
    }
    out.appendLine()

    for (script in block.installScripts) {
        out.append("iscr\n")
            .append(script.indented(variant))
            .append("\n\n")
    }

    for (script in block.eventScripts) {
        out.append(script.withEndm().indented(variant))
            .append("\n\n")
    }

    block.removalScript?.let {
        out.append("rscr\n")
            .append(it.indented(variant))
            .append("\n\n")
    }
    return out.toString()
}

/**
 * Construct an author block for a C2 CAOS2Cob file
 */
private fun constructAuthorText(block: AuthorBlock): String {
    return StringBuilder()
        .tag("Creation Date", block.creationDate)
        .tagNotEmpty("Author Name", block.authorName)
        .tagNotEmpty("Author Email", block.authorEmail)
        .tagNotEmpty("Author URL", block.authorUrl)
        .tagNotEmpty("Author Email", block.authorEmail)
        .tagNotZero("Version", block.version)
        .tagNotZero("Revision", block.revision)
        .tagNotEmpty("Comment", block.authorComments)
        .toString()
}

/**
 * Creates the name for an agent blocks thumbnail
 * @param prefix prefix to add to filename
 * @param agentName name of the agent this thumbnail belongs to
 */
internal fun getThumbnailFileName(prefix: String, agentName: String): String {
    val thumbnailPrefix = when {
        prefix.isNotBlank() && agentName.isNotBlank() -> "$prefix-$agentName"
        prefix.isNotBlank() -> prefix.ensureNotEndsWith("-")
        agentName.isNotBlank() -> agentName
        else -> randomString(8) // Not sure what to do here if both parts are empty
    }
    return ("$thumbnailPrefix-thumbnail.png")
        .replace("\\", "_")
        .replace("/", "_")
        .replace(":", "_")
        .replace("$", "")
        .replace("^", "")
}

/**
 * Adds a CAOS2Cob command to string builder
 * @param command command string; i.e. "Link", "Attach", "Inline", etc.
 * @param text text for the command
 */
private fun StringBuilder.command(command: String, text: String): StringBuilder {
    return append("*# ")
        .append(command.escape())
        .append(" \"")
        .append(text.escape())
        .append("\"\n")
}

/**
 * Appends tag text to this string builder
 * @param tag The tag name in this directive
 * @param text text value for this tag
 */
private fun StringBuilder.tag(tag: String, text: String): StringBuilder {
    return append("*# ")
        .append(tag.escape())
        .append(" = \"")
        .append(text.escape())
        .append("\"\n")
}

/**
 * Appends a tag, only if the text is not null
 * @param tag tag name
 * @param text tag value text
 */
private fun StringBuilder.tagNotEmpty(tag: String, text: String?): StringBuilder {
    if (text.isNullOrBlank()) {
        return this
    }
    return append("*# ")
        .append(tag.escape())
        .append(" = \"")
        .append(text.escape())
        .append("\"\n")
}

/**
 * Adds a tag with a data value
 * @param tag tag name
 * @param value Date for this tag (will be converted to string)
 */
private fun StringBuilder.tag(tag: String, value: DateComponents?): StringBuilder {
    if (value == null) {
        return this
    }
    return append("*# ")
        .append(tag.escape())
        .append(" = ")
        .append(value.year)
        .append('-')
        .append(value.monthZeroIndexed + 1)
        .append('-')
        .append(value.day)
        .append("\n")
}

/**
 * Appends a tag with an integer value
 * @param tag tag name
 * @param value tag's integer value
 */
private fun StringBuilder.tag(tag: String, value: Int): StringBuilder {
    return append("*# ")
        .append(tag.escape())
        .append(" = ")
        .append(value)
        .append("\n")
}

/**
 * Appends int tag, only if tag value non-zero, and non-null
 * @param tag tag name
 * @param value tag's integer value
 */
private fun StringBuilder.tagNotZero(tag: String, value: Int?): StringBuilder {
    if (value == null || value == 0) {
        return this
    }
    return append("*# ")
        .append(tag.escape())
        .append(" = ")
        .append(value)
        .append("\n")
}

/**
 * Creates options for CAOS formatter
 */
private val formattingOptions by lazy {
    CaosFormatterOptionsBuilder()
        .withInsertFinalNewline(true)
        .withSpaceBetweenByteStringBrackets(false)
        .withTrimTrailingWhitespace(true)
        .withForceMinBlankLinesAfterComments(true)
        .withNewlineChar("\n")
}

/**
 * Determines whether script should be indented
 */
private fun String.indented(variant: String): String {
    return try {
        format(variant, text = this, options = formattingOptions)
            .formattedText
    } catch (e: Exception) {
        e.rethrowIfCancellationException()
        if (e is FormatExceptionWithCaosErrors) {
            Log.eIf(LOG_DEBUG) {
                "Failed to format script: ${e.formatted(false)}\n" +
                        "Script: $this\nErrors:\n\t- " +
                        e.errors.joinToString("\n\t- ") { it.textRange.endIndex.toString() + ": [" + it.text + "] ->" + it.message }

            }
        }
        Log.eIf(LOG_DEBUG) {
            "Failed to format text; ${e.formatted(true)}"
        }
        this
    }
}

/**
 * Ensures string ends with "endm"
 */
private fun String.withEndm(): String {
    return if (this.trim().endsWith("endm")) {
        this.trim()
    } else {
        this.trim() + " endm"
    }
}

/**
 * removes duplicate CAOS2Cob tags "*#"
 */
private fun String.trimDoubleCaos2Prefix(): String {
    return "(\\*#\\s+){2,}".toRegex().replace(this, "*# ")
}
