@file:Suppress("unused")

package com.bedalton.common.coroutines

import kotlinx.coroutines.*

expect val MainDispatcher: CoroutineDispatcher
expect val BackgroundDispatcher: CoroutineDispatcher
expect val UnconfinedDispatcher: CoroutineDispatcher


fun CoroutineScope.launch(start: CoroutineStart, callback: suspend () -> Unit): Job {
    return this@launch.launch(coroutineContext, start = start) {
        try {
            callback()
        } catch (e: CancellationException) {
            throw e
        } catch (e: Throwable) {
            e.rethrowIfCancellationException()
            e.printStackTrace()
            throw e
        }
    }
}

fun <T> CoroutineScope.async(start: CoroutineStart, callback: suspend () -> T): Deferred<T> {
    return async(coroutineContext, start = start) {
        try {
            callback()
        } catch (e: CancellationException) {
            throw e
        } catch (e: Throwable) {
            e.rethrowIfCancellationException()
            e.printStackTrace()
            throw e
        }
    }
}