package com.bedalton.creatures.agents.pray.compiler.data

import com.bedalton.common.coroutines.rethrowIfCancellationException
import com.bedalton.creatures.agents.pray.compiler.internal.writeBlockBytes
import com.bedalton.creatures.agents.util.RelativeFileSystem
import com.bedalton.io.bytes.ByteStreamReader
import com.bedalton.io.bytes.ByteStreamWriter
import com.bedalton.io.bytes.Compressor
import kotlinx.coroutines.CoroutineScope


class CompilerDataBlock(
    startLine: Int,
    @Suppress("unused", "MemberVisibilityCanBePrivate")
    val commonName: String,
    blockTag: TextValue,
    blockName: TextValue,
    private val bytes: () -> ByteArray?
) : CompilerPrayBlock(startLine, blockTag, blockName) {


    internal constructor(
        commonName: String,
        blockTag: TextValue,
        blockName: TextValue,
        stream: ByteStreamReader,
        byteStart: Long,
        byteEnd: Long,
        compressed: Boolean,
        cacheBytes: Boolean
    ) : this(
        -1,
        commonName,
        blockTag,
        blockName,
        getBytesFromStream(stream, byteStart, byteEnd, compressed, cacheBytes)
    )

    @Suppress("unused")
    internal constructor(
        commonName: String,
        blockTag: TextValue,
        blockName: TextValue,
        data: ByteArray?,
        compressed: Boolean = false
    ) : this(-1, commonName, blockTag, blockName, data?.let {
        var bytes: ByteArray? = null
        return@let func@{
            bytes?.let {
                return@func it
            }
            val byteTemp = if (compressed) {
                Compressor.decompress(data)
            } else {
                data
            }
            bytes = byteTemp
            byteTemp
        }
    } ?: { null })

    fun data(): ByteArray? = bytes()

    override suspend fun write(coroutineScope: CoroutineScope, fs: RelativeFileSystem, writer: ByteStreamWriter, compression: Int) {
        val data = data()
            ?: throw Exception("Cannot write data block without data for block $label")
        writer.writeStringWithCreaturesEncoding(blockTag.text)
        writer.writeStringWithCreaturesEncoding(blockName.text.padEnd(128, 0.toChar()))
        writer.writeUInt32(data.size)
        writeBlockBytes(writer, data, compression)
    }

    override fun toCommonData(): com.bedalton.creatures.agents.pray.data.DataBlock {
        return com.bedalton.creatures.agents.pray.data.DataBlock(
            commonName,
            blockTag = blockTag.text,
            blockName = blockName.text,
            bytes = bytes
        )
    }
    private companion object {

        fun getBytesFromStream(
            stream: ByteStreamReader,
            start: Long,
            end: Long,
            compressed: Boolean,
            cache: Boolean
        ): () -> ByteArray {
            var cachedBytes: ByteArray? = null
            return func@{
                cachedBytes?.let {
                    return@let it
                }
                val tempBytes = stream.copyOfBytes(start, end)
                val outBytes: ByteArray = if (compressed) {
                    try {
                        Compressor.decompressThrowing(tempBytes)
                    } catch (e: Exception) {
                        // Do not hold onto cancellation exceptions
                        e.rethrowIfCancellationException()

                        throw PrayDataBlockDecompressionException(
                            "Decompress block failed: ${e.message}",
                            tempBytes,
                            e
                        )
                    }
                } else {
                    tempBytes
                }
                if (cache) {
                    cachedBytes = outBytes
                }
                outBytes
            }
        }
    }
}


