package com.bedalton.creatures.breed.render.internal

import com.bedalton.common.exceptions.rethrowCancellationException
import com.bedalton.creatures.breed.render.renderer.BreedRendererBuilder
import com.bedalton.creatures.breed.render.renderer.NotSingleCharException
import com.bedalton.creatures.breed.render.renderer.RenderValueOutOfRangeException
import com.bedalton.creatures.common.structs.GameVariant


internal fun BreedRendererBuilder.breedChar(charString: String): Char {
    val breedChar = charSafe(charString)?.lowercaseChar()
        ?: throw NotSingleCharException(
            "Breed char string must be a single breed character",
            "breed char",
            charString,
        )
    val validBreedChars = validBreedChars
    if (breedChar !in validBreedChars) {
        throw RenderValueOutOfRangeException(
            "Invalid breed. Breed must be in range: ${validBreedChars.first}..${validBreedChars.last}",
            "breed char",
            breedChar,
            validBreedChars.first.toString(), validBreedChars.last.toString()
        )
    }
    return breedChar
}


private val BreedRendererBuilder.validBreedChars
    get() = if (getGameVariant() == GameVariant.C1) {
        '0'..'9'
    } else {
        'a'..'z'
    }


internal fun charSafe(charString: String): Char? {
    return try {
        if (charString.length == 1) {
            charString[0]
        } else {
            null
        }
    } catch (e: Exception) {
        e.rethrowCancellationException()
        null
    }
}