package com.bedalton.creatures.agents.pray.compiler

import com.bedalton.common.util.nullIfEmpty
import com.bedalton.common.util.stripSurroundingQuotes

internal fun getLinkFilenameReferenceText(filename: String): String {
    return "* [FileName=\"$filename\"]\n"
}

val linkFilenameRegexText = "^\\s*[*]{1,2}\\s*\\[FileName=(\"(?:[^\"]|\\\\.)*\"|(?:[^\"]|\\\\.)*)]"
    .toRegex(setOf(RegexOption.IGNORE_CASE, RegexOption.MULTILINE))

fun getLinkFilenameReferenceFromCaosText(caos: String): String? {
    val firstLine = caos.split("\n", limit = 2)
        .first()
    return linkFilenameRegexText
        .matchEntire(firstLine)
        ?.groupValues
        ?.getOrNull(1)
        ?.stripSurroundingQuotes()
        .nullIfEmpty()
}