@file:Suppress("unused")

package com.bedalton.creatures.sprite.parsers

import com.bedalton.creatures.sprite.util.ColorPalette
import korlibs.image.bitmap.Bitmap32
import korlibs.image.color.RGBA

/**
 * An implementation of an Async frame
 * Allows deferring a sprite image's parsing until needed
 */
data class SpriteFrameAsyncImpl(
    override val width: Int,
    override val height: Int,
    private var palette: List<RGBA>,
    private val keepBlack: Boolean = false,
    var disposeGetter: (() -> Unit)? =  null,
    private var getPixelIndices: (() -> PixelIndices)? = null,
) : SpriteFrameAsync {

    private var image: Bitmap32? = null

    private var mPixelIndices: PixelIndices? = null


    constructor(
        width: Int,
        height: Int,
        palette: ColorPalette,
        disposeGetter: (() -> Unit)? =  null,
        getPixelIndices: (() -> PixelIndices)? = null,
    ): this (
        width,
        height,
        palette.colors,
        false,
        disposeGetter,
        getPixelIndices
    )

    constructor(
        width: Int,
        height: Int,
        palette: ColorPalette,
        keepBlack: Boolean = false,
        disposeGetter: (() -> Unit)? =  null,
        getPixelIndices: (() -> PixelIndices)? = null,
    ): this (
        width,
        height,
        palette.colors,
        keepBlack,
        disposeGetter,
        getPixelIndices
    )

    /**
     * Closes internal stream but does not clear parse image data
     */
    override fun close() {
        getPixelIndices = null
        disposeGetter?.invoke()
        disposeGetter = null
    }

    /**
     * Closes stream and nullifies all cached/parsed data
     */
    override fun dispose() {
        close()
        mPixelIndices = null
        image = null
    }

    /**
     * Get the palette indices needed to construct this image
     */
    override fun pixelIndices(): PixelIndices {
        mPixelIndices?.let {
            return it
        }
        val indices = getPixelIndices?.invoke()
            ?: throw SpriteParserException("Cannot get sprite image. Sprite stream already closed")
        getPixelIndices = null
        mPixelIndices = indices
        return indices
    }

    /**
     * Gets the image using the default palette
     */
    @Deprecated("Use image(keepBlack: Boolean)",
        replaceWith = ReplaceWith("image(keepBlack)")
    )
    override fun image(): Bitmap32 {
        image?.let {
            return it
        }

        val theImage = pixelIndices()
            .withPalette(palette, keepBlack)
        image = theImage
        return theImage
    }

    /**
     * Gets the image using the default palette
     */
    override fun image(keepBlack: Boolean): Bitmap32 {
        image?.let {
            return it
        }

        val black = if (keepBlack) {
            ColorPalette.OPAQUE_BLACK
        } else {
            ColorPalette.TRANSPARENT_BLACK
        }

        val theImage = pixelIndices()
            .withPalette(palette, black)
        image = theImage
        return theImage
    }

    /**
     * Get the image using a given palette
     */
    fun withPalette(palette: ColorPalette): Bitmap32 {
        if (palette == this.palette) {
            return image(keepBlack)
        }
        return pixelIndices().withPalette(palette)
    }

    override fun flipX(): SpriteFrameAsync {
        return copy(
            disposeGetter = null,
            getPixelIndices = { pixelIndices().flipX() }
        )
    }

    override fun flipY(): SpriteFrameAsync {
        return copy(
            disposeGetter = null,
            getPixelIndices = { pixelIndices().flipY() }
        )
    }
}