package com.bedalton.creatures.agents.pray.compiler.caos2pray.internal

import com.bedalton.creatures.agents.pray.compiler.DEPENDENCY_TAG_REGEX
import com.bedalton.creatures.agents.pray.compiler.caos2pray.Caos2PrayCommands
import com.bedalton.creatures.agents.pray.compiler.caos2pray.CommandValue
import com.bedalton.creatures.agents.pray.compiler.pray.bestDependencyCategoryForFile
import com.bedalton.creatures.agents.util.internal.ANY_PATH_SEPARATOR
import com.bedalton.creatures.agents.pray.compiler.data.Tag
import com.bedalton.creatures.agents.pray.compiler.data.TextValue


/**
 * Process and com.bedalton.creatures.pray.create dependencies list
 */
internal fun processDependencies(tags: List<Tag.StringTag>, commands: List<CommandValue>): List<Tag<*>> {
    var index = 0
    return commands
        .filter { it.command == Caos2PrayCommands.DEPENDS || it.command == Caos2PrayCommands.ATTACH }
        .flatMap { command ->
            val lineNumber = command.lineNumber
            command.values.flatMap { fileName ->
                makeDependsTag(
                    index = ++index,
                    lineNumber = lineNumber,
                    startIndex = fileName.startIndex,
                    endIndex = fileName.endIndex,
                    fileName = fileName.copy(
                        text = fileName.text.split(ANY_PATH_SEPARATOR).last()
                    )
                )
            }
        } + tags.filter { DEPENDENCY_TAG_REGEX.matches(it.tag) }
        .flatMap { tag ->
            makeDependsTag(
                index = ++index,
                lineNumber = tag.lineNumber,
                startIndex = tag.startIndex,
                endIndex = tag.endIndex,
                fileName = tag.valueRange.copy()
            )
        } + Tag.IntTag(
        lineNumber = -1,
        startIndex = -1,
        endIndex = -1,
        tagRange = TextValue(
            "Dependency Count",
            lineNumber = 0,
            startIndex = -1,
            endIndex = -1,
        ),
        value = TextValue(
            text = "$index",
            lineNumber = 0,
            startIndex = -1,
            endIndex = -1,
        )
    )
}


/**
 * Create a matching set of Dependency tags
 * i.e. "Dependency (n)" and "Dependency Category (n)"
 */
private fun makeDependsTag(
    index: Int,
    lineNumber: Int,
    startIndex: Int,
    endIndex: Int,
    fileName: TextValue,
): List<Tag<*>> {
    return listOf(
        Tag.StringTag(
            lineNumber = lineNumber,
            startIndex = startIndex,
            endIndex = endIndex,
            tagRange = TextValue(
                text = "Dependency $index",
                lineNumber = lineNumber,
                startIndex = fileName.startIndex,
                endIndex = fileName.endIndex
            ),
            value = fileName
        ),
        Tag.IntTag(
            lineNumber = lineNumber,
            startIndex = startIndex,
            endIndex = endIndex,
            tagRange = TextValue(
                "Dependency Category $index",
                lineNumber = lineNumber,
                startIndex = fileName.startIndex,
                endIndex = fileName.endIndex
            ),
            value = TextValue(
                text = "${(bestDependencyCategoryForFile(fileName.text) ?: -1)}",
                lineNumber = lineNumber,
                startIndex = fileName.startIndex,
                endIndex = fileName.endIndex
            )
        )
    )
}
