@file:Suppress("unused", "MemberVisibilityCanBePrivate")

package com.bedalton.creatures.breed.render.support.pose

import com.bedalton.creatures.common.structs.GameVariant
import kotlin.jvm.JvmStatic

object PoseStringUtil {


    private val validBodyPoseChars = arrayOf('0', '1', '2', '3', '4', '?', '!', 'X')
    private val validHeadPoseChars = arrayOf('0', '1', '2', '3', '4', '5', '?')
    private val validPartPoseChars = arrayOf('0', '1', '2', '3', 'X')
    private val noPartPoseChars = emptyArray<Char>()

    fun toPoseString(pose: Pose): String {
        return pose.run {
            val out = StringBuilder()
            out.append(pose.bodyFacing.char)
            when (pose.headFacing) {
                PoseFacing.VIEWER_LEFT, PoseFacing.VIEWER_RIGHT -> out.append(head.int)
                PoseFacing.FRONT -> out.append(4)
                PoseFacing.BACK -> out.append(5)
                else -> out.append(headFacing.char)
            }
            out.append(body.int)
            out.append(leftThigh.int)
            out.append(leftShin.int)
            out.append(leftFoot.int)
            out.append(rightThigh.int)
            out.append(rightShin.int)
            out.append(rightFoot.int)
            out.append(leftUpperArm.int)
            out.append(leftForearm.int)
            out.append(rightUpperArm.int)
            out.append(rightForearm.int)
            out.append(tailBase?.int ?: Tilt.STRAIGHT)
            out.append(tailTip?.int ?: Tilt.STRAIGHT)

            out.toString()
        }
    }


    @Throws(PoseException::class)
    @JvmStatic
    fun fromPoseString(
        variant: GameVariant,
        poseString: String,
    ): Pose {

        // If pose string has known issues, throw error
        getPoseStringErrorMessage(poseString)?.let { poseStringError ->
            throw PoseException(poseStringError)
        }

        // Get body facing
        val bodyFacing = PoseFacing.fromChar(poseString[0])
            ?: throw PoseException("Invalid body pose direction. Expected [0,1,2,3,?,!,X]; Found ${poseString[0]}")

        // Get both head tilt and facing from the same char
        val headChar = poseString[1]
        val (headFacing, headTilt) = getHeadFacingAndTilt(bodyFacing, headChar)

        // Get tilts, reformatting exceptions if any
        val tilts = poseString.toCharArray().slice(2..poseString.lastIndex)
                .map { Tilt.fromChar(it) }

        return try {
            Pose(
                variant,
                headFacing = headFacing,
                head = headTilt,
                bodyFacing = bodyFacing,
                body = tilts[0] ?: Tilt.STRAIGHT,
                leftThigh = tilts[1]!!,
                leftShin = tilts[2]!!,
                leftFoot = tilts[3]!!,
                rightThigh = tilts[4]!!,
                rightShin = tilts[5]!!,
                rightFoot = tilts[6]!!,
                leftUpperArm = tilts[7]!!,
                leftForearm = tilts[8]!!,
                rightUpperArm = tilts[9]!!,
                rightForearm = tilts[10]!!,
                tailBase = tilts[11],
                tailTip = tilts[12]
            )
        } catch (e: Exception) {
            throw if (e is NullPointerException) {
                PoseException("Invalid pose value. Expected [0,1,2,3,X]; Found: $poseString")
            } else {
                e
            }
        }
    }

    /**
     * Calculates the combo box pose, tilt and mood.
     */
    private fun getHeadFacingAndTilt(
        bodyFacing: PoseFacing,
        pose: Char
    ): Pair<PoseFacing, Tilt> {
        val facing = when (pose) {
            '4' -> {
                if (bodyFacing != PoseFacing.BACK) {
                    PoseFacing.FRONT
                } else {
                    PoseFacing.BACK
                }
            }

            '5' -> if (bodyFacing != PoseFacing.FRONT) {
                PoseFacing.BACK
            } else {
                PoseFacing.FRONT
            }
            '?', '!' -> {
                // If body facing is concrete, use it
                if (bodyFacing.int != null) {
                    bodyFacing
                    // Body facing is concrete but not left right
                } else {
                    PoseFacing.FRONT
                }
            }
            // No change, so use body facing
            else -> bodyFacing
        }
        val tilt = when (pose) {
            '0' -> Tilt.DOWN
            '1' -> Tilt.STRAIGHT
            '2' -> Tilt.UP
            '3' -> Tilt.FAR_UP
            else /* 'X', '!', '?' */ -> Tilt.STRAIGHT
        }
        return Pair(facing, tilt)
    }

    @JvmStatic
    fun getPoseStringErrorMessage(poseStringIn: String): String? {
        val poseString = poseStringIn.uppercase().trim()
        if (poseString.length < 15) {
            return "Invalid pose length. Expected 15. Found ${poseString.length}"
        }

        // Builds pose highlighting errors
        val outPose = StringBuilder()

        // Check direction
        var pose = poseString[0]
        var valid = pose in validBodyPoseChars
        outPose.append(pose, valid)


        // Check Head
        pose = poseString[1]
        valid = pose in validHeadPoseChars
        outPose.append(pose, valid)


        // Check parts
        for (i in 2 until 15) {
            pose = poseString[i]
            outPose.append(pose, pose in validPartPoseChars)
        }

        val poseWithHighlightedErrors = outPose.toString()
        if (poseWithHighlightedErrors.contains('[')) {
            return "Invalid pose chars: '$poseWithHighlightedErrors'"
        }

        if (poseString.length > 15) {
            return "Extraneous characters: ${poseStringIn.substring(0,15)}[${poseString.substring(15)}]"
        }

        return null
    }


    @JvmStatic
    fun walkPoseString(poseStringIn: String, on: (i: Int, char: Char?, valid: Boolean, validChars: Array<Char>) -> Unit): Boolean  {
        val poseString = poseStringIn.uppercase()

        var allOkay = true

        // Check direction
        allOkay = walkPartPose(0, poseString, validBodyPoseChars, on) && allOkay

        // Check Head
        allOkay = walkPartPose(1, poseString, validHeadPoseChars, on) && allOkay

        // Check parts
        for (i in 2 until 15) {
            allOkay = walkPartPose(i, poseString, validPartPoseChars, on) && allOkay
        }

        if (poseString.length > 15) {
            allOkay = false
            for (i in 16 .. poseString.lastIndex) {
                on(i, poseString[i], false, noPartPoseChars)
            }
        }

        return allOkay
    }

    private fun walkPartPose(i: Int, poseString: String, validPoses: Array<Char>, on: (i: Int, char: Char?, valid: Boolean, validChars: Array<Char>) -> Unit): Boolean {
        val pose = poseString.getOrNull(i)
        val valid = pose in validPoses
        on(i, pose, valid, validPoses)
        return valid
    }
}


private fun StringBuilder.append(pose: Char, valid: Boolean): StringBuilder {
    return if (valid) {
        append(pose)
    } else {
        append('[').append(pose).append(']')
    }
}