package com.bedalton.io.bytes

import com.bedalton.common.structs.AlreadyDisposedDataCacheException
import com.bedalton.common.util.gcCollectIfMemoryConstrained
import okio.Buffer
import okio.ByteString
import okio.ByteString.Companion.toByteString

class MemoryByteStreamReader(
    bytes: ByteString,
    private val start: Int = 0,
    private val end: Int = bytes.size
): ByteStreamReader() {

    constructor(
        bytes: ByteArray,
        start: Int = 0,
        end: Int = bytes.size
    ): this(
        bytes.toByteString(),
        start,
        end
    )

    override val size: Long by lazy {
        (end - start).toLong()
    }

    private val trueSize by lazy {
        bytes.size
    }

    override val closed: Boolean
        get() = mByteString == null


    private var mPosition = 0L

    private var mByteString: ByteString? = bytes

    private val byteString: ByteString get() = mByteString
        ?: throw AlreadyDisposedDataCacheException("Byte stream already closed")

    private var mBuffer: Buffer? = null

    private val buffer: Buffer get() {
        mBuffer?.let {
            return it
        }
        val buffer = Buffer()
        buffer.write(byteString.substring(start, end))
        this.mBuffer = buffer
        return buffer
    }

    init {
        if (start < 0) {
            throw IndexOutOfBoundsException("Cannot set memory byte stream start less than 0")
        }
        if (end > trueSize) {
            throw IndexOutOfBoundsException("Cannot set memory stream end past end of stream")
        }
    }

    override fun toByteArray(): ByteArray = byteString.toByteArray()

    override fun get(): Byte {
        return buffer.readByte().also {
            ++mPosition
        }
    }

    override fun char(): Char {
        return buffer.readByte().toInt().toChar().also {
            ++mPosition
        }
    }

    override fun position(): Long = mPosition

    override fun setPosition(newPosition: Long): MemoryByteStreamReader {
        if (newPosition > Int.MAX_VALUE) {
            throw NotEnoughBytesException("Memory buffer position cannot be larger than a signed int32")
        }
        val positionLong = mPosition
        if (newPosition == positionLong) {
            return this
        }
        if (newPosition > positionLong) {
            val positionOffset = newPosition - positionLong
            mPosition = newPosition
            buffer.skip(positionOffset)
            return this
        }
        // Recreate original buffer so we can skip bytes
        mBuffer = null
        buffer.skip(newPosition)
        mPosition = newPosition
        return this
    }


    override fun copy(): MemoryByteStreamReader {
        return MemoryByteStreamReader(
            byteString,
            start,
            end
        ).also {
            setPosition(this.position())
        }
    }

    /**
     * @param end exclusive
     */
    override fun copyOfBytes(start: Long, end: Long): ByteArray {
        if (start < 0) {
            throw Exception("ByteBuffer copy of range is invalid. Start index cannot be less than zero")
        }
        if (end > size) {
            throw NotEnoughBytesException("ByteBuffer copy of range is invalid. EndOffset $end > $size")
        }
        val offsetStart = this.start + start.toInt()
        val offsetEnd = this.start + end.toInt()
        val byteArray = ByteArray(offsetEnd - offsetStart)
        byteString.copyInto(offsetStart,  byteArray, 0, offsetEnd - offsetStart)
        return byteArray
    }


    /**
     * @param end exclusive
     */
    override fun copyOfRange(start: Long, end: Long): MemoryByteStreamReader {
        if (start < 0) {
            throw Exception("ByteBuffer copy of range is invalid. Start index cannot be less than zero")
        }
        if ((this.start + start) >= this.end) {
            throw Exception("Cannot set start past end of stream")
        }
        if ((this.start + end) > this.end) {
            throw NotEnoughBytesException("ByteBuffer copy of range is invalid. EndOffset $end > $size")
        }

        val offsetStart = this.start + start.toInt()
        val offsetEnd = this.start + end.toInt()
        return MemoryByteStreamReader(byteString, offsetStart, offsetEnd)
    }

    override fun canReopen(): Boolean {
        return false
    }

    override fun copyAsOpened(): ByteStreamReader {
        return mByteString?.let { bytes ->
            MemoryByteStreamReader(bytes, start, end)
        } ?: throw AlreadyDisposedDataCacheException("Cannot copy already closed memory byte stream")
    }

    override fun close(): Boolean {
        mByteString = null
        mBuffer?.close()
        mBuffer = null
        gcCollectIfMemoryConstrained()
        return true
    }

    override fun uInt16(): Int {
        mPosition += 2
        return buffer.readShortLe().toInt() and 0xFFFF
    }

    override fun uInt16BE(): Int {
        mPosition += 2
        return buffer.readShort().toInt() and 0xFFFF
    }

    override fun uInt32(): Long {
        mPosition += 4
        return buffer.readIntLe().toLong() and 0xffffffffL
    }

    override fun uInt32AsInt(): Int {

        mPosition += 4
        return (buffer.readIntLe() and (0xffffffffL).toInt())
    }

    override fun uInt32BE(): Long {
        mPosition += 4
        return buffer.readInt().toLong() and 0xffffffffL
    }
//
//    override fun bytes(length: Int): ByteArray {
//        mPosition += length
//        val out = ByteArray(length)
//        buffer.read(out)
//        return out
//    }

    override fun bytes(length: Int): ByteArray {
        val position = mPosition
        mPosition += length
        buffer.skip(length.toLong())
        return byteString.substring(position.toInt(), position.toInt() + length).toByteArray()
    }

    override fun bytes(length: Long): ByteArray {
        var position = mPosition
        this.buffer.skip(length)
        mPosition += length
        var bytesLeft = length
        val out = Buffer()
        while (bytesLeft > Int.MAX_VALUE) {
            out.write(byteString.substring(position.toInt(), position.toInt() + Int.MAX_VALUE))
            bytesLeft -= Int.MAX_VALUE
            position += Int.MAX_VALUE
        }
        if (bytesLeft > 0) {
            out.write(byteString.substring(position.toInt(), position.toInt() + bytesLeft.toInt()))
        }
        return out.readByteArray()
    }

    override fun byte(): Int {
        mPosition++
        return buffer.readByte().toInt() and 0xFF
    }

    override fun uByte(): UByte {
        mPosition += 1
        return (buffer.readByte().toInt() and 0xFF).toUByte()
    }

    override fun copyOfBytes(start: Int, end: Int): ByteArray {
        val out = ByteArray(end - start)
        byteString.copyInto(start, out, 0, end - start)
        return out
    }

    override fun int16(): Int {
        mPosition += 2
        return buffer.readShortLe().toInt()
    }


    override fun uShort(): UShort {
        mPosition += 2
        return buffer.readShortLe().toUShort()
    }

    override fun int16BE(): Int {
        mPosition += 2
        return buffer.readShort().toInt()
    }

    override fun int32(): Int {
        mPosition += 4
        return buffer.readIntLe()
    }


    override fun uInt(): UInt {
        mPosition += 4
        return buffer.readIntLe().toUInt()
    }

    override fun int32BE(): Int {
        mPosition += 4
        return buffer.readInt()
    }

    override fun int64(): Long {
        mPosition += 8
        return buffer.readLongLe()
    }

    override fun uLong(): ULong {
        mPosition += 8
        return buffer.readLongLe().toULong()
    }

    override fun int64BE(): Long {
        mPosition += 8
        return buffer.readLong()
    }

    override fun peakUInt8(): Int? {
        return try {
            buffer.peek().readByte().toInt() and  0xFF
        } catch (_: Exception) {
            return null
        }
    }

    override fun peakUInt16(): Int? {
        return try {
            buffer.peek().readShortLe().toInt() and 0xFFFF
        } catch (_: Exception) {
            null
        }
    }

    override fun peakToken(steps: Int): Int? {
        val position = (position() + steps).toInt()
        val bytes = byteString
        return try {
            bytes.uInt8(position) shl 24 or
                    (bytes.uInt8(position + 1) shl 16) or
                    (bytes.uInt8(position + 2) shl 8) or
                    bytes.uInt8(position + 3)
        } catch (_: Exception) {
            null
        }
    }

    override fun peakUInt16(bytesForward: Int): Int? {
        val position = position().toInt() + bytesForward
        return try {
            byteString.uInt16(position)
        } catch (_: Exception) {
            null
        }
    }

    override fun peakUInt8(steps: Int): Int? {
        val position = position().toInt() + steps
        return try {
            byteString.uInt8(position)
        } catch (_: Exception) {
            null
        }
    }

    override fun string(length: Int): String {
        val position = position().toInt()
        mPosition += length
        buffer.skip(length.toLong())
        return byteString
            .decodeToWindowsCP1252(position, position + length)
    }

    override fun string(length: Long): String {
        return string(length.toInt())

    }

    override fun stringUTF8(length: Int): String {
        val position = position().toInt()
        mPosition += length
        buffer.skip(length.toLong())
        return byteString
            .substring(position, (position + length))
            .toByteArray()
            .decodeToString()
    }

    override fun stringUTF8(length: Long): String {
        return stringUTF8(length.toInt())
    }

    override fun cString(): String {
        val position = position().toInt()
        var length = 0
        val nullByte = 0.toByte()

        while (byteString[position + length++] != nullByte) {
            // ignore
        }

        buffer.skip(length.toLong())
        mPosition += length

        if (length <= 1) {
            return ""
        }

        return byteString
            .substring(position, position + length - 1)
            .toByteArray()
            .decodeToWindowsCP1252()
    }
    override fun offset(offset: Int): MemoryByteStreamReader {
        return offset(offset.toLong())
    }

    override fun offset(offset: Long): MemoryByteStreamReader {
        if (offset == 0L) {
            return this
        }
        if (offset < 0) {
            setPosition(position() - offset)
        }
        mPosition += offset.toInt()
        buffer.skip(offset)
        return this
    }
}