/**
 * Helper class to return sprite files matched to ATTs
 */
object BreedFileUtil {

    private const val DEFAULT_CLOSE_ATT_MATCH_ONLY = true

    // This considers same breed and genus, but different ages and genders
    private const val MINIMUM_MAX_PART_DISTANCE_CONSIDERED = 16
    private const val MINIMUM_MAX_PART_DISTANCE_CONSIDERED_OLD = MINIMUM_MAX_PART_DISTANCE_CONSIDERED + 2

    @Suppress("SpellCheckingInspection")
    private val ALL_PARTS_CHAR_SET = "abcdefghijklmnopq".toCharArray().toSet()

    /**
     * Gets all available distinct breeds represented in sprites located within the source sets
     */
    fun availableBreeds(
        gameVariant: GameVariant,
        files: List<BreedFileData>,
    ): Set<BreedKey> {
        val sprites = variantSprites(gameVariant, files)

        return sprites
            .map {
                it.breedKey
            }
            .toSet()
    }

    /**
     * Finds all available breed files by variant, that match a given filter
     */
    internal fun availableBreedFiles(
        gameVariant: GameVariant,
        files: List<BreedFileData>,
        closeMatchOnly: Boolean? = null,
        filter: (BreedFileData) -> Boolean = { true }
    ): List<BodyPartFiles> {

        val bodyData = files.filter {
            it.isAtt && it.part in 'a'..'q'
        }

        val sprites = variantSprites(gameVariant, files)

        return sprites.filter(filter).mapNotNull map@{ spriteFile ->
            val part = spriteFile.part
            getData(gameVariant, part, spriteFile, bodyData, null, null, closeMatchOnly)
        }
    }

    /**
     * Gets the nearest matching breed file for a breed part key, with nearest age, gender and breed
     * Only genus is guaranteed to be the same as the key
     */
    @Deprecated(
