    /**
     * Gets the first matching breed file for a breed part key, having the nearest match to age, gender and breed
     * Only genus is guaranteed to be the same
     */
    @Deprecated(
        "Use getBreedFileFuzzyMatch with explicit cancellable coroutine context",
        replaceWith = ReplaceWith(
            "getBreedFileFuzzyMatch(null, files, breedKey, preferredSpriteDirectory, preferredAttDirectory)",
            imports = ["com.bedalton.creatures.breed.render.files.BreedFileUtil"]
        )
    )
    fun getBreedFileFuzzyMatch(
        files: BreedPartFiles,
        breedKey: BreedKey,
        preferredSpriteDirectory: String? = null,
        preferredAttDirectory: String? = null
    ): BodyPartFiles? {
        return getBreedFileFuzzyMatch(null, files, breedKey, preferredSpriteDirectory, preferredAttDirectory)
    }

    /**
     * Gets the first matching breed file for a breed part key, having the nearest match to age, gender and breed
     * Only genus is guaranteed to be the same
     */
    fun getBreedFileFuzzyMatch(
        coroutineContext: CoroutineContext?,
        files: BreedPartFiles,
        breedKey: BreedKey,
        preferredSpriteDirectory: String? = null,
        preferredAttDirectory: String? = null
    ): BodyPartFiles? {

        val part = files.part.lowercaseChar()
        breedKey.assertConcrete("Fuzzy Match for part ${files.part}")

        firstBreedFile(coroutineContext, files, true, preferredSpriteDirectory, preferredAttDirectory) { _, key ->
            part == key.part && breedKey == key.breedKey
        }?.apply {
            return this
        }


        // Create a fuzzy match key which will do initial filter
        val anyAgeGenderOrBreed = breedKey.copyWithGender(null).copyWithAgeGroup(null).copyWithBreed(null)

        // Filter by fuzzy then find breed files with the least amount of distance
        // from key actual, and the fuzzy matches
        return findFuzzyThenClosest(
            coroutineContext = coroutineContext,
            files = files,
            targetBreedKey = breedKey,
            fuzzyBreedKey = anyAgeGenderOrBreed
        )
    }

