            imports = ["com.bedalton.creatures.breed.render.files.BreedFileUtil"]
        )

    )
    fun getBreedFileExactMatch(
        files: BreedPartFiles,
        breedKey: BreedKey,
        preferredSpriteDirectory: String?,
        preferredAttDirectory: String?,
        otherAges: Boolean = true,
        otherGenders: Boolean = true,
    ): BodyPartFiles? {
        return getBreedFileExactMatch(
            null,
            files,
            breedKey,
            preferredSpriteDirectory,
            preferredAttDirectory,
            otherAges,
            otherGenders
        )
    }

    /**
     * Gets the first matching breed file for a breed part key
     */
    fun getBreedFileExactMatch(
        coroutineContext: CoroutineContext?,
        files: BreedPartFiles,
        breedKey: BreedKey,
        preferredSpriteDirectory: String?,
        preferredAttDirectory: String?,
        otherAges: Boolean = true,
        otherGenders: Boolean = true,
    ): BodyPartFiles? {

        val part = files.part.lowercaseChar()
        breedKey.assertConcrete("Exact match for part: $part")
        var i = 0
        firstBreedFile(
            coroutineContext,
            files,
            true,
            preferredSpriteDirectory,
            preferredAttDirectory
        ) { _, key ->
            if (coroutineContext != null && ++i % 14 == 0) {
                coroutineContext.ensureActive()
            }
            part == key.part && BreedKey.isGenericMatch(breedKey, key.breedKey)
        }?.also { match ->
            if (match.attFile != null) {
                return match
            }
        }
        i = 0

        firstBreedFile(
            coroutineContext,
            files,
            false,
            preferredSpriteDirectory,
            preferredAttDirectory
        ) { path, key ->
            if (coroutineContext != null && ++i % 14 == 0) {
                coroutineContext.ensureActive()
            }
            key.breedKey.assertConcrete("Path: $path")
            (part == key.part && BreedKey.isGenericMatch(breedKey, key.breedKey))
        }?.apply {
            if (this.attFile != null) {
                return this
            }
        }

        if (!otherAges && !otherGenders) {
            return null
        }

        // Exact match can possibly include other ages or other genders
        var fuzzyKey = breedKey
        if (otherAges) {
            fuzzyKey = fuzzyKey.copyWithAgeGroup(null)
        }
        if (otherGenders) {
            fuzzyKey = fuzzyKey.copyWithGender(null)
        }

        // Find nearest match in limited fuzzy result
        return findFuzzyThenClosest(coroutineContext, files, breedKey, fuzzyKey)
    }

    private fun findFuzzyThenClosest(
        coroutineContext: CoroutineContext?,
        files: BreedPartFiles,
        targetBreedKey: BreedKey,
        fuzzyBreedKey: BreedKey
    ): BodyPartFiles? {

        val partChar = files.part.lowercaseChar()
        val alternate = if (targetBreedKey.genus == 0 && (targetBreedKey.breed == 'b' || targetBreedKey.breed == 'c')) {
            fuzzyBreedKey.copyWithBreed('a')
        } else {
            null
        }
        var breedFiles = files.inRoot.filterIndexed { i, file ->
            if (coroutineContext != null && i % 14 == 0) {
                coroutineContext.ensureActive()
            }
            (partChar == file.breedPartKey.part && BreedKey.isGenericMatch(
                file.breedPartKey.breedKey,
                fuzzyBreedKey
            ))
        }

        if (breedFiles.isEmpty()) {
            breedFiles = files.inAnyRoot.filterIndexed filter@{ i, file ->
                if (coroutineContext != null && i % 10 == 0) {
                    coroutineContext.ensureActive()
                }
                if (partChar != file.part) {
                    return@filter false
                }
                val match = BreedKey.isGenericMatch(
                    file.breedPartKey.breedKey,
                    fuzzyBreedKey
                )
                if (match || alternate == null) {
                    return@filter match
                }

                BreedKey.isGenericMatch(
                    file.breedPartKey.breedKey,
                    alternate
                )
            }
        }

        return breedFiles.minByOrNull { file ->
            file.breedPartKey.breedKey.assertConcrete(file.toString())
            (targetBreedKey.distance(file.breedPartKey.breedKey) ?: Int.MAX_VALUE)
        }
    }


    fun getBreedFileCollections(
        variant: GameVariant,
        files: List<BreedFileData>,
        requiredParts: Set<Char> = emptySet(),
        optionalParts: Set<Char> = emptySet(),
        inRoot: String? = null,
        closeMatchOnly: Boolean? = null,
        filter: (key: BreedKey) -> Boolean = { true }
    ): List<BreedFileCollection> {
        val raw = getBreedsForPartsInGroups(
            variant, files, requiredParts, optionalParts, inRoot, closeMatchOnly, filter
        )
        return raw.toBreedFileCollections()
    }

    fun getBreedsForPartsInGroups(
        variant: GameVariant,
        files: List<BreedFileData>,
        requiredParts: Set<Char>,
        optionalParts: Set<Char> = emptySet(),
        inRoot: String? = null,
        closeMatchOnly: Boolean? = null,
        filter: (key: BreedKey) -> Boolean = { true }
    ): Map<BreedKey, List<SpriteAndAtt>> {

        val requiredPartsLower = requiredParts.map { it.lowercaseChar() }.toSet()
        val optionalPartsLower = optionalParts.map { it.lowercaseChar() }.toSet()

        // Filter by root if needed
        val filesTemp = if (inRoot != null) {
            val root = inRoot.normalized().ensureEndsWith('/')
            files.filter { it.path.normalized().startsWith(root) }
        } else {
            files
        }

        // Filter out breed parts we do not care about
        val quickFilteredFiles = filesTemp.filter {
            val part = it.part
            (requiredPartsLower.isEmpty() && optionalParts.isEmpty()) || part in requiredPartsLower || part in optionalParts
        }

        // Find all atts in the files list
        val atts = quickFilteredFiles.filter(BreedFileData::isAtt)

        // Get possible breeds which contain any pf these parts
        val keys = availableBreeds(variant, quickFilteredFiles)
            .filter(filter)
            .nullIfEmpty()
            ?: return emptyMap()

        // Convert files into file / breed key pairs
        var sprites = quickFilteredFiles.filter(BreedFileData::isSprite)
        sprites = variantSprites(variant, sprites)

        // Associate each breed key with its list of associated parts
        val partsByKey = keys.associateWith { breedKey ->
            sprites.filter { breedKey.isGenericMatchFor(it.breedKey) }
        }

        // Determine output
        val out = mutableMapOf<BreedKey, List<SpriteAndAtt>>()

        // Go through all available keys and add only breed parts which match all needed parts
        for (key in keys) {

            // Get the breed key's parts
            val partsWithKey = partsByKey[key]
                ?: continue

            // Get breed key chars
            val allPartsChars = partsWithKey.map { it.part }.toSet()
            if (requiredParts.isNotEmpty() && !requiredPartsLower.all { it in allPartsChars }) {
                continue
            }

            val wantedParts: Set<Char> = if (requiredParts.isEmpty() && optionalParts.isEmpty()) {
                ALL_PARTS_CHAR_SET
            } else {
                requiredPartsLower + optionalPartsLower
            }

            // Find sprite/att pairs within the list of files
            val matched = availableBreedFiles(
                variant,
                atts + partsWithKey,
                closeMatchOnly
            ).filter { it.attFile != null && it.part.lowercaseChar() in wantedParts }

            // Find which parts have matching sprites and ATTs
            val matchedPartChars = matched.map { it.part.lowercaseChar() }.distinct().toSet()

            // Do not continue if not all required parts are present
            if (requiredPartsLower.any { it !in matchedPartChars }) {
                continue
            }

            // Add matches to output map
            out[key] = matched.map {
                SpriteAndAtt(
                    it.part.lowercaseChar(),
                    it.breedPartKey.breedKey,
                    spriteFile = it.spriteFile,
                    attFile = it.attFile!!
                )
            }
        }
        return out
    }


    /**
     * Returns the first breed file that matches a given filter and preferred paths
     */
    private inline fun firstBreedFile(
        coroutineContext: CoroutineContext?,
        breedFiles: BreedPartFiles,
        inRootOnly: Boolean,
        preferredAttDirectory: String?,
        preferredSpriteDirectory: String?,
        filter: (spriteFile: BreedFileData, key: BreedPartKey) -> Boolean
    ): BodyPartFiles? {

        // Find match in root
        val matchInRoot = findInRoot(
            coroutineContext,
            breedFiles.inRoot,
            preferredSpriteDirectory,
            preferredAttDirectory,
            filter
        )

        // Return if only searching root OR there is a preferred paths match
        if (inRootOnly || matchInRoot?.second == true) {
            return matchInRoot?.first
        }

        // Find match in any root, hopefully in preferred paths
        val inAnyRootMatch = findInRoot(
            coroutineContext,
            breedFiles.inAnyRoot,
            preferredSpriteDirectory,
            preferredAttDirectory,
            filter
        )

        // If preferred match in any root, return it
        // else return the original match in root
        return if (inAnyRootMatch != null && (inAnyRootMatch.second || matchInRoot == null)) {
            inAnyRootMatch.first
        } else {
            matchInRoot?.first
        }
    }


    /**
     *
     */
    private inline fun findInRoot(
        coroutineContext: CoroutineContext?,
        root: List<BodyPartFiles>,
        preferredSpriteDirectory: String?,
        preferredAttDirectory: String?,
        filter: (spriteFile: BreedFileData, key: BreedPartKey) -> Boolean
    ): Pair<BodyPartFiles, Boolean>? {
        // do a simple check if no preferred paths
        if (preferredSpriteDirectory == null && preferredAttDirectory == null) {
            return findMatchWithoutPreferredPaths(root, filter)?.let {
                Pair(it, true)
            }
        }

        // Try to find matches in preferred path first
        return findMatchInPreferredPaths(
            coroutineContext,
            root,
            preferredSpriteDirectory,
            preferredAttDirectory,
            filter
        )
    }

    private inline fun findMatchWithoutPreferredPaths(
        root: List<BodyPartFiles>,
        filter: (spriteFile: BreedFileData, key: BreedPartKey) -> Boolean
    ): BodyPartFiles? {
        val match = root.firstNotNullOfOrNull find@{ file ->
            if (!filter(file.spriteFile, file.breedPartKey)) {
                return@find null
            }
            file
        }
        return match
    }

    private inline fun findMatchInPreferredPaths(
        coroutineContext: CoroutineContext?,
        root: List<BodyPartFiles>,
        preferredSpriteDirectory: String?,
        preferredAttDirectory: String?,
        filter: (spriteFile: BreedFileData, key: BreedPartKey) -> Boolean
    ): Pair<BodyPartFiles, Boolean>? {

        // Preferred directories
        val preferredSpriteDirectoryLower = preferredSpriteDirectory?.lowercase()
        val preferredAttDirectoryLower = preferredAttDirectory?.lowercase()

        // Possible Atts and Sprite, matching filter, but possibly not preferred path
        val possibleAtt = Pointer<BodyPartFiles?>(null)
        val possibleSprite = Pointer<BodyPartFiles?>(null)

        // Check if possible sprite/att were found in preferred paths
        val foundSpriteInPreferredPath = Pointer(false)
        val foundAttInPreferredPath = Pointer(false)

        // Find first possible match
        val match = root.withIndex().firstNotNullOfOrNull find@{ (i, file) ->
            if (coroutineContext != null && i % 14 == 0) {
                coroutineContext.ensureActive()
            }

            if (!filter(file.spriteFile, file.breedPartKey)) {
                return@find null
            }

            val matchesSprite = applyInPreferredPath(
                file,
                preferredSpriteDirectoryLower,
                file.spriteFile,
                possibleSprite,
                foundSpriteInPreferredPath
            )

            val matchesAtt = file.attFile != null && applyInPreferredPath(
                file,
                preferredAttDirectoryLower,
                file.attFile,
                possibleAtt,
                foundAttInPreferredPath
            )

            if (matchesAtt && matchesSprite) {
                foundSpriteInPreferredPath.value = true
                foundAttInPreferredPath.value = true
                file
            } else if (foundSpriteInPreferredPath.value && foundAttInPreferredPath.value) {
                combinePossibleBodyPartFiles(possibleSprite, possibleAtt)
            } else {
                // Keep chugging along to check for valid match
                null
            }
        } ?: combinePossibleBodyPartFiles(possibleSprite, possibleAtt)
        return if (match != null) {
            Pair(match, foundSpriteInPreferredPath.value && foundAttInPreferredPath.value)
        } else {
            null
        }
    }

    private fun combinePossibleBodyPartFiles(
        spriteFile: BodyPartFiles,
        attFile: BodyPartFiles
    ): BodyPartFiles? {
        if (spriteFile.part != attFile.part) {
            return null
        }
        return spriteFile.copy(
            attFile = attFile.attFile,
        )
    }

    private fun combinePossibleBodyPartFiles(
        spritePointer: Pointer<BodyPartFiles?>,
        attPointer: Pointer<BodyPartFiles?>
    ): BodyPartFiles? {
        val spriteFile = spritePointer.value
            ?: return null
        val attFile = attPointer.value
            ?: return null
        return combinePossibleBodyPartFiles(spriteFile, attFile)
    }

    private fun applyInPreferredPath(
        file: BodyPartFiles,
        preferredPath: String?,
        breedFile: BreedFileData?,
        foundFile: Pointer<BodyPartFiles?>,
        foundInPreferredPath: Pointer<Boolean>
    ): Boolean {

        // If preferred directory is set, use it
        if (preferredPath == null) {
            foundInPreferredPath.value = true
            if (foundFile.value == null) {
                foundFile.value = file
            }
            return true
        }

        val found = breedFile?.path?.lowercase()?.startsWith(preferredPath)
        if (foundFile.value == null || found != false) {
            foundFile.value = file
        }
        if (found != false) {
            foundInPreferredPath.value = true
        }
        return found != false
    }

    /**
     * Creates a BreedPartData object for the given sprite, and the body data that matches it
     */
    internal fun getData(
        gameVariant: GameVariant,
        part: Char,
        spriteFile: BreedFileData,
        bodyData: List<BreedFileData>,
        attRoot: String?,
        paletteTransform: PaletteTransform?,
        closeMatchOnly: Boolean? = null
    ): BodyPartFiles? {
        val key = spriteFile.breedKey
        val attFile = findClosestMatch(spriteFile, key, bodyData, attRoot)
            ?: return null

        if (part.lowercaseChar() != attFile.part) {
            throw PoseRenderException(
                "Att file returned does not match sprite part. Expected: $part; Found: ${attFile.part}"
            )
        }

        // Not sure if this should be a flag or not
        if ((closeMatchOnly ?: DEFAULT_CLOSE_ATT_MATCH_ONLY)) {
            // Get breed key for the ATT file
            val bodyDataKey = attFile.breedKey

            // Suppress close match only for breeds 'b' (bengal) and 'c' (civet) on DS which use
            // the ATTs of breed 'a' (bruin)
            val suppress = gameVariant.isC3DS &&
                    (key.breed == 'b' || key.breed == 'c') &&
                    bodyDataKey.breed == 'a' &&
                    key.genus == 0 && bodyDataKey.genus == 0
            if (!suppress && !key.copyWithGender(null).copyWithAgeGroup(null).isGenericMatchFor(bodyDataKey)) {
                return null
            }
        }
        return BodyPartFiles(
            part = part.lowercaseChar(),
            gameVariant = gameVariant,
            spriteFile = spriteFile,
            attFile = attFile,
            paletteTransform = paletteTransform
        )
    }

    /**
     * Finds the ATT that is closest to the sprite file, both by breed part distance and physical distance
     */
    private fun findClosestMatch(
        sprite: BreedFileData,
        spriteBreedKey: BreedKey,
        attFiles: List<BreedFileData>,
        attRoot: String?
    ): BreedFileData? {
        if (attFiles.isEmpty()) {
            return null
        }

        val part = sprite.part

        // Calculate an ATTs distance to the given sprite
        val filesWithDistance = attFiles.filter { it.part == part }.mapNotNull { attFile ->
            val attBreedKey = attFile.breedKey
            // Breed distance is used to find ATTs that are loose matches
            //  such as when only the male ATTs are given for a breed
            val breedDistance = spriteBreedKey.distance(attBreedKey)
                ?: return@mapNotNull null


            // Find physical distance, and combine it with ATT path and breed part distance
            filePathDistance(
                breedDistance,
                sprite,
                attFile,
                attRoot
            )
        }


        // Only consider the closest half of breed part matches
        val maxPartDistance = filesWithDistance.maxOfOrNull { it.partDistance }
            ?: return null

        // Force considering at least the same genus and breed, but different gender and ages
        val minimumMaxPartDistanceConsidered = if (sprite.ageGroup > 4) {
            MINIMUM_MAX_PART_DISTANCE_CONSIDERED_OLD
        } else {
            MINIMUM_MAX_PART_DISTANCE_CONSIDERED
        }
        val maxPartDistanceConsidered = max(minimumMaxPartDistanceConsidered, ceil(maxPartDistance / 2.0).toInt())

        // Do first filter and sorting based on breed part distance
        val working = filesWithDistance
            .filter { it.partDistance <= maxPartDistanceConsidered }
            .sortedBy { it.partDistance }

        // Will find the first breed file close to the sprites folder
        //  Since files are sorted by breed part distance first, it will find the closest one close to the sprite
        working
            .firstOrNull { it.upDistance < 2 }
            ?.let {
                return it.path
            }

        // Just return the breed matching the nearest part distance
        return working
            .sortedBy { it.computedDistance }
            .firstOrNull { it.partDistance == 0 }?.path
    }

    /**
     * Filters files matching a given parent path
     */
    private fun filterByParent(parent: String, files: List<String>): List<String> {
        return files.filter { it.startsWith(parent) }
    }

    /**
     * Simple naive filter for finding sprites for a given variant
     * Does not check file contents, only extensions
     */
    internal fun variantSprites(
        gameVariant: GameVariant,
        files: List<BreedFileData>
    ): List<BreedFileData> {
        return when (gameVariant) {
            GameVariant.C1 -> files.filter { it.extension like "spr" }
            GameVariant.C2 -> files.filter { it.extension like "s16" }
            else -> files.filter { filePath ->
                filePath.extension like "c16" || filePath.extension like "s16"
            }
        }
    }
}

