package com.creaturesforge.application.ui

import com.bedalton.common.util.isNotNullOrEmpty
import com.bedalton.creatures.breed.render.support.pose.PartChars
import com.bedalton.log.LOG_DEBUG
import com.bedalton.log.LOG_VERBOSE
import com.bedalton.log.Log
import com.bedalton.log.iIf
import com.creaturesforge.application.compile.CompileData.AgeGenderStats
import com.creaturesforge.application.ui.html.*
import com.creaturesforge.application.ui.html.id
import kotlinx.atomicfu.atomic
import kotlinx.html.*
