import kotlinx.html.js.table
import kotlinx.html.js.tr
import org.w3c.dom.*

internal class VerifyPanel(private val element: HTMLElement) {

    private val id = nextId

    private val root: HTMLElement by lazy {
        createTableElement()
    }

    private val emptyState: HTMLElement by lazy {
        element.append.article {
            p {
                +"No files defined for project and breed slot"
            }
        }
    }


    private val tbody by lazy {
        root.querySelector(".$TBODY_CLASS") as HTMLTableSectionElement
    }

    private val rows: List<VerifyRow> by lazy {
        (0..6).map { age ->
            VerifyRow(tbody, id, age)
        }
    }

    fun setStatus(stats: List<AgeGenderStats>) {
        if (stats.isEmpty()) {
            clear()
        } else {
            rows.forEach { it.setStats(stats) }
        }
        showEmptyState(stats.isEmpty())
    }

    private fun showEmptyState(show: Boolean) {
        show(root, !show)
        show(emptyState, show)
    }

    private fun show(childElement: HTMLElement, show: Boolean) {
        if (show) {
            childElement.unhide()
        } else {
            childElement.hide()
        }
        childElement.ariaHidden = !show
    }

    private fun createTableElement(): HTMLTableElement {
        val idPrefix = "verify-$id-header"
        val maleHeaderId = "$idPrefix-male"
        val femaleHeaderId = "$idPrefix-female"
        return element.append.table {
            thead {
                tr {
                    row()

                    th {
                        columnHeader()
                        colSpan = "1"
                        ariaHidden = true
                    }

                    th {
                        id = maleHeaderId
                        colSpan = "2"
                        columnHeader()
                        +"Male"
                    }

                    th {
                        id = femaleHeaderId
                        colSpan = "2"
                        columnHeader()
                        +"Female"
                    }
                }

                tr {
                    row()
                    th {
                        columnHeader()
                        id = "$idPrefix-age"
                        classes += "verify-age-header"
                        +"Age"
                    }
                    th {
                        columnHeader()
                        id = "$maleHeaderId-sprites"
                        classes += "verify-sprites-header"
                        +"Sprites"
                    }
                    th {
                        columnHeader()
                        id = "$maleHeaderId-atts"

                        classes += "verify-att-header"
                        +"ATT"
                    }
                    th {
                        columnHeader()
                        id = "$femaleHeaderId-sprites"
                        classes += "verify-sprites-header"
                        +"Sprites"
                    }
                    th {
                        columnHeader()
                        id = "$femaleHeaderId-atts"
                        classes += "verify-att-header"
                        +"ATT"
                    }
                }
            }
            tbody {
                classes += TBODY_CLASS
            }
            consumer.finalize()
        }
    }

    private fun clear() {
        rows.forEach(VerifyRow::clear)
    }

    companion object {
        private var mLastId = atomic(1)
        private val nextId get() = mLastId.incrementAndGet()
        private const val TBODY_CLASS = "verify-tbody"
    }
}


private class VerifyRow(parent: HTMLElement, val parentId: Int, val age: Int) {

    val root: HTMLTableRowElement by lazy {

        val idPrefix = "verify-$parentId-header"
        val maleHeaderId = "$idPrefix-male"
        val femaleHeaderId = "$idPrefix-female"

        parent.append.tr {
            row()
            td {
                classes += "verify-age-value"
                +"Age $age"
            }
            td {
                classes += "male-sprites-value"
                classes += "verify-sprites-value"
                attributes["data-values-for"] = "sprites"
                ariaLabelledBy = "$maleHeaderId $maleHeaderId-sprites"
            }

            td {
                classes += "male-atts-value"
                classes += "verify-atts-value"

                attributes["data-values-for"] = "atts"
                ariaLabelledBy = "$maleHeaderId $maleHeaderId-atts"
            }

            td {
                classes += "female-sprites-value"
                classes += "verify-sprites-value"

                attributes["data-values-for"] = "sprites"
                ariaLabelledBy = "$femaleHeaderId $femaleHeaderId-sprites"
            }

            td {
                classes += "female-atts-value"
                classes += "verify-atts-value"
                attributes["data-values-for"] = "atts"
                ariaLabelledBy = "$femaleHeaderId $femaleHeaderId-atts"
            }
            consumer.finalize()
        }
    }

    private val maleSpritesElement by lazy {
        root.querySelector(".male-sprites-value") as HTMLTableCellElement
    }

    private val maleAttsElement by lazy {
        root.querySelector(".male-atts-value") as HTMLTableCellElement
    }

    private val femaleSpritesElement by lazy {
        root.querySelector(".female-sprites-value") as HTMLTableCellElement
    }

    private val femaleAttsElement by lazy {
        root.querySelector(".female-atts-value") as HTMLTableCellElement
    }

    private var disabled by BooleanAttributeOf("data-disabled", root)


    private fun hideChild(element: HTMLElement, querySelector: String): HTMLElement? {
        return element.querySelector(querySelector)?.unsafeCast<HTMLElement>()?.also {
            it.hide()
            it.ariaHidden = true
        }
    }

    private fun unhideChild(childElement: HTMLElement) {
        childElement.unhide()
        childElement.ariaHidden = false
    }

    private fun clear(element: HTMLElement) {
        hideChild(element, ".missing-text")?.also {
            it.innerText = ""
        }
        hideChild(element, ".complete-icon")
    }

    private fun missing(element: HTMLElement, missing: List<Char>, shared: List<Char>? = null) {
        val missingAfterShared = if (missing.isNotEmpty() && !shared.isNullOrEmpty()) {
            missing.filter { part -> part !in shared }
        } else {
            missing
        }
        val hasSharedAtts = missingAfterShared.size < missing.size
        element.attribute("data-shared-atts", hasSharedAtts)

        sharedIcon(element, hasSharedAtts && missingAfterShared.isEmpty())

        completeIcon(element, missing.isEmpty())

        element.attribute("data-has-missing", missingAfterShared.isNotEmpty())

        if (missingAfterShared.isEmpty()) {
            element.querySelector(".missing-text")?.unsafeCast<HTMLElement>()?.let {
                it.hide()
                it.innerHTML = ""
                it.innerText = ""
                it.title = ""
                it.ariaLabel = null
            }
            element.querySelector(".has-text")?.unsafeCast<HTMLElement>()?.let {
                it.innerHTML = ""
                it.hide()
                it.innerText = ""
                it.title = ""
                it.ariaLabel = null
            }
            element.ariaLabel = null
        } else {
            val missingRuns = getRuns(missingAfterShared).joinToString()
            val cvParts = 'O'..'Q'
            val hasWithShared = PartChars.ALL_PARTS.filter { it.uppercaseChar() !in missingAfterShared && it.uppercaseChar() !in cvParts }
            val hasRuns = getRuns(hasWithShared).joinToString()

            (element.querySelector(".has-text")?.unsafeCast<HTMLElement>() ?: element("span") { element.appendChild(this); classList.add("has-text") } ).apply {
                if (hasRuns.isEmpty()) {
                    this.unhide()
                    this.innerText = hasRuns
                    this.title = "Has Parts: $hasRuns"
                    this.ariaLabel = "has: $hasRuns"
                } else {
                    this.hide()
                    this.innerText = ""
                    this.title = ""
                    this.ariaLabel = null
                }
            }
            (element.querySelector(".missing-text")?.unsafeCast<HTMLElement>() ?: missingLabel(element)).apply {
                unhide()
                this.innerText = missingRuns
                this.title = "Missing Parts: $missing"
                this.ariaLabel = "missing: $missing"
            }
        }
    }

    private fun completeIcon(parentElement: HTMLElement, show: Boolean) {
        if (show) {
            val icon = parentElement.querySelector(".complete-icon") ?: okayImage(parentElement.getAttribute("data-values-for") ?: "parts").apply {
                parentElement.appendChild(this)
            }
            icon.classList.remove("hidden")
            icon.ariaHidden = false
            icon.removeAttribute("hidden")
        } else {
            parentElement.querySelector(".complete-icon")?.also { icon ->
                icon.classList.add("hidden")
                icon.ariaHidden = true
                icon.setAttribute("hidden", "hidden")
            }
        }
    }

    private fun sharedIcon(parentElement: HTMLElement, show: Boolean) {
        if (show) {
            val icon = parentElement.querySelector(".shared-icon") ?: sharedImage(parentElement.getAttribute("data-values-for") ?: "parts").apply {
                parentElement.appendChild(this)
            }
            icon.classList.remove("hidden")
            icon.ariaHidden = false
            icon.removeAttribute("hidden")
        } else {
            parentElement.querySelector(".shared-icon")?.also { icon ->
                icon.classList.add("hidden")
                icon.ariaHidden = true
                icon.setAttribute("hidden", "hidden")
            }
        }
    }

    private fun setStats(stats: AgeGenderStats?, spritesField: HTMLElement, attsField: HTMLElement) {
        if (stats == null) {
            spritesField.innerText = ""
            attsField.innerText = ""
            attsField.attribute("data-shared-atts", false)
        } else {
            missing(spritesField, stats.missingSprites)
            Log.iIf(LOG_DEBUG) {
                "Age $age; Gender: ${stats.gender}; Missing: [Sprites=${stats.missingSprites}, Atts=${stats.missingAtts}]"
            }

            missing(attsField, stats.missingAtts, stats.shared)
        }
    }

    private fun setStats(maleStats: AgeGenderStats?, femaleStats: AgeGenderStats?) {
        setStats(maleStats, maleSpritesElement, maleAttsElement)
        setStats(femaleStats, femaleSpritesElement, femaleAttsElement)
        setDisabled(false)
    }

    fun setStats(stats: List<AgeGenderStats>) {
        val statsForAge = stats.filter { it.age == this.age }
        val maleStatsForAge = statsForAge.firstOrNull { it.gender == 1 }
        val femaleStatsForAge = statsForAge.firstOrNull { it.gender == 2 }

        if (maleStatsForAge == null && femaleStatsForAge == null) {
            setDisabled(true)
            return
        }

        if (maleStatsForAge == null) {
            Log.iIf(LOG_VERBOSE) {
                "Male stats for age $age is null; AllStats: [\n\t${stats.joinToString("\n\t")}\n]"
            }
        }
        if (femaleStatsForAge == null) {
            Log.iIf(LOG_VERBOSE) {
                "Female stats for age $age is null; AllStats: [\n\t${stats.joinToString("\n\t")}\n" +
                        "]"
            }
        }
        setStats(maleStatsForAge, femaleStatsForAge)
    }

    fun setDisabled(disabled: Boolean) {
        this.disabled = disabled
        if (disabled) {
            clear()
            root.hide()
        } else {
            root.unhide()
        }

    }


    fun clear() {

        clear(maleSpritesElement)
        clear(maleAttsElement)

        clear(femaleSpritesElement)
        clear(femaleAttsElement)
    }


    companion object {

        fun missingLabel(parentElement: HTMLElement): HTMLElement = element("span") {
            classList.add("missing-text")
            parentElement.appendChild(this)
        }

        fun okayImage(kind: String): Image {
            return element("img") {
                this.src = "src/images/icons/check_circle.svg"
                this.alt = "complete $kind"
                this.ariaLabel = "complete $kind"
                this.title = "complete $kind"
                this.classList.add("complete-icon")
            }
        }

        fun sharedImage(kind: String): Image {
            return element("img") {
                this.src = "src/images/icons/link.svg"
                this.alt = "shared $kind"
                this.ariaLabel = "shared $kind"
                this.title = "shared $kind"
                this.classList.add("shared-icon")
            }
        }

        fun formatRun(start: Char, end: Any): String {
            val endUpper = if (end is Int) {
                end.toChar()
            } else {
                end as Char
            }.uppercaseChar()
            val startUpper = start.uppercaseChar()
            if (startUpper == endUpper) {
                return startUpper.toString()
            }
            return "$startUpper-$endUpper"
        }

        /**
         *
         * @param {string[]} missing
         * @return string[]
         */
        private fun getRuns(missing: List<Char>): List<String> {
            if (missing.isEmpty()) {
                return emptyList()
            }
            if (missing.size == 1) {
                return listOf(missing[0].uppercase())
            }
            val missingMapped = missing.map { p -> p.uppercaseChar() }.sorted()
            val out = mutableListOf<String>()
            var start: Char? = null
            var last: Int? = null
            for (partChar in missingMapped) {
                val partCode = partChar.code
                if (start == null) {
                    start = partChar
                }
                if (last == null) {
                    start = partChar
                } else if (partCode != last + 1) {
                    val run = formatRun(start, last)
                    out.add(run.uppercase())
                    start = partChar
                }
                last = partCode
            }
            val lastChar = last?.toChar()?.uppercaseChar()
            if (lastChar != null && lastChar == start) {
                out.add(lastChar.uppercase())
            } else if (last != null) {
                out.add(formatRun(start ?: last.toChar(), last.toChar()))
            }
            return out
        }
    }
}