@file:Suppress("unused")

import com.bedalton.creatures.sprite.compilers.BLKCompiler
import com.bedalton.creatures.sprite.compilers.SpriteCompiler
import com.bedalton.creatures.sprite.util.ColorEncoding
import com.bedalton.creatures.sprite.util.SpriteType
import kotlinx.coroutines.GlobalScope
import kotlinx.coroutines.asPromise
import kotlinx.coroutines.async
import kotlin.js.Promise


@JsExport
fun createSpriteCompiler(format: String, encoding: String? = null): JsSpriteCompiler {
    val type = SpriteType.fromString(format)
    val colorEncoding = if (encoding != null) {
        ColorEncoding.fromString(encoding)
    } else
        null
    return JsSpriteCompiler(type, colorEncoding)
}

@JsExport
data class JsSpriteCompiler internal constructor(private val format: SpriteType, private val encoding: ColorEncoding?) {
    private val images: MutableList<Pair<String, ByteArray>> = mutableListOf()
    fun addImage(fileName: String, bytes: ByteArray): JsSpriteCompiler {
        images.add(Pair(fileName, bytes))
        return this
    }

    fun compile(formatIn: String? = null, keepBlack: Boolean = false): Promise<ByteArray> {
        val type = formatIn?.let { SpriteType.fromString(it) } ?: format
        val compiler = SpriteCompiler.getCompiler(type)
        return GlobalScope.async {
            compiler.compileSpriteFromImageBytes(images, keepBlack, encoding)
        }.asPromise()
    }
}


@JsExport
fun compileBLK(
    filename: String,
    backgroundBytes: ByteArray
): Promise<ByteArray> {
    return GlobalScope.async {
        BLKCompiler.compileSpriteFromImageBytes(listOf(Pair(filename, backgroundBytes)), true)
    }.asPromise()
}