package com.creaturesforge.application.compile

import com.bedalton.common.coroutines.cancelIfRunning
import com.bedalton.common.util.PathUtil
import com.bedalton.common.util.className
import com.bedalton.common.util.formatted
import com.bedalton.creatures.agents.pray.compiler.PrayCompilerTaskImpl
import com.bedalton.creatures.agents.pray.compiler.compilePrayFileToBytes
import com.bedalton.creatures.agents.pray.compiler.pray.PrayParseValidationFailException
import com.bedalton.log.Log
import com.bedalton.log.iWith
import com.bedalton.state.simple.Dispatch
import com.bedalton.state.simple.Next
import com.creaturesforge.application.state.*
import com.creaturesforge.application.util.LOG_CONSOLE
import com.creaturesforge.application.util.LOG_STATUS
import com.bedalton.common.exceptions.rethrowCancellationException
import kotlinx.coroutines.*

internal object EggCompiler {

    private var mIsCompiling = false
    internal val isCompiling: Boolean get() = mIsCompiling
    private var mJob: CoroutineScope? = null

    internal fun compileMiddleware(
        state: ForgeState,
        action: FAction,
        dispatch: Dispatch<FAction>,
        next: Next<ForgeState, FAction>
    ): FAction {

        return when (action) {
            is CompileEggAction -> {
                mIsCompiling = action is EggCompileRunning
                return next(state, action, dispatch)
            }

            is RequestCompileCancelAction -> {
                mIsCompiling = false
                mJob?.cancel()
                if (mJob?.isActive == true) {
                    throw CancellationException("Coroutine is still not cancelled")
                }
                mJob = null
                return CompileEggCancelledAction
            }

            is RequestCompileAction -> {
                requestCompile(state, action, dispatch)
                next(state, action, dispatch)
            }

            else -> next(state, action, dispatch)
        }
    }

    private fun requestCompile(
        state: ForgeState,
        action: RequestCompileAction,
        dispatch: Dispatch<FAction>,
    ) {
        mJob?.cancelIfRunning("New compile request")
        val job = CoroutineScope(Job())
        mJob = job
        job.launch {
            try {
                compile(state, dispatch, action.outputFile)
            } catch (e: Exception) {
                Log.e("Failed to start compile; ${e.formatted(true)}")
            }
        }
    }

    private suspend fun compile(state: ForgeState, dispatch: Dispatch<FAction>, outputFile: String) {
        mIsCompiling = true

        dispatch(CompileEggStartedAction(outputFile))

        // Build compile data object
        val data = try {
            state.toCompileData(false, outputFile)
        } catch (e: MissingCompileParametersException) {
            dispatch(
                CompileEggFailedAction(
                    e.message ?: MissingCompileParametersException.defaultMessage(e.missing),
                    e
                )
            )
            return
        } catch (e: DuplicateCompileValuesException) {
            dispatch(
                CompileEggFailedAction(
                    e.message!!,
                    e
                )
            )
            return
        }

        try {
            coroutineScope {
                compileAndWrite(this, data, dispatch)
            }
            mIsCompiling = false
        } catch (e: Exception) {
            e.rethrowCancellationException()
            mIsCompiling = false
            dispatch(CompileEggFailedAction(e.message ?: "Uncaught ${e.className} occurred", e))
        }

    }

    /**
     *
     */
    private suspend fun compileAndWrite(
        coroutineScope: CoroutineScope,
        state: CompileData,
        dispatch: Dispatch<FAction>
    ): Boolean {

        val outputPath = state.outputFile

        val fs = vfs

        val opts = PrayCompilerTaskImpl(
            mergeScripts = false,
            validate = true,
            inputFile = "/dummy.cos",
            outputDirectory = outputPath,
            printStats = false,
            mergeRscr = false,
            generateScriptRemovers = false,
            generateAgentRemovers = false,
            logProgress = false,
            joins = emptyArray(),
            isJoin = false,
            compressionLevel = 9,
        )

        val prayData = makePrayFile(state)

        val bytes: ByteArray = try {
            compilePrayFileToBytes(
                coroutineScope,
                fs = fs,
                input = opts,
                subFoldersOnly = false,
                prayData = prayData
            )
        } catch (e: Exception) {
            e.rethrowCancellationException()
            if (e is PrayParseValidationFailException) {
                Log.e { "Failed to compile pray with errors: ${e.formatted()}" }
            }
            dispatch(CompileEggFailedAction(("Failed to compile egg " + (e.message ?: "")).trim(), e))
            return false
        }

        Log.iWith(LOG_STATUS) { "Writing to file..." }

        Log.iWith(LOG_CONSOLE) { "Writing to: outputPath" }

        fs.write(outputPath, bytes)

        dispatch(CompileEggCompletedAction(outputPath))

        val outputFilename = PathUtil.getLastPathComponent(outputPath) ?: outputPath
        Log.iWith(LOG_STATUS) { "Wrote egg file to $outputFilename" }

        return true
    }

}


