package com.creaturesforge.application.ui.pages

import com.bedalton.common.coroutines.launchMain
import com.bedalton.common.util.nullIfEmpty
import com.bedalton.log.Log
import com.creaturesforge.application.state.CompilerListeners
import com.creaturesforge.application.state.onCompileEggAction
import com.creaturesforge.application.ui.controls.CompileButton
import com.creaturesforge.application.ui.html.map
import com.creaturesforge.application.ui.progressLogger
import com.creaturesforge.application.ui.showMessageAndWait
import kotlinx.browser.document
import org.w3c.dom.HTMLButtonElement
import org.w3c.dom.HTMLElement
import tauri.process.exit

@Suppress("MemberVisibilityCanBePrivate")
internal object Pages {

    val body = document.body!!

    private lateinit var mPages: List<Page>

    private val pagesIfInitialized: List<Page> get() = if (this::mPages.isInitialized) {
        mPages
    } else {
        emptyList()
    }

    fun init() {
        Log.i("Initializing pages")
        PageButtons.init()
        initCompileButton()
        addStatusLogging()
        initPages()
        Log.i("Initialized pages")
    }


    private fun initPages() {
        Log.i("Initializing page elements")
        mPages = document
            .querySelectorAll("[data-page]")
            .map<HTMLElement, Page> { Page(it) }
            .nullIfEmpty()
            ?: throw Exception("No pages found in document")
        if (mPages.isEmpty()) {
            throw Exception("No pages found in document")
        }
        Log.i("Found ${mPages.size} pages")
    }

    fun validate() {
        clearErrors()
        for (page in pagesIfInitialized) {
            validate(page)
        }
    }

    fun isValid(): Boolean {
        return pagesIfInitialized.all(Page::isValid)
    }

    fun validate(pageNumber: Int?) {

        if (pageNumber == null) {
            return
        }

        val page = pagesIfInitialized.firstOrNull { it.pageNumber == pageNumber }
            ?: return

        validate(page)
    }

    private fun validate(page: Page) {
        page.validate()
    }

    private fun clearErrors() {
        for (page in pagesIfInitialized) {
            page.clearErrors()
        }
    }

    private fun addStatusLogging() {
        Log.setLogger(progressLogger)
        CompilerListeners.addListener(::onCompileEggAction)
    }

    private fun initCompileButton() {
        val button = (document.getElementById("compile") as? HTMLButtonElement)
        if (button != null) {
            CompileButton(button)
            return
        }
        launchMain(capture = true) {
            showMessageAndWait("Failed to initialize compile button. Application must terminate") {
                title = "Unrecoverable Error"
            }
            exit(1)
        }
    }

}