@JsExport
@Serializable
@SerialName("StimulusGene")
data class CreatureStimulusGene(
    // @ProtoNumber(1)
    @SerialName("version")
    override val version: Int,
    // @ProtoNumber(6)
    @SerialName("gene_index")
    override val geneIndex: Int,
    // @ProtoNumber(7)
    @SerialName("gene_index_of_type")
    override var geneIndexOfType: Int?,
    // @ProtoNumber(8)
    @SerialName("gene_header")
    override val geneHeader: GeneHeader = GeneHeader(version),
    //! @ProtoNumber(12)
    @SerialName("stimulus")
    val stimulus: Int = 0,
    //! @ProtoNumber(13)
    @SerialName("significance")
    val significance: Int = 0,
    //! @ProtoNumber(14)
    @SerialName("sensory_neuron")
    val sensoryNeuron: Int = 0,
    //! @ProtoNumber(15)
    @SerialName("intensity")
    val intensity: Int = 0,
    //! @ProtoNumber(16)
    @SerialName("modulate")
    val modulate: Boolean = false,
    //! @ProtoNumber(17)
    @SerialName("add_offset")
    val addOffset: Boolean = false,
    //! @ProtoNumber(18)
    @SerialName("when_asleep")
    val whenAsleep: Boolean = false,
    //! @ProtoNumber(19)
    @SerialName("drive_amounts")
    val driveAmounts: Array<StimulusDrive> = Array(STIMULUS_DRIVE_COUNT) { StimulusDrive() },
    // @ProtoNumber(9)
    @SerialName("note")
    override val note: GeneNote? = null,
) : Gene() {

    override val geneType: Int
        get() = GENE_TYPE_CREATURE

    override val typeName: String
        get() = GENE_TYPE_NAME_CREATURE

    override val geneSubType: Int
        get() = GENE_SUBTYPE_CREATURE_STIMULUS

    override val subtypeName: String
        get() = GENE_SUBTYPE_NAME_CREATURE_STIMULUS

    override val description: String? get() = null

    init {
        assertValid()
    }

    override fun toJSON(): String {
        return json.encodeToString(serializer(), this)
    }

    override fun withGeneHeader(newHeader: GeneHeader): CreatureStimulusGene {
        return copy(
            geneHeader = newHeader
        )
    }

    override fun withNote(newValue: GeneNote): CreatureStimulusGene {
        return copy(
            note = newValue
        )
    }

    fun withSignificance(newValue: Int): CreatureStimulusGene {
        return copy(
            significance = newValue
        )
    }

    fun withSensoryNeuron(newValue: Int): CreatureStimulusGene {
        return copy(
            sensoryNeuron = newValue
        )
    }

    fun withIntensity(newValue: Int): CreatureStimulusGene {
        return copy(
            intensity = newValue
        )
    }

    fun withModulate(newValue: Boolean): CreatureStimulusGene {
        return copy(
            modulate = newValue
        )
    }

    fun withAddOffset(newValue: Boolean): CreatureStimulusGene {
        return copy(
            addOffset = newValue
        )
    }

    fun withWhenAsleep(newValue: Boolean): CreatureStimulusGene {
        return copy(
            whenAsleep = newValue
        )
    }

    fun withDriveStimulusAt(index: Int, drive: Int, amount: Int): CreatureStimulusGene {
        if (index !in driveAmounts.indices) {
            throw GeneFormatException("Cannot stimulus drive at an index not in valid range of 0..${STIMULUS_DRIVE_COUNT}; Found: $index")
        }
        return copy(
            driveAmounts = driveAmounts.copyOf().apply {
                driveAmounts[index] = StimulusDrive(drive, amount)
            }
        )
    }

    fun withDriveStimuli(stimuli: Array<StimulusDrive>, copyArray: Boolean = true): CreatureStimulusGene {
        return copy(
            driveAmounts = if (copyArray) stimuli.copyOf() else stimuli
        )
    }

    private fun assertValid() {
        if (driveAmounts.size != STIMULUS_DRIVE_COUNT) {
            throw GeneFormatException("Invalid number of Stimulus drive amounts. Expected: $STIMULUS_DRIVE_COUNT; Found: ${driveAmounts.size}")
        }
    }


    private val flags: Int
        get() {
            return (
                    (if (modulate) 1 else 0) or
                            (if (addOffset) 2 else 0) or
                            (if (whenAsleep) 4 else 0) or
                            (if (driveAmounts[0].silent) 16 else 0) or
                            (if (driveAmounts[1].silent) 32 else 0) or
                            (if (driveAmounts[2].silent) 64 else 0) or
                            (if (driveAmounts[3].silent) 128 else 0)
                    )
        }

    override fun writeData(writer: ByteStreamWriter) {
        writer
            .writeUInt8(stimulus)
            .writeUInt8(significance)
            .writeUInt8(sensoryNeuron)
            .writeUInt8(intensity)
            .writeUInt8(flags)
        driveAmounts.forEach {
            writer.writeUInt8(it.drive)
            writer.writeUInt8(it.amount)
        }
    }

    override fun equals(other: Any?): Boolean {
        if (this === other) return true
        if (other == null || this::class != other::class) return false

        other as CreatureStimulusGene

        if (version != other.version) return false
        if (geneIndex != other.geneIndex) return false
        if (geneIndexOfType != other.geneIndexOfType) return false
        if (geneHeader != other.geneHeader) return false
        if (stimulus != other.stimulus) return false
        if (significance != other.significance) return false
        if (sensoryNeuron != other.sensoryNeuron) return false
        if (intensity != other.intensity) return false
        if (modulate != other.modulate) return false
        if (addOffset != other.addOffset) return false
        if (whenAsleep != other.whenAsleep) return false
        if (!driveAmounts.contentEquals(other.driveAmounts)) return false
        return note == other.note
    }

    override fun hashCode(): Int {
        var result = version
        result = 31 * result + geneIndex
        result = 31 * result + (geneIndexOfType ?: 0)
        result = 31 * result + geneHeader.hashCode()
        result = 31 * result + stimulus
        result = 31 * result + significance
        result = 31 * result + sensoryNeuron
        result = 31 * result + intensity
        result = 31 * result + modulate.hashCode()
        result = 31 * result + addOffset.hashCode()
        result = 31 * result + whenAsleep.hashCode()
        result = 31 * result + driveAmounts.contentHashCode()
        result = 31 * result + (note?.hashCode() ?: 0)
        return result
    }


    companion object {
        private const val STIMULUS_DRIVE_COUNT = 4

        internal fun fromReader(version: Int, reader: ByteStreamReader, geneIndex: Int) = fromReader(
            version,
            geneIndex = geneIndex,
            geneIndexOfType = reader.uInt8(),
            geneHeader = GeneHeader.fromReader(version, reader),
            reader.uInt8(),
            reader.uInt8(),
            reader.uInt8(),
            reader.uInt8(),
            reader.uInt8(),
            reader
        )

        internal fun fromReader(
            version: Int,
            geneIndex: Int,
            geneIndexOfType: Int,
            geneHeader: GeneHeader,
            stimulus: Int,
            significance: Int,
            sensoryNeuron: Int,
            intensity: Int,
            flags: Int,
            reader: ByteStreamReader,
        ) = CreatureStimulusGene(
            version = version,
            geneIndex = geneIndex,
            geneIndexOfType = geneIndexOfType,
            geneHeader = geneHeader,
            stimulus = stimulus,
            significance = significance,
            sensoryNeuron = sensoryNeuron,
            intensity = intensity,
            modulate = flags hasFlag 1,
            addOffset = flags hasFlag 2,
            whenAsleep = flags hasFlag 4,
            driveAmounts = Array(STIMULUS_DRIVE_COUNT) { i ->
                StimulusDrive(
                    reader.uInt8(),
                    reader.uInt8(),
                    flags hasFlag ((2.0).pow(4 + i)).toInt()
                )
            }
        )
    }
}


@JsExport
@Serializable
@SerialName("GenusGene")
data class GenusGene(
    // @ProtoNumber(1)
    @SerialName("version")
    override val version: Int,
    // @ProtoNumber(6)
    @SerialName("gene_index")
    override val geneIndex: Int,
    // @ProtoNumber(7)
    @SerialName("gene_index_of_type")
    override var geneIndexOfType: Int?,
    // @ProtoNumber(8)
    @SerialName("gene_header")
    override val geneHeader: GeneHeader = GeneHeader(version),
    //! @ProtoNumber(12)
    @SerialName("genus")
    val genus: Int = 0,
    //! @ProtoNumber(13)
    @SerialName("mum")
    val mum: String = "?".repeat(monikerLength(version)),
    //! @ProtoNumber(14)
    @SerialName("dad")
    val dad: String = "?".repeat(monikerLength(version)),
    // @ProtoNumber(9)
    @SerialName("note")
    override val note: GeneNote? = null,
) : Gene() {

    override val geneType: Int
        get() = GENE_TYPE_CREATURE

    override val typeName: String
        get() = GENE_TYPE_NAME_CREATURE

    override val geneSubType: Int
        get() = GENE_SUBTYPE_CREATURE_GENUS

    override val subtypeName: String
        get() = GENE_SUBTYPE_NAME_CREATURE_GENUS

    override val description: String? get() = null

    init {
        assertValid(version)
    }

    override fun toJSON(): String {
        return json.encodeToString(serializer(), this)
    }

    override fun withGeneHeader(newHeader: GeneHeader): GenusGene {
        return copy(
            geneHeader = newHeader
        )
    }

    override fun withNote(newValue: GeneNote): GenusGene {
        return copy(
            note = newValue
        )
    }

    fun withGenus(newValue: Int): GenusGene {
        return copy(
            genus = newValue
        )
    }

    fun withMum(newValue: String?): GenusGene {
        val expectedLength = monikerLength(version)
        val value = if (newValue.isNullOrBlank()) {
            "?".repeat(expectedLength)
        } else if (newValue.length != expectedLength) {
            throw GeneFormatException("Invalid MUM moniker length. Expected length: $expectedLength; Found: ${newValue.length}")
        } else {
            newValue
        }
        return copy(
            mum = value
        )
    }


    fun withDad(newValue: String?): GenusGene {
        val expectedLength = monikerLength(version)
        val value = if (newValue.isNullOrBlank()) {
            "?".repeat(expectedLength)
        } else if (newValue.length != expectedLength) {
            throw GeneFormatException("Invalid DAD moniker length. Expected length: $expectedLength; Found: ${newValue.length}")
        } else {
            newValue
        }
        return copy(
            dad = value
        )
    }

    private fun assertValid(version: Int) {
        val expectedMonikerLength = monikerLength(version)
        if (mum.length != expectedMonikerLength || dad.length != expectedMonikerLength) {
            throw GeneFormatException("Invalid parent moniker length. Expected $expectedMonikerLength; Found: ${mum.length} and ${dad.length}")
        }
    }

    override fun writeData(writer: ByteStreamWriter) {
        writer
            .writeUInt8(genus)
            .writeStringWithCreaturesEncoding(mum)
            .writeStringWithCreaturesEncoding(dad)
    }

    companion object {
        private const val C1E_MONIKER_LENGTH = 4
        private const val C2E_MONIKER_LENGTH = 32
        private fun monikerLength(version: Int): Int {
            return if (version == 3) {
                C2E_MONIKER_LENGTH
            } else {
                C1E_MONIKER_LENGTH
            }
        }

        internal fun fromReader(version: Int, reader: ByteStreamReader, geneIndex: Int): GenusGene {
            val gene = GenusGene(
                version = version,
                geneIndex = geneIndex,
                geneIndexOfType = reader.uInt8(),
                geneHeader = GeneHeader.fromReader(version, reader),
                genus = reader.uInt8(),
                mum = reader.string(monikerLength(version)),
                dad = reader.string(monikerLength(version))
            )
            return gene
        }
    }
}

