@JsExport
@Serializable
@SerialName("GaitGene")
data class GaitGene(
    // @ProtoNumber(1)
    @SerialName("version")
    override val version: Int,
    // @ProtoNumber(6)
    @SerialName("gene_index")
    override val geneIndex: Int,
    // @ProtoNumber(7)
    @SerialName("gene_index_of_type")
    override var geneIndexOfType: Int?,
    // @ProtoNumber(8)
    @SerialName("gene_header")
    override val geneHeader: GeneHeader = GeneHeader(version),
    //! @ProtoNumber(13)
    @SerialName("drive")
    val drive: Int = 0,
    //! @ProtoNumber(14)
    @SerialName("gait")
    val gait: IntArray = IntArray(GAIT_LENGTH) { 0 },
    // @ProtoNumber(9)
    @SerialName("note")
    override val note: GeneNote? = null,
) : Gene() {

    override val geneType: Int
        get() = GENE_TYPE_CREATURE

    override val typeName: String
        get() = GENE_TYPE_NAME_CREATURE

    override val geneSubType: Int
        get() = GENE_SUBTYPE_CREATURE_GAIT

    override val subtypeName: String
        get() = GENE_SUBTYPE_NAME_CREATURE_GAIT

    override val description: String? get() = null

    init {
        assertValid()
    }

    override fun withGeneHeader(newHeader: GeneHeader): GaitGene {
        return copy(
            geneHeader = newHeader
        )
    }

    override fun withNote(newValue: GeneNote): GaitGene {
        return copy(
            note = newValue
        )
    }

    fun withDrive(newValue: Int): GaitGene {
        return copy(
            drive = newValue
        )
    }

    fun withGait(newValue: IntArray): GaitGene {
        val newValueSize = newValue.size
        if (newValueSize > GAIT_LENGTH) {
            throw GeneFormatException("Invalid gait length. Expected $GAIT_LENGTH; Found: ${newValue.size}")
        }

        val newGait = IntArray(GAIT_LENGTH) { 0 }
        newValue.copyInto(newGait, 0, 0)
        return copy(
            gait = newGait
        )
    }

    private fun assertValid() {
        if (gait.size != GAIT_LENGTH) {
            throw GeneFormatException("Invalid GAIT length for Drive[$drive]. Expected: $GAIT_LENGTH; Found: ${gait.size}")
        }
    }

    override fun writeData(writer: ByteStreamWriter) {
        writer.writeUInt8(drive)
            .writeUInt8Array(gait)

    }

    override fun toJSON(): String {
        return json.encodeToString(serializer(), this)
    }

    override fun equals(other: Any?): Boolean {
        if (this === other) return true
        if (other == null || this::class != other::class) return false

        other as GaitGene

        if (version != other.version) return false
        if (geneIndex != other.geneIndex) return false
        if (geneIndexOfType != other.geneIndexOfType) return false
        if (geneHeader != other.geneHeader) return false
        if (drive != other.drive) return false
        if (!gait.contentEquals(other.gait)) return false
        return note == other.note
    }

    override fun hashCode(): Int {
        var result = version
        result = 31 * result + geneIndex
        result = 31 * result + (geneIndexOfType ?: 0)
        result = 31 * result + geneHeader.hashCode()
        result = 31 * result + drive
        result = 31 * result + gait.contentHashCode()
        result = 31 * result + (note?.hashCode() ?: 0)
        return result
    }


    companion object {
        private const val GAIT_LENGTH = 8

        internal fun fromReader(version: Int, reader: ByteStreamReader, geneIndex: Int) = GaitGene(
            version,
            geneIndex = geneIndex,
            geneIndexOfType = reader.uInt8(),
            geneHeader = GeneHeader.fromReader(version, reader),
            reader.uInt8(),
            reader.readUInt8Array(GAIT_LENGTH)
        )
    }
}

