internal inline fun <reified T> ByteStreamReader.read(count: Int, get: ByteStreamReader.(i: Int) -> T): Array<T> {
    return (0 until count).map { i ->
        get(i)
    }.toTypedArray()
}

internal inline fun <reified T> ByteStreamWriter.write(
    values: Array<T>,
    write: ByteStreamWriter.(i: T) -> Unit,
): ByteStreamWriter {
    values.forEach { item ->
        write(item)
    }
    return this
}


private val GENE_EXTENSION_HEADER = listOf('g'.code, 'e'.code, 'x'.code, 't'.code)

internal inline fun <ExtensionT : GeneExtension> ByteStreamReader.readExtension(
    read: ByteStreamReader.() -> ExtensionT,
): ExtensionT? {
    return if (isNext(GENE_EXTENSION_HEADER)) {
        // Make sure you skip the "gext" header bytes
        skip(4)
        // Read in the extension data and return the object created
        read()
    } else {
        null
    }
}


internal inline fun <ExtensionT : GeneExtension> ByteStreamWriter.writeExtension(
    data: ExtensionT?,
    write: ByteStreamWriter.(data: ExtensionT) -> Unit,
): ByteStreamWriter {
    if (data == null) {
        return this
    }
    writeUInt8('g'.code)
        .writeUInt8('e'.code)
        .writeUInt8('x'.code)
        .writeUInt8('t'.code)
    write(data)
    return this
}