package com.creaturesforge.application.util

import com.bedalton.common.util.ensureStartsWith
import com.bedalton.common.util.nullIfEmpty
import com.bedalton.creatures.common.structs.BreedKey
import com.bedalton.creatures.common.structs.BreedPartKey
import com.bedalton.log.LOG_DEBUG
import com.bedalton.log.Log
import com.bedalton.log.iIf
import com.creaturesforge.application.state.BreedSlot
import com.creaturesforge.application.state.EggMode
import com.creaturesforge.application.state.FileReslotUtil


internal fun getBreedFilesForSlot(
    eggMode: EggMode,
    files: List<String>?,
    extension: String,
    inputSlot: BreedSlot?,
    outputSlot: BreedSlot?,
): List<Pair<String, String>>? {

    if (files == null) {
        return null
    }

    if (inputSlot == null) {
        Log.e("Cannot get breed files without breed slot")
        return null
    }

    if (outputSlot == null) {
        Log.e("Cannot get breed files without output slot")
        return null
    }

    Log.iIf(LOG_DEBUG) {
        "EggMode: $eggMode; Input: $inputSlot; Output: $outputSlot; FinalOutput: $outputSlot"
    }

    return if (eggMode == EggMode.SINGLE) {
        // Output breed and input breed are the same in single egg mode
        getBreedFilesFromSingleEgg(files, extension, outputSlot)
    } else {
        getBreedFilesFromMultiEgg(files, extension, inputSlot, outputSlot)
    }


}

private fun getBreedFilesFromSingleEgg(
    files: List<String>,
    extension: String,
    breedSlot: BreedSlot,
): List<Pair<String, String>>? {
    val extensionWithDot = extension.ensureStartsWith('.')

    val breedKey = BreedKey(genus = breedSlot.genus, breed = breedSlot.breed.uppercaseChar())

    return files
        .mapNotNull map@{ path ->
            val fileKey = BreedPartKey.fromFileName(path)
                ?: return@map null

            if (BreedKey.isGenericMatch(fileKey.breedKey, breedKey)) {
                path to fileKey.code!! + extensionWithDot
            } else {
                null
            }

        }
        .nullIfEmpty()
}

private fun getBreedFilesFromMultiEgg(
    files: List<String>,
    extension: String,
    inputSlot: BreedSlot,
    outputSlot: BreedSlot,
): List<Pair<String, String>> {
    return FileReslotUtil.reslot(
        files,
        extension,
        inputSlot,
        outputSlot
    )
}