@file:Suppress("unused")

package com.creaturesforge.application.ui.html

import org.w3c.dom.Element
import kotlin.reflect.KProperty


interface IAnAttributeBase<T, V> {
    operator fun getValue(thisRef: T, property: KProperty<*>): V
    operator fun setValue(thisRef: T, property: KProperty<*>, value: V)
}

internal abstract class AnAttributeBase<T, V> (
    private val name: String,
    defaultOnce: V?
): IAnAttributeBase<T,V> {
    private var defaultValueOnce: V? = defaultOnce

    protected abstract fun getActualElement(thisRef: T): Element

    protected abstract fun getValue(element: Element, name: String): V

    protected abstract fun setValue(element: Element, name: String, value: V)

    override operator fun getValue(thisRef: T, property: KProperty<*>): V {
        val element = getActualElement(thisRef)
        setDefaultOnce(element, property)
        return getValue(element, name)
    }

    override operator fun setValue(thisRef: T, property: KProperty<*>, value: V) {
        val element = getActualElement(thisRef)
        setValueOnElement(element, property, value)
    }

    @Suppress("UNUSED_PARAMETER")
    private fun setValueOnElement(thisRef: Element, property: KProperty<*>, value: V) {
        setValue(thisRef, name, value)
    }

    private fun setDefaultOnce(element: Element, property: KProperty<*>) {
        val default = defaultValueOnce
            ?: return
        defaultValueOnce = null
        if (!element.hasAttribute(name)) {
            setValueOnElement(element, property, default)
        }
    }

    fun default(value: V & Any): IAnAttributeBase<T, V & Any> = AnAttributeNotNull(this, value)
}


internal class AnAttributeNotNull<T, V> (
    private val attribute: AnAttributeBase<T, V>,
    private val defaultValue: V & Any
): IAnAttributeBase<T, V & Any> {

    override operator fun getValue(thisRef: T, property: KProperty<*>): V & Any {
        return attribute.getValue(thisRef, property) ?: defaultValue
    }
    override operator fun setValue(thisRef: T, property: KProperty<*>, value: V & Any) {
        return attribute.setValue(thisRef, property, value)
    }
}

internal abstract class AnAttribute<V>(
    name: String,
    defaultOnce: V?
): AnAttributeBase<Element, V>(name, defaultOnce) {

    override fun getActualElement(thisRef: Element): Element {
        return thisRef
    }
}

internal abstract class AnAttributeOf<V> (
    name: String,
    private val element: Element,
    defaultOnce: V?
): AnAttributeBase<Any?, V>(name, defaultOnce) {

    override fun getActualElement(thisRef: Any?): Element {
        return element
    }

}

internal class StringAttribute(
    name: String,
    defaultOnce: String? = null
): AnAttribute<String?>(name, defaultOnce) {

    override fun getValue(element: Element, name: String): String? {
        return element.getAttribute(name)
    }

    override fun setValue(element: Element, name: String, value: String?) {
        element.attribute(name, value)
    }
}

internal class StringAttributeOf(
    name: String,
