@file:Suppress("unused")

package com.bedalton.creatures.agents.util

import com.bedalton.common.exceptions.IOException
import com.bedalton.common.structs.*
import com.bedalton.common.util.*
import com.bedalton.io.bytes.decodeToWindowsCP1252
import com.bedalton.vfs.FileSystem

class RelativeFileSystem(
    private val fileSystem: FileSystem,
    val rootPath: String,
    val subFoldersOnly: Boolean = true
) {

    private val rootPathLower by lazy {
        rootPath.lowercase()
    }

    suspend fun read(relativePath: String): ByteArray {
        val path = path(relativePath)
        return fileSystem.read(path)
    }

    suspend fun readAsText(relativePath: String): String {
        return read(relativePath)
            .decodeToWindowsCP1252()
    }

    suspend fun write(relativePath: String, bytes: ByteArray){
        val path = path(relativePath)
        fileSystem.write(path, bytes)
    }

    suspend fun fileExists(relativePath: String): Boolean {
        val path = path(relativePath)
        return fileSystem.fileExists(path)
    }

    suspend fun makeDirectory(relativePath: String, recursive: Boolean = true): Boolean {
        val path = path(relativePath)
        return fileSystem.makeDirectory(path, recursive)
    }

    suspend fun isFile(relativePath: String): Boolean {
        val path = path(relativePath)
        return !fileSystem.isDirectory(path)
    }

    suspend fun isDirectory(relativePath: String): Boolean {
        val path = path(relativePath)
        return fileSystem.isDirectory(path)
    }


    internal fun path(relativePath: String): String {
        return if (PathUtil.isAbsolute(relativePath)) {
            if (subFoldersOnly && !inRoot(relativePath)) {
                throw IOException("Cannot access PRAY files outside root path: $rootPath")
            }
            if (relativePath.contains("..")) {
                PathUtil.combine(relativePath)
            } else {
                relativePath
            }
        } else {
            PathUtil.combine(rootPath, relativePath)
        }
    }

    internal fun relativeFs(relativePath: String): RelativeFileSystem {
        return RelativeFileSystem(fileSystem, path(relativePath), subFoldersOnly)
    }

    private fun inRoot(path: String): Boolean {
        if (!PathUtil.isAbsolute(path)) {
            return true
        }
        val relativePath = PathUtil.combine(path.lowercase())
        return relativePath.startsWith(rootPathLower)
    }

}