package com.bedalton.log.internal

import com.bedalton.log.ConsoleColors
import com.bedalton.log.ILoggerObject
import com.bedalton.log.LoggerColor

internal fun getLogColorPrefix(color: LoggerColor?): String? {
    if (color == null) {
        return null
    }
    return when (color) {
        LoggerColor.BLACK -> ConsoleColors.BLACK
        LoggerColor.RED -> ConsoleColors.RED
        LoggerColor.GREEN -> ConsoleColors.GREEN
        LoggerColor.YELLOW -> ConsoleColors.YELLOW
        LoggerColor.BLUE -> ConsoleColors.BLUE
        LoggerColor.MAGENTA -> ConsoleColors.PURPLE
        LoggerColor.CYAN -> ConsoleColors.CYAN
        LoggerColor.WHITE -> ConsoleColors.WHITE
    }
}


internal fun ILoggerObject.wrapMessage(color: LoggerColor?, message: String): String {
    val prefix = getColorPrefix(color)
    return if (prefix.isNotNullOrBlank()) {
        message.getNamespacePrefix() + prefix + message.stripNamespacePrefix() + ConsoleColors.RESET
    } else {
        message
    }
}