package com.bedalton.creatures.agents.pray.compiler.pray.validators

import com.bedalton.common.coroutines.checkCancelled
import com.bedalton.creatures.agents.pray.compiler.data.Tag
import kotlinx.coroutines.CoroutineScope

internal suspend fun validateLinkTags(
    coroutineScope: CoroutineScope,
    fileExists: suspend (relativePath: String) -> Boolean,
    addError: AddError, tags: Array<Tag<*>>
) {
    for (tag in tags.filterIsInstance<Tag.LinkTag>()) {
        coroutineScope.checkCancelled()
        if (fileExists(tag.value)) {
            return
        }
        addError(
            tag.valueRange,
            "Linked CAOS file '${tag.value}' could not be found",
        )
    }
}
