package com.bedalton.creatures.breed.render.internal



fun <V1, V2> Pair<V1,V2>.withFirst(value: V1): Pair<V1,V2> {
    return copy(
        first = value
    )
}

fun <V1, V2> Pair<V1,V2?>?.withFirstAndNull(value: V1): Pair<V1,V2?> {
    return this?.copy(
        first = value
    ) ?: Pair(value, null)
}


fun <V1, V2> Pair<V1?,V2?>?.withNullableFirstAndNull(value: V1?): Pair<V1?,V2?> {
    return this?.copy(
        first = value
    ) ?: Pair(value, null)
}

fun <V1, V2> Pair<V1,V2>.withSecond(value: V2): Pair<V1,V2> {
    return copy(
        second = value
    )
}

fun <V1, V2> Pair<V1?,V2>?.withSecondAndNull(value: V2): Pair<V1?,V2> {
    return this?.copy(
        second = value
    ) ?: Pair(null, value)
}


fun <V1, V2> Pair<V1?,V2?>?.withNullableSecondAndNull(value: V2?): Pair<V1?,V2?> {
    return this?.copy(
        second = value
    ) ?: Pair(null, value)
}