/**
 * Combines all RSCR code blocks in all script tags
 */
internal fun combineRemoverScripts(scripts: Array<String>): Tuple<Array<String>, String> {
    val bodyScripts = mutableListOf<String>()
    var index = 0
    val count = scripts.size

    var i = 1

    val gsubs = mutableListOf<String>()
    val subr = mutableListOf<String>()
    val rawRemover = mutableListOf<String>()

    // Extract body scripts while adding removal scripts
    for (script in scripts) {
        Log.iWith(LOG_PROGRESS, replace = true) { "Extracting remover scripts from ${++index} of $count" }
        val bodyScript = walkScript(script, i++, gsubs, subr, rawRemover)
        bodyScripts.add(bodyScript.trim())
    }
    if (rawRemover.size == 0) {
        return Tuple(bodyScripts.toTypedArray(), "")
    }
    if (rawRemover.size == 1) {
        return Tuple(bodyScripts.toTypedArray(), rawRemover[0].replace(NEWLINE_REGEX, "\n"))
    }

    Log.iWith(LOG_PROGRESS, replace = true) { "Combined $index remover scripts\r\n" }

    // Combine removal scripts
    val removalScriptBuilder = StringBuilder()

    for (gsub in gsubs) {
        removalScriptBuilder.append(gsub).append("\n")
    }

    for (subroutine in subr) {
        removalScriptBuilder.append(subroutine).append("\n")
    }

    val removalScript = removalScriptBuilder
        .append("\n")
        .toString()
        .trim()
        .replace(NEWLINE_REGEX, "\n")

    return Tuple(bodyScripts.toTypedArray(), removalScript)
}


/**
 * Walks script to find all RSCR blocks
 * @first:Body Script without RSCR
 * @second: Combined RSCR blocks
 */
private fun walkScript(
    script: String,
    scriptIndex: Int,
    gsubs: MutableList<String>,
    subr: MutableList<String>,
    raws: MutableList<String>
): String {

    val charStream = CharStreams.fromString(script)
    val lexer = CaosRscrLexer(charStream)
    val tokenStream = CommonTokenStream(lexer)
    val parser = CaosRscrParser(tokenStream)
    val walker = RscrWalker("remover_${scriptIndex}_subr_")
    parser.addErrorListener(walker)
    ParseTreeWalker.DEFAULT.walk(walker, parser.file())


    val removerScripts = walker.removerScripts

    raws.addAll(walker.removerScripts)

    for (i in removerScripts.indices) {
        val key = "remover_${scriptIndex}_$i"
        subr.add("\nsubr $key\n" + removerScripts[i].trim() + "\nretn\n")
        gsubs.add("gsub $key")
    }

    subr.add(walker.rscrSubr.toString().trim())

    if (walker.hasStops) {
        Log.w { "Combined RSCR has stop statements, and may not complete as expected" }
    }
    return walker.codeBlocks.filter { it.first != 1 }.joinToString("") { it.second }
}

/**
 * Walker implementation to strip and combine RSCR scripts
 */
private class RscrWalker(private val subroutinePrefix: String) : CaosRscrParserBaseListener(), ANTLRErrorListener {

    val codeBlocks: MutableList<Tuple<Int, String>> = mutableListOf()
    val removerScripts: MutableList<String> = mutableListOf()
//    val loops = mutableListOf<Boolean>()
    var hasStops = false
    var rscrSubr = StringBuilder()
    var inRscr = false
    var rawRscr = StringBuilder()

    override fun enterBody(ctx: CaosRscrParser.BodyContext) {
        super.enterBody(ctx)
        codeBlocks.add(Tuple(0, ctx.originalText ?: ctx.text))
    }

    override fun enterRscr(ctx: CaosRscrParser.RscrContext) {
        inRscr = true
        super.enterRscr(ctx)
        var nextToken = false
        val script = StringBuilder()
        var subject = script
        val body = ctx.findRscrBody()
            ?: return
        var lastWasNewLine = true
        rawRscr.append(body.originalText ?: body.text)
        val children = body.children.orEmpty()
        val depth = mutableListOf<List<String>>()
        val loops = mapOf(
            "enum" to listOf("next"),
            "etch" to listOf("next"),
            "esee" to listOf("next"),
            "epas" to listOf("next"),
            "econ" to listOf("next"),
            "loop" to listOf("ever", "untl"),
            "reps" to listOf("repe")
        )
        val loopEnds = loops.values.flatten()
        val scopes = mapOf(
            "doif" to listOf("endi"),
        ) + loops
        val theLoops = mutableListOf<List<String>>()
        val scopeStart = scopes.keys
        val scopeEnd = scopes.values.flatten()
        for (tokenIndex in children.indices) {
            val token = children[tokenIndex]
            var text = if (nextToken) {
                subroutinePrefix + token.text
            } else {
                if (token is ParserRuleContext) {
                    token.originalText ?: token.text
                } else {
                    token.text
                }
            }

            val textLower = text.lowercase()
            if (nextToken) {
                nextToken = false
            } else {
                if (textLower in scopeStart) {
                    depth.add(scopes[text]!!)
                }
                loops[textLower]?.let {
                    theLoops.add(it)
                }
                if (textLower in loopEnds) {
                    if (textLower !in theLoops.lastOrNull().orEmpty()) {
                        if (theLoops.isNotEmpty()) {
                            throw Exception(
                                "Cannot combine RSCR scripts. Unclosed loop: $text; Expected: [${
                                    theLoops.last().joinToString(",")
                                }]"
                            )
                        } else {
                            throw Exception("Cannot combine RSCR scripts. Unexpected loop close: $text")
                        }
                    }
                    theLoops.removeLast()
                }
                if (textLower in scopeEnd) {
                    if (textLower !in depth.lastOrNull().orEmpty()) {
                        if (depth.isNotEmpty()) {
                            throw Exception(
                                "Cannot combine RSCR scripts. Unclosed control statement: $text; Expected: [${
                                    depth.last().joinToString(",")
                                }]"
                            )
                        } else {
                            throw Exception("Cannot combine RSCR scripts. Unexpected control statement close: $text")
                        }
                    }
                    depth.removeLast()
                }
                when (textLower) {
                    "subr" -> {
                        nextToken = true
                        subject = rscrSubr.append("\n")
                    }

                    "gsub" -> {
                        nextToken = true
                    }

                    "stop" -> {
                        if (loops.isEmpty()) {
                            hasStops = true
                            text = "retn"
                        }
                    }

                    "retn" -> {
                        if (depth.isEmpty()) {
                            if (!lastWasNewLine) {
                                subject.append('\n')
                            }
                            lastWasNewLine = false
                            subject.append(text).append('\n')
                            subject = script
                            continue
                        }
                    }
                }
            }
            val isNewline = text.endsWith('\n')
            if (!lastWasNewLine && !isNewline) {
                subject.append(' ')
            }
            lastWasNewLine = isNewline
            subject.append(text)
        }
        removerScripts.add(script.toString())
    }

//    override fun exitRscr(ctx: CaosRscrParser.RscrContext) {
//        loops.clear()
//        super.exitRscr(ctx)
//    }

