package com.bedalton.creatures.agents.pray.compiler.pray.validators

import com.bedalton.creatures.agents.pray.compiler.DEPENDENCY_DECLARATION_TAGS_REGEX
import com.bedalton.creatures.agents.pray.compiler.pray.PrayValidationError
import com.bedalton.creatures.agents.pray.compiler.data.Tag
import com.bedalton.creatures.agents.pray.compiler.data.TextValue

/**
 * Finds duplicates and creates error objects for them
 */
internal fun validateTagDuplicates(
    fullFilePath: String,
    validationErrors: MutableList<PrayValidationError>,
    blockTag: TextValue,
    blockName: TextValue,
    tags: Array<Tag<*>>,
    ignoreCase: Boolean = true
) {
    // Get all tag names
    val tagNames = (if (ignoreCase) tags.map { it.tag.lowercase() } else tags.map { it.tag })
        .filterNot {
            // Filter out Dependency tags as these are handled in their own validator
            DEPENDENCY_DECLARATION_TAGS_REGEX.matches(it)
        }

    // Find the unique names in tag names
    val uniqueTags = tagNames.toSet()
    // Count instances of tag and keep duplicates
    val duplicatedTagNames = uniqueTags.filter { tagName -> tagNames.count { it == tagName } > 1 }

    // If ignoreCase is set to true, compare case-insensitive
    val duplicateTags = if (ignoreCase)
        tags.filter { it.tag.lowercase() in duplicatedTagNames }
    else
        tags.filter { it.tag in duplicatedTagNames }

    // Create errors for duplicate tags
    val duplicateTagErrors: List<PrayValidationError> =
        duplicateTags.map { duplicateTag ->
            PrayValidationError.DuplicateTagError(
                blockTag = blockTag,
                blockName = blockName,
                duplicateTag = duplicateTag,
                message = formatDuplicateTagsError(
                    blockTag = blockTag.text,
                    blockName = blockName.text,
                    duplicateTag = duplicateTag,
                ),
                fullFilePath = fullFilePath
            )
        }

    // Add all errors
    validationErrors.addAll(duplicateTagErrors)
}


private fun formatDuplicateTagsError(blockTag: String, blockName: String, duplicateTag: Tag<*>): String {
    return "Duplicate tag '${duplicateTag.tag}' found in $blockTag BLOCK \"$blockName\"" //${if (duplicateTag.value is Int) "" else "\"${duplicateTag.value}\""}
}