package com.creaturesforge.application.state

import com.bedalton.common.util.ensureStartsWith
import com.bedalton.creatures.common.structs.BreedPartKey

internal object FileReslotUtil {

    fun reslot(
        files: List<String>,
        extension: String,
        filterSlot: BreedSlot,
        outputSlot: BreedSlot,
    ): List<Pair<String, String>> {
        return files
            .mapNotNull map@{ filePath ->
                reslot(filePath, extension, filterSlot, outputSlot)
            }
    }

    private fun reslot(
        filePath: String,
        extension: String,
        filterSlot: BreedSlot,
        outputSlot: BreedSlot,
    ): Pair<String, String>? {
        val partKey = BreedPartKey.fromFileName(filePath)
            ?: return null

        val fileBreedKey = partKey.breedKey

        if (fileBreedKey.genus != filterSlot.genus && fileBreedKey.genus != (filterSlot.genus + 4)) {
            return null
        }
        if (fileBreedKey.breed != filterSlot.breed) {
            return null
        }

        val translated = partKey.copy(
            breedKey = partKey.breedKey.copy(
                genus = outputSlot.genus,
                breed = outputSlot.breed
            )
        )

        val extensionWithDot = extension.ensureStartsWith('.')

        return filePath to (translated.code!! + extensionWithDot)
    }
}