@file:Suppress("NON_EXPORTABLE_TYPE", "unused")

package com.bedalton.creatures.caos.collectors

import com.bedalton.common.ast.structs.HasRange
import com.bedalton.common.ast.structs.RangeWithIndex
import com.bedalton.common.ast.structs.parserIndex
import com.bedalton.common.ast.structs.stitch
import com.bedalton.creatures.caos.libs.CommandType
import com.bedalton.creatures.caos.libs.VariantCaosCommand
import com.bedalton.creatures.caos.libs.VariantCaosParameter
import kotlinx.serialization.SerialName
import kotlinx.serialization.Serializable
import kotlin.js.JsExport
import kotlin.js.JsName

@JsExport
@Serializable
@JsName("CommandCall")
data class CommandCall(
    @SerialName("typeId")
    override val type: Int,

    @JsName("command")
    val command: VariantCaosCommand,

    @JsName("arguments")
    var arguments: Array<Argument> = emptyArray(),

    @JsName("tokenTextRange")
    val tokenTextRange: RangeWithIndex,

    @JsName("inVariant")
    val inVariant: Boolean,

    override var textRange: RangeWithIndex,

    override val parameter: VariantCaosParameter?,

    override var inEqualityExpression: Boolean,

    override val containingCommand: CommandReference?,

    @JsName("tokens")
    val tokens: Array<CaosParserItem.CommandToken>,

    @JsName("callType")
    val callType: CommandType

) : HasRange, Argument, CaosItem {

    val isRvalue get() = callType == CommandType.RVALUE
    val isLvalue get() = callType == CommandType.LVALUE
    val isCommand get() = callType == CommandType.COMMAND

    val callTypeId  = callType.value

    private val parameterCount = command.parameters.size

    val done: Boolean get() = arguments.size >= parameterCount

    override val parserItem by lazy {
        CaosParserItem.CompoundCommandToken(tokens)
    }

    override var text = (listOf(this.parserItem) + arguments).stitch()

    val commandString = command.command

    var missingParameters: Array<VariantCaosParameter>  = if (arguments.size >= parameterCount) {
            emptyArray()
        } else {
            command.parameters.sliceArray(arguments.size until parameterCount)
        }

    override val parserIndexStart: Int? = tokens
            .firstOrNull()
            ?.parserIndex
            ?: textRange.parserIndex

    override var parserIndexEnd: Int? = arguments
            .lastOrNull()
            ?.let {
                when (it) {
                    is CommandCall -> it.parserIndexEnd
                    is ParserItemArgument -> it.parserIndexEnd
                    else -> it.textRange.parserIndex
                }
            }
            ?: tokens.lastOrNull()
                ?.parserIndex
            ?: textRange.parserIndex


    internal fun finalizeProperties() {
        updateText()
        updateMissing()
    }

    internal fun updateText() {
        arguments.filterIsInstance<CommandCall>().forEach(CommandCall::updateText)
        text = (listOf(this.parserItem) + arguments).stitch()
    }


    private fun updateMissing() {
        missingParameters = if (arguments.size >= parameterCount) {
            emptyArray()
        } else {
            command.parameters.sliceArray(arguments.size until parameterCount)
        }
    }

    private fun updateParserEnd() {
        parserIndexEnd = arguments
            .lastOrNull()
            ?.let {
                when (it) {
                    is CommandCall -> it.parserIndexEnd
                    is ParserItemArgument -> it.parserIndexEnd
                    else -> it.textRange.parserIndex
                }
            }
            ?: tokens.lastOrNull()
                ?.parserIndex
            ?: textRange.parserIndex
    }

    @Suppress("RedundantIf")
    override fun equals(other: Any?): Boolean {
        if (this === other) return true
        if (other !is CommandCall) return false

        if (type != other.type) return false
        if (command != other.command) return false
        if (!arguments.contentEquals(other.arguments)) return false
        if (tokenTextRange != other.tokenTextRange) return false
        if (inVariant != other.inVariant) return false
        if (textRange != other.textRange) return false
        if (parameterCount != other.parameterCount) return false

        return true
    }

    override fun hashCode(): Int {
        var result = type.hashCode()
        result = 31 * result + command.hashCode()
        result = 31 * result + arguments.contentHashCode()
        result = 31 * result + tokenTextRange.hashCode()
        result = 31 * result + inVariant.hashCode()
        result = 31 * result + textRange.hashCode()
        result = 31 * result + parameterCount
        return result
    }
}