object PathUtil {
    fun combine(vararg components: String): String = combine(false, *components)
    fun combine(subFoldersOnly: Boolean, vararg components: String): String {

        val pathSeparatorChar = components.mapNotNull { getPathSeparatorChar(it, true) }
            .distinct()
            .singleOrNull()
            ?: if (components.any { Platform.isWindows() || it.contains('\\')} ) {
                '\\'
            } else {
                '/'
            }

        if (subFoldersOnly) {
            val componentCounts = components.sumOf {
                val quickSplit = it.split(pathSeparatorChar)
                quickSplit.count{ it != ".." } - quickSplit.count { it == ".." }
            }
            if (componentCounts < 0) {
                throw Exception("Cannot build path with parent '..$pathSeparatorChar' components")
            }
        }

        val componentsExpanded = if (components.firstOrNull() == "~") {
            val expandedComponents = expandTilde("~/")
                .split(pathSeparatorChar)
                .toTypedArray()
            val tail: Array<String> = if (components.size == 1) {
                arrayOf()
            } else {
                components.drop(1).toTypedArray()
            }
            arrayOf(*expandedComponents, *tail)
        } else {
            components
        }

        val out = when (componentsExpanded.size) {
            0 -> ""
            1 -> removeNesting(components[0].normalizeSlashes())
            else -> {
                val out = StringBuilder(
                    // Add initial component
                    components[0].let { first ->
                        if (first.endsWith(pathSeparatorChar)) {
                            first.substring(0, first.lastIndex)
                        } else {
                            first
                        }
                    }
                )

                for (component in components.drop(1)) {
                    if (!component.startsWith(pathSeparatorChar)) {
                        out.append(pathSeparatorChar)
                    }
                    if (component.endsWith(pathSeparatorChar)) {
                        out.append(component.substring(0, component.lastIndex))
                    } else {
                        out.append(component)
                    }
                }
                if (components.last().endsWith(pathSeparatorChar)) {
                    out.append(pathSeparatorChar)
                }
                return removeNesting(out.toString()).normalizeSlashes()
            }
        }
        return out
    }

    /**
     * Normalizes path, dividing along perceived accidentally concatenated paths
     * @return normalized path or null if path seems concatenated and divide is false
     */
    fun normalizePath(pathIn: String, divide: Boolean = false): String? {
        val path = if (isWindows(pathIn)) {
            pathIn.replace('/', '\\')
        } else {
            superUnescape(pathIn)
        }
        if (path.isBlank()) {
            return ""
        }
        val quoteEscape = getEscape(path, "quote")
        var out = try {
            path.replace("([\\^`\\\\])\"".toRegex(), "\$1$quoteEscape")
        } catch (e: Exception) {
            Log.eIf(LOG_DEBUG) { "Failed to escape escaped quote" }
            path
        }

        // Split on internal quote as it should be delimiting paths
        if (out.startsWith("\"") && out.endsWith('"') && out.contains('"')) {
            if (!divide) {
                return null
            }
            val temp = out
                .substring(1)
                .split('"')
                .firstOrNull {
                    it.isNotBlank()
                }
            if (temp != null) {
                out = "\"$temp\""
            }
        }

        // Remove surrounding quotes if any
        val temp = out.stripSurroundingQuotes(2, false)

        // If quoted, allow internal spaces
        val canHaveSpaces = temp != out

        // Use unquoted as output
        out = temp

        // Escape spaces
        out = out.superUnescape(' ')

        // If path could not have spaces, split on a space
        if (!canHaveSpaces) {
            out = out.split(' ')
                .firstOrNull {
                    it.isNotBlank()
                }
                ?.apply {
                    // Path seems to contain another path, but path is not to be divided
                    // so return null
                    if (!divide && out != this) {
                        return null
                    }
                }
                ?: out
        }
        // Remove internally quoted strings
        out = out.replace("\"", "")
        return out
            .replace(quoteEscape, "\"")
            .let {
                combine(out)
            }
    }


    /**
     * Find the relative path between a file and another directory
     * Returns null if the two paths are assumed not to share a common root
     */
    fun relativePath(sourcePath: String, targetPath: String, separatorChar: Char? = null): String? {

        val slashChar = '/'
        val slash = "" + slashChar

        // Get original path separator chars
        val targetPathSeparatorChar = getPathSeparatorChar(targetPath)
        val sourcePathSeparatorChar = getPathSeparatorChar(sourcePath)

        // Get the requested char to use as output
        val outputPathSeparator =
            separatorChar ?: if (targetPathSeparatorChar != sourcePathSeparatorChar) '/' else targetPathSeparatorChar

        // Prepare to replace the possibly different file system separators with the same separator
        val pathSeparatorRegex = "[/\\\\]+".toRegex()

        // Split source path
        var sourcePathComponents = combine(sourcePath).replace(pathSeparatorRegex, slash).split(slashChar)

        // Format and split target path
        val targetPathNormalized = combine(targetPath).replace(pathSeparatorRegex, slash)
        var targetPathComponents = combine(targetPathNormalized).split(slashChar)

        // Pop filename from target array
        val fileName = targetPathComponents.last()
        targetPathComponents = if (targetPathComponents.size > 1) targetPathComponents.dropLast(1) else emptyList()

        if (targetPathComponents.isEmpty() && sourcePathComponents.isEmpty()) {
            return ""
        } else if (targetPathComponents.isEmpty() || sourcePathComponents.isEmpty()) {
            return null
        }

        // Paths can never equal as they share no common start
        if (targetPathComponents[0] != sourcePathComponents[0] && targetPath[0] != '/' && sourcePath[0] != '/') {
            return null
        }

        // Out variables
        var relativePath = ""

        // Pop source components off until it matches the target path
        while (
            sourcePathComponents.isNotEmpty() &&
            targetPathNormalized.lowercase().ensureStartsWith(slash)
                .indexOf(sourcePathComponents
                    .joinToString(slash)
                    .lowercase()
                    .ensureStartsWith(slash)) != 0
        ) {
            sourcePathComponents = sourcePathComponents.dropLast(1)
            relativePath += "..$outputPathSeparator"
        }

        // Find all path components after the shared root
        val relativePathComponents = if (targetPathComponents.isNotEmpty()) {
            val mod = if (relativePath.isNotEmpty()) {
                0
            } else {
                -1
            }
            targetPathComponents.slice(
                (sourcePathComponents.size + mod) until targetPathComponents.size
            )
        } else {
            targetPathComponents
        }

        // Joint the relative path together if needed
        if (relativePathComponents.isNotEmpty()) {
            relativePath += relativePathComponents.joinToString("" + outputPathSeparator) + outputPathSeparator
        }

        // Return the relative path with filename
        return relativePath + fileName
    }

    // Get an escape sequence to prevent un-escaping a specific char or string
    private fun getEscape(string: String, escapeBase: String, escapeChar: Char = ';'): String {
        var escape = "" + escapeChar + escapeChar + escapeChar + escapeBase + escapeChar + escapeChar + escapeChar
        while (string.contains(escape)) {
            escape = escapeChar + escapeBase + escapeChar
        }
        return escape
    }

