    val WINDOWS_ABSOLUTE_PATH_PREFIX = "^[a-zA-Z]:[\\\\/]{1,2}.*".toRegex()
    val ABSOLUTE_VIRTUAL_PATH_PREFIX = "^[a-zA-Z]+:[\\\\/]{1,2}.*".toRegex()

    fun isAbsolute(path: String): Boolean {
        return isAbsolute(path, virtualSchemas = true)
    }

    fun isAbsolute(path: String, virtualSchemas: Boolean): Boolean {
        return path.startsWith('/') ||
                path.startsWith("~/") ||
                WINDOWS_ABSOLUTE_PATH_PREFIX.matches(path) ||
                (virtualSchemas && ABSOLUTE_VIRTUAL_PATH_PREFIX.matches(path))
    }

    fun requiresTildeExpansion(path: String): Boolean {
        return path.startsWith("~/")
    }

    fun ensureAbsolutePath(path: String, newRootPath: String): String? {
        if (requiresTildeExpansion(path)) {
            return expandTilde(path)
        }
        if (isAbsolute(path)) {
            return path
        }
        val newPath = combine(newRootPath, path)
        if (!isAbsolute(newPath)) {
            return null
        }
        return newPath
    }


    /**
     * Gets filename without extension
     */
    fun getFileName(path: String): String? {
        return getFileNameWithoutExtension(path)
    }


    /**
     * Get filename without folder path
     * Same as last path component
     */
    fun getBasename(path: String, nullIfBlank: Boolean? = null): String? {
        return getLastPathComponent(path, nullIfBlank = nullIfBlank)
    }

    /**
     * Get the directory of the given path
     * @since 1.1.0
     */
    fun getDirname(path: String): String? {
        return getWithoutLastPathComponent(path)
    }

    fun getFileNameWithoutExtension(fileName: String): String? {
        if (fileName.endsWith('/') || fileName.endsWith('\\')) {
            return null;
        }
        val separator = getPathSeparatorChar(fileName)
        var startIndex = fileName.lastIndexOf(separator)
        if (startIndex < 0) {
            startIndex = 0
        } else {
            startIndex += 1
        }

        val lastIndex = fileName.lastIndexOf('.')
        val string: String? = when {
            lastIndex < startIndex -> {
                if (startIndex == 0) {
                    fileName
                } else {
                    fileName.substring(startIndex)
                }
            }

            lastIndex > startIndex -> fileName.substring(startIndex, lastIndex)
            else -> null
        }
        return string?.nullIfEmpty()
    }

    fun getExtension(fileName: String): String? {
        val lastIndex = fileName.lastIndexOf('.')
        val extension = when {
            lastIndex < 0 -> null
            lastIndex < fileName.lastIndex -> fileName.substring(lastIndex + 1).let {
                if (it.contains('/') || it.contains('\\')) {
                    null
                } else {
                    it
                }
            }

            else -> null
        }
        return extension.nullIfEmpty()

    }

    /**
     * Gets the closest directory to this path, returning file as is, if it is determined to be a directory
     * Not the most reliable implementation of such a method
     */
    fun getSelfOrParentDirectory(file: String, appendSeparator: Boolean? = null): String? {

        val separator = getPathSeparatorChar(file)

        // Internal function to append path separator if desired and separator is missing
        fun String.close(): String {
            return if (appendSeparator != true || this.endsWith(separator)) {
                this
            } else {
                this.ensureEndsWith(separator)
            }
        }
        // If path ends with slash assume it is a directory
        if (file.endsWith(separator)) {
            return file
        }

        // If path has no slash, assume directory if no extension
        val index = file.lastIndexOf(separator)
        if (index < 0) {
            return if (file.contains('.')) {
                null
            } else {
                file.close()
            }
        }

        // Remove last component if it contains a dot
        return if (file.substring(index).contains('.')) {
            file.substring(0 until index).close()
        } else {
            file.close()
        }
    }


    /**
     * Gets the last path components, which may or may not be a file name
     */
    fun getLastPathComponent(path: String, nullIfBlank: Boolean? = null): String? {
        fun String.close(): String? {
            return if (nullIfBlank == true && this.isBlank()) {
                null
            } else {
                this
            }
        }

        val separator = getPathSeparatorChar(path)

        return when {
            path.isBlank() -> null
            path == separator.toString() -> "".close()
            else -> {
                val index = path.lastIndexOf(separator)
                when {
                    index < 0 -> path.close()
                    index == path.lastIndex -> "".close()
                    else -> path.substring(index + 1).close()
                }
            }
        }
    }

    /**
     * Gets path without last path component.
     * Path must already be unescaped
     */
    @JvmStatic
    fun getWithoutLastPathComponent(path: String): String? {
//        // *NOTE*: PATH SHOULD ALREADY BE UNESCAPED
        val separator = getPathSeparatorChar(path)

        val refined = path.trimEnd(separator)
        if (separator == '\\' && refined.matches("[a-zA-Z]+:".toRegex())) {
            return refined + '\\'
        }
        val lastIndex = refined.lastIndexOf(separator)
        if (lastIndex < 0) {
            return null
        }
        return refined.substring(0, lastIndex + 1)
    }


    @JvmStatic
    fun getPathSeparatingLastPathComponent(aPath: String): Pair<String?, String?>? {
        var path = aPath
        // Unescape whitespace
        if (path.contains('/') && path.contains('\\')) {
            if (path.contains("\\ ")) {
                path = path.replace("\\ ", " ")
            }
            if (path.contains("\\\t")) {
                path = path.replace("\\\t", "\t")
            }
            // Do not unescape newline, as a path should not have newline in it
        }

        val separator = getPathSeparatorChar(path)
        val components = path.split(separator)
        if (components.isEmpty())
            return null
        return if (components.size == 1) {
            val component = components.first()
            if (separator == '\\' && component.matches("[a-zA-Z]:".toRegex())) {
                Pair(component + '\\', null)
            } else {
                Pair(null, components.first())
            }
        } else {
            Pair(components.dropLast(1).joinToString(separator.toString()), components.last())
        }
    }

    fun getPathSeparatorChar(path: String?): Char {
        return getPathSeparatorChar(path, false)!!
    }
    fun getPathSeparatorChar(path: String?, nullIfUnknown: Boolean): Char? {
        if (path.isNullOrBlank()) {
            return if (nullIfUnknown) {
                null
            } else {
                return pathSeparatorChar
            }
        }
        if (isWindows(path)) {
            return '\\'
        }
        if (path.contains('/') && path.contains('\\')) {
            return if (path.contains("\\ ") || path.contains("\\(") || path.contains("\\)")) {
                '/'
            } else {
                '\\'
            }
        }
        if (path.contains('\\')) {
            if (!path.contains("\\ ") && !path.contains("\\(") && !path.contains("\\)")) {
                return '\\'
            }
        }
        return if (!Platform.isWindows() && !Platform.isJs()) {
            pathSeparatorChar
        } else {
            if (path.contains(pathSeparatorChar)) {
                return pathSeparatorChar
            }
            if (path.contains('\\')) {
                return '\\'
            } else if (path.contains('/')) {
                return '/'
            } else if (!nullIfUnknown) {
                pathSeparatorChar
            } else {
                null
            }
        }

    }

    fun shortestPaths(paths: Collection<String>): Map<String, String> {
        return mShortestPaths(paths)
    }

    fun shortestPaths(paths: Array<String>): Map<String, String> {
        return mShortestPaths(paths.toList())
    }

    fun shortestPaths(paths: Collection<String>, minDepth: Int?): Map<String, String> {
        return mShortestPaths(paths,  DEFAULT_SEPARATOR_CHAR, minDepth ?: 0)
    }


