        return mShortestPaths(paths.toList(),  DEFAULT_SEPARATOR_CHAR, minDepth ?: 0)
    }

    fun shortestPaths(paths: Collection<String>, separator: Char?): Map<String, String> {
        return mShortestPaths(paths, separator ?: DEFAULT_SEPARATOR_CHAR, 0)
