    fun shortestPaths(paths: Collection<String>, separator: Char? = null, minDepth: Int? = null): Map<String, String> {
        return mShortestPaths(paths, separator ?: DEFAULT_SEPARATOR_CHAR, minDepth ?: 0)
    }

    fun shortestPaths(paths: Array<String>, separator: Char? = null, minDepth: Int? = null): Map<String, String> {
