    }


    fun shortestPathsPreservingOrder(paths: Collection<String>): List<String> {
        val shortestPaths = mShortestPaths(paths)
        return paths.map {path -> shortestPaths[path] ?: path }
    }

    fun shortestPathsPreservingOrder(paths: Array<String>): List<String> {
        return shortestPathsPreservingOrder(paths.toList())
    }

    fun shortestPathsPreservingOrder(paths: Collection<String>, separator: Char? = null, minDepth: Int? = null): List<String> {
        val shortestPaths = mShortestPaths(paths, separator ?: DEFAULT_SEPARATOR_CHAR, minDepth ?: 0)
        return paths.map {path -> shortestPaths[path] ?: path }
    }

    fun shortestPathsPreservingOrder(paths: Array<String>, separator: Char? = null, minDepth: Int? = null): List<String> {
        val shortestPaths = mShortestPaths(paths.toList(), separator ?: DEFAULT_SEPARATOR_CHAR, minDepth ?: 0)
        return paths.map {path -> shortestPaths[path] ?: path }
    }

    fun sharedPath(paths: Collection<String>): String? {
        return mCommonParent(paths)
    }

    fun sharedPath(paths: Array<String>): String? {
        return mCommonParent(paths.toList())
    }
}

private const val DEFAULT_SEPARATOR_CHAR = '/'

expect val applicationSupportPath: String?

expect fun expandTilde(path: String): String


private fun removeNesting(path: String): String {
    val expandedPath = if (path.startsWith('~')) {
        expandTilde(path)
    } else {
        path
    }
    val pathSeparator = getPathSeparatorChar(expandedPath)
    val prefix = if (path.startsWith(pathSeparator)) {
        pathSeparator.toString()
    } else if (path.startsWith('\\')) {
        "\\"
    } else if (path.startsWith('/')) {
        "/"
    } else {
        ""
    }

    val components = expandedPath.split(pathSeparator)
    val out = mutableListOf<String>()
    for (component in components) {
        if (component == ".") {
            continue
        }
        if (component == "..") {
            if (out.isNotEmpty()) {
                out.removeLast()
            } else {
                out.add(component)
            }
        } else {
            out.add(component)
        }
    }
    return out.joinToString(pathSeparator).ensureStartsWith(prefix)
}


private fun String.normalizeSlashes(): String {
    val pathSeparatorChar = getPathSeparatorChar(this)
    return this.replace('\\', pathSeparatorChar).replace('/', pathSeparatorChar)
}


fun String.normalized() = this.lowercase()
    .let {
        if (isWindows(this)) {
            it.replace('/', '\\')
        } else if (it.contains('/')) {
            it.unescape()
        } else {
            it
        }
    }
    .replace('\\', '/')

private fun mShortestPaths(allPaths: Iterable<String>, separator: Char = DEFAULT_SEPARATOR_CHAR, minDepth: Int = 0): Map<String, String> {
    val allPathsComponents = allPaths.map { path ->
        Pair(path, path.replace('\\', '/').split('/').reversed().filterNot { it.isBlank() })
    }.filterNot { it.second.isEmpty() }

    val sharedEnds = allPathsComponents.map { it.second.first().lowercase() }.distinct().map { tail ->
        allPathsComponents.filter { it.second.first().lowercase() == tail }
    }

    val out = mutableMapOf<String, String>()
    for (shared in sharedEnds) {
        for ((original, components) in shared) {
            var matches = shared.filterNot { it.first.lowercase() == original.replace('\\', '/').lowercase() }
            var temp = components[0]
            var hasNext = true
            loop@ for (i in components.indices.drop(1)) {
                if (!hasNext) {
                    continue@loop
                }
                val component = components[i].lowercase()
                if (matches.isEmpty()) {
                    hasNext = false
                    continue@loop
                }
                matches = matches.filter { it.second.size > i && it.second[i].lowercase() == component }
                temp = "${components[i]}${separator}$temp"
            }
            out[original] = if (original.endsWith('/') || original.endsWith('\\') || original.endsWith(separator)) {
                temp + separator
            } else {
                temp.trim('/', '\\', separator)
            }
        }
    }

    return ensureMinimumDepth(out, separator, minDepth)
}

private fun ensureMinimumDepth(shortestPaths: Map<String, String>, separator: Char, minDepth: Int): Map<String, String> {
    val out = HashMap(shortestPaths)
    for ((path, shortest) in shortestPaths) {
        if (path.isEmpty()) {
            continue
        }
        val pathNormalized = path.trim().replace("[\\\\/]".toRegex(), separator.toString()).trimEnd(separator).trim()
        val shortestDepth = shortest.trim().replace("[\\\\/]".toRegex(), separator.toString()).trimEnd(separator).count { it == separator}
        if (minDepth > shortestDepth) {
            val allComponents = pathNormalized.trimEnd(separator).split(separator)
            val toDrop = (allComponents.filter { it.isNotEmpty() }.size - minDepth - 1)

            if (toDrop <= 0) {
                out[path] = path
                continue
            }

            val prefixComponents = allComponents
                .drop(toDrop)

            val prefix = prefixComponents.joinToString(separator)
            out[path] = prefix
        }
    }
    return out
}

private fun mCommonParent(allPaths: Iterable<String>): String? {
    val normalized = allPaths.map { it.replace('\\', '/') }
    val prefix = if (normalized.all { it.firstOrNull() == '/' }) "/" else ""
    val allPathsComponents = normalized.map { path ->
        path.split('/').filter { it.isNotBlank() }
    }.toMutableList().nullIfEmpty()
        ?: return null
    val maxSharedLength = allPathsComponents.minOf { it.size }
    val out = mutableListOf<String>()
    val base = allPathsComponents.removeAt(0)
    for (i in 0 until maxSharedLength) {
        val component = base[i]
        if (!allPathsComponents.all { it[i] == component }) {
            break
        }
        out.add(component)
    }
    if (out.isEmpty()) {
        return null
    }
    return prefix + out.joinToString('/')

}

fun isWindows(path: String): Boolean {
    return path.contains("^[a-zA-Z]:\\\\".toRegex())
}