/**
 * Return a new list, with the first item matching the predicate replaced by the newItem parameter
 * If no value in the list matches the predicate, the newItem will be appended to the end of the list
 * @param newItem the value to replace or add to the list
 * @param check The predicate to determine which item to replace. Item matching true will be replaced
 */
@Deprecated(
    "Use replaceFirstInstance instead",
    replaceWith = ReplaceWith(
        "replaceFirst(newItem, check)",
        imports = ["com.bedalton.common.util.replaceFirstInstance"]
    )
)
inline fun <T> Iterable<T>.replaceFirst(newItem: T, check: (item: T) -> Boolean): List<T> {
    return replaceFirstInstance(newItem, check)
}


/**
 * Return a new list, with the first item matching the predicate replaced by the newItem parameter
 * If no value in the list matches the predicate, the newItem will be appended to the end of the list
 * @param newItem the value to replace or add to the list
 * @param check The predicate to determine which item to replace. Item matching true will be replaced
 */
inline fun <T> Iterable<T>.replaceFirstInstance(newItem: T, check: (item: T) -> Boolean): List<T> {
    return replaceFirstInstance(newItem, appendIfNotFound = true, check)
}

/**
 * Return a new list, with the first item matching the predicate replaced by the newItem parameter
 * Optionally the new item can be appended to the end of the list if no match is found
 * @param newItem the value to replace or add to the list
 * @param appendIfNotFound If <b>true</b> item is appended to end of list if no match is found
 * @param check The predicate to determine which item to replace. Item matching true will be replaced
 */
inline fun <T> Iterable<T>.replaceFirstInstance(newItem: T, appendIfNotFound: Boolean, check: (item: T) -> Boolean): List<T> {
    var replaced = false
    val out = mutableListOf<T>()
    for (item in this) {
        if (!replaced && check(item)) {
            replaced = true
            out.add(newItem)
        } else {
            out.add(item)
        }
    }
    if (!replaced && appendIfNotFound) {
        out.add(newItem)
    }
    return out
}



