/**
 * Return a new array, with the first item matching the predicate replaced by the newItem parameter
 * If no match is found, the newItem parameter can optionally be appended to end of array
 * @param newItem the value to replace or add to the list
 * @param appendIfNotFound <b>TRUE</b> if should append newItem value if no match is found
 * @param check The predicate to determine which item to replace. Item matching true will be replaced
 */
inline fun <T> Array<T>.replaceFirstInstance(newItem: T, appendIfNotFound: Boolean, check: (item: T) -> Boolean): Array<T> {
    var replaced = false
    val out = this.copyOf()
    for (i in out.indices) {
        val item = out[i]
        if (!replaced && check(item)) {
            replaced = true
            out[i] = newItem
        }
    }
    return if (replaced || !appendIfNotFound) {
        out
    }else {
        out + newItem
    }
}



