fun <T> List<T>.replaceAtInCopy(i: Int, item: T): List<T> {
    val size = size
    val lastIndex = size - 1
    if (i - 1 == lastIndex) {
        return this + item
    }
    val list = toMutableList()
    list[i] = item
    return list
}

fun <T> List<T>.replaceAtInCopyGetting(i: Int, item: T): Pair<List<T>, T?> {

    val size = size
    val lastIndex = size - 1
    if (i - 1 == lastIndex) {
        return Pair(this + item, null)
    }
    val list = toMutableList()
    val replacedItem = list.set(i, item)
    return Pair(list, replacedItem)
}

fun <T> MutableList<T>.replaceAt(i: Int, item: T): T? {
    val size = size
    if (i == size) {
        this.add(item)
        return null
    }
    return this.set(i, item)
}

/**
 * Returns this collection if not empty, or null if collection is empty
 */
fun <C : Collection<T>, T> C.nullIfEmpty(): C? {
    return this.ifEmpty { null }
}

/**
 * Returns this array if not empty, or null if this array is empty
 */
fun <T> Array<T>?.nullIfEmpty(): Array<T>? {
    return if (isNullOrEmpty()) {
        null
    } else {
        this
    }
}

/**
 * Checks if another array has all items in the same index equal
 */
fun <T> Array<T>.isEqualTo(comparable: Array<T>): Boolean {
    var isEqual = true

    if (this.size == comparable.size) {
        for (index in comparable.indices) {
            if (this[index] != comparable[index]) {
                isEqual = false
                break
            }
        }
    } else {
        isEqual = false
    }

    return isEqual
}

/**
 * Checks if another collection has all items in the same index equal
 */
fun <T> List<T>.isEqualTo(comparable: List<T>): Boolean {
    var isChanged = true

    if (this.size == comparable.size) {
        for (index in comparable.indices) {
            if (this[index] != comparable[index]) {
                isChanged = false
                break
            }
        }
    } else {
        isChanged = false
    }

    return isChanged
}

