/**
 * Removes all null values from a list
 */
fun <T> Iterable<T?>.filterNotNull(): List<T> {
    val list: MutableList<T> = mutableListOf()
    for (item in this) {
        if (item != null) {
            list.add(item)
        }
    }
    return list
}


/**
 * Returns null if this array has no items, or optionally if empty or all items are null
 */
fun <R, T : Collection<R>> T?.nullIfEmpty(filterNullsFirst: Boolean): T? {
    if (this == null)
        return null
    val isEmpty = if (filterNullsFirst)
        this.filterNotNull().isEmpty()
    else
        this.isEmpty()
    return if (isEmpty) null else this
}

/**
 * Checks if this map is null or empty
 */
fun <K, V> Map<K, V>?.isNullOrEmpty(): Boolean {
    contract {
        returns(true) implies (this@isNullOrEmpty == null)
        returns(false) implies (this@isNullOrEmpty != null)
    }
    return this == null || this.isEmpty()
}

/**
 * Checks if this map is not null and not empty
 */
fun <K, V> Map<K, V>?.isNotNullOrEmpty(): Boolean {
    contract {
        returns(true) implies (this@isNotNullOrEmpty != null)
        returns(false) implies (this@isNotNullOrEmpty == null)
    }
    return this != null && this.isNotEmpty()
}

/**
 * Checks if this collection is null or empty
 */
fun <T> Collection<T>?.isNullOrEmpty(): Boolean {
    contract {
        returns(true) implies (this@isNullOrEmpty == null)
        returns(false) implies (this@isNullOrEmpty != null)
    }
    return this == null || this.isEmpty()
}

/**
 * Checks if this collection is not null and not empty
 */
fun <T> Collection<T>?.isNotNullOrEmpty(): Boolean {
    contract {
        returns(true) implies (this@isNotNullOrEmpty != null)
        returns(false) implies (this@isNotNullOrEmpty == null)
    }
    return this != null && this.isNotEmpty()
}


/**
 * Subtracts elements from one collection from the other if two items selected with lambda match
 */
inline fun <T, R> Collection<T>.minus(elements: Collection<T>, selector: (T) -> R?) {
    filter { t -> elements.none { selector(it) == selector(t) } }
}

/**
 * Returns a mutable list of not-null values from the values given
 */
fun <T : Any> mutableListOfNotNull(vararg elements: T?): MutableList<T> = elements.filterNotNull().toMutableList()


/**
 * Takes an iterator and pulls out all items into a list
 */
val <T : Any> Iterator<T>.values: List<T>
    get() {
        val out = mutableListOf<T>()
        while (hasNext()) {
            out.add(next())
        }
        return out
    }

/**
 * Checks that two collections have exactly the same items, regardless of ordering
 */
fun <T> Collection<T>.equalIgnoringOrder(other: Collection<T>): Boolean {
    if (other.size != size)
        return false
    val otherCopy: MutableList<T> = ArrayList(other)
    for (e in this) {
        if (e !in otherCopy) {
            return false
        }
        otherCopy.remove(e)
    }
    return true
}


/**
 * Checks that a collection has exactly the same items as the given array, regardless of ordering
 */
fun <T> Collection<T>.equalIgnoringOrder(other: Array<T>): Boolean {
    if (other.size != size)
        return false
    val otherCopy: MutableList<T> = other.toMutableList()
    for (e in this) {
        if (e !in otherCopy)
            return false
        otherCopy.remove(e)
    }
    return true
}

