/**
 * Returns a list with this value as its only value
 */
inline fun <reified T> T.toListOf(): List<T> {
    return listOf(this)
}

/**
 * Returns an array with this value as its only value
 */
inline fun <reified T> T.toArrayOf(): Array<T> {
    return arrayOf(this)
}



/**
 * See if any values in this collection match any values in the other collection
 */
infix fun <T> Collection<T>.likeAny(other: Collection<T>): Boolean {
    return this.intersect(other.toSet()).isNotEmpty()
}

/**
 * See if any values in this array match any values in the given array
 */
infix fun <T> Collection<T>.likeAny(other: Array<T>): Boolean {
    return this.intersect(other.toSet()).isNotEmpty()
}

