/**
 * Returns a value from a collection, if there is only one item in the list
 */
@Deprecated(
    "Use built in kotlin command: singleOrNull",
    replaceWith = ReplaceWith(
        "singleOrNull()"
    )
)
internal val <T> Collection<T>.firstIfOnlyOne: T?
    get() {
        return if (this.size == 1)
            first()
        else
            null
    }

/**
 * Returns a single value from an array, if there is only one item in the array
 */
internal val <T> Array<T>.firstIfOnlyOne: T?
    get() {
        return if (this.size == 1)
            first()
        else
            null
    }

/**
 * Returns a list with this iterables values, less any intersecting values
 */
fun <T> Iterable<T>.filterNotIn(other: Iterable<T>): List<T> {
    return this.filterNot { it in other }
}


/**
 * Returns a list with this iterables values, less any intersecting values
 */
fun <T> Iterable<T>.filterNotIn(other: Array<T>): List<T> {
    return this.filterNot { it in other }
}

/**
 * Returns a set of this set's values, less any intersecting items
 */
fun <T> Set<T>.filterNotIn(other: Iterable<T>): Set<T> {
    return filterNot { it in other }.toSet()
}


/**
 * Returns a new set, less any items that are also contained in the given array parameter
 */
fun <T> Set<T>.filterNotIn(other: Array<T>): Set<T> {
    return filterNot { it in other }.toSet()
}

/**
 * Returns a new array of this array's values, less any intersecting values
 */
inline fun <reified T> Array<T>.filterNotIn(other: Collection<T>): Array<T> {
    return this.filterNot { it in other }.toTypedArray()
}

/**
 * Returns a new array of this array's values, less any intersecting values
 */
inline fun <reified T> Array<T>.filterNotIn(other: Array<T>): Array<T> {
    return this.filterNot { it in other }.toTypedArray()
}

fun <T> MutableList<T>.insertFront(item: T): MutableList<T> {
    if (this.isEmpty())
        this.add(item)
    else
        this.add(0, item)
    return this
}

fun <T> MutableList<T>.insertFront(more: List<T>): MutableList<T> {
    if (this.isEmpty())
        this.addAll(more)
    else
        this.addAll(0, more)
    return this
}
fun <T> MutableList<T>.insertFront(more: Array<T>): MutableList<T> {
    if (this.isEmpty())
        this.addAll(more)
    else
        this.addAll(0, more.toList())
    return this
}

fun <T> MutableList<T>.splice(index:Int, itemCount:Int) : List<T> {
    val slice = slice(index until index + itemCount)
    for (i in index + itemCount - 1 downTo index) {
        removeAt(i)
    }
    return slice
}


fun <T> Iterator<T>.toList(): List<T> {
    if (!hasNext()) {
        return emptyList()
    }

    val out = mutableListOf<T>()
    while (hasNext()) {
        out.add(next())
    }

    return out
}

inline fun <T, R> Iterator<T>.map(transform: (T) -> R): List<R> {
    if (!hasNext()) {
        return emptyList()
    }
    val out = mutableListOf<R>()
    while (hasNext()) {
        out.add(transform(next()))
    }
    return out
}


inline fun <T, R> Iterator<T>.forEach(work: (T) -> R) {
    while (hasNext()) {
        work(next())
    }
}

inline fun <T, R> Iterator<List<T>>.flatMap(transform: (T) -> R): List<R> {
    val out = mutableListOf<R>()
    while (hasNext()) {
        out.addAll(next().map(transform))
    }
    return out
}

/**
 * Checks if this map is null or empty
 */
fun <K, V> Map<K, V>.with(key: K, value: V): Map<K, V> {
    val map = if (this is MutableMap<K, V>) {
        this
    } else {
        this.toMutableMap()
    }
    map[key] = value
    return map
}