private val containsInnerDir = "^.*?(.:[\\\\/].*)$".toRegex()

internal actual suspend fun isDirectoryInternal(filePath: String): Boolean {
    if (filePath.startsWith("resource:")) {
        return false
    }
    if (filePath.endsWith('/') || filePath.endsWith('\\')) {
        return true
    }
    val pathFixed = containsInnerDir.matchEntire(filePath)
        ?.groupValues
        ?.getOrNull(1)
        ?.nullIfEmpty()
        ?: filePath
    if (pathFixed != filePath) {
        Log.e { "File path is incorrectly concatenated; $pathFixed; $filePath" }
    }
    val opts = js("{}")
    opts.path = pathFixed
    return try {
        tauri.tauri.invoke<dynamic, Boolean>("is_directory", opts).await()
    } catch (e: dynamic) {
        return com.bedalton.common.util.trySilent {
            tauri.tauri.invoke<dynamic, Boolean>("is_dir", opts).await()
        } ?: isDirFallback(filePath)
    }
}

private suspend fun isDirFallback(filePath: String): Boolean {
    return suspendCoroutine { cont ->
        try {
            val pathEnding = pathSeparator(filePath)
            tauri.fs.exists(filePath.ensureEndsWith(pathEnding))
                .then { cont.resume(it) }
                .catch { cont.resume(false) }
        } catch (_: Error) {
            cont.resume(false)
        } catch (eRaw: dynamic) {
            val e = asTauriThrowable(eRaw)
            e.rethrowCancellationException()
            cont.resume(false)
        }
    }
}

internal suspend fun makeDirInternal(path: String, recursive: Boolean) {
    val opts: FsDirOptions = js("{}").unsafeCast<FsDirOptions>()
    opts.recursive = recursive
    createDir(path, options = opts).await()
}

internal suspend fun getChildrenInternal(parentFolder: String): List<String>? {
    return try {
        readDir(parentFolder).await().map {
            checkCancelled()
            val child = it.path
            if (PathUtil.isAbsolute(child)) {
                PathUtil.combine(child)
            } else {
                PathUtil.combine(parentFolder, child)
            }.replace('\\', '/')
        }
    } catch (e: Throwable) {
        e.rethrowCancellationException()
        if (fileExistsInternal(parentFolder)) {
            listOf(parentFolder)
        } else {
            null
        }
    }
}
