@file:Suppress("unused")

package com.bedalton.creatures.caos.libs

import kotlinx.serialization.KSerializer
import kotlinx.serialization.Serializable
import kotlinx.serialization.descriptors.PrimitiveKind
import kotlinx.serialization.descriptors.PrimitiveSerialDescriptor
import kotlinx.serialization.descriptors.SerialDescriptor
import kotlinx.serialization.encoding.Decoder
import kotlinx.serialization.encoding.Encoder
import kotlin.js.JsExport
import kotlin.js.JsName

internal object ValueTypeSerializer : KSerializer<ValueType> {
    override fun deserialize(decoder: Decoder): ValueType {
        return ValueType.fromIntValue(
            decoder.decodeInt()
        )
    }

    override val descriptor: SerialDescriptor
        get() = PrimitiveSerialDescriptor("value", PrimitiveKind.INT)

    override fun serialize(encoder: Encoder, value: ValueType) {
        encoder.encodeInt(value.value)
    }

}

/**
 * Represents the base types for a CaosScript expression
 */
@Serializable(with = ValueTypeSerializer::class)
@JsExport
enum class ValueType(val value: Int, val simpleName: String) {
    INT(1, "integer"),
    FLOAT(2, "float"),
    TOKEN(3, "token"),
    STRING(4, "string"),
    VARIABLE(6, "variable"),
    COMMAND(8, "command"),
    C1_STRING(9, "[string]"),
    BYTE_STRING(10, "[byte_string]"),
    AGENT(11, "agent"),
    ANY(13, "any"),
    CONDITION(15, "condition"),
    DECIMAL(16, "decimal"),
    ANIMATION(17, "[anim]"),
    HEXADECIMAL(18, "hexadecimal"),
    NULL(0, "NULL"),
    PICT_DIMENSION(19, "pict_dimensions"),
    EQ_OP(-2, "eqOp"),
    EQ_JOIN(-3, "(AND|OR)"),
    UNKNOWN(-1, "UNKNOWN"),
    PLACEHOLDER(-4, "PLACEHOLDER"),
    COMMENT(-5, "*comment"),
    CAOS2_COMMENT(-6, "*#CAOS2Pray comment"),
    NEWLINE(-7, "NEWLINE"),
    SPACES(-8, "SPACES");

    companion object {


        /**
         * Gets the expression type from its simple name
         */
        @Suppress("SpellCheckingInspection")
        fun fromSimpleName(simpleName: String): ValueType {
            return when (simpleName.trim().lowercase()) {
                "any" -> ANY
                "agent" -> AGENT
                "[anim]" -> ANIMATION
                "[byte_string]", "[byte string]", "byte string", "bytestring" -> BYTE_STRING
                "command" -> COMMAND
                "condition" -> CONDITION
                "decimal" -> DECIMAL
                "float" -> FLOAT
                "hexadecimal" -> HEXADECIMAL
                "int", "integer" -> INT
                "pict_dimension", "pict_dimensions", "picdemensions", "picdemension", "pict dimensions", "pict dimension" -> PICT_DIMENSION
                "string" -> STRING
                "[string]" -> C1_STRING
                "token" -> TOKEN
                "variable" -> VARIABLE
                "null" -> NULL
                else -> {
                    UNKNOWN
                }
            }
        }


        /**
         * Gets the expression type from its int representation
         */
        fun simpleName(value: Int): String? {
            return when (value) {
                1 -> INT.simpleName
                2 -> FLOAT.simpleName
                3 -> TOKEN.simpleName
                4 -> STRING.simpleName
                6 -> VARIABLE.simpleName
                8 -> COMMAND.simpleName
                9 -> C1_STRING.simpleName
                10 -> BYTE_STRING.simpleName
                11 -> AGENT.simpleName
                13 -> ANY.simpleName
                15 -> CONDITION.simpleName
                16 -> DECIMAL.simpleName
                17 -> ANIMATION.simpleName
                18 -> HEXADECIMAL.simpleName
                19 -> PICT_DIMENSION.simpleName
                -2 -> EQ_OP.simpleName
                -3 -> EQ_JOIN.simpleName
                -4 -> PLACEHOLDER.simpleName
                else -> null
            }
        }

        /**
         * Gets the expression type from its int representation
         */
        fun fromIntValue(value: Int): ValueType {
            return when (value) {
                1 -> INT
                2 -> FLOAT
                3 -> TOKEN
                4 -> STRING
                6 -> VARIABLE
                8 -> COMMAND
                9 -> C1_STRING
                10 -> BYTE_STRING
                11 -> AGENT
                13 -> ANY
                15 -> CONDITION
                16 -> DECIMAL
                17 -> ANIMATION
                18 -> HEXADECIMAL
                0 -> NULL
                19 -> PICT_DIMENSION
                -1 -> UNKNOWN
                -2 -> EQ_OP
                -3 -> EQ_JOIN
                -4 -> PLACEHOLDER
                else -> return UNKNOWN
            }
        }
    }
}


private val listOfNumberTypes = listOf(
    ValueType.INT,
    ValueType.FLOAT,
    ValueType.DECIMAL
)

private val listOfNumberTypeInts by lazy {
    listOfNumberTypes.map(ValueType::value)
}

internal val ValueType.isNumberType: Boolean
    get()
    = this in listOfNumberTypes

internal val listOfStringTypes = listOf(
    ValueType.STRING,
    ValueType.C1_STRING,
    ValueType.HEXADECIMAL
)

private val listOfStringTypesAsInts by lazy {
    listOfStringTypes.map(ValueType::value)
}


internal val listOfByteStringTypes by lazy {
    listOf(
        ValueType.BYTE_STRING,
        ValueType.ANIMATION
    )
}


private val listOfByteStringTypesAsInts by lazy {
    listOfByteStringTypes.map(ValueType::value)
}

internal val listOfAgentTypes by lazy {
    listOf(
        ValueType.AGENT,
        ValueType.NULL
    )
}

private val listOfAgentTypesAsInts by lazy {
    listOfAnyTypes.map(ValueType::value)
}

internal val ValueType.isAgentType: Boolean
    get()
    = this in listOfAgentTypes

internal val ValueType.isStringType: Boolean
    get()
    = this in listOfStringTypes

internal val ValueType.isByteStringLike: Boolean
    get() = this in listOfByteStringTypes


internal val listOfAnyTypes = listOf(
    ValueType.ANY,
    ValueType.UNKNOWN,
    ValueType.PLACEHOLDER
)

private val listOfAnyTypesInts by lazy {
    listOfAnyTypes.map(ValueType::value)
}

internal val ValueType.isAnyType: Boolean
    get()
    = this in listOfAnyTypes


infix fun ValueType.like(other: ValueType): Boolean {
    if (this == other)
        return true
    if (this == ValueType.VARIABLE || other == ValueType.VARIABLE)
        return true
    if (this.isAnyType || other.isAnyType)
        return true
    if (isNumberType && other.isNumberType)
        return true
    if (isStringType && other.isStringType)
        return true
    if (isByteStringLike && other.isByteStringLike)
        return true
    if (isAgentType && other.isAgentType)
        return true
    return false
}


infix fun ValueType.like(typeToken: Int): Boolean {
    return when (typeToken) {
        TypeTokens.COMMAND_TOKEN -> this == ValueType.TOKEN
        TypeTokens.SPACES -> this == ValueType.SPACES
        TypeTokens.NEWLINE -> this == ValueType.NEWLINE
        TypeTokens.INT -> this.isNumberType
        TypeTokens.FLOAT -> this.isNumberType
        TypeTokens.QUOTE_STRING -> this.isStringType
        TypeTokens.TOKEN -> this == ValueType.TOKEN
        TypeTokens.INDEXED_VARIABLE -> this == ValueType.VARIABLE
        TypeTokens.EQ_OP -> this == ValueType.EQ_OP
        TypeTokens.BRACKET_STRING -> this.isStringType
        TypeTokens.BYTE_STRING -> this.isByteStringLike
        TypeTokens.COMMENT -> this == ValueType.COMMENT
        TypeTokens.CAOS2_COMMENT -> this == ValueType.CAOS2_COMMENT
        TypeTokens.EQ_JOIN -> this == ValueType.EQ_JOIN
        TypeTokens.BINARY -> this.isNumberType
        TypeTokens.CHAR -> this.isNumberType
        TypeTokens.PLACEHOLDER_TOKEN -> this == ValueType.PLACEHOLDER
        TypeTokens.PICT_DIMENSION -> this == ValueType.PICT_DIMENSION
        TypeTokens.ERROR -> false
        else -> false
    }

}

@JsExport
@JsName("isSimilarValueType")
fun isSimilarType(type: ValueType, other: ValueType): Boolean {
    if (type == other)
        return true
    if (type == ValueType.VARIABLE || other == ValueType.VARIABLE)
        return true
    if (type.isAnyType || other.isAnyType)
        return true
    if (type.isNumberType && other.isNumberType)
        return true
    if (type.isStringType && other.isStringType)
        return true
    if (type.isByteStringLike && other.isByteStringLike)
        return true
    if (type.isAgentType && other.isAgentType)
        return true
    return false
}

@JsExport
@JsName("isSimilarType")
fun isSimilarType(type: Int, other: Int): Boolean {
    if (type == other) {
        return true
    }
    if (type == ValueType.VARIABLE.value || other == ValueType.VARIABLE.value) {
        return true
    }
    if (type in listOfAnyTypesInts || other in listOfAnyTypesInts) {
        return true
    }
    if (type in listOfNumberTypeInts && other in listOfNumberTypeInts) {
        return true
    }
    if (type in listOfStringTypesAsInts && other in listOfStringTypesAsInts) {
        return true
    }
    if (type in listOfByteStringTypesAsInts && other in listOfByteStringTypesAsInts) {
        return true
    }
    if (type in listOfAgentTypesAsInts && other in listOfAgentTypesAsInts) {
        return true
    }
    return false
}