@file:Suppress("unused")

package com.bedalton.creatures.breed.render.internal

import com.bedalton.creatures.common.structs.BreedKey
import com.bedalton.creatures.common.structs.GameVariant
import com.bedalton.creatures.common.util.getGenusString
import com.bedalton.creatures.sprite.util.PaletteTransform


/**
 * Write a palette transform as a CLI opt list
 */
internal fun StringBuilder.appendTransform(transform: PaletteTransform?): StringBuilder {
    if (transform == null) {
        return this
    }

    val red = transform.red
    val green = transform.green
    val blue = transform.blue
    if ((red != null && red != 128) || (green != null && green != 128) || (blue != null && blue != 128)) {
        append("--tint ")
        append(red ?: "").append(':')
        append(green ?: "").append(':')
        append(blue ?: "").append(' ')
    }
    if (transform.swap != null && transform.swap != 128) {
        appendOpt("swap", transform.swap)
    }
    if (transform.rotation != null && transform.rotation != 128) {
        appendOpt("rotation", transform.rotation)
    }
    return this
}


internal fun StringBuilder.appendOpt(opt: String, value: Any?): StringBuilder {
    if (value == null) {
        return this
    }
    return append("--").append(opt).append(' ').append(value).append(' ')
}

internal fun StringBuilder.appendOpt(opt: Char, value: Any?): StringBuilder {
    return append("-").append(opt).append(' ').append(value).append(' ')
}

internal fun StringBuilder.appendOpt(opt: String, parts: List<Char>?): StringBuilder {
    if (parts.isNullOrEmpty()) {
        return this
    }
    return append("--").append(opt).append(*parts.toTypedArray())
}

internal fun StringBuilder.appendOpt(opt: String, key: BreedKey?): StringBuilder {
    if (key == null) {
        return this
    }
    val genusInt = key.genus
        ?: return this
    val genusString = getGenusString(genusInt, GameVariant.C1)?.getOrNull(0)?.lowercaseChar()
        ?: return this
    val breedChar = key.breed
        ?: return this
    return append("--").append(opt)
        .append(' ')
        .append(genusString).append(':').append(breedChar)
        .append(' ')
}

internal fun StringBuilder.appendFlag(flag: String): StringBuilder {
    return append("--").append(flag).append(' ')
}

internal fun StringBuilder.appendFlag(flag: String, active: Boolean?): StringBuilder {
    if (active == true) {
        append("--").append(flag).append(' ')
    }
    return this
}


internal fun <T,V> Collection<T>.takeIfOne(opt: (T) -> V): V? {
    if (isEmpty()) {
        return null
    }
    return map(opt).distinct().takeIfOne()
}


internal fun <T> Collection<T>.takeIfOne(): T? {
    return if (size == 1) {
        first()
    } else {
        null
    }
}