package com.creaturesforge.application.state

import com.bedalton.log.LOG_VERBOSE
import com.bedalton.log.Log
import com.bedalton.log.iIf
import com.bedalton.state.simple.Dispatch
import com.bedalton.state.simple.Next
import com.creaturesforge.application.util.json

internal fun loggingMiddleware(
    state: ForgeState,
    action: FAction,
    dispatch: Dispatch<FAction>,
    next: Next<ForgeState, FAction>,
): FAction {

    if (action is DoNotLogThisAction) {
        return next(state, action, dispatch)
    }
    Log.iIf(LOG_VERBOSE) {
        getActionStateString(state, action)
    }

    return next(state, action, dispatch)
}


private fun Collection<String>?.toCountOf(): List<String>? {
    return if (this == null) {
        null
    } else {
        listOf(this.size.toString())
    }
}

internal fun getActionStateString(state: ForgeState, action: FAction): String {
    val loggableAction = when (action) {
        is SetAttFilesAction -> action.copy(files = listOf(action.files.size.toString()))
        is SetSpriteFilesAction -> action.copy(files = listOf(action.files.size.toString()))
        else -> action
    }

    val trimmedState = state.copy(
        spriteFiles = state.spriteFiles.toCountOf(),
        attFiles = state.attFiles.toCountOf(),
    )

    val stateString = json.encodeToString(ForgeState.serializer(), trimmedState)

    return "Action: $loggableAction;\nState:\n$stateString"
}