package com.bedalton.creatures.breed.render.files

import com.bedalton.creatures.breed.render.renderer.RenderValueOutOfRangeException
import com.bedalton.creatures.common.structs.BreedKey
import com.bedalton.log.ConsoleColors.BOLD
import com.bedalton.log.ConsoleColors.RESET
import com.bedalton.log.LOG_VERBOSE
import com.bedalton.log.Log
import com.bedalton.log.wIf


data class SpriteAndAtt(
    val part: Char,
    val key: BreedKey,
    val spriteFile: BreedFileData,
    val attFile: BreedFileData
) {

    val code: String by lazy { "$part${key.code}" }

    init {
        if (part.lowercaseChar() !in 'a' .. 'q' && part.lowercaseChar() != '0' && part.lowercaseChar() != 'z') {
            throw RenderValueOutOfRangeException(
                "Part string must be a single character 'a'..'q'",
                "part char",
                part,
                "a", "q"
            )
        }
        if (part.lowercaseChar() == '0' || part.lowercaseChar() == 'z') {
            Log.wIf(LOG_VERBOSE) { "Parts with prefix $BOLD'0'$RESET and $BOLD'z'$RESET should probably not be handled" }
        }
    }
}