package com.bedalton.io.bytes

import okio.ByteString


/**
 * Decodes a byte array of a windows CP1252 encoded string to a kotlin string
 */
@Deprecated("Use decodeToWindowsCP1252",
    ReplaceWith("decodeToWindowsCP1252(start, endExclusive)",
        imports = ["com.bedalton.io.bytes.decodeToWindowsCP1252"]
    )
)
fun ByteArray.decodeToCreaturesEncoding(start: Int = 0, endExclusive: Int? = null): String {
    return decodeToWindowsCP1252(start, endExclusive)
}

/**
 * Decodes a byte array of a windows CP1252 encoded string to a kotlin string
 */
expect fun ByteArray.decodeToWindowsCP1252(start: Int = 0, endExclusive: Int? = null): String


fun ByteString.decodeToWindowsCP1252(start: Int = 0, endExclusive: Int? = null): String {
    val substring = if (endExclusive != null) {
        substring(start, endExclusive)
    } else {
        substring(start)
    }
    return substring
        .toByteArray()
        .decodeToString()
}
