package com.bedalton.creatures.agents.util.internal

import com.bedalton.creatures.agents.pray.compiler.PrayCompileOptions
import com.bedalton.creatures.agents.pray.compiler.REMOVER_SCRIPT_REGEX
import com.bedalton.creatures.agents.pray.compiler.internal.blockStats
import com.bedalton.creatures.agents.pray.compiler.data.Tag
import com.bedalton.creatures.agents.pray.compiler.data.Tags
import com.bedalton.creatures.agents.pray.compiler.data.TextValue

/**
 * Takes all tags and returns a processed set of tags with auto-remover scripts
 */
internal fun tagsWithGeneratedRemovers(tags: Tags, opts: PrayCompileOptions) : Tags {
    if (!opts.generateAgentRemovers && !opts.generateScriptRemovers) {
        return tags
    }
    var outScript = ""
    val stringTags = tags.filterIsInstance<Tag.StringTag>().toTypedArray()
    val blockStats = blockStats(stringTags)
    if (opts.generateAgentRemovers) {
        outScript += "* Autogenerated Agent Remover scripts\n"
        outScript += blockStats.keys.joinToString("\n") { "enum $it\n\tkill targ\nnext" }
        outScript += "\n\n"
    }
    if (opts.generateScriptRemovers) {
        outScript += "* Autogenerated Event Script removers"
        outScript += blockStats.entries.joinToString("\n") { (classifier, eventNumbers) ->
            eventNumbers.joinToString("\n") { eventNumber -> "scrx $classifier $eventNumber" }
        }
    }

    if (outScript.isBlank()) {
        return tags
    }

    if (stringTags.none { REMOVER_SCRIPT_REGEX.matches(it.tag) } )
        return tags + Tag.StringTag(
            lineNumber = 0,
            startIndex = -1,
            endIndex = -1,
            tagRange = TextValue(
                "Remove script",
                lineNumber = -1,
                startIndex = -1,
                endIndex = -1,
            ),
            value = TextValue(
                text = outScript,
                lineNumber = -1,
                startIndex = -1,
                endIndex = -1,
            )
        )

    val outTags = tags.filterIsInstance<Tag.IntTag>() + stringTags.map {
            if (REMOVER_SCRIPT_REGEX.matches(it.tag)) {
                Tag.StringTag(
                    lineNumber = it.lineNumber,
                    startIndex = -1,
                    endIndex = -1,
                    tagRange = it.tagRange,
                    value = TextValue(
                        text = it.value + "\n\n" + outScript,
                        lineNumber = it.lineNumber,
                        startIndex = -1,
                        endIndex = -1
                    )
                )
            } else {
                it
            }
        }

    return outTags.toTypedArray()
}