@file:Suppress("unused")

package com.bedalton.creatures.sprite.parsers

import com.bedalton.common.structs.AlreadyDisposedDataCacheException
import com.bedalton.creatures.sprite.util.ColorEncoding
import com.bedalton.creatures.sprite.util.PaletteTransform
import com.bedalton.creatures.sprite.util.SpriteType
import com.bedalton.io.bytes.ByteStreamReader

/**
 * Parses Creatures S16 sprite file
 * Based on c2ephp by telyn
 * @url https://github.com/telyn/c2ephp
 */
class S16SpriteFile(
    bytesBuffer: ByteStreamReader,
    keepBlack: Boolean,
    paletteTransform: PaletteTransform? = null,
    progressChunkSize: Int = 1,
    progressCallback: ((current: Int, total: Int) -> Boolean?)? = null,
) : SpriteFile(SpriteType.S16, keepBlack, paletteTransform, progressChunkSize, progressCallback) {

    private var mBytesBuffer: ByteStreamReader? = bytesBuffer

    override val allowAsync: Boolean
        get() = false

    private var mSize: Int? = null


    private var mEncoding: ColorEncoding? = null

    private val readAt = bytesBuffer.position()

    override val encoding: ColorEncoding
        get() = mEncoding ?: mBytesBuffer?.readAtPosition(readAt) {
            // Figure out encoding either 555 or 565
            val encoding = when (val encodingBuffer = uInt32()) {
                1L -> ColorEncoding.X_565
                0L -> ColorEncoding.X_555
                else -> throw Exception("S16 file encoding not recognized. ('$encodingBuffer')")
            }
            mEncoding = encoding
            encoding
        } ?: throw AlreadyDisposedDataCacheException("Cannot get encoding. Byte buffer already closed")


    override fun sizeInternal(): Int {
        mSize?.let {
            return it
        }
        val bytesBuffer = mBytesBuffer
            ?: throw SpriteParserException("Failed to get sprite frame count. File stream already closed")
        return SpriteParser.imagesCount("file.$extension", bytesBuffer)?.apply {
            mSize = this
        } ?: throw SpriteParserException("Failed to get sprite count from raw bytes")
    }

    override fun initFramesInternal(): List<SpriteFrameAsync> {
        val bytesBuffer = mBytesBuffer
            ?: throw SpriteParserException("Cannot init S16 sprite file with closed byte buffer")

        // Figure out encoding either 555 or 565
        val encoding = when (val encodingBuffer = bytesBuffer.uInt32()) {
            1L -> ColorEncoding.X_565
            0L -> ColorEncoding.X_555
            else -> throw Exception("S16 file encoding not recognized. ('$encodingBuffer')")
        }
        mEncoding = encoding
        return initS16Frames(encoding, bytesBuffer, keepBlack, paletteTransform)
    }

    /**
     * Close any internal streams, and release references
     */
    override fun closeInternal(): Boolean {
        return mBytesBuffer?.close()?.apply {
            mBytesBuffer = null
        } ?: true
    }

}

fun parseS16FrameAtPosition(
    bytesBuffer: ByteStreamReader,
    offset: Long,
    width: Int,
    height: Int,
): PixelIndices {
    return bytesBuffer.readAtPosition(offset) {
        parseS16FrameAtCurrentPosition(
            this,
            width,
            height
        )
    }
}

/**
 * Parses a sprite image at the current buffer position
 */
fun parseS16FrameAtCurrentPosition(
    bytesBuffer: ByteStreamReader,
    width: Int,
    height: Int,
): PixelIndices {
    val out = IntArray(width * height) { 0 }
    val black = PixelIndices.TRANSPARENT_BLACK
    repeat(height) { y ->
        val offsetY = y * width
        repeat(width) { x ->
            val pixel = bytesBuffer.uInt16()
            out[offsetY + x] = if (pixel == 0) {
                black
            } else {
                pixel
            }
        }
    }
    // Return the bytes
    return PixelIndices(width, height, out)
}

/**
 * Reads the frame data for an S16 sprite at current offset of byte stream reader
 */
private fun initS16Frames(
    encoding: ColorEncoding,
    buffer: ByteStreamReader,
    keepBlack: Boolean,
    paletteTransform: PaletteTransform?,
): List<SpriteFrameAsync> {

    val palette = paletteTransform
        ?.transform(encoding, keepBlack)
        ?: encoding.toRgbWithTables(keepBlack)

    val paletteColors = palette.colors

    // Find number of images
    val imagesCount = buffer.uInt16()

    return (0 until imagesCount).map {
        val offsetForData = buffer.uInt32()
        val width = buffer.uInt16()
        val height = buffer.uInt16()
        SpriteFrameAsyncImpl(
            width,
            height,
            paletteColors,
            keepBlack,
            { }
        ) {
            parseS16FrameAtPosition(
                bytesBuffer = buffer,
                offsetForData,
                width = width,
                height = height
            )
        }
    }
}