package com.bedalton.vfs

import com.bedalton.common.util.PathUtil
import com.bedalton.common.util.ensureNotEndsWith

fun List<String>.sortedNice() = this.sortedWith(sortedFilesNice)

private val leadingNumberRegex = "^(\\d+)(.+?)?(\\..+$)?".toRegex()
private val trailingNumberRegex = "^(.+?)?(\\d+)(\\..+$)?".toRegex()

/**
 * Sort string values by leading and trailing numbers
 */
private val sortedFilesNice: Comparator<String> = Comparator sort@{ aRaw: String, bRaw: String ->
    val a = (PathUtil.getLastPathComponent(aRaw) ?: aRaw).lowercase()
    val b = (PathUtil.getLastPathComponent(bRaw) ?: bRaw).lowercase()
    val aDirectory = PathUtil.getSelfOrParentDirectory(aRaw)?.lowercase()?.ensureNotEndsWith(a)
    val bDirectory = PathUtil.getSelfOrParentDirectory(bRaw)?.lowercase()?.ensureNotEndsWith(b)
    if (aDirectory != null && aDirectory != a && bDirectory != null && bDirectory != b) {
        val sort = aDirectory.compareTo(bDirectory)
        if (sort != 0) {
            return@sort sort
        }
    }
    val aMatchLeading = leadingNumberRegex
        .matchEntire(a)
        ?.groupValues
        ?.let {
            Pair(it[2], it[1])
        }
    val bMatchLeading = leadingNumberRegex
        .matchEntire(b)
        ?.groupValues
        ?.let {
            Pair(it[2], it[1])
        }

    if (aMatchLeading != null && bMatchLeading != null) {
        val numberA = aMatchLeading.second.toInt()
        val numberB = bMatchLeading.second.toInt()

        val sort = numberA - numberB
        if (sort != 0) {
            return@sort sort
        }

        val secondSort = aMatchLeading.first.compareTo(bMatchLeading.first)
        if (secondSort != 0) {
            return@sort secondSort
        }

    }


    // Get a parts with trailing number
    val aMatchTrailing = trailingNumberRegex
        .matchEntire(a)
        ?.groupValues
        ?.let { matches ->
            Pair(matches[1].let { name -> if (name.startsWith('.')) "" else name }, matches[2])
        }

    // Get b parts with trailing number
    val bMatchTrailing = trailingNumberRegex
        .matchEntire(b)
        ?.groupValues
        ?.let { matches ->
            Pair(matches[1].let { name -> if (name.startsWith('.')) "" else name }, matches[2])
        }

    // Compare the parts by their trailing number
    if (aMatchTrailing != null && bMatchTrailing != null) {
        val numberA = aMatchTrailing.second.toInt()
        val numberB = bMatchTrailing.second.toInt()

        val firstSort = aMatchTrailing.first.compareTo(bMatchTrailing.first)
        if (firstSort != 0) {
            return@sort firstSort
        }

        val sort = numberA - numberB
        if (sort != 0) {
            return@sort sort
        }
    }
    a.compareTo(b)
}