package com.bedalton.common.ast.collectors

import kotlinx.serialization.Serializable
import kotlin.js.JsExport

@JsExport
@Serializable
enum class CursorPosition(val value: Int) {
    BEFORE(CursorPositionValues.BEFORE),
    START(CursorPositionValues.START),
    INSIDE(CursorPositionValues.INSIDE),
    END(CursorPositionValues.END),
    AFTER(CursorPositionValues.AFTER)
}

@JsExport
object CursorPositionValues {
    const val BEFORE = 0
    const val START = 1
    const val INSIDE = 2
    const val END = 3
    const val AFTER = 4
}