@file:Suppress("unused")

package com.bedalton.creatures.breed.render.renderer

import com.bedalton.creatures.breed.render.internal.dynamicToPaletteTransform
import com.bedalton.creatures.breed.render.support.pose.PoseRenderException
import com.bedalton.creatures.common.structs.BreedKey
import com.bedalton.creatures.common.structs.GameVariant
import com.bedalton.creatures.genetics.genome.Genome
import kotlin.js.JsExport

/**
 * Builder for gener
 */
@JsExport
open class JsBreedRendererBuilderBase(gameVariant: String) {

    private var builder = BreedRendererBuilder(GameVariant.fromString(gameVariant)!!)

    /**
     * Get root directories where the renderer looks for breed files
     */
    fun getSourceRoots(): Array<String> {
        return builder.getSourceRoots()
    }

    /**
     * Swap and rotate to apply to the sprites
     */
    fun withSwapAndRotate(
        red: Int,
        green: Int,
        blue: Int,
        swap: Int,
        rotation: Int,
        throwOnInvalidValues: Boolean
    ): JsBreedRendererBuilderBase {
        builder = builder.withTintSwapAndRotate(red, green, blue, swap, rotation, throwOnInvalidValues)
        return this
    }

    /**
     * Add a root directory to search for breed files
     */
    fun withAddRoot(root: String): JsBreedRendererBuilderBase {
        builder = builder.withAddSourceRoot(root)
        return this
    }

    /**
     * Add a root directory to search for breed files
     */
    fun withAddRoots(root: Array<String>): JsBreedRendererBuilderBase {
        builder = builder.withAddSourceRoots(root)
        return this
    }

    /**
     * The root directories to search for files in
     */
    fun withSetRoots(roots: Array<String>): JsBreedRendererBuilderBase {
        builder = builder.withSetSourceRoots(roots.toList())
        return this
    }

    /**
     * Head and ear breed to apply to rendered creature
     */
    fun withHead(genus: Int, breed: String, gender: Int? = null): JsBreedRendererBuilderBase {
        builder = builder.withHead(genus, breed[0], gender)
        return this
    }

    /**
     * Body breed to apply to rendered creature
     */
    fun withBody(genus: Int, breed: String, gender: Int? = null): JsBreedRendererBuilderBase {
        builder = builder.withBody(genus, breed[0], gender)
        return this
    }

    /**
     * Leg breed to apply to rendered creature
     */
    fun withLegs(genus: Int, breed: String, gender: Int? = null): JsBreedRendererBuilderBase {
        builder = builder.withLegs(genus, breed[0], gender)
        return this
    }

    /**
     * Left leg breed to apply to rendered creature
     */
    fun withLeftLeg(genus: Int, breed: String, gender: Int? = null): JsBreedRendererBuilderBase {
        builder = builder.withLeftLeg(genus, breed[0], gender)
        return this
    }

    /**
     * Right leg breed to apply to rendered creature
     */
    fun withRightLeg(genus: Int, breed: String, gender: Int? = null): JsBreedRendererBuilderBase {
        builder = builder.withRightLeg(genus, breed[0], gender)
        return this
    }

    /**
     * Arm breed to apply to the rendered creature
     */
    fun withArms(genus: Int, breed: String, gender: Int? = null): JsBreedRendererBuilderBase {
        builder = builder.withArms(genus, breed[0], gender)
        return this
    }

    /**
     * Left arm breed to apply to the rendered creature
     */
    fun withLeftArm(genus: Int, breed: String, gender: Int? = null): JsBreedRendererBuilderBase {
        builder = builder.withLeftArm(genus, breed[0], gender)
        return this
    }

    /**
     * Right arm breed to apply to the rendered creature
     */
    fun withRightArm(genus: Int, breed: String, gender: Int? = null): JsBreedRendererBuilderBase {
        builder = builder.withRightArm(genus, breed[0], gender)
        return this
    }

    /**
     * Tail breed to apply to the rendered creature
     */
    fun withTail(genus: Int, breed: String, gender: Int? = null): JsBreedRendererBuilderBase {
        builder = builder.withTail(genus, breed[0], gender)
        return this
    }

    /**
     * Hair breed to apply to the rendered creature
     */
    fun withHair(genus: Int, breed: String, gender: Int? = null): JsBreedRendererBuilderBase {
        builder = builder.withHair(genus, breed[0], gender)
        return this
    }

    /**
     * The game variant for these sprites and atts
     */
    fun withGameVariant(gameVariant: String): JsBreedRendererBuilderBase {
        builder = builder.withGameVariant(GameVariant.fromString(gameVariant)!!)
        return this
    }

    /**
     * Gender to use if no gender is set for the part breeds assigned
     */
    fun withFallbackGender(gender: Int): JsBreedRendererBuilderBase {
        builder = builder.withFallbackGender(gender)
        return this
    }

    /**
     * Color transform game variant to use in transforms
     * Really only matters if rendering C1 transforms for C2+ sprites as this limits the palette
     */
    fun withPaletteTransformVariant(variantString: String): JsBreedRendererBuilderBase {
        val variant = GameVariant.fromString(variantString)
            ?: throw PoseRenderException("Failed to parse variant for palette transform variant; Variant $variantString is invalid")
        builder = builder.withPaletteTransformVariant(variant)
        return this
    }

    /**
     * The color transform to apply to rendered sprites
     */
    fun withPaletteTransform(paletteTransform: Any?): JsBreedRendererBuilderBase {
        builder = builder.withPaletteTransform(dynamicToPaletteTransform(paletteTransform))
        return this
    }


    /**
     * The creature age at which to render the poses
     */
    fun withAge(age: Int): JsBreedRendererBuilderBase {
        builder = builder.withAge(age)
        return this
    }

    /**
     * Whether to only use att and sprites that match the breed exactly
     */
    fun withExactMatch(exact: Boolean?): JsBreedRendererBuilderBase {
        builder = builder.withExactMatch(exact)
        return this
    }

    /**
     * Parts to render semi-transparent
     * Set alpha using #withGhostAlpha
     */
    fun withGhostParts(parts: String): JsBreedRendererBuilderBase {
        builder = builder.withGhostParts(parts.lowercase().toCharArray().filter { char -> char in 'a'..'q' })
        return this
    }

    /**
     * Parts char string with parts to hide from the rendering
     */
    fun withHiddenParts(parts: String): JsBreedRendererBuilderBase {
        builder = builder.withHiddenParts(parts.lowercase().toCharArray().filter { char -> char in 'a'..'q' }.joinToString{ "$it" })
        return this
    }

    /**
     * The alpha to apply to all ghost parts
     */
    fun withGhostAlpha(alpha: Double?): JsBreedRendererBuilderBase {
        builder = builder.withGhostAlpha(alpha)
        return this
    }

    /**
     * Whether to render ghost parts below non-transparent parts
     */
    fun withGhostPartsBelow(below: Boolean): JsBreedRendererBuilderBase {
        builder = builder.withRenderGhostPartsBelow(below)
        return this
    }

    /**
     * The zoom to apply to rendered image, if not set in poseRender constructor
     */
    fun withDefaultZoom(zoom: Int): JsBreedRendererBuilderBase {
        builder = builder.withDefaultZoom(zoom)
        return this
    }

    /**
     * Whether to prevent intersecting limbs, that are typically rendered in the games
     */
    fun withNonIntersectingLimbs(doNotIntersect: Boolean): JsBreedRendererBuilderBase {
        builder = builder.withNonIntersectingLimbs(doNotIntersect)
        return this
    }

    /**
     * Whether to trim whitespace around generated image
     * Part sprites tend to have whitespace around them
     * adding to whitespace around the rendered creature
     */
    fun withTrimWhitespace(trim: Boolean?): JsBreedRendererBuilderBase {
        builder = builder.withTrimWhitespace(trim)
        return this
    }

    /**
     * Padding to add around all generated images
     */
    fun withPadding(padding: Int?): JsBreedRendererBuilderBase {
        builder = builder.withPadding(padding)
        return this
    }

    /**
     * Sets the genome part breeds and color transform right before building
     * This will overwrite any transform or part breeds already set
     */
    fun withGenomeApplyAtBuild(genome: Genome?, geneVariant: Int? = null): JsBreedRendererBuilderBase {
        builder = builder.withGenomeApplyAtBuild(genome, geneVariant ?: 0)
        return this
    }

    /**
     * Set the genome and set breed parts and color transforms immediately
     */
    fun withGenomeApplyNow(genome: Genome?, gender: Int, age: Int, geneVariant: Int? = null): JsBreedRendererBuilderBase {
        builder = builder.withGenomeApplyNow(genome, gender, age, geneVariant ?: 0)
        return this
    }

    /**
     * Whether to search roots recursively
     */
    fun withRecursiveFileSearch(recursive: Boolean?): JsBreedRendererBuilderBase {
        builder = builder.withRecursiveFileSearch(recursive)
        return this
    }

    /**
     * Only match atts that are for the same breed and genus
     */
    fun withCloseAttMatchOnly(closeAttMatchOnly: Boolean?): JsBreedRendererBuilderBase {
        builder = builder.withCloseAttMatchOnly(closeAttMatchOnly)
        return this
    }

    /**
     * Gets the genome that is being used by this renderer
     */
    fun getGenome(): Genome? {
        return builder.getGenome()
    }

    /**
     * Applies the palette transform from the genomes tint, swap and rotate genes
     */
    fun applyColorTransformFromGenome(genome: Genome, gender: Int, age: Int, geneVariant: Int? = null): JsBreedRendererBuilderBase {
        builder = builder.applyColorTransformFromGenome(genome, gender, age, geneVariant ?: 0)
        return this
    }

    /**
     * Apply part breeds from a genome's genes
     * @param selectedVariant gene variant as used from C3 (0..8) or for C2 eggs (0..2); With zero first found
     */
    fun applyPartBreedsFromGenome(genome: Genome, gender: Int, age: Int, selectedVariant: Int? = null): JsBreedRendererBuilderBase {
        builder = builder.applyPartsFromGenome(genome, gender, age, selectedVariant ?: 0)
        return this
    }

    /**
     * Sets the breed for a parts in the string if they are not set
     */
    fun withBreedIfNotSet(genus: Int, breed: String, gender: Int? = null, parts: String): JsBreedRendererBuilderBase {
        val breedKey = BreedKey(
            genus = genus,
            breed = breed[0],
            gender = gender
        )
        builder = builder.withBreedIfNotSet(breedKey, *parts.toCharArray())
        return this
    }

    /**
     * Sets the Sprite directory to use for a given breed
     */
    fun withBreedSpriteDirectory(genus: Int, breed: String, gender: Int, directory: String): JsBreedRendererBuilderBase {
        builder = builder.withBreedSpriteDirectory(genus, breed, gender, directory)
        return this
    }


    /**
     * Sets the Att directory to use for a given breed
     */
    fun withBreedAttDirectory(genus: Int, breed: String, gender: Int, directory: String): JsBreedRendererBuilderBase {
        builder = builder.withBreedSpriteDirectory(genus, breed, gender, directory)
        return this
    }

    /**
     * Get array of limbs missing breeds
     * @param requireTail whether tail should be added to missing if not set
     */
    fun missingRequiredParts(requireTail: Boolean): Array<String> = builder.missingRequiredParts(requireTail)

    /**
     * Output the CLI options that make up this render
     */
    fun toCLIOpts(withRoots: Boolean = false): String? = builder.toCLIOpts(withRoots)

    /**
     * Whether breeds have been set for all parts in array.
     * Array should contain single char strings
     */
    fun hasBreed(parts: Array<String>): Boolean = builder.hasBreed(parts.map { it.single() })

    /**
     * Whether breeds have been set for every char in this string
     */
    fun hasBreedForPartsInString(parts: String): Boolean = builder.hasBreed(*parts.toCharArray())

    /**
     * Check if a breed has been set for the head
     */
    fun hasHeadBreed(): Boolean = builder.hasHeadBreed()

    /**
     * Check if a breed has been set for the body
     */
    fun hasBodyBreed(): Boolean = builder.hasBodyBreed()

    /**
     * Checks if a breed has been set for the left leg
     */
    fun hasLeftLegBreed(): Boolean = builder.hasLeftLegBreed()

    /**
     * Checks if a breed has been set for the right leg
     */
    fun hasRightLegBreed(): Boolean = builder.hasRightLegBreed()

    /**
     * Checks if a breed has been set for both legs
     */
    fun hasLegBreed(): Boolean = builder.hasLegBreed()

    /**
     * Checks if a breed has been set for left arm
     */
    fun hasLeftArmBreed(): Boolean = builder.hasLeftArmBreed()

    /**
     * Checks if a breed has been set for the right arm
     */
    fun hasRightArmBreed(): Boolean = builder.hasRightArmBreed()

    /**
     * Checks if a breed has been set for the both arms
     */
    fun hasArmBreed(): Boolean = builder.hasArmBreed()

    /**
     * Checks if a breed has been set for the tail
     */
    fun hasTailBreed(): Boolean = builder.hasTailBreed()


    /**
     * Checks if a breed has been set for the hair
     */
    fun hasHairBreed(): Boolean = builder.hasHairBreed()


    /**
     * Get a renderer that can renders poses from Pose objects
     */
    internal fun poseRenderer(padding: Int? = null, defaultZoom: Double? = null, paletteTransform: Any? = null): PoseRenderer {
        return builder.poseRenderer(padding ?: builder.getPadding() ?: 0, defaultZoom, dynamicToPaletteTransform(paletteTransform))
    }

    /**
     * Get a renderer that can renders poses from pose strings
     */
    internal fun poseStringRenderer(padding: Int? = null, defaultZoom: Double? = null, paletteTransform: Any? = null): PoseStringRenderer {
        return builder.poseStringRenderer(padding ?: builder.getPadding() ?: 0, defaultZoom, dynamicToPaletteTransform(paletteTransform))
    }
}