package com.creaturesforge.application.interop

import com.bedalton.common.util.formatted
import com.bedalton.log.Log
import com.bedalton.state.simple.Dispatch
import com.bedalton.state.simple.Middleware
import com.creaturesforge.application.state.*


internal val tauriMiddleware: Middleware<ForgeState, FAction> = alwaysNextMiddleware { _: ForgeState, action: FAction, _: Dispatch<FAction> ->

    when (action) {

        is SetDisablePreviousGenomeCaching -> {
            try {
                if (action.initiator) {
                    DisabledSettingsInterop.setGenomeListDisabledInTauri(action.disable)
                }
            } catch (e: Throwable) {
                Log.e { "set disable previous genome list caching in tauri; ${e.formatted()}" }
            }
        }

        is SetDisableProjectDataCaching -> {
            try {
                if (action.initiator) {
                    DisabledSettingsInterop.setDisableCachedProjectSettingsInTauri(action.disable)
                }
            } catch (e: Throwable) {
                Log.e { "set project data caching in tauri; ${e.formatted()}" }
            }
        }

        is SetEggModeAction -> {
            setEggModeInTauri(action.eggMode)
        }

        else -> {}

    }

}

