@file:Suppress("MemberVisibilityCanBePrivate", "unused")

package com.bedalton.creatures.breed.render.support.pose

import com.bedalton.creatures.breed.render.support.pose.PoseConstants.EarsIndex.EARS_ANGRY
import com.bedalton.creatures.breed.render.support.pose.PoseConstants.EarsIndex.EARS_DROOPY
import com.bedalton.creatures.breed.render.support.pose.PoseConstants.EarsIndex.EARS_NORMAL
import com.bedalton.creatures.breed.render.support.pose.PoseConstants.EarsIndex.EARS_PRICKED
import com.bedalton.creatures.common.structs.GameVariant
import com.bedalton.creatures.common.structs.isC1e

/**
 * Converts Pose data into the index into the sprite that should render it
 */
object PoseToSpriteIndex {

    /**
     * Return which head sprite frame matches the head values within the pose
     */
    fun getHeadSpriteIndex(pose: Pose): Int {
        return getHeadSpriteIndex(
            variant = pose.variant,
            headFacing = pose.headFacing,
            tilt = pose.head,
            mood = pose.mood ?: Mood.NORMAL,
            eyesClosed = pose.eyesClosed ?: false
        )
    }

    /**
     * Return which head sprite frame matches this facing, tilt, mood and eyes closed status
     */
    fun getHeadSpriteIndex(
        variant: GameVariant,
        headFacing: PoseFacing,
        tilt: Tilt,
        mood: Mood,
        eyesClosed: Boolean,
    ): Int {

        // Make sure mood can be rendered in this variant
        mood.assertIsValidForVariant(variant)

        // Head is funny, and needs special handling
        return if (variant.isC1e)
        // Get for C1/C2
            calculateC1eHeadSpriteIndex(
                variant,
                headFacing,
                tilt,
                mood.int,
                eyesClosed
            )
        else {
            // Get for [CV, C3, DS]
            calculateC2eHeadSpriteIndex(
                headFacing,
                tilt,
                mood.int,
                eyesClosed
            )
        }.apply {
            // Log if head index is less than zero (i.e. could not be calculated)
            if (this < 0) {
                throw PoseException("Failed to calculate head pose: Variant:$variant; FacingDirection:$headFacing; Tilt: $tilt; Mood: $mood; EyesClosed: $eyesClosed")
            }
        }
    }

    /**
     * Return which head sprite frame matches this facing, tilt, mood and eyes closed status
     */
    fun getHeadSpriteIndex(
        variant: GameVariant,
        headFacing: PoseFacing,
        tilt: Tilt,
        mood: Int,
        eyesClosed: Boolean,
    ): Int {
        val moodActual = Mood.fromInt(mood)
            ?: throw PoseException("Invalid mood int $mood; Expected 0..3 for C1, 0..5 for C2,C3,DS; 0..11 for CV")
        return getHeadSpriteIndex(variant, headFacing, tilt, moodActual, eyesClosed)

    }

    /**
     * Calculate the pose specifically for earlier games
     */
    private fun calculateC1eHeadSpriteIndex(
        variant: GameVariant,
        facing: PoseFacing,
        tilt: Tilt,
        mood: Int,
        eyesClosed: Boolean,
    ): Int {
        val base = when (facing) {
            PoseFacing.VIEWER_RIGHT -> 0
            PoseFacing.VIEWER_LEFT -> 4
            PoseFacing.FRONT -> 8
            PoseFacing.BACK -> 9
            else -> throw PoseException("Cannot determine head sprite index with non-integer facing")
        }

        val baseOffset = if (base < 8) base + tilt.intOrDefault else base

        return if (variant == GameVariant.C1) {
            val eyesMod = if (eyesClosed) {
                13
            } else {
                0
            }
            // C1 has head back in pose 9, so for moods other than neutral, we add 1 to offset by head back sprite
            val moodMod = if (baseOffset == 8 && mood > 0) mood + 1 else 0
            baseOffset + eyesMod + moodMod
        } else {
            baseOffset + (mood * 20) + (if (eyesClosed) 10 else 0)
        }
    }

    /**
     * Calculate head sprite index for CV+ games
     */
    private fun calculateC2eHeadSpriteIndex(
        facing: PoseFacing,
        tilt: Tilt,
        mood: Int,
        eyesClosed: Boolean,
    ): Int {

        val base = when (facing) {
            PoseFacing.VIEWER_RIGHT -> 0
            PoseFacing.VIEWER_LEFT -> 4
            PoseFacing.FRONT -> 8
            PoseFacing.BACK -> 12
            else -> throw PoseException("Cannot determine head sprite index with non-specific facing")
        }

        val calculated = base + tilt.intOrDefault
        val eyesClosedMod = if (eyesClosed) 16 else 0
        val moodOffset = mood * 32
        return calculated + eyesClosedMod + moodOffset
    }

    /**
     * Gets the sprite index for a given part and pose object
     */
    fun getSpriteIndex(pose: Pose, part: Char): Int? {
        val tilt = when (part.lowercaseChar()) {
            'a' -> return getHeadSpriteIndex(pose)
            'b' -> return pose.body.getSpriteIndex(pose.variant, pose.bodyFacing)
            'o', 'p' -> return getEarSpriteIndex(getHeadSpriteIndex(pose))
            in ('a' .. 'l') -> pose[part]
                ?: throw PoseException("Missing pose for required part $part")
            'm', 'n', 'q' -> pose[part]
                ?: return null
            else -> throw PoseException("Unexpected part '$part' requested. expected part 'a'..'q'")
        }
        return tilt.getSpriteIndex(pose.variant, pose.bodyFacing)
    }

    /**
     * Gets the sprite index for the ears given the heads actual sprite index
     * Conversion is not strictly straight forward, as the ear sprites do not match one to one with head sprites
     * Ear sets are reused by different head moods
     */
    fun getEarSpriteIndex(headSpriteIndex: Int): Int {
        val index = headSpriteIndex % 16
        val earsIndex = when (headSpriteIndex) {
            // Neutral
            in 0..31 -> EARS_ANGRY
            // HAPPY
            in 32..63 -> EARS_ANGRY
            // SAD
            in 64..95 -> EARS_DROOPY
            // ANGRY
            in 96..127 -> EARS_ANGRY
            // Scared
            in 128..159 -> EARS_PRICKED
            // Sleepy
            in 160..191 -> EARS_DROOPY
            // Very Sleepy
            in 192 .. 223 -> EARS_DROOPY
            // Very Happy
            in 224 .. 255 -> EARS_PRICKED
            // Mischievous
            in 256 .. 287 -> EARS_NORMAL
            // Scared
            in 288 .. 319 -> EARS_DROOPY
            // Ill
            in 320 .. 351 -> EARS_DROOPY
            // Hungry
            in 352 .. 383 -> EARS_NORMAL

        //  === UNKNOWN ALL SET TO EARS ANGRY ACCORDING TO SOURCE == //
            // Neutral 2 == No Entry In source
            in 384 .. 415 -> EARS_ANGRY // No entry in source
            // Happy 2
            in 416 .. 447 -> EARS_ANGRY // No entry in source
            // Crying 1
            in 448 .. 479 -> EARS_ANGRY // No entry in source
            // Crying 2
            in 480 .. 511 -> EARS_ANGRY // No entry in source
            // Wide mouth
            in 512 .. 543 -> EARS_ANGRY // No entry in source
            in 544 .. 575 -> EARS_ANGRY // No entry in source
            else -> EARS_ANGRY
        }
        val offset = earsIndex * 16
        return index + offset
    }
}