@Suppress("unused")
internal object ForgeConfig {

    private var cachedConfig: ForgeConfigData? = null
    private var tempCachedconfig: ForgeConfigData? = null

    private var onLoadListeners: MutableList<(ForgeConfig) -> Unit> = mutableListOf()

    private var emptyConfig = ForgeConfigData()


    init {
        CoroutineScope(Job()).launch {
            try {
                cachedConfig = getConfigLoading()
                for (listener in onLoadListeners) {
                    listener(ForgeConfig)
                }
                onLoadListeners.clear()
            } catch (e: Exception) {
                Log.e("Failed to get cached config; ${e.formatted(true)}")
            }
        }

    }

    private const val LAST_AGENT_DIRECTORY_DELIMITER = "::::"

    internal fun addOnInitialLoadListener(listener: (ForgeConfig) -> Unit) {
        (cachedConfig ?: tempCachedconfig)?.let {
            listener(ForgeConfig)
            return
        }
        onLoadListeners.add(listener)
    }

    private suspend inline fun get(cached: Boolean = true, get: ForgeConfigData.() -> String?): String? {
        return getConfigLoading(cached).get()
    }

    private suspend inline fun <T> getValue(cached: Boolean = true, get: ForgeConfigData.() -> T?): T? {
        return getConfigLoading(cached).get()
    }

    private suspend inline fun set(cached: Boolean = true, work: ForgeConfigData.() -> ForgeConfigData?): Boolean {
        return try {

            val currentConfig = getConfigLoading(cached)

            val config = currentConfig
                .work()
                ?: return true

            if (cachedConfig == config || config == emptyConfig) {
                return true
            }

            cachedConfig = config
            ConfigLoader.saveConfig(config)
        } catch (e: Exception) {
            Log.e("ForgeConfig::set() failed; ${e.formatted(true)}")
            false
        }
    }

