    suspend inline fun setDefaultEggName(root: String, state: ForgeState, egg: EggData, eggName: String) = set {
        if (eggName.isBlank() || eggName.startsWith(':')) {
            return@set null
        }
        val breedNames = defaultBreedNames.toMutableMap()
        val key = getDefaultBreedKey(root, state, egg)
        if (breedNames[key] == eggName) {
            return@set null
        }
        breedNames[key] = eggName
        this.copy(defaultBreedNames = breedNames)
    }

