    private fun ForgeConfigData.alterProjectConfig(
        state: ForgeState,
        transform: ProjectConfig.() -> ProjectConfig?,
    ): ForgeConfigData {
        val projectFolder = state.projectFolder
            ?: return this
        val key = getProjectDataKey(projectFolder)
        val config = projectData[key] ?: ProjectConfig(
            forgeState = state
        )
        val projectData = projectData.toMutableMap()
        val newData = config.transform()

        if (newData == null) {
            projectData.remove(key)
        } else {
            projectData[key] = newData
        }
        return copy(
            projectData = projectData
        )
    }

    private fun ForgeConfigData.alterProjectConfig(
        root: String?,
        transform: ProjectConfig.() -> ProjectConfig?,
    ): ForgeConfigData {

        val projectFolder = root
            ?: return this

        val key = getProjectDataKey(projectFolder)

        val config = projectData[key]
            ?: return this

        val projectData = projectData.toMutableMap()

        val newData = config.transform()

        if (newData == null) {
            projectData.remove(key)
        } else {
            projectData[key] = newData
        }

        return copy(
            projectData = projectData
        )
    }

