    suspend inline fun setProjectData(state: ForgeState, onlyIncrementedState: Boolean = true) = set(cached = false) {
        if (projectSettingsCacheDisabled) {
            return@set if (projectData.isNotEmpty()) {
                copy(projectData = emptyMap())
            } else {
                null
            }
        }

        val root = state
            .projectFolder
            ?.nullIfEmpty()
            ?: return@set null

        val key = getProjectDataKey(root)

        val oldState = projectData[key]

        if (onlyIncrementedState && oldState != null && oldState.forgeState.stateId >= state.stateId && state.stateId > 1) {
            return@set null
        }

        var eggId = 1
        val previouslySelectedEggId = state.selectedEgg.id
        var selectedEgg: EggData? = null

        val eggs = state.eggs.map { oldEgg ->
            val id = eggId++
            val egg = oldEgg.copy(id = id)
            if (oldEgg.id == previouslySelectedEggId) {
                selectedEgg = egg
            }
            egg
        }.nullIfEmpty()
            ?: listOf(EggData())

        var stateScrubbed = state.copy(
            attFiles = null,
            spriteFiles = null,
            eggs = eggs,
            selectedEgg = selectedEgg ?: eggs.first()
        )

        if (previousGenomeListDisabled) {
            stateScrubbed = stateScrubbed.copy(
                additionalGenomes = emptyMap()
            )
        }

        if (stateScrubbed == oldState?.forgeState) {
            return@set null
        }

        var newState = oldState?.copy(
            forgeState = stateScrubbed
        ) ?: ProjectConfig(
            forgeState = stateScrubbed
        )

        for (egg in state.eggs) {
            val genomePath = egg.baseGenomeFile
                ?.filepath
                ?: continue

            newState = newState.withCachedGenomeNames(egg.baseGenomeFile)
            newState = newState.withCachedGenomeNames(egg.fatherGenomeFile)
            newState = newState.withCachedGenomeNames(egg.motherGenomeFile)

            val eggName = egg.eggName?.nullIfAutoNameNullOrBlank()
                ?: continue

            newState = newState.copy(
                genomeEggNames = newState.genomeEggNames.with(genomePath.lowercase(), eggName),
            )
        }

        // Do not cache files lists as they could change between loads

        val allGenomes: Set<String> = if (previousGenomeListDisabled) {
            emptySet()
        } else {
            (previousGenomes + state.additionalGenomes.map { it.value }).toSet()
        }

        copy(
            projectData = projectData.with(key, newState),
            previousGenomes = allGenomes
        )
    }

    private fun ProjectConfig.withCachedGenomeNames(genome: GenomeFile?): ProjectConfig {
        if (genome == null) {
            return this
        }

        val name = genome.filename
            .nullIfAutoNameNullOrBlank()
            ?: return this

        val path = genome
            .filepath
            .nullIfEmpty()
            ?: return this

        return copy(
            lastGenomeNames = lastGenomeNames.with(path, name),
        )
    }

    private fun getProjectDataValue(state: ForgeConfigData, root: String?): ForgeState? {
        if (root == null) {
            return null
        }

        if (state.projectSettingsCacheDisabled) {
            return null
        }

        return state.projectData[getProjectDataKey(root)]
            ?.forgeState
            // Do not keep files lists as they can change between loads
            ?.copy(
                lastStateId = korAtomic(0),
                attFiles = null,
                spriteFiles = null,
            )
    }

