        getValue get@{
            val root = projectRoot
                ?: return@get null
            val projectKey = getProjectDataKey(root)
            projectData[projectKey]?.get() ?: default
        }

    suspend fun setPreviousGenomeListDisabled(disabled: Boolean) = set(cached = false) {
        if (previousGenomeListDisabled == disabled) {
            if (disabled && previousGenomes.isEmpty()) {
                return@set null
            }
        }
        if (disabled) {
            withClearedGenomes()
                .copy(
                    previousGenomeListDisabled = disabled,
                    projectData = projectData
                )
        } else {
            copy(previousGenomeListDisabled = disabled)
        }
    }

    suspend fun clearAllPreviousGenomes() = set {
        withClearedGenomes()
    }


    private fun ForgeConfigData.withClearedGenomes(): ForgeConfigData {
        val projectData = projectData.mapValues { (_, value) ->
            value.copy(
                forgeState = value.forgeState.copy(
                    additionalGenomes = emptyMap()
                )
            )
        }.toMap()
        return copy(
            projectData = projectData,
            previousGenomes = emptySet()
        )
    }

    suspend fun clearProjectGenomes(root: String?) = alterProjectDataNotNull(root) {
        copy(
            additionalGenomes = emptyMap()
