    private suspend inline fun alterProjectDataNotNull(
        root: String?,
        transform: ForgeState.() -> ForgeState?,
    ) = set {
        if (root == null) {
            return@set null
        }

        val projectData = projectData.toMutableMap()
        val key = getProjectDataKey(root)

        val config = projectData[key]
            ?: return@set null

        val data: ForgeState = config
            .forgeState
            .transform()
            ?: return@set null

        projectData[key] = config.copy(
            forgeState = data
        )

        copy(
            projectData = projectData.toMap()
        )
    }

    internal fun forceReload() {
        tempCachedconfig = cachedConfig
        this.cachedConfig = null
        GlobalScope.launch {
            getConfigLoading(cached = false).also {
                if (cachedConfig == null) {
                    cachedConfig = it
                }
                tempCachedconfig = null
            }
        }
    }


    internal suspend fun forceReloadSync() {
        tempCachedconfig = cachedConfig
        this.cachedConfig = null
        getConfigLoading(cached = false).also {
            if (cachedConfig == null) {
                cachedConfig = it
            }
            tempCachedconfig = null
        }
    }

    private suspend inline fun alterProjectDataOrDelete(
        root: String?,
        transform: ForgeState.() -> ForgeState?,
    ) = set {

        if (root == null) {
            return@set null
        }

        val projectData = projectData.toMutableMap()
        val key = getProjectDataKey(root)

        val config = projectData[key]

        val originalData: ForgeState = config?.forgeState
            ?: return@set null

        val data = originalData.transform()


        // If transform returned null,
        // we remove the current data
        if (data == null) {
            projectData.remove(key)
        } else {
            projectData[key] = config.copy(
                forgeState = data
            )
        }

        copy(
            projectData = projectData.toMap()
        )
    }


    suspend inline fun getEggName(projectRoot: String?, genomePath: String) = getProjectConfigValue(projectRoot) {
        genomeEggNames[genomePath.lowercase()]
    }

    suspend inline fun getGenomeName(projectRoot: String?, genomePath: String) = getProjectConfigValue(projectRoot) {
        lastGenomeNames[genomePath.lowercase()]
    }

    fun pushProjectState(state: ForgeState, onlyIncrementedState: Boolean = true) = launchCatching {
        setProjectData(state, onlyIncrementedState)
    }

}


internal expect object ConfigLoader {
    internal val loadedOnce: Boolean
    suspend inline fun getConfigLoading(cached: Boolean = true): ForgeConfigData
    suspend inline fun saveConfig(config: ForgeConfigData): Boolean
}

private fun getProjectConfig(state: ForgeConfigData, projectRoot: String?): ProjectConfig? {
    if (projectRoot == null) {
        return null
    }
    if (state.projectSettingsCacheDisabled) {
        return null
    }
    val key = getProjectDataKey(projectRoot)
    return state.projectData[key]
}