package com.bedalton.creatures.agents.pray.compiler.pray.internal

import com.bedalton.common.coroutines.checkCancelled
import com.bedalton.common.coroutines.rethrowIfCancellationException
import com.bedalton.common.util.nullIfEmpty
import com.bedalton.creatures.agents.pray.compiler.NEWLINE_REGEX
import com.bedalton.creatures.agents.pray.compiler.REMOVER_SCRIPT_REGEX
import com.bedalton.creatures.agents.pray.compiler.SCRIPT_TAG_REGEX
import com.bedalton.creatures.agents.pray.compiler.caos2pray.internal.combineRemoverScripts
import com.bedalton.creatures.agents.pray.compiler.data.*
import com.bedalton.creatures.agents.pray.compiler.pray.PrayParseException
import com.bedalton.creatures.agents.util.RelativeFileSystem
import com.bedalton.log.*
import kotlinx.coroutines.CoroutineScope

/**
 * Combines removal scripts from nested scripts as needed
 */
internal suspend fun combineRscr(coroutineScope: CoroutineScope, fs: RelativeFileSystem, block: CompilerPrayBlock): CompilerPrayBlock {

    Log.i2With(LOG_PROGRESS) { "Combining RSCR in block: ${block.blockTag} \"${block.blockName}\"" }
    // Check if block has tags, if not, nothing to do. Return
    if (block !is CompilerBlockWithTags) {
        return block
    }
    val outTags = try {
        mergeRscrFromTags(coroutineScope, fs, block.tags.toList())
    } catch (e: Exception) {
        // Do not hold onto cancellation exceptions
        e.rethrowIfCancellationException()
        throw PrayParseException(-1, "Failed to parse scripts for merge RSCR.")
    }.toTypedArray()

    // Return a new block with the remover scripts combined
    return when (block) {
        is CompilerAgentBlock -> block.copy(
            tags = outTags
        )

        is CompilerEggBlock -> block.copy(
            tags = outTags
        )

        is CompilerGeneralBlockWithTags -> block.copy(
            tags = outTags
        )
    }
}

internal suspend fun mergeRscrFromTags(
    coroutineScope: CoroutineScope,
    fs: RelativeFileSystem,
    tags: List<Tag<*>>
): List<Tag<*>> {

    // Find all non-script tags and set as out
    var outTags: MutableList<Tag<*>> = tags
        .filterNot { tag ->
            tag is Tag.StringTag && (SCRIPT_TAG_REGEX.matches(tag.tag) || tag.tag.lowercase() == "remove script")
        }
        .toMutableList()

    // Find all script tags by subtracting all non-script tags
    val scriptTags: List<Tag<*>> = tags.subtract(outTags.toSet()).toList()

    // Run combiner which returns scripts without removers and a script of all removers combined
    val (scripts, removerScript) = combineRemoverScripts(scriptTags.map { tag ->
        if (tag.tag.lowercase() == "remove script") {
            "rscr " + (tag as Tag.StringTag).value
        } else {
            (tag as Tag.StringTag).value
        }
    }.toTypedArray())

    // Adds the updated script tags, having removed them earlier
    for (i in scriptTags.indices) {
        outTags.add(
            (scriptTags[i] as Tag.StringTag).copy(
                value = scripts[i].trim()
            )
        )
    }

    // Find old remover script
    val oldRemoverScriptTag = outTags.filter { tag ->
        REMOVER_SCRIPT_REGEX.matches(tag.tag)
    }.nullIfEmpty()

    // Remove old remover script if it exists
    if (oldRemoverScriptTag != null) {
        outTags = outTags.subtract(oldRemoverScriptTag).toMutableList()
    }

    // Combine old and new remover scripts
    val combinedRemoveScript = (if (oldRemoverScriptTag != null)
        (combineRemoverScripts(oldRemoverScriptTag.map {
            // Ensure coroutine is not cancelled
            coroutineScope.checkCancelled()

            (if (it is Tag.LinkTag) {
                fs.readAsText(it.value)
            } else {
                it.value as String
            }).let { script ->
                if (script.startsWith("rscr", ignoreCase = true)) {
                    script
                } else {
                    "rscr $script"
                }
            }
        }.toTypedArray()).second + "\n\n" + removerScript).trim()
    else {
        removerScript.trim()
    })

    // Add remover script if non-empty
    if (combinedRemoveScript.isNotBlank()) {
        val removerScriptTag = Tag.StringTag(
            lineNumber = oldRemoverScriptTag?.minByOrNull { it.lineNumber }?.lineNumber ?: -1,
            startIndex = -1,
            endIndex = -1,
            tagRange = TextValue(
                text = "Remove script",
                lineNumber = -1,
                startIndex = -1,
                endIndex = -1,
            ),
            value = TextValue(
                lineNumber = -1,
                startIndex = -1,
                endIndex = -1,
                text = combinedRemoveScript.trim().replace(NEWLINE_REGEX, "\n")
            )
        )
        outTags.add(removerScriptTag)
    } else {
        Log.i2If(LOG_VERBOSE) { "Remove Script was empty with combine RSCR" }
    }
    return outTags
}