package com.bedalton.creatures.sprite.util

import com.bedalton.creatures.sprite.util.ColorEncoding.X_565
import korlibs.image.color.RGBA

internal fun swapAndRotateC2e(
    encoding: ColorEncoding,
    palette: Array<RGBA>,
    red: Int?,
    green: Int?,
    blue: Int?,
    swap: Int?,
    rotation: Int?
): ColorPalette {

    if (isDefaultColorValues(red, green, blue, swap, rotation)) {
        return encoding.toRgbWithTables(black)
    }

    // Get translation function
    val translate = createC2eSwapAndRotateFunction(red, green, blue, swap, rotation)

    // Use same first color as it will determine transparency of pure black
    val out = arrayOf(palette[0]) + palette.drop(1).map(translate).toTypedArray()

    // Create palette with colors
    return ColorPalette(encoding, out, true)
}

internal fun createC2eSwapAndRotateFunction(
    transform: PaletteTransform
): (color: RGBA) -> RGBA = createC2eSwapAndRotateFunction(
    transform.red,
    transform.green,
    transform.blue,
    transform.swap,
    transform.rotation
)

internal fun createC2eSwapAndRotateFunction(
    red: Int?,
    green: Int?,
    blue: Int?,
    swap: Int?,
    rotation: Int?
): (color: RGBA) -> RGBA {
    // Color tints
    val redTint = (red ?: 128) - 128
    val greenTint = (green ?: 128) - 128
    val blueTint = (blue ?: 128) - 128


    // Swap
    val swapNotNull = swap ?: 128
    val absoluteSwap = if (swapNotNull >= 128) swapNotNull - 128 else 128 - swapNotNull
    val invertedSwap = 127 - absoluteSwap

    val rotate = rotationFunction(rotation ?: 128)

    var temp: Array<Int>

    return color@{ color: RGBA ->

        if (color.r == 0 && color.g == 0 && color.b == 0) {
            return@color color
        }
        // Clamp between 0 .. 255
        val r = (color.r + redTint).bound()
        val g = (color.g + greenTint).bound()
        val b = (color.b + blueTint).bound()

        // Rotate colors
        temp = rotate(r, g, b)
        val rotatedR = temp[0]
        val rotatedG = temp[1]
        val rotatedB = temp[2]

        // Swap Red and Blue
        val swappedR = (((absoluteSwap * rotatedB) + (invertedSwap * rotatedR)) shr 7).bound()
        val swappedB = (((absoluteSwap * rotatedR) + (invertedSwap * rotatedB)) shr 7).bound()
        if (swappedR == 0 &&  rotatedG == 0 &&  swappedB == 0) {
            X_565.blackishRGBA
        } else {
            RGBA(swappedR, rotatedG, swappedB)
        }
    }
}

internal fun swapAndRotateToIntC2e(
    red: Int?,
    green: Int?,
    blue: Int?,
    swap: Int?,
    rotation: Int?,
    encoding: ColorEncoding,
): (red: Int, green: Int, blue: Int) -> Int {
    // Color tints
    val redTint = (red ?: 128) - 128
    val greenTint = (green ?: 128) - 128
    val blueTint = (blue ?: 128) - 128


    // Swap
    val swapNotNull = swap ?: 128
    val absoluteSwap = if (swapNotNull >= 128) swapNotNull - 128 else 128 - swapNotNull
    val invertedSwap = 127 - absoluteSwap

    val rotate = rotationFunction(rotation ?: 128)

    var temp: Array<Int>

    val toInt = encoding.toInt
    val blackish = encoding.blackish
    return toInt@{ thisRed, thisGreen, thisBlue ->
        if (red == 0 && green == 0 && blue == 0) {
            return@toInt 0
        }
        // Clamp between 0 .. 255
        val r = (thisRed + redTint).bound()
        val g = (thisGreen + greenTint).bound()
        val b = (thisBlue + blueTint).bound()

        // Rotate colors
        temp = rotate(r, g, b)
        val rotatedR = temp[0]
        val rotatedG = temp[1]
        val rotatedB = temp[2]

        // Swap Red and Blue
        val swappedR = (((absoluteSwap * rotatedB) + (invertedSwap * rotatedR)) shr 7).bound()
        val swappedB = (((absoluteSwap * rotatedR) + (invertedSwap * rotatedB)) shr 7).bound()
        toInt(swappedR, rotatedG, swappedB).let {
            if (it == 0) {
                blackish
            } else {
                it
            }
        }
    }
}

private fun rotationFunction(rotation: Int): (r: Int, g: Int, b: Int) -> Array<Int> {
    val temp: Array<Int> = Array(3) { 0 }
    // Rotation
    val absoluteRotation = if (rotation >= 128) rotation - 128.0 else 128.0 - rotation
    val invertedRotation = 127.0 - absoluteRotation
    return if (rotation < 128) {
        { r: Int, g: Int, b: Int ->
            temp[0] = (((absoluteRotation * b) + (invertedRotation * r)).toInt()) shr 7
            temp[1] = (((absoluteRotation * r) + (invertedRotation * g)).toInt()) shr 7
            temp[2] = (((absoluteRotation * g) + (invertedRotation * b)).toInt()) shr 7
            temp
        }
    } else if (rotation > 128) {
        { r: Int, g: Int, b: Int ->
            temp[0] = (((absoluteRotation * g) + (invertedRotation * r)).toInt()) shr 7
            temp[1] = (((absoluteRotation * b) + (invertedRotation * g)).toInt()) shr 7
            temp[2] = (((absoluteRotation * r) + (invertedRotation * b)).toInt()) shr 7
            temp
        }
    } else {
        { r: Int, g: Int, b: Int ->
            temp[0] = r
            temp[1] = g
            temp[2] = b
            temp
        }
    }
}

fun Int.bound(): Int {
    return if (this < 0) {
        0
    } else if (this > 255) {
        255
    } else {
        this
    }
}