package com.bedalton.creatures.caos.collectors

import com.bedalton.common.ast.structs.HasRange
import kotlinx.serialization.Serializable
import kotlin.js.JsExport
import kotlin.js.JsName

@JsExport
@Serializable
data class ClosestItemResult<T : HasRange>(
    @JsName("closest")
    val closest: T,
    @JsName("previous")
    val previous: Array<CaosParserItem.CommandToken>,
) {
    override fun equals(other: Any?): Boolean {
        if (this === other) return true
        if (other !is ClosestItemResult<*>) return false

        if (closest != other.closest) return false
        if (!previous.contentEquals(other.previous)) return false

        return true
    }

    override fun hashCode(): Int {
        var result = closest.hashCode()
        result = 31 * result + previous.contentHashCode()
        return result
    }
}