import com.creaturesforge.application.state.*
import com.creaturesforge.application.ui.fileOf
import com.creaturesforge.application.ui.html.get
import com.creaturesforge.application.ui.html.getOrNull
import com.creaturesforge.application.util.jsOb
import kotlinx.browser.document
import kotlinx.coroutines.*
import org.w3c.dom.HTMLButtonElement
import org.w3c.dom.HTMLElement
import org.w3c.dom.HTMLInputElement
import tauri.dialog.open
import tauri.os.platform

internal sealed class RootInput(element: HTMLElement, private val kind: String): Validatable {

    private var mRoot: String? = null

    private lateinit var dispatch: Dispatch<FAction>

    private val mRootLabel: HTMLInputElement = element.get("[data-id='root-path']")

    private val selectRootButton: HTMLButtonElement = element.get("[data-id='root-open']")

    private val refreshRootButton: HTMLButtonElement = element.get("[data-id='refresh-root-button']")

    private val clearRootButton: HTMLButtonElement? = element.getOrNull("[data-id='clear-root-button']")

    private var projectRoot: String? = null

    private var root: String?
        get() = mRoot
        set(value) {
            mRoot = value
            mRootLabel.setAttribute("data-path", value ?: "")
        }

    protected abstract val openTitle: String

    protected abstract suspend fun getLastRootFromConfig(projectRoot: String?): String?

    protected abstract fun createSetterAction(path: String?): FAction

    init {
        ForgeStore.subscribe { state, dispatch ->
            projectRoot = state.projectFolder
            this.dispatch = dispatch
            val root = getRootFromState(state)
            updateRoot(root)
        }
        Log.i("Initializing $kind root button in parent: " + (element.closest("[data-page]")?.getAttribute("data-page") ?: element.parentElement?.toString() ))
        mRootLabel.addEventListener("click", {
            selectRoot()
        })
        initClickHandlers()
        @Suppress("LeakingThis")
        addControl(this)
    }


    protected abstract fun getRootFromState(state: ForgeState): String?


    private fun initClickHandlers() {
        refreshRootButton.onclick = {
            requestRefresh()
        }

        selectRootButton.onclick = {
            selectRoot()
        }

        clearRootButton?.onclick = {
            GlobalScope.launch {
                clearRootInternal()
            }
        }
    }

    protected open fun requestRefresh() {
        dispatch(RequestRefreshAllFiles)
    }

    private fun selectRoot() {
        CoroutineScope(Job()).launch {
            try {
                selectRootAsync()
            } catch (e: Exception) {
                Log.e("Failed to select $kind root; {${e.formatted(true)}")
            }
        }
    }


    private suspend fun selectRootAsync() {
        val root = try {
            requestRoot()
                ?: return
        } catch (e: Exception) {
            e.rethrowCancellationException()
            Log.e("${className}.selectRoot() failed; ${e.formatted(true)}")
            return
        }
        if (mRootLabel.value != root) {
            dispatch(createSetterAction(root))
        }
        try {
            updateRoot(root)
        } catch (e: Exception) {
            Log.e("${className}.selectRoot()->updateRoot; failed; ${e.formatted(true)}")
        }
    }

    private fun updateRoot(newRoot: String?) {
        if (root == newRoot) {
            return
        }
        root = newRoot
        if (newRoot.isNullOrBlank()) {
            document.body!!.setAttribute("data-has-$kind-root", "false")
            mRootLabel.value = ""
            return
        }
        document.body!!.setAttribute("data-has-$kind-root", "true")
        fitPathToField(newRoot)
    }

    private fun fitPathToField(newRoot: String) {
        updateShortestPaths(newRoot)
    }

    private suspend fun requestRoot(): String? {
        val defaultPath = root
            ?.nullIfVirtual()
            ?: getLastRootFromConfig(projectRoot)
            ?: if (platform().await() == "linux") {
                "~/"
            } else {
                null
            }

        val response = open(jsOb {
            this.directory = true
            this.title = openTitle
            this.recursive = true
            this.multiple = false
            this.defaultPath = defaultPath
        }).await()

        if (response == null) {
            Log.i { "No $kind root selected" }
            return null
        }
        val directory: String? = fileOf(response)

        Log.i { "Directory: $directory; Response: " + JSON.stringify(response) }
        if (directory == null) {
            Log.e { "Directory was null after response was non-null; " + JSON.stringify(response) }
            return null
        }
        onRootSet(projectRoot, directory)
        return directory
    }

    protected open suspend fun onRootSet(projectRoot: String?, directory: String) {

    }

    private suspend fun clearRootInternal() {
        onClearRoot(mRoot)
        mRoot = null
        dispatch(createSetterAction(null))
        updateRoot(null)
    }

    protected open suspend fun onClearRoot(oldRoot: String?) {
    }

    companion object {
        private val USER_PATH_REGEX =
            "^(?:.:\\|.:/|/[^/]+?)?users[\\\\/]([^\\\\/]+)[\\\\/]".toRegex(RegexOption.IGNORE_CASE)

        private val pastPaths = mutableSetOf<String>()

        private const val MAX_LABEL_LENGTH = 34
        private const val MAX_LABEL_LENGTH_WITH_CLEAR_BUTTON = 28

        private val allControls: MutableSet<RootInput> = mutableSetOf()

        private fun addControl(input: RootInput) {
            allControls.add(input)
        }

        private fun updateShortestPaths(newRoot: String) {
            pastPaths.add(newRoot)
            updateShortestPaths()
        }

        private fun updateShortestPaths() {
            for (control in allControls) {
                val newRoot = control.root
                    ?: continue
                val path = formatPath(newRoot)
                val paths = PathUtil.shortestPaths(pastPaths, minDepth = 1)
                var out = path//paths[newRoot] ?: path
                Log.i(LOG_DEBUG) { "NewRoot: $newRoot; ShortPath: $path; Out: $out; Paths: [${paths.keys.joinToString { "\"$it\"" }}]" }
                val maxLength = if (control.clearRootButton != null) {
                    MAX_LABEL_LENGTH_WITH_CLEAR_BUTTON
                } else {
                    MAX_LABEL_LENGTH
                }
                if (out.length >= maxLength) {
                    out = out.substring(out.length - maxLength)
                }
                control.mRootLabel.value = out
            }
        }

        private fun formatPath(pathRaw: String): String {
            return pathRaw.replace(USER_PATH_REGEX, "~/")
        }
    }

    override fun isValid(): Boolean {
        return root != null
    }

    private fun String.nullIfVirtual(): String? {
        return if (lowercase().startsWith(agentScheme.lowercase())) {
            null
        } else {
            this
        }
    }

    override fun highlightErrors() {
        if (isValid()) {
            return
        }
        mRootLabel.closest(".validatable-input-container")?.setAttribute("data-is-valid", "false")
    }

}