@file:Suppress("unused")

package com.creaturesforge.application.ui.html

import org.w3c.dom.Element
import org.w3c.dom.HTMLElement
import org.w3c.dom.ParentNode

internal fun HTMLElement.hide() {
    hidden = true
    classList.add("hidden")
}

internal fun HTMLElement.unhide() {
    hidden = false
    classList.remove("hidden")
}

internal fun <T: HTMLElement> Element.getOrNull(selector: String): T? {
    return querySelector(selector).unsafeCast<T?>()
}

internal fun <T: HTMLElement> Element.get(selector: String): T {
    return querySelector(selector).unsafeCast<T?>()
        ?: throw NullPointerException("Failed to find element with selector: $selector")
}

internal fun <T:HTMLElement> ParentNode.all(selector: String, init: (node: T) -> Unit = {}): List<T> {
    return querySelectorAll(selector)
        .map { element: T ->
            init(element)
            element
        }
}

internal fun <T:Element> ParentNode.withRole(role: String): List<T> {
    return querySelectorAll("[data-role='$role']")
        .map { element: Element ->
            element.unsafeCast<T>()
        }
}

internal fun <R: Any> ParentNode.fromRole(role: String, transform: (element: HTMLElement) -> R): List<R> {
    return withRole<HTMLElement>(role)
        .map { element: HTMLElement ->
            transform(element)
        }
}