package com.bedalton.common.ast.serialization

import com.bedalton.common.ast.structs.Range
import com.bedalton.common.ast.structs.RangeWithIndexImpl

actual fun isRangeWithIndex(range: Range): Boolean {
    if (range is RangeWithIndexImpl) {
        return true
    }
    val dynamic = range.asDynamic();
    return dynamic.hasOwnProperty != null && dynamic.hasOwnProperty("startIndex") == true
}