package com.bedalton.creatures.caos.validation.internal

import com.bedalton.creatures.caos.collectors.CaosParserItem
import com.bedalton.creatures.caos.collectors.CommandCall
import com.bedalton.creatures.caos.collectors.ParseCancelledException
import com.bedalton.creatures.caos.libs.CaosVariant

internal fun collectErrors(
    variant: CaosVariant,
    isCaos2: Boolean,
    items: Array<CaosParserItem>,
    commandCalls: Array<CommandCall>,
    looseTokens: Array<CaosParserItem>,
    checkCancelled: () -> Unit,
): Array<CaosParserItem.ErrorVal> {

    val itemsWithoutErrors = items.filter { it !is CaosParserItem.ErrorVal }.toTypedArray()

    val whitespaceItems: Array<CaosParserItem> = itemsWithoutErrors
        .filterIsInstance<CaosParserItem.WhitespaceItem>()
        .toTypedArray()

    val errors: MutableList<CaosParserItem.ErrorVal> = items
        .filterIsInstance<CaosParserItem.ErrorVal>()
        .toMutableList()

    try {
        addCommandErrors(variant, isCaos2, commandCalls, errors, checkCancelled)
        addEqErrors(variant, itemsWithoutErrors, errors, checkCancelled)
        addLooseParserItemErrors(looseTokens, errors)
        addTokenFormatErrors(variant, commandCalls, errors, checkCancelled)
        addVarErrors(variant, itemsWithoutErrors, errors, checkCancelled)
        addVariantStringErrors(variant, itemsWithoutErrors, commandCalls, errors, checkCancelled)
        addWhitespaceErrors(variant, itemsWithoutErrors, whitespaceItems, errors)
    } catch (_: ParseCancelledException) {
    }
    return errors
        .sortedBy {
            it.textRange.startIndex
        }
        .distinct()
        .toTypedArray()

}