 package com.bedalton.vfs

import com.bedalton.common.exceptions.IOException

internal object FileSystemErrors {
    fun throwDeletingAFolderNotAFile(path: String): Nothing {
        throw IOException(
            "Cannot delete a directory with FileSystem.delete; " +
                    "Use FileSystem.deleteDirectory instead; " +
                    "Directory: <$path>"
        )
    }


    fun throwDeletingAFileNotAFolder(path: String): Nothing {
        throw IOException(
            "Cannot delete a file with FileSystem.deleteDirectory; " +
                    "Use FileSystem.delete instead; " +
                    "File: <$path>"
        )
    }
}