package com.bedalton.io.bytes

import DeflateFunctionOptions
import com.bedalton.common.exceptions.IOException
import com.bedalton.io.bytes.internal.rethrowIfCancellationException
import deflate
import inflate

actual object Compressor {
    /**
     * Compress bytes using ZLIB level should be 1-9; null/-1 for default compression level
     *
     * @param bytes bytes to compress
     * @param level compression amount, 1-9; null/-1 for default
     * @return compressed bytes
     */
    actual fun compress(bytes: ByteArray, level: Int?): ByteArray? {
        return try {
            if (level == 0) {
                return bytes
            }

            if (level != null && level != -1 && level !in 1..9) {
                throw IOException("Invalid ZLib compression value: $level; Expected 1..9, or  -1(use default)")
            }

            val actual = if (level == -1) {
                null
            } else {
                level
            }

            val opts = js("{}").unsafeCast<DeflateFunctionOptions>()
            opts.level = actual ?: COMPRESSOR_DEFAULT_COMPRESSION
            deflate(bytes.toUIntArray(), opts).toByteArray()
        } catch (e: Exception) {
            e.rethrowIfCancellationException()
//            Log.eIf(LOG_VERBOSE) { "Failed to compress byte array ${e.formatted(true)}" }
            null
        }
    }

    actual fun decompress(bytes: ByteArray): ByteArray? {
        return try {
            inflate(bytes.toUIntArray()).toByteArray()
        } catch (e: Exception) {
            e.rethrowIfCancellationException()
//            Log.eIf(LOG_VERBOSE) { "Failed to decompress byte array ${e.formatted(true)}" }
            null
        }
    }


    actual fun decompressThrowing(bytes: ByteArray): ByteArray {
        return inflate(bytes.toUIntArray()).toByteArray()
    }
}