package com.bedalton.creatures.sprite.util


fun progressCallbackWithIgnoredPass(
    callback: ((current: Int, total: Int) -> Boolean?)?,
    totalPasses: Int? = null
): ((pass: Int, current: Int, total: Int) -> Boolean?)? {
    if (callback == null) {
        return null
    }
    return if (totalPasses == null || totalPasses <= 1) {
        { _: Int, current: Int, total: Int ->
            callback(current, total)
        }
    } else {
        { pass: Int, current: Int, total: Int ->
            val offset = pass * total
            callback(current + offset, total * totalPasses)
        }
    }
}