package com.creaturesforge.application.interop

import com.creaturesforge.application.state.EggMode
import com.creaturesforge.application.state.ForgeStore
import com.creaturesforge.application.state.SetEggModeAction
import com.creaturesforge.application.state.invert
import com.creaturesforge.application.ui.pages.AppEggMode


/**
 * Send the given egg mode to tauri Rust backend
 * @param eggMode
 */
internal fun setEggModeInTauri(eggMode: EggMode) = tauriInvoke<Boolean>("set_egg_mode_in_tauri") {
    console.log("EggModeToTauri: $eggMode")
    this.eggMode = eggMode.name.lowercase()
    this.window_id = windowId
}.then {  }

/**
 * Send current egg mode to rust backend
 */
internal suspend fun updateEggModeInTauri()  {
    val eggMode = AppEggMode.getEggModeNotNull()
    setEggModeInTauri(eggMode)
}

/**
 * Toggles between single and multi egg modes
 */
internal suspend fun toggleEggMode() {
    toggleEggMode(AppEggMode.getEggModeNotNull())
}

/**
 * Toggles the given egg mode off
 *
 * @param eggMode egg mode to toggle off
 */
internal fun toggleEggMode(eggMode: EggMode) {
    val inverted = eggMode.invert()
    ForgeStore.dispatch(SetEggModeAction(inverted))
    AppEggMode.setEggMode(inverted)
}
