package com.bedalton.creatures.caos.libs

import kotlinx.serialization.Serializable
import kotlin.js.JsExport
import kotlin.js.JsName

/**
 * Represents a value in a values list
 */
@Serializable
@JsExport
@JsName("ValuesListValue")
data class CaosValuesListValue(
    @JsName("value")
    val value: String,
    @JsName("name")
    val name: String,
    @JsName("description")
    val description: String? = null,
    @JsName("beforeRegion")
    val beforeRegion: String? = null
) {
    @JsName("intValue")
    val intValue: Int? by lazy {
        val value = value.trim()
        if (value.startsWith(">") || value.startsWith("!"))
            value.substring(1).toIntOrNull()
        else
            value.toIntOrNull()
    }

    @JsName("negatedValue")
    val not by lazy {
        value.startsWith("!")
    }

    @JsName("greaterThanValue")
    val greaterThan by lazy {
        intValue != null && value.startsWith(">")
    }

}