package com.bedalton.creatures.breed.render.support.att

import com.bedalton.common.geometry.Point


/**
 * Parser for ATT files -> Data objects
 */
object AttFileParser {
    /**
     * Parses an ATT file from raw text to a data object, ensuring that there are the expected number of lines and points
     */
    fun parse(
        text: String,
        expectedLines: Int? = null,
        expectedPoints: Int? = null,
        fileName: String? = null
    ): AttFileData {
        // Break ATT into lines
        val rawLines = text
            .trimEnd()
            .split("[\n\r]+".toRegex())
            .filter { it.isNotBlank() }

        // Convert lines into points list
        val lines = (0 until (expectedLines ?: rawLines.size)).map { lineNumber ->
            val line = rawLines.getOrNull(lineNumber) ?: ""
            val intsRaw = line.trim().split("[ \t]+".toRegex())
            val points = (0 until (expectedPoints ?: (intsRaw.size / 2))).map { pointIndex ->
                val x = intsRaw.getOrNull(pointIndex * 2)?.toIntOrNull() ?: 0
                val y = intsRaw.getOrNull(pointIndex * 2 + 1)?.toIntOrNull() ?: 0
                Point(x, y)
            }
            AttFileLine(points = points)
        }
        return AttFileData(lines = lines, fileName = fileName)
    }
}