package com.creaturesforge.application.state

import com.bedalton.common.util.isNullOrEmpty
import com.bedalton.common.util.nullIfEmpty
import com.bedalton.log.Log

internal object StateValidator {


    @Suppress("MemberVisibilityCanBePrivate")
    fun getMissing(state: ForgeState, glyphsNotNull: Boolean): List<String> {
        val missing = mutableListOf<String>()

        val projectFolder = state.projectFolder

        if (projectFolder == null) {
            missing.add("project root")
        }

        if (state.outputBreedSlot == null) {
            missing.add("breed slot")
        }

        val eggs = EggFileNameUtil.fillInMissingGenomeFileNames(state.eggs)

        val notEmptyEggs = eggs.filterNot { isEmpty(it) }
        if (notEmptyEggs.isEmpty()) {
            missing.add("missing egg definitions")
        }

        for ((i,egg) in eggs.withIndex()) {
            validateEgg(i, egg, missing)
        }

        validateGlyph("male", state.maleGlyph, glyphsNotNull, missing)
        validateGlyph("female", state.femaleGlyph, glyphsNotNull, missing)

        val fs = vfs

        if (state.spriteFiles.isNullOrEmpty()) {
            missing.add("sprite files")
        }

        return missing.also {
            Log.i("Missing: $it")
        }
    }


    private fun validateEgg(i: Int, egg: EggData, missing: MutableList<String>) {
        val eggName = egg.eggName?.nullIfEmpty() ?: "Egg $i"
        if (egg.eggName.isNullOrBlank() || egg.baseGenomeFile == null) {
            if (egg.motherGenomeFile == null && egg.fatherGenomeFile == null) {
                return
            } else {
                missing.add("$eggName is incomplete")
            }
        }
        validateEggGenome(eggName, "base", egg.baseGenomeFile, missing)
        validateEggGenome(eggName, "mother", egg.motherGenomeFile, missing)
        validateEggGenome(eggName, "father", egg.fatherGenomeFile, missing)
    }

    private fun validateEggGenome(eggName: String, genomeSlot: String, genome: GenomeFile?, missing: MutableList<String>) {
        if (genome == null) {
            return
        }

        if (genome.filepath.isBlank()) {
            missing.add("$genome's $genomeSlot genome file path")
        }

        if (genome.filename.isBlank()) {
            missing.add("$eggName's $genomeSlot genome output filename")
        }
    }

    fun isEmpty(egg: EggData): Boolean {
        return egg.eggName.isNullOrBlank() && isEmpty(egg.baseGenomeFile) && isEmpty(egg.motherGenomeFile) && isEmpty(egg.fatherGenomeFile)
    }

    fun isEmpty(genome: GenomeFile?): Boolean {
        return genome == null || genome.filename.isBlank() || genome.filepath.isBlank()
    }

    private fun validateGlyph(glyphSlot: String, glyph: Glyph?, requireNotNull: Boolean, missing: MutableList<String>) {
        if (requireNotNull && glyph == null) {
            missing.add("$glyphSlot glyph")
        }
        if (glyph?.filename?.isBlank() == true) {
            missing.add("$glyphSlot glyph filename")
        }
    }
}