package com.bedalton.creatures.sprite.util

import com.bedalton.creatures.sprite.parsers.PixelIndices
import com.bedalton.creatures.sprite.util.ColorEncoding.C1
import korlibs.memory.clampUByte

class Int32Palette(private val encoding: ColorEncoding, opaqueBlack: Boolean) {

    private val colorTable by lazy {
        toInt32ColorTable()
    }

    val black = if (opaqueBlack) {
        (255 shl 24)
    } else {
        0
    }

    private val toInt32: (pixel: Int) -> Int by lazy {
        if (encoding.marker == -1) {
            val black = if (encoding == C1) {
                0
            } else {
                (255 shl 24)
            }
            { pixel: Int ->
                if (pixel == 0) {
                    black
                } else {
                    ColorPalette.C1TransparentBlack[pixel].value
                }
            }
        } else {
            { pixel: Int ->
                val red = (pixel and encoding.decodeBitMask.first) shr encoding.bitShifts.first
                val green = (pixel and encoding.decodeBitMask.second) shr encoding.bitShifts.second
                val blue = (pixel and encoding.decodeBitMask.third) shl encoding.bitShifts.third
                red.clampUByte() or (green.clampUByte() shl 8) or (blue.clampUByte() shl 16) or (255 shl 24)
            }
        }
    }

    operator fun get(int16Color: Int): Int {
        return try {
            colorTable[int16Color]
        } catch (e: IndexOutOfBoundsException) {
            if (int16Color == PixelIndices.TRANSPARENT_BLACK) {
                return 0
            }
            throw e
        }
    }

    private fun toInt32ColorTable(): IntArray {
        val colorCount = if (encoding.marker == -1) 256 else 65536
        val palette = IntArray(colorCount)
        palette[0] = black
        for (i in 1 until colorCount) {
            palette[i] = toInt32(i)
        }
        return palette
    }
}