package com.bedalton.creatures.caos.formatter

import com.bedalton.common.ast.structs.*
import com.bedalton.creatures.caos.collectors.CaosParserItem
import com.bedalton.creatures.caos.formatter.EditReason.COMMENT
import com.bedalton.creatures.caos.formatter.EditReason.FORMAT_CAOS2


internal fun Formatter.formatComment(item: CaosParserItem.Comment) {
    if (item.startCharacter == 0 || !state.indentComments) {
        state.out.append(item.text)
        return
    }
    val newTab = state.currentTab
    val lastItem = state.lastItem
    val start = if (lastItem != null) {
        if (lastItem is CaosParserItem.Spaces) {
            lastItem.start
        } else {
            lastItem.end
        }
    } else {
        item.start
    }
    if (lastItem?.text != newTab) {
        state.edits.add(
            TextEditImpl(
                RangeImpl(
                    start,
                    item.start
                ),
                newTab
            )
        )
        state.editReasons.add(COMMENT)
    }
    state.out
        .append(newTab)
        .append(item.text)
}

internal fun Formatter.formatCaos2(item: CaosParserItem.Caos2Comment) {
    val builder = StringBuilder("*# ")
    if (item.isTag) {
        builder.append(item.tag!!.replace("\\s\\s+", " "))
        builder.append(" = ")
    } else {
        builder.append(item.command).append(' ')
    }
    builder.append(item.values.filter { it.text.isNotBlank() }.joinToString(" ") { it.text }).trim()
    val newText = builder.toString()
    if (item.text != newText) {
        state.edits.add(
            TextEditImpl(
                RangeImpl(
                    item.textRange.start,
                    item.textRange.end
                ),
                newText = newText
            )
        )
        state.editReasons.add(FORMAT_CAOS2)
    }
    state.out
        .append(newText)
}
