@file:Suppress("unused")

package com.bedalton.creatures.sprite.parsers

import com.bedalton.creatures.sprite.util.PaletteTransform
import com.bedalton.creatures.sprite.util.SpriteType
import com.bedalton.io.bytes.ByteStreamReader

object SpriteParserAsync {

    fun parse(
        filenameOrExtension: String,
        reader: ByteStreamReader,
        paletteTransform: PaletteTransform? = null,
        progressChunkSize: Int = 1,
        progressCallback: ((current: Int, total: Int) -> Boolean?)? = null
    ): List<SpriteFrameAsync> {
        return parse(
            filenameOrExtension,
            reader,
            false,
            paletteTransform,
            progressChunkSize,
            progressCallback
        )
    }

    fun parse(
        filenameOrExtension: String,
        reader: ByteStreamReader,
        keepBlack: Boolean,
        paletteTransform: PaletteTransform? = null,
        progressChunkSize: Int = 1,
        progressCallback: ((current: Int, total: Int) -> Boolean?)? = null
    ): List<SpriteFrameAsync> {
        return ToSpriteFileParser.parse(
            filenameOrExtension,
            reader,
            keepBlack,
            paletteTransform,
            progressChunkSize,
            progressCallback
        ).getAsyncFrames()
    }

    fun parse(
        spriteType: SpriteType,
        reader: ByteStreamReader,
        paletteTransform: PaletteTransform? = null,
        progressChunkSize: Int = 1,
        progressCallback: ((current: Int, total: Int) -> Boolean?)? = null
    ): List<SpriteFrameAsync> {
        return parse(
            spriteType,
            reader,
            false,
            paletteTransform,
            progressChunkSize,
            progressCallback
        )
    }

    fun parse(
        spriteType: SpriteType,
        reader: ByteStreamReader,
        keepBlack: Boolean,
        paletteTransform: PaletteTransform? = null,
        progressChunkSize: Int = 1,
        progressCallback: ((current: Int, total: Int) -> Boolean?)? = null
    ): List<SpriteFrameAsync> {
        return ToSpriteFileParser.parse(
            spriteType,
            reader,
            keepBlack,
            paletteTransform,
            progressChunkSize,
            progressCallback
        ).getAsyncFrames()
    }
}