internal suspend fun FileSystemActions.ensureAndGetOutputDirectory(
    outputDirectory: String,
    recursive: Boolean = true
): String? {
    if (!PathUtil.isAbsolute(outputDirectory)) {
        throw PathNotAbsoluteException(outputDirectory, "Cannot make output directory without an absolute path")
    }
//!BACKSLASH    val actualOutputDirectory = outputDirectory.ensureEndsWith(pathSeparatorChar)
    val actualOutputDirectory = outputDirectory.ensureEndsWith('/')

    if (actualOutputDirectory.count { it == ':' } > 1) {
        throw Exception("Cannot create directory. Path cannot contain ':'")
    }
    if (!fileExists(actualOutputDirectory)) {
        try {
            makeDirectory(actualOutputDirectory, recursive)
        } catch (e: Throwable) {
            e.rethrowCancellationException()
            throw IOException("Failed to create output directory: $actualOutputDirectory")
        }
    } else if (!isDirectory(actualOutputDirectory)) {
        throw NotADirectoryException(
            actualOutputDirectory,
            "Output path is not a directory; Path: <$actualOutputDirectory>"
        )
    }
    if (!fileExists(actualOutputDirectory) || !isDirectory(actualOutputDirectory)) {
        return null
    }
    return actualOutputDirectory
}


/**
 * Ensures the output folder exists, creating as needed
 * Also ensures output path is an actual directory not a file
 */
suspend fun FileSystem.ensureAndGetOutputDirectory(
    outputDirectory: String,
    recursive: Boolean = true,
): String? {
    if (!PathUtil.isAbsolute(outputDirectory) && !(isVirtualPathInVirtualFS(outputDirectory))) {
        throw PathNotAbsoluteException(outputDirectory, "Cannot make output directory without an absolute path")
    }
    return FileSystemActions.ensureAndGetOutputDirectory(outputDirectory, recursive)
}

suspend fun FileSystem.qualifyPath(root: String?, path: String, wildcard: Boolean = false): String {
    val pathExpanded = path.expandTildeIfNecessary()
    val pathTemp = if (path.lowercase().startsWith("resource:")) {
        return path

    } else if (PathUtil.isAbsolute(pathExpanded) || isVirtualPathInVirtualFS(pathExpanded)) {
        pathExpanded

    } else if (root != null) {
        if (PathUtil.isAbsolute(root) || isVirtualPathInVirtualFS(root)) {
            PathUtil.combine(root.expandTildeIfNecessary(), pathExpanded)
        } else {
            throw PathNotAbsoluteException(path, "Cannot qualify path. Path and root are not absolute")
        }

    } else {
        throw PathNotAbsoluteException(path, "Cannot qualify path. Paths must be absolute")
    }

    return if (fileExists(pathTemp) && wildcard) {
        if (!isDirectory(pathTemp)) {
            return pathTemp
        } else {
            pathTemp.ensureEndsWith('/') + "*"
        }
    } else {
        pathTemp
    }
}


@Suppress("RegExpUnnecessaryNonCapturingGroup")
internal val pathRegex = "^((?:\"(?:(?:\\\\).|[^\"])*\")|(?:(?:\\\\.|[^\"\\s])+))(.*)".toRegex()

fun splitMultiFileString(string: String): List<String> {
    val out = mutableListOf<String>()
    var working = string.trim()
    while (working.isNotBlank()) {
        val values = pathRegex.matchEntire(working)
            ?.groupValues
            ?: break
        out.add(values[1].unescapePath())
        working = values.getOrNull(2)
            .nullIfEmpty()
            ?.trim()
            ?: break
    }
    return out
}


fun String.unescapePath(): String {
    return if (this.startsWith('"') && this.endsWith('"')) {
        this.trim()
            .stripSurroundingQuotes(false)
            .superUnescape(' ')
            .replace(
                "[\\\\/][\\\\/]?".toRegex(),
                pathSeparator.replace("\\", "\\\\").replace("$", "\\$")
            )
    } else {
        this.trim()
            .superUnescape(' ', '$', '(', ')', '^')
            .replace(
                "[\\\\/][\\\\/]?".toRegex(),
                pathSeparator.replace("\\", "\\\\").replace("$", "\\$")
            )
    }
}

fun isDriveRoot(path: String): Boolean {
    return path.trim() == "/" || path.trim() == "\\" || WINDOWS_DRIVE_ROOT.matches(path.trim())
}


private val isVirtualRegex = "^[a-zA-Z0-9_]+:/.*$".toRegex()
internal fun isAbsoluteOrVirtual(path: String): Boolean {
    return PathUtil.isAbsolute(path) || isResourcePath(path) || isVirtualPath(path)
}

internal fun isResourcePath(path: String): Boolean {
    return path.startsWith("resource:")
}

internal fun isVirtualPath(path: String): Boolean {
    return isVirtualRegex.matches(path)
}

internal fun FileSystem.isVirtualPathInVirtualFS(path: String): Boolean {
    return isVirtualFileSystem() && isVirtualPath(path)
}