package com.creaturesforge.application.ui.controls

import com.creaturesforge.application.state.FAction
import com.creaturesforge.application.state.ForgeConfig
import com.creaturesforge.application.state.ForgeState
import com.creaturesforge.application.state.SetAttRootAction
import org.w3c.dom.HTMLElement

internal class AttRootInput(element: HTMLElement): RootInput(element, "att") {

    override val openTitle: String = "Select ATT Root"

    override fun createSetterAction(path: String?): FAction {
        return SetAttRootAction(path)
    }

    override fun getRootFromState(state: ForgeState): String? {
        return state.attRoot
    }

    override suspend fun getLastRootFromConfig(projectRoot: String?): String? {
        return ForgeConfig.getLastAttRoot(projectRoot)
    }

    override suspend fun onRootSet(projectRoot: String?, directory: String) {
        ForgeConfig.setLastAttRoot(projectRoot, directory)
    }
}