package com.creaturesforge.application.ui.controls

import com.bedalton.common.util.isNotNullOrBlank
import com.bedalton.log.Log
import com.bedalton.state.simple.Dispatch
import com.creaturesforge.application.state.FAction
import com.creaturesforge.application.state.ForgeState
import com.creaturesforge.application.state.ForgeStore
import com.creaturesforge.application.state.SetEggNameAction
import org.w3c.dom.HTMLInputElement

internal class EggNameInput(private val element: HTMLInputElement) : Validatable {

    private lateinit var dispatch: Dispatch<FAction>
    private var autoName: String = ""

    init {
        ForgeStore.subscribe { state, dispatch ->
            this@EggNameInput.dispatch = dispatch
            updateName(state)
        }
        initListeners()
    }

    private fun initListeners() {

        element.onblur = {
            persist()
        }

        element.onkeyup = {
            if (it.key.lowercase() == "enter") {
                persist()
            }
        }

    }

    private fun persist() {

        val newName = element.value.normalize()
        val autoName = autoName.normalize()

        if (autoName == newName) {
            return
        }

        Log.i { "NewName: ${element.value}; AutoName: $autoName" }
        dispatch(SetEggNameAction(newName))
    }

    private fun updateName(state: ForgeState) {

        var oldName = state
            .selectedEgg
            .eggName

        if (oldName != null && oldName.startsWith(':')) {
            autoName = oldName
        }

        oldName = oldName
            ?.normalize()
            ?: ""

        val newName = element.value.normalize()

        if (newName == oldName) {
            return
        }

        element.value = oldName
    }

    private fun String.normalize(): String {
        return this
            .trimEnd()
            .trimStart(':', ' ', '\t')
    }

    override fun highlightErrors() {
        val valid = isValid()
        element
            .closest(".validatable-input-container")
            ?.setAttribute("data-is-valid", valid.toString())
    }

    override fun isValid(): Boolean {
        return element.value.isNotNullOrBlank()
    }
}