package com.bedalton.creatures.sprite.parsers

import com.bedalton.creatures.sprite.parsers.BlkParser.BLOCK_SIZE
import com.bedalton.creatures.sprite.util.ColorEncoding
import com.bedalton.creatures.sprite.util.forEachAsync
import com.bedalton.io.bytes.ByteStreamReader
import com.bedalton.io.bytes.uInt16
import korlibs.image.bitmap.Bitmap32
import korlibs.image.bitmap.extract
import korlibs.image.color.RGBA
import korlibs.image.color.RgbaArray
import korlibs.io.concurrent.atomic.KorAtomicInt
import korlibs.io.concurrent.atomic.incrementAndGet
import kotlin.math.floor

object BlkParser {

    internal const val BLOCK_SIZE = 128
    internal const val CELL_BYTES_SIZE = BLOCK_SIZE * BLOCK_SIZE * 2
    const val TRIM_BY_DEFAULT = true


    fun parse(
        bytes: ByteArray,
        progressChunkSize: Int? = null,
        progressCallback: ((pass: Int, current: Int, total: Int) -> Boolean?)? = null,
    ): Bitmap32 {
        return ByteStreamReader.read(bytes) {
            parse(
               this,
                progressChunkSize,
                progressCallback
            )
        }
    }


    fun parse(
        bytesBuffer: ByteStreamReader,
        progressChunkSize: Int? = null,
        progressCallback: ((pass: Int, current: Int, total: Int) -> Boolean?)? = null,
    ): Bitmap32 {
        return parse(
            bytesBuffer,
            trim = TRIM_BY_DEFAULT,
            progressChunkSize,
            progressCallback
        )
    }



    suspend fun parseAsync(
        bytes: ByteArray,
        progressChunkSize: Int? = null,
        progressCallback: ((pass: Int, current: Int, total: Int) -> Boolean?)? = null,
    ): Bitmap32 {
        return ByteStreamReader.read(bytes) {
            parseAsync(
                this,
                progressChunkSize,
                progressCallback
            )
        }
    }


    suspend fun parseAsync(
        bytesBuffer: ByteStreamReader,
        progressChunkSize: Int? = null,
        progressCallback: ((pass: Int, current: Int, total: Int) -> Boolean?)? = null,
    ): Bitmap32 {
        return parseAsync(
            bytesBuffer,
            trim = TRIM_BY_DEFAULT,
            progressChunkSize,
            progressCallback
        )
    }

    fun parseToFrames(
        bytes: ByteArray,
        progressChunkSize: Int? = null,
        progressCallback: ((current: Int, total: Int) -> Boolean?)? = null
    ): List<Bitmap32> {
        return ByteStreamReader.read(bytes) {
            parseToFrames(this, progressChunkSize, progressCallback)
        }
    }

    fun parseToFrames(
        bytesBuffer: ByteStreamReader,
        progressChunkSize: Int? = null,
        progressCallback: ((current: Int, total: Int) -> Boolean?)? = null
    ): List<Bitmap32> {
        return BlkSpriteFile(
            bytesBuffer,
            progressChunkSize = progressChunkSize ?: 1,
            progressCallback = progressCallback
        ).frames()
    }

    suspend fun parseToFramesAsync(
        bytes: ByteArray,
        progressChunkSize: Int? = null,
        progressCallback: ((current: Int, total: Int) -> Boolean?)? = null
    ): List<Bitmap32> {
        return ByteStreamReader.read(bytes) {
            parseToFramesAsync(
                this,
                progressChunkSize = progressChunkSize ?: 1,
                progressCallback = progressCallback
            )
        }
    }

    suspend fun parseToFramesAsync(
        bytesBuffer: ByteStreamReader,
        progressChunkSize: Int? = null,
        progressCallback: ((current: Int, total: Int) -> Boolean?)? = null
    ): List<Bitmap32> {
        return BlkSpriteFile(
            bytesBuffer,
            progressChunkSize = progressChunkSize ?: 1,
            progressCallback = progressCallback
        ).framesAsync()
    }


    fun parse(
        bytes: ByteArray,
        trim: Boolean? = null,
        progressChunkSize: Int? = null,
        progressCallback: ((pass: Int, current: Int, total: Int) -> Boolean?)? = null
    ): Bitmap32 {
        return ByteStreamReader.read(bytes) {
            parse(
                this, trim, progressChunkSize, progressCallback
            )
        }
    }

    fun parse(
        bytesBuffer: ByteStreamReader,
        trim: Boolean? = null,
        progressChunkSize: Int? = null,
        progressCallback: ((pass: Int, current: Int, total: Int) -> Boolean?)? = null
    ): Bitmap32 {

        val file = BlkFileParser(
            bytesBuffer,
            trim,
            progressChunkSize,
            progressCallback
        )

        return file.imageSync()
    }

    suspend fun parseAsync (
        bytes: ByteArray,
        trim: Boolean? = null,
        progressChunkSize: Int? = null,
        progressCallback: ((pass: Int, current: Int, total: Int) -> Boolean?)? = null
    ): Bitmap32 {
        return ByteStreamReader.read(bytes) {
            parseAsync(this, trim, progressChunkSize, progressCallback)
        }
    }

    suspend fun parseAsync (
        bytesBuffer: ByteStreamReader,
        trim: Boolean? = null,
        progressChunkSize: Int? = null,
        progressCallback: ((pass: Int, current: Int, total: Int) -> Boolean?)? = null
    ): Bitmap32 {
        val frames = BlkFileParser(
            bytesBuffer,
            trim,
            progressChunkSize,
            progressCallback
        )
        return frames.imageAsync()
    }

    fun parseBlkToFramesSync(
        bytes: ByteArray,
        progressChunkSize: Int? = null,
        progressCallback: ((current: Int, total: Int) -> Boolean?)? = null
    ): BlkParseResult {
        return ByteStreamReader.read(bytes) {
            parseBlkToFramesSync(
                this,
                progressChunkSize,
                progressCallback
            )
        }
    }

    fun parseBlkToFramesSync(
        bytes: ByteStreamReader,
        progressChunkSize: Int? = null,
        progressCallback: ((current: Int, total: Int) -> Boolean?)? = null
    ): BlkParseResult {
        val sprite = BlkSpriteFile(
            bytes,
            progressChunkSize = progressChunkSize,
            progressCallback = progressCallback
        )
        val frames = sprite.frames()
        sprite.close()
        return BlkParseResult(frames, sprite.cellsWide, sprite.cellsHigh)
    }

    suspend fun parseBlkToFramesAsync(
        bytes: ByteArray,
        progressChunkSize: Int? = null,
        progressCallback: ((current: Int, total: Int) -> Boolean?)? = null
    ): BlkParseResult {
        return ByteStreamReader.read(bytes) {
            parseBlkToFramesAsync(
                this,
                progressChunkSize,
                progressCallback
            )
        }
    }

    suspend fun parseBlkToFramesAsync(
        bytes: ByteStreamReader,
        progressChunkSize: Int? = null,
        progressCallback: ((current: Int, total: Int) -> Boolean?)? = null
    ): BlkParseResult {
        val sprite = BlkSpriteFile(
            bytes,
            progressChunkSize = progressChunkSize,
            progressCallback = progressCallback
        )
        val frames = sprite.framesAsync()
        sprite.close()
        return BlkParseResult(frames, sprite.cellsWide, sprite.cellsHigh)
    }

    /**
     * Gets this BLK stitched from already parsed sprite frames
     */
    fun getStitched(
        cellsWide: Int,
        cellsHigh: Int,
        frames: List<Bitmap32>,
        progressCallback: ((current: Int, total: Int) -> Unit)?,
    ): Bitmap32 {
        // Calculate image size
        val trueWidth = cellsWide * BlkSpriteFile.BLOCK_SIZE
        val trueHeight = cellsHigh * BlkSpriteFile.BLOCK_SIZE

        val totalCells = cellsWide * cellsHigh
        // Create image for writing
        val temp = Bitmap32(trueWidth, trueHeight, false)
        // Loop Cells vertically, then horizontally
        repeat(cellsWide) { cellX ->
            val x = cellX * BlkSpriteFile.BLOCK_SIZE
            repeat(cellsHigh) repeatY@{ cellY ->
                val frame = (cellX * cellsHigh) + cellY
                progressCallback?.invoke(frame, totalCells)
                // Get cells start y pixel
                val y = cellY * BlkSpriteFile.BLOCK_SIZE
                // Get cell image data as uri
                val cell = frames[frame]

                temp.draw(cell, x, y)
            }
        }
        return temp
    }

    /**
     * Gets this BLK stitched from already parsed sprite frames
     */
    suspend fun getStitchedAsync(
        cellsWide: Int,
        cellsHigh: Int,
        frames: List<Bitmap32>,
        progressCallback: ((current: Int, total: Int) -> Unit)?,
    ): Bitmap32 {
        // Calculate image size
        val trueWidth = cellsWide * BlkSpriteFile.BLOCK_SIZE
        val trueHeight = cellsHigh * BlkSpriteFile.BLOCK_SIZE

        val totalCells = cellsWide * cellsHigh
        // Create image for writing
        val temp = Bitmap32(trueWidth, trueHeight, false)

        (0 until cellsWide).forEachAsync { cellX ->
            val x = cellX * BlkSpriteFile.BLOCK_SIZE
            (0 until cellsHigh).forEachAsync repeatY@{ cellY ->
                val frame = (cellX * cellsHigh) + cellY
                progressCallback?.invoke(frame, totalCells)
                // Get cells start y pixel
                val y = cellY * BlkSpriteFile.BLOCK_SIZE
                // Get cell image data as uri
                val cell = frames[frame]
                temp.draw(cell, x, y)
            }
        }
        return temp
    }
}

private class BlkFileParser(
    bytesBufferIn: ByteStreamReader,
    trim: Boolean?,
    progressChunkSize: Int?,
    private var progressCallback: ((pass: Int, current: Int, total: Int) -> Boolean?)?
) {

    private var mBytesBuffer: ByteStreamReader? = bytesBufferIn

    private val bytesBuffer get() = mBytesBuffer
        ?: throw Exception("Blk data already disposed")

    private var mBytes: ByteArray? = mBytesBuffer!!.let { reader ->
        reader.bytes(mBytesBuffer!!.size).also {
            reader.setPosition(0)
        }
    }

    private val bytes get() = mBytes
        ?: throw Exception("Blk data already disposed")



    private val doTrim = trim ?: BlkParser.TRIM_BY_DEFAULT
    private val totalBytes get() = bytesBuffer.size
    private val flags = bytesBuffer.uInt32()

    private val encoding get() = if (flags and 1L == 1L) {
        ColorEncoding.X_565
    } else {
        ColorEncoding.X_555
    }

    // Get number of cells wide/high
    private val cellsWide = bytesBuffer.uInt16()
    private val cellsHigh = bytesBuffer.uInt16()

    private val totalWidth get() = cellsWide * BLOCK_SIZE
    private val totalHeight get() = cellsHigh * BLOCK_SIZE

    // Read total cells and validate
    private val totalCells = bytesBuffer.uInt16()

    private val image = Bitmap32(totalWidth, totalHeight, false).apply {
        fill(RGBA(0, 0, 0, 255), 0, 0)
    }

    private val current = KorAtomicInt(0)

    private val offsets by lazy {
        val offsets = mutableListOf<Long>()
        for (index in 0 until totalCells) {
            val offsetForData = bytesBuffer.uInt32() + 4
            if (offsetForData + BlkParser.CELL_BYTES_SIZE > totalBytes) {
                throw SpriteParserException("Invalid byte offset[$index]. Expected < ${totalBytes - BlkParser.CELL_BYTES_SIZE}. Found: $offsetForData")
            }
            val width = bytesBuffer.uInt16()
            if (width != BLOCK_SIZE) {
                throw SpriteParserException("BLK cell width invalid. Expected 128; Actual: $width")
            }
            val height = bytesBuffer.uInt16()
            if (height != BLOCK_SIZE) {
                throw SpriteParserException("BLK cell height invalid. Expected 128; Actual: $height")
            }
            offsets.add(offsetForData)
            progressCallback?.invoke(1, index, totalCells)
        }
        offsets
    }

    private val indices get() = offsets.indices

    private val heightFloat get() = cellsHigh.toFloat()

    private val palette = encoding
        .toRgbWithTables(true)
        .colors

    // You should not trim off more than the last blocks worth of black
    private val minWidth = (BLOCK_SIZE * (cellsWide - 1))
    private val minHeight = (BLOCK_SIZE * (cellsHigh - 1))

    // Furthest size with opaque pixels
    private var maxWidth = minWidth
    private var maxHeight = minHeight

    // Adjust max size on opaque pixels
    private val onOpaque: (x: Int, y: Int) -> Unit = if (doTrim) {
        { x, y ->
            if (x > maxWidth) {
                maxWidth = x
            }
            if (y > maxHeight) {
                maxHeight = y
            }
        }
    } else {
        {_,_ -> }
    }

    private var done = false

    private val progressChunkSizeNotNull = progressChunkSize ?: 1

    init {
        if (cellsWide == 0 || cellsHigh == 0) {
            throw SpriteParserException("BLK has no size; ByteStreamPosition: ${bytesBuffer.position()}")
        }
        if (cellsWide * cellsHigh != totalCells) {
            throw SpriteParserException("Sprite cells width($cellsWide) x height($cellsHigh) do not match total cells($totalCells)")
        }
    }

    suspend fun imageAsync(): Bitmap32 {
        if (done) {
            return image
        }
        indices.forEachAsync(this::applyCell)
        done = true
        return finalize()
    }

    fun imageSync(): Bitmap32 {
        if (done) {
            return image
        }
        indices.map(this::applyCell)
        done = true
        return finalize()
    }

    private fun applyCell(
        index: Int,
    ) {

        // Get cell location
        val cellX = floor(index / heightFloat).toInt()
        val cellY = index % cellsHigh

        // Get bytes offset
        var offset = offsets[index]

        // Read pixels into image
        val offsetX = cellX * BLOCK_SIZE
        val baseOffsetY = cellY * BLOCK_SIZE
        val rowChunk = RgbaArray(BLOCK_SIZE)
        val bytes = bytes
        for (yRaw in 0 until BLOCK_SIZE) {
            val y = baseOffsetY + yRaw
            for (xRaw in 0 until BLOCK_SIZE) {
                val x = offsetX + xRaw
                val pixel = bytes.uInt16(offset.toInt())
                offset += 2
                val color = palette[pixel]
                if (pixel != 0) {
                    onOpaque(x, y)
                }
                rowChunk[xRaw] = color
            }
            image.setRowChunk(offsetX, y, rowChunk, BLOCK_SIZE, 1)
        }

        if ((current.incrementAndGet() % progressChunkSizeNotNull) == 0) {
            progressCallback?.invoke(2, current.value, totalCells)
        }
    }

    private fun finalize(): Bitmap32 {
        mBytesBuffer = null
        mBytes = null
        if (!doTrim) {
            return image
        }
        val needsTrim = doTrim &&
                ((maxWidth > minWidth && maxWidth < image.width) ||
                        (maxHeight > minHeight && maxHeight < image.height))

        return if (needsTrim) {
            image.extract(0, 0, maxWidth, maxHeight)
        } else {
            image
        }
    }

}