package com.creaturesforge.application.ui.controls

import com.creaturesforge.application.state.FAction
import com.creaturesforge.application.state.ForgeState
import com.creaturesforge.application.state.SetBreedSlotAction
import com.creaturesforge.application.state.SetSpriteSlotAction
import org.w3c.dom.HTMLSelectElement

internal class SpriteBreedSlot(element: HTMLSelectElement): BreedSlot(element) {

    override fun getBreedSlots(state: ForgeState): Set<com.creaturesforge.application.state.BreedSlot> {
        return state.getAvailableSpriteSlots()
    }

    override fun getSelectedSlot(state: ForgeState): com.creaturesforge.application.state.BreedSlot? {
        return state.spriteSlot
    }

    override fun hasProjectRoot(state: ForgeState): Boolean {
        return state.spriteRoot != null || state.projectFolder != null
    }

    override fun getSetAction(genus: Int, breed: Char): FAction {
        return SetSpriteSlotAction(com.creaturesforge.application.state.BreedSlot(genus, breed))
    }

    override fun isValid(): Boolean {
        return selected != null
    }

}