package com.bedalton.vfs

import kotlin.js.Promise

@JsExport
interface InMemoryVFS: VFS {

//    @JsName("setBytes")
//    operator fun set(fileName: String, disposeExisting: Boolean = DISPOSE_EXISTING_DEFAULT, bytes: ByteArray): InMemoryVFS

//    @JsName("set")
//    operator fun set(fileName: String, disposeExisting: Boolean = DISPOSE_EXISTING_DEFAULT, file: org.w3c.files.File): InMemoryVFS

//    @Suppress("NON_EXPORTABLE_TYPE")
//    @JsName("setKotlinFile")
//    operator fun set(fileName: String, disposeExisting: Boolean = DISPOSE_EXISTING_DEFAULT, file: File): InMemoryVFS

    @JsName("setJsFile")
    operator fun set(fileName: String, disposeExisting: Boolean = DISPOSE_EXISTING_DEFAULT, file: dynamic): InMemoryVFS

    @JsName("get")
    operator fun get(fileName: String): Promise<ByteArray?>? {
        try {
            return readBytes(fileName)
        } catch (e: Throwable) {
            throw e
        }
    }

    @JsName("clearWritten")
    fun clearWritten()

    @JsName("getWritten")
    fun getWritten(): Promise<Array<JsFile>?>?

    /**
     * Disposes of all files in the memory VFS and clears references.
     * Do not dispose if file data is needed elsewhere
     */
    @JsName("dispose")
    fun dispose()

    /**
     * Resets memory VFS to empty state, disposing of existing files if requested
     */
    @JsName("reset")
    fun reset(disposeFiles: Boolean = false)


    @JsName("allFilePaths")
    fun allFilePaths(): Array<String>
}