package com.bedalton.creatures.caos.libs

import com.bedalton.common.util.like
import com.bedalton.creatures.caos.utils.token
import kotlin.js.JsName

/**
 * A queryable CAOS lib object
 */
@Suppress("unused")
class CaosLib internal constructor(private val lib: CaosLibDefinitions, val variant: CaosVariantData) {

    private val commandsById = lib.commands.map {
        it.key.toInt() to it.value
    }.toMap()

    /**
     * Rvalue definitions getter
     */
    val rvalue: CommandGetter = CaosCommandMap(commandsById, variant.rvalues.map { (commandString, commandIds) ->
        commandString to commandIds.values.toIntArray()
    }.toMap())

    /**
     * List of all RValues in this variant
     */
    val rvalues: Array<CaosCommand> by lazy {
        val rvalueCommandIds = variant.rvalues.values.flatMap { returnTypeIdMap ->
            returnTypeIdMap.values
        }
        lib.commands.values.filter { command ->
            command.id in rvalueCommandIds
        }.toTypedArray()
    }

    /**
     * LValue definitions getter
     */
    val lvalue: CommandGetter = CaosCommandMap(commandsById, variant.lvalues.map { (commandString, commandId) ->
        commandString to intArrayOf(commandId)
    }.toMap())


    /**
     * List of all LValues in this variant
     */
    val lvalues: Array<CaosCommand> by lazy {
        val lvalueCommandIds = variant.lvalues.values
        lib.commands.values.filter { command ->
            command.id in lvalueCommandIds
        }.toTypedArray()
    }

    /**
     * Command definitions getter
     */
    val command: CommandGetter = CaosCommandMap(commandsById, variant.commands.map { (commandString, commandId) ->
        commandString to intArrayOf(commandId)
    }.toMap())

    /**
     * List of all commands in this variant
     */
    val commands: Array<CaosCommand> by lazy {
        val commandIds = variant.commands.values
        lib.commands.values.filter { command ->
            command.id in commandIds
        }.toTypedArray()
    }

    val allCommands: Array<CaosCommand> by lazy {
        val commandIds = variant.rvalues.values.flatMap { it.values } + variant.lvalues.values + variant.commands.values
        lib.commands.values.filter { command ->
            command.id in commandIds
        }.toTypedArray()
    }

    /**
     * Values lists getter
     */
    val valuesLists: Array<CaosValuesList>
        get() = CaosLibs.getValuesLists(variant.valuesListsIds)

    @JsName("valuesListWithId")
    fun valuesList(valuesListId: Int): CaosValuesList? = CaosLibs.valuesList[valuesListId]

    @JsName("valuesListWithName")
    fun valuesList(valuesListName: String): CaosValuesList? = valuesLists.firstOrNull { it.name like valuesListName }

    /**
     * Getter for variable max value type
     */
    val variableTypeMaxValues: HasGetter<CaosScriptVarTokenGroup, Int?> = variant.vars


    // Variant query information
    /** Variant CODE */
    val variantCode: String = variant.code

    /** The full name of this variant */
    val variantName: String = variant.name

    /** Helper command to check variant oldness (i.e. C1,C2) */
    val isOldVariant: Boolean
        get() = variant.isOld

    /** Helper command to check variant newness (i.e. CV,C3,DS) */
    val isNewVariant: Boolean
        get() = variant.isNew

    operator fun get(type: CommandType): CommandGetter {
        return when (type) {
            CommandType.RVALUE -> rvalue
            CommandType.LVALUE -> lvalue
            CommandType.COMMAND -> command
        }
    }

    @JsName("getCommandWithTypeEnum")
     operator fun get(type: CommandType, tokens: IntArray, bias: ValueType = ValueType.ANY): Pair<CaosCommand, Int>? {
        return when (type) {
            CommandType.RVALUE -> rvalue
            CommandType.LVALUE -> lvalue
            CommandType.COMMAND -> command
        }[tokens, bias]
    }

    @JsName("getCommandFromString")
    operator fun get(type: CommandType, commandString: String, bias: ValueType = ValueType.ANY): Pair<CaosCommand, Int>? {
        val tokens = commandString.split("\\s+")
            .map { token(commandString.lowercase()) }
            .toIntArray()
        return when (type) {
            CommandType.RVALUE -> rvalue
            CommandType.LVALUE -> lvalue
            CommandType.COMMAND -> command
        }[tokens, bias]
    }

    @JsName("get")
    operator fun get(type: CommandType, tokens: IntArray, bias: Int = ValueType.ANY.value): Pair<CaosCommand, Int>? {
        return when (type) {
            CommandType.RVALUE -> rvalue
            CommandType.LVALUE -> lvalue
            CommandType.COMMAND -> command
        }[tokens, ValueType.fromIntValue(bias)]
    }
}