package com.bedalton.creatures.agents.util.internal


import com.bedalton.common.util.stripSurroundingQuotes
import com.bedalton.common.coroutines.rethrowIfCancellationException
import com.bedalton.log.Log
import org.antlr.v4.kotlinruntime.ParserRuleContext
import org.antlr.v4.kotlinruntime.misc.Interval

internal val ParserRuleContext.originalText: String?
    get() {
        val a = start?.startIndex
            ?: return null
        val b = stop?.stopIndex
            ?: return null
        if (a > b) {
            Log.e { "Invalid context start and end at ${start!!.line}:${start!!.charPositionInLine} -> ${stop!!.line}:${stop!!.charPositionInLine}" }
            return null
        }
        val interval = Interval(a, b)
        return try {
            start?.inputStream?.getText(interval)
        } catch (e: Exception) {
            // Do not hold onto cancellation exceptions
            e.rethrowIfCancellationException()

            null
        }
    }

internal val ParserRuleContext.originalStringValue: String?
    get() {
        val a = start?.startIndex
            ?: return null
        var b = stop?.stopIndex
            ?: return null
        if (a == b) {
            b += 1
        }
        if (a >= b) {
            Log.e { "Invalid context start and end at ${start!!.line}:${start!!.charPositionInLine} -> ${stop!!.line}:${stop!!.charPositionInLine}" }
            return null
        }

        val stream = start?.inputStream
        val streamLength = stream?.size() ?: -1
        if (b >= streamLength) {
            return null
        }
        val interval = Interval(a, b)
        return stream
            ?.getText(interval)
            ?.stripSurroundingQuotes(2)
    }