@file:Suppress("unused")

package com.creaturesforge.application.interop

import kotlinx.browser.window
import kotlinx.coroutines.*


/**
 * Exposes js methods to rust to call on window.eval calls
 */
internal fun initTauriInterop() {
    GlobalScope.launch {
        window.asDynamic().setWindowId = { id: String ->
            console.log("Setting window id to $id")
            mWindowId = id
        }
        mWindowId = tauriAsync<String>("get_window_id")
        TauriEvents.initTauriListeners()
        pushStateToWindow()
    }
}

// Window ID for this specific instance
private var mWindowId: String? = null

// Window ID for this specific instance
internal val windowId: String? get() = mWindowId


internal suspend fun pushStateToWindow() {
    updateEggModeInTauri()
    DisabledSettingsInterop.updatePreviousGenomeListDisabledInTauri()
    DisabledSettingsInterop.updateProjectSettingReloadDisabledInTauri()
}