@file:Suppress("unused")

package com.bedalton.common.serialization

import kotlinx.serialization.builtins.ArraySerializer
import kotlinx.serialization.builtins.ListSerializer
import kotlinx.serialization.builtins.nullable
import kotlinx.serialization.builtins.serializer

// String
internal val nullableStringSerializer = String.serializer().nullable
internal val stringListSerializer = ListSerializer(String.serializer())
internal val nullableStringListSerializer = ListSerializer(String.serializer()).nullable
internal val stringArraySerializer = ArraySerializer(String.serializer())
internal val nullableStringArraySerializer = ArraySerializer(String.serializer()).nullable
// Boolean
internal val nullableBooleanSerializer = Boolean.serializer().nullable

// Fixed
internal val nullableByteSerializer = Byte.serializer().nullable
internal val nullableShortSerializer = Short.serializer().nullable
internal val nullableIntSerializer = Int.serializer().nullable
internal val nullableLongSerializer = Long.serializer().nullable

// Floating
internal val nullableDoubleSerializer = Double.serializer().nullable
internal val nullableFloatSerializer = Float.serializer().nullable