package com.bedalton.creatures.caos.libs

import kotlinx.serialization.Serializable

/**
 * Holds information on the variant in a Lib file
 */
@Serializable
data class CaosVariantData(
    val name: String,
    val code: String,
    val vars: CaosVarConstraints,
    val commands: Map<String, Int>,
    val lvalues: Map<String, Int>,
    val rvalues: Map<String, Map<Int, Int>>,
    val valuesListsIds: Array<Int> = emptyArray()
) {
    val isOld: Boolean by lazy {
        code in listOf("C1", "C2")
    }
    val isNew: Boolean by lazy {
        code !in listOf("C1", "C2")
    }
    val valuesLists: List<CaosValuesList>
        get() = CaosLibs.getValuesLists(valuesListsIds).sortedBy {
            it.name
        }

    override fun equals(other: Any?): Boolean {
        if (this === other) return true
        if (other !is CaosVariantData) return false

        if (name != other.name) return false
        if (code != other.code) return false
        if (vars != other.vars) return false
        if (commands != other.commands) return false
        if (lvalues != other.lvalues) return false
        if (rvalues != other.rvalues) return false
        if (!valuesListsIds.contentEquals(other.valuesListsIds)) return false

        return true
    }

    override fun hashCode(): Int {
        var result = name.hashCode()
        result = 31 * result + code.hashCode()
        result = 31 * result + vars.hashCode()
        result = 31 * result + commands.hashCode()
        result = 31 * result + lvalues.hashCode()
        result = 31 * result + rvalues.hashCode()
        result = 31 * result + valuesListsIds.contentHashCode()
        return result
    }

}