package com.bedalton.creatures.agents.pray.compiler.data

import com.bedalton.common.structs.HasRange
import kotlin.js.JsExport

@JsExport
data class BlockDependency(
    val index: Int,
    val fileName: Tag<*>?,
    val category: Tag<*>?
) : HasRange {
    internal val first: Tag<*>?
        get() = if (fileName != null && category != null) {
            if (fileName.lineNumber < category.lineNumber)
                fileName
            else
                category
        } else fileName ?: category

    override val lineNumber get() = first?.lineNumber ?: -1
    override val startIndex get() = first?.startIndex ?: -1
    override val endIndex get() = first?.endIndex ?: -1
}