package com.bedalton.creatures.breed.render.files

import com.bedalton.common.util.PathUtil
import com.bedalton.common.util.pathSeparator
import com.bedalton.creatures.breed.render.internal.normalized
import com.bedalton.creatures.common.structs.BreedKey

fun Map<BreedKey, List<SpriteAndAtt>>.toBreedFileCollections(): List<BreedFileCollection> {
    return entries.flatMap { (key, files) -> bunches(key, files) }
}

private fun bunches(key: BreedKey, files: List<SpriteAndAtt>): List<BreedFileCollection> {
    val jsKey = key.toJsBreedKey()
    val parentPaths = files
        .map {
            it.spriteFile.parentPath.normalized()
        }
        .toSet()

    val shortestPaths = shortestPaths(parentPaths.filterNotNull())

    return parentPaths.map { parentPath ->
        val associatedFiles = files.filter {
            parentPath == it.spriteFile.parentPath.normalized()
        }
        BreedFileCollection(
            breedKey = jsKey,
            files = associatedFiles,
            parentDirectory = parentPath,
            shortestPathInCollection = shortestPaths[parentPath] ?: ""
        )
    }
}


private fun shortestPaths(allPaths: List<String>): Map<String, String> {
    val allPathsComponents = allPaths.map {
        Pair(it, it.lowercase().normalized().split('/').reversed())
    }
    val out = mutableMapOf<String, String>()
    for ((path, components) in allPathsComponents) {
        var base = ""
        var matching: List<Pair<String, List<String>>> = allPathsComponents
        for (i in components.indices) {
            val component = components[i]
            matching = matching.filter { it.second[i] == component }
            if (matching.isEmpty()) {
                break
            }
            base += pathSeparator + component
        }
        out[path] = base
    }
    return out
}