package com.bedalton.creatures.breed.render.internal

import com.bedalton.common.util.nullIfEmpty
import com.bedalton.creatures.breed.render.renderer.BreedRendererBuilder
import com.bedalton.creatures.breed.render.support.pose.PartChars
import com.bedalton.creatures.common.structs.BreedKey
import com.bedalton.creatures.common.structs.GameVariant
import com.bedalton.creatures.genetics.gene.AppearanceGene
import com.bedalton.creatures.genetics.gene.Gene
import com.bedalton.creatures.genetics.gene.GenusGene
import com.bedalton.creatures.genetics.genome.Genome
import com.bedalton.creatures.genetics.genome.genesOfType
import com.bedalton.creatures.genetics.genome.isC1
import com.bedalton.log.*


internal fun skip(gene: Gene, defaultGender: Int, age: Int?, geneVariant: Int?): Boolean {
    if (age != null && age < gene.geneHeader.switchOnTimeInt) {
        return true
    }

    if (gene.geneHeader.notExpressed) {
        return true
    }

    // Filter by gene variant if available// Should only affect C2e
    if ((geneVariant ?: 0) != 0 && (gene.geneHeader.geneVariant
            ?: 0) != 0 && geneVariant != gene.geneHeader.geneVariant
    ) {
        return true
    }

    if ((gene.geneHeader.flags.flag and (8/*Male*/ or 16 /*Female*/)) == 0) {
        return false
    }

    when (defaultGender) {
        1 -> {
            if (gene.geneHeader.femaleOnly) {
                return true
            }
        }

        2 -> {
            if (gene.geneHeader.maleOnly) {
                return true
            }
        }
    }
    return false
}

internal fun BreedRendererBuilder.applyPartsFromGenomeActual(
    gameVariant: GameVariant,
    genome: Genome,
    gender: Int,
    age: Int,
    selectedVariant: Int = 0
): BreedRendererBuilder {
    var out = this
    val genus = if (genome.isC1) {
        genome.genesOfType<GenusGene>()
            .firstOrNull()
            ?.genus
    } else {
        null
    }

    // Get age filter only if needed
    val ageFilter = if (genome.version > 2) age else null

    // Get all appearance genes
    val appearanceGenesAll = genome.genesOfType<AppearanceGene>()

    // Get only appearance genes matching variant
    val appearanceGenesByVariant = appearanceGenesAll.filter { gene ->
        // Filter by variant if needed
        val geneVariant = gene.geneHeader.geneVariant ?: 0
        selectedVariant == geneVariant || selectedVariant == 0 || geneVariant == 0
    }

    val genesByPart = appearanceGenesAll.map { it.part }
        .distinct()
        .associateWith { partGroup ->
            // Try to get variant only appearance genes for part group
            var temp = appearanceGenesByVariant.filter { it.part == partGroup }
            if (temp.isNotEmpty() && genome.version > 2) {
                // Find only active appearance genes
                val temp2 = temp.filter { gene -> !skip(gene, gender, age, selectedVariant) }
                if (temp2.isNotEmpty()) {
                    // Genes found that are not skipped, so use those
                    temp = temp2
                }
            }

            // Check if any genes exist for part group AND variant
            if (temp.isEmpty()) {
                // No part group genes match variant, so
                // get all part group genes regardless of variant
                temp = appearanceGenesAll.filter { it.part == partGroup }
                if (temp.isNotEmpty()) {
                    // Try to get only active appearance genes
                    val temp2 = temp.filter { gene -> !skip(gene, gender, age, selectedVariant) }
                    if (temp2.isNotEmpty()) {
                        // Genes found that are not skipped, so use those
                        temp = temp2
                    }
                }
            }
            temp
        }

    // Apply genes for part groups
    for ((partGroup, genes) in genesByPart) {
        if (genes.isEmpty()) {
            Log.wIf(LOG_VERBOSE) { "No appearance gene found for part group $partGroup" }
        }
        val gene = if (ageFilter != null) {
            // Try to get appearance genes by valid age
            (genes.filter { it.geneHeader.switchOnTimeInt <= ageFilter }
                .nullIfEmpty()
                // Find gene for oldest state still matching age filter
                ?.maxByOrNull { it.geneHeader.switchOnTimeInt })
            // If no appearance gene matches age, just return first in list
                ?: genes.first()
        } else {
            genes.first()
        }

        // Create breed key from gene, using genus from C1 if needed
        val breed = BreedKey(
            variant = gameVariant,
            genus = gene.genus ?: genus,
            breed = gene.breed,
            gender = gender,
            ageGroup = age
        ).also {
            Log.iIf(LOG_VERBOSE) { "Part ${gene.part} = Genus: ${it.genus}; Breed: ${it.breed}" }
        }
        val parts = when (gene.part) {
            AppearanceGene.HEAD -> PartChars.REQUIRED_AND_OPTIONAL_HEAD_PARTS
            AppearanceGene.BODY -> PartChars.BODY_PARTS
            AppearanceGene.LEGS -> PartChars.LEG_PARTS
            AppearanceGene.ARMS -> PartChars.ARM_PARTS
            AppearanceGene.TAIL -> PartChars.TAIL_PARTS
            AppearanceGene.HAIR -> PartChars.HAIR_PARTS
            else -> {
                Log.eIf(LOG_DEBUG) { "Invalid appearance gene part value: ${gene.part}" }
                continue
            }
        }

        // Set breed for parts in body part group
        out = out.withPartsBreed(breed, *parts.toCharArray())
    }
    return out
}

