package com.bedalton.creatures.sprite.util

import com.bedalton.creatures.sprite.compilers.SprCompiler
import kotlin.math.abs


internal fun swapAndRotateC1(
    palette: ColorPalette,
    red: Int?,
    green: Int?,
    blue: Int?,
    swap: Int?,
    rotation: Int?
): ColorPalette {

    if (
        isDefaultColorValue(red) &&
        isDefaultColorValue(green) &&
        isDefaultColorValue(blue) &&
        isDefaultColorValue(swap) &&
        isDefaultColorValue(rotation)
    ) {
        return palette
    }

    val out = palette.colors.toTypedArray()

    val toInt = swapAndRotateToIntC1(palette, red, green, blue, swap, rotation)

    for (i in 1 until 246) {
        val color = palette[i]
        if (color.r == 0 && color.g == 0 && color.b == 0) {
            out[i] = color
            continue
        }
        val translated = toInt(color.r, color.g, color.b)
        out[i] = palette[translated]
    }
    return ColorPalette(ColorEncoding.C1, out, true)
}

internal fun swapAndRotateToIntC1(
    palette: ColorPalette,
    red: Int?,
    green: Int?,
    blue: Int?,
    swap: Int?,
    rotation: Int?
): (red: Int, green: Int, blue: Int) -> Int {

    val redMap = remap(red ?: 128)
    val greenMap = remap(green ?: 128)
    val blueMap = remap(blue ?: 128)

    val temp: Array<Int> = Array(3) { 0 }

    val rotate = rotationFunction(rotation ?: 128)
    if (palette.size != 256) {
        throw Exception("Palette does not match C1")
    }
    val blackish = (1..255).first { i ->
        val color = palette[i]
        color.r == 0 && color.g == 0 && color.b == 0
    }
    val absoluteSwap = abs((swap ?: 128) - 127.5) / 127.5
    val inverseSwap = 1 - absoluteSwap
    return toInt@{ redColor: Int, greenColor: Int, blueColor: Int ->
        if(redColor == 0 && greenColor == 0 && blueColor == 0) {
            return@toInt 0
        }
        var r = redMap[redColor]
        var g = greenMap[greenColor]
        var b = blueMap[blueColor]
        rotate(temp, r, g, b)
        r = temp[0]
        g = temp[1]
        b = temp[2]
        if (swap != null && swap != 128) {
            r = ((absoluteSwap * b) + (inverseSwap * r)).toInt().bound()
            b = ((absoluteSwap * r) + (inverseSwap * b)).toInt().bound()
        }
        SprCompiler.getColorIndex(palette, r, g, b, true).let {
            if (it == 0) {
                blackish
            } else {
                it
            }
        }
    }
}


private fun rotationFunction(rotation: Int): (out: Array<Int>, r: Int, g: Int, b: Int) -> Unit {
    return if (rotation < 128) {
        val absoluteRotation = (127.0 - rotation) / 127.0
        val inverseRotation = 1 - absoluteRotation
        { temp: Array<Int>, r: Int, g: Int, b: Int ->
            temp[0] = ((absoluteRotation * b) + (inverseRotation * r)).toInt().bound()
            temp[1] = ((absoluteRotation * r) + (inverseRotation * g)).toInt().bound()
            temp[2] = ((absoluteRotation * g) + (inverseRotation * b)).toInt().bound()
        }
    } else if (rotation > 128) {
        val absoluteRotation = (rotation - 128) / 127.0
        val inverseRotation = 1 - absoluteRotation
        { temp: Array<Int>, r: Int, g: Int, b: Int ->
            temp[0] = ((absoluteRotation * g) + (inverseRotation * r)).toInt().bound()
            temp[1] = ((absoluteRotation * b) + (inverseRotation * g)).toInt().bound()
            temp[2] = ((absoluteRotation * r) + (inverseRotation * b)).toInt().bound()
        }
    } else {
        { temp: Array<Int>, r: Int, g: Int, b: Int ->
            temp[0] = r
            temp[1] = g
            temp[2] = b
        }
    }
}

private fun remap(value: Int): Array<Int> {
    val base = value - 128
    val b = 64 + ((20 * base) / 128)
    val c = 128 + ((32 * base) / 128)
    val d = 192 + (20 * base) / 128
    val out = Array(256) { 0 }
    repeat(64) { i ->
        out[i] = 0 + ((b - 0) * i) / 64
        out[i + 64] = b + ((c - b) * i) / 64
        out[i + 128] = c + ((d - c) * i) / 64
        out[i + 192] = d + ((255 - d) * i) / 64
    }
    return out
}
