package com.bedalton.vfs

import com.bedalton.common.coroutines.AlreadyDisposedException
import com.bedalton.common.exceptions.IOException
import com.bedalton.common.util.PathUtil
import com.bedalton.common.util.className
import com.bedalton.log.LOG_VERBOSE
import com.bedalton.log.Log
import com.bedalton.log.tIf

abstract class MemoryFile: File {

    // The name of the file
    abstract override val name: String

    // Mime type of file, most likely null
    abstract override val mimeType: String?

    abstract suspend fun md5(): String

    // File extension for quick access
    val extension by lazy {
        PathUtil.getExtension(name)
    }


    abstract override suspend fun read(): ByteArray

    // Free up memory
    private var disposed: Boolean = false

    protected abstract fun disposeInternal()

    override fun dispose() {
        if (disposed) {
            return
        }
        Log.tIf(LOG_VERBOSE) {
            "Disposing ${this.className}[$name]"
        }
        disposed = true
        disposeInternal()
    }

    fun assertNotDisposed() {
        if (disposed) {
            throw AlreadyDisposedException("File $name was already disposed")
        }
    }

}