@file:Suppress("unused")

package com.bedalton.io.bytes

import okio.BufferedSource
import okio.ByteString

fun ByteArray.uInt8(offset: Int): Int {
    return get(offset).toInt() and 0xFF
}

fun ByteArray.uByte(offset: Int): UByte {
    return (get(offset).toInt() and 0xFF).toUByte()
}

fun ByteArray.uInt16(offset: Int): Int {
    return int(offset, 2).toInt() and 0xFFFF
}

fun ByteArray.uShort(offset: Int): UShort {
    return (int(offset, 2).toInt() and 0xFFFF).toUShort()
}

fun ByteArray.uInt(offset: Int): UInt {
    return (int(offset, 4) and 0xFFFFFFFFFF).toUInt()
}

fun ByteArray.uInt32(offset: Int): Long {
    return (int(offset, 4) and 0xFFFFFFFFFF)
}

fun ByteArray.int(offset: Int, count: Int): Long {
    var position = offset
    var result = 0L
    repeat(count) { i ->
        result = result or (uInt8(position++) shl 8 * i).toLong()
    }
    return result
}

fun ByteArray.char(position: Int) {
    uInt8(position).toChar()
}


fun ByteArray.tokenInt(position: Int): Int {
    return uInt8(position) shl 24 or
                (uInt8(position + 1) shl 16) or
                (uInt8(position + 2) shl 8) or
                uInt8(position + 3)
}


fun ByteArray.tokenString(position: Int): String {
    return "" + char(position) + char(position + 1) + char(position + 2) + char(position + 3)
}

fun ByteString.uInt8(offset: Int): Int {
    return get(offset).toInt() and 0xFF
}

fun ByteString.uByte(offset: Int): UByte {
    return (get(offset).toInt() and 0xFF).toUByte()
}

fun ByteString.uInt16(offset: Int): Int {
    return int(offset, 2).toInt() and 0xFFFF
}

fun ByteString.uShort(offset: Int): UShort {
    return (int(offset, 2).toInt() and 0xFFFF).toUShort()
}

fun ByteString.uInt(offset: Int): UInt {
    return (int(offset, 4) and 0xFFFFFFFFFF).toUInt()
}

fun ByteString.uInt32(offset: Int): Long {
    return (int(offset, 4) and 0xFFFFFFFFFF)
}

fun ByteString.int(offset: Int, count: Int): Long {
    var position = offset
    var result = 0L
    repeat(count) { i ->
        result = result or (uInt8(position++) shl 8 * i).toLong()
    }
    return result
}

fun ByteString.tokenInt(position: Int): Int? {
    return try {
        uInt8(position) shl 24 or
                (uInt8(position + 1) shl 16) or
                (uInt8(position + 2) shl 8) or
                uInt8(position + 3)
    } catch (_: Exception) {
        null
    }
}

fun ByteString.tokenString(position: Int): String {
    return "" + char(position) + char(position + 1) + char(position + 2) + char(position + 3)
}

fun ByteString.char(position: Int) {
    uInt8(position).toChar()
}

fun BufferedSource.uInt8(): Int {
    return readByte().toInt() and 0xFF
}

fun BufferedSource.uInt16(): Int {
    return int(2).toInt() and 0xFFFF
}

fun BufferedSource.uInt(): UInt {
    return (int(4) and 0xFFFFFFFFFF).toUInt()
}

fun BufferedSource.uInt32(): Long {
    return (int(4) and 0xFFFFFFFFFF)
}

fun BufferedSource.int(count: Int): Long {
    var result = 0L
    repeat(count) { i ->
        result = result or (uInt8() shl 8 * i).toLong()
    }
    return result
}

fun BufferedSource.char() {
    uInt8().toChar()
}

fun BufferedSource.tokenInt(): Int {
    return uInt8() shl 24 or
            (uInt8() shl 16) or
            (uInt8() shl 8) or
            uInt8()
}

fun BufferedSource.tokenString(): String {
    return "" + char() + char() + char() + char()
}