import tauri.os.platform
import kotlin.js.Date

internal class CompileButton(private val button: HTMLButtonElement) {

    private lateinit var dispatch: Dispatch<FAction>
    private var lastPath: String? = null
    private var mState: ForgeState? = null
    private val canCancel by button.dataBoolean("is-cancellable", true)
    private var dataCompiling by body.dataBoolean("compiling")
    private val needsConfirm by button.dataBoolean("needs-confirm", false)
    private val isConfirmButton by button.dataBoolean("confirm-button")
        .default(false)

    private val state: ForgeState get() = mState ?: throw NullPointerException("State accessed before ready")

    private var confirming = false

    private val progressBar: HTMLElement? by lazy {
        button.parentElement?.querySelector(".button-progress-bar") as HTMLElement?
    }

    private val compileText by lazy {
        (button.querySelector("[data-id='compile-text']") as? HTMLElement)
            ?: element("span") {
                this.innerText = "Compile"
                this.setAttribute("data-id", "compile-text")
                this.classList.add("hide-on-compile", "hidden")
                button.appendChild(this)
            }
    }

    private val confirmingText by lazy {
        (button.querySelector("[data-id='confirming-text']") as? HTMLElement)
            ?: if (needsConfirm == true) {
                element("span") {
                    this.innerText = "Confirm Compile"
                    this.setAttribute("data-id", "confirming-text")
                    this.classList.add("hide-on-compile")
                    this.hide()
                    this.ariaHidden = true
                    button.appendChild(this)
                }
            } else {
                null
            }
    }

    private val cancelText by lazy {
        (button.querySelector("[data-id='cancel-compile-text']") as? HTMLElement)
            ?: if (canCancel != false) {
                element("span") {
                    this.innerText = "Cancel"
                    this.setAttribute("data-id", "cancel-compile-text")
                    this.classList.add("hide-on-not-compiling")
                    this.hide()
                    this.ariaHidden = true
                    button.appendChild(this)
                }
            } else {
                null
            }
    }

    init {
        button.addEventListener("click", this::onClick)
        CompilerListeners.addListener(this::updateCompileStatus)
        ForgeStore.subscribe { state, dispatch ->
            if (!this::dispatch.isInitialized) {
                this.dispatch = dispatch
            }

            mState = state
            updateEnabled(state)
        }
    }

    @Suppress("UNUSED_PARAMETER")
    private fun onClick(e: Event? = null) {
        if (EggCompiler.isCompiling) {
            if (canCancel != false) {
                requestCompileCancel()
            } else {
                Log.iWith(LOG_PROGRESS) { "Compile cannot be cancelled now" }
            }
        } else if (!button.disabled) {
            if (confirming || needsConfirm != true) {
                GlobalScope.launch {
                    try {
                        requestCompile(state)
                    } catch (e: Exception) {
                        Log.e("Failed to requestCompile(); ${e.formatted(true)}")
                    }
                }
            } else if (needsConfirm == true) {
                dispatch(RequestCompileWithVerificationAction)
                showConfirmingText()
            }
        } else {
            Log.e { "Missing required fields" }
        }
    }

    fun showConfirmingText() {
        if (!isConfirmButton) {
            return
        }
        compileText.hide()
        compileText.ariaHidden = true
        cancelText?.hide()
        cancelText?.ariaHidden = true
        confirmingText?.unhide()
        confirmingText?.ariaHidden = false
        confirming = true
    }

    private fun showCompileText() {
        confirming = false
        confirmingText?.hide()
        confirmingText?.ariaHidden = true
        cancelText?.hide()
        cancelText?.ariaHidden = true
        compileText.unhide()
        compileText.ariaHidden = false
    }

    private fun showCancelText() {
        confirming = false
        confirmingText?.hide()
        confirmingText?.ariaHidden = true
        compileText.hide()
        compileText.ariaHidden = true
        cancelText?.unhide()
        cancelText?.ariaHidden = false
    }

    private suspend fun requestCompile(state: ForgeState) {
        Log.i { "Requested compile" }

        if (!Pages.isValid()) {
            Pages.validate()
            button.setAttribute("data-before-page-validate", button.disabled.toString())
            button.disabled = true
            return
        }

        if (button.disabled) {
            button.disabled = button.getBoolean("data-before-page-validate") ?: false
        }

        val platform = platform().await().lowercase()

        val defaultFileOrFolder = try {
            getDefaultSavePath(platform, state)
        } catch (e: Exception) {
            Log.e("CompileButton::requestCompile()->getDefaultSavePath() failed; ${e.formatted(true)}")
            throw e
        }

        val file = getSaveFilePath {
            this.title = "Output Agent File"
            this.defaultPath = defaultFileOrFolder.also {
                Log.i("Default path: <$it>")
            }
            this.filters = arrayOf(
                jsOb {
                    this.name = "agent"
                    this.extensions = arrayOf("agents", "agent")
                }
            )
        } ?: return Unit.also {
            Log.i { "Compile aborted" }
        }

        addFile(file)

        // Cache folder or file path
        val directory = PathUtil.getWithoutLastPathComponent(file) ?: file

        ForgeConfig.setLastAgentsSaveDirectory(state.projectFolder, directory)

        ForgeConfig.setLastCompilePath(getLastCompilePathRootKey(state), file)

        this@CompileButton.lastPath = if (platform == "darwin") {
            directory
        } else {
            file
        }

        // Dispatch compile event
        dispatch(RequestCompileAction(file, Date.now()))
    }

    private suspend fun getDefaultSavePath(platform: String, state: ForgeState): String? {

        state.outputFile?.let {
//            if (platform != "darwin") {
//                return null
//            } else {
                return it
//            }
        }

//        if (platform != "darwin") {
            val lastCompilePathKey: String? = getLastCompilePathRootKey(state)
            ForgeConfig.getLastCompilePath(lastCompilePathKey)?.let {
                return it
            }
//        }

        val root = getDefaultFolder(state)
            ?: return null

        val name = state.fileNameOrDefault()


        return if (platform != "darwin") {
            val tail = if (name != null) {
                name.trim() + ".agents"
            } else {
                ""
            }
            root + tail
        } else {
            root
        }
    }

    private suspend fun getDefaultFolder(state: ForgeState): String? {

        val lastPath = lastPath

        if (lastPath != null && !lastPath.startsWith(':')) {
            return lastPath
        }

        state.lastSaveDirectory?.let {
            return it
        }

        val projectFolder = ForgeConfig
            .getLastAgentsSaveDirectory(state.projectFolder)
            ?: state.projectFolder
            ?: return null

        return projectFolder
            .ensureEndsWith(pathSeparator(projectFolder))
    }

    private fun requestCompileCancel() {
        dispatch(RequestCompileCancelAction)
    }

    private fun updateEnabled(state: ForgeState) {
        button.disabled = !canCompile(state)
    }

    private fun canCompile(state: ForgeState): Boolean {
        return try {
            StateValidator.getMissing(state, true).isEmpty()
        } catch (e: Exception) {
            Log.e("CompileButton:canCompile() threw exception; ${e.formatted(true)}")
            false
        }
    }


    private fun hide(selector: String, hide: Boolean) {
        val items = document.querySelectorAll(selector)

        if (hide) {
            for (i in 0 until items.length) {
                val item = items.item(i) as HTMLElement
                item.setAttribute("aria-hidden", "true")
                item.hidden = true
            }
        } else {
            for (i in 0 until items.length) {
                val item = items.item(i) as HTMLElement
                item.removeAttribute("aria-hidden")
                item.hidden = false
            }
        }

    }


    private fun showProgressBar(show: Boolean) {
        val progressBar = progressBar
            ?: return

        if (!show == progressBar.hidden) {
            return
        }

        if (show) {
            progressBar.style.removeProperty("display")
            progressBar.hidden = false
            progressBar.style.visibility = "visible"
        } else {
            progressBar.style.display = "none"
            progressBar.hidden = true
            progressBar.style.visibility = "hidden"
        }
    }

    private fun updateProgress(progress: Double?) {

        val progressBar = progressBar
            ?: return

        if (progress == null) {
            showProgressBar(false)
            return
        } else if (progressBar.hidden){
            showProgressBar(true)
        }

        progressBar.style.width = "$progress%"
    }

    private fun updateCompileStatus(action: CompileEggAction) {

        if (action is CompileEggProgress) {
            updateProgress(action.progress)
            return
        }

        // Clear confirming on status change
        confirming = false

        val isCompiling = action is CompileEggStartedAction
        updateCompilingUI(isCompiling)
        dataCompiling = isCompiling
    }

    private fun getLastCompilePathRootKey(state: ForgeState): String? {
        return state.projectFolder?.lowercase()?.let { projectFolder ->
            if (projectFolder.startsWith("agent://")) {
                projectFolder
            } else if (state.breedSlot != null) {
                projectFolder + ":" + state.breedSlot
            } else if (state.spriteSlot != null) {
                projectFolder + ":" + state.spriteSlot
            } else {
                null
            }
        }
    }

    private fun updateCompilingUI(isCompiling: Boolean) {

        // Update compiling classes
        hide(".hide-on-not-compiling", !isCompiling)
        hide(".hide-on-compiling", isCompiling)

        if (isCompiling) {
            updateProgress(0.0)
            button.disabled = false
            button.removeAttribute("disabled")
            showCancelText()
        } else {
            showCompileText()
        }

        // Clear progress bar if not compiling
        if (!isCompiling) {
            showProgressBar(false)
        }
    }

}