
import com.bedalton.creatures.sprite.compilers.SpriteCompiler
import com.bedalton.creatures.sprite.util.ColorEncoding
import com.bedalton.creatures.sprite.util.SpriteType
import com.bedalton.creatures.sprite.util.parser
import com.bedalton.io.bytes.MemoryByteStreamReader
import korlibs.io.async.async
import korlibs.io.async.runBlockingNoSuspensions
import kotlinx.coroutines.GlobalScope
import kotlinx.coroutines.asPromise
import kotlin.js.Promise

/**
 * Convert one sprite's raw bytes, to another format's raw bytes
 */
@JsExport
fun convertSprite(
    byteArray: ByteArray,
    fromSpriteTypeString: String,
    toSpriteTypeString: String,
    colorEncodingString: String? = null,
    callback: ((pass: Int, current: Int, total: Int) -> Boolean?)?,
): Promise<ByteArray> {

    // Get sprite to/from
    val fromSpriteType = SpriteType.fromString(fromSpriteTypeString)
    val toSpriteType = SpriteType.fromString(toSpriteTypeString)

    // Create a promise around the suspending conversion function
    return GlobalScope.async {
        convertSprite(
            fromSpriteType,
            toSpriteType,
            byteArray,
            colorEncodingString,
            callback
        )
    }.asPromise()
}

/**
 * Actual work to convert the sprite
 */
private fun convertSprite(
    fromSpriteType: SpriteType,
    toSpriteType: SpriteType,
    byteArray: ByteArray,
    colorEncodingString: String?,
    callback: ((pass: Int, current: Int, total: Int) -> Boolean?)?
): ByteArray {
    // Parse images
    val images = runBlockingNoSuspensions {
        fromSpriteType.parser(MemoryByteStreamReader(byteArray), false) { current: Int, total: Int ->
            callback?.invoke(1, current, total)
        }
    }

    // Get target color encoding if any
    val colorEncoding = colorEncodingString?.let { ColorEncoding.fromString(it) }

    // Compile sprite and return bytes
    return SpriteCompiler.getCompiler(toSpriteType)
        .compileSpriteFromLoadedImages(images, true, colorEncoding) { current, total ->
            callback?.invoke(2, current, total)
        }
}
