internal fun ByteArray.decodeToWindowsCP1252EncodingFallback(start: Int = 0, endExclusive: Int? = null): String {
    val chars = StringBuilder()
    try {
        this.decodeToString(0, this.size, true).apply {
            if (this.all { it in encoding }) {
                return this
            }
        }
    } catch (e: Exception) {
        e.rethrowIfCancellationException()
    }
    for (i in start until (endExclusive ?: size)) {
        val char = this[i].toInt().let {
            if (it < 0) {
                256 + it
            } else {
                it
            }
        }
        chars.append(encoding[char])
    }
    return chars.toString()
}