package com.creaturesforge.application.ui

import com.bedalton.common.util.randomString
import kotlinx.html.*

val used = mutableSetOf<String>()

private fun getInputId(): String {
    var id: String
    do {
        id = "input-field-" + randomString(8)
    } while (id.isEmpty() || id in used)
    used.add(id)
    return id
}
internal fun FlowContent.inputField(label: String, id: String = getInputId(), init: FlowContent.(id: String) -> Unit) {
    div {
        this.classes += "input-field"
        label {
            this.attributes["for"] = id
            + label
        }
        init(id)
    }
}