@file:Suppress("unused")

package com.bedalton.creatures.sprite.parsers

import com.bedalton.common.structs.AlreadyDisposedDataCacheException
import com.bedalton.creatures.sprite.util.ColorEncoding
import com.bedalton.creatures.sprite.util.PaletteTransform
import com.bedalton.creatures.sprite.util.SpriteType
import com.bedalton.io.bytes.ByteStreamReader
import com.bedalton.log.Log

/**
 * Parses Creatures C16 sprite file
 * Based on c2ephp by telyn
 * @link https://github.com/telyn/c2ephp
 */
class C16SpriteFile(
    bytesBuffer: ByteStreamReader,
    keepBlack: Boolean,
    paletteTransform: PaletteTransform? = null,
    progressChunkSize: Int = 1,
    progressCallback: ((current: Int, total: Int) -> Boolean?)? = null,
) : SpriteFile(
    spriteType = SpriteType.C16,
    keepBlack = keepBlack,
    paletteTransform = paletteTransform,
    progressChunkSize = progressChunkSize,
    progressCallback = progressCallback
) {


    override val allowAsync: Boolean
        get() = false

    private var mBytesBuffer: ByteStreamReader? = bytesBuffer

    private var mSize: Int? = null

    private var mEncoding: ColorEncoding? = null

    override val encoding: ColorEncoding
        get() = mEncoding ?: mBytesBuffer?.readAtPosition(0) {
            // Get encoding and sprite type as bit-masked int
            val buffer = uInt32()
            val encoding = if (buffer and 1L == 0L) ColorEncoding.X_555 else ColorEncoding.X_565
            mEncoding = encoding
            encoding
        } ?: throw AlreadyDisposedDataCacheException("Cannot get color encoding. Byte buffer already closed")

    private val bytesBuffer: ByteStreamReader?
        get() {
            val buffer = mBytesBuffer
                ?: return null
            if (buffer.closed) {
                mBytesBuffer = null
                return null
            }
            return buffer
        }

    override fun sizeInternal(): Int {
        mSize?.let {
            return it
        }
        val bytesBuffer = bytesBuffer
            ?: throw SpriteParserException("Failed to get sprite frame count. File stream already closed")

        return SpriteParser.imagesCount("file.$extension", bytesBuffer)?.apply {
            mSize = this
        } ?: throw SpriteParserException("Failed to get sprite count from raw bytes")
    }


    override fun initFramesInternal(): List<SpriteFrameAsync> {
        return bytesBuffer?.initC16Frames(keepBlack, paletteTransform)
            ?: throw SpriteParserException("Cannot init frames as byte buffer is already closed")
    }


    /**
     * Close any internal streams, and release references
     */
    override fun closeInternal(): Boolean {

        if (mSize == null) {
            bytesBuffer?.let {
                try {
                    SpriteParser
                        .imagesCount("file.$extension", it)?.apply {
                            mSize = this
                        }
                } catch (_: Exception) {
                    null
                }
            }
        }
        return bytesBuffer?.close()?.apply {
            mBytesBuffer = null
        } ?: true
    }

    private fun ByteStreamReader.initC16Frames(
        keepBlack: Boolean,
        paletteTransform: PaletteTransform?,
    ): List<SpriteFrameAsync> {
        if (this.closed) {
            throw SpriteParserException("Failed to initC16 frames. File stream already closed")
        }
        val bytesSize = size

        // Get encoding and sprite type as bit-masked int
        val buffer = uInt32()
        val encoding = if (buffer and 1L == 0L) ColorEncoding.X_555 else ColorEncoding.X_565
        mEncoding = encoding

        if (buffer and 2L == 0L) {
            throw Exception("C16 parse exception. This file is probably a S16 masquerading as a C16!")
        } else if (buffer > 3) {
            throw Exception("C16 file encoding not recognised. ('$buffer')")
        }
        // Parse number of files
        val imagesCount = uInt16()

        // Get palette for encoding
        val palette = paletteTransform
            ?.transform(encoding, true)
            ?.colors
            ?: encoding
                .toRgbWithTables(true)
                .colors

        // Read frame data into frame object
        val frameTriples = (0 until imagesCount).map {
            // Find sprite frame offset in file
            val offsetForData = uInt32()
            if (offsetForData > bytesSize) {
                throw Exception("Offset for data out of range. Max: $bytesSize; Offset: $offsetForData")
            }
            val width = uInt16()
            val height = uInt16()

            // Read and discard line offsets ... not used here
            (0 until height - 1).forEach { _ ->
                uInt32()
            }

            Triple(offsetForData, width, height)
        }

        return frameTriples.indices.map { i ->
            val (offsetForData, width, height) = frameTriples[i]
            var endOffset = (if (i == imagesCount - 1) size() - 1L else frameTriples[i + 1].first)
            if (endOffset < offsetForData) {
                endOffset = size
            } else {
                endOffset += 1
            }
            SpriteFrameAsyncImpl(
                width,
                height,
                palette,
                keepBlack,
                { },
                getC16ParserFunction(
                    index = i,
                    bytesBuffer = this,
                    offset = offsetForData,
                    endOffset = endOffset,
                    width = width,
                    height = height,
                    keepBlack = keepBlack
                )
            )
        }
    }

    companion object {
        fun parseFrame(
            index: Int,
            bytesBuffer: ByteStreamReader,
            offset: Long,
            endOffset: Long,
            width: Int,
            height: Int,
            keepBlack: Boolean,
        ): PixelIndices {
            return bytesBuffer.readAtPosition(offset) {
                parseC16FrameAtCurrentPosition(index, this, endOffset, width, height, keepBlack)
            }
        }
    }
}


/**
 * Holds C16 frame information and optionally decodes it
 */
private fun getC16ParserFunction(
    index: Int,
    bytesBuffer: ByteStreamReader,
    offset: Long,
    endOffset: Long,
    width: Int,
    height: Int,
    keepBlack: Boolean,
): (() -> PixelIndices) {
    return {
        bytesBuffer.readAtPosition(offset) {
            if (offset != this.position()) {
                Log.e("Position not properly set to offset; Expected: $offset; Found: ${this.position()}")
            }
            parseC16FrameAtCurrentPosition(index, this, endOffset, width, height, keepBlack)
        }
    }
}

/**
 * Parse a single frame at the bytes buffer's current offset
 */
private fun parseC16FrameAtCurrentPosition(
    index: Int,
    bytesBuffer: ByteStreamReader,
    endOffset: Long,
    width: Int,
    height: Int,
    keepBlack: Boolean,
): PixelIndices {
    // Ensure that end offset is less than bytes
    if (bytesBuffer.lastIndex + 1 < endOffset) {
        throw Exception("Not enough bytes for next C16 image. Position $endOffset > limit ${bytesBuffer.lastIndex}")
    }

    // Create data holder for image data bytes
    val pixels = IntArray(width * height) { 0 }

    val transparentBlack = if (keepBlack) {
        0
    } else {
        PixelIndices.TRANSPARENT_BLACK
    }

    // Loop across then down
    for (y in 0 until height) {
        var x = 0
        val offsetY = y * width
        // C16 uses runs to shrink size. So x at start of loop is variable
        while (x < width) {
            // Find current run
            val run = bytesBuffer.uInt16()
            // Find run length
            val runLength = (run and 0x7FFF) shr 1
            // Determine if x + run is past width
            val z = x + runLength
            if (z > width) {
                // Throw error if x + run length is greater than width
                val error = "Run[$run]; RunLength ($runLength) + X($x) is greater than width($width) sprite '$index' @ ${bytesBuffer.position() - 2}; Y[$y]"
                throw SpriteParserException(error)
            }
            // Determine whether run is black or colored
            if ((run and 0x0001) <= 0) {
                // If black fill in pixels with transparent black
                while (x < z) {
                    pixels[offsetY + x] = transparentBlack
                    x++
                }
            } else {
                // Read in all color pixels in run
                while (x < z) {
                    pixels[offsetY + x] = bytesBuffer.uInt16()
                    x++
                }
            }
        }
        // if x == width, discard extra short
        if (x == width) {
            bytesBuffer.uInt16()
        }
    }
    // Return bytes from ImageDataBuffer for use in canvas object in client side
    return PixelIndices(width, height, pixels)
}