@file:Suppress("unused")

package com.bedalton.creatures.sprite.compilers

import com.bedalton.common.util.PathUtil
import com.bedalton.creatures.sprite.util.ColorEncoding
import com.bedalton.creatures.sprite.util.ColorEncoding.Companion.ENCODING_DEFAULT
import com.bedalton.creatures.sprite.util.PaletteTransform
import com.bedalton.creatures.sprite.util.swapAndRotateToIntC2e
import com.bedalton.io.bytes.ByteStreamWriter
import korlibs.image.bitmap.Bitmap32
import kotlin.math.ceil

@Suppress("MemberVisibilityCanBePrivate")
object BLKCompiler : SpriteCompiler {

    private const val SPRITE_HEADER_SIZE = 10 // 4 = format, 2 = Num images
    private const val IMAGE_HEADER_SIZE = 8 // 4 = offset to start of data, 2 = width, 2 = height
    private const val BLOCK_SIZE = 128
    private const val BLOCK_BYTE_SIZE = BLOCK_SIZE * BLOCK_SIZE * 2

    @Deprecated(
        "Use with keepBlack parameter",
        ReplaceWith("compileSpriteFromImageBytes(images, false, colorEncoding, callback")
    )
    override fun compileSpriteFromImageBytes(
        images: List<Pair<String, ByteArray>>,
        colorEncoding: ColorEncoding?,
        callback: ((pass: Int, current: Int, total: Int) -> Boolean?)?
    ): ByteArray {
        return compileSpriteFromImageBytes(images, false, colorEncoding, callback)
    }

    @Deprecated(
        "Use with keepBlack parameter",
        ReplaceWith("compileSpriteFromImageBytes(images, false, colorEncoding, callback")
    )
    override fun compileSpriteFromLoadedImages(
        images: List<Bitmap32>,
        colorEncoding: ColorEncoding?,
        callback: ((current: Int, total: Int) -> Boolean?)?
    ): ByteArray {
        return compileSpriteFromLoadedImages(images, false, colorEncoding, callback)
    }

    override fun compileSpriteFromImageBytes(
        images: List<Pair<String, ByteArray>>,
        keepBlack: Boolean,
        colorEncoding: ColorEncoding?,
        paletteTransform: PaletteTransform?,
        callback: ((pass: Int, current: Int, total: Int) -> Boolean?)?
    ): ByteArray {
        if (images.size > 1) {
            throw Exception("BLK compiler can only compile one image at a time")
        }
        val image = images.first()
        val extension = PathUtil.getExtension(image.first)
            ?: throw Exception("File '${image.first}' has no discernible extension")
        if (callback?.invoke(1, 0, 1) == false) {
            throw SpriteCompilerCancelledException("Cancelled BLK compiler during image loading phase")
        }
        val bitmap = ImageLoader.load(extension, image.second)
        callback?.invoke(1, 1, 1)
        return compileSprite(bitmap, keepBlack, colorEncoding, paletteTransform) { current, total ->
            callback?.invoke(2, current, total)
        }
    }

    override fun compileSpriteFromLoadedImages(
        images: List<Bitmap32>,
        keepBlack: Boolean,
        colorEncoding: ColorEncoding?,
        paletteTransform: PaletteTransform?,
        callback: ((current: Int, total: Int) -> Boolean?)?
    ): ByteArray {
        if (images.size > 1) {
            throw Exception("BLK compiler can only compile one image at a time")
        }
        return compileSprite(images.first(), keepBlack, colorEncoding, paletteTransform) { current, total ->
            if (callback?.invoke(current, total) == false) {
                throw SpriteCompilerCancelledException("Cancelled BLK compiler during compile phase")
            }
            true
        }
    }

    private fun compileSprite(
        image: Bitmap32,
        keepBlack: Boolean,
        colorEncoding: ColorEncoding?,
        paletteTransform: PaletteTransform?,
        callback: ((current: Int, total: Int) -> Boolean?)?
    ): ByteArray {
        val encoding = (colorEncoding ?: ENCODING_DEFAULT)

        val trueWidth = image.width
        val trueHeight = image.height
        val blocksWide = ceil(trueWidth / BLOCK_SIZE.toDouble()).toInt()
        val blocksHigh = ceil(trueHeight / BLOCK_SIZE.toDouble()).toInt()
        val blockCount = blocksWide * blocksHigh
        var imageOffset = SPRITE_HEADER_SIZE + (blockCount * IMAGE_HEADER_SIZE)

        val toInt = if (paletteTransform != null) {
            swapAndRotateToIntC2e(
                paletteTransform.red,
                paletteTransform.green,
                paletteTransform.blue,
                paletteTransform.swap,
                paletteTransform.rotation,
                encoding
            )
        } else {
            encoding.toInt
        }

        // Buffer size is
        return ByteStreamWriter.writeBytes {

            // Write header
            writeUInt32(encoding.marker)
            writeUInt16(blocksWide)
            writeUInt16(blocksHigh)
            writeUInt16(blockCount)

            /* Sub 4 due to an offset built in that does not account for the blocksWide and blocksHigh 4 bytes*/
            imageOffset -= 4

            // Write offsets
            repeat(blockCount) {
                writeUInt32(imageOffset)
                writeUInt16(BLOCK_SIZE)
                writeUInt16(BLOCK_SIZE)
                imageOffset += BLOCK_BYTE_SIZE
            }

            val actualCallback: ((current: Int, total: Int) -> Boolean?)? = callback?.let { it ->
                { current: Int, total: Int ->
                    if (it(current, total) == false) {
                        throw SpriteCompilerCancelledException("BLK compilation cancelled during compiler phase")
                    }
                    true
                }
            }
            actualCallback?.invoke(0, blockCount)

            repeat(blocksWide) { x ->
                repeat(blocksHigh) { y ->
                    writeCompiledSprite(
                        image,
                        trueWidth,
                        trueHeight,
                        x,
                        y,
                        this,
                        SpriteCompiler.getBlack(keepBlack),
                        toInt
                    )
                    actualCallback?.invoke(y * blocksWide + x, blockCount)
                }
            }
        }
    }

    private fun writeCompiledSprite(
        image: Bitmap32,
        trueWidth: Int,
        trueHeight: Int,
        cellX: Int,
        cellY: Int,
        buffer: ByteStreamWriter,
        black: Int,
        rgbToInt: (red: Int, green: Int, blue: Int) -> Int
    ): Long {
        val offsetX = cellX * BLOCK_SIZE
        val offsetY = cellY * BLOCK_SIZE
        val base = buffer.size
        repeat(BLOCK_SIZE) { yi ->
            val y = yi + offsetY
            repeat(BLOCK_SIZE) { xi ->
                val x = xi + offsetX
                if (y >= trueHeight || x >= trueWidth) {
                    buffer.writeUInt16(black)
                } else {
                    val pixel = image[x, y]
                    val alpha: Int = pixel.a
                    if (alpha < 127) {
                        buffer.writeUInt16(black)
                    } else {
                        val red: Int = pixel.r
                        val green: Int = pixel.g
                        val blue: Int = pixel.b
                        if (red + green + blue == 0) {
                            buffer.writeUInt16(black)
                        } else {
                            val subFrom =
                                0//arrayOf(((255 - alpha) * 0.7).toInt(), red - 2, green - 2, blue - 2).min()!!
                            val color = rgbToInt(red - subFrom, green - subFrom, blue - subFrom)
                            buffer.writeUInt16(color)
                        }
                    }
                }
            }
        }
        val written = buffer.size - base
        if (written != (128 * 128 * 2L)) {
            throw SpriteCompileException("Bytes written is incorrect. Expected: ${128 * 128 * 2}; Actual: $written")
        }
        return written
    }

}