package com.bedalton.common.ast.structs

import kotlinx.serialization.Serializable
import kotlin.js.JsExport
import kotlin.js.JsName

@JsExport
@Serializable
data class InsertReplaceEdit(
    /**
     * The string to be inserted.
     */
    @JsName("newText")
    val newText: String,

    /**
     * The range if the "insert" action is requested
     */
    @JsName("insert")
    val insert: Range,

    /**
     * The range if the "replace" action is requested.
     */
    @JsName("replace")
    val replace: Range,
): ITextEdit