@file:Suppress("unused")

package com.bedalton.creatures.sprite.parsers

import com.bedalton.common.exceptions.IOException
import com.bedalton.common.util.className
import com.bedalton.common.util.gcCollectIfMemoryConstrained
import com.bedalton.common.util.nullIfEmpty
import com.bedalton.creatures.sprite.util.ColorEncoding
import com.bedalton.creatures.sprite.util.PaletteTransform
import com.bedalton.creatures.sprite.util.SpriteType
import com.bedalton.creatures.sprite.util.mapAsync
import korlibs.image.bitmap.Bitmap32
import kotlinx.coroutines.CompletableDeferred
import kotlinx.coroutines.Deferred
import kotlinx.coroutines.GlobalScope
import kotlinx.coroutines.async
import kotlinx.coroutines.sync.Mutex
import kotlinx.coroutines.sync.withLock


const val SPRITE_DEBUG_LOGGING = "debug.sprite"


@Suppress("MemberVisibilityCanBePrivate")
/**
 * Abstract class representing a Sprite file
 * Holds sprite frame information
 */
abstract class SpriteFile(
    val spriteType: SpriteType,
    protected val keepBlack: Boolean,
    protected val paletteTransform: PaletteTransform?,
    private val progressChunkSize: Int?,
    private val progressCallback: ((current: Int, total: Int) -> Boolean?)? = null,
) {

    protected val extension: String get() = spriteType.extension

    private var closed = false

    private var closedAllChildren = false

    private var mFramesAsync: List<SpriteFrameAsync>? = null

    private var mDecodedFrames: List<Bitmap32>? = null

    private val mutex = Mutex()

    abstract val encoding: ColorEncoding

    private val mDecodedFramesSync: List<Bitmap32>
        get() {
            mDecodedFrames?.let {
                return it
            }
            val progressCallback = progressCallback
            val progressChunkSizeNotNull = progressChunkSize ?: PROGRESS_CHUNK_SIZE_DEFAULT
            val frames = getAsyncFrames()
            val size = frames.size
            progressCallback?.invoke(0, size)
//            Log.iIf(SPRITE_DEBUG_LOGGING) { "Getting frames in ${this::className}" }

            // Decode all frames
            return frames.mapIndexed { i, frame ->
                if (progressCallback != null && i % progressChunkSizeNotNull == 0) {
                    if (progressCallback(i, size) == false) {
                        throw SpriteParserCancelledException("Parse sprite was cancelled during compile")
                    }
                }
                frame.image(keepBlack)
            }.apply {
                mDecodedFrames = this
                progressCallback?.invoke(this.size, this.size)
                frames.forEach { frame -> frame.close() }
                closeFully()
            }
        }

    private val mDecodedFramesAsync: Deferred<List<Bitmap32>>
        get() {
            mDecodedFrames?.let {
                return CompletableDeferred(it)
            }
            val frames = getAsyncFrames()
            val progressCallback = progressCallback
            val progressChunkSizeNotNull = progressChunkSize ?: PROGRESS_CHUNK_SIZE_DEFAULT
            val size = frames.size
            progressCallback?.invoke(0, size)
//            Log.iIf(SPRITE_DEBUG_LOGGING) { "Getting frames in ${this::className}" }
            // Decode all frames
            return GlobalScope.async {
                var i = 0
                frames.mapAsync { frame ->
                    val image = frame.image(keepBlack)
                    i++
                    if (progressCallback != null && i % progressChunkSizeNotNull == 0) {
                        if (progressCallback(i, size) == false) {
                            throw SpriteParserCancelledException("Parse sprite was cancelled during compile")
                        }
                    }
                    image
                }.apply {
                    mDecodedFrames = this
                    progressCallback?.invoke(this.size, this.size)
                    frames.forEach { frame -> frame.close() }
                    closeFully()
                }
            }
        }

    protected abstract fun initFramesInternal(): List<SpriteFrameAsync>

    @Deprecated(
        "Use getAsyncFrames",
        replaceWith = ReplaceWith("getAsyncFrames()")
    )
    fun initFrames(): List<SpriteFrameAsync> {
        return getAsyncFrames()
    }

    fun getAsyncFrames(): List<SpriteFrameAsync> {
        mFramesAsync?.let {
            return it
        }
        if (closed) {
            throw IOException("Image stream already closed")
        }

        val frames = try {
            initFramesInternal()
        } catch (e: Exception) {
            throw SpriteParserException(
                "Failed to init frames for decode; ${e.className}${
                    e.message.nullIfEmpty()?.let { ": $it" } ?: ""
                }", e)
        }
        mFramesAsync = frames
        return frames
    }

    private var mSize: Int? = null

    fun size(): Int {
        mSize?.let {
            return it
        }
        mDecodedFrames?.size?.let {
            return it
        }
        return sizeInternal().apply {
            mSize = this
        }
    }

    protected abstract fun sizeInternal(): Int

    abstract val allowAsync: Boolean

    fun frames(): List<Bitmap32> {
        return mDecodedFramesSync
            .apply {
                mDecodedFrames = this
            }
    }

    suspend fun framesAsync()  = mutex.withLock {
        val progressCallback = progressCallback
        mDecodedFrames?.let { decoded ->
            val size = decoded.size
            progressCallback?.invoke(size, size)
            return decoded
        }
        mDecodedFramesAsync
            .await()
            .apply {
                mDecodedFrames = this
            }
    }

    /**
     * Close any streams, and release references to them
     */
    abstract fun closeInternal(): Boolean

    fun close(): Boolean {
        if (closed) {
            return true
        }
        mFramesAsync?.forEach(SpriteFrameAsync::close)
        mFramesAsync = null
        return closeInternal().also {
            gcCollectIfMemoryConstrained()
        }
    }

    /**
     * Try to fully close the file's stream and all its child frames
     */
    private fun closeFully() {
        if (closed) {
            return
        }
//        Log.iIf(SPRITE_DEBUG_LOGGING) { "Closing fully in ${this::className}" }
        closed = close()
        if (closed && !closedAllChildren) {
            closedAllChildren = true
        }
        if (!closed) {
            throw Exception("Failed to close byte stream")
        }
    }

    companion object {
        const val PROGRESS_CHUNK_SIZE_DEFAULT = 1
    }


}


