package com.bedalton.vfs.internal


import com.bedalton.io.bytes.ByteStreamReader
import com.bedalton.vfs.FileSystemActionsSurrogate

/**
 * Mostly unchecked raw file actions
 * Meant to be used exclusively internally by UnscopedFileSystem
 */
internal object FileSystemActions {

    private var mSurrogate: FileSystemActionsSurrogate? = null

    private val surrogate: FileSystemActionsSurrogate
        get() {
            mSurrogate?.let {
                return it
            }
            return FileSystemActionsSurrogate().apply {
                mSurrogate = this
            }
        }

    suspend fun readAsStreamReader(path: String): ByteStreamReader {
        return surrogate.readAsStreamReader(path)
    }

    suspend fun delete(path: String): Boolean {
        return surrogate.delete(path)
    }

    suspend fun fileExists(path: String): Boolean {
        return surrogate.fileExists(path)
    }

    suspend fun isDirectory(path: String): Boolean {
        return surrogate.isDirectory(path)
    }

    suspend fun md5(path: String): String? {
        return surrogate.md5(path)
    }

    suspend fun readBytes(path: String): ByteArray {
        return surrogate.readBytes(path)
    }

    suspend fun readBytes(path: String, offset: Long, length: Long): ByteArray {
        return surrogate.readBytes(path, offset, length)
    }

    suspend fun readTextWithWindowsCP1252Encoding(path: String): String {
        return surrogate.readTextWithWindowsCP1252Encoding(path)
    }

    suspend fun readTextWithUTF8Encoding(path: String): String {
        return surrogate.readTextWithUTF8Encoding(path)
    }

    suspend fun write(path: String, data: ByteArray, append: Boolean) {
        return surrogate.write(path, data, append)
    }

    suspend fun makeDirectory(path: String, recursive: Boolean): Boolean {
        return surrogate.makeDirectory(path, recursive)
    }

    suspend fun deleteDirectory(path: String): Boolean {
        return surrogate.deleteDirectory(path)
    }


    suspend fun getChildrenNonRecursive(directory: String): List<String>? {
        return surrogate.getChildrenNonRecursive(directory)
    }

    fun setSurrogate(surrogate: FileSystemActionsSurrogate) {
        mSurrogate = surrogate
    }

    fun clearSurrogate() {
        mSurrogate = null
    }
}