package com.bedalton.creatures.sprite.parsers

import com.bedalton.common.structs.AlreadyDisposedDataCacheException
import com.bedalton.common.util.PathUtil
import com.bedalton.creatures.sprite.util.ColorEncoding
import com.bedalton.creatures.sprite.util.ColorPalette.Companion.C1OpaqueBlack
import com.bedalton.creatures.sprite.util.ColorPalette.Companion.OPAQUE_BLACK
import com.bedalton.creatures.sprite.util.SpriteType
import com.bedalton.io.bytes.ByteStreamReader
import korlibs.image.bitmap.Bitmap32
import korlibs.image.format.PNG
import kotlinx.coroutines.sync.Mutex

private val palette = C1OpaqueBlack


class PhotoAlbumFile(
    filenameOrMoniker: String?,
    val reader: ByteStreamReader,
    progressChunkSize: Int = 1,
    progressCallback: ((i: Int, total: Int) -> Boolean?)? = null,
) : SpriteFile(
    spriteType = SpriteType.PHOTO_ALBUM,
    keepBlack = false,
    paletteTransform = null,
    progressChunkSize = progressChunkSize,
    progressCallback = progressCallback,
) {

    override val encoding: ColorEncoding
        get() = ColorEncoding.X_565

    private val mutex = Mutex()
    private var mFrames: List<SpriteFrameAsync>? = null
    val moniker: String? = when {
        filenameOrMoniker == null -> null
        filenameOrMoniker.trim().matches("^[a-fA-F0-9]{4}$".toRegex()) -> PhotoAlbum.creaturesHexMonikerToToken(
            filenameOrMoniker
        )

        else -> {
            try {
                val filename = PathUtil.getFileNameWithoutExtension(filenameOrMoniker)
                creaturesHexMonikerToToken(filenameOrMoniker)
            } catch (_: Throwable) {
                null

            }
        }
    }

    private var mSize: Int? = null

    constructor(
        reader: ByteStreamReader,
        progressChunkSize: Int = 1,
        progressCallback: ((i: Int, total: Int) -> Boolean?)? = null,
    ) : this(
        null,
        reader,
        progressChunkSize,
        progressCallback
    )

    fun photos(): List<SpriteFrameAsync> {
        return getAsyncFrames()
    }

    override fun initFramesInternal(): List<SpriteFrameAsync> {
        mFrames?.let {
            return it
        }

        val imagesCount = reader.uInt16()
        mSize = imagesCount
        val frames = (0 until imagesCount).map { i ->
            val image = readPhotoAlbumImageAsync(
                i,
                reader,
                imagesCount > 1
            )
            image
        }
        mFrames = frames
        return frames
    }

    override fun sizeInternal(): Int {
        return mSize ?: getAsyncFrames().size
    }

    override val allowAsync: Boolean
        get() = true

    override fun closeInternal(): Boolean {
        mFrames?.forEach(SpriteFrameAsync::close)
        return reader.close()
    }

    companion object {

        fun creaturesHexMonikerToToken(hexMoniker: String?): String? {
            if (hexMoniker == null || hexMoniker.length != 8) {
                return null
            }
            val out = StringBuilder()
            for (i in 0..3) {
                val charHex = hexMoniker.substring(i * 2, (i * 2) + 2)
                val charCode = charHex.toInt(16)
                out.append(charCode.toChar())
            }
            return out.reverse().toString()
        }
    }
}


private fun readPhotoAlbumImageAsync(
    i: Int,
    reader: ByteStreamReader,
    isOneOfMany: Boolean
): AlbumPhotoAsync {
    val timestamp = reader.sfcString()
    val paddedWidth = reader.uInt32().toInt()
    if (paddedWidth > 500) {
        throw SpriteParserException("Photo[$i] width is too great at $paddedWidth")
    }
    // Get and check height
    val height = reader.uInt32().toInt()
    if (height > 500) {
        throw SpriteParserException("Photo[$i] height is too great at $height")
    }

    // Get and check true width
    val trueWidth = reader.uInt32().toInt()
    if (trueWidth > 500) {
        throw SpriteParserException("Photo[$i] true width is too great at $trueWidth")
    }

    val imageBytes = reader.bytes(paddedWidth * height)
    val comment = if (reader.hasBytes(1) && reader.peakUInt8() == 0) {
        reader.sfcString()
    } else {
        ""
    }

    if (isOneOfMany) {
        if (reader.hasBytes(1) && reader.peakUInt8() == 0) {
            reader.skip(1)
        }
    }
    return AlbumPhotoAsync(
        trueWidth,
        height,
        timestamp,
        comment
    ) {
        getSprite(
            bytes = imageBytes,
            paddedWidth = paddedWidth,
            trueWidth = trueWidth,
            height = height,
            isOneOfMany = isOneOfMany
        )
    }
}

private fun getSprite(
    bytes: ByteArray,
    paddedWidth: Int,
    trueWidth: Int,
    height: Int,
    isOneOfMany: Boolean
): PixelIndices {
    return ByteStreamReader.read(bytes) {
        val pixels = IntArray(trueWidth * height) { 0 }
        val readAndSetPixel: ((x: Int, y: Int) -> Unit) = if (paddedWidth != trueWidth) {
            set@{ x: Int, y: Int ->
                val pixelInt = uInt8()
                if (x >= trueWidth) {
                    return@set
                }
                pixels[y * trueWidth + x] = pixelInt
            }
        } else {
            { x: Int, y: Int ->
                val pixelInt = uInt8()
                pixels[x + y * paddedWidth] = pixelInt
            }
        }
        repeat(height) { y ->
            repeat(paddedWidth) x@{ x ->
                if (isOneOfMany && y == height - 1 && x >= paddedWidth - 2) {
                    return@x
                }
                readAndSetPixel(x, height - y - 1)
            }
        }
        PixelIndices(trueWidth, height, pixels)
    }
}


class AlbumPhotoAsync(
    override val width: Int,
    override val height: Int,
    val timestamp: String,
    val comment: String?,
    getImage: () -> PixelIndices
) : SpriteFrameAsync {

    private var mImage: Bitmap32? = null
    private var buildIndices: (() -> PixelIndices)? = getImage
    private var indices: PixelIndices? = null

    override fun pixelIndices(): PixelIndices {
        indices?.let {
            return it
        }
        return buildIndices?.invoke()?.also {
            indices = it
        } ?: throw AlreadyDisposedDataCacheException("Album photo data has already been disposed")
    }

    @Deprecated("Use image(keepBlack: Boolean)",
        replaceWith = ReplaceWith("image(keepBlack = true)")
    )
    override fun image(): Bitmap32 {
        mImage?.let {
            return it
        }
        return pixelIndices().withPalette(C1OpaqueBlack).also {
            mImage = it
        }
    }

    /**
     * Gets the image using the default palette
     */
    override fun image(keepBlack: Boolean): Bitmap32 {
        mImage?.let {
            return it
        }

        return pixelIndices().withPalette(C1OpaqueBlack, OPAQUE_BLACK).also {
            mImage = it
        }
    }

    val unixDate by lazy {
        com.bedalton.creatures.common.util.creaturesDateToUnixTime(timestamp)
    }

    override fun close() {
        buildIndices = null
    }

    fun pngBytes(): ByteArray {
        return PNG.encode(image(true))
    }


    override fun flipX(): SpriteFrameAsync {
        return AlbumPhotoAsync(
            width,
            height,
            timestamp,
            comment
        ) {
            pixelIndices().flipX()
        }
    }

    override fun flipY(): SpriteFrameAsync {
        return AlbumPhotoAsync(
            width,
            height,
            timestamp,
            comment
        ) {
            pixelIndices().flipX()
        }
    }
    override fun dispose() {
        indices = null
        buildIndices = null
    }
}


