package com.bedalton.creatures.agents.pray.compiler.caos2pray.internal

import com.bedalton.creatures.agents.pray.compiler.NEWLINE_REGEX
import com.bedalton.creatures.agents.pray.compiler.data.Tag
import com.bedalton.creatures.agents.pray.compiler.data.TextValue

internal fun processScriptTag(
    mergeScripts: Boolean,
    linkedScripts: List<Tag.StringTag>,
): List<Tag<*>> {

    // Get scripts, combining if needed
    val scripts = if (mergeScripts) {
        val combined = linkedScripts
            .joinToString("\n\n") { tag ->
                tag.value.replace(NEWLINE_REGEX, "\n")
            }

        if (combined.isBlank()) {
            return emptyList()
        }

        val scriptTag: Tag<String> = Tag.StringTag(
            lineNumber = -1,
            startIndex = -1,
            endIndex = -1,
            tagRange = TextValue(
                "Script 1",
                lineNumber = -1,
                startIndex = -1,
                endIndex = -1
            ),
            value = TextValue(
                text = combined,
                lineNumber = 0,
                startIndex = -1,
                endIndex = -1
            )
        )
        listOf(scriptTag)
    } else {
        var index = 0
        linkedScripts.map { script ->
            script.copy(
                tagRange = script.tagRange.copy(
                    text = "Script ${++index}"
                )
            )
        }
    }

    // Script count string tag
    val scriptCountTag = Tag.IntTag(
        lineNumber = -1,
        startIndex = -1,
        endIndex = -1,
        tagRange = TextValue(
            "Script Count",
            lineNumber = -1,
            startIndex = -1,
            endIndex = -1,
        ),
        value = TextValue(
            text = scripts.size.toString(),
            lineNumber = 0,
            startIndex = -1,
            endIndex = -1
        ),
        tagValue = scripts.size
    )

    return scripts + scriptCountTag
}


