package com.creaturesforge.application

import com.bedalton.io.bytes.decodeBase64
import com.bedalton.io.bytes.toBase64
import com.creaturesforge.application.state.SpriteGlyph
import korlibs.image.bitmap.Bitmap32
import korlibs.image.format.PNG
import kotlinx.serialization.KSerializer
import kotlinx.serialization.SerializationException
import kotlinx.serialization.descriptors.*
import kotlinx.serialization.encoding.CompositeDecoder
import kotlinx.serialization.encoding.Decoder
import kotlinx.serialization.encoding.Encoder

internal object SpriteGlyphSerializer: KSerializer<SpriteGlyph> {
    override val descriptor: SerialDescriptor by lazy {
        buildClassSerialDescriptor("SpriteGlyph") {
            element<Int>("frame")
            element<String>("output_name")
            element<String>("sprite_name")
            element<Boolean>("manual")
        }
    }

    override fun deserialize(decoder: Decoder): SpriteGlyph {
        val descriptor = descriptor
        val ob = decoder.beginStructure(descriptor)
        var frame: Int? = null
        var outputName: String? = null
        var spriteName: String? = null
        var manual: Boolean? = null

        while (true) {
            when (val i = ob.decodeElementIndex(descriptor)) {
                0 -> frame = ob.decodeIntElement(descriptor, i)
                1 -> outputName = ob.decodeStringElement(descriptor, i)
                2 -> spriteName = ob.decodeStringElement(descriptor, i)
                3 -> manual = ob.decodeBooleanElement(descriptor, i)
                CompositeDecoder.DECODE_DONE -> break
                else -> throw SerializationException("Unknown index $i in SpriteGlyph")
            }
        }
        ob.endStructure(descriptor)
        val missing = mutableListOf<String>()

        if (frame == null) {
            missing.add("frame")
        }
        if (outputName == null) {
            missing.add("output_name")
        }
        if (spriteName == null) {
            missing.add("sprite_name")
        }
        if (manual == null) {
            missing.add("manual")
        }

        if (missing.isNotEmpty()) {
            throw SerializationException("SpriteGlyph is missing properties: $missing")
        }

        return SpriteGlyph.create(
            outputName!!,
            frame!!,
            spriteName!!,
            manual!!
        )
    }

    override fun serialize(encoder: Encoder, value: SpriteGlyph) {
        val descriptor = descriptor
        val ob = encoder.beginStructure(descriptor)
        ob.encodeIntElement(descriptor,0, value.frame)
        ob.encodeStringElement(descriptor, 1, value.filename)
        ob.encodeStringElement(descriptor, 2, value.spriteName)
        ob.encodeBooleanElement(descriptor, 3, value.manual)
        ob.endStructure(descriptor)
    }


}

object Bitmap32Serializer: KSerializer<Bitmap32> {

    override val descriptor: SerialDescriptor by lazy {
        PrimitiveSerialDescriptor("base64", PrimitiveKind.STRING)
    }

    override fun deserialize(decoder: Decoder): Bitmap32 {
        val code = decodeBase64(decoder.decodeString())
        return PNG.decode(code).toBMP32IfRequired()
    }

    override fun serialize(encoder: Encoder, value: Bitmap32) {
        val code = PNG.encode(value)
        encoder.encodeString(code.toBase64())
    }

}