package com.bedalton.vfs

import com.bedalton.vfs.internal.FileSystemActions
import com.bedalton.vfs.internal.fileExistsInternal
import com.bedalton.vfs.internal.isDirectoryInternal

actual open class UnscopedFileSystem : UnscopedFileSystemBase() {

    @Deprecated(
        "Root directory scopes are no longer checked",
        replaceWith = ReplaceWith("true")
    )
    override suspend fun accept(path: String): Boolean {
        return true
    }

    override suspend fun canDeleteDirectory(path: String): Boolean {
        return FileSystemActions.fileExists(path) && FileSystemActions.isDirectory(path)
    }

    override suspend fun canMakeDirectories(): Boolean {
        return true
    }

    override suspend fun write(path: String, data: ByteArray, append: Boolean) {
        FileSystemActions.write(path, data, append)
    }
}