@file:JvmName("Caos2PrayParserUtilKt")

package com.bedalton.creatures.agents.pray.compiler.caos2pray

import com.bedalton.common.util.*
import com.bedalton.creatures.agents.pray.compiler.*
import com.bedalton.creatures.agents.pray.compiler.data.Tag
import com.bedalton.creatures.agents.pray.compiler.data.TextValue
import com.bedalton.creatures.agents.pray.compiler.pray.PrayValidationError
import com.bedalton.creatures.agents.util.RelativeFileSystem
import com.bedalton.creatures.pray.parser.Caos2PrayLexer
import com.bedalton.creatures.pray.parser.Caos2PrayParser
import com.bedalton.vfs.FileNotFoundException
import kotlinx.coroutines.CoroutineScope
import org.antlr.v4.kotlinruntime.CharStreams
import org.antlr.v4.kotlinruntime.CommonTokenStream
import org.antlr.v4.kotlinruntime.tree.ParseTreeWalker
import kotlin.jvm.JvmName

/**
 * Responsible for parsing a CAOS2Pray file to data needed to construct an agent
 */
internal object Caos2PrayParserUtil {

    /**
     * Returns a pray data object, as well as a string for the original code without the CAOS2Pray tags statements
     *
     * @param coroutineScope parent context to use for parsing options
     * @param fs the file system to use for parsing this file
     * @param caosFile the filename or file contents of this CAOS2Pray file
     * @param opts parsing options
     * @return result of the CAOS2Pray file parse
     */
    suspend fun parse(
        coroutineScope: CoroutineScope,
        fs: RelativeFileSystem,
        caosFile: String,
        opts: PrayCompileOptions = PrayCompileOptionsImpl(),
    ): Caos2PrayResult {
        // Name of the file if `caosFile` is a file path
        val fileName = if (caosFile.contains('\n') || caosFile.contains('"') || caosFile.contains('*')) {
            // A file name is required, so one is generated based on contents of file
            "StringContents::" + MD5.compute(caosFile.encodeToByteArray()).toHexString()
        } else {
            caosFile
        }

        // Parse the CAOS2Pray file
        return parse(
            coroutineScope,
            fs,
            fileName,
            caosFile,
            opts
        )
    }

    /**
     * Parse
     *
     * @param coroutineScope the parent context to use when parsing this file
     * @param fs file system object to use when parsing this request
     * @param fullFilePath full path to the CAOS2Pray file
     * @param caosFile the file name or contents of a CAOS2Pray file
     * @param opts parsing options
     * @return result of the CAOS2Pray file parse
     */
    suspend fun parse(
        coroutineScope: CoroutineScope,
        fs: RelativeFileSystem,
        fullFilePath: String,
        caosFile: String,
        opts: PrayCompileOptions = PrayCompileOptionsImpl(),
    ): Caos2PrayResult {

        return parse(
            coroutineScope,
            fs,
            fullFilePath,
            caosFile,
            opts,
            false
        )
    }

    /**
     * Returns a pray data object, as well as a string for the original code, minus the CAOS2Pray tags
     * Joins are extra agents added to the main CAOS2Pray file
     *
     * @param coroutineScope the parent context to use when parsing this file
     * @param fs file system object to use when parsing this request
     * @param fullFilePath full path to the CAOS2Pray file
     * @param caosFile the file name or contents of a CAOS2Pray file
     * @param opts parsing options
     * @param isJoin whether this CAOS2Pray file is a join found in the Main CAOS2Pray file
     * @return result of the CAOS2Pray file parse
     */
    suspend fun parse(
        coroutineScope: CoroutineScope,
        fs: RelativeFileSystem,
        fullFilePath: String,
        caosFile: String,
        opts: PrayCompileOptions = PrayCompileOptionsImpl(),
        isJoin: Boolean
    ): Caos2PrayResult {

        // List of errors found while parsing
        val errors: MutableList<PrayValidationError> = mutableListOf()

        // Uses `caosFile` if is file content, or loads file contents from path
        val prayFileText = if (caosFile.contains('\n') || caosFile.contains("\"") || caosFile.contains("*")) {
            caosFile
        } else {
            if (!fs.fileExists(caosFile)) {
                throw FileNotFoundException("Failed to locate pray file at ${fs.path(caosFile)}")
            }
            fs.readAsText(caosFile)
        }

        // Get CAOS2Pray file walker to breakup script parts
        val walker = walkCaos2PrayFile(
            fullFilePath,
            prayFileText,
            errors,
            recursiveJoins = opts.recursiveJoinsNotNull,
            isJoin = isJoin
        )

        // Overriding file name if any (overrides output filename in CAOS2Pray file)
        val overrideFileName = opts.overrideAgentNameOrNull

        // Agent output name as defined in the Caos2Pray file or file name override if set
        val outputFileName = overrideFileName ?: walker.prayFileName

        // Verify has file name
        if (!isJoin && outputFileName == null) {
            errors.add(
                PrayValidationError.GeneralError(
                    message = "Pray file tag missing",
                    lineNumber = -1,
                    startIndex = -1,
                    endIndex = -1,
                    fullFilePath = fullFilePath,
                )
            )
        }

        // All scripts found in all blocks that are not removal scripts
        // (it.first == 1, means removal script)
        // (it.second is script content plus header (i.e. scrp, iscr, rscr))
        val script = walker
            .codeBlocks
            .filterNot { it.first == 1 }
            .joinToString("") { it.second }

        // Checks if block is more than block of comments
        val hasNonCommentBody = script.trim().split("\r?\n".toRegex())
            .any {
                !(it.isBlank() || it.trim().startsWith("*"))
            }

        // Combine all non-removal scripts in the file into a single script tag in a PRAY file
        val bodyScript = if (hasNonCommentBody) {
            val prefix =  if (opts.linkWithFilenameReferenceNotNull) {
                getLinkFilenameReferenceText(PathUtil.getLastPathComponent(caosFile) ?: caosFile)
            } else {
                ""
            }
            Tag.StringTag(
                lineNumber = walker.tags.maxOfOrNull { it.lineNumber } ?: 0,
                startIndex = -1,
                endIndex = -1,
                tagRange = TextValue(
                    "Script 99999999",
                    lineNumber = walker.tags.maxOfOrNull { it.lineNumber } ?: 0,
                    startIndex = -1,
                    endIndex = -1,
                ),
                value = TextValue(
                    text = "$prefix$script",
                    lineNumber = walker.tags.maxOfOrNull { it.lineNumber } ?: 0,
                    startIndex = -1,
                    endIndex = -1,
                ))
        } else {
            null
        }

        // Get remover script from walker result as a parse result string tag
        val remover = pullRemover(fullFilePath, opts, fs, walker, errors)

        // Gets all content as tags
        val tags = listOfNotNull(bodyScript) + walker.tags + listOfNotNull(remover)

        // Converts walker result into an object that can be compiled
        val prayData = walkerResultToPray(
            coroutineScope,
            fs = fs,
            fullFilePath = fullFilePath,
            agentNames = walker.agentNames,
            commands = if (remover != null) {
                walker.commands.filterNot { it.command == Caos2PrayCommands.RSCR }
            } else {
                walker.commands
            },
            tagsIn = tags,
            opts = opts,
            errors = errors,
            isJoin = isJoin
        )

        // Result of parse that can be used to build agent file
        return Caos2PrayResult(outputFileName, prayData)
    }
}

/**
 * Walks a CAOS2Pray file
 *
 * @param fullFilePath fully qualified path to the CAOS2Pray file
 * @param prayFileText text of CAOS2Pray file
 * @param errors errors found while parsing this file
 * @return pray file parse tree walker
 */
private fun walkCaos2PrayFile(
    fullFilePath: String,
    prayFileText: String,
    errors: MutableList<PrayValidationError>,
    recursiveJoins: Boolean,
    isJoin: Boolean,
): Caos2PrayWalker {
    // Parse tree walker for ANTLR file
    val walker = Caos2PrayWalker(
        fullFilePath,
        errors,
        recursiveJoin = recursiveJoins,
        isJoin = isJoin)
    val charStream = CharStreams.fromString(prayFileText)
    val lexer = Caos2PrayLexer(charStream)
    val tokenStream = CommonTokenStream(lexer)
    val parser = Caos2PrayParser(tokenStream)
    parser.addErrorListener(walker)
    ParseTreeWalker.DEFAULT.walk(walker, parser.file())
    return walker
}

/**
 * Extracts the removal script(s) as a PRAY tag object
 *
 * @param opts
 * @param fs file system to use when reading removal script
 * @param walker parse tree walker for CAOS2Pray file
 * @return Removal script as a PRAY file string tag
 */
private suspend fun pullRemover(
    fullFilePath: String,
    opts: PrayCompileOptions,
    fs: RelativeFileSystem,
    walker: Caos2PrayWalker,
    errors: MutableList<PrayValidationError>,
): Tag.StringTag? {

    // Create remover if any
    if (!opts.mergeRscr && walker.commands.none { it.command == Caos2PrayCommands.RSCR }) {
        return walker.codeBlocks
            .filter { it.first == 1 }
            .joinToString("\n") { it.second }
            .nullIfEmpty()
            ?.let { remover ->
                Tag.StringTag(
                    lineNumber = walker.tags.maxOfOrNull { it.lineNumber } ?: 0,
                    startIndex = -1,
                    endIndex = -1,
                    tagRange = TextValue(
                        "Remove script",
                        lineNumber = walker.tags.maxOfOrNull { it.lineNumber } ?: 0,
                        startIndex = -1,
                        endIndex = -1,
                    ),
                    value = TextValue(
                        text = remover,
                        lineNumber = walker.tags.maxOfOrNull { it.lineNumber } ?: 0,
                        startIndex = -1,
                        endIndex = -1,
                    ))
            }
    }

    var out: Tag.StringTag? = null
    val rscrCommands = walker.commands.filter { it.command == Caos2PrayCommands.RSCR }
    for (command in rscrCommands) {
        if (out != null) {
            errors.add(
                PrayValidationError.GeneralError(
                    command.lineNumber,
                    command.startIndex,
                    command.endIndex,
                    "Only one RSCR value is allowed",
                    fullFilePath
                )
            )
        }

        // Get only the first file specified
        val value = command.values.firstOrNull()
            ?: return null

        // Mark any extra command values on line as errors
        command.values.drop(1)
            .forEach {
                errors.add(
                    PrayValidationError.GeneralError(
                        it.lineNumber,
                        it.startIndex,
                        it.endIndex,
                        "Only one RSCR value is allowed",
                        fullFilePath
                    )
                )
            }

        // Get text from CAOS2Pray RSCR command
        val text = value.text.nullIfEmpty()
            ?: return null

        // Remove escapes if needed from tag text
        val path = text.superUnescape(' ', '\'', '\"')

        // Determine if text is a path
        val isPath = path.matches(".*\\.[a-zA-Z_]+$".toRegex()) ||
                fs.fileExists(path)

        // Get script text, reading from file if needed
        val scriptText = if (isPath) {
            fs.readAsText(path)
        } else {
            superUnescape(text)
        }

        // Format removal script as PRAY string tag
        out = Tag.StringTag(
            lineNumber = walker.tags.maxOfOrNull { it.lineNumber } ?: 0,
            startIndex = -1,
            endIndex = -1,
            tagRange = TextValue(
                "Remove script",
                lineNumber = walker.tags.maxOfOrNull { it.lineNumber } ?: 0,
                startIndex = command.startIndex,
                endIndex = command.endIndex,
            ),
            value = TextValue(
                text = scriptText,
                lineNumber = value.lineNumber,
                startIndex = value.startIndex,
                endIndex = value.endIndex,
            ))
    }
    return out
}

