package com.bedalton.creatures.genetics.gene

import com.bedalton.creatures.genetics.genome.Genome


fun AppearanceGene.isHead() = part == AppearanceGene.HEAD

fun AppearanceGene.isBody() = part == AppearanceGene.BODY

fun AppearanceGene.isLegs() = part == AppearanceGene.LEGS

fun AppearanceGene.isArms() = part == AppearanceGene.ARMS

fun AppearanceGene.isTail() = part == AppearanceGene.TAIL

fun AppearanceGene.isHair() = part == AppearanceGene.HAIR


fun Genome.genus(): Int? {
    return (genes.firstOrNull{ it is GenusGene } as GenusGene?)?.genus
}

fun List<Gene>.genus(): Int? {
    return (firstOrNull{ it is GenusGene } as GenusGene?)?.genus
}