@file:Suppress("unused")

package com.bedalton.creatures.breed.render.support.pose

import com.bedalton.creatures.common.structs.GameVariant
import kotlinx.serialization.Serializable
import kotlin.js.JsExport
import kotlin.js.JsName



@Serializable
@JsExport
data class Pose(
    @Suppress("NON_EXPORTABLE_TYPE")
    val variant: GameVariant,
    val headFacing: PoseFacing,
    val head: Tilt,
    val bodyFacing: PoseFacing,
    val body: Tilt,
    val leftThigh: Tilt,
    val leftShin: Tilt,
    val leftFoot: Tilt,
    val rightThigh: Tilt,
    val rightShin: Tilt,
    val rightFoot: Tilt,
    val leftUpperArm: Tilt,
    val leftForearm: Tilt,
    val rightUpperArm: Tilt,
    val rightForearm: Tilt,
    val tailBase: Tilt?,
    val tailTip: Tilt?,

    // Face
    val mood: Mood? = null,
    val eyesClosed: Boolean? = null,

    // Extra
    val itLocation: PoseFacing? = null
) {

    @JsName("construct")
    constructor(
        variant: String,
        headFacing: PoseFacing,
        head: Tilt,
        bodyFacing: PoseFacing,
        body: Tilt,
        leftThigh: Tilt,
        leftShin: Tilt,
        leftFoot: Tilt,
        rightThigh: Tilt,
        rightShin: Tilt,
        rightFoot: Tilt,
        leftUpperArm: Tilt,
        leftForearm: Tilt,
        rightUpperArm: Tilt,
        rightForearm: Tilt,
        tailBase: Tilt?,
        tailTip: Tilt?,
        mood: Mood? = null,
        eyesClosed: Boolean? = null,
        it: PoseFacing? = null
    ): this(
        GameVariant.fromString(variant)!!,
        headFacing,
        head,
        bodyFacing,
        body,
        leftThigh,
        leftShin,
        leftFoot,
        rightThigh,
        rightShin,
        rightFoot,
        leftUpperArm,
        leftForearm,
        rightUpperArm,
        rightForearm,
        tailBase,
        tailTip,
        mood,
        eyesClosed,
        it
    )

    fun toBuilder(): PoseBuilder {
        return PoseBuilder(variant, this)
    }

    // Example pose: 241000330022333
    fun toPoseString(): String {
        return PoseStringUtil.toPoseString(this)
    }

    fun get(part: String): Tilt? {
        return tilt(part[0])
    }

    @Suppress("NON_EXPORTABLE_TYPE")
    @JsName("getNoJS")
    operator fun get(part: Char): Tilt? {
        return tilt(part)
    }

    private fun tilt(part: Char): Tilt? {
        return when (part) {
            'a' -> head
            'b' -> body
            'c' -> leftThigh
            'd' -> leftShin
            'e' -> leftFoot
            'f' -> rightThigh
            'g' -> rightShin
            'h' -> rightFoot
            'i' -> leftUpperArm
            'j' -> leftForearm
            'k' -> rightUpperArm
            'l' -> rightForearm
            'm' -> tailBase
            'n' -> tailTip
            'o' -> head
            'p' -> head
            'q' -> head
            else -> null
        }
    }

    /**
     * Gets the sprite index for a given part's pose
     */
    @Suppress("NON_EXPORTABLE_TYPE")
    @JsName("spriteIndexNoJS")
    fun spriteIndex(part: Char): Int? {
        return PoseToSpriteIndex.getSpriteIndex(this, part)
    }

    /**
     * Gets the sprite index for a part's pose from a string with a single character in it
     */
    fun spriteIndex(part: String): Int? {
        return PoseToSpriteIndex.getSpriteIndex(this, part[0])
    }

    fun headFacingSnapped(): PoseFacing {
        val headFacing = headFacing
        val bodyFacing = bodyFacing

        val bodyFacingInt = bodyFacing.int
            ?: return headFacing

        val headFacingInt = headFacing.int
            ?: return bodyFacing

        if (headFacingInt == bodyFacingInt) {
            return headFacing
        }
        if (bodyFacingInt < 2 && headFacingInt < 2) {
            return bodyFacing
        }
        if (bodyFacingInt >= 2 && headFacingInt >= 2) {
            return bodyFacing
        }
        
        return headFacing
    }

    companion object {

        /**
         * Generate the default pose for a given variant
         */
        fun defaultPose(variantString: String): Pose {
            val variant = GameVariant.fromString(variantString)
                ?: throw PoseException("Variant '$variantString' is invalid; Expected: [C1,C2,CV,C3,DS]")
            return defaultPose(variant)
        }

        fun fromString(gameVariant: String, pose: String): Pose {
            return PoseStringUtil.fromPoseString(GameVariant.fromString(gameVariant) ?: GameVariant.C3, pose)
        }

        @Suppress("NON_EXPORTABLE_TYPE")
        @JsName("defaultPoseNoJS")
        fun defaultPose(variant: GameVariant): Pose {
            return Pose(
                variant = variant,
                bodyFacing = PoseFacing.VIEWER_RIGHT,
                headFacing = PoseFacing.VIEWER_RIGHT,
                head = Tilt.STRAIGHT,
                body = Tilt.UP,
                // Left Leg
                leftThigh = Tilt.UP,
                leftShin = Tilt.UP,
                leftFoot = Tilt.UP,
                // Right Leg
                rightThigh = Tilt.UP,
                rightShin = Tilt.UP,
                rightFoot = Tilt.UP,

                // Left Arm
                leftUpperArm = Tilt.STRAIGHT,
                leftForearm = Tilt.STRAIGHT,

                // Right Arm
                rightUpperArm = Tilt.STRAIGHT,
                rightForearm = Tilt.STRAIGHT,

                // Tail
                tailBase = Tilt.STRAIGHT,
                tailTip = Tilt.UP,

                mood = Mood.NORMAL,
                eyesClosed = false
            )
        }
    }
}