@file:Suppress("unused")

package com.bedalton.app

import com.bedalton.log.Log

sealed class DataType<T>(val name: String) {
    internal abstract fun write(store: PreferencesStore, key: String, value: T?)
    internal abstract fun read(store: PreferencesStore, key: String): T?

    object INT : SerializableType<Int>("Int") {

        override fun write(store: PreferencesStore, key: String, value: Int?) {
            store.setInt(key, value)
        }

        override fun serialize(value: Int): String {
            return value.toString()
        }

        override fun deserialize(value: String): Int {
            return value.toInt()
        }

        override fun read(store: PreferencesStore, key: String): Int? {
            return store.getInt(key)
        }
    }

    object FLOAT : SerializableType<Float>("Float") {
        override fun write(store: PreferencesStore, key: String, value: Float?) {
            store.setFloat(key, value)
        }

        override fun serialize(value: Float): String {
            return value.toString()
        }

        override fun deserialize(value: String): Float {
            return value.toFloat()
        }

        override fun read(store: PreferencesStore, key: String): Float? {
            return store.getFloat(key)
        }
    }

    object STRING : SerializableType<String>("String") {
        override fun write(store: PreferencesStore, key: String, value: String?) {
            store.setString(key, value)
        }

        override fun serialize(value: String): String {
            return value
        }

        override fun deserialize(value: String): String {
            return value
        }

        override fun read(store: PreferencesStore, key: String): String? {
            return store.getString(key)
        }
    }

    object BOOLEAN : SerializableType<Boolean>("Boolean") {
        override fun write(store: PreferencesStore, key: String, value: Boolean?) {
            store.setBoolean(key, value)
        }

        override fun serialize(value: Boolean): String {
            return value.toString().lowercase()
        }

        override fun deserialize(value: String): Boolean {
            return when (value.lowercase().trim()) {
                "1", "t", "true", "yes" -> true
                "0", "f", "false", "no" -> false
                else -> throw Exception("Invalid boolean serialized value: $value")
            }
        }

        override fun read(store: PreferencesStore, key: String): Boolean? {
            return store.getBoolean(key)
        }
    }

    class ListTypeWithNulls<T>(
        serialName: String,
        private val serialize: (T) -> String,
        private val deserialize: (String) -> T
    ) :
        DataType<List<T?>>(serialName) {

        constructor(type: SerializableType<T>) : this(
            type.name + "[]",
            type::serialize,
            type::deserialize
        )

        override fun write(store: PreferencesStore, key: String, value: List<T?>?) {
            if (value == null) {
                store.setString(key, null)
                return
            }
            val values = value.map {
                if (it != null) {
                    serialize(it)
                } else {
                    null
                }
            }

            // Find unique value for null
            var nullToken = "__!__NULLNULLNULL__!__"
            while (nullToken in values) {
                nullToken = "+null!_${nullToken}_!null+"
            }

            //Find delimiter that does not show up in any value or in the null token
            var delimiter = "__@@__"
            while (values.any { it != null && it.contains(delimiter) } || nullToken.contains(delimiter)) {
                delimiter = "x_${delimiter}_x"
            }

            val stringValue = values.joinToString(delimiter) { it ?: nullToken }
            store.setString(key, delimiter + delimiterDelimiter + nullToken + delimiterDelimiter + stringValue)
        }

        override fun read(store: PreferencesStore, key: String): List<T?>? {
            val raw = store.getString(key)
                ?.split(delimiterDelimiter, limit = 3)
                ?: return null
            if (raw.size < 2 || raw[0].isBlank() || raw[1].isBlank()) {
                Log.e { "Invalid list preference format for $key; Type: $name; Value: $raw" }
                return null
            }
            return if (raw.size != 3) {
                emptyList()
            } else if (raw[2].isEmpty()) {
                emptyList()
            } else {
                val delimiter = raw[0]
                val nullToken = raw[1]
                val valuesRaw = raw[2]
                valuesRaw.split(delimiter).map {
                    if (it == nullToken) {
                        null
                    } else {
                        deserialize(it)
                    }
                }
            }
        }

        companion object {
            private const val delimiterDelimiter: String = "<::::>"
        }
    }

    class ListType<T>(
        serialName: String,
        private val serialize: (T) -> String,
        private val deserialize: (String) -> T
    ) : DataType<List<T>>(serialName) {

        constructor(type: SerializableType<T>) : this(
            type.name + "[]",
            type::serialize,
            type::deserialize
        )

        override fun write(store: PreferencesStore, key: String, value: List<T>?) {
            if (value == null) {
                store.setString(key, null)
                return
            }
            var delimiter = "__@@__"
            val values = value.map(serialize)
            while (values.any { it.contains(delimiter) }) {
                delimiter = "x_${delimiter}_x"
            }
            val stringValue = values.joinToString(delimiter)
            store.setString(key, delimiter + delimiterDelimiter + stringValue)
        }

        override fun read(store: PreferencesStore, key: String): List<T>? {
            val raw = store.getString(key)
                ?.split(delimiterDelimiter, limit = 2)
                ?: return null
            if (raw.first().isEmpty()) {
                Log.e { "Invalid list preference format for $key; Type: $name; Value: $raw" }
                return null
            }
            return if (raw.size != 2) {
                emptyList()
            } else if (raw[1].isEmpty()) {
                emptyList()
            } else {
                raw[1].split(raw[0]).map(deserialize)
            }
        }

        companion object {
            private const val delimiterDelimiter: String = "<::::>"
        }
    }


    object StringList : DataType<List<String>>("StringList") {

        private const val delimiterDelimiter: String = "<::::>"
        override fun write(store: PreferencesStore, key: String, value: List<String>?) {
            var delimiter = "__@@__"
            if (value == null) {
                store.setString(key, null)
                return
            }
            while (value.any { it.contains(delimiter) }) {
                delimiter = "x_${delimiter}_x"
            }
            val stringValue = value.joinToString(delimiter)
            store.setString(key, delimiter + delimiterDelimiter + stringValue)
        }

        override fun read(store: PreferencesStore, key: String): List<String>? {
            val raw = store.getString(key)
                ?.split(delimiterDelimiter, limit = 2)
                ?: return null
            if (raw.first().isEmpty()) {
                Log.e { "Invalid string list preference value for $key; Type: $name; Value: $raw" }
                return null
            }
            return if (raw.size != 2) {
                emptyList()
            } else if (raw[1].isEmpty()) {
                emptyList()
            } else {
                raw[1].split(raw[0])
            }
        }
    }

    abstract class SerializableType<T>(name: String) : DataType<T>(name) {
        abstract fun serialize(value: T): String
        abstract fun deserialize(value: String): T
        override fun read(store: PreferencesStore, key: String): T? {
            return store.getString(key)?.let {
                deserialize(it)
            }
        }

        override fun write(store: PreferencesStore, key: String, value: T?) {
            return store.setString(key, value?.let { serialize(value) })
        }
    }

    @Deprecated(
        "Use SerializableType instead",
        replaceWith = ReplaceWith(
            "SerializableType(name)",
            imports = ["com.bedalton.app.DataType.SerializableType"]
        )
    )
    abstract class CustomType<T>(name: String) : SerializableType<T>(name)
}

open class Preference<T>(
    open val key: String,
    open val type: DataType<T>
) {
    fun write(store: PreferencesStore, value: T?) {
        type.write(store, key, value)
    }

    fun read(store: PreferencesStore): T? {
        return type.read(store, key)
    }
}

data class StringPreference(
    override val key: String
) : Preference<String>(key, DataType.STRING)

data class IntPreference(
    override val key: String
) : Preference<Int>(key, DataType.INT)

data class FloatPreference(
    override val key: String
) : Preference<Float>(key, DataType.FLOAT)

data class BooleanPreference(
    override val key: String
) : Preference<Boolean>(key, DataType.BOOLEAN)


data class ListPreference<T>(
    override val key: String,
    override val type: DataType.ListType<T>
) : Preference<List<T>>(key, type) {

    constructor(
        key: String,
        serialName: String,
        serialize: (T) -> String,
        deserialize: (String) -> T,
    ) : this(
        key,
        DataType.ListType<T>(serialName, serialize, deserialize)
    )

    constructor(
        key: String,
        type: DataType.SerializableType<T>
    ) : this(
        key,
        DataType.ListType<T>(type)
    )
}

data class StringListPreference(
    override val key: String,
) : Preference<List<String>>(key, DataType.StringList)


class Preferences(
    appKey: String,
    key: String,
) {

    constructor(key: String) : this("bedalton.creatures", key)

    private val store by lazy {
        PreferencesStoreImpl(appKey, key)
    }

    operator fun <T> set(preference: Preference<T>, value: T?) {
        preference.type.write(store, preference.key, value)
    }

    operator fun <T> get(preference: Preference<T>): T? {
        return preference.type.read(store, preference.key)
    }
}

interface PreferencesStore {
    fun setInt(key: String, value: Int?)
    fun setString(key: String, value: String?)
    fun setBoolean(key: String, value: Boolean?)
    fun setFloat(key: String, value: Float?)
    fun getInt(key: String): Int?
    fun getString(key: String): String?
    fun getBoolean(key: String): Boolean?
    fun getFloat(key: String): Float?
    fun delete(key: String)
    fun deletePreferencesFile(): Boolean
}

internal expect class PreferencesStoreImpl(
    appKey: String,
    settingsKey: String
) : PreferencesStore {
    override fun setInt(key: String, value: Int?)
    override fun setString(key: String, value: String?)
    override fun setBoolean(key: String, value: Boolean?)
    override fun setFloat(key: String, value: Float?)
    override fun getInt(key: String): Int?
    override fun getString(key: String): String?
    override fun getBoolean(key: String): Boolean?
    override fun getFloat(key: String): Float?
    override fun delete(key: String)
    override fun deletePreferencesFile(): Boolean
}


val loadPreferenceBytes: (suspend (path: String) -> ByteArray)? = null
val writePreferenceBytes: (suspend (path: String, bytes: ByteArray) -> Boolean)? = null

internal val nullString = byteArrayOf(0x00).decodeToString()