package com.bedalton.vfs.internal

import com.bedalton.common.exceptions.asThrowable
import com.bedalton.common.exceptions.rethrowCancellationException
import com.bedalton.io.bytes.*
import com.bedalton.log.Log
import kotlinx.coroutines.await
import tauri.fs.FsDirOptions
import tauri.fs.readBinaryFile

/**
 * Mostly unchecked raw file actions
 * Meant to be used exclusively internally by UnscopedFileSystem
 */
internal actual object FileSystemActionsBase {

    actual suspend fun readAsStreamReader(path: String): ByteStreamReader {
        return MemoryByteStreamReader(readBytes(path))
    }

    actual suspend fun delete(path: String): Boolean {
        return try {
            tauri.fs.removeFile(path).await()
            tauri.fs.exists(path).await()
        } catch (e: dynamic) {
            asThrowable(e).rethrowCancellationException()
            false
        }
    }

    actual suspend fun fileExists(path: String): Boolean {
        return fileExistsInternal(path)
    }

    actual suspend fun isDirectory(path: String): Boolean {
        return isDirectoryInternal(path)
    }

    actual suspend fun md5(path: String): String? {
        return try {
            val bytes = loadBytesInternal(path)
            MD5.compute(bytes).toHexString()
        } catch (err: dynamic) {
            val e = asThrowable(err)
            e.rethrowCancellationException()
            Log.e { "Failed to compute MD5 for file: $path. ${e.message}" }
            null
        }
    }

    actual suspend fun readBytes(path: String): ByteArray {
        return loadBytesInternal(path)
    }

    actual suspend fun readBytes(path: String, offset: Long, length: Long): ByteArray {
        return loadBytesInternal(path)
            .sliceArray(offset.toInt() .. (offset + length).toInt())
    }

    actual suspend fun readTextWithWindowsCP1252Encoding(path: String): String {
        return readBytes(path).decodeToWindowsCP1252()
    }

    actual suspend fun readTextWithUTF8Encoding(path: String): String {
        return readBytes(path).decodeToString()
    }

    actual suspend fun write(path: String, data: ByteArray, append: Boolean) {
        // Append is not natively supported, so you must read the existing file
        val outData = if (append && fileExistsInternal(path)) {
            loadBytesInternal(path) + data
        } else {
            data
        }
        try {
            tauri.fs.writeBinaryFile(path, outData.toUIntArray().buffer).await()
        } catch (e: dynamic) {
            throw asTauriThrowable(e)
        }
    }

    private suspend fun loadBytesInternal(filePath: String): ByteArray {
        val path = resolveResourcePath(filePath)
            ?: filePath
        try {
            return readBinaryFile(path).await().toByteArray()
        } catch (eRaw: dynamic) {
            throw asTauriThrowable(eRaw)
        }
    }


    actual suspend fun makeDirectory(path: String, recursive: Boolean): Boolean {
        makeDirInternal(path, recursive)
        return fileExists(path) && isDirectory(path)
    }

    actual suspend fun deleteDirectory(path: String): Boolean {
        val options = js("{}").unsafeCast<FsDirOptions>()
        options.recursive = true
        try {
            tauri.fs.removeDir(path, options)
        } catch (e: dynamic) {
            throw asTauriThrowable(e)
        }
        return !fileExists(path)
    }

    actual suspend fun getChildrenNonRecursive(directory: String): List<String>? {
        return getChildrenInternal(directory)
    }
}