@file:OptIn(DelicateCoroutinesApi::class)
@file:Suppress("unused")

import com.bedalton.common.exceptions.rethrowCancellationException
import com.bedalton.common.util.className
import com.bedalton.creatures.breed.render.renderer.JsBreedRendererBuilderBase
import com.bedalton.creatures.breed.render.renderer.PoseRenderer
import com.bedalton.creatures.breed.render.renderer.PoseStringRenderer
import com.bedalton.creatures.breed.render.support.pose.*
import com.bedalton.creatures.common.structs.GameVariant
import com.bedalton.creatures.sprite.util.dynamicToPaletteTransform
import korlibs.image.bitmap.Bitmap32
import korlibs.image.format.PNG
import kotlinx.coroutines.DelicateCoroutinesApi
import kotlinx.coroutines.GlobalScope
import kotlinx.coroutines.launch
import kotlin.js.Promise


/**
 * A Render function builder
 * The end goal is to produce a function that renders a pose object or pose string
 */
@JsExport
class JsRenderBuilder(variant: String): JsBreedRendererBuilderBase(variant) {

    /**
     * Build the pose renderer that this builder creates
     * The returned function renders a Pose or a String into PNG bytes
     * @return (pose: Pose|string) -> Promise<ByteArray>
     */
    fun buildPoseRenderer(padding: Int, defaultZoom: Double, paletteTransformJs: dynamic): (pose: Any, zoom: Double?) -> Promise<ByteArray> {
        val paletteTransform = dynamicToPaletteTransform(paletteTransformJs)
        var poseObjectRenderer: PoseRenderer? = null
        var poseStringRenderer: PoseStringRenderer? = null
        return { pose, zoom ->
            Promise { resolve, reject ->
                GlobalScope.launch {
                    // Build render for type Pose or String
                    val render: (suspend () -> Bitmap32?) = when (pose) {
                        is Pose -> {
                            // Render for pose object
                            {
                                val renderer = poseObjectRenderer ?: poseRenderer(padding, defaultZoom, paletteTransform).apply {
                                    poseObjectRenderer = this
                                }
                                renderer(pose, zoom)
                            }
                        }

                        is String -> {
                            // Render for pose string
                            {
                                val renderer = poseStringRenderer ?: poseStringRenderer(padding, defaultZoom, paletteTransform).apply {
                                    poseStringRenderer = this
                                }
                                renderer(pose, zoom)
                            }
                        }

                        else -> {
                            // Invalid type passed to renderer
                            val type = pose.className ?: jsTypeOf(pose)
                            val error = "Renderer expects pose of type Pose or String; Found: $type"
                            reject(PoseRenderException(error))
                            return@launch
                        }
                    }

                    // Actually render result
                    val result = try {
                        render()
                    } catch (e: Exception) {
                        e.rethrowCancellationException()
                        reject(Exception(e.message ?: "Failed to render pose", e))
                        return@launch
                    }

                    // Resolve or reject result
                    if (result != null) {
                        resolve(PNG.encode(result))
                    } else {
                        reject(Exception("Failed to render pose"))
                    }
                }
            }
        }
    }
}

/**
 * Creates a render function builder
 * After setting options, builder can compile a function to render poses
 */
@JsExport
fun createRenderBuilder(variant: String): JsRenderBuilder {
    return JsRenderBuilder(variant)
}

/**
 * Builds a pose builder for given variant
 * Calling build() on the pose builder creates a Pose object that can be used in the renderer
 */
@JsExport
fun poseBuilder(variantString: String): PoseBuilder {
    val variant = variantThrowing(variantString)
    return PoseBuilder(variant)
}

/**
 * Creates a pose builder from a previous pose
 * Calling build() on the pose builder creates a Pose object that can be used in the renderer
 */
@JsExport
fun poseBuilderWithPreviousPose(pose: Pose): PoseBuilder {
    return pose.toBuilder()
}


/**
 * Creates a pose builder with an initial pose set from a 15 char pose string
 * Calling build() on the pose builder creates a Pose object that can be used in the renderer
 */
@JsExport
fun poseBuilderWithPoseString(variantString: String, poseString: String): PoseBuilder {
    val variant = variantThrowing(variantString)
    val pose = PoseStringUtil.fromPoseString(variant, poseString)
    return PoseBuilder(variant, pose)
}


/**
 * Parses a variant, throwing if string is invalid
 */
private fun variantThrowing(variantString: String): GameVariant {
    return try {
        GameVariant.fromString(variantString)!!
    } catch (e: Exception) {
        e.rethrowCancellationException()
        throw PoseException("Invalid variant value $variantString; Expected: [C1,C2,CV,C3,DS]")
    }
}