import com.bedalton.common.util.nullIfEmpty
import com.bedalton.log.LOG_DEBUG
import com.bedalton.log.LOG_PROGRESS
import com.bedalton.log.LOG_VERBOSE
import com.bedalton.log.Log
import com.creaturesforge.application.interop.handleStartupRequests
import com.creaturesforge.application.interop.initTauriInterop
import com.creaturesforge.application.state.initVfsSwitches
import com.creaturesforge.application.ui.LoggerPanel
import com.creaturesforge.application.ui.html.ariaLabel
import com.creaturesforge.application.ui.pages.AppEggMode
import com.creaturesforge.application.ui.pages.Pages
import com.creaturesforge.application.util.LOG_STATUS
import com.creaturesforge.eggforge.util.EGG_FORGE_VERSION
import kotlinx.browser.document
import kotlinx.coroutines.*
import org.w3c.dom.HTMLElement
import tauri.app.getVersion


fun main() {
    init()
}

private fun init() = MainScope().launch {
    initLogging()
    initVfsSwitches()
    initTauriInterop()
    AppEggMode.init()
    Pages.init()
    handleStartupRequests()
    setVersionText(this)
    document.body!!.setAttribute("data-loading-main", "false")
}

private fun initLogging() {
    Log.setMode(LOG_VERBOSE, true)
    Log.setMode(LOG_DEBUG, true)
    Log.setMode(LOG_PROGRESS, true)
    Log.setMode(LOG_STATUS, true)
    LoggerPanel.initLoggerPanels()
}

private fun setVersionText(coroutineScope: CoroutineScope) = coroutineScope.launch {
    val theWindow = tauri.window.getCurrent()
    val tauriVersion = getVersion().await()
    val gradleVersion = EGG_FORGE_VERSION
    if (tauriVersion.lowercase() != gradleVersion.lowercase()) {
        Log.i("Kt/Tauri Mismatch; Kt: $gradleVersion; Tauri: $tauriVersion")
    }
    theWindow.setTitle("EggForge - v$tauriVersion")
    setVersionButtonText(tauriVersion)
}

private fun setVersionButtonText(version: String) {
    val button = document.getElementById("show-log-button") as HTMLElement?
        ?: return Unit.also {
            Log.e { "Failed to find show log button"}
        }

    val buttonText = button.innerText
    if (buttonText.lowercase() != version) {
        button.innerText = "v$version"
    }

    var ariaText = button.ariaLabel
    ariaText = ariaText
        ?.replace("{{ _version_ }}", version)
        ?.replace(Regex.escape(buttonText), version)
        .nullIfEmpty()
        ?: "v$version - Debug Log"
    button.ariaLabel = ariaText
}
