package com.bedalton.creatures.caos.collectors.internal

import com.bedalton.creatures.caos.collectors.CommandCall
import com.bedalton.creatures.caos.collectors.CaosParserItem
import com.bedalton.creatures.caos.collectors.CaosParserItem.WhitespaceItem
import com.bedalton.creatures.caos.libs.CaosLib

/**
 * Collects parser items in a CAOS file
 * @param lib CAOS definitions for a given CAOS variant
 * @param items a list of parsed tokens
 */
internal class CaosWalker(
    private val lib: CaosLib,
    originalText: String,
    items: Array<CaosParserItem>,
    private val checkCancelled: () -> Unit,
) {
    private val nonWhitespaceItems: Array<CaosParserItem?> = items
        .filter { it !is WhitespaceItem }
        .toTypedArray()

    private val commandWalker by lazy {
        CommandWalker(
            lib,
            originalText,
            nonWhitespaceItems,
            checkCancelled
        )
    } // Transforms values to parameter types as well

    val commandCalls: Array<CommandCall> get() = commandWalker.commandCalls

    val looseTokens: Array<CaosParserItem> get() = commandWalker.looseTokens

    val equalityStatements by lazy {
        commandWalker.equalityStatements
    }

    val equalityStatementRanges by lazy {
        commandWalker.equalityStatementRanges
    }

    val comments get() = commandWalker.comments

    val caos2Comments get() = commandWalker.caos2Comments
}