package com.creaturesforge.application.state

import com.bedalton.common.util.formatted
import com.bedalton.log.Log
import com.bedalton.vfs.UnscopedFileSystem
import com.bedalton.vfs.VfsSwitches
import com.bedalton.vfs.resourcePathOrPath
import com.creaturesforge.application.interop.tauriAsync
import com.creaturesforge.application.interop.tauriAsyncTyped
import com.creaturesforge.application.util.jsOb
import tauri.dialog.SaveDialogOptions

internal actual suspend fun addGno(path: String): Boolean {
    return tauriAsync("add_gno") {
        this.path = path
    }
}

private external interface Options<T> {
    @JsName("options")
    var options: T
}

@Suppress("USELESS_CAST")
internal suspend fun getSaveFilePath(opts: SaveDialogOptions): String? {
    return try {
        Log.i("Invoking TAURI\"save_file\"")
        val path = tauriAsyncTyped<Options<SaveDialogOptions>, dynamic>("save_file") {
            this.options = opts
        }
            ?: return null.also {
                Log.i("Invoke returned null result")
            }

        Log.i("Path is ${path::class.simpleName}")
        if (path is String) {
            path as String
        } else {
            null
        }
    } catch (e: Throwable) {
        Log.e("Get Save Path Failed: " + e.formatted())
        return null
    } catch (e: Error) {
        Log.e("Get Save Path Failed With Error. " + e.formatted())
        return null
    }
}

internal suspend fun getSaveFilePath(init: SaveDialogOptions.() -> Unit): String? {
    val options = jsOb(init)
    return getSaveFilePath(options)
}

internal fun initVfsSwitches() {
    VfsSwitches.ignoreScope = true
    VfsSwitches.pathsMustBeAbsolute = false
}

internal actual fun createFileSystem(): UnscopedFileSystem {
    return TauriFS()
}


private class TauriFS: UnscopedFileSystem() {

    override suspend fun read(path: String): ByteArray {
        val truePath = resourcePathOrPath(path)
        return super.read(truePath)
    }

    override suspend fun fileExists(path: String): Boolean {
        val truePath = resourcePathOrPath(path)
        return tauriAsync("file_exists") {
            this.path = truePath
        }
    }

    override suspend fun isDirectory(path: String): Boolean {
        return tauriAsync("is_directory") {
            this.path = path
        }
    }

    override suspend fun listAllFiles(
        path: String,
        recursive: Boolean,
        filter: ((path: String) -> Boolean)?
    ): List<String> {
        if (recursive) {
            Log.e("Cannot list files recursively in this scope; Path: $path")
        }
        return tauriAsync("list_files") {
            this.path = path
        }
    }

}