package com.bedalton.creatures.caos.collectors

import com.bedalton.common.util.nullIfEmpty
import com.bedalton.creatures.caos.antlr.CaosUniversalLexer
import com.bedalton.creatures.caos.antlr.CaosUniversalParser
import com.bedalton.creatures.caos.collectors.internal.ScriptOffsetsWalker
import com.bedalton.creatures.caos.collectors.internal.scriptOffsetsToScriptsArray
import org.antlr.v4.kotlinruntime.CharStreams
import org.antlr.v4.kotlinruntime.CommonTokenStream
import org.antlr.v4.kotlinruntime.tree.ParseTreeWalker


/**
 * Gets the script offsets within a CAOS file
 */
fun scriptOffsets(text: String): Array<BlockRange> {
    val charStream = CharStreams.fromString(text)
    val lexer = CaosUniversalLexer(charStream)
    val tokenStream = CommonTokenStream(lexer)
    val parser = CaosUniversalParser(tokenStream)
    val scriptOffsetListener = ScriptOffsetsWalker()
    ParseTreeWalker.DEFAULT.walk(scriptOffsetListener, parser.file())
    return scriptOffsetListener.scriptOffsets
}

fun getScriptsFromParseResult(parseResult: ParseResult): Array<Script> {
    if (parseResult.scripts.isNotEmpty()) {
        return parseResult.scripts
    }
    val scriptOffsets = scriptOffsets(parseResult.originalText)
        .nullIfEmpty()
        ?: return emptyArray()
    return scriptOffsetsToScriptsArray(scriptOffsets, parseResult.items)
}