import com.bedalton.common.ast.structs.RangeImpl
import com.bedalton.common.ast.structs.TextEditImpl
import com.bedalton.common.ast.structs.endLine
import com.bedalton.common.ast.structs.startLine
import com.bedalton.creatures.caos.collectors.CaosParserItem
import com.bedalton.creatures.caos.collectors.getWhitespace
import com.bedalton.creatures.caos.collectors.parseCaos
import com.bedalton.creatures.caos.exceptions.CaosException
import com.bedalton.creatures.caos.libs.ErrorTypes
