package com.bedalton.creatures.sprite.util

import korlibs.image.bitmap.Bitmap32
import korlibs.image.color.RGBA

internal val white by lazy { RGBA(255, 255, 255, 255) }
internal val black by lazy { RGBA(0, 0, 0, 255) }
internal const val trimBlackAlphaCutoff = 180

internal val transparentBlack by lazy { ColorPalette.TRANSPARENT_BLACK }
internal val opaqueBlack by lazy { ColorPalette.OPAQUE_BLACK }
private const val transparentRunMinWhite = 18

/**
 * Remove black and near black pixels surrounding the image
 */
fun Bitmap32.shrinkBlackBorder(keepBlack: Boolean): Bitmap32 {
    val black = if (keepBlack) {
        opaqueBlack
    } else {
        transparentBlack
    }
    return shrinkBlackBorder(black)
}

/**
 * Remove black and near black pixels surrounding the image
 */
fun Bitmap32.shrinkBlackBorder(transparentBlack: RGBA): Bitmap32 {
    val out = clone()
//    var shrankBlackBorder = false
    val done = (0 until width).associateWith {
        mutableMapOf<Int, Boolean>()
    }
    val blackAndWhite = out.blackAndWhite(transparentRunMinWhite)
    each { x, y ->
        var isBlack = done[x]!!.containsKey(y) && done[x]!![y]!!
        if (!isBlack && blackAndWhite.shouldBeTransparent(x, y, xUp = false, yUp = false, checked = done)) {
            isBlack = true
        }
        if (!isBlack && blackAndWhite.shouldBeTransparent(x, y, xUp = true, yUp = false, checked = done)) {
            isBlack = true
        }
        if (!isBlack && blackAndWhite.shouldBeTransparent(x, y, xUp = false, yUp = true, checked = done)) {
            isBlack = true
        }
        if (!isBlack && blackAndWhite.shouldBeTransparent(x, y, xUp = true, yUp = true, checked = done)) {
            isBlack = true
        }
        if (isBlack) {
//            shrankBlackBorder = true
            out[x, y] = transparentBlack
        }
    }
//    if (shrankBlackBorder) {
//        Log.iIf(LOG_VERBOSE) { "Shrank black border" }
//    }
    return out
}


/**
 * Checks if a pixel should be transparent
 * Which means pixel borders transparent pixels or
 * borders pixels that will be made transparent in
 * a chain leading up to transparent pixels
 */
private fun Bitmap32.shouldBeTransparent(x: Int, y: Int, xUp: Boolean, yUp: Boolean, checked: Map<Int, MutableMap<Int, Boolean>>): Boolean {
    // If past edge of image, return true,
    // as any black pixel leading up to the edge should be transparent
    if (x !in 0 until width || y !in 0 until height) {
        return true
    }

    // If cached value, return
    checked[x]!![y]?.let {
        return it
    }

    // Actual pixel value
    val pixel = get(x, y)

    // If pixel is actually transparent
    if (pixel.a < trimBlackAlphaCutoff) {
        checked[x]!![y] = true
        return true
    }
    // Determine if this pixel could be transparent
    val isBlack = pixel == black
    if (!isBlack) {
        // Pixel is not transparent or near black
        checked[x]!![y] = false
        return false
    }


    // Pixel is black and borders a transparent pixel,
    // or is in a chain of black pixels leading to a transparent pixel
    val nextX = x + (if (xUp) 1 else -1)
    val nextY = y + (if (yUp) 1 else -1)
    return shouldBeTransparent(nextX, nextY, xUp, yUp, checked)
}


/**
 * Turns each pixel either black or white based simply on the sum of its color components or alpha channel
 */
private fun Bitmap32.blackAndWhite(minWhite: Int = 382): Bitmap32 {
    return transformCopy { _, _, color ->
        color.blackAndWhite(minWhite)
    }
}

/**
 * Makes a pixel black or white based simply on the sum of its color components, or alpha channel
 */
private fun RGBA.blackAndWhite(minWhite: Int = 382): RGBA {
    return if (color.a > trimBlackAlphaCutoff) {
        val mod = (a / 255.0)
        if (((color.r * mod) + (color.g * mod)  + (color.b * mod)) > minWhite) {
            white
        } else {
            black
        }
    } else {
        black
    }
}