package com.bedalton.creatures.caos.libs

import kotlinx.serialization.Serializable
import kotlin.js.JsExport
import kotlin.js.JsName

/**
 * A concrete holder for data associated with a variant
 * Using a MAP failed under JS
 */
@Suppress("PropertyName")
@JsExport
@Serializable
data class MutableVariantData<T>(
    @JsName("C1")
    var C1: T? = null,
    @JsName("C2")
    var C2: T? = null,
    @JsName("CV")
    var CV: T? = null,
    @JsName("C3")
    var C3: T? = null,
    @JsName("DS")
    var DS: T? = null,
    @JsName("SM")
    var SM: T? = null
) {

    /**
     * Constructs an object using a MAP indexed by CAOS variant codes
     */
    @Suppress("unused")
    internal constructor(map: Map<String, T>): this(
        C1 = map["C1"],
        C2 = map["C2"],
        CV = map["CV"],
        C3 = map["C3"],
        DS = map["DS"],
        SM = map["SM"]
    )


    /**
     * Gets the value given a caos variant object
     */
    @JsName("valueForVariant")
    operator fun get(variant: CaosVariant): T? {
        return when(variant) {
            CaosVariant.C1 -> C1
            CaosVariant.C2 -> C2
            CaosVariant.CV -> CV
            CaosVariant.C3 -> C3
            CaosVariant.DS -> DS
            CaosVariant.SM -> SM
            else -> null
        }
    }

    /**
     * Get value for given variant string
     */
    operator fun get(variant: String): T? {
        return when(variant.uppercase()) {
            "C1" -> C1
            "C2" -> C2
            "CV" -> CV
            "C3" -> C3
            "DS" -> DS
            "SM" -> SM
            else -> null
        }
    }

    @JsName("setValueForVariantEnum")
    operator fun set(variant: CaosVariant, value: T?) {
        when(variant) {
            CaosVariant.C1 -> C1 = value
            CaosVariant.C2 -> C2 = value
            CaosVariant.CV -> CV = value
            CaosVariant.C3 -> C3 = value
            CaosVariant.DS -> DS = value
            CaosVariant.SM -> SM = value
            else -> throw Exception("Invalid variant")
        }
    }
    operator fun set(variant: String, value: T?) {
        when(variant.uppercase()) {
            "C1" -> C1 = value
            "C2" -> C2 = value
            "CV" -> CV = value
            "C3" -> C3 = value
            "DS" -> DS = value
            "SM" -> SM = value
            else -> throw Exception("Invalid variant: \"$variant\"")
        }
    }
}