package com.bedalton.creatures.agents.pray.compiler.caos2pray.internal

import co.touchlab.stately.collections.ConcurrentMutableSet
import co.touchlab.stately.concurrency.AtomicReference
import com.bedalton.common.coroutines.BackgroundDispatcher
import com.bedalton.common.structs.ITuple
import com.bedalton.common.structs.Tuple
import com.bedalton.common.util.toListOf
import com.bedalton.creatures.agents.pray.compiler.PrayCompileOptions
import com.bedalton.creatures.agents.pray.compiler.caos2pray.Caos2PrayCommands
import com.bedalton.creatures.agents.pray.compiler.caos2pray.Caos2PrayParserUtil
import com.bedalton.creatures.agents.pray.compiler.caos2pray.CommandValue
import com.bedalton.creatures.agents.pray.compiler.data.CompilerPrayData
import com.bedalton.creatures.agents.pray.compiler.toBuilder
import com.bedalton.creatures.agents.util.RelativeFileSystem
import com.bedalton.log.LOG_PROGRESS
import com.bedalton.log.Log
import com.bedalton.log.iWith
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.async
import kotlinx.coroutines.awaitAll


/**
 * Process JOIN and its JOIN commands
 *
 * @param fs
 * @param fullFilePath
 * @param opts
 * @param commands
 * @return
 */
internal suspend fun processJoins(
    coroutineScope: CoroutineScope,
    fs: RelativeFileSystem,
    fullFilePath: String,
    opts: PrayCompileOptions,
    commands: List<CommandValue>,
    isJoin: Boolean,
): List<ITuple<String, CompilerPrayData>> {
    // The actual path to this file
    val thisPath = fs.path(fullFilePath)

    // Do not join this file, if it has already been joined
    if (fs.path(thisPath).lowercase() in opts.joins) {
        return emptyList()
    }

    // Add joins to this options object
    val newOpts: PrayCompileOptions = opts
        .toBuilder()
        .withIsJoin(isJoin)
        .withJoins(opts.joins + fs.path(thisPath).lowercase())

    val atomicOpts = AtomicReference(newOpts)
    val files = ConcurrentMutableSet<String>()


    // Return all parsed pray data from all JOIN commands
    return commands
        .asSequence()
        .filter { it.command == Caos2PrayCommands.JOIN }
        .flatMap { command -> command.values.map { it.text } }
        .distinctBy { fs.path(it).lowercase() }
        .filter { fs.path(it).lowercase() !in opts.joins }
        .map commands@{ fileNode: String ->
            coroutineScope.async(BackgroundDispatcher) {
                // Get join result
                val (optsWithJoin, result) = processJoin(
                    coroutineScope,
                    fs,
                    fileNode,
                    files,
                    atomicOpts
                )
                files.add(fileNode)
                files.add(fs.path(fileNode))

                // Get opts with updated join information
                atomicOpts.set(optsWithJoin)

                // Return this join and all its contained joins
                result
            }
        }
        .toList()
        .awaitAll()
        .flatten()
        .distinct()
}

private val EMPTY_JOIN = emptyList<Tuple<String, CompilerPrayData>>()


/**
 * Processed a file used in JOIN command
 *
 * @param fs file system used to access data
 * @param fileName name of join file
 * @param opts current options object
 *
 * @Tuple::First = Opts with added filenames in Joins
 * @Tuple::Second::First = Join filename
 * @Tuple::Second::Second = Parsed Pray data for this Join
 *
 * @return this files pray data and all join data for its JOIN commands
 */
private suspend fun processJoin(
    coroutineScope: CoroutineScope,
    fs: RelativeFileSystem,
    fileName: String,
    files: ConcurrentMutableSet<String>,
    opts: AtomicReference<PrayCompileOptions>,
): Tuple<PrayCompileOptions, List<ITuple<String, CompilerPrayData>>> {

    // If file has already been joined, skip it
    if (fs.path(fileName).lowercase() in opts.get().joins) {
        return Tuple(opts.get(), EMPTY_JOIN)
    }

    var fileNameComponent: String = fileName
    var parentDirectory = ""
    if (fileName.contains('/') || fileName.contains('\\')) {
        val components = fileName.split("[\\\\/]".toRegex())
        fileNameComponent = components.last()
        parentDirectory = components.dropLast(1).joinToString("/")
    }

    val fsRelative = if (parentDirectory.isNotEmpty()) {
        fs.relativeFs(parentDirectory)
    } else {
        fs
    }

    Log.iWith(LOG_PROGRESS, true) { "Joining file: $fileName;" }

    // Parsed pray data for this JOIN
    val dataRaw = Caos2PrayParserUtil.parse(
        coroutineScope = coroutineScope,
        fs = fsRelative,
        fullFilePath = fileNameComponent,
        caosFile = fileNameComponent,
        opts = opts.get()
            .toBuilder()
            .withIsJoin(true)
            .withJoins(opts.get().joins + files.block { it.toTypedArray() }),
        isJoin = true,
    ).prayData

    val data = if (dataRaw.inlineFiles.isEmpty()) {
        dataRaw
    } else {
        val inlineFiles = dataRaw.inlineFiles
            .map { inlineFile ->
                val fileNameElement = inlineFile.inputFileName
                val fileNamePath = fileNameElement.text
                inlineFile.copy(
                    inputFileName = fileNameElement.copy(text = fsRelative.path(fileNamePath))
                )
            }
            .toTypedArray()
        dataRaw.copy(
            inlineFiles = inlineFiles
        )
    }

    // Tuple of filename and pray data
    val thisData = Tuple(fileName, data)

    files.addAll(opts.get().joins + data.joinedFiles.map { fs.path(it.first).lowercase() } + fs.path(fileName)
        .lowercase())


    // Opts with updated filenames
    val newOptsWithJoin = opts
        .get()
        .asJoin()
        .withJoins(files.block { it.toTypedArray() })

    // Combine this joined file, and all joins found in it
    return Tuple(
        newOptsWithJoin,
        ((thisData.toListOf() + data.joinedFiles)).distinctBy { fs.path(it.first).lowercase() }.toList()
    )
}