package com.bedalton.creatures.agents.pray.compiler

expect interface PrayCompileOptions {
    /**
     * Merge all scripts in pray files into one giant script
     */
    val mergeScripts: Boolean

    /**
     * Merge all removal scripts from all files into a single removal script
     */
    val mergeRscr: Boolean

    /**
     * Automatically generate script removers for all scripts in pray file
     */
    val generateScriptRemovers: Boolean

    /**
     * Create removers for all created agent classifiers
     * Parses new: (simp|comp|*) creation statements and generates a remover for that class
     */
    val generateAgentRemovers: Boolean

    /**
     * Whether to validate syntax and existence of inline files
     */
    val validate: Boolean

    /**
     * Whether this agent is meant to be joined into a multi-agent bundle
     */
    val isJoin: Boolean

    /**
     * Flag this pray task as producing an agent should be inlined into a single multi-agent bundle
     */
    fun asJoin(): PrayCompileOptions

    /**
     * List of pray files to inline as children in this single file multi-agent bundle
     */
    fun withJoins(joins: Array<String>): PrayCompileOptions

    /**
     * PRAY source files for agents to be inlined into a single multi-agent bundle
     */
    val joins: Array<String>

    /**
     * Amount of GZIP compression to apply [0-9] or [null or -1] = use default
     */
    val compressionLevel: Int?
}

fun PrayCompileOptions.toBuilder(pure: Boolean = false): PrayCompilerOptionsBuilder {
    return PrayCompilerOptionsBuilder(this, pure)
}