@file:Suppress("unused")

package com.bedalton.creatures.agents.pray.data

import com.bedalton.common.structs.AlreadyDisposedDataCacheException
import com.bedalton.creatures.agents.pray.exceptions.PrayDataBlockDecompressionException
import com.bedalton.creatures.agents.pray.internal.bytesToStreamSimple
import com.bedalton.creatures.agents.pray.internal.getBytesFromStream
import com.bedalton.creatures.agents.pray.parser.PRAY_BLOCK_COMPRESS_FLAG
import com.bedalton.io.bytes.ByteStreamReader
import com.bedalton.io.bytes.ByteStreamWriter
import com.bedalton.io.bytes.Compressor


class DataBlock(
    val commonName: String,
    blockTag: String,
    blockName: String,
    bytes: () -> ByteArray?,
) : PrayBlock(blockTag, blockName) {

    private var disposed = false
    private var mBytes: (() -> ByteArray?)? = bytes

    internal constructor(
        commonName: String,
        blockTag: String,
        blockName: String,
        stream: ByteStreamReader,
        byteStart: Int,
        byteEnd: Int,
        decompressedLength: Int,
        compressed: Boolean,
        cacheBytes: Boolean,
    ) : this(commonName, blockTag, blockName, getBytesFromStream(stream, byteStart, byteEnd, decompressedLength, compressed, cacheBytes))

    internal constructor(
        commonName: String,
        blockTag: String,
        blockName: String,
        data: ByteArray?,
        compressed: Boolean = false,
    ) : this(commonName, blockTag, blockName, bytesToStreamSimple(data, compressed))

    private var mRawData: ByteArray? = null

    private val mData: ByteArray? by lazy {
        if (disposed) {
            throw AlreadyDisposedDataCacheException("Pray Block: ${blockTag}: $blockName already disposed")
        }
        val theBytes = mBytes
            ?: throw AlreadyDisposedDataCacheException("Pray Block: ${blockTag}: $blockName data function already disposed")
        try {
            theBytes().apply {
                this@DataBlock.mBytes = null
            }
        } catch (e: PrayDataBlockDecompressionException) {
            mRawData = e.originalBytes
            throw e
        }
    }

    fun data(): ByteArray? = mData

    fun dispose() {
        if (disposed) {
            return
        }
        this.disposed = true
        mBytes = null
    }

    override fun write(writer: ByteStreamWriter, compress: Boolean) {
        var originalBytes: ByteArray? = null
        var expectedDecompressedSize: Int? = null
        val data: ByteArray? = try {
            data() ?: throw Exception("Cannot write data block without data for block $label")
        } catch (e: PrayDataBlockDecompressionException) {
            originalBytes = e.originalBytes
            expectedDecompressedSize = e.expectedDecompressedSize
            null
        }
        writer.writeStringWithCreaturesEncoding(blockTag)
        writer.writeStringWithCreaturesEncoding(blockName.padEnd(128, 0.toChar()))
        val compressed: ByteArray?
        if (data != null) {
            val contentsFullLength = data.size
            writer.writeUInt32(contentsFullLength)
            compressed = if (compress) Compressor.compress(data) else null
            val compressedLength = compressed?.size ?: contentsFullLength
            // write compressed length
            writer.writeUInt32(compressedLength)
        } else {
            val contentsFullLength = expectedDecompressedSize!!
            writer.writeUInt32(contentsFullLength)
            compressed = originalBytes!!
            val compressedLength = compressed.size
            // write compressed length
            writer.writeUInt32(compressedLength)
        }
        // Write 1 if compressed
        writer.writeUInt32(if (compressed != null) PRAY_BLOCK_COMPRESS_FLAG else 0)

        // Write bytes
        writer.write(compressed ?: data ?: originalBytes!!)
    }
}

