@file:Suppress("unused")

package com.bedalton.common.util

expect fun gcCollect()

fun gcCollectIfMemoryConstrained() {
    if (mMemoryConstrained) {
        gcCollect()
    }
}

private var mMemoryConstrained = false

val isMemoryConstrained: Boolean
    get() = mMemoryConstrained

fun setIsMemoryConstrained(value: Boolean) {
    mMemoryConstrained = value
}

