@file:Suppress("unused")

package com.bedalton.creatures.breed.render.support.render

import com.bedalton.common.geometry.Point
import com.bedalton.common.geometry.minus
import com.bedalton.common.geometry.plus
import com.bedalton.common.structs.HasSize
import com.bedalton.creatures.breed.render.support.att.AttFileLine
import com.bedalton.creatures.breed.render.support.pose.PoseException

/**
 * Data class holding information needed to render a single part in a single pose
 */
@Suppress("MemberVisibilityCanBePrivate")
data class PoseRenderFrameData<ImageT> (
    val part: Char,
    val image: ImageT,
    val attFileLine: AttFileLine,
    val offset: Point? = null,
    val size: HasSize,
    var visibility: PartVisibility? = null
) {
    fun getPoint(point: Int): Point {
        return attFileLine[point]
    }

    fun getOffsetPoint(point: Int): Point {
        if (offset == null) {
            throw PoseException("Cannot get offset point without initial offset")
        }
        return attFileLine[point] + offset
    }

    fun getOffsetPoint(parentOffset: Point, point: Int): Point {
        return attFileLine[point] + parentOffset
    }

    fun withAttachedAt(parentAttPoint: Point): PoseRenderFrameData<ImageT> {
        return copy(
            offset = pointAttachedAt(parentAttPoint)
        )
    }

    fun withVisibility(visibility: PartVisibility): PoseRenderFrameData<ImageT> {
        return copy(
            visibility = visibility
        )
    }

    fun pointAttachedAt(parentAttPoint: Point): Point {
        return parentAttPoint - attFileLine[0]
    }
}