package com.bedalton.creatures.caos.formatter

import com.bedalton.common.ast.formatter.CaosFormatterOptions
import com.bedalton.common.ast.formatter.CaosFormatterOptionsImpl
import com.bedalton.common.ast.formatter.isWhitespace
import com.bedalton.common.ast.structs.TextEdit
import com.bedalton.common.ast.structs.contains
import com.bedalton.creatures.caos.collectors.CommandCall
import com.bedalton.creatures.caos.collectors.ParseResult
import com.bedalton.creatures.caos.collectors.CaosParserItem
import com.bedalton.creatures.caos.utils.token

internal class FormatterState(
    private val opts: CaosFormatterOptionsImpl,
    private val parseResult: ParseResult,
    internal val whiteSpaceItems: List<CaosParserItem>,
) : CaosFormatterOptions {

    /**
     * Commands waiting before short de-denting
     */
    val waiting: MutableList<List<Int>> = mutableListOf()

    // Whether
    var lastLine: Int = -1
    val out: StringBuilder = StringBuilder()
    val edits: MutableList<TextEdit> = mutableListOf()
    val editReasons: MutableList<EditReason> = mutableListOf()

    val lastItem: CaosParserItem? get() = if (index > 0) {
        items[index - 1]
    } else {
        null
    }

    private val itemsCount by lazy {
        items.size
    }

    val hasNext get() = itemsCount > index + 1
    var continuations: Int = 0
    private val commandCalls: List<CommandCall> by lazy {
        parseResult.commandCalls.filter { it.command.isCommand }.sortedBy { it.textRange.startIndex }
    }
    val allCommands get() = parseResult.commandCalls
    val equalityStatements by lazy { parseResult.equalityStatements }
    val equalityStatementRanges get() = parseResult.equalityStatementRanges
    val equalityStatementGroups by lazy {
        equalityStatementRanges.map { range ->
            Pair(range, equalityStatements.filter { range.contains(it.textRange) })
        }
    }

    val scriptStarts by lazy {
        val endm = token("endm")
        parseResult.scripts
            .filter { (it.items.lastOrNull() as? CaosParserItem.CommandToken)?.token == endm }
            .mapNotNull { it.items.firstOrNull()?.textRange?.startIndex }
    }
    val blockLevelCommandCalls: MutableList<IntRange> by lazy {
        getCommandRanges()
    }
    var eqIndents: Int = 0
    var index = -1
//    val lastIndex: Int get() = index - 1
    var newlineLast = false

//    private val scriptEndIndices: MutableList<Pair<Int, Boolean>> = parseResult.scripts
//        .map {
//            val endm = (it.items.lastOrNull() as? ParserItem.CommandToken)?.token == Formatter.ENDM
//            Pair(it.textRange.endIndex, endm)
//        }
//        .sortedBy {
//            it.first
//        }
//        .toMutableList()

    private val items by lazy {
        (whiteSpaceItems + parseResult.items).sortedBy { it.textRange.startIndex }
    }

    val variant = opts.variant

    val tab = if (opts.insertSpaces) {
        " ".repeat(opts.tabSize)
    } else {
        "\t"
    }

    val currentTab
        get() = tab.repeat(waiting.size) +
                continuationTab.repeat(continuations) +
                continuationTab.repeat(eqIndents)



    fun peak(distance: Int = 1): CaosParserItem? {
        if (index + distance !in items.indices) {
            return null
        }
        return items[index + distance]
    }

    @Suppress("unused")
    fun lastNotWhitespace(distance: Int = -1): CaosParserItem? {
        var i = index + distance
        while (i in items.indices) {
            val item = items[i--]
            if (!item.isWhitespace()) {
                return item
            }
        }
        return null
    }

    fun last(distance: Int = -1, filter: (i: CaosParserItem)->Boolean): CaosParserItem? {
        var i = index + distance
        while (i in items.indices) {
            val item = items[i--]
            if (filter(item)) {
                return item
            }
        }
        return null
    }

    @Suppress("unused")
    fun nextNotWhitespace(distance: Int = 1): CaosParserItem? {
        var i = index + distance
        while (i in items.indices) {
            val item = items[i++]
            if (!item.isWhitespace()) {
                return item
            }
        }
        return null
    }

    fun next(distance: Int = 1, filter: (i: CaosParserItem)->Boolean): CaosParserItem? {
        var i = index + distance
        while (i in items.indices) {
            val item = items[i++]
            if (filter(item)) {
                return item
            }
        }
        return null
    }


    fun formatted() = out.toString()

    fun next(): CaosParserItem? {
        if (index + 1 >= items.size) {
            return null
        }
        return items[++index]
    }

    /**
     * Size of a tab in spaces.
     */
    override val tabSize: Int
        get() = opts.tabSize

    override val continuationIndent: Int
        get() = opts.continuationIndent

    private val continuationTab: String = if (opts.insertSpaces) {
        " ".repeat(if (opts.continuationIndent == 0) opts.tabSize else opts.continuationIndent)
    } else {
        "\t".repeat(if (opts.continuationIndent == 0) opts.tabSize else opts.continuationIndent)
    }

    /**
     * Prefer spaces to tabs.
     */
    override val insertSpaces: Boolean
        get() = opts.insertSpaces

    /**
     * Trim whitespace at the end of the formatted script
     */
    override val trimTrailingWhitespace: Boolean
        get() = opts.trimTrailingWhitespace

    /**
     * Insert a newline at the end of the formatted text
     */
    override val insertFinalNewline: Boolean
        get() = opts.insertFinalNewline

    /**
     * Trim final new lines at end of formatted script
     */
    override val trimFinalNewlines: Boolean
        get() = opts.trimFinalNewlines

    /**
     * Allow caos commands to stay on the same line
     */
    override val keepSameLine: Boolean
        get() = opts.keepSameLine

    override val maxBlankLines: Int by lazy {
        @Suppress("unused")
        if (opts.maxBlankLines < 0) {
            Short.MAX_VALUE.toInt()
        } else {
            opts.maxBlankLines
        }
    }

    override val indentComments: Boolean
        get() = opts.indentComments

    /**
     * Whether to add inner spaces between items in a byte-string
     * [ 1 2 3 ] or [1 2 3]
     */
    override val spaceBetweenByteStingBrackets: Boolean =
        variant != "C1" && variant != "C2" && opts.spaceBetweenByteStingBrackets

    val newLines: String = opts.newLineChar.repeat(opts.minBlankLines + 1)

    override val minBlankLines: Int get() = opts.minBlankLines

    override val newLineChar: String
        get() = opts.newLineChar

    override val forceMinBlankLinesAfterComments: Boolean
        get() = opts.forceMinBlankLinesAfterComments

    private fun getCommandRanges(): MutableList<IntRange> {
        val eqStatements = parseResult.equalityStatementRanges
        val requiresCondition: List<Int> = listOf(token("doif"), token("elif"), token("asrt"))

        val commandCallRanges = mutableListOf<IntRange>()
        for (i in commandCalls.indices) {
            val command = commandCalls[i]
            if (command.tokens.last().token in requiresCondition) {
                val next = commandCalls.getOrNull(i + 1)?.textRange
                val commandRange = command.textRange.startIndex until (next?.startIndex ?: Int.MAX_VALUE)
                val eqs = eqStatements.filter { it.startIndex in commandRange }
                commandCallRanges.add(command.textRange.startIndex .. (eqs.lastOrNull() ?: command.textRange).endIndex)
            } else {
                commandCallRanges.add(command.textRange.startIndex .. command.textRange.endIndex)
            }
        }
        // Get all block level command call index ranges
        return commandCallRanges
            .sortedBy { it.first }
            .toMutableList()
    }

    companion object {
        @Suppress("unused")
        private const val TAG = "FormatterState"
    }

}


