@file:Suppress("unused")

package com.bedalton.vfs
import com.bedalton.common.exceptions.IOException
import com.bedalton.common.util.PathUtil
import com.bedalton.io.bytes.ByteStreamReader
import kotlin.js.JsName

interface OutsideFileBase {

    /**
     * Deletes a file from the file system
     * @throws IOException
     */
    suspend fun delete(path: String): Boolean

    /**
     * Checks whether a given file exists
     */
    suspend fun fileExists(path: String): Boolean

    /**
     * Checks if a path points to a directory
     */
    suspend fun isDirectory(path: String): Boolean
}

/**
 * Generic interface for an object that can write files as bytes
 */
interface OutsideFileWriter : OutsideFileBase {
    /**
     * Writes bytes to a file possibly appending
     * @throws IOException
     */
    suspend fun write(path: String, data: ByteArray, append: Boolean = false)

    /**
     * Writes text to a file
     * @throws IOException
     */
    suspend fun write(path: String, text: String, append: Boolean = false) {
        write(path, text.encodeToByteArray(), append)
    }
}

/**
 * Generic interface for an object that can read files as bytes
 */
interface OutsideFileReader : OutsideFileBase {

    /**
     * Reads all bytes from a given file
     * @throws IOException
     */
    suspend fun read(path: String): ByteArray

    /**
     * Reads a section of bytes from a file
     * @throws IOException
     */

    @JsName("readWithRange")
    suspend fun read(path: String, offset: Long, length: Long): ByteArray?

    /**
     * Reads a file or object as a stream reader.
     * Stream reader type is implementation specific
     */
    suspend fun readAsStreamReader(path: String): ByteStreamReader

    /**
     * Reads the entire contents of a file as UTF8 text
     * @throws IOException
     */
    suspend fun readTextUTF8(path: String): String

    /**
     * Reads the entire contents of a file as UTF8 text
     * @throws IOException
     */
    suspend fun readTextWindowsCP1252(path: String): String

    /**
     * Get MD5 of file at path
     */
    suspend fun md5(path: String): String?
}


open class RelativeFileWriter(private val basePath: String, private val writer: OutsideFileWriter) : OutsideFileWriter {
    override suspend fun write(path: String, data: ByteArray, append: Boolean) {
        writer.write(PathUtil.combine(basePath, path), data, append)
    }

    override suspend fun delete(path: String): Boolean {
        return writer.delete(PathUtil.combine(basePath, path))
    }

    override suspend fun fileExists(path: String): Boolean {
        return writer.fileExists(PathUtil.combine(basePath, path))
    }

    override suspend fun isDirectory(path: String): Boolean {
        return writer.isDirectory(PathUtil.combine(basePath, path))
    }

}

open class RelativeFileReader(
    private val basePath: String,
    private val reader: OutsideFileReader,
): OutsideFileReader {
    override suspend fun read(path: String): ByteArray {
        return reader.read(PathUtil.combine(basePath, path))
    }

    override suspend fun read(path: String, offset: Long, length: Long): ByteArray? {
        return reader.read(PathUtil.combine(basePath, path), offset, length)
    }

    override suspend fun readTextWindowsCP1252(path: String): String {
        return reader.readTextWindowsCP1252(PathUtil.combine(basePath, path))
    }

    override suspend fun readTextUTF8(path: String): String {
        return reader.readTextUTF8(PathUtil.combine(basePath, path))
    }

    override suspend fun delete(path: String): Boolean {
        return reader.delete(PathUtil.combine(basePath, path))
    }

    override suspend fun fileExists(path: String): Boolean {
        return reader.fileExists(PathUtil.combine(basePath, path))
    }

    override suspend fun isDirectory(path: String): Boolean {
        return reader.isDirectory(PathUtil.combine(basePath, path))
    }

    override suspend fun readAsStreamReader(path: String): ByteStreamReader {
        return reader.readAsStreamReader(PathUtil.combine(basePath, path))
    }

    override suspend fun md5(path: String): String? {
        return reader.md5(PathUtil.combine(basePath, path))
    }
}

class  RelativeFileReaderWriter(
    private val basePath: String,
    private val writer: OutsideFileWriter,
    private val reader: OutsideFileReader,
): OutsideFileBase, OutsideFileReader, OutsideFileWriter {

    override suspend fun write(path: String, data: ByteArray, append: Boolean) {
        writer.write(PathUtil.combine(basePath, path), data, append)
    }

    override suspend fun read(path: String): ByteArray {
        return reader.read(PathUtil.combine(basePath, path))
    }

    override suspend fun read(path: String, offset: Long, length: Long): ByteArray? {
        return reader.read(PathUtil.combine(basePath, path), offset, length)
    }

    override suspend fun readAsStreamReader(path: String): ByteStreamReader {
        return reader.readAsStreamReader(PathUtil.combine(basePath, path))
    }

    override suspend fun readTextUTF8(path: String): String {
        return reader.readTextUTF8(PathUtil.combine(basePath, path))
    }

    override suspend fun readTextWindowsCP1252(path: String): String {
        return reader.readTextWindowsCP1252(PathUtil.combine(basePath, path))
    }

    override suspend fun delete(path: String): Boolean {
        return reader.delete(PathUtil.combine(basePath, path))
    }

    override suspend fun fileExists(path: String): Boolean {
        return reader.fileExists(PathUtil.combine(basePath, path))
    }

    override suspend fun isDirectory(path: String): Boolean {
        return reader.isDirectory(PathUtil.combine(basePath, path))
    }

    override suspend fun md5(path: String): String? {
        return reader.md5(PathUtil.combine(basePath, path))
    }
}