package com.bedalton.creatures.caos.libs


/**
 * Converts a concreate command into the format used by JS implentations
 */
internal fun CaosCommand.toVariantCommand(variant: String): VariantCaosCommand {
    return VariantCaosCommand(
        command = command,
        parameters = parameters.map {
            VariantCaosParameter(it, variant)
        }.sortedBy { it.index }.toTypedArray(),
        isLvalue = lvalue,
        isRvalue = rvalue,
        returnTypeId = returnType.value,
        returnTypeName = returnType.simpleName,
        variants = variants,
        description = description,
        commandGroup = commandGroup,
        doifFormat = doifFormat,
        lvalueName = lvalueName,
        requiresCreatureOwnr = requiresCreatureOwnr,
        requiresOwnr = requiresOwnr,
        returnValuesListIds = returnValuesListIds?.let { VariantData(it) },
        isCommand = isCommand,
    )
}


