/**
 * A copy of the C1 palette as a list of RGBA colors
 */
open class ColorPalette(
    private val baseEncoding: ColorEncoding,
    private val paletteColors: Array<RGBA>,
    private val isTransformed: Boolean,
) : Iterable<RGBA> {

    //    constructor(
//        baseEncoding: ColorEncoding,
//        paletteColors: Array<RGBA>,
//    ): this( baseEncoding, paletteColors, false)
    open operator fun get(index: Int): RGBA = when (index) {
        in indices -> paletteColors[index]
        0 -> paletteColors[0]
        PixelIndices.TRANSPARENT_BLACK -> TRANSPARENT_BLACK
        else -> throw IndexOutOfBoundsException("Invalid color index: $index. Range: 0..${paletteColors.lastIndex}")
    }

    open val size: Int get() = paletteColors.size

    open val colors get() = paletteColors.toList()

    internal open val indices: IntRange by lazy {
        paletteColors.indices
    }

    internal open val lastIndex: Int
        get() = paletteColors.lastIndex

    fun withKeepBlack(keep: Boolean): ColorPalette {
        return if (keep) {
            if (paletteColors[0].a == 255) {
                this
            } else {
                withOpaqueBlack()
            }
        } else if (paletteColors[0].a == 0) {
            this
        } else {
            withTransparentBlack()
        }
    }

    open fun toInt(keepBlack: Boolean, encoding: ColorEncoding? = null): RgbToInt {
        val blackish: Int
        var blackInt = 0
        val rgbToInt: RgbToInt = when (size) {
            65535, 65536 -> {
                val encodingNotNull = encoding ?: ColorEncoding.X_565
                blackish = encodingNotNull.blackish
                encodingNotNull.toInt
            }
            255 -> {
                val allowBlack = black.a != 0
                val palette = if (allowBlack) C1OpaqueBlack else C1TransparentBlack
                blackish = palette.colors.indexOfFirst { it.r == 0 && it.g == 0 && it.b == 0 && it.a == 255 }
                blackInt = if (allowBlack) blackish else 0
                toIntC1@{ red: Int, green: Int, blue: Int ->
                    SprCompiler.getColorIndex(palette, red, green, blue, allowBlack)
                }
            }
            else -> {
                throw SpriteParserException("Invalid palette color count. Expected 255 or 65535; Found: $size")
            }
        }

        return toIntOut@{ red: Int, green: Int, blue: Int ->
            if (red == 0 && green == 0 && blue == 0) {
                return@toIntOut blackInt
            }
            val originalIndex = rgbToInt(red, green, blue)
            val color = get(originalIndex)
            rgbToInt(color.r, color.g, color.b).let {
                if (it == 0) {
                    blackish
                } else {
                    it
                }
            }
        }
    }

    fun withTransparentBlack(): ColorPalette {
        return if (paletteColors[0] == TRANSPARENT_BLACK) {
            this
        } else {
            return ColorPalette(
                baseEncoding,
                arrayOf(TRANSPARENT_BLACK, *paletteColors.drop(1).toTypedArray()),
                isTransformed
            )
        }

    }


    fun withOpaqueBlack(): ColorPalette {
        return if (paletteColors[0] == OPAQUE_BLACK) {
            this
        } else {
            ColorPalette(baseEncoding, arrayOf(OPAQUE_BLACK, *paletteColors.drop(1).toTypedArray()), isTransformed)
        }
    }

    private fun inferredEncoding(): ColorEncoding {
        return if (size == 256) {
            ColorEncoding.C1
        } else {
            val count565 = X_565.colors.indices.count { i -> X_565[i] == this[i] }
            if (count565 == 65535) {
                return ColorEncoding.X_565
            }

            val count555 = X_555.colors.indices.count { i -> X_555[i] == this[i] }
            if (count555 == 65535) {
                return ColorEncoding.X_555
            }
            if (count565 >= count555) {
                ColorEncoding.X_565
            } else {
                ColorEncoding.X_555
            }
        }
    }

    fun transform(paletteTransform: PaletteTransform): ColorPalette {
        val black = paletteColors[0]
        val hasTransform = paletteTransform.hasTransform
        val paletteSize = size
        val isC1Target = paletteTransform.gameVariant == C1
        val isC1Size = paletteSize == 256

        // If there is no transformation to apply, and variant does not change
        // Return this same instance
        if (!hasTransform) {
            if (isC1Target && isC1Size) {
                return this
            } else if (!isC1Target && !isC1Size) {
                return this
            }
        }


        // If this is C2+ palette with a C2+ size
        // Return self translated
        return if (!isC1Target && !isC1Size) {
            // Use C2 transform
            if (paletteTransform.gameVariant == GameVariant.C2) {
                swapAndRotateC2(
                    baseEncoding,
                    black = black,
                    red = paletteTransform.red,
                    green = paletteTransform.green,
                    blue = paletteTransform.blue,
                    swap = paletteTransform.swap,
                    rotation = paletteTransform.rotation
                )
            } else {
                // Use C2e transform
                swapAndRotateC2e(
                    baseEncoding,
                    baseEncoding.toRGBColorList(black).toTypedArray(),
                    red = paletteTransform.red,
                    green = paletteTransform.green,
                    blue = paletteTransform.blue,
                    swap = paletteTransform.swap,
                    rotation = paletteTransform.rotation
                )
            }
        } else if (isC1Target) {
            // If targets a C1 palette, colors need to be clamped to nearest in palette

            val palette = swapAndRotateC1(
                (get(0).a > 127),
                paletteTransform.red ?: 128,
                paletteTransform.green ?: 128,
                paletteTransform.blue ?: 128,
                paletteTransform.swap ?: 128,
                paletteTransform.rotation ?: 128,
            )

            if (isC1Size) {
                return palette // Return as is
            }

            // Find nearest not-black black
            val offBlack = palette[SprCompiler.getColorIndex(palette, 1, 1, 1, false)]

            // Create transformed palette
            return ColorPaletteTranslating(
                baseEncoding,
                size = 65536,
                black = black,
                paletteTransform,
                colorByIndex = baseEncoding.toRgb
            ) { color ->
                toC1Color(palette, color, offBlack)
            }
        } else { // if (isC1Size) { // Is a C2+ Target with a C1 palette size
            // If targets a C1 palette size, colors need to be clamped to nearest in palette

            // Get base C1 palette
            val palette = if (this.size == 256) {
                this
            } else if (get(0).a > 127) {
                C1OpaqueBlack
            } else {
                C1TransparentBlack
            }

            // Find nearest not-black black
            val offBlack = palette[SprCompiler.getColorIndex(palette, 1, 1, 1, false)]

            // Create transformed palette
            return ColorPaletteTranslating(
                ColorEncoding.X_565,
                size = 65536,
                black = black,
                paletteTransform,
                colorByIndex = ColorEncoding.X_565.toRgb
            ) { color ->
                toC1Color(palette, color, offBlack)
            }
        }
    }

    /**
     * Palette using encoding should only be C2+ palettes
     */
    fun transform(transform: PaletteTransform, encoding: ColorEncoding, keepBlack: Boolean? = null): ColorPalette {
        val black = if (keepBlack == null) {
            this[0]
        } else if (keepBlack) {
            OPAQUE_BLACK
        } else {
            TRANSPARENT_BLACK
        }
        val hasTransform = transform.hasTransform
        val paletteSize = size
        val isC1Target = transform.gameVariant == C1
        val isC1Size = paletteSize == 256

        // If there is no transformation to apply, and variant does not change
        // Return this same instance
        if (!hasTransform) {
            if (isC1Target && isC1Size) {
                return this
            } else if (!isC1Target && !isC1Size) {
                return this
            }
        }

        // If this is C2+ palette with a C2+ size
        // Return self translated
        return if (!isC1Target && !isC1Size) {
            // Use C2 transform
            if (transform.gameVariant == GameVariant.C2) {
                swapAndRotateC2(
                    encoding,
                    black = black,
                    red = transform.red,
                    green = transform.green,
                    blue = transform.blue,
                    swap = transform.swap,
                    rotation = transform.rotation
                )
            } else {
                // Use C2e transform
                swapAndRotateC2e(
                    encoding,
                    encoding.toRGBColorList(black).toTypedArray(),
                    red = transform.red,
                    green = transform.green,
                    blue = transform.blue,
                    swap = transform.swap,
                    rotation = transform.rotation
                )
            }
        } else if (isC1Target) {
            // If targets a C1 palette, colors need to be clamped to nearest in palette

            val palette = swapAndRotateC1(
                keepBlack ?: (get(0).a > 127),
                transform.red ?: 128,
                transform.green ?: 128,
                transform.blue ?: 128,
                transform.swap ?: 128,
                transform.rotation ?: 128,
            )

            if (isC1Size) {
                return palette // Return as is
            }

            // Find nearest not-black black
            val offBlack = palette[SprCompiler.getColorIndex(palette, 1, 1, 1, false)]

            // Create transformed palette
            return ColorPaletteTranslating(
                encoding,
                size = 65536,
                black = black,
                transform,
                colorByIndex = encoding.toRgb
            ) { color ->
                toC1Color(palette, color, offBlack)
            }
        } else { // if (isC1Size) { // Is a C2+ Target with a C1 palette size
            // If targets a C1 palette size, colors need to be clamped to nearest in palette

            // Get base C1 palette
            val palette = if (this.size == 256) {
                this
            } else if (get(0).a > 127) {
                C1OpaqueBlack
            } else {
                C1TransparentBlack
            }

            // Find nearest not-black black
            val offBlack = palette[SprCompiler.getColorIndex(palette, 1, 1, 1, false)]

            // Create transformed palette
            return ColorPaletteTranslating(
                encoding,
                size = 65536,
                black = black,
                transform,
                colorByIndex = encoding.toRgb
            ) { color ->
                toC1Color(palette, color, offBlack)
            }
        }
    }

    companion object {

        @JvmStatic
        // Holds an RGBA instance for transparent black
        @Suppress("unused")
        val TRANSPARENT_BLACK by lazy {
            RGBA(0, 0, 0, 0)
        }

        @JvmStatic
        @Suppress("unused")
        val OPAQUE_BLACK by lazy {
            RGBA(0, 0, 0, 255)
        }

        internal fun swapAndRotateC1(
            keepBlack: Boolean,
            red: Int,
            green: Int,
            blue: Int,
            swap: Int,
            rotate: Int,
        ): ColorPalette {
            return swapAndRotateC1(
                if (keepBlack) {
                    C1OpaqueBlack
                } else {
                    C1TransparentBlack
                },
                red,
                green,
                blue,
                swap,
                rotate
            )
        }

        internal fun swapAndRotate(
            gameVariant: GameVariant,
            encoding: ColorEncoding,
            keepBlack: Boolean,
            reds: List<Int>,
            blues: List<Int>,
            greens: List<Int>,
            swapIn: List<Int>,
            rotationIn: List<Int>,
        ): ColorPalette {
            val red = reds.average() ?: 128
            val green = greens.average() ?: 128
            val blue = blues.average() ?: 128
            val swap = collapseRunning(swapIn) ?: 128
            val rotation = collapseRunning(rotationIn) ?: 128
            return swapAndRotate(gameVariant, encoding, keepBlack, red, green, blue, swap, rotation)
        }

        internal fun swapAndRotate(
            gameVariant: GameVariant,
            encoding: ColorEncoding,
            keepBlack: Boolean,
            red: Int,
            green: Int,
            blue: Int,
            swap: Int,
            rotate: Int,
        ): ColorPalette {
            return when (gameVariant) {
                C1 -> swapAndRotateC1(
                    keepBlack = keepBlack,
                    red = red,
                    green = green,
                    blue = blue,
                    swap = swap,
                    rotate = rotate
                )

                GameVariant.C2 -> swapAndRotateC2(
                    encoding,
                    black = if (keepBlack) OPAQUE_BLACK else TRANSPARENT_BLACK,
                    red = red,
                    green = green,
                    blue = blue,
                    swap = swap,
                    rotation = rotate
                )

                else -> swapAndRotateC2e(
                    encoding,
                    palette = encoding.toRgbWithTables(keepBlack).paletteColors,
                    red = red,
                    green = green,
                    blue = blue,
                    swap = swap,
                    rotation = rotate
                )
            }
        }

