        private fun toC1Color(palette: ColorPalette, color: RGBA, offBlack: RGBA): RGBA {
            val index = SprCompiler.getColorIndex(palette, color.r, color.g, color.b, false)
            return if (index == 0) {
                offBlack
            } else {
                palette[index]  // palette[index] TODO See if should use passed in palette
            }
        }

        val C1TransparentBlack by lazy {
            ColorPalette(ColorEncoding.C1, defaultC1PaletteColors(TRANSPARENT_BLACK), false)
        }
        val C1OpaqueBlack by lazy {
            ColorPalette(ColorEncoding.C1, defaultC1PaletteColors(OPAQUE_BLACK), false)
        }

        val X_565 by lazy {
            ColorEncoding.X_565.toRgbWithTables(TRANSPARENT_BLACK)
        }

        val X_555 by lazy {
            ColorEncoding.X_555.toRgbWithTables(TRANSPARENT_BLACK)
        }

        val DEFAULT by lazy {
            ColorEncoding.ENCODING_DEFAULT.toRgbWithTables(TRANSPARENT_BLACK)
        }

        fun fromEncoding(encoding: ColorEncoding?, keepBlack: Boolean = false): ColorPalette {
            return when (encoding) {
                ColorEncoding.X_555 -> {
                    if (keepBlack) {
                        X_555.withKeepBlack(true)
                    } else {
                        X_555
                    }
                }

                ColorEncoding.X_565 -> {
                    if (keepBlack) {
                        X_565.withKeepBlack(true)
                    } else {
                        X_565
                    }
                }

                ColorEncoding.C1 -> C1TransparentBlack
                else -> DEFAULT
            }
        }
    }

    override fun iterator(): Iterator<RGBA> {
        return object : Iterator<RGBA> {
            var i = 0
            var max = paletteColors.lastIndex
            override fun hasNext(): Boolean {
                return i < max
            }

            override fun next(): RGBA {
                return paletteColors[i++]
            }

        }
    }

}

