internal fun loadC1Palette(black: RGBA, bytes: ByteArray): ColorPalette {
    val otherColors = (1 until 246).map { i ->
        val base = i * 3
        RGBA(
            bytes[base] * 4,
            bytes[base + 1] * 4,
            bytes[base + 2] * 4
        )
    }
    val colors: List<RGBA> = listOf(black) + otherColors + last10
    return loadC1Palette(colors)
}

internal fun loadC1Palette(black: RGBA, stream: ByteStreamReader): ColorPalette {
    val otherColors = stream.readAtPosition(0) {
        (1 until 246).map {
            RGBA(
                uInt8() * 4,
                uInt8() * 4,
                uInt8() * 4
            )
        }
    }
    val colors = listOf(black) + otherColors + last10
    return loadC1Palette(colors)
}

private fun loadC1Palette(colors: List<RGBA>): ColorPalette {
    if (colors.size != 256) {
        throw SpriteParserException("Invalid palette. Expected 256 colors. Found: ${colors.size}")
    }
    return ColorPalette(ColorEncoding.C1, colors.toTypedArray(), false)
}

private fun collapseRunning(values: List<Int>): Int? {
    if (values.isEmpty()) {
        return null
    }
    var out = values[0]
    for (value in values.drop(1)) {
        out = (out + value) / 2
    }
    return out
}

private fun List<Int>.average(): Int? {
    if (isEmpty()) {
        return null
    }
    val count = size
    return sum() / count
}


typealias RgbToInt = (red: Int, green: Int, blue: Int) -> Int


internal fun isDefaultColorValues(vararg values: Int?): Boolean {
    return values.isEmpty() || values.all { value -> value == null || value == 128 }
}

internal fun isDefaultColorValue(value: Int?): Boolean {
    return value == null || value == 128
}
