package com.bedalton.creatures.genetics.genome

import com.bedalton.creatures.genetics.gene.Gene
import com.bedalton.io.bytes.ByteStreamWriter
import kotlinx.serialization.SerialName
import kotlinx.serialization.Serializable


@SerialName("GeneBytePair")
@Serializable
data class GeneBytePair(
    // @ProtoNumber(1)
	@SerialName("gene_type")
	val geneType: Int,
    // @ProtoNumber(2)
	@SerialName("gene_subtype")
	val geneSubtype: Int,
    // @ProtoNumber(3)
	@SerialName("index_of_type")
	val indexOfType: Int,
    // @ProtoNumber(4)
	@SerialName("header_bytes")
	val headerBytes: ByteArray,
    // @ProtoNumber(5)
	@SerialName("gene_bytes")
	val geneBytes: ByteArray
) {



    override fun equals(other: Any?): Boolean {
        if (this === other) return true
        if (other == null || this::class != other::class) return false

        other as GeneBytePair

        if (geneType != other.geneType) return false
        if (geneSubtype != other.geneSubtype) return false
        if (!headerBytes.contentEquals(other.headerBytes)) return false
        if (!geneBytes.contentEquals(other.geneBytes)) return false

        return true
    }

    override fun hashCode(): Int {
        var result = geneType
        result = 31 * result + geneSubtype
        result = 31 * result + headerBytes.contentHashCode()
        result = 31 * result + geneBytes.contentHashCode()
        return result
    }


    companion object {
        fun fromGene(gene: Gene, indexOfType: Int): GeneBytePair {
            return GeneBytePair(
                geneType = gene.geneType,
                geneSubtype = gene.geneSubType,
                indexOfType = indexOfType,
                headerBytes = ByteStreamWriter.writeBytes { gene.geneHeader.write(this) },
                geneBytes = ByteStreamWriter.writeBytes { gene.writeData(this) }
            )
        }
    }
}