package com.creaturesforge.application.util


internal fun <T> jsOb(work: T.() -> Unit = {}): T {
    val ob = js("{}").unsafeCast<T>()
    ob.work()
    return ob
}


@JsName("Object")
external object Object {

    @JsName("keys")
    fun keys(ob: Any): Array<String>
    @JsName("assign")
    fun assign(target: dynamic, vararg others: dynamic): dynamic
}


internal fun <T:Any> Object.copy(obj: T): T {
    return assign(js("{}"), obj.asDynamic())
        .unsafeCast<T>()
}