@file:Suppress("unused")

package com.bedalton.common.coroutines

import com.bedalton.common.util.className
import kotlinx.coroutines.*

fun CoroutineDispatcher.launch(
    start: CoroutineStart = CoroutineStart.DEFAULT,
    capture: Boolean? = null,
    block: suspend (scope: CoroutineScope) -> Unit,
): Job {
    return if (capture == true) {
        val scope = CoroutineScope(this)
        scope.launch(start = start) {
            try {
                block(scope)
            } catch (e: Exception) {
                println(e.className + "\n" + e.stackTraceToString())
                throw e
            }
        }
    } else {
        CoroutineScope(this).launch(start = start, block = block)
    }
}

fun <T> CoroutineDispatcher.async(
    start: CoroutineStart = CoroutineStart.DEFAULT,
    capture: Boolean? = null,
    block: suspend (scope: CoroutineScope) -> T,
): Deferred<T> {
    return if (capture == true) {
        val scope = CoroutineScope(this)
        scope.async(start = start) {
            try {
                block(scope)
            } catch (e: Exception) {
                println(e.className + "\n" + e.stackTraceToString())
                throw e
            }
        }
    } else {
        CoroutineScope(this).async(start = start, block = block)
    }
}

