package com.bedalton.common.exceptions

import kotlinx.coroutines.CancellationException

fun Throwable.rethrowCancellationException() {
    if (this is CancellationException || this is kotlin.coroutines.cancellation.CancellationException) {
        throw this
    }
}

fun rethrowCancellationException(e: Any) {
    if (e is CancellationException || e is kotlin.coroutines.cancellation.CancellationException) {
        throw e as Throwable
    }
}

fun Throwable.rethrowCancellationException(doBefore: ((e: Throwable) -> Unit)? = null) {
    if (this is CancellationException || this is kotlin.coroutines.cancellation.CancellationException) {
        try {
            doBefore?.invoke(this)
        } catch (_: Throwable) {
        }
        throw this
    }
}