package com.bedalton.creatures.agents.pray.compiler

expect interface PrayCompileOptionsWithLinkWithFileName {
    /**
     * Prefix Linked CAOS file tags with source filename
     */
    val linkWithFilenameReference: Boolean?
}


internal expect val PrayCompileOptions.linkWithFilenameReferenceOrNull: Boolean?

internal val PrayCompileOptions.linkWithFilenameReferenceNotNull: Boolean get() {
    return linkWithFilenameReferenceOrNull ?: CompilerOptionsDefault.LINK_WITH_FILENAME_REFERENCE_DEFAULT
}