package com.bedalton.creatures.breed.render.files

import com.bedalton.common.util.PathUtil

private val partChars = 'a'..'q'

fun partChar(filename: String?): Char? {
    if (filename.isNullOrBlank()) {
        return null
    }
    val part = PathUtil.getLastPathComponent(filename)
        ?.getOrNull(0)
        ?.lowercaseChar()
        ?: return null
    return if (part in partChars) {
        part
    } else {
        null
    }
}