@file:Suppress("unused")
package com.bedalton.creatures.sprite.compilers

import com.bedalton.creatures.sprite.util.*
import com.bedalton.creatures.sprite.util.ColorEncoding.Companion.ENCODING_DEFAULT
import com.bedalton.io.bytes.ByteStreamWriter
import korlibs.image.bitmap.Bitmap32

@Suppress("MemberVisibilityCanBePrivate")
object S16Compiler: SpriteCompiler {

    private const val SPRITE_HEADER_SIZE = 6 // 4 = format, 2 = Num images
    private const val IMAGE_HEADER_SIZE = 8 // 4 = offset to start of data, 2 = width, 2 = height


    @Deprecated("Use with keepBlack parameter", ReplaceWith("compileSpriteFromImageBytes(images, false, colorEncoding, callback"))
    override fun compileSpriteFromImageBytes(images: List<Pair<String, ByteArray>>, colorEncoding: ColorEncoding?, callback: ((pass: Int, current: Int, total: Int) -> Boolean?)?): ByteArray {
        return compileSpriteFromImageBytes(images, false, colorEncoding, callback)
    }

    @Deprecated("Use with keepBlack parameter", ReplaceWith("compileSpriteFromImageBytes(images, false, colorEncoding, callback"))
    override fun compileSpriteFromLoadedImages(
        images: List<Bitmap32>,
        colorEncoding: ColorEncoding?,
        callback: ((current: Int, total: Int) -> Boolean?)?
    ): ByteArray {
        return compileSpriteFromLoadedImages(images, false, colorEncoding, callback)
    }

    override fun compileSpriteFromImageBytes(
        images: List<Pair<String, ByteArray>>,
        keepBlack: Boolean,
        colorEncoding: ColorEncoding?,
        paletteTransform: PaletteTransform?,
        callback: ((pass: Int, current: Int, total: Int) -> Boolean?)?
    ): ByteArray {
        val bitmaps = ImageLoader.loadMany(images) { current, total ->
            if (callback?.invoke(1, current, total) == false) {
                throw SpriteCompilerCancelledException("Cancelled SPR compilation during image loading phase")
            }
            true
        }
        return compileSpriteFromLoadedImages(bitmaps, keepBlack, colorEncoding) { current, total ->
            callback?.invoke(2, current, total)
        }
    }

    override fun compileSpriteFromLoadedImages(
        images: List<Bitmap32>,
        keepBlack: Boolean,
        colorEncoding: ColorEncoding?,
        paletteTransform: PaletteTransform?,
        callback: ((current: Int, total: Int) -> Boolean?)?
    ): ByteArray {
        val encoding = (colorEncoding ?: ENCODING_DEFAULT)
        val imagesCount = images.size
        var imageOffset = SPRITE_HEADER_SIZE + (images.size * IMAGE_HEADER_SIZE)

        val rgbToInt = paletteTransform.nullIfDefault()?.transform(encoding, keepBlack)?.toInt(keepBlack) ?: encoding.toInt

        return ByteStreamWriter.writeBytes {
            writeUInt32(encoding.marker)
            writeUInt16(images.size)
            val black = SpriteCompiler.getBlack(keepBlack)
            for (image in images) {
                writeUInt32(imageOffset)
                val width = image.width
                val height = image.height
                writeUInt16(width)
                writeUInt16(height)
                imageOffset += width * height * 2
            }

            val headerSize = size

            val actualCallback: ((current: Int, total: Int) -> Boolean?)? = callback?.let { it ->
                { current: Int, total: Int ->
                    if (it(current, total) == false) {
                        throw SpriteCompilerCancelledException("S16 compilation cancelled during compiler phase")
                    }
                    true
                }
            }
            if (actualCallback?.invoke(0, imagesCount) == false) {
                throw SpriteCompilerCancelledException("S16 compilation cancelled during compile phase")
            }
            var i = 0
            for (image in images) {
                writeCompiledImage(image, this, black, rgbToInt)
                if (actualCallback?.invoke(++i, imagesCount) == false) {
                    throw SpriteCompilerCancelledException("S16 compilation cancelled during compile phase")
                }
            }
            if (size != imageOffset.toLong()) {
                throw SpriteCompileException(
                    "Bytes written is inconsistent with calculated offsets; Expected: $imageOffset; Written: ${size - headerSize}"
                )
            }
        }
    }

    fun writeCompiledImage(image: Bitmap32, buffer: ByteStreamWriter, keepBlack: Boolean, colorEncoding: ColorEncoding) : Int {
        return writeCompiledImage(image, buffer, SpriteCompiler.getBlack(keepBlack), colorEncoding.toInt)
    }

    private fun writeCompiledImage(image: Bitmap32, buffer: ByteStreamWriter, black: Int, rgbToInt: RgbToInt) : Int {

        val alphaCutoff = programAlphaCutoff
        val width = image.width
        val height = image.height
        val base = buffer.size
        for (y in 0 until height) {
            for (x in 0 until width) {
                val pixel = image[x, y]
                val alpha: Int = pixel.a
                if (alpha < alphaCutoff) {
                    buffer.writeUInt16(0)
                } else {
                    val red: Int = pixel.r
                    val green: Int = pixel.g
                    val blue: Int = pixel.b
                    if (red + green + blue == 0) {
                        buffer.writeUInt16(black)
                    } else {
                        val subFrom = 0//arrayOf(((255 - alpha) * 0.7).toInt(), red - 2, green - 2, blue - 2).min()!!
                        var color = rgbToInt(red - subFrom, green - subFrom, blue - subFrom)
                        if (color == 0) {
                            color = black
                        }
                        buffer.writeUInt16(color)
                    }
                }
            }
        }
        val written = buffer.size - base
        if (written != (width * height * 2).toLong()) {
            throw SpriteCompileException(
                "Bytes written is incorrect. Expected: ${width * height * 2}; Actual: $written"
            )
        }
        return written.toInt()
    }

}