import com.bedalton.common.ast.collectors.CursorPosition
import com.bedalton.common.ast.collectors.CursorPositionValues
import com.bedalton.common.ast.collectors.ParseTreeItem
import com.bedalton.common.ast.collectors.inQuotes
import com.bedalton.common.ast.structs.Range
import com.bedalton.common.ast.utils.astJson
import kotlinx.serialization.json.decodeFromDynamic


@JsExport
@JsName("CursorPosition")
object CursorPositionJs {
    val BEFORE = CursorPosition.BEFORE
    val START = CursorPosition.START
    val INSIDE = CursorPosition.INSIDE
    val END = CursorPosition.END
    val AFTER = CursorPosition.AFTER
}

@JsExport
@JsName("CursorPositionValues")
val cursorPositionValues = CursorPositionValues


@Suppress("FunctionName")
@JsExport()
@JsName("inQuotes")
fun inQuotes_jsApi(parserItem: dynamic, line: Int, character: Int): Boolean {
    if (parserItem is ParseTreeItem) {
        return inQuotes(parserItem as ParseTreeItem, line, character)
    }
    if (parserItem.textRange == null) {
        throw Exception("Parser item missing textRange property")
    }
    val textRange = astJson.decodeFromDynamic<Range>(parserItem.textRange);
    val text = parserItem.text as String
    return inQuotes(text, textRange, line, character)
}