package com.bedalton.creatures.agents.pray.compiler.pray

import com.bedalton.common.util.PathUtil

fun bestDependencyCategoryForFile(fileName: String): Int? {
    val extension = PathUtil.getExtension(fileName)?.lowercase()
        ?: return null
    return when (extension) {
        "wav", "mng", "ming" -> 1
        "c16", "s16" -> 2
        "gen", "gno" -> 3
        "att" -> 4
        "back", "blk" -> 6
        "catalogue" -> 7
        "creature" -> 10
        else -> null
    }
}