package com.bedalton.creatures.breed.render.files

import com.bedalton.common.util.orElse
import com.bedalton.creatures.common.structs.BreedKey


fun BreedKey.toJsBreedKey() = JsBreedKey(
    genus = genus,
    gender = gender,
    ageGroup = ageGroup,
    breed = breed?.lowercase()
)


fun JsBreedKey.toBreedKey(): BreedKey = BreedKey(
    genus = genus,
    gender = gender,
    ageGroup = ageGroup,
    breed = breed?.getOrNull(0)?.lowercaseChar()
)


val BreedKey?.codeSafe: String? get() {
    if (this == null) {
        return null
    }
    val genus = genus
    val gender = gender
    val first = if (genus == null || gender == null) {
        '*'
    } else {
        (genus * gender).digitToChar()
    }
    val second = ageGroup?.digitToChar().orElse('*')
    val third = breed.orElse('*')
    return "$first$second$third"
}