package com.bedalton.vfs

import kotlin.js.Promise


/**
 * Convert a VFS to a file system
 */
fun VFS.toFileSystem(): FileSystem {
    return VfsFileSystemWrapper(this)
}

/**
 * Handle to currently selected global VFS object
 */
internal var vfs: VFS? = null


internal val returnsTruePromise by lazy {
    Promise.resolve(true)
}