package com.bedalton.creatures.caos.collectors.internal

import com.bedalton.common.ast.collectors.trueText
import com.bedalton.common.ast.structs.RangeWithIndexImpl
import com.bedalton.creatures.caos.antlr.CaosWhitespaceParser
import com.bedalton.creatures.caos.antlr.CaosWhitespaceParserBaseListener
import com.bedalton.creatures.caos.collectors.CaosParserItem

internal class WhitespaceCollector: CaosWhitespaceParserBaseListener() {


    private val mWhitespace = mutableListOf<CaosParserItem>()

    val whitespace: List<CaosParserItem>
        get() = mWhitespace

    override fun enterSpace(ctx: CaosWhitespaceParser.SpaceContext) {
        super.enterSpace(ctx)
        mWhitespace.add(
            CaosParserItem.Spaces(
                RangeWithIndexImpl.create(ctx.start!!, ctx.stop!!),
                ctx.trueText
            )
        )
    }


    override fun enterNewline(ctx: CaosWhitespaceParser.NewlineContext) {
        super.enterNewline(ctx)
        mWhitespace.add(
            CaosParserItem.NewLine(
                RangeWithIndexImpl.create(ctx.start!!, ctx.stop!!),
                ctx.trueText
            )
        )
    }
}