package com.bedalton.creatures.caos.collectors

import com.bedalton.common.ast.structs.PositionImpl
import com.bedalton.common.ast.structs.RangeWithIndexImpl
import com.bedalton.common.ast.structs.contains
import com.bedalton.common.ast.structs.stitch
import com.bedalton.common.util.nullIfEmpty
import com.bedalton.creatures.caos.collectors.internal.CaosWalker
import com.bedalton.creatures.caos.collectors.internal.assertValidVariant
import com.bedalton.creatures.caos.collectors.internal.createCheckCancelled
import com.bedalton.creatures.caos.libs.CaosLibs
import com.bedalton.creatures.caos.libs.ErrorTypes
import com.bedalton.creatures.caos.libs.TypeTokens
import com.bedalton.creatures.caos.libs.GameVariant


/**
 * Create a parserResult from parser items
 * Can be used to parse scripts from parser result using only its enclosed items
 */
fun parseTokens(
    variant: GameVariant,
    text: String,
    items: Array<CaosParserItem>,
    scriptOffsets: Array<BlockRange> = emptyArray(),
    checkErrors: Boolean? = null,
    checkDelay: Int? = null,
    keepGoing: (() -> Boolean)? = null,
): ParseResult {

    // Ensure variant string is valid
    assertValidVariant(variant)

    // Get CAOS lib for variant
    val lib = CaosLibs[variant.uppercase()]

    // Create a callback that will throw an exception if KeepGoing returns false
    // This is used to abort processing if signaled to stop
    val checkCancelled = createCheckCancelled(checkDelay, keepGoing)

    val nonWhitespaceItems = items.filter { it !is CaosParserItem.WhitespaceItem }.toTypedArray()
    val whitespaceItems = items.filter { it is CaosParserItem.WhitespaceItem }.toTypedArray()

    // Create walker for CAOS file
    val caosWalker = CaosWalker(lib, text, items, checkCancelled)

    // Check for incomplete control statements
    val controlStatementErrors = if (checkErrors != false) {
        val controlStatementWalker = ControlStatementOffsetsTokenWalker(variant, nonWhitespaceItems)
        getControlStatementErrors(controlStatementWalker.getStatementOffsets(), nonWhitespaceItems)
    } else {
        emptyArray()
    }

    // Return the processed result
    return ParseResult(
        variant = variant,
        text,
        items = nonWhitespaceItems,
        whitespaceItems = whitespaceItems,
        controlStatementErrors = controlStatementErrors,
        scriptOffsets = scriptOffsets,
        equalityStatements = caosWalker.equalityStatements,
        equalityStatementRanges = caosWalker.equalityStatementRanges,
        commandCalls = caosWalker.commandCalls,
        comments = caosWalker.comments.toTypedArray(),
        caos2Comments = (caosWalker.caos2Comments.nullIfEmpty()
            ?: items.filter { it.typeToken == TypeTokens.CAOS2_COMMENT }
                .map { it as CaosParserItem.Caos2Comment }).toTypedArray(),
        looseTokens = caosWalker.looseTokens
    )
}


private fun getControlStatementErrors(statements: List<BlockRange>, items: Array<CaosParserItem>): Array<CaosParserItem.ErrorVal> {
    return statements.mapNotNull { statement ->
        if (statement.endToken == null && statement.startToken != null) {
            CaosParserItem.ErrorVal(
                textRange = RangeWithIndexImpl(
                    startIndex = statement.endIndex,
                    endIndex = statement.endIndex,
                    start = PositionImpl(
                        line = statement.end.line,
                        character = maxOf(0, statement.end.character)
                    ),
                    end = PositionImpl(
                        line = statement.end.line,
                        character = statement.end.character
                    )
                ),
                message = "Missing terminating ${getTerminator(statement.startToken)}",
                type = ErrorTypes.UNTERMINATED_CONTROL_STATEMENT,
                text = items.filter { statement.contains(it.textRange) }.stitch()
            )
        } else if (statement.startToken == null) {
            CaosParserItem.ErrorVal(
                textRange = RangeWithIndexImpl(
                    startIndex = statement.startIndex,
                    endIndex = statement.endIndex,
                    start = PositionImpl(
                        line = statement.start.line,
                        character = statement.end.character
                    ),
                    end = PositionImpl(
                        line = statement.end.line,
                        character = statement.start.character
                    )
                ),
                message = "Unexpected '${statement.endToken!!.uppercase()}'",
                type = ErrorTypes.UNEXPECTED_CONTROL_TERMINATOR,
                text = items.filter { statement.contains(it.textRange) }.stitch()
            )
        } else {
            null
        }
    }.toTypedArray()
}


private fun getTerminator(start: String): String {
    return when (start.lowercase()) {
        "doif" -> "ENDI"
        "loop" -> "EVER|UNTL"
        "reps" -> "REPE"
        "enum", "esee", "etch", "epas", "econ" -> "NEXT"
        "escn" -> "NSCN"
        "subr" -> "RETN"
        else -> throw Exception("Unexpected start token '$start' for getTerminator()")
    }
}

