package com.bedalton.creatures.genetics.utils


import com.bedalton.io.bytes.ByteStreamReader
import com.bedalton.io.bytes.ByteStreamWriter

internal fun ByteStreamWriter.writeUInt8Array(array: IntArray): ByteStreamWriter {
    for (int in array) {
        writeUInt8(int)
    }
    return this
}

internal fun ByteStreamWriter.writeUInt8ArrayIfNotNull(array: IntArray?): ByteStreamWriter {
    if (array == null) {
        return this
    }
    for (int in array) {
        writeUInt8(int)
    }
    return this
}

internal fun ByteStreamReader.readUInt8Array(bytes: Int): IntArray {
    return IntArray(bytes) { uInt8() }
}


internal fun ByteStreamWriter.writeUInt8Array(array: Array<Int>): ByteStreamWriter {
    for (int in array) {
        writeUInt8(int)
    }
    return this
}

internal fun ByteStreamWriter.writeUInt8ArrayIfNotNull(array: Array<Int>?): ByteStreamWriter {
    if (array == null) {
        return this
    }
    for (int in array) {
        writeUInt8(int)
    }
    return this
}

internal fun ByteStreamReader.readUInt8ArrayAsArray(bytes: Int): Array<Int> {
    return Array(bytes) { uInt8() }
}


internal fun ByteStreamWriter.writeUInt8Bool(value: Boolean): ByteStreamWriter {
    return writeUInt8(if (value) 1 else 0)
}