@file:Suppress("MemberVisibilityCanBePrivate", "unused")

package com.bedalton.creatures.breed.render.renderer

import com.bedalton.creatures.breed.render.support.pose.PoseRenderException
import com.bedalton.creatures.sprite.util.ColorPalette
import com.bedalton.creatures.sprite.util.bound
import com.bedalton.log.Log
import com.bedalton.log.wIf
import korlibs.image.bitmap.Bitmap32
import korlibs.image.color.RGBA
import kotlin.math.abs
import kotlin.math.floor
import kotlin.math.max

object Combinator {

    const val OPAQUE_WINS_DEFAULT = true

    /**
     * Overlays an image over the first (mutating), applying an alpha blend if requested
     */
    fun overlay(main: Bitmap32, other: Bitmap32, x: Int, y: Int, alpha: Double?, opaqueWins: Boolean? = null) {
        return overlay(main, other, x, y, alphaToInt(alpha), opaqueWins)
    }

    /**
     * Overlays an image over the first (mutating), applying an alpha blend if requested
     */
    fun overlay(main: Bitmap32, other: Bitmap32, x: Int, y: Int, alpha: Int? = null, opaqueWins: Boolean? = null) {
        if (other.width < 1 || other.width < 1) {
            throw PoseRenderException("Cannot overlay empty image range")
        }

        val maxX = minOf(main.width, x + other.width)
        val maxY = minOf(main.height, y + other.height)
        val endX = maxX - x
        val endY = maxY - y


        val alphaInt = (alpha ?: 255).bound()

        // Do not bother copying an image that is made completely transparent by alpha 0
        if (alphaInt == 0) {
            return
        }

        // Use built in combining method
        if (alphaInt == 255) {
            main.draw(other, x, y)
            return
        }

        // Get alpha conversion function
        val applyAlpha = getAlphaFunction(alphaInt, opaqueWins)

        val mainWidth = main.width
        val mainHeight = main.height

        var hasOpaquePixel = false
        for (yy in 0 until endY) {
            for (xx in 0 until endX) {
                val pixel = other[xx, yy]
                if (pixel.a < 127) {
                    continue
                } else if (!hasOpaquePixel) {
                    hasOpaquePixel = true
                }
                val originalX = x + xx
                val originalY = y + yy
                val original = if (mainWidth > originalX && mainHeight > originalY) {
                    main[originalX, originalY]
                } else {
                    null
                }
                main[originalX, originalY] = applyAlpha(original, pixel)
            }
        }
        if (!hasOpaquePixel) {
            Log.wIf("debug") { "Part is completely transparent" }
        }
    }

    /**
     * Overlays an image over a copy of another, growing image if necessary to fit
     * Function shifts the images right or down if x or y is negative and growToFit is true
     */
    fun overlayInCopy(main: Bitmap32, other: Bitmap32, x: Int, y: Int, growToFit: Boolean, alpha: Double?, opaqueWins: Boolean? = null): Bitmap32 {
        return overlayInCopy(main, other, x, y, growToFit, alphaToInt(alpha), opaqueWins)
    }

    /**
     * Overlays an image over a copy of another, growing image if necessary to fit
     * Function shifts the images right or down if x or y is negative and growToFit is true
     */
    fun overlayInCopy(
        main: Bitmap32,
        other: Bitmap32,
        x: Int,
        y: Int,
        growToFit: Boolean,
        alpha: Int? = null,
        opaqueWins: Boolean? = null
    ): Bitmap32 {

        // Get negative offsets if any
        val otherXOffset = minOf(x, 0)
        val otherYOffset = minOf(y, 0)

        // Get any offset that may occur from shifting a negative x, y to zero
        val mainX = if (growToFit) maxOf(-otherXOffset, 0) else 0
        val mainY = if (growToFit) maxOf(-otherYOffset, 0) else 0

        // Get offsets for other
        val otherX = if (growToFit) maxOf(0, x) else x
        val otherY = if (growToFit) maxOf(0, y) else y

        // Get true end of image
        val endX = if (growToFit) maxOf(mainY + main.width, otherX + other.width) else main.width
        val endY = if (growToFit) maxOf(mainY + main.height, otherY + other.height) else main.height

        // Create blank image on which to copy
        val out = if (growToFit && endX > main.width && endY > main.height) {
            // Bitmap is resized, so need to fill and copy at new location
            Bitmap32(endX, endY, false).apply {
                overlay(this, main, mainX, mainY)
            }
        } else {
            // Did not grow bitmap, so simply copy
            Bitmap32(main.width, main.height, false).apply {
                main.copyTo(this)
            }
        }

        // Copy the other image into a cropped slice if necessary
        val otherSlice = if (growToFit) {
            other
        } else if (x >= 0 && y >= 0) {
            // Image does not grow, crop image ends as needed
            val copyWidth = if (x + other.width > main.width) main.width - x else other.width
            val copyHeight = if (x + other.width > main.width) main.width - x else other.width
            if (copyWidth == other.width && copyHeight == other.height) {
                other
            } else {
                other.copySliceWithSize(0, 0, copyWidth, copyHeight)
            }
        } else {
            // Image does not grow, and image has a negative offset, so trim beginning as needed
            val copyX = if (growToFit) 0 else if (x < 0) -x else 0
            val copyY = if (growToFit) 0 else if (y < 0) -y else 0
            var copyWidth = other.width - copyX
            var copyHeight = other.height - copyY
            if (copyWidth + copyX > main.width) {
                copyWidth = main.width - copyX
            }
            if (copyHeight + copyX > main.height) {
                copyHeight = main.height - copyY
            }
            other.copySliceWithSize(copyX, copyY, copyWidth, copyHeight)
        }
        overlay(out, otherSlice, maxOf(0, x), maxOf(0, y), alpha, opaqueWins)
        return out
    }

    /**
     * Overlays one image over a copy of the first
     */
    fun overlayInCopy(main: Bitmap32, other: Bitmap32, x: Int, y: Int, alpha: Double?, opaqueWins: Boolean = false): Bitmap32 {
        return overlayInCopy(main, other, x, y, alphaToInt(alpha), opaqueWins)
    }

    /**
     * Overlays one image over a copy of the first
     */
    fun overlayInCopy(main: Bitmap32, other: Bitmap32, x: Int, y: Int, alpha: Int? = null, opaqueWins: Boolean = false): Bitmap32 {
        val copy = Bitmap32(main.width, main.height, false)
        main.copyTo(copy)
        overlay(copy, other, x, y, alpha, opaqueWins)
        return copy
    }

    /**
     * Convert the alpha double to an integer 0..255
     */
    private fun alphaToInt(alpha: Double?, errorTolerance: Double = 0.005): Int {
        if (alpha == null) {
            return 255
        }
        return if (abs(alpha) <= errorTolerance) {
            0
        } else if (abs(alpha - 1) < errorTolerance) {
            255
        } else {
            max(1, floor(alpha * 255).toInt())
        }
    }

    /**
     * Function to handle applying one color to another
     * This is done naively, and may not produce the expected results
     */
    private fun getAlphaFunction(alpha: Int, opaqueWins: Boolean? = null): (original: RGBA?, pixel: RGBA) -> RGBA {

        // No use trying to apply completely transparent pixels
        if (alpha == 0) {
            return { original, _ -> original ?: ColorPalette.TRANSPARENT_BLACK }
        }
        if (alpha == 255) {
            return { _, pixel -> pixel }
        }

        val aMod = alpha / 255.0
        // If 0 or 1, return
        return if (alpha.bound() in 1 until 255) {
            { original: RGBA?, pixel: RGBA ->
                // Blend pixels if original has pixels
                if ((opaqueWins ?: OPAQUE_WINS_DEFAULT) && original?.a == 255) {
                    original
                } else if (original != null && original.a > 0 && original.a != alpha) {
                    val oMod = (original.a / 255.0) - aMod
                    RGBA(
                        ((original.r * oMod) + (pixel.r * aMod)).toInt(),
                        ((original.g * oMod) + (pixel.g * aMod)).toInt(),
                        ((original.b * oMod) + (pixel.b * aMod)).toInt(),
                        original.a + alpha
                    )
                } else {
                    pixel.withA(alpha)
                }
            }
        } else {
            { _, pixel -> pixel }
        }
    }
}