package com.bedalton.creatures.agents.pray.compiler.pray.validators

import com.bedalton.creatures.agents.pray.compiler.pray.PrayValidationError
import com.bedalton.creatures.agents.pray.compiler.data.CompilerEggBlock
import com.bedalton.creatures.agents.pray.compiler.data.Tags
import com.bedalton.creatures.agents.util.internal.GENETICS_FILE_EXTENSIONS
import com.bedalton.creatures.agents.util.internal.SPRITE_EXTENSIONS

/**
 * Responsible for validating EGG blocks
 */
internal fun validatePrayEggBlock(fullFilePath: String, block: CompilerEggBlock, errors: MutableList<PrayValidationError>) {

    val addError = addErrorLambda(fullFilePath, errors, block)
    val tags = block.tags
    // Validate agent lists "Agent Type" 0
    validateHasAgentType0(addError, tags)
    validateTagWithFileExtension(addError, "Egg Glyph File", SPRITE_EXTENSIONS, tags)
    validateTagWithFileExtension(addError, "Egg Glyph File 2", SPRITE_EXTENSIONS, tags)
    validateEggGlyphFile(addError, tags)
    validateTagWithFileWithoutExtension(addError, "Egg Gallery male", SPRITE_EXTENSIONS, tags)
    validateTagWithFileWithoutExtension(addError, "Egg Gallery female", SPRITE_EXTENSIONS, tags)
    validateTagWithFileWithoutExtension(addError, "Mother Genetic File", SPRITE_EXTENSIONS, tags)
    validateTagWithFileWithoutExtension(addError, "Father Genetic File", GENETICS_FILE_EXTENSIONS, tags)
    validateTagWithFileWithoutExtension(addError, "Genetics File", GENETICS_FILE_EXTENSIONS, tags)
}


private fun validateEggGlyphFile(
    addError: AddError,
    tags: Tags
) {
    val regex = "^Egg\\s+Glyph\\s+File\\s+(\\d+)$".toRegex(RegexOption.IGNORE_CASE)
    // Only need to check that glyph int is null or equals 2
    // If null, glyph is for male
    val glyphTags = tags.filter { tag -> regex.matchEntire(tag.tag)?.let { regexResult -> regexResult.groupValues.last() != "2"} ?: false }
    for (tag in glyphTags) {
        addError(
            tag,
            "\"${tag.tag}\" is out of range. Tag should be \"Egg Glyph File\" or \"Egg Glyph File 2\""
        )
    }
}
