@file:Suppress("unused")

package com.bedalton.creatures.breed.render.support.pose

import com.bedalton.creatures.common.structs.GameVariant
import kotlinx.serialization.Serializable
import kotlin.js.JsExport
import kotlin.js.JsName

/**
 * Creature moods for calculating their facial expressions
 */
@Serializable
@JsExport
enum class Mood(val int: Int, aliases: Set<String>) {
    NORMAL(PoseConstants.Mood.NORMAL, setOf("normal", "neutral")),
    HAPPY(PoseConstants.Mood.HAPPY, setOf("happy")),
    SAD(PoseConstants.Mood.SAD, setOf("sad")),
    ANGRY(PoseConstants.Mood.ANGRY, setOf("angry", "mad")),
    SCARED(PoseConstants.Mood.SCARED, setOf("scared", "worried")),
    SLEEPY(PoseConstants.Mood.SLEEPY, setOf("sleepy", "tired")),
    VERY_SLEEPY_CV_ONLY(PoseConstants.Mood.CV.VERY_SLEEPY, setOf("very sleepy", "very tired")),
    VERY_HAPPY_CV_ONLY(PoseConstants.Mood.CV.VERY_HAPPY, setOf("very happy")),
    MISCHIEVOUS_CV_ONLY(PoseConstants.Mood.CV.MISCHIEVOUS, setOf("mischievous")),
    VERY_SCARED_CV_ONLY(PoseConstants.Mood.CV.VERY_SCARED, setOf("very scared", "very worried")),
    ILL_CV_ONLY(PoseConstants.Mood.CV.ILL, setOf("ill", "sick")),
    HUNGRY_CV_ONLY(PoseConstants.Mood.CV.HUNGRY, setOf("hungry"));


    /**
     * Lookup regex
     */
    private val regex by lazy {
        ("(" + aliases.joinToString(")|(") {
            it.replace(" ", "\\s*")
        } + ")" ).lowercase().toRegex(RegexOption.IGNORE_CASE)
    }

    @Suppress("NON_EXPORTABLE_TYPE")
    @JsName("isValidForVariantNoJS")
    fun isValidForVariant(variant: GameVariant): Boolean {
        return isValidForVariant(variant, this)
    }

    fun isValidForVariant(variant: String): Boolean {
        return isValidForVariant(variant, this.int)
    }

    @Suppress("NON_EXPORTABLE_TYPE")
    fun assertIsValidForVariant(variant: GameVariant) {
        if (isValidForVariant(variant)) {
            return
        }
        val valid = when (variant) {
            GameVariant.C1 -> setOf(NORMAL, HAPPY, SAD, ANGRY)
            GameVariant.CV -> values().toSet()
            else -> setOf(NORMAL, HAPPY, SAD, ANGRY, SCARED, SLEEPY)
        }
        val mood = name.replaceFirstChar { it.uppercaseChar() }
        val validMoodsAsString = valid.joinToString { it.name.replaceFirstChar { firstChar -> firstChar.uppercaseChar() } }
        val message = "Mood $mood is invalid for $variant; Valid moods are [$validMoodsAsString]"
        throw PoseException(message)
    }


    companion object {
        @Suppress("NON_EXPORTABLE_TYPE")
        @JsName("validForVariantFromEnums")
        fun isValidForVariant(variant: GameVariant, mood: Mood): Boolean {
            return when (variant) {
                GameVariant.C1 -> mood.int <= PoseConstants.Mood.ANGRY
                GameVariant.CV -> true
                else -> mood.int <= PoseConstants.Mood.SLEEPY
            }
        }
        @Suppress("NON_EXPORTABLE_TYPE")
        @JsName("validForVariantInt")
        fun isValidForVariant(variant: GameVariant, mood: Int): Boolean {
            return when (variant) {
                GameVariant.C1 -> mood < PoseConstants.Mood.ANGRY
                GameVariant.CV -> true
                else -> mood <= PoseConstants.Mood.SLEEPY
            }
        }

        @JsName("validForVariant")
        fun isValidForVariant(variantString: String, mood: Int): Boolean {
            val variant = GameVariant.fromString(variantString)
                ?: throw PoseException("Invalid variant '$variantString'")
            return when (variant) {
                GameVariant.C1 -> mood < PoseConstants.Mood.ANGRY
                GameVariant.CV -> true
                else -> mood <= PoseConstants.Mood.SLEEPY
            }
        }

        fun fromString(string: String): Mood? {
            val mood = string.lowercase()
            return values().firstOrNull { it.regex.matches(mood) }
        }

        fun fromInt(int: Int): Mood? {
            return when(int) {
                NORMAL.int -> NORMAL
                HAPPY.int -> HAPPY
                SAD.int -> SAD
                ANGRY.int -> ANGRY
                SCARED.int -> SCARED
                SLEEPY.int -> SLEEPY
                VERY_SLEEPY_CV_ONLY.int -> VERY_SLEEPY_CV_ONLY
                VERY_HAPPY_CV_ONLY.int -> VERY_HAPPY_CV_ONLY
                MISCHIEVOUS_CV_ONLY.int -> MISCHIEVOUS_CV_ONLY
                VERY_SCARED_CV_ONLY.int -> VERY_SCARED_CV_ONLY
                ILL_CV_ONLY.int -> ILL_CV_ONLY
                HUNGRY_CV_ONLY.int -> HUNGRY_CV_ONLY
                else -> null
            }
        }
    }
}