@file:Suppress("unused")

package com.bedalton.common.util

import com.bedalton.log.LOG_DEBUG
import com.bedalton.log.LOG_VERBOSE
import com.bedalton.log.Log

private val defaultLogStackTrace get() = Log.hasMode(LOG_DEBUG) || Log.hasMode(LOG_VERBOSE)

fun Throwable.formatted(printStackTrace: Boolean? = defaultLogStackTrace): String {
    val message = message?.let { ": $it" } ?: ""
    val stack = if (printStackTrace ?: Log.hasMode(LOG_DEBUG)) {
        '\n' + stackTraceToString()
    } else {
        ""
    }
    return "${className}$message$stack"
}