package com.bedalton.creatures.genetics.parser

import com.bedalton.creatures.genetics.gene.*
import com.bedalton.creatures.genetics.gene.GeneConstants.GENE_SUBTYPE_CREATURE_APPEARANCE
import com.bedalton.creatures.genetics.gene.GeneConstants.GENE_SUBTYPE_CREATURE_FACIAL_EXPRESSION
import com.bedalton.creatures.genetics.gene.GeneConstants.GENE_SUBTYPE_CREATURE_GAIT
import com.bedalton.creatures.genetics.gene.GeneConstants.GENE_SUBTYPE_CREATURE_GENUS
import com.bedalton.creatures.genetics.gene.GeneConstants.GENE_SUBTYPE_CREATURE_INSTINCT
import com.bedalton.creatures.genetics.gene.GeneConstants.GENE_SUBTYPE_CREATURE_PIGMENT
import com.bedalton.creatures.genetics.gene.GeneConstants.GENE_SUBTYPE_CREATURE_PIGMENT_BLEED
import com.bedalton.creatures.genetics.gene.GeneConstants.GENE_SUBTYPE_CREATURE_POSE
import com.bedalton.creatures.genetics.gene.GeneConstants.GENE_SUBTYPE_CREATURE_STIMULUS
import com.bedalton.io.bytes.ByteStreamReader

internal fun readCreatureGene(version: Int, reader: ByteStreamReader, geneIndex: Int): Gene {
    return when (val subType = reader.uInt8()) {
        GENE_SUBTYPE_CREATURE_STIMULUS -> CreatureStimulusGene.fromReader(version, reader, geneIndex)
        GENE_SUBTYPE_CREATURE_GENUS -> GenusGene.fromReader(version, reader, geneIndex)
        GENE_SUBTYPE_CREATURE_APPEARANCE -> AppearanceGene.fromReader(version, reader, geneIndex)
        GENE_SUBTYPE_CREATURE_POSE -> PoseGene.fromReader(version, reader, geneIndex)
        GENE_SUBTYPE_CREATURE_GAIT -> GaitGene.fromReader(version, reader, geneIndex)
        GENE_SUBTYPE_CREATURE_INSTINCT -> InstinctGene.fromReader(version, reader, geneIndex)
        GENE_SUBTYPE_CREATURE_PIGMENT -> PigmentGene.fromReader(version, reader, geneIndex)
        GENE_SUBTYPE_CREATURE_PIGMENT_BLEED -> PigmentBleedGene.fromReader(version, reader, geneIndex)
        GENE_SUBTYPE_CREATURE_FACIAL_EXPRESSION -> FacialExpressionGene.fromReader(version, reader, geneIndex)
        else -> throw GenomeParseException("Failed to understand gene type: Creature(2)->[$subType]")
    }
}

