@file:Suppress("MemberVisibilityCanBePrivate", "unused")

package com.bedalton.creatures.agents.pray.compiler

import com.bedalton.common.exceptions.IOException
import com.bedalton.common.util.PathUtil
import com.bedalton.creatures.agents.pray.compiler.CompilerOptionsDefault.DEFAULT_GENERATE_AGENT_REMOVERS
import com.bedalton.creatures.agents.pray.compiler.CompilerOptionsDefault.DEFAULT_GENERATE_SCRIPT_REMOVERS
import com.bedalton.creatures.agents.pray.compiler.CompilerOptionsDefault.DEFAULT_LOG_PROGRESS
import com.bedalton.creatures.agents.pray.compiler.CompilerOptionsDefault.DEFAULT_MERGE_RSCR
import com.bedalton.creatures.agents.pray.compiler.CompilerOptionsDefault.DEFAULT_MERGE_SCRIPTS
import com.bedalton.creatures.agents.pray.compiler.CompilerOptionsDefault.DEFAULT_VALIDATE
import kotlin.js.JsExport
import kotlin.js.JsName


/**
 * Pray compiler task
 *
 * @property pure whether to make this task mutable or immutable
 * @constructor
 *
 * @param inputFile
 * @param outputDirectory
 */
@JsExport
open class PrayCompilerTask(
    inputFile: String,
    outputDirectory: String,
    val pure: Boolean = false,
) : IPrayCompilerTask,
    PrayCompileOptionsWithOverrideName,
    PrayCompileOptionsWithRecursiveJoin,
    PrayCompileOptionsWithLinkWithFileName {

    @Suppress("NON_EXPORTABLE_TYPE")
    @JsName("fromCompilerTask")
    constructor(task: IPrayCompilerTask, pure: Boolean = false) : this(
        task.inputFile,
        task.outputDirectory,
        pure,
    ) {
        this.mMergeScripts = task.mergeScripts
        this.mMergeRscr = task.mergeRscr
        this.mJoins = task.joins.copyOf()
        this.mGenerateScriptRemovers = task.generateScriptRemovers
        this.mGenerateAgentRemovers = task.generateAgentRemovers
        this.mPrintStats = task.printStats
        this.mValidate = task.validate
        this.mIsJoin = task.isJoin
        this.mCompressionLevel = task.compressionLevel
        this.mRecursiveJoins = task.recursiveJoinsOrNull
        this.mOverrideAgentName = task.overrideAgentNameOrNull
    }

    // ================= //
    // == Input File === //
    // ================= //
    private var mInputFile = inputFile.apply {
        if (!PathUtil.isAbsolute(this)) {
            throw IOException("Pray input file must be absolute; Found: <$this>")
        }
    }

    /**
     * The fully qualified path to the PRAY File
     */
    override val inputFile: String get() = mInputFile

    /**
     * The fully qualified path to the PRAY File
     */
    fun withInputFile(file: String): PrayCompilerTask {
        return copy {
            this.mInputFile = file
        }
    }

    // ======================== //
    // === Output Directory === //
    // ======================== //
    private var mOutputDirectory = outputDirectory.apply {
        if (!PathUtil.isAbsolute(this)) {
            throw IOException("Pray output directory must be absolute. Found: $this")
        }
    }

    /**
     * The absolute path to the target location for this compiled agent
     */
    override val outputDirectory: String
        get() = mOutputDirectory

    /**
     * The absolute path to the target location for this compiled agent
     */
    fun withOutputDirectory(directory: String): PrayCompilerTask {
        return copy {
            this.mOutputDirectory = directory
        }
    }

    // =================== //
    // === Print Stats === //
    // =================== //
    private var mPrintStats: Boolean? = null

    /**
     * Whether to log information about classes and scripts in pray files
     */
    override val printStats: Boolean
        get() = this.mPrintStats ?: CompilerOptionsDefault.DEFAULT_PRINT_STATS

    /**
     * Whether to log information about classes and scripts in pray files
     */
    fun withPrintStats(print: Boolean?): PrayCompilerTask {
        return copy {
            this.mPrintStats = print
        }
    }

    // ==================== //
    // === Log Progress === //
    // ==================== //

    // @private //
    private var mLogProgress: Boolean? = null

    /**
     * Whether to Log compilation progress
     */
    override val logProgress: Boolean
        get() = mLogProgress ?: DEFAULT_LOG_PROGRESS

    /**
     * Whether to Log compilation progress
     */
    fun withLogProgress(log: Boolean?): PrayCompilerTask {
        return copy {
            this.mLogProgress = log
        }
    }


    // ===================== //
    // === Merge Scripts === //
    // ===================== //

    private var mMergeScripts: Boolean? = null

    /**
     * Whether to merge all scripts into one script
     */
    override val mergeScripts: Boolean
        get() = this.mMergeScripts ?: DEFAULT_MERGE_SCRIPTS

    /**
     * Whether to merge all scripts into one script
     */
    fun withMergeScripts(merge: Boolean?): PrayCompilerTask {
        return copy {
            this.mMergeScripts = merge
        }
    }

    // ================ //
    // === VALIDATE === //
    // ================ //
    private var mValidate: Boolean? = null

    /**
     * Whether to validate the syntax and links in a pray file
     */
    fun withValidate(validate: Boolean?): PrayCompilerTask {
        return copy {
            this.mValidate = validate
        }
    }

    /**
     * Whether to validate the syntax and links in a pray file
     */
    override val validate: Boolean
        get() = this.mValidate ?: DEFAULT_VALIDATE


    // ======================= //
    // ======= IS JOIN ======= //
    // ======================= //
    private var mIsJoin: Boolean? = null

    /**
     * Whether this agent is meant to be merged into a multi-agent bundle
     */
    override val isJoin: Boolean get() = mIsJoin ?: false

    /**
     * Whether this agent is meant to be merged into a multi-agent bundle
     */
    fun withIsJoin(join: Boolean?): PrayCompilerTask {
        return copy {
            this.mIsJoin = join
        }
    }

    /**
     * Mark this agent as needing to be merged into a multi-agent bundle
     */
    override fun asJoin(): PrayCompilerTask {
        return copy {
            this.mIsJoin = true
        }
    }

    // ===================== //
    // ======= JOINS ======= //
    // ===================== //

    private var mJoins: Array<String> = emptyArray()

    /**
     * Array of PRAY files for agents that should be merged into a single agent bundle
     */
    override val joins: Array<String>
        get() = mJoins


    /**
     * Array of PRAY files for agents that should be merged into a single agent bundle
     */
    override fun withJoins(joins: Array<String>): PrayCompilerTask {
        return copy {
            this.mJoins = joins
        }
    }

    // ================================ //
    // === Generate Script Removers === //
    // ================================ //
    private var mGenerateScriptRemovers: Boolean? = null

    /**
     * Whether to automatically generate removers for all event scripts in PRAY source
     */
    override val generateScriptRemovers: Boolean
        get() = mGenerateScriptRemovers ?: DEFAULT_GENERATE_SCRIPT_REMOVERS

    /**
     * Whether to automatically generate removers for all event scripts in PRAY source
     */
    fun withGenerateScriptRemovers(generate: Boolean?): PrayCompilerTask {
        return copy {
            this.mGenerateScriptRemovers = generate
        }
    }

    // =============================== //
    // === Generate Agent Removers === //
    // =============================== //
    private var mGenerateAgentRemovers: Boolean? = null

    /**
     * Create removers for all created agent classifiers
     * Parses new: (simp|comp|*) creation statements and generates a remover for that class
     */
    override val generateAgentRemovers: Boolean
        get() = this.mGenerateAgentRemovers ?: DEFAULT_GENERATE_AGENT_REMOVERS

    /**
     * Create removers for all created agent classifiers
     * Parses new: (simp|comp|*) creation statements and generates a remover for that class
     */
    fun withGenerateAgentRemovers(generate: Boolean?): PrayCompilerTask {
        return copy {
            this.mGenerateAgentRemovers = generate
        }
    }

    // ================== //
    // === Merge RSCR === //
    // ================== //

    private var mMergeRscr: Boolean? = null

    /**
     * Whether to merge all removal scripts into a single massive removal script
     */
    override val mergeRscr: Boolean
        get() = mMergeRscr ?: DEFAULT_MERGE_RSCR

    /**
     * Whether to merge all removal scripts into a single massive removal script
     */
    fun withMergeRscr(merge: Boolean?): PrayCompilerTask {
        return copy {
            this.mMergeRscr = merge
        }
    }

    // ========================== //
    // === JOIN KEEP FILENAME === //
    // ========================== //

    private var mLinkFilenameWithReference: Boolean? = null

    /**
     * Whether to add a comment at start of linked script with filename
     */
    override val linkWithFilenameReference: Boolean? get() = mLinkFilenameWithReference

    /**
     * Whether to add a comment at start of linked script with filename
     */
    fun withLinkWithFilenameReference(link: Boolean?): PrayCompilerTask {
        mLinkFilenameWithReference = link
        return this
    }

    // ================== //
    // ==  Compression == //
    // ================== //
    
    private var mCompressionLevel: Int? = null

    /**
     * Level of GZIP compression to apply [0-9]; 0/null=None; 9=Max
     */
    override val compressionLevel: Int?
        get() = mCompressionLevel

    /**
     * Level of GZIP compression to apply
     * 0/null = no compression
     */
    fun withCompressionLevel(level: Int?): PrayCompilerTask {
        return this.copy {
            this.mCompressionLevel = level
        }
    }

    // ====================== //
    // ==  Recursive Joins == //
    // ====================== //


    private var mRecursiveJoins: Boolean? = null

    override val recursiveJoins: Boolean? get() = mRecursiveJoins

    fun setRecursiveJoins(recursive: Boolean?): PrayCompilerTask {
        mRecursiveJoins = recursive
        return this
    }


    // ====================== //
    // ==  Recursive Joins == //
    // ====================== //
    private var mOverrideAgentName: String? = null

    /**
     * Override the CAOS2Pray supplied agent file name
     */
    override val overrideAgentName: String?
        get() = mOverrideAgentName

    /**
     * Override the CAOS2Pray supplied agent file name
     */
    fun setOverrideAgentName(value: String?): PrayCompilerTask {
        this.mOverrideAgentName = value
        return this
    }


    // ================== //
    // === Copy === //
    // ================== //

    fun copy(pure: Boolean = this.pure): PrayCompilerTask {
        val out = PrayCompilerTask(inputFile, outputDirectory, pure)
        out.mLogProgress = logProgress
        out.mMergeRscr = mMergeRscr
        out.mMergeScripts = mMergeScripts
        out.mIsJoin = mIsJoin
        out.mJoins = mJoins.copyOf()
        out.mGenerateAgentRemovers = mGenerateAgentRemovers
        out.mGenerateScriptRemovers = mGenerateScriptRemovers
        out.mLogProgress = mLogProgress
        out.mPrintStats = mPrintStats
        out.mValidate = mValidate
        out.mCompressionLevel = mCompressionLevel
        return out
    }

    private fun copy(work: PrayCompilerTask.() -> Unit): PrayCompilerTask {
        return (if (pure) copy() else this).apply {
            this.work()
        }
    }


}


fun PrayCompilerTask.withLogProgress(): PrayCompilerTask {
    return withLogProgress(true)
}

fun PrayCompilerTask.withMergeRscr(): PrayCompilerTask {
    return withMergeRscr(true)
}