import com.creaturesforge.application.compile.EggCompiler
import com.creaturesforge.application.interop.tauriMiddleware

internal actual fun getMiddleware(): List<Middleware<ForgeState, FAction>> {
    return listOf(
        tauriMiddleware,
        alterSettingsMiddleware,
        ::eggModeMiddleware,
        ::filesListMiddleware,
        ::preCompileMiddleware,
        EggCompiler::compileMiddleware,
