package com.creaturesforge.application.interop

import com.bedalton.common.util.formatted
import com.bedalton.log.Log
import com.bedalton.state.simple.Dispatch
import com.creaturesforge.application.state.*


internal object DisabledSettingsInterop {


    private const val SET_GENOME_DISABLED_IN_TAURI = "set_genome_list_disabled_in_tauri"
    private const val SET_PROJECT_SETTINGS_CACHE_DISABLED_IN_TAURI = "set_project_settings_cached_disabled_in_tauri"

    private lateinit var state: ForgeState
    private lateinit var dispatch: Dispatch<FAction>

    init {
        ForgeStore.subscribe { state, dispatch ->
            this.state = state
            this.dispatch = dispatch
        }
    }

    fun setGenomeListDisabledInTauri(disabled: Boolean) {
        try {
            tauriInvoke<Boolean>(SET_GENOME_DISABLED_IN_TAURI) {
                this.disabled = disabled
            }
        } catch (e: Throwable) {
            Log.e {"Failed to set genome list to ${disabled.disabledText}; ${e.formatted()}" }
        }
    }

    internal suspend fun updatePreviousGenomeListDisabledInTauri() {
        setGenomeListDisabledInTauri(ForgeConfig.isPreviousGenomeListDisabled())
    }

    internal fun setDisableCachedProjectSettingsInTauri(disabled: Boolean) {
        tauriInvoke<Boolean>(SET_PROJECT_SETTINGS_CACHE_DISABLED_IN_TAURI) {
            this.disabled = disabled
        }
    }

    internal suspend fun updateProjectSettingReloadDisabledInTauri() {
        setDisableCachedProjectSettingsInTauri(ForgeConfig.isProjectSettingsCacheDisabled())
    }

    private val Boolean.disabledText: String get() = if (this) {
        "disabled"
    } else {
        "enabled"
    }
}
