@file:Suppress("unused")

package com.bedalton.log

import com.bedalton.log.internal.getLogColorPrefix
import kotlin.js.JsExport


private typealias LogStatement = (message: String, color: LoggerColor?) -> Unit

private typealias LogWithReplace = (replace: Boolean, message: String, color: LoggerColor?) -> Unit


/**
 * Creates a logger using implementations of each logging kind
 */
internal data class CallbackLogger(
    val mLog: LogWithReplace?,
    val mInfo: LogWithReplace?,
    val mWarning: LogStatement?,
    val mError: LogStatement?,
    val mLogMemory:(() -> Unit)?,
    val mGetColor: ((color: LoggerColor?) -> String?)?,
    override var prependLogType: Boolean? = null
): ILoggerObject {
    override fun log(replace: Boolean, message: String, color: LoggerColor?) {
        mLog?.invoke(replace, message, color)
    }
    override fun info(replace: Boolean, message: String, color: LoggerColor?) {
        mInfo?.invoke(replace, message, color)
    }
    override fun warning(message: String, color: LoggerColor?) {
        mWarning?.invoke(message, color)
    }
    override fun error(message: String, color: LoggerColor?) {
        mError?.invoke(message, color)
    }
    override fun logMemory() {
        mLogMemory?.invoke()
    }

    override fun getColorPrefix(color: LoggerColor?): String? {
        return (mGetColor ?: ::getLogColorPrefix).invoke(color)
    }
}


/**
 * Allows building a logger command by command
 */
@JsExport
class LoggerBuilder {
    private var mLog: LogWithReplace? = null
    private var mInfo: LogWithReplace? = null
    private var mWarning: LogStatement? = null
    private var mError: LogStatement? = null
    private var mLogMemory: (() -> Unit)? = null
    private var mGetColor: ((color: LoggerColor?) -> String?)? = null

    fun withLog(log: LogWithReplace) {
        mLog = log
    }
    fun info(log: LogWithReplace): LoggerBuilder {
        mInfo = log
        return this
    }
    fun warning(log: LogStatement): LoggerBuilder {
        mWarning = log
        return this
    }
    fun error(log: LogStatement): LoggerBuilder {
        mError = log
        return this
    }
    fun logMemory(log: () -> Unit): LoggerBuilder {
        mLogMemory = log
        return this
    }

    fun getColor(callback: ((color: LoggerColor?) -> String?)?): LoggerBuilder {
        this.mGetColor = callback
        return this
    }

    @Suppress("NON_EXPORTABLE_TYPE")
    fun build(): ILoggerObject {
        return CallbackLogger(
            mLog, mInfo, mWarning, mError, mLogMemory, mGetColor,
        )
    }
}