package com.bedalton.vfs

import com.bedalton.common.structs.DataCache
import com.bedalton.common.exceptions.IOException
import com.bedalton.common.util.MD5
import com.bedalton.vfs.internal.toHexString

data class BinaryFile constructor(
    override var name: String,
    private var bytes: ByteArray?,
    override var mimeType: String? = null,
) : MemoryFile() {


    private var md5Cache: DataCache<String>? = DataCache {
        MD5.compute(read()).toHexString()
    }

    /**
     * Read bytes from the file
     */
    override suspend fun read(): ByteArray {
        assertNotDisposed()
        return bytes
            ?: throw IOException("File $name already disposed")
    }

    init {
        if (bytes == null) {
            throw IOException("In memory binary file cannot be created with null data")
        }
    }

    override fun disposeInternal() {
        bytes = null
        md5Cache?.dispose()
        md5Cache = null
    }

    override suspend fun md5(): String {
        return md5Cache?.getData()
            ?: throw IOException("Cannot get MD5, file data already disposed")
    }

    override fun equals(other: Any?): Boolean {
        if (this === other) return true
        if (other == null || this::class != other::class) return false

        other as BinaryFile

        if (name != other.name) return false
        if (bytes != null) {
            if (other.bytes == null) return false
            if (!bytes.contentEquals(other.bytes)) return false
        } else if (other.bytes != null) return false
        if (mimeType != other.mimeType) return false

        return true
    }

    override fun hashCode(): Int {
        var result = name.hashCode()
        result = 31 * result + (bytes?.contentHashCode() ?: 0)
        result = 31 * result + (mimeType?.hashCode() ?: 0)
        return result
    }
}