@file:Suppress("MemberVisibilityCanBePrivate")

package com.bedalton.creatures.breed.render.support.pose

/**
 * Holds part chars by part name
 */
@Suppress("unused")
object PartChars {
    const val HEAD = 'a'
    const val BODY = 'b'

    const val LEFT_THIGH = 'c'
    const val LEFT_SHIN = 'd'
    const val LEFT_FOOT = 'e'

    const val RIGHT_THIGH = 'f'
    const val RIGHT_SHIN = 'g'
    const val RIGHT_FOOT = 'h'

    const val LEFT_UPPER_ARM = 'i'
    const val LEFT_FOREARM = 'j'

    const val RIGHT_UPPER_ARM = 'k'
    const val RIGHT_FOREARM = 'l'

    const val TAIL_BASE = 'm'
    const val TAIL_TIP = 'n'

    const val LEFT_EAR = 'o'
    const val RIGHT_EAR = 'p'

    const val HAIR = 'q'

    val ALL_PARTS = arrayOf(
        'a', 'b', 'c', 'd', 'e', 'f', 'g', 'h', 'i', 'j', 'k', 'l', 'm', 'n', 'o', 'p', 'q'
    )

    val REQUIRED_HEAD_PARTS get() = arrayOf(HEAD)

    val OPTIONAL_HEAD_PARTS get() = arrayOf(LEFT_EAR, RIGHT_EAR, HAIR)

    val REQUIRED_AND_OPTIONAL_HEAD_PARTS get() = arrayOf(HEAD, LEFT_EAR, RIGHT_EAR, HAIR)

    val BODY_PARTS get() = arrayOf(BODY)

    val LEFT_LEG_PARTS get() = arrayOf(LEFT_THIGH, LEFT_SHIN, LEFT_FOOT)

    val RIGHT_LEG_PARTS get() = arrayOf(RIGHT_THIGH, RIGHT_SHIN, RIGHT_FOOT)

    val LEG_PARTS = LEFT_LEG_PARTS + RIGHT_LEG_PARTS

    val LEFT_ARM_PARTS = arrayOf(LEFT_UPPER_ARM, LEFT_FOREARM)

    val RIGHT_ARM_PARTS = arrayOf(RIGHT_UPPER_ARM, RIGHT_FOREARM)

    val ARM_PARTS = LEFT_ARM_PARTS + RIGHT_ARM_PARTS

    val TAIL_PARTS = arrayOf(TAIL_BASE, TAIL_TIP)

    val EAR_PARTS = arrayOf(LEFT_EAR, RIGHT_EAR)

    val HAIR_PARTS = arrayOf(HAIR)

    fun appearanceGenePartsOrEmptyArray(appearanceGenePartInt: Int): Array<Char> {
        return appearanceGenePartsOrNull(appearanceGenePartInt)
            ?: emptyArray()
    }

    fun appearanceGenePartsOrNull(appearanceGenePartInt: Int): Array<Char>? {
        return when (appearanceGenePartInt) {
            0 -> REQUIRED_HEAD_PARTS + EAR_PARTS
            1 -> BODY_PARTS
            2 -> LEG_PARTS
            3 -> ARM_PARTS
            4 -> TAIL_PARTS
            5 -> HAIR_PARTS
            else -> null
        }
    }
}