@file:Suppress("unused")

package com.bedalton.vfs

import com.bedalton.common.exceptions.IOException
import com.bedalton.common.util.JsExport
import com.bedalton.vfs.Overwrite.Answer
import com.bedalton.vfs.Overwrite.Default
import kotlin.js.JsName


/**
 * Callback for asking if a file should be overwritten
 */
typealias ShouldOverwriteCallbackAsync = suspend (filePath: String) -> ShouldOverwrite

/**
 * Global value for the "should-overwrite" callback.
 * Used to overwrite the local CLI behavior by a GUI program
 */
private var askShouldOverwriteOverride: Pair<ShouldOverwriteCallbackAsync, OverwriteAllNone?>? = null

/**
 * Sets the simple callback of  *suspend (filePath: String) -> Boolean*
 * To use when generically calling promptShouldOverwrite()
 * Returns a holder for setting the always none outside the callback
 */
fun setShouldOverwriteCallback(
    callback: ShouldOverwriteCallbackAsync,
    overwriteAllNone: OverwriteAllNone?
): OverwriteAllNone {
    val allNone = OverwriteAllNone()
    askShouldOverwriteOverride = Pair(callback, overwriteAllNone)
    return allNone
}

/**
 * Sets the simple callback of  *suspend (filePath: String) -> Boolean*
 * To use when generically calling promptShouldOverwrite()
 * Returns a holder for setting the always none outside the callback
 */
fun setShouldOverwriteCallback(
    callback: ShouldOverwriteCallbackAsync
): OverwriteAllNone {
    val allNone = OverwriteAllNone()
    askShouldOverwriteOverride = Pair(callback, allNone)
    return allNone
}

/**
 * Sets the simple callback of  *suspend (filePath: String) -> Boolean*
 * To use when generically calling promptShouldOverwrite()
 * Returns a holder for setting the always none outside the callback
 */
fun setShouldOverwriteCallbackWithoutImplicitAlwaysNever(
    callback: ShouldOverwriteCallbackAsync
): OverwriteAllNone {
    val alwaysNever = OverwriteAllNone()
    askShouldOverwriteOverride = Pair(callback, alwaysNever)
    return alwaysNever
}

/**
 * Sets the simple callback of  *suspend (filePath: String) -> Boolean* if it is not already set
 * This is used when generically calling promptShouldOverwrite()
 */
fun setShouldOverwriteCallbackIfNotSet(callback: ShouldOverwriteCallbackAsync) {
    if (askShouldOverwriteOverride == null) {
        setShouldOverwriteCallback(callback)
    }
}

/**
 * Ensures that a file should be written,
 * without using/setting overwrite ALWAYS or NEVER
 */
suspend fun promptShouldOverwrite(
    fileSystem: FileSystem,
    outputFilePath: String
): Boolean {
    val ask = askShouldOverwriteOverride
        ?: throw IOException("Cannot prompt shouldOverwrite without first setting ask handler")
    return promptShouldOverwrite(
        fileSystem = fileSystem,
        outputFilePath = outputFilePath,
        overwriteAllNone = ask.second,
        callback = ask.first
    )
}

/**
 * Ensures that a file should be written
 * without using/setting overwrite ALWAYS or NEVER
 */
suspend fun promptShouldOverwrite(
    fileSystem: FileSystem,
    outputFilePath: String,
    callback: ShouldOverwriteCallbackAsync
): Boolean {
    return promptShouldOverwrite(
        fileSystem = fileSystem,
        outputFilePath = outputFilePath,
        overwriteAllNone = null,
        callback = callback
    )
}



/**
 * Ensures that a file should be written
 * Takes into account and possibly sets overwrite ALWAYS / NEVER
 */
suspend fun promptShouldOverwrite(
    fileSystem: FileSystem,
    outputFilePath: String,
    overwriteAllNone: OverwriteAllNone?,
    callback: ShouldOverwriteCallbackAsync
): Boolean {
    // Check whether to overwrite a file or not
    val shouldOverwrite = prompt(
        fileSystem,
        outputFilePath,
        overwriteAllNone,
        callback
    )

    // Converts the "should-overwrite" answer to true or false,
    // setting overwrite ALWAYS and NEVER as needed
    return when (shouldOverwrite) {
        ShouldOverwrite.ALWAYS -> {
            overwriteAllNone?.set(OverwriteDefault.ALWAYS)
            true
        }

        ShouldOverwrite.NEVER -> {
            overwriteAllNone?.set(OverwriteDefault.NEVER)
            false
        }

        ShouldOverwrite.YES -> true
        ShouldOverwrite.NO -> false
    }
}

/**
 * Prompts whether to overwrite a file or not using a passed in prompt
 * This is private as it returns an enum value
 * that is not really important outside this system
 */
private suspend fun prompt(
    fileSystem: FileSystem,
    outputFilePath: String,
    overwriteAllNone: OverwriteAllNone?,
    prompt: ShouldOverwriteCallbackAsync
): ShouldOverwrite {
    return shouldOverwriteWithoutPromptYesOrNo(
        fileSystem = fileSystem,
        outputFilePath = outputFilePath,
        overwriteAllNone = overwriteAllNone,
    ) ?: prompt(outputFilePath)
}

/**
 * Checks whether a YES or NO answer can be ascertained without asking the user
 * ALWAYS is converted to YES and NEVER is coerced into NO
 */
private suspend fun shouldOverwriteWithoutPromptYesOrNo(
    fileSystem: FileSystem,
    outputFilePath: String,
    overwriteAllNone: OverwriteAllNone?
): ShouldOverwrite? {
    if (overwriteAllNone?.overwriteAll == true) {
        return ShouldOverwrite.YES
    }
    // Check if file should be overwritten if it exists
    if (!fileSystem.fileExists(outputFilePath)) {
        return ShouldOverwrite.YES
    }
    if (overwriteAllNone?.overwriteNone == true) {
        return ShouldOverwrite.NO
    }
    return null
}


/**
 * Holder for whether to overwrite or skip existing files without asking
 */
@Suppress("MemberVisibilityCanBePrivate")
@JsExport
class OverwriteAllNone(
    overwriteDefault: OverwriteDefault? = null,
    val allowOverwriteAll: Boolean = true,
    val allowOverwriteNone: Boolean = true
) {

    @JsName("constructWithBooleans")
    constructor(
        overwriteAlways: Boolean,
        overwriteNever: Boolean,
        allowOverwriteAll: Boolean = true,
        allowOverwriteNone: Boolean = true
    ): this (
        if (overwriteAlways && overwriteNever) {
            throw IOException("Cannot set overwrite default to both ALWAYS and NEVER")
        } else if (overwriteAlways) {
            OverwriteDefault.ALWAYS
        } else if (overwriteNever) {
            OverwriteDefault.NEVER
        } else {
            null
        },
        allowOverwriteAll,
        allowOverwriteNone
    )

    @JsName("constructFromInt")
    constructor(overwriteDefault: Int): this(OverwriteDefault.fromValue(overwriteDefault))

    private var mOverwriteAllNone: OverwriteDefault? = overwriteDefault

    init {
        if (overwriteAll && overwriteNone) {
            throw IOException("Cannot set overwrite all and none to true on init")
        }
    }

    val overwriteAll: Boolean get() = allowOverwriteAll && mOverwriteAllNone == OverwriteDefault.ALWAYS
    val overwriteNone: Boolean get() = allowOverwriteNone && mOverwriteAllNone == OverwriteDefault.NEVER

    fun set(default: OverwriteDefault) {
        this.mOverwriteAllNone = default
    }
}

/**
 * Constants for use in Javascript
 */
@JsExport
object Overwrite {
    object Answer {
        const val NEVER = -1
        const val NO = 0
        const val YES = 1
        const val ALWAYS = 2
    }

    object Default {
        const val ALWAYS = 2
        const val NEVER = -1
        const val ASK = 0

    }
}

/**
 * Enum for setting the "overwrite" default to ALWAYS or NEVER (and possibly ASK)
 */
@JsExport
enum class OverwriteDefault(val value: Int) {
    ALWAYS(Default.ALWAYS),
    NEVER(Default.NEVER),
    ASK(Default.ASK);

    companion object {
        fun fromValue(value: Int): OverwriteDefault {
            return when (value) {
                ALWAYS.value -> ALWAYS
                NEVER.value -> NEVER
                ASK.value -> ASK
                else -> throw IOException("Failed to understand should overwrite default value")
            }
        }
    }

}

/**
 * Answer enum for a "should-overwrite" prompt
 * Allows for returning more than YES/NO
 */
@JsExport
enum class ShouldOverwrite(val intValue: Int, val should: Boolean) {
    NEVER(Answer.NEVER, false),
    NO(Answer.NO, false),
    YES(Answer.YES, true),
    ALWAYS(Answer.ALWAYS, true);

    companion object {
        fun fromIntVal(intValue: Int): ShouldOverwrite {
            return when (intValue) {
                NEVER.intValue -> NEVER
                NO.intValue -> NO
                YES.intValue -> YES
                ALWAYS.intValue -> ALWAYS
                else -> throw IOException("Failed to understand should overwrite value")
            }
        }
    }
}