@file:Suppress("unused")

package com.bedalton.io.bytes

import com.bedalton.io.bytes.internal.mDecodeBase64
import com.bedalton.io.bytes.internal.mToBase64
import org.khronos.webgl.ArrayBuffer
import org.khronos.webgl.Int8Array
import org.khronos.webgl.Uint8Array

/**
 * Converts a byte array to a base64 encoded string
 */
actual fun ByteArray.toBase64(): String {
    return mToBase64(this)
}

/**
 * Decodes a base64 encoded string to a byte array
 */
actual fun decodeBase64(src:String) : ByteArray {
    return mDecodeBase64(src)
}

/**
 * Converts a byte array into an int8 array for use in javascript
 */
fun ByteArray.toInt8Array() = this.unsafeCast<Uint8Array>()

/**
 * Converts a byte array to an JS array buffer for use in javascript
 */
fun ByteArray.toBuffer() = this.toInt8Array().let { array -> array.buffer.slice(array.byteOffset, array.byteLength + array.byteOffset) }

fun ArrayBuffer.toByteArray(): ByteArray = Int8Array(this).unsafeCast<ByteArray>()

fun ByteArray.toUIntArray(): Uint8Array {
    val out = Uint8Array(this.size)
    out.set(this.toTypedArray())
    return out
}

fun Uint8Array.toByteArray(): ByteArray {
    return this.buffer.toByteArray()
}