package com.bedalton.vfs

import com.bedalton.common.exceptions.asThrowable
import com.bedalton.common.exceptions.rethrowCancellationException
import com.bedalton.vfs.internal.resolveResourcePath
import kotlinx.coroutines.GlobalScope
import kotlinx.coroutines.asPromise
import kotlinx.coroutines.async
import kotlin.js.Promise

@JsExport
actual open class LocalVfs : VFS {

    internal actual fun getFS(): FileSystem {
        return internalFileSystem
    }

    override fun fileExists(filePath: String): Promise<Boolean> {
        return GlobalScope.async {
            val actualPath = resolveResourcePath(filePath)
                ?: filePath
            internalFileSystem.fileExists(actualPath)
        }.asPromise()
    }

    override fun isDirectory(fileName: String): Promise<Boolean?> {
        return GlobalScope.async {
            internalFileSystem.isDirectory(fileName)
        }.asPromise()
    }

    override fun listChildren(directoryPath: String, recursive: Boolean): Promise<Array<String>?> {
        return GlobalScope.async {
            internalFileSystem.listAllFiles(directoryPath, recursive)
                .toTypedArray()
        }.asPromise()
    }

    override fun readBytes(filePath: String): Promise<ByteArray?> {
        return GlobalScope.async {
            val actualPath = resolveResourcePath(filePath)
                ?: filePath
            internalFileSystem.read(actualPath)
        }.asPromise()
    }

    override fun writeBytes(filePath: String, bytes: ByteArray): Promise<Boolean> {
        return GlobalScope.async {
            try {
                internalFileSystem.write(filePath, bytes)
                true
            } catch (err: dynamic) {
                val e = asThrowable(err)
                e.rethrowCancellationException()
                false
            }
        }.asPromise()
    }

    override fun makeDirectory(directoryPath: String, recursive: Boolean): Promise<Boolean> {
        return GlobalScope.async {
            internalFileSystem.makeDirectory(directoryPath, recursive)
        }.asPromise()
    }

    override fun deleteFile(filePath: String): Promise<Boolean> {
        return GlobalScope.async {
            internalFileSystem.delete(filePath)
        }.asPromise()
    }

    override fun canDeleteDirectory(filePath: String): Promise<Boolean> {
        return GlobalScope.async {
            internalFileSystem.canDeleteDirectory(filePath)
        }.asPromise()
    }

    override fun deleteDirectory(filePath: String): Promise<Boolean> {
        return GlobalScope.async {
            internalFileSystem.deleteDirectory(filePath)
        }.asPromise()
    }

    override fun canMakeDirectories(): Promise<Boolean> {
        return GlobalScope.async {
            internalFileSystem.canMakeDirectories()
        }.asPromise()
    }

    override fun getAppPath(directoryId: String): Promise<String?> {
        return when (directoryId) {
            AppDirectory.applicationPath -> tauri.path.appDir()
            AppDirectory.cwd -> Promise.resolve(null)
            AppDirectory.data -> tauri.path.dataDir()
            AppDirectory.executableDirectory -> tauri.path.executableDir()
            else -> Promise.resolve(null)
        }
    }

    override fun move(fromPath: String, toPath: String, overwrite: Boolean): Promise<Int> {
        return GlobalScope.async {
            internalFileSystem.moveFile(fromPath, toPath, overwrite)
        }.asPromise()
    }

    override fun makeTempFile(prefix: String, suffix: String?): Promise<String?> {
        return GlobalScope.async {
            com.bedalton.vfs.makeTempFile(prefix, suffix)
        }.asPromise()
    }

    override fun globFiles(pattern: String, path: String?): Promise<Array<String>?> {
        return GlobalScope.async {
            globPathsManual(internalFileSystem, pattern, path).toTypedArray()
        }.asPromise()
    }

    @Deprecated(
        "Source roots are no longer checked. Accept always returns true",
        ReplaceWith(
            "Promise.resolve(true)",
            imports = ["kotlin.js.Promise"]
        )
    )
    override fun accept(path: String): Promise<Boolean> {
        return returnsTruePromise
    }

    companion object {
        private var internalFileSystem: FileSystem = UnscopedFileSystem()


        @Suppress("NON_EXPORTABLE_TYPE")
        fun setInternalFileSystem(internalFileSystem: FileSystem) {
            this.internalFileSystem = internalFileSystem
        }
    }
}