package com.creaturesforge.application.state

import com.bedalton.common.util.PathUtil
import com.bedalton.creatures.common.structs.BreedKey
import com.creaturesforge.application.compile.CompileData
import com.creaturesforge.application.util.getBreedFilesForSlot

internal object StatsUtil {

    fun getStats(state: ForgeState): List<CompileData.AgeGenderStats> {

        val slots = state.spriteFiles
            .orEmpty()
            .mapNotNull {
                BreedKey.fromFileName(PathUtil.getFileNameWithoutExtension(it)!!)
            }
            .distinctBy { it.code!!.lowercase() }
            .toSet()

        val spriteFiles = getBreedFilesForSlot(
            state.eggMode,
            state.spriteFiles,
            "c16",
            state.spriteBreedSlot,
            state.spriteBreedSlot,
        ).orEmpty().map { it.second }

        val spritesByKey = slots.associateWith {
            getPartsInFilesForBreedKey(it, spriteFiles)
        }

        val attsFiles = getBreedFilesForSlot(
            state.eggMode,
            state.attFiles,
            "att",
            state.attBreedSlot,
            state.attBreedSlot,
        ).orEmpty().map { it.second }

        val attsByKey = slots.associateWith {
            getPartsInFilesForBreedKey(it, attsFiles)
        }

        return slots.map {
            val oppositeGender = if (it.gender == 1) 2 else 1
            CompileData.AgeGenderStats(
                gender = it.gender!!,
                age = it.ageGroup!!,
                sprites = spritesByKey[it]!!,
                atts = attsByKey[it]!!,
                shared = if (attsByKey[it]!!.isEmpty()) {
                    attsByKey[it.copyWithGender(oppositeGender)]
                } else {
                    null
                }
            )
        }
    }
}