package com.bedalton.creatures.sprite.parsers

import com.bedalton.common.util.PathUtil
import com.bedalton.creatures.sprite.util.*
import com.bedalton.io.bytes.ByteStreamReader

object ToSpriteFileParser {

    fun parse(
        filenameOrExtension: String,
        reader: ByteStreamReader,
        keepBlack: Boolean = false,
        paletteTransform: PaletteTransform? = null,
        progressChunkSize: Int = 1,
        progressCallback: ((current: Int, total: Int) -> Boolean?)? = null
    ): SpriteFile {

        val extension = if (filenameOrExtension.contains('.')) {
            PathUtil.getExtension(filenameOrExtension) ?: filenameOrExtension
        } else {
            filenameOrExtension
        }.lowercase()

        val type = when (extension) {
            "spr" -> SpriteType.SPR
            "s16" -> SpriteType.S16
            "c16" -> SpriteType.C16
            "blk" -> SpriteType.BLK
            "photoalbum", "photo album" -> SpriteType.PHOTO_ALBUM
            else -> throw Exception("Unexpected file extension \"${extension.uppercase()}\" for parse sprite frames async")
        }
        return parse(
            type,
            reader,
            keepBlack,
            paletteTransform,
            progressChunkSize,
            progressCallback
        )
    }

    fun parse(
        type: SpriteType,
        reader: ByteStreamReader,
        keepBlack: Boolean = false,
        paletteTransform: PaletteTransform? = null,
        progressChunkSize: Int = 1,
        progressCallback: ((current: Int, total: Int) -> Boolean?)? = null
    ): SpriteFile {
        return when (type) {
            SpriteType.C16 -> {
                C16SpriteFile(
                    bytesBuffer = reader,
                    keepBlack = keepBlack,
                    paletteTransform = paletteTransform,
                    progressChunkSize = 10,
                    progressCallback = null
                )
            }
            SpriteType.SPR -> {
                val palette = paletteTransform?.let {
                    ColorPalette.C1TransparentBlack.transform(
                        transform = it,
                        encoding = ColorEncoding.ENCODING_DEFAULT,
                        keepBlack = keepBlack
                    )
                } ?: ColorPalette.C1TransparentBlack

                SprSpriteFile(
                    bytesBuffer = reader,
                    protoType = false,
                    palette = palette,
                    progressChunkSize = progressChunkSize,
                    progressCallback = progressCallback
                )
            }

            SpriteType.S16 -> {
                S16SpriteFile(
                    reader,
                    keepBlack,
                    paletteTransform,
                    10,
                    null
                )
            }

            SpriteType.BLK -> BlkSpriteFile(
                bytesBuffer = reader,
                progressChunkSize = progressChunkSize,
                progressCallback = progressCallback
            )

            SpriteType.PHOTO_ALBUM -> PhotoAlbumFile(
                reader,
                progressChunkSize,
                progressCallback
            )

            SpriteType.SPR_SET -> throw Exception("Cannot parse SPR sprite sets asynchronously")


        }
    }
}