package com.bedalton.creatures.caos.collectors

import com.bedalton.creatures.caos.antlr.Caos2PrayLexer
import com.bedalton.creatures.caos.antlr.Caos2PrayParser
import com.bedalton.creatures.caos.collectors.internal.Caos2PrayWalker
import org.antlr.v4.kotlinruntime.CharStreams
import org.antlr.v4.kotlinruntime.CommonTokenStream
import org.antlr.v4.kotlinruntime.tree.ParseTreeWalker


fun getCaos2PrayComments(text: String): Array<CaosParserItem.Caos2Comment> {
    val charStream = CharStreams.fromString(text)
    val lexer = Caos2PrayLexer(charStream)
    val tokenStream = CommonTokenStream(lexer)
    val parser = Caos2PrayParser(tokenStream)
    val walker = Caos2PrayWalker()
    ParseTreeWalker.DEFAULT.walk(walker, parser.file())
    return walker.caos2Comments.toTypedArray()
}

