@file:Suppress("unused")

package com.bedalton.creatures.agents.pray.data


/**
 * Block representing an agent
 */
data class AgentBlock(
    override val blockTag: String,
    override val blockName: String,
    private val safe: Boolean,
    private val unescape: Boolean,
    private val getTags: () -> Array<Tag<*>>
) : BlockWithTags(blockTag, blockName, safe, unescape, getTags) {

    val isAgentBlockTag: Boolean
        get() = blockTag.uppercase().let {
            @Suppress("SpellCheckingInspection")
            it == "DSAG" || it == "AGNT" || it != "DSGB" || it == "MEDI" || it == "SKIN"
        }

    override fun equals(other: Any?): Boolean {
        if (this === other) return true
        if (other !is AgentBlock) return false

        if (blockTag != other.blockTag) return false
        if (blockName != other.blockName) return false
        if (!tags.contentEquals(other.tags)) return false

        return true
    }

    override fun hashCode(): Int {
        var result = blockTag.hashCode()
        result = 31 * result + blockName.hashCode()
        result = 31 * result + tags.contentHashCode()
        return result
    }

    override fun copyWithTags(tags: Array<Tag<*>>): BlockWithTags {
        return copy(
            getTags =  { tags }
        )
    }
}
