import com.bedalton.io.bytes.ByteStreamReader

/**
 * Parses Creatures 1 SPR sprite files
 * Based on python code by Shee's Lost Knowledge
 *a
 * @url http://sheeslostknowledge.blogspot.com/2014/11/parsing-creatures-1-spr-files.html
 */
class SprSpriteFile(
    bytesBuffer: ByteStreamReader,
    private val protoType: Boolean = false,
    val palette: ColorPalette,
    progressChunkSize: Int = 1,
    progressCallback: ((current: Int, total: Int) -> Boolean?)? = null,
) : SpriteFile(
    spriteType = SpriteType.SPR,
    keepBlack = palette[0].a != 0,
    paletteTransform = null,
    progressChunkSize = progressChunkSize,
    progressCallback = progressCallback
) {

    private var mBytesBuffer: ByteStreamReader? = bytesBuffer

    override val encoding: ColorEncoding by lazy {
        ColorEncoding.C1
    }

    constructor(
        bytesBuffer: ByteStreamReader,
        keepBlack: Boolean,
        progressChunkSize: Int = 1,
        progressCallback: ((current: Int, total: Int) -> Boolean?)? = null,
    ) : this(
        bytesBuffer,
        protoType = false,
        palette = if (keepBlack) {
            ColorPalette.C1OpaqueBlack
        } else {
            ColorPalette.C1TransparentBlack
        },
        progressChunkSize = progressChunkSize,
        progressCallback = progressCallback
    )

    constructor(
        bytesBuffer: ByteStreamReader,
        keepBlack: Boolean,
        palette: ByteArray,
        progressChunkSize: Int = 1,
        progressCallback: ((current: Int, total: Int) -> Boolean?)? = null,
    ) : this(
        bytesBuffer,
        protoType = false,
        palette = if (keepBlack) {
            loadC1Palette(
                ColorPalette.OPAQUE_BLACK,
                palette
            )
        } else {
            loadC1Palette(
                ColorPalette.TRANSPARENT_BLACK,
                palette
            )
        },
        progressChunkSize = progressChunkSize,
        progressCallback = progressCallback
    )

    constructor(
        bytesBuffer: ByteStreamReader,
        protoType: Boolean,
        keepBlack: Boolean,
        palette: ByteArray,
        progressChunkSize: Int = 1,
        progressCallback: ((current: Int, total: Int) -> Boolean?)? = null,
    ) : this(
        bytesBuffer,
        protoType,
        if (keepBlack) {
            loadC1Palette(ColorPalette.OPAQUE_BLACK, palette)
        } else {
            loadC1Palette(
                ColorPalette.TRANSPARENT_BLACK,
                palette
            )
        },
        progressChunkSize,
        progressCallback
    )

    override val allowAsync: Boolean
        get() = false

    override fun initFramesInternal(): List<SpriteFrameAsync> {
        val bytesBuffer = mBytesBuffer
            ?: throw SpriteParserException("Cannot init SPR frames without an open byte buffer")
        return bytesBuffer.initSprFrames(protoType, palette, keepBlack)
    }

    private var mSize: Int? = null

    override fun sizeInternal(): Int {
        mSize?.let {
            return it
        }
        val bytesBuffer = mBytesBuffer
            ?: throw SpriteParserException("Failed to get sprite frame count. File stream already closed")
        return SpriteParser.imagesCount("file.$extension", bytesBuffer)?.apply {
            mSize = this
        } ?: throw SpriteParserException("Failed to get sprite count from raw bytes")
    }


    /**
     * Close any internal streams, and release references
     */
    override fun closeInternal(): Boolean {
        return mBytesBuffer?.close()?.apply {
            if (this) {
                mBytesBuffer = null
            } else {
                throw IOException("Failed to close Byte stream")
            }
        } ?: true
    }


}

private fun ByteStreamReader.initSprFrames(
    isProtoType: Boolean,
    palette: ColorPalette,
    keepBlack: Boolean,
): List<SpriteFrameAsync> {
    // determine number of bytes in file
    val rawBytesCount = size
    // Create byte buffer

    // Determine the number of images in this file
    val imagesCount = uInt16()


    // Create list of sprite frames
    return (0 until imagesCount).map {
        // Find byte offset in file for image data start
        val offsetForData = if (isProtoType) uInt16().toLong() else uInt32()
        if (offsetForData < 0) {
            throw SpriteParserException("OffsetForData returned negative number. $offsetForData")
        }
        val width = if (isProtoType) uInt8() else uInt16()
        val height = if (isProtoType) uInt8() else uInt16()

        // Determine number of bytes in image
        val byteCount = width * height
        val endByte = (offsetForData + byteCount)

        // Ensure that there are enough bytes in file to read
        if (rawBytesCount < endByte || endByte < 0) {
            throw SpriteParserException("Invalid byte range requested. Total Bytes: ${rawBytesCount}; Offset: $offsetForData, Width:$width, Height:$height; EndByte: $endByte}")
        }

        SpriteFrameAsyncImpl(
            width,
            height,
            palette,
            keepBlack,
        ) {
            // Create actual frame object
            readSprFrame(
                bytesBuffer = this,
                offset = offsetForData,
                width = width,
                height = height,
            )
        }
    }
}

fun readSprFrame(
    bytesBuffer: ByteStreamReader,
    offset: Long,
    width: Int,
    height: Int,
): PixelIndices {
    return bytesBuffer.readAtPosition(offset) {
        readSprFrame(this, width, height)
    }
}

fun readSprFrame(
    bytesBuffer: ByteStreamReader,
    width: Int,
    height: Int,
): PixelIndices {
    val transparent = PixelIndices.TRANSPARENT_BLACK
    val out = IntArray(width * height) { 0 }
    repeat(height) { y ->
        val offsetY = y * width
        repeat(width) { x ->
            out[offsetY + x] = bytesBuffer.uInt8().let {
                if (it == 0) {
                    transparent
                } else {
                    it
                }
            }
        }
    }
    return PixelIndices(width, height, out)
}

