@file:Suppress("unused")

package com.bedalton.io.bytes

import com.bedalton.common.exceptions.IOException
import com.bedalton.common.exceptions.IOReadException
import com.bedalton.io.bytes.internal.rethrowIfCancellationException
import okio.Buffer
import kotlin.contracts.InvocationKind
import kotlin.contracts.contract
import kotlin.js.JsName
import kotlin.jvm.JvmStatic

@Suppress("MemberVisibilityCanBePrivate")
abstract class ByteStreamReader {

    abstract val closed: Boolean

    abstract fun toByteArray(): ByteArray

    abstract val size: Long

    abstract fun get(): Byte

    /**
     * The current position in buffer
     */
    @JsName("getPosition")
    abstract fun position(): Long

    /**
     * Set the read position in buffer
     */
    @JsName("setPosition")
    abstract fun setPosition(newPosition: Long): ByteStreamReader


    /**
     * Create a copy of this reader as is, keeping position
     */
    abstract fun copy(): ByteStreamReader

    /**
     * Whether this byte stream can be re-opened after it is closed
     */
    abstract fun canReopen(): Boolean

    /**
     * Copy this byte stream and re-open it if it is closed
     */
    abstract fun copyAsOpened(): ByteStreamReader?

    /**
     * Locked block now creates a copy of a reader to use, removing the need for mutexes (hopefully)
     */
    inline fun <T> lockedBlock(atPosition: Long? = null, work: ByteStreamReader.() -> T): T {
        contract {
            callsInPlace(work, InvocationKind.EXACTLY_ONCE)
        }
        val reader = copy()
        if (atPosition != null) {
            reader.setPosition(atPosition)
        }
        val out = reader.work()
        reader.close()
        return out
    }


    /**
     * Locked block now creates a copy of a reader to use, removing the need for mutexes (hopefully)
     */
    @Suppress("REDUNDANT_INLINE_SUSPEND_FUNCTION_TYPE")
    suspend inline fun <T> lockedBlockSuspending(atPosition: Long? = null, work: suspend ByteStreamReader.() -> T): T {
        contract {
            callsInPlace(work, InvocationKind.EXACTLY_ONCE)
        }
        val reader = copy()
        if (atPosition != null) {
            reader.setPosition(atPosition)
        }
        val out = reader.work()
        reader.close()
        return out
    }

    abstract fun close(): Boolean


    /**
     * Reads the bytes for a null terminated c-style string
     */
    private fun readCStringBytes(): ByteArray {
        var bytes = ByteArray(STRING_BUFFER_SIZE)
        var position = 0
        while (true) {
            try {
                val byte = get()
                if (byte == NULL_BYTE) {
                    break
                }
                if (bytes.size < position + 1) {
                    bytes += ByteArray(STRING_BUFFER_SIZE)
                }
                bytes[position++] = byte
            } catch (e: Exception) {
                e.rethrowIfCancellationException()
                break
            }
        }

        return bytes.copyOfRange(0, position)
    }

    open fun cString(): String {
        return readCStringBytes().decodeToWindowsCP1252()
    }

    /**
     * Reads the bytes of an SFC style string from a byte stream reader
     */
    private fun readSFCStringBytes(): ByteArray {
        var length = uInt8()
        if (length == 255) {
            length = uInt16()
            if (length == 65535) {
                return bytes(uInt32())
            }
        }
        return bytes(length)
    }

    /**
     * Reads an SFC style string from a byte stream reader
     */
    open fun sfcString(): String {
        return readSFCStringBytes().decodeToWindowsCP1252()
    }

    /**
     * Reads a string of known length from the buffer as a UTF string
     */
    open fun stringUTF8(length: Int): String {
        return bytes(length).decodeToString()
    }

    /**
     * Reads a string of known length from the buffer as a UTF string
     */
    open fun stringUTF8(length: Long): String {
        return bytes(length).decodeToString()
    }

    /**
     * Reads a string of known length from the buffer as a CP1252 encoded string
     */
    open fun string(length: Int): String {
        return bytes(length).decodeToWindowsCP1252()
    }


    /**
     * Reads a string of known length from the buffer as a CP1252 encoded string
     */
    open fun string(length: Long): String {
        return bytes(length).decodeToWindowsCP1252()
    }


    /**
     * Seek to position and begin a read operation
     * Returns to previous position when block is finished
     */
    inline fun <T> readAtPosition(position: Int, work: ByteStreamReader.() -> T): T {
        return lockedBlock(position.toLong()) {
            work()
        }
    }

    /**
     * Seek to position and begin a read operation
     * Returns to previous position when block is finished
     */
    inline fun <T> readAtPosition(position: Long, work: ByteStreamReader.() -> T): T {
        return lockedBlock(position) {
            work()
        }
    }

    /**
     * Seek to position and run a read operation returning an object or value
     * Returns to previous position after the read block ends
     */
    @Deprecated(
        "Use readAtPosition() which now always returns value",
        replaceWith = ReplaceWith("readAtPosition(position, work)")
    )
    inline fun <T> readAtPositionReturning(position: Int, work: ByteStreamReader.() -> T): T {
        return readAtPosition(position.toLong(), work)
    }


    /**
     * Seek to position and run a read operation returning an object or value
     * Returns to previous position after the read block ends
     */
    @Deprecated(
        "Use readAtPosition() which now always returns value",
        replaceWith = ReplaceWith("readAtPosition(position, work)")
    )
    inline fun <T> readAtPositionReturning(position: Long, work: ByteStreamReader.() -> T): T {
        return readAtPosition(position, work)
    }

    /**
     * Run a read operation at the current position without returning a value
     */
    inline fun <T> readAtCurrentPosition(work: ByteStreamReader.() -> T): T {
        return lockedBlock {
            work()
        }
    }


    /**
     * Run a read operation at the current position without returning a value
     */
    @Suppress("REDUNDANT_INLINE_SUSPEND_FUNCTION_TYPE")
    suspend inline fun <T> readAtCurrentPositionSuspending(work: suspend ByteStreamReader.() -> T): T {
        return lockedBlock {
            work()
        }
    }

    /**
     * Run a read operation at the current position returning an object or value
     */
    @Deprecated(
        "Use readAtCurrentPosition() which now always returns value",
        replaceWith = ReplaceWith("readAtCurrentPosition(work)")
    )
    inline fun <T> readAtCurrentPositionReturning(work: ByteStreamReader.() -> T): T {
        return lockedBlock {
            work()
        }
    }


    /**
     * Create a new reader with a byte range in this reader
     */
    open fun copyOfRange(start: Int, end: Int): ByteStreamReader {
        return copyOfRange(start.toLong(), end.toLong())
    }

    /**
     * Create a new reader with a byte range in this reader
     */
    abstract fun copyOfRange(start: Long, end: Long): ByteStreamReader

    /**
     * Return a range of bytes in this reader
     */
    open fun copyOfBytes(start: Int, end: Int): ByteArray {
        return copyOfBytes(start.toLong(), end.toLong())
    }

    /**
     * Return a range of bytes in this reader
     */
    abstract fun copyOfBytes(start: Long, end: Long): ByteArray


    /**
     * Reads the next unsigned byte as an int
     */
    open fun peakUInt8(): Int? {
        return try {
            uInt8().apply {
                offset(-1)
            }
        } catch (e: Exception) {
            e.rethrowIfCancellationException()
            return null
        }
    }

    /**
     * Reads the next unsigned byte as an int
     */
    open fun peakUByte(): UByte? {
        return try {
            uByte().apply {
                offset(-1)
            }
        } catch (e: Exception) {
            e.rethrowIfCancellationException()
            return null
        }
    }

    /**
     * Reads the next unsigned byte as an int
     */
    open fun peakUInt16(): Int? {
        return try {
            uInt16().apply {
                offset(-2)
            }
        } catch (e: Exception) {
            e.rethrowIfCancellationException()
            return null
        }
    }


    /**
     * Reads the next unsigned byte as an int
     */
    open fun peakUShort(): UShort? {
        return try {
            uShort().apply {
                offset(-2)
            }
        } catch (e: Exception) {
            e.rethrowIfCancellationException()
            return null
        }
    }


    /**
     * Reads the next unsigned byte as an int
     */
    open fun peakUInt16(bytesForward: Int = 0): Int? {
        if (bytesForward < 0) {
            throw IOException("Cannot peak at previous bytes")
        }
        return try {
            if (bytesForward > 0) {
                skip(bytesForward)
            }
            uInt16().apply {
                offset(-(bytesForward + 2))
            }
        } catch (e: Exception) {
            e.rethrowIfCancellationException()
            return null
        }
    }


    /**
     * Reads the next unsigned byte as an int
     */
    open fun peakUShort(bytesForward: Int = 0): UShort? {
        if (bytesForward < 0) {
            throw IOException("Cannot peak at previous bytes")
        }
        return try {
            if (bytesForward > 0) {
                skip(bytesForward)
            }
            uShort().apply {
                offset(-(bytesForward + 2))
            }
        } catch (e: Exception) {
            e.rethrowIfCancellationException()
            return null
        }
    }

    /**
     * Peaks at the UInt8 at an offset from current position
     */
    open fun peakUInt8(steps: Int = 0): Int? {
        if (steps < 0) {
            throw IOException("Peak cannot have a negative offset")
        }
        val position = position()
        if (position() + steps > size) {
            return null
        }
        return try {
            if (steps != 0) {
                skip(steps)
            }
            uInt8().apply {
                offset(-(steps + 1))
            }
        } catch (e: Exception) {
            e.rethrowIfCancellationException()
            setPosition(position)
            return null
        }
    }

    open fun peakUByte(steps: Int = 0): UByte? {
        if (steps < 0) {
            throw IOException("Peak cannot have a negative offset")
        }
        val position = position()
        if (position() + steps > size) {
            return null
        }
        return try {
            if (steps != 0) {
                skip(steps)
            }
            uByte().apply {
                offset(-(steps + 1))
            }
        } catch (e: Exception) {
            e.rethrowIfCancellationException()
            setPosition(position)
            return null
        }
    }

    /**
     * Peaks at the UInt8 at an offset from current position
     */
    open fun peakToken(steps: Int = 0): Int? {
        if (steps < 0) {
            throw IOException("Peak cannot have a negative offset")
        }
        val position = position()
        if (position() + steps + 3 >= size) {
            return null
        }

        return try {
            if (steps != 0) {
                skip(steps)
            }
            uInt8() shl 24 or (uInt8() shl 16) or (uInt8() shl 8) or uInt8()
        } catch (e: Exception) {
            e.rethrowIfCancellationException()
            null
        } finally {
            setPosition(position) // try to force position back to where it was if there is a problem
        }
    }

    open fun char(): Char {
        return uInt8().toChar()
    }

    /**
     * Reads a byte as an unsigned int (0..255)
     */
    open fun uInt8(): Int {
        return byte() and 0xFF
    }



    /**
     * Reads a byte as an unsigned int (0..255)
     */
    open fun uByte(): UByte {
        return (byte() and 0xFF).toUByte()
    }

    /**
     * Reads an unsigned Int16 little endian from the stream
     */
    open fun uInt16(): Int {
        return int(2).toInt() and 0xFFFF
    }

    /**
     * Reads an unsigned Int16 little endian from the stream
     */
    open fun uShort(): UShort {
        return (int(2).toInt() and 0xFFFF).toUShort()
    }


    /**
     * Reads an int16 little endian from the stream
     */
    open fun int16(): Int {
        return int(2).toInt().let {
            if (it < 32767) it else if (it > 32768) -it else -32768
        }
    }

    /**
     * Reads a signed int 32
     */
    open fun int32(): Int {
        return int(4).toInt()
    }


    /**
     * Reads a signed int 32
     */
    open fun uInt(): UInt {
        return (int(4) and 0xffffffffL).toUInt()
    }

    /**
     * Reads an unsigned Int32 little endian from the stream
     */
    open fun uInt32(): Long {
        return int(4) and 0xffffffffL
    }

    /**
     * Reads an unsigned Int32 little endian from the stream
     */
    open fun uLong(): ULong {
        return (int(4) and 0xffffffffL).toULong()
    }

    open fun float(): Float {
        return float(this)
    }

    open fun double(): Double {
        return double(this)
    }

    /**
     * Reads an unsigned Int32 little endian from the stream
     */
    open fun uInt32AsInt(): Int {
        val int = (int(4) and 0xffffffffL)
        if (int > Int.MAX_VALUE) {
            throw IOReadException("UInt is to large to convert to signed int32. Value: $int")
        }
        return int.toInt()
    }

    /**
     * Reads an Int64 little endian from the stream
     */
    open fun int64(): Long {
        return int(8)
    }

    /**
     * Reads a variable number of bytes as an unsigned int (actually a long)
     */
    private fun uInt(bytes: Int): Long {
        return int(bytes) and mask(bytes)
    }

    private fun mask(bytes: Int): Long {
        return when (bytes) {
            1 -> 0xFF.toLong()
            2 -> 0xFFFF.toLong()
            4 -> 0xFFFFFFFF
            else -> {
                var mask = 0L
                for (i in 0 until bytes) {
                    mask = mask or (255 shl (8 * i)).toLong()
                }
                mask
            }
        }
    }

    /**
     * Reads an arbitrary number of bytes as a signed long
     */
    private fun int(bytes: Int): Long {
        var result = 0L
        repeat(bytes) { i ->
            result = result or (uInt8() shl (8 * i)).toLong()
        }
        return result
    }

    /**
     * Reads a byte as a boolean where true if non-zero
     */
    open fun uInt8Bool(): Boolean {
        return uInt8() != 0
    }

    /**
     * Reads a short as a boolean, where true if non-zero
     */
    open fun uInt16Bool(): Boolean {
        return uInt16() != 0
    }

    /**
     * Reads an int as a boolean where true if non-zero
     */
    open fun uInt32Bool(): Boolean {
        return uInt32() != 0L
    }


    /**
     * Reads a UInt16 in big endian format
     */
    open fun uInt16BE(): Int {
        return intBE(2).toInt()
    }

    /**
     * Reads an Int16 in big endian format
     */
    open fun int16BE(): Int {
        return intBE(2).toInt().let {
            if (it < 32767) it else if (it > 32768) -it else -32768
        }
    }

    /**
     * Reads an Int32 in big endian format
     */
    open fun int32BE(): Int {
        return intBE(4).toInt()
    }

    /**
     * Reads a UInt32 in big endian format
     */
    open fun uInt32BE(): Long {
        return intBE(4) and 0xffffffffL
    }

    /**
     * Reads an Int64 in big endian format
     */
    open fun int64BE(): Long {
        return intBE(8)
    }

    /**
     * Reads an int of variable bytes as an unsigned long
     */
    private fun uIntBE(bytes: Int): Long {
        return intBE(bytes) and mask(bytes)
    }


    /**
     * Reads an arbitrary number of bytes as a signed long
     */
    private fun intBE(bytes: Int): Long {
        var result = 0L
        bytes(bytes).apply {
            reverse()
            this.forEachIndexed { i, byte ->
                result = result or (byte.toInt() shl 8 * i).toLong()
            }
        }
        return result
    }


    /**
     * Reads a single byte from the stream
     */
    open fun byte(): Int {
        return get().toInt()
    }


    open fun tokenInt(): Int {
        return (uInt8() shl 24) or
                (uInt8() shl 16) or
                (uInt8()  shl 8) or
                uInt8()
    }

    open fun tokenString(): String {
        return "" + char() + char() + char() + char()
    }

    /**
     * Skip a given number of bytes
     */
    open fun skip(length: Int): ByteStreamReader {
        offset(length)
        return this
    }

    /**
     * Move cursor in byte array forward by a number of bytes
     */
    open fun offset(offset: Int): ByteStreamReader {
        setPosition(position() + offset)
        return this
    }

    /**
     * Move cursor in byte array forward by a number of bytes
     */
    open fun offset(offset: Long): ByteStreamReader {
        setPosition(position() + offset.toInt())
        return this
    }

    /**
     * Checks if the stream still has the required number of bytes
     */
    open fun hasBytes(size: Int): Boolean {
        return hasBytes(size.toLong())
    }


    /**
     * Checks that a stream has the required number of bytes
     */
    open fun hasBytes(size: Long): Boolean {
        return size + position() <= this.size
    }

    /**
     * Gets the last byte index in a byte stream reader stream
     */
    open val lastIndex: Long get() = size - 1


    /**
     * Returns a number of bytes from the current position
     */
    open fun bytes(length: Int): ByteArray {
        if (!hasBytes(length)) {
            throw NotEnoughBytesException("Not enough bytes. Expected $length; Found: ${size - position()} at ${position()}")
        }
        return if (length > 8) {
            val position = position()
            copyOfBytes(position, position + length).apply {
                setPosition(position + length)
            }
        } else {
            (0..<length).map {
                get()
            }.toByteArray()
        }
    }

    /**
     * Returns a number of bytes from the current position
     */
    open fun bytes(length: Long): ByteArray {
        if (!hasBytes(length)) {
            throw NotEnoughBytesException("Not enough bytes. Expected $length; Found: ${size - position()} at ${position()}")
        }
        var bytesLeft = length
        val out = Buffer()
        while (length > Int.MAX_VALUE) {
            out.write(bytes(Int.MAX_VALUE))
            bytesLeft -= Int.MAX_VALUE
        }
        if (bytesLeft > 0) {
            out.write(bytes(bytesLeft.toInt()))
        }
        return out.readByteArray()
    }

    companion object {


        private const val STRING_BUFFER_SIZE = 20

        private const val NULL_BYTE: Byte = 0.toByte()

        @JvmStatic
        fun create(bytes: ByteArray): ByteStreamReader {
            return MemoryByteStreamReader(bytes)
        }


        private fun Char.toByteFromCode(): Byte {
            return code.toByte()
        }

        inline fun <T> read(bytes: ByteArray, work: ByteStreamReader.() -> T): T {
            val reader = MemoryByteStreamReader(bytes)
            return reader
                .readAtCurrentPosition(work)
        }

        @Suppress("REDUNDANT_INLINE_SUSPEND_FUNCTION_TYPE")
        suspend inline fun <T> readSuspending(bytes: ByteArray, work: suspend ByteStreamReader.() -> T): T {
            val reader = MemoryByteStreamReader(bytes)
            return reader
                .readAtCurrentPositionSuspending(work)
        }
    }
}


fun createDefaultByteStreamReader(bytes: ByteArray): ByteStreamReader {
    return ByteStreamReader.create(bytes)
}


/**
 * Converts a byte to an unsigned int8
 */
private fun byteToUInt(b: Byte): Int {
    return if (b < 0) b + 256 else b.toInt()
}