package com.bedalton.common.ast.hints

import com.bedalton.common.ast.structs.InlayHint
import com.bedalton.common.ast.structs.Position
import com.bedalton.common.ast.structs.TextEdit
import kotlinx.serialization.Serializable

@Serializable
data class InlayHintImpl(
    override val position: Position,
    override val label: String,
    override val kind: Int? = InlayKind.Type,
    override val textEdits: Array<TextEdit>? = null,
    override val tooltip: String? = null,
    override val paddingLeft: Boolean? = null,
    override val paddingRight: Boolean? = null,
) : InlayHint {
    override fun equals(other: Any?): Boolean {
        if (this === other) return true
        if (other !is InlayHintImpl) return false

        if (position != other.position) return false
        if (label != other.label) return false
        if (kind != other.kind) return false
        if (textEdits != null) {
            if (other.textEdits == null) return false
            if (!textEdits.contentEquals(other.textEdits)) return false
        } else if (other.textEdits != null) return false
        if (tooltip != other.tooltip) return false
        if (paddingLeft != other.paddingLeft) return false
        if (paddingRight != other.paddingRight) return false
//        if (data != other.data) return false

        return true
    }

    override fun hashCode(): Int {
        var result = position.hashCode()
        result = 31 * result + label.hashCode()
        result = 31 * result + (kind ?: 0)
        result = 31 * result + (textEdits?.contentHashCode() ?: 0)
        result = 31 * result + (tooltip?.hashCode() ?: 0)
        result = 31 * result + (paddingLeft?.hashCode() ?: 0)
        result = 31 * result + (paddingRight?.hashCode() ?: 0)
//        result = 31 * result + data.hashCode()
        return result
    }
}