/**
 * Parses and writes a PRAY file as described in the input object
 * @return String com.bedalton.creatures.pray.path to the written .agents file
 */
@Suppress("unused")
suspend fun compilePrayAndWrite(
    coroutineScope: CoroutineScope,
    fs: FileSystem,
    input: IPrayCompilerTask,
    subFoldersOnly: Boolean
): String {
    if (input.logProgress) {
        Log.setMode(LOG_PROGRESS, true)
    }
    val outputFolder = input.outputDirectory
    if (!fs.fileExists(outputFolder)) {
        fs.makeDirectory(outputFolder, true)
    }
    if (!fs.isDirectory(outputFolder)) {
        throw PrayInputException("Output folder '$outputFolder' is not a directory")
    }
    val inputFile = input.inputFile
    if (!PathUtil.isAbsolute(inputFile)) {
        throw PrayInputException("Input file path must be absolute")
    }
    if (!fs.fileExists(inputFile)) {
        throw PrayInputException("Input file does not exist")
    }
    if (fs.isDirectory(inputFile)) {
        throw PrayInputException("Input file is actually a directory; Path: $inputFile")
    }

    if (input.printStats) {
        val prayData = try {
            parseCaosScript(coroutineScope, fs, input.inputFile, input, subFoldersOnly).prayData
        } catch (e: Exception) {
            e.rethrowIfCancellationException()
            Log.e { "Failed to get stats. Parse failed with exception: ${e.message}" }
            throw Exception("Failed to get stats. Parse failed with exception: ${e.message}", e)
        }
        printStats(prayData)
        return ""
    }
    val (outputFile, bytes) = compilePrayFileToBytes(coroutineScope, fs, input, subFoldersOnly)
    if (outputFile == null) {
        throw PrayException("No output file specified")
    }
    val extension = PathUtil.getExtension(outputFile)?.lowercase()
    val filenameWithExtensions = if (extension == "agent" || extension == "agents") {
        outputFile
    } else {
        "$outputFile.agents"
    }

    Log.iWith(LOG_PROGRESS, replace = true) { "Writing bytes..." }
    val writePath = PathUtil.combine(outputFolder, filenameWithExtensions)
    fs.write(writePath, bytes, append = false)
    val sizeString = formatByteSize(bytes.size)
    Log.iIf(LOG_DEBUG) { "Agent output file size: $sizeString" }
    Log.iWith(LOG_PROGRESS, replace = true) { "Wrote bytes to $filenameWithExtensions" }

    return writePath
}

