/**
 * Compiles
 */
suspend fun compilePrayFileToBytes(
    coroutineScope: CoroutineScope,
    fs: FileSystem,
    input: IPrayCompilerTask,
    subFoldersOnly: Boolean
): CompileResult {
    if (input.logProgress) {
        Log.setMode(LOG_PROGRESS, true)
    }
    if (!PathUtil.isAbsolute(input.outputDirectory)) {
        throw PrayInputException("Output directory must be absolute in compilePrayFileToBytes")
    }
    if (!PathUtil.isAbsolute(input.inputFile)) {
        throw PrayInputException("Input directory must be absolute in compilePrayFileToBytes")
    }
    val outputFolder = input.outputDirectory
    if (!fs.fileExists(outputFolder) && !fs.makeDirectory(outputFolder, true)) {
        throw PrayInputException("Output folder '$outputFolder' does not exist")
    }
    if (!fs.isDirectory(outputFolder)) {
        throw PrayInputException("Output folder '$outputFolder' is not a directory")
    }
    val parseResult = parseCaosScript(coroutineScope, fs, input.inputFile, input, subFoldersOnly)
    val inputFileDirectory = PathUtil.combine(input.inputFile, "..")
    val relativeFs = RelativeFileSystem(fs, inputFileDirectory, subFoldersOnly = subFoldersOnly)
    val compressionLevel = input.compressionLevel?.let {
        if (it == -1) {
            null
        } else {
            it
        }
    }
    if (compressionLevel != null && compressionLevel !in 0..9) {
        throw IOException("Invalid compression level found expected NUll or 0(noCompression)..9(Best Compression)")
    }
    val compiled =  PrayCompiler.compile(
        coroutineScope = coroutineScope,
        fs = relativeFs,
        prayData = parseResult.prayData,
        compress = input.compressionLevel,
        validate = input.validate,
    )
    Log.iWith(LOG_PROGRESS, replace = true) { "Got compiled bytes" }
    return CompileResult(
        outputFile = parseResult.outputFileName,
        bytes = compiled
    )
}

