/**
 * Compiles
 */
suspend fun compilePrayFileToBytes(
    coroutineScope: CoroutineScope,
    fs: FileSystem,
    input: IPrayCompilerTask,
    subFoldersOnly: Boolean,
    prayData: CompilerPrayData
): ByteArray {
    if (input.logProgress) {
        Log.setMode(LOG_PROGRESS, true)
    }
    val inputFileDirectory = if (input.inputFile.isNotNullOrBlank()) PathUtil.combine(input.inputFile, "..") else ""
    val relativeFs = RelativeFileSystem(fs, inputFileDirectory, subFoldersOnly = subFoldersOnly)
    val compressionLevel = input.compressionLevel?.let {
        if (it == -1) {
            null
        } else {
            it
        }
    }
    if (compressionLevel != null && compressionLevel !in 0..9) {
        throw IOException("Invalid compression level found expected NUll or 0(noCompression)..9(Best Compression)")
    }
    val bytes = PrayCompiler.compile(coroutineScope, relativeFs, prayData, input.compressionLevel, input.validate)

    if (!coroutineScope.isActive) {
        coroutineScope.ensureActive()
        throw CancellationException("Compilation was cancelled")
    }
    return bytes
}

/**
 * Parses the file into a Pray Parse result
 */
private suspend fun parseCaosScript(
    coroutineScope: CoroutineScope,
    fs: FileSystem,
    inputFile: String,
    opts: PrayCompileOptions,
    subFoldersOnly: Boolean
): Caos2PrayResult {
    Log.iWith(LOG_PROGRESS, replace = true) { "Parsing pray file..." }
    if (!PathUtil.isAbsolute(inputFile)) {
        throw PathNotAbsoluteException("Input file path must be absolute")
    }
    val inputDirectory = PathUtil.combine(inputFile, "..")
    val relativeFs = RelativeFileSystem(fs, inputDirectory, subFoldersOnly)
    val fileName = PathUtil.getLastPathComponent(inputFile)
        ?: throw IOException("Failed to get pray file name")
    return try {
        getInputData(coroutineScope, relativeFs, fileName, opts).also {
            Log.iWith(LOG_PROGRESS, replace = true) { "Parsed pray file" }
        }
    } catch (e: Exception) {
        e.rethrowIfCancellationException()
        Log.e { e.message ?: "Failed to load pray file at <${relativeFs.path(fileName)}>" }
        throw e
    }
}
