@file:Suppress("unused")

package com.bedalton.creatures.caos.utils

import com.bedalton.creatures.caos.collectors.ParseResult
import com.bedalton.creatures.caos.collectors.CaosParserItem

private val caos2FileRegex = "(pray|cob)\\s*-?(file)".toRegex(RegexOption.IGNORE_CASE)

val ParseResult.isCaos2: Boolean get() {
    return caos2Comments.any {
        caos2FileRegex.matches(it.command ?: it.tag ?: "")
    }
}

val Iterable<CaosParserItem.Caos2Comment>.isCaos2: Boolean get() {
    return any {
        caos2FileRegex.matches(it.command ?: it.tag ?: "")
    }
}

val Array<CaosParserItem.Caos2Comment>.isCaos2: Boolean get() {
    return any {
        caos2FileRegex.matches(it.command ?: it.tag ?: "")
    }
}