// Buffers
private val floatsBuffer = Float32Array(1)
private val doubleBuffer = Float64Array(1)


/**
 * Writes a float to this ByteStreamWriter
 */
internal actual fun writeFloat(writer: ByteStreamWriter, float: Float): ByteStreamWriter = floatsBuffer.let {
    it[0] = float
    val buffer = Uint8Array(it.buffer)
    val bytes = (0..3).map { i ->
        buffer[i]
    }.toByteArray()
    console.log("FloatBytesToWrite: [" + bytes.joinToString(",") + "]")
    writer.write(bytes)
}


/**
 * Writes a double to this ByteStreamWriter
 */
internal actual fun writeDouble(writer: ByteStreamWriter, double: Double): ByteStreamWriter = doubleBuffer.let {
    it[0] = double
    val buffer = Uint8Array(it.buffer)
    val bytes = (0..7).map { i ->
        buffer[i]
    }.toByteArray()
    console.log("DoubleBytesToWrite: [" + bytes.joinToString(",") + "]")
    writer.write(bytes)
}


