package com.bedalton.creatures.sprite.parsers

import com.bedalton.creatures.sprite.util.ColorPalette
import com.bedalton.creatures.sprite.util.SpriteType
import com.bedalton.common.structs.Pointer
import com.bedalton.common.util.*
import com.bedalton.creatures.sprite.util.ColorEncoding
import com.bedalton.creatures.sprite.util.orThrow
import com.bedalton.io.bytes.*
import com.bedalton.log.Log
import com.bedalton.log.eIf
import com.bedalton.log.iIf
import korlibs.image.color.RGBA
import korlibs.image.format.PNG


internal const val MAX_SPRITE_WIDTH = 1600
const val SPR_SHORT_DEBUG_LOGGING = "SPR.SHORT.LOGGING"
const val SPR_SHORT_DEBUG_LOGGING_VERBOSE = "SPR.SHORT.LOGGING.VERBOSE"


/**
 * Decompiler for C1 Applet SPR files
 */
object SprSetDecompiler {


    /**
     * Decompiles a multi-sprite SPR file keeping black(aka transparent) pixels if desired
     */
    fun decompileSets(
        reader: ByteStreamReader,
        keepBlack: Boolean,
        progressChunkSize: Int? = null,
        progressCallback: ((pass: Int, current: Int, total: Int) -> Boolean?)? = null,
    ): List<SpriteFile>? {
        val palette = if (keepBlack) {
            ColorPalette.C1OpaqueBlack
        } else {
            ColorPalette.C1TransparentBlack
        }

        return try {
            decompileSets(reader, palette, progressChunkSize, progressCallback)
        } catch (e: Exception) {
            Log.eIf(SPR_SHORT_DEBUG_LOGGING_VERBOSE) {
                "Failed to decompile sprite set. ${e.className}: ${e.message ?: "Unknown error occurred"}\n${e.stackTraceToString()}"
            }
            null
        }
    }


    /**
     * Decompiles a multi-sprite SPR file given a black RGBA object
     * @param reader A byte stream reader of the entire file
     */
    private fun decompileSets(
        reader: ByteStreamReader,
        palette: ColorPalette,
        progressChunkSize: Int?,
        progressCallback: ((pass: Int, current: Int, total: Int) -> Boolean?)?,
    ): List<SpriteFile>? {
        val size = reader.size
        Log.iIf(SPR_SHORT_DEBUG_LOGGING_VERBOSE) {
            "Reading applet format file; Bytes: $size"
        }

        // Try to read file as a set of short format sprite files.
        // If that fails try and read as a single sprite short format SPR
        return try {
            reader.copy().readAtPosition(0) {
                // Read the number of sprites in this set
                val spriteSetCount = uInt16()

                // Skip an unknown uInt32
                skip(4)

                Log.iIf(SPR_SHORT_DEBUG_LOGGING_VERBOSE) {
                    "Trying to read SPR multi-sprite file. Sets: $spriteSetCount."
                }
                val referenceCounter = Pointer(spriteSetCount)
                // Try to read SPR short multi-file
                // These images have a secondary "true-width" int and are upside down.
                // Width(full)/Height is an uInt32
                (0 until spriteSetCount).map { spriteFileIndex ->
                    readSprShort(
                        setIndex = spriteFileIndex,
                        reader = this,
                        palette = palette,
                        hasTrueWidth = true,
                        flipped = true,
                        readSizeInt = uInt32SizeReader,
                        progressChunkSize = progressChunkSize ?: 1,
                        referenceCounter = referenceCounter
                    ) { current: Int, total: Int ->
                        progressCallback?.invoke(spriteFileIndex, current, total)
                    }
                }.apply {
                    Log.iIf(SPR_SHORT_DEBUG_LOGGING) {
                        "Read SPR multi-sprite file in primary format"
                    }
                }
            }
        } catch (e: Exception) {

            try {
                reader.copy().readAtPosition(6) {// After size and skip(4) done previously
                    val callback = if (progressCallback != null) {
                        { current: Int, total: Int ->
                            progressCallback(1, current, total)
                        }
                    } else {
                        null
                    }
                    readSprShort(
                        setIndex = 0,
                        reader = this,
                        palette = palette,
                        hasTrueWidth = true,
                        flipped = true,
                        readSizeInt = uInt32SizeReader,
                        progressChunkSize = progressChunkSize ?: 1,
                        referenceCounter = null,
                        callback
                    ).toListOf().apply {
                        Log.iIf(SPR_SHORT_DEBUG_LOGGING) {
                            "Read single sprite SPR file in primary multi-sprite format at index 6"
                        }
                    }
                }
            } catch (e2: Exception) {
                try {
                    reader.copy().readAtPosition(0) {
                        // Read fallback SPR short single file
                        // These images have no trueSize int, and are not upside down.
                        // Width/Heights are uInt16
                        val callback = if (progressCallback != null) {
                            { current: Int, total: Int ->
                                progressCallback(1, current, total)
                            }
                        } else {
                            null
                        }
                        readSprShort(
                            setIndex = 0,
                            reader = this,
                            palette = palette,
                            hasTrueWidth = true,
                            flipped = true,
                            readSizeInt = uInt32SizeReader,
                            progressChunkSize = progressChunkSize ?: 1,
                            referenceCounter = null,
                            callback
                        ).toListOf().apply {
                            Log.iIf(SPR_SHORT_DEBUG_LOGGING) {
                                "Read single sprite SPR file in primary multi-sprite format at index 0"
                            }
                        }
                    }
                } catch (e3: Exception) {
                    Log.iIf(SPR_SHORT_DEBUG_LOGGING_VERBOSE) {
                        "Trying to read SPR short single sprite file."
                    }
                    try {
                        reader.copy().readAtPosition(0) {
                            // Read fallback SPR short single file
                            // These images have no trueSize int, and are not upside down.
                            // Width/Heights are uInt16
                            val callback = if (progressCallback != null) {
                                { current: Int, total: Int ->
                                    progressCallback(1, current, total)
                                }
                            } else {
                                null
                            }
                            readSprShort(
                                setIndex = 0,
                                reader = this,
                                palette = palette,
                                hasTrueWidth = false,
                                flipped = false,
                                readSizeInt = uInt16SizeReader,
                                progressChunkSize = progressChunkSize ?: 1,
                                referenceCounter = null,
                                callback
                            ).toListOf().apply {
                                Log.iIf(SPR_SHORT_DEBUG_LOGGING) {
                                    "Read single sprite short SPR file in secondary format"
                                }
                            }
                        }
                    } catch (e4: Exception) {
                        Log.iIf(SPR_SHORT_DEBUG_LOGGING_VERBOSE) {
                            "Failed to read applet SPR multi-sprite file. ${e.className}: ${e.message ?: "An unknown exception occurred"}\n${e.printStackTrace()}"
                        }

                        Log.iIf(SPR_SHORT_DEBUG_LOGGING_VERBOSE) {
                            "Failed to read applet SPR single-sprite file in multi-sprite format. ${e2.className}: ${e2.message ?: "An unknown exception occurred"}\n${e2.printStackTrace()}"
                        }

                        Log.iIf(SPR_SHORT_DEBUG_LOGGING_VERBOSE) {
                            "Failed to read applet SPR single-sprite file. ${e3.className}: ${e3.message ?: "An unknown exception occurred"}\n${e3.printStackTrace()}"
                        }

                        Log.iIf(SPR_SHORT_DEBUG_LOGGING_VERBOSE) {
                            "Failed to read applet SPR single-sprite file in multi-sprite format. ${e4.className}: ${e4.message ?: "An unknown exception occurred"}\n${e4.printStackTrace()}"
                        }
                        throw e
                    }
                }
            }
        }
    }


    private fun readSprShort(
        setIndex: Int,
        reader: ByteStreamReader,
        palette: ColorPalette,
        hasTrueWidth: Boolean,
        flipped: Boolean,
        readSizeInt: Sizer,
        progressChunkSize: Int = 1,
        referenceCounter: Pointer<Int>? = null,
        progressCallback: ((current: Int, total: Int) -> Boolean?)?,
    ): SpriteFile {
        val imageCount = reader.uInt16()
        if (imageCount !in 0..1000) {
            throw SpriteParserException(
                "Image count is too great for Sprite[$setIndex] as multi-sprite short SPR primary format. Might be secondary format"
            )
        }
        reader.skip(4)
        var frames: List<SpriteFrameAsync>? = (0 until imageCount).map { index ->
            Log.iIf(SPR_SHORT_DEBUG_LOGGING_VERBOSE) { "Reading at index Sprite[$setIndex].Frame[${index + 1}/$imageCount]" }
            // Read frame data
            val (frame, dataLength) = readSprFragmentRaw(
                setIndex,
                index,
                reader = reader,
                palette = palette,
                hasTrueWidth = hasTrueWidth,
                flipped = flipped,
                readSizeInt = readSizeInt
            )

            if ((reader.position() + dataLength) < reader.size) {
                // Skip data frames as this will be decompiled later
                Log.iIf(SPR_SHORT_DEBUG_LOGGING_VERBOSE) {
                    "Skipping $dataLength bytes for spr fragment Sprite[$setIndex].Frame[${index + 1}/$imageCount]"
                }
                reader.skip(dataLength)
            }

            // There are some sprite images that have trailing bytes
            // Not sure what these are
//            skipAfter(reader, index, imageCount)
            Log.iIf(SPR_SHORT_DEBUG_LOGGING_VERBOSE) {
                "Read image Sprite[$setIndex].Frame[${index + 1}/$imageCount]"
            }
            frame
        }
        var tempReader: ByteStreamReader? = reader

        return SimpleSpriteFile(
            frames = frames!!,
            keepBlack = true,
            progressChunkSize = progressChunkSize,
            progressCallback = progressCallback,
        ) close@{
            if (referenceCounter != null) {
                referenceCounter.value--
                if (referenceCounter.value != 0) {
                    return@close true
                }
            }
            frames?.map { it.close() }
            frames = null
            // Close reader function
            // Used for closing the reader not-located inside the SPR file.
            // Should remove reference to reader to allow for GC
            val closed = tempReader?.close() != false
            tempReader = null
            closed
        }
    }
}

private class SimpleSpriteFile(
    private val frames: List<SpriteFrameAsync>,
    keepBlack: Boolean,
    progressChunkSize: Int = 1,
    progressCallback: ((current: Int, total: Int) -> Boolean?)?,
    private var closeStream: (SimpleSpriteFile.() -> Boolean)?,
) : SpriteFile(SpriteType.SPR_SET, keepBlack, null, progressChunkSize, progressCallback) {
    override val allowAsync: Boolean
        get() = false

    override val encoding: ColorEncoding get() = ColorEncoding.C1

    override fun closeInternal(): Boolean {
        val result = closeStream?.invoke(this) != false
        closeStream = null
        return result
    }

    private var mSize: Int = frames.size

    override fun sizeInternal(): Int = mSize


    override fun initFramesInternal(): List<SpriteFrameAsync> {
        return frames
    }

}

/**
 * Reads an SPR frame given the images parameters
 * @param bytesBuffer The buffer to read the image from
 * @param setIndex the current set being read from this multi-sprite file (if any)
 * @param index this frames index in this SPR image set
 * @param offset the offset in the buffer for this image
 * @param trueWidth The actual visible part of the image, this is without forcing width to a multiple of 4
 * @param widthWithBuffer This is the width in bytes, padded to a multiple of 4
 * @param height height of image to read
 * @param flipped whether this image is written upside down and needs to be flipped
 */
private fun readShortSprFrame(
    bytesBuffer: ByteStreamReader,
    setIndex: Int?,
    index: Int?,
    offset: Long,
    trueWidth: Int,
    widthWithBuffer: Int,
    height: Int,
    flipped: Boolean
): PixelIndices {
    return bytesBuffer.readAtPosition(offset) {
        readSprMultiSpriteFrame(setIndex, index, trueWidth, widthWithBuffer, height, flipped)
    }
}

/**
 * A reader to simplify reading width constrained to a certain int size
 */
private typealias Sizer = (ByteStreamReader.() -> Int)

/**
 * Read an unsigned int32 when reading size
 */
private val uInt32SizeReader: Sizer by lazy {
    { uInt32().toInt() }
}

/**
 * Read an unsigned int16 when reading size
 */
private val uInt16SizeReader: Sizer by lazy { { uInt16() } }


/**
 * Attempts to read the longer form of the short SPR format
 * This fragment has two width properties
 * @param reader stream to read image from (already opened and seeked to position)
 * @param keepBlack whether to keep supposed to be transparent pixels (which are written as index 0 black pixels)
 * @param flipped whether this image is written upside down and needs to be flipped
 * @param throws whether to throw an error when parsing fails
 * @param setIndex the set index in the multi-SPR sprite file if any
 * @param frameIndex the index of the frame being decompiled here within the current multi-SPR set
 */
private fun readShortFormSprFragmentWithTrueWidth(
    reader: ByteStreamReader,
    keepBlack: Boolean,
    flipped: Boolean = true,
    throws: Boolean,
    setIndex: Int? = null,
    frameIndex: Int? = null
): ByteArray? {
    return readSprFragment(
        reader,
        keepBlack,
        true,
        flipped,
        sizeIntIsInt32 = true,
        throws,
        setIndex,
        frameIndex
    )
}

/**
 * Attempts to read the shorter form of the short SPR format
 * This fragment has two width properties
 */
fun readShortFormSprFragmentSingleWidth(
    reader: ByteStreamReader,
    keepBlack: Boolean,
    flipped: Boolean = true,
    throws: Boolean,
    setIndex: Int? = null,
    index: Int? = null
): ByteArray? {
    return readSprFragment(
        reader,
        keepBlack,
        hasTrueWidth = false,
        flipped,
        sizeIntIsInt32 = false,
        throws,
        setIndex,
        index
    )
}

/**
 * Reads an SPR fragment using possible switches
 * @param reader A reader with its offset set to the start of the sprite.
 * SPR fragments are read sequentially in their entirety, not like normal
 * SPR files which have all SPR headers first
 */
fun readSprFragment(
    reader: ByteStreamReader,
    keepBlack: Boolean,
    hasTrueWidth: Boolean,
    flipped: Boolean,
    sizeIntIsInt32: Boolean,
    throws: Boolean = false,
    setIndex: Int? = null,
    index: Int? = null
): ByteArray? {
    val palette = if (keepBlack) {
        ColorPalette.C1OpaqueBlack
    } else {
        ColorPalette.C1TransparentBlack
    }
    return try {
        val bitmap = readSprFragmentRaw(
            setIndex,
            index,
            reader,
            palette,
            hasTrueWidth,
            flipped,
            sizeIntIsInt32
        ).image(keepBlack)
        PNG.encode(bitmap)
    } catch (e: Exception) {
        if (throws) {
            throw e
        }
        null
    }
}

/**
 * Tries to read a sprite frame using a given set of parameters
 * SPR short files read images sequentially in full, not headers first like normal SPRs
 * Short files may have both a padded width and a true width
 *
 * @param reader A stream reader set to the start position of this sprite.
 *  SPR short format reads the images sequentially, not headers first
 * @param hasTrueWidth May have a secondary width parameter that shows the true width
 *  when the first parameter is padded to fit multiple of 4
 * @param sizeIntIsInt32 Some SPR short formats read width/height as uInt32's and others as uInt16
 * @throws SpriteParserException
 */
private fun readSprFragmentRaw(
    setIndex: Int?,
    index: Int?,
    reader: ByteStreamReader,
    palette: ColorPalette,
    hasTrueWidth: Boolean,
    flipped: Boolean,
    sizeIntIsInt32: Boolean
): SpriteFrameAsync {

    val readSizeInt = if (sizeIntIsInt32) {
        uInt32SizeReader
    } else {
        uInt16SizeReader
    }
    return readSprFragmentRaw(
        setIndex,
        index,
        reader,
        palette,
        hasTrueWidth,
        flipped,
        readSizeInt
    ).first
}

/**
 * Tries to read a sprite frame using a given set of parameters
 * SPR short files read images sequentially in full, not headers first like normal SPRs
 * Short files may have both a padded width and a true width
 *
 * @param reader A stream reader set to the start position of this sprite.
 *  SPR short format reads the images sequentially, not headers first
 * @param hasTrueWidth May have a secondary width parameter that shows the true width
 *  when the first parameter is padded to fit multiple of 4
 * @param readSizeInt Some SPR short formats read width/height as uInt32's and others as uInt16
 * @throws SpriteParserException
 */
private fun readSprFragmentRaw(
    setIndex: Int?,
    index: Int?,
    reader: ByteStreamReader,
    palette: ColorPalette,
    hasTrueWidth: Boolean,
    flipped: Boolean,
    readSizeInt: Sizer
): Pair<SpriteFrameAsync, Int> {

    val widthWithBuffer = reader.readSizeInt()
    if (widthWithBuffer !in 0..MAX_SPRITE_WIDTH) {
        throw SpriteParserException("Invalid sprite[$index] fragment width <$widthWithBuffer>")
    }

    val height = reader.readSizeInt()
    if (height !in 0..MAX_SPRITE_WIDTH) {
        throw SpriteParserException("Invalid sprite[$index] height <$height>")
    }

    val trueWidth = if (hasTrueWidth) {
        val trueWidthTemp = reader.uInt16()
        if (trueWidthTemp !in 0..widthWithBuffer) {
            throw SpriteParserException("Invalid true image[$index] width <$trueWidthTemp>. Should have been 0..${widthWithBuffer}")
        }
        trueWidthTemp
    } else {
        widthWithBuffer
    }

    val bytesCount = widthWithBuffer * height
    val position = reader.position()
    if (!reader.hasBytes(bytesCount)) {
        throw SpriteParserException("Not enough bytes for sprite[$index]. Expected $bytesCount. Remaining ${reader.size - position}")
    }

    Log.iIf(SPR_SHORT_DEBUG_LOGGING_VERBOSE) {
        "Sprite[$setIndex].Frame[$index]->WidthWithBuffer: $widthWithBuffer; TrueWidth:$trueWidth; Height: $height; Offset: $position; To: ${position + bytesCount}"
    }
    var imageBuffer: ByteStreamReader? = reader.copyOfRange(position, position + bytesCount)
    return Pair(
        SpriteFrameAsyncImpl(
            trueWidth,
            height,
            palette,
            false,
            { imageBuffer?.close(); imageBuffer = null }
        ) {
            readShortSprFrame(
                bytesBuffer = imageBuffer.orThrow(),
                setIndex,
                index,
                offset = 0,
                trueWidth = trueWidth,
                widthWithBuffer = widthWithBuffer,
                height = height,
                flipped
            )
        }, bytesCount
    )
}

/**
 * Reads the actual image data SPR short file
 * @param setIndex the current set being read from this multi-sprite file (if any)
 * @param index this frames index in this SPR image set
 * @param trueWidth The actual visible part of the image, this is without forcing width to a multiple of 4
 * @param widthWithBuffer This is the width in bytes, padded to a multiple of 4
 * @param height height of image to read
 * @param flipped whether this image is written upside down and needs to be flipped
 */
private fun ByteStreamReader.readSprMultiSpriteFrame(
    setIndex: Int?,
    index: Int?,
    trueWidth: Int,
    widthWithBuffer: Int,
    height: Int,
    flipped: Boolean,
): PixelIndices {
    val out = IntArray(trueWidth * height) { 0 }

    val imageByteLength = widthWithBuffer * height
    if (position() + imageByteLength > size) {
        throw SpriteParserException("Not enough bytes to read Sprite[$setIndex].frame[$index]. Expected: <${imageByteLength}> more bytes; Found: <${size - position()}>")
    }
    // Read rows reversed if needed
    val yRange = if (flipped) {
        (height - 1) downTo 0
    } else {
        0 until height
    }
    for (y in yRange) {
        val offsetY = y * trueWidth
        repeat(widthWithBuffer) x@{ x ->
            // Skip padding bytes
            if (x >= trueWidth) {
                skip(1)
                return@x

            }
            // Read uInt8 as color palette index
            val paletteIndex = uInt8()
            if (paletteIndex !in 0..255) {
                throw SpriteParserException("Palette index '$paletteIndex' is invalid")
            }

            out[offsetY + x] = paletteIndex
        }
    }
    return PixelIndices(trueWidth, height, out)
}


internal fun RGBA.toSimpleString(): String {
    return "{r: $r, g: $g, b: $b}"
}