package com.bedalton.creatures.agents.pray.parser

import com.bedalton.creatures.agents.pray.compiler.*
import com.bedalton.creatures.agents.pray.compiler.caos2pray.Caos2PrayShortTags
import com.bedalton.creatures.agents.pray.compiler.data.*
import com.bedalton.creatures.agents.pray.compiler.data.Tag.LinkTag
import com.bedalton.creatures.agents.pray.compiler.data.Tag.StringTag
import com.bedalton.creatures.agents.util.RelativeFileSystem
import com.bedalton.common.util.className
import com.bedalton.common.util.like
import com.bedalton.common.util.quote
import com.bedalton.common.util.superEscape
import com.bedalton.log.Log


internal suspend fun constructCaos2PrayFile(
    namespace: String,
    blocks: List<CompilerPrayBlock>,
    fileWriter: RelativeFileSystem,
    outScripts: NonDuplicateScriptHolder,
    inlineScripts: Boolean,
): List<String> {

    // Get all file blocks and convert them to their appropriate format
    val dataBlocks = blocks.filterIsInstance<CompilerDataBlock>()

    val outsideFileNames = mutableListOf<String>()
    val fileNames = dataBlocks.associate { block ->
        block.blockName.text to block.blockTag.text
    }

    // Convert each block to its own CAOS2Pray file
    blocks.filterIsInstance<CompilerBlockWithTags>().forEach map@{ block ->
        // Get CAOS2 pray text
        val builder = StringBuilder("**CAOS2Pray")
            .appendLine()
            .writeTagBlockAsCaos2Pray(namespace, block, fileNames, outScripts, inlineScripts)
            .apply {
                if (this == null) {
                    Log.e { "Failed to write tag block ${block.blockTag}[${block.blockName}] as CAOS2Pray;" }
                    return@map
                }
            }

        // Write CAOS2Pray file
        val fileName = namespaceValue(
            namespace,
            block.blockTag,
            block.blockName.text + ".caos2pray.cos"
        )
        fileWriter.write(fileName, builder.toString().encodeToByteArray())
        outsideFileNames.add(fileName)
    }

    // Return the name of files created
    return outsideFileNames
}

private fun StringBuilder.writeTagBlockAsCaos2Pray(
    namespace: String,
    block: CompilerBlockWithTags,
    dataBlocks: Map<String, String>,
    outScripts: NonDuplicateScriptHolder,
    inlineScripts: Boolean,
): StringBuilder? {
    if (block.intTags.getInt("Agent Type") != 0) {
        return null
    }
    val blockName = block.blockName.text
    append("*# Pray-File ")
        .quote("$namespace${block.blockTag}-${block.blockName}")
        .appendLine()
        .append("*# ${block.blockTag}-Name ")
        .quote(block.blockName)
        .appendLine()

    val script = StringBuilder()
    val attached: MutableSet<String> = mutableSetOf()

    block
        .tags
        .sortedBy { it.tag }.forEach each@{ tag ->
            val tagName = Caos2PrayShortTags.SHORT_TAGS.entries.firstOrNull { it.value == tag.tag }?.key ?: tag.tag

            val skip = when (tag) {
                is StringTag -> SCRIPT_TAG_REGEX.matches(tagName)
                is Tag.IntTag -> {
                    DEPENDENCY_CATEGORY_REGEX.matches(tagName) ||
                            SCRIPT_COUNT_TAG_REGEX.matches(tagName) ||
                            DEPENDENCY_COUNT_REGEX.matches(tagName) ||
                            tagName like "Agent Type"
                }

                else -> {
                    append("*! ").append("UNKNOWN TAG DATA TYPE! ${tag::className}; $tagName = ${tag.value}")
                    return@each
                }
            }

            if (skip) {
                return@each
            }

            append("*# ")
            if (tag is StringTag || tag is LinkTag) {
                if (REMOVER_SCRIPT_REGEX.matches(tagName)) {
                    append("rscr ")
                    if (inlineScripts) {
                        quote(superEscape(tag.value.toString()))
                    } else {
                        quote(outScripts.add(namespace, blockName, tag.value.toString(), true))
                    }
                } else if (DEPENDENCY_TAG_REGEX.matches(tagName)) {
                    val name = tag.value.toString()
                    if (name in dataBlocks.keys && name !in attached) {
                        val namespaceFile = namespaceValue(
                            namespace,
                            dataBlocks[name] ?: "",
                            name,
                            isData = true
                        )
                        attached.add(name)
                        if (namespaceFile != name) {
                            append("Inline ")
                                .quote(name)
                                .append(' ')
                                .quote(namespaceFile)
                                .appendLine()
                                // Since files are namespaced. We cannot use attach and must use "depend" and "inline"
                                .append("*# Depend ")
                                .quote(name)
                        } else {
                            append("Attach ").quote(name)
                        }
                    }
                } else {
                    append(tagName).append(" = ").quote(tag.value.toString())
                }
            } else if (tag is Tag.IntTag) {
                append(tagName).append(" = ").append(tag.value)
            }
            appendLine()
        }

    dataBlocks.keys.subtract(attached).forEach each@{
        val namespacedFileName = namespaceValue(
            namespace,
            dataBlocks[it]!!,
            it,
            true
        )
        if (namespacedFileName != it) {
            append("*# Inline ")
                .quote(it)
                .appendLine()
        } else {
            append("*# Inline ")
                .quote(it)
                .append(' ')
                .quote(namespacedFileName)
                .appendLine()
        }
    }

    val linkedScripts = mutableListOf<String>()
    val inlinedScripts = mutableListOf<Pair<String, String>>()
    if (inlineScripts) {
        block
            .getScriptsNamespaced(namespace)
            .forEach { (_, scriptTag) ->
                // Append any script to the body of this file
                inlinedScripts.add(Pair(scriptTag.tag, scriptTag.value))
                appendLine()
            }
    } else {
        block.scripts()
            .sortedBy { it.first }
            .forEach { scriptTag ->
                val name = outScripts.add(namespace, blockName, scriptTag.second, false)
                linkedScripts.add(name)
                appendLine()
            }
    }

    // Link all non-inlined scripts
    if (linkedScripts.isNotEmpty()) {
        append("*# Link ")
        linkedScripts
            .sorted()
            .forEach { scriptName ->
                append(' ')
                    .quote(scriptName)
            }
        appendLine()
    }

    inlinedScripts
        .sortedBy { it.first }
        .forEach { (scriptName, scriptText) ->
            script.append("\n*** Inlined: ")
                .append(scriptName)
                .append(" ***\n")
                .append(scriptText)
                .appendLine()
        }
    append("\n")
    append(script)
    return this
}