@file:Suppress("unused")

package com.bedalton.creatures.sprite.parsers

import com.bedalton.creatures.sprite.util.ColorPalette
import com.bedalton.creatures.sprite.util.Int32Palette
import korlibs.image.bitmap.Bitmap32
import korlibs.image.color.RGBA
import kotlinx.serialization.Serializable


@Suppress("MemberVisibilityCanBePrivate")
@Serializable
data class PixelIndices(
    val width: Int,
    val height: Int,
    val pixels: IntArray
) {

    val hasAnyTransparentPixels by lazy {
        pixels.any { it == TRANSPARENT_BLACK }
    }

    private var mWithoutTransparentPixelMarkers: PixelIndices? = null

    val withoutTransparentPixelMarkers: PixelIndices get() {
        mWithoutTransparentPixelMarkers?.let { return it }
        if (!hasAnyTransparentPixels) {
            return this
        }
        val newPixels = pixels.map {
            if (it == TRANSPARENT_BLACK) {
                0
            } else {
                it
            }
        }.toIntArray()
        val out = PixelIndices(width, height, newPixels)
        mWithoutTransparentPixelMarkers = out
        return out
    }



    fun pixel(x: Int, y: Int): Int {
        return (pixels.getOrNull(x * width + y))
            ?: throw IndexOutOfBoundsException("Pixel $x:$y is out of range; MaxX: ${width - 1}; MaxY: ${height - 1}")
    }

    fun row(y: Int): IntArray {
        val startX = y * width
        return pixels.copyOfRange(startX, startX + width)
    }

   fun row(y: Int, palette: Int32Palette): IntArray {
        val startX = y * width
        val out = IntArray(width)
        for (x in 0 until width) {
            out[x] = palette[pixels[startX + x]]
        }
        return out
    }

    fun row(y: Int, palette: ColorPalette): List<RGBA> {
        val startX = y * width
        return (0 until width).map { x ->
            when (val color = pixels[startX + x]) {
                TRANSPARENT_BLACK -> {
                    ColorPalette.TRANSPARENT_BLACK
                }

                0 -> {
                    ColorPalette.OPAQUE_BLACK
                }

                else -> {
                    palette[color]
                }
            }
        }
    }


    fun column(x: Int): List<Int> {
        return (0 until height).map { y ->
            // No need to replace shifted opaque black with zero
            pixels[(y * width) + x]
        }
    }


    fun column(x: Int, palette: ColorPalette): List<RGBA> {
        return (0 until height).map { y ->
            // No need to replace shifted opaque black with zero
            when (val color = pixels[(y * width) + x]) {
                TRANSPARENT_BLACK -> {
                    ColorPalette.TRANSPARENT_BLACK
                }
                0 -> {
                    ColorPalette.OPAQUE_BLACK
                }
                else -> {
                    palette[color]
                }
            }
        }
    }

    fun pixel(x: Int, y: Int, palette: ColorPalette): RGBA {
        return pixel(x, y, palette, ColorPalette.TRANSPARENT_BLACK)
    }

    fun pixel(x: Int, y: Int, palette: ColorPalette, transparentBlack: RGBA): RGBA {
        val color = (pixels.getOrNull(x * width + y))
            ?: throw IndexOutOfBoundsException("Pixel $x:$y is out of range; MaxX: ${width - 1}; MaxY: ${height - 1}")

        return when (color) {
            TRANSPARENT_BLACK -> {
                transparentBlack
            }
            0 -> {
                ColorPalette.OPAQUE_BLACK
            }
            else -> {
                palette[color]
            }
        }
    }

    fun withPalette(palette: ColorPalette): Bitmap32 {
        return withPalette(palette, palette[0])
    }

    fun withPalette(palette: ColorPalette, transparentBlack: RGBA): Bitmap32 {
        return withPalette(palette.colors, transparentBlack)
    }

    fun withPalette(palette: List<RGBA>): Bitmap32 {
        return withPalette(palette, false)
    }

    fun withPalette(palette: List<RGBA>, keepBlack: Boolean): Bitmap32 {
        return withPalette(palette, if (keepBlack) {
            ColorPalette.OPAQUE_BLACK
        } else {
            ColorPalette.TRANSPARENT_BLACK
        })
    }

    fun withPalette(palette: List<RGBA>, transparentBlack: RGBA): Bitmap32 {
        val bitmap = Bitmap32(width, height, premultiplied = true)
        val opaqueBlack = ColorPalette.OPAQUE_BLACK

        var i = 0
        repeat(height) { y ->
            repeat(width) { x ->
                val pixel = pixels[i++]
                bitmap[x, y] = when (pixel) {
                    0 -> opaqueBlack
                    TRANSPARENT_BLACK -> transparentBlack
                    else -> palette[pixel]
                }
            }
        }
        return bitmap
    }

    override fun equals(other: Any?): Boolean {
        if (this === other) return true
        if (other == null || this::class != other::class) return false

        other as PixelIndices

        if (width != other.width) return false
        if (height != other.height) return false
        if (!pixels.contentEquals(other.pixels)) return false

        return true
    }

    override fun hashCode(): Int {
        var result = width
        result = 31 * result + height
        result = 31 * result + pixels.contentHashCode()
        return result
    }

    fun flipX(): PixelIndices {
        val out = mutableListOf<Int>()
        repeat (height) { y ->
            out.addAll(row(y).reversed())
        }
        return PixelIndices(
            width,
            height,
            out.toIntArray()
        )
    }

    fun flipY(): PixelIndices {
        val out = mutableListOf<Int>()
        for (y in height - 1 downTo 0) {
            out.addAll(row(y).reversed())
        }
        return PixelIndices(
            width,
            height,
            out.toIntArray()
        )
    }
    companion object {
        const val TRANSPARENT_BLACK = -1
    }
}


fun Int.isSpriteOpaqueBlack(): Boolean {
    return this != PixelIndices.TRANSPARENT_BLACK
}

fun Int.isSpriteOpaquePixel(): Boolean {
    return this != 0
}