package com.bedalton.creatures.caos.collectors

import com.bedalton.creatures.caos.antlr.CaosUniversalLexer
import com.bedalton.creatures.caos.collectors.internal.StopCommands
import com.bedalton.creatures.caos.collectors.internal.StopsWalker
import org.antlr.v4.kotlinruntime.CharStreams


/**
 * Gets all stops based on command words not found in an R/L value context
 */
//@JsName("getStops")
fun getStops(variant: String, text: String): IntArray {
    val charStream = CharStreams.fromString(text)
    val lexer = CaosUniversalLexer(charStream)
    return StopsWalker(StopCommands[variant] ?: intArrayOf(), lexer).stops
}
