package com.bedalton.common.ast.serialization

import com.bedalton.common.serialization.*
import com.bedalton.common.ast.hints.InlayHintImpl
import com.bedalton.common.ast.structs.InlayHint
import com.bedalton.common.ast.structs.Position
import com.bedalton.common.ast.structs.PositionImpl
import com.bedalton.common.ast.structs.TextEdit
import kotlinx.serialization.KSerializer
import kotlinx.serialization.SerializationException
import kotlinx.serialization.builtins.ListSerializer
import kotlinx.serialization.builtins.nullable
import kotlinx.serialization.descriptors.SerialDescriptor
import kotlinx.serialization.descriptors.buildClassSerialDescriptor
import kotlinx.serialization.descriptors.element
import kotlinx.serialization.encoding.CompositeDecoder
import kotlinx.serialization.encoding.Decoder
import kotlinx.serialization.encoding.Encoder

object InlayHintSerializer : KSerializer<InlayHint> {

    // Serializers
    private val textEditListSerializer = ListSerializer(TextEditSerializer).nullable

    // Indices
    private const val POSITION_INDEX = 0 // position: Position
    private const val LABEL_INDEX = 1 // label: String
    private const val KIND_INDEX = 2 //kind: Int?
    private const val TEXT_EDITS_ARRAY_INDEX = 3// textEdits: Array<TextEdit>
    private const val TOOLTIP_INDEX = 4 //tooltip: String?
    private const val PADDING_LEFT_INDEX = 5 //paddingLeft: Boolean?
    private const val PADDING_RIGHT_INDEX = 6 //paddingRight: Boolean?

    override val descriptor: SerialDescriptor by lazy {
        buildClassSerialDescriptor("InlayHint") {
            element("position", PositionSerializer.descriptor)
            element<String>("label")
            element<Int?>("kind")
            element<Array<TextEdit>>("text_edits")
            element<String?>("tooltip")
            element<Boolean>("padding_left")
            element<Boolean>("padding_right")
//            element<Any>("")
        }
    }

    override fun deserialize(decoder: Decoder): InlayHint {
        val descriptor = descriptor
        val ob = decoder.beginStructure(descriptor)
        var index: Int
        var position: Position? = null
        var label: String? = null
        var kind: Int? = null
        var edits: Array<TextEdit>? = null
        var tooltip: String? = null
        var paddingLeft: Boolean? = null
        var paddingRight: Boolean? = null
        while (ob.decodeElementIndex(descriptor).also { index = it } != CompositeDecoder.DECODE_DONE) {
            when (index) {
                POSITION_INDEX -> position = ob.decodeSerializableElement(
                    descriptor,
                    index,
                    PositionImpl.serializer()
                )

                LABEL_INDEX -> label = ob.decodeStringElement(
                    descriptor,
                    index
                )

                KIND_INDEX -> kind = ob.decodeNullableIntElement(
                    descriptor,
                    index
                )

                TEXT_EDITS_ARRAY_INDEX -> edits = ob.decodeSerializableElement(
                    descriptor,
                    index,
                    textEditListSerializer,
                )?.toTypedArray()

                TOOLTIP_INDEX -> tooltip = ob.decodeNullableStringElement(
                    descriptor,
                    index
                )

                PADDING_LEFT_INDEX -> paddingLeft = ob.decodeNullableBooleanElement(
                    descriptor,
                    index
                )

                PADDING_RIGHT_INDEX -> paddingRight = ob.decodeNullableBooleanElement(
                    descriptor,
                    index
                )
            }
        }
        ob.endStructure(descriptor)
        if (position == null || label == null) {
            val missing = if (position == null && label == null) {
                "position, label"
            } else if (position == null) {
                "position"
            } else {
                "label"
            }
            throw SerializationException("InlayHint is missing element: [$missing]")
        }
        return InlayHintImpl(
            position = position,
            label = label,
            kind = kind,
            textEdits = edits,
            tooltip = tooltip,
            paddingLeft = paddingLeft,
            paddingRight = paddingRight
        )
    }

    override fun serialize(encoder: Encoder, value: InlayHint) {
        val ob = encoder.beginStructure(descriptor)
        ob.encodeSerializableElement(descriptor, POSITION_INDEX, PositionSerializer, value.position)
        ob.encodeStringElement(descriptor, LABEL_INDEX, value.label)
        ob.encodeNullableIntElement(descriptor, KIND_INDEX, value.kind)
        ob.encodeSerializableElement(
            descriptor,
            TEXT_EDITS_ARRAY_INDEX,
            textEditListSerializer,
            value.textEdits?.toList()
        )
        ob.encodeNullableStringElement(descriptor, TOOLTIP_INDEX, value.tooltip)
        ob.encodeNullableBooleanElement(descriptor, PADDING_LEFT_INDEX, value.paddingLeft)
        ob.encodeNullableBooleanElement(descriptor, PADDING_RIGHT_INDEX, value.paddingRight)
        ob.endStructure(descriptor)
    }

}