internal const val PRAY_BLOCK_COMPRESS_FLAG = 1

private const val DEFAULT_INLINE_SCRIPTS: Boolean = false
private val magic by lazy { "PRAY".encodeToByteArray() }

private const val MIN_BLOCK_SIZE = 4 + 128 + 4 + 4 + 4 // Block tag, block name, byte length 1&2, flags

/**
 * Parses a compiled PRAY file from bytes
 * @throws AgentFileDecompilerException
 */
fun parsePrayAgentToMemory(
    bytes: ByteArray,
    whitelist: Array<String>? = null,
    tagSafe: Boolean = false,
    maxBlockSize: Int? = null
): PrayAgentParseResult {
    val reader = MemoryByteStreamReader(bytes)
    return parsePrayAgentToMemory(reader, whitelist, tagSafe, maxBlockSize)
}

/**
 * Parses a compiled PRAY file from a byte stream reader
 * @throws AgentFileDecompilerException
 */
fun parsePrayAgentToMemory(
    reader: ByteStreamReader,
    whitelist: Array<String>? = null,
    tagSafe: Boolean = false,
    maxBlockSize: Int? = null
): PrayAgentParseResult {
    val blocks = parsePrayAgentBlocks(reader, whitelist ?: emptyArray(), tagSafe, maxBlockSize)
    return PrayAgentParseResult(blocks)
}


/**
 * Parses a compiled PRAY file from stream
 * @throws AgentFileDecompilerException
 */
fun parsePrayAgentBlocks(
    reader: ByteStreamReader,
    whitelist: Array<String> = emptyArray(),
    tagSafe: Boolean,
    maxBlockSize: Int? = null
): List<PrayBlock> {
    val agentMagic = reader.bytes(4)
    if (!magic.contentEquals(agentMagic)) {
        throw AgentFileDecompilerException("Not a pray file. Header does not match")
    }
    val shouldAdd: (blockName: PrayBlock) -> Boolean = if (whitelist.isEmpty() || whitelist.intersect(setOf("ALL", "*")).isNotEmpty()) {
        { true }
    } else if (whitelist.intersect(listOf("NONE", "", "!")).isNotEmpty()) {
        { false }
    } else {
        val blacklistRegex = whitelist.filter { it.isNotBlank() && it.trim()[0] == '!' }
            .filter { it.isNotBlank() }
            .joinToString("|")
            .let {
                "($it)".toRegex(RegexOption.IGNORE_CASE)
            }
        val whitelistRegex = whitelist.filter { it.isNotBlank() && it.trim()[0] != '!' }
            .joinToString("|")
            .let {
                "($it)".toRegex(RegexOption.IGNORE_CASE)
            };

        { block ->
            !blacklistRegex.matches(block.blockTag) &&
                    (block is BlockWithTags || whitelistRegex.matches(block.blockTag))
        }
    }
    val blocks = mutableListOf<PrayBlock>()
    while (reader.hasBytes(MIN_BLOCK_SIZE)) {
        val block = parseBlock(reader, tagSafe, maxBlockSize)
            ?: continue
        if (shouldAdd(block)) {
            blocks.add(block)
        }
    }
    return blocks
}


private fun parseBlock(reader: ByteStreamReader, safe: Boolean, maxBlockSize: Int? = null): PrayBlock? {
    val startPosition = reader.position()
    val blockTag = reader.string(4)
    val blockTagInt = tok(blockTag)
    val name = reader.string(128).substringBefore(0x00.toChar())
    val actualLength = reader.int32()
    val decompressedLength = reader.int32()
    if (maxBlockSize != null && (actualLength > maxBlockSize || decompressedLength > maxBlockSize)) {
        throw AgentFileDecompilerException("Max block size exceeded in block $blockTag at $startPosition. Max block size: $maxBlockSize; ActualLength: $actualLength; DecompressedLength: $decompressedLength")
    }
    val flags = reader.uInt32()
    val isCompressed = flags hasFlag PRAY_BLOCK_COMPRESS_FLAG
    if (!reader.hasBytes(actualLength)) {
        throw AgentFileDecompilerException("Not enough bytes left to read PRAY $blockTag at $startPosition block. Expected $actualLength; Found: ${reader.size - reader.position()}")
    }
    if (reader.position() != startPosition + 144) {
        throw AgentFileDecompilerException("Reader has not incremented position properly. Start: $startPosition; Expected: ${startPosition + 144}; Found: ${reader.position()}")
    }
    // Get byte start end
    val start = reader.position()
    val end = start + actualLength

    // Skip bytes so they are not double read
    reader.skip(actualLength)

    if (reader.position() != startPosition + 144 + actualLength) {
        throw AgentFileDecompilerException("Skipped bytes for delayed read, but position does not match expected. Start: $startPosition; ActualLength: $actualLength; Expected: ${startPosition + 144L + actualLength}; Actual: ${reader.position()}")
    }

    val bytesNow: () -> ByteArray = {
        val copy = reader.copyAsOpened()
        val compressed = (copy ?: reader).copyOfBytes(start, end)
        copy?.close()
        if (compressed.size != actualLength) {
            throw Exception("Failed to read required number of bytes for [$blockTag]->$name")
        }
        val decompressed = if (flags hasFlag PRAY_BLOCK_COMPRESS_FLAG) {
            Compressor.decompress(compressed)?.apply {
                if (this.size != decompressedLength) {
                    throw AgentFileDecompilerException("Decompressed data block size differs from expected in [$blockTag]->\"$name\"; Expected: $decompressedLength; Actual: ${this.size}")
                }
            }
        } else {
            null
        }
        decompressed ?: compressed
    }

    val blockNow: () -> PrayBlock = {
        DataBlock(
            commonName = blockTag,
            blockTag = blockTag,
            blockName = name,
            stream = reader.copyAsOpened() ?: reader,
            byteStart = start.toInt(),
            byteEnd = end.toInt(),
            decompressedLength,
            compressed = isCompressed,
            cacheBytes = false
        )
    }
    if (blockTagInt in UNSUPPORTED_BLOCKS || blockTagInt in FILE_BLOCKS) {
        return blockNow()
    }
    return try {
        parseTagBlock(blockTag, name, start.toInt(), safe, bytesNow)
    } catch (e: Exception) {
        blockNow()
    }
}

private fun parseTagBlock(
    blockTag: String,
    blockName: String,
    startOffset: Int,
    safe: Boolean,
    data: () -> ByteArray,
): PrayBlock {
    val tags = try {
        getTagParser(blockTag, blockName, startOffset, data)
    } catch (e: Exception) {
        if (safe) {
            { emptyArray() }
        } else {
            throw e
        }
    }
    return PrayBlock.makeBlock(
        blockTag = blockTag,
        blockName = blockName,
        safe = safe,
        false,
        getTags = tags,
    )
}

internal fun getTagParser(
    blockTag: String,
    blockName: String,
    startOffset: Int,
    data: () -> ByteArray,
    onError: ((Throwable) -> Unit)? = null,
): () -> Array<Tag<*>> {
        val bytes = try {
            data()
        } catch (e: Exception) {
            onError?.invoke(AgentFileDecompilerException("Failed to get bytes for $blockTag[$blockName] at $startOffset. ${e.className}: ${e.message};\n${e.stackTraceToString()}"))
            return { emptyArray() }
        }
        // Create reader for this block of data bytes
        val tags: Array<Tag<*>> = ByteStreamReader.read(bytes) read@{
            val reader = this

            // Read int tag count
            val intTagsCount = reader.uInt32()
            if (intTagsCount > 1000) {
                return@read emptyArray()
            }
            // Read int tags
            val intTags = (0 until intTagsCount).map { i ->
                val length = reader.uInt32()
                if (length > bytes.size) {
                    onError?.invoke(AgentFileDecompilerException("Invalid string length <$length> for int tag $i in $blockTag[$blockName] at ${startOffset + reader.position() - 4}"))
                    return@read emptyArray()
                }
                Tag.IntTag(
                    try {
                        reader.string(length)
                    } catch (e: Exception) {
                        onError?.invoke(
                            AgentFileDecompilerException(
                                "Failed to read int tag $i in $blockTag[$blockName]",
                                e
                            )
                        )
                        return@read emptyArray()
                    },
                    reader.uInt32().toInt()
                )
            }

            // Read string tag count
            val stringTagCount = reader.uInt32()
            if (stringTagCount > 1500) {
                onError?.invoke(AgentFileDecompilerException("Too many string tags. Expecting $stringTagCount string tags"))
                return@read emptyArray()
            }

            // Read string tags
            val stringTags = (0 until stringTagCount).map { i ->
                Tag.StringTag(
                    try {
                        reader.string(reader.uInt32())
                    } catch (e: Exception) {
                        onError?.invoke(AgentFileDecompilerException("Invalid string length for int tag $i in $blockTag[$blockName]"))
                        return@read emptyArray()
                    },
                    try {
                        reader.string(reader.uInt32())
                    } catch (e: Exception) {
                        onError?.invoke(AgentFileDecompilerException("Invalid string length for string value in tag $i in $blockTag[$blockName]"))
                        return@read emptyArray()
                    },
                )
            }
            (intTags + stringTags).toTypedArray()
        }
        return { tags }
}


