package com.bedalton.creatures.agents.pray.data

import com.bedalton.creatures.agents.pray.compiler.writeBlock
import com.bedalton.io.bytes.ByteStreamWriter
import kotlin.reflect.KClass

/**
 * Represents block with tags such as EGGS, AGNT, DSAG, etc
 */
sealed class BlockWithTags(
    blockTag: String,
    blockName: String,
    private val safe: Boolean,
    private val unescape: Boolean,
    private val getTags: () -> Array<Tag<*>>,
) : PrayBlock(blockTag, blockName) {


    // Combination of all tags for iteration
    // TODO see if this is ever needed
    private var mTags: Array<Tag<*>>? = null

    // Public facing tags array
    //  Needed so that agents blocks can separate
    //  regular string tags from script tags
    open val tags: Array<Tag<*>> get() = try {
        mTags ?: getTags().apply {
            mTags = this
        }
    } catch (e: Exception) {
        if (safe) {
            emptyArray()
        } else {
            throw e
        }
    }

    /** String tags only */
    val stringTags: Array<Tag.StringTag> by lazy {
        tags.filterIsInstance<Tag.StringTag>().toTypedArray()
    }

    /** Int tags only */
    val intTags: Array<Tag.IntTag> by lazy {
        tags.filterIsInstance<Tag.IntTag>().toTypedArray()
    }

    fun string(tag: String): String? {
        return stringTags.firstOrNull { it.tag == tag }?.value
    }

    fun int(tag: String): Int? {
        return intTags.firstOrNull { it.tag == tag }?.value
    }

    /**
     * Gets the last tag with the tag name given
     */
    operator fun get(tag: String, last: Boolean = true): Tag<*>? {
        return if (last)
            tags.lastOrNull { it.tag.equals(tag, true) }
        else
            tags.firstOrNull { it.tag.equals(tag, true) }
    }

    /**
     * Gets a tag given a types class
     */
    internal inline operator fun <reified T : KClass<Tag<*>>> get(tag: String, last: Boolean = true): T? {
        return if (last)
            tags.filterIsInstance<T>().lastOrNull { (it as Tag<*>).tag.equals(tag, true) }
        else
            tags.filterIsInstance<T>().firstOrNull { (it as Tag<*>).tag.equals(tag, true) }
    }

    abstract fun copyWithTags(tags: Array<Tag<*>>): BlockWithTags


    override fun write(writer: ByteStreamWriter, compress: Boolean) {
        writeBlock(writer, this, compress, unescape)
    }
}