package com.creaturesforge.application.state

import com.bedalton.common.util.*
import com.bedalton.log.LOG_VERBOSE
import com.bedalton.log.Log
import com.bedalton.log.iIf
import com.creaturesforge.application.util.isAutoNameNullOrBlank
import com.creaturesforge.application.util.notStartsWith
import com.creaturesforge.application.util.nullIfAutoNameNullOrBlank

internal object AutoNamesHelper {

    private val genomeWithGenTypeRegex = "^resource:.*?/?(?:(?:norn|gren(?:del)?|etti?n|geat)\\\\.)?(twb|cfe|tcb|ex\\d+|final46e|final46g|46g|46e)\\.gen".toRegex(RegexOption.IGNORE_CASE)

    private val userGenomeWithGenTypeRegex =
        "^.*?\\.(cfem?|cff|twb|tcb|2017|(final)?46[eg])\\..*?$".toRegex(RegexOption.IGNORE_CASE)
    private val stockExRegex = "^.*?\\.(ex\\d+|48|47|(final)?46[eg])\\..*?$".toRegex(RegexOption.IGNORE_CASE)
    private val toxicRegex = "^.*?\\.(toxic(colortrue)?)[.-].*?$".toRegex(RegexOption.IGNORE_CASE)
    private val genusRegex = ".*?(norn|gren(del)?|etti?n|geat|shee).*".toRegex(RegexOption.IGNORE_CASE)

    fun updateAutoNames(state: ForgeState): ForgeState {

        var out = state

        out = updateEggAutoNames(out)

        state.maleGlyph?.let { updateGlyphName(out, it, true) }.also {
            out = out.copy(maleGlyph = it)
        }

        state.femaleGlyph?.let { updateGlyphName(out, it, false) }.also {
            out = out.copy(femaleGlyph = it)
        }



        return out
    }

    private fun updateEggAutoNames(state: ForgeState): ForgeState {
        val genomeFilesWithName = EggFileNameUtil.mapGenomePathsLowercaseToFileNames(state.eggs)

        var out = state
        for (egg in out.eggs) {
            val temp = updateEggAutoName(state, egg, genomeFilesWithName)
            out = out.copy(
                eggs = out.eggs.filter { it.id != egg.id } + temp
            )
        }

        return out.copy(
            selectedEgg = getSelectedEgg(out, out.eggs)
        )
    }

    private fun updateEggAutoName(state: ForgeState, egg: EggData, genomeFilesWithNames: Map<String, String>): EggData {

        var out = egg


        if (egg.eggName.nullIfAutoNameNullOrBlank() == null) {
            val eggName = getDefaultEggName(state, out)
            if (eggName != null) {
                out = out.copy(
                    eggName = ":$eggName"
                )
            }
        }

        out.baseGenomeFile
            ?.let { updateAutoGenomeFilename(state, out, genomeFilesWithNames, it) }
            ?.also {
                out = out.copy(baseGenomeFile = it)
            }

        out.motherGenomeFile
            ?.let { updateAutoGenomeFilename(state, out, genomeFilesWithNames, it) }
            ?.also {
                out = out.copy(motherGenomeFile = it)
            }

        out.fatherGenomeFile
            ?.let { updateAutoGenomeFilename(state, out, genomeFilesWithNames, it) }
            ?.also {
                out = out.copy(fatherGenomeFile = it)
            }

        return out
    }

    private fun updateGlyphName(state: ForgeState, glyph: Glyph, male: Boolean): Glyph {

        if (!glyph.filename.isAutoNameNullOrBlank()) {
            return glyph
        }

        val name = getBaseName(state)
            ?: return glyph

        val gender = if (male) "male" else "female"

        val autoName = ':' + (name.lowercase().replace("[\\s:/\\\\]+".toRegex(), "_")
            .replace("[^a-zA-Z0-9_]".toRegex(), "_") + '_' + gender + "_glyph")
            .replace("__+".toRegex(), "_")

        return glyph.withName(autoName.lowercase())
    }

    private fun getDefaultEggName(state: ForgeState, egg: EggData): String? {

        val eggName = getBaseName(state, egg)
            ?: return null

        if (userGenomeWithGenTypeRegex.find(eggName) != null) {
            return eggName
        }

        val genomeCode = setOfNotNull(
            egg.baseGenomeFile?.filename,
            egg.motherGenomeFile?.filename,
            egg.fatherGenomeFile?.filename
        )
            .map {
                userGenomeWithGenTypeRegex.matchEntire(
                    it.replace(
                        "\\s*\\(\\d+\\)\\s*".toRegex(),
                        ""
                    )
                )?.groups?.get(1)?.value
            }
            .singleOrNull()
            ?.nullIfEmpty()

        var tempName = if (genomeCode != null) {
            "$eggName (${genomeCode.uppercase()})"
        } else {
            eggName
        }

        val nameNormalized = tempName.normalizeAutoName()

        val duplicateName = state
            .eggs
            .any {
                it.eggName?.normalizeAutoName() == nameNormalized && it.id != egg.id
            }

        if (duplicateName) {
            tempName = "$eggName (${egg.id})"
        }

        return tempName
    }

    private fun updateAutoGenomeFilename(
        state: ForgeState,
        egg: EggData,
        genomeFilesWithName: Map<String, String>,
        genomeFile: GenomeFile,
    ): GenomeFile {

        val isNotBlank = genomeFile.filename.ensureNotEndsWith(".gen").trim().isNotBlank()
        val isNotAutoName = genomeFile.filename.notStartsWith(':')

        if (isNotBlank && isNotAutoName) {
            Log.iIf(LOG_VERBOSE) { "Genome file filename is not blank and is: <${genomeFile.filename}>" }
            return genomeFile
        }

        val name = getBaseName(state, egg)
            ?: return genomeFile

        genomeFilesWithName[genomeFile.filepath.lowercase()]
            .nullIfAutoNameNullOrBlank()
            ?.let {
                Log.iIf(LOG_VERBOSE) { "Genome already has name: <$it>" }
                return genomeFile.copy(
                    filename = ":$it"
                )
            }

        val filepath = genomeFile.filepath

        val filepathTrimmed = filepath.trim()


        val (genus, prefix) = getGenomeGenusString(state.genomeGenus)
            ?: Pair(null as String?, null as String?)

        val autoName = StringBuilder()
        val breedName = name.lowercase()
        val toxic = if (toxicRegex.matches(filepathTrimmed)) {
            "toxic."
        } else {
            ""
        }
        if (genus.isNotNullOrBlank()) {
            autoName.append(prefix).append('.')
            autoName.append(toxic)
            autoName.append(breedName.replaceFirst("${genus}s?".toRegex(RegexOption.IGNORE_CASE), "").trim())
        } else {
            autoName.append(toxic)
            autoName.append(breedName)
        }

        val baseGenomeName = getBaseGenomeName(filepathTrimmed, name)

        autoName.append(baseGenomeName.trim())
        autoName.append(".gen")
        val autoNameNormalized = autoName.toString()
            .replace("[\\\\/:\\-_\\s\\[\\]()$!*%#]+".toRegex(), ".")
            .replace("\\.{2,}".toRegex(), ".")
            .lowercase()
            .trim(' ', '.')
        Log.iIf(LOG_VERBOSE) { "Genome auto name is: <${genomeFile.filename}>" }
        return genomeFile.copy(
            filename = ":$autoNameNormalized"
        )
    }


    fun stripGenomeInitials(name: String): String {
        val baseRegex = "(CFE|(true\\s*(cold|warm)\\s*blood)|TWB|TCB|ex[46]\\d|final46e|final46g|46g|46e)".toRegex(RegexOption.IGNORE_CASE)
        return name
            .replace(baseRegex, "")
            .trim('-', '.', '_', ' ', '(', ')', '\t')
            .ensureNotStartsWith(':')
            .replace("[\\\\/:]".toRegex(), "-")
    }

    private fun getBaseName(state: ForgeState, egg: EggData? = null): String? {

        ForgeConfig.getCachedDefaultEggName(state, egg)?.let {
            return it
        }

        return egg
            ?.eggName
            .nullIfAutoNameNullOrBlank()
            ?.let(::stripGenomeInitials)
            ?: state.eggs
                .firstNotNullOfOrNull first@{
                    val name = it.eggName.nullIfAutoNameNullOrBlank()
                        ?: return@first null
                    stripGenomeInitials(name)
                        .nullIfAutoNameNullOrBlank()
                }
            ?: getEggNameFromProjectName(state)
    }

    private fun getBaseGenomeName(path: String, eggName: String): String {

        val filepathTrimmed = path.trim()

        var baseGenomeName = genomeWithGenTypeRegex
            .matchEntire(filepathTrimmed)
            ?.groupValues
            ?.get(1)

        if (baseGenomeName == null) {
            baseGenomeName = userGenomeWithGenTypeRegex
                .matchEntire(filepathTrimmed)
                ?.groupValues
                ?.get(1)
                ?: stockExRegex.matchEntire(filepathTrimmed)
                    ?.groupValues
                    ?.get(1)
        }

        if (baseGenomeName.isNullOrBlank()) {
            return ""
        }

        val genomeInEggName = "[._\\- (]((ex)?$baseGenomeName)|((ex)?$baseGenomeName)[._\\- )]"
            .toRegex(RegexOption.IGNORE_CASE)

        // Only append genome type if not already included in egg name
        return if (genomeInEggName.containsMatchIn(eggName)) {
            ""
        } else {
            ".$baseGenomeName"
        }
    }

    private fun getEggNameFromProjectName(state: ForgeState): String? {
        val projectDirectory = state.projectFolder
            ?.trim()
            ?.ensureNotEndsWith('/')
            ?.ensureNotEndsWith('\\')
            ?.trim()
            ?: return null

        val name = PathUtil.getLastPathComponent(projectDirectory)
            .nullIfEmpty()
            ?: return null

        val nameChars = name
            .toCharArray()

        var uppercaseLast = nameChars[0].isUpperCase()

        val out = StringBuilder(nameChars[0].uppercase() + "")

        for (char in nameChars.drop(1)) {
            val isUppercase = char.isUpperCase()
            if (isUppercase) {
                if (!uppercaseLast) {
                    out.append(' ')
                }
            }
            out.append(char)
            uppercaseLast = isUppercase
        }
        val breedName = out.toString()

        if (genusRegex.matches(breedName)) {
            return breedName
        }


        val genusName = genusNameFromGenomeNames(state, "Norns")

        return "$breedName $genusName"
    }

    private fun genusNameFromGenomeNames(state: ForgeState, default: String = "Norn"): String {
        return state.eggs
            .flatMap {
                listOfNotNull(
                    it.baseGenomeFile,
                    it.fatherGenomeFile,
                    it.motherGenomeFile
                )
            }
            .mapNotNull map@{
                val fileName = it.filename
                    .lowercase()
                when {
                    fileName.contains("norn") -> "Norns"
                    fileName.contains("grendel") -> "Grendels"
                    fileName.contains("ettin") -> "Ettins"
                    fileName.contains("geat") -> "Geat"
                    fileName.contains("gren") -> "Grendel"
                    fileName.contains("shee") -> "Shee"
                    else -> null
                }
            }
            .singleOrNull()
            ?: default
    }

    private fun getGenomeGenusString(genus: Int): Pair<String, String>? {
        return when (genus) {
            0 -> Pair("norn", "norn")
            1 -> Pair("grendel", "gren")
            2 -> Pair("ettin", "ettn")
            3 -> Pair("geat", "geat")
            else -> null
        }
    }

    private fun String.normalizeAutoName(): String {
        return ensureNotStartsWith(':').lowercase()
    }
}
