@file:Suppress("unused")

package com.bedalton.creatures.agents.pray.data

import kotlin.js.JsExport

/**
 * Data object for a parsed pray file
 */
@JsExport
data class PrayData(
    val language: String?,
    val fullFilePath: String,
    val blocks: Array<PrayBlock>,
    val unescape: Boolean,
) {
    override fun equals(other: Any?): Boolean {
        if (this === other) return true
        if (other !is PrayData) return false

        if (language != other.language) return false
        if (fullFilePath != other.fullFilePath) return false
        if (!blocks.contentEquals(other.blocks)) return false
        if (unescape != other.unescape) return false

        return true
    }

    override fun hashCode(): Int {
        var result = language?.hashCode() ?: 0
        result = 31 * result + fullFilePath.hashCode()
        result = 31 * result + blocks.contentHashCode()
        result = 31 * result + unescape.hashCode()
        return result
    }
}

