@file:Suppress("unused")

package com.bedalton.creatures.breed.render.files

import com.bedalton.creatures.breed.render.renderer.InvalidRenderValueException

@Suppress("MemberVisibilityCanBePrivate")
data class BreedFileCollection(
    val breedKey: JsBreedKey,
    val files: List<SpriteAndAtt>,
    val parentDirectory: String,
    val shortestPathInCollection: String
) {
    val code: String get() = breedKey.code!!.lowercase()

    val genus: Int get() = breedKey.genus!!

    val age: Int get() = breedKey.ageGroup!!

    val gender: Int get() = breedKey.gender!!

    val breedChar: Char get() = breedKey.breed!![0].lowercaseChar()

    val breedCharString get() = breedKey.breed!!.lowercase()

    val hasHeadPart: Boolean by lazy { hasParts('a') }
    val hasBodyPart: Boolean by lazy { hasParts('b') }
    val hasAllLegParts: Boolean by lazy { hasParts('c', 'd', 'e', 'f', 'g', 'h') }
    val hasAllArmParts: Boolean by lazy { hasParts('i', 'j', 'k', 'l') }
    val hasAllTailParts: Boolean by lazy { hasParts('m', 'n') }
    val hasAllEarParts: Boolean by lazy { hasParts('o','p') }
    val hasHairPart: Boolean by lazy { hasParts('q') }
    val hasHeadAndEars get() = hasHeadPart && hasAllEarParts


    private val representedParts: Set<Char> by lazy {
        files.map { it.part }.toSet()
    }

    init {
        if (!breedKey.isConcrete()) {
            throw InvalidRenderValueException("Breed key for breed file collection is non-concrete", "breed key", breedKey)
        }
    }

    fun hasParts(vararg parts: Char): Boolean {
        return parts.all { part -> part.lowercaseChar() in representedParts }
    }

    fun hasPartsInString(partsString: String): Boolean {
        return hasParts(*partsString.toCharArray())
    }

}


