package com.bedalton.log

internal fun nodeRequireSafe(moduleName: String, vararg requiredProperties: String): dynamic {
    val inBrowser = !(js("(typeof window === 'undefined')") as Boolean)
    if (inBrowser) {
        return null
    }
    val worker = js("typeof WorkerGlobalScope !== 'undefined' && self instanceof WorkerGlobalScope") as Boolean
    if (worker) {
        return null
    }
    val mod = js(
        """
        (function () { 
            if (require == null) {
                return null
            }
            try {
                return require(moduleName);
            } catch (e) {
                return null;
            }
        })()
    """
    )
    if (missingProperties(moduleName, requiredProperties).isNotEmpty()) {
        return null
    }
    return mod
}

external interface JsObject {
    fun hasOwnProperty(string: String): Boolean
}

private fun missingProperties(obj: dynamic, requiredProperties: Array<out String>): List<String> {
    if (requiredProperties.isEmpty()) {
        return emptyList()
    }
    return if (obj.hasOwnProperty != null) {
        val jsObject = obj.unsafeCast<JsObject>()
        requiredProperties.filter { !jsObject.hasOwnProperty(it) }
    } else {
        try {
            requiredProperties.filter { obj[it] == null }
        } catch (e: Exception) {
            requiredProperties.toList()
        }
    }
}