package com.bedalton.creatures.agents.pray.parser

import com.bedalton.common.coroutines.checkCancelled
import com.bedalton.common.util.PathUtil
import com.bedalton.common.util.nullIfEmpty
import com.bedalton.creatures.agents.util.RelativeFileSystem
import com.bedalton.creatures.agents.util.internal.nameWithoutC3DSTail
import com.bedalton.log.LOG_PROGRESS
import com.bedalton.log.Log
import com.bedalton.log.iWith
import com.bedalton.vfs.FileSystem
import com.bedalton.vfs.OutsideFileWriter
import kotlinx.coroutines.CoroutineScope

internal class NonDuplicateScriptHolder {
    private val files: MutableList<Script> = mutableListOf()

    private var index: Int = 0
    private var rscr: Int = 0

    private fun makeName(namespace: String, blockName: String, rscr: Boolean): String {
        val index = if (rscr) ++this.rscr else ++index
        return nameWithoutC3DSTail(blockName).nullIfEmpty()
            ?.let {  "$namespace$blockName-${if (rscr) "RemoverScript" else "Script"}-$index.cos"}
            ?: "Script-$index.cos"
    }

    fun add(namespace: String, blockName: String, script: String, rscr: Boolean): String {
        val length = script.length
        files.firstOrNull { it.length == length && it.script == script }
            ?.apply {
                ++references
                return this.fileName
            }
        val fileName = makeName(namespace, blockName, rscr)
        files.add(Script(
            index = index,
            length = script.length,
            script = script,
            fileName = fileName,
            references = 1
        ))
        return fileName
    }

    suspend fun write(coroutineScope: CoroutineScope, writer: RelativeFileSystem, basePath: String = ""): List<String> {
        val out = mutableListOf<String>()
        for (file in files) {
            // Ensure coroutine has not been cancelled
            coroutineScope.checkCancelled()

            val fileOutPath = basePath.nullIfEmpty()?.let { PathUtil.combine(basePath, file.fileName) } ?: file.fileName
            Log.iWith(LOG_PROGRESS, replace = true) { "Writing $fileOutPath with length ${file.length}" }
            writer.write(fileOutPath, file.script.encodeToByteArray())
            out.add(fileOutPath)
        }
        return out
    }

    suspend fun write(coroutineScope: CoroutineScope, basePath: String, writer: OutsideFileWriter): Boolean {
        for (file in files) {
            // Ensure coroutine has not been cancelled
            coroutineScope.checkCancelled()
            writer.write(PathUtil.combine(basePath, file.fileName), file.script, false)
        }
        return true
    }

    suspend fun write(coroutineScope: CoroutineScope, basePath: String, writer: FileSystem): Boolean {
        for (file in files) {
            // Ensure coroutine has not been cancelled
            coroutineScope.checkCancelled()
            writer.write(PathUtil.combine(basePath, file.fileName), file.script, false)
        }
        return true
    }

}

private data class Script(
    val index: Int,
    val length: Int,
    val script: String,
    val fileName: String,
    var references: Int
)
