@file:Suppress("MemberVisibilityCanBePrivate")

package com.bedalton.creatures.breed.render.support.att

import com.bedalton.creatures.breed.render.support.pose.Pose
import com.bedalton.creatures.breed.render.support.pose.PoseConstants.Facing
import com.bedalton.creatures.breed.render.support.pose.PoseException
import com.bedalton.creatures.breed.render.support.pose.PoseFacing
import com.bedalton.creatures.common.structs.isC1e
import com.bedalton.log.LOG_DEBUG
import com.bedalton.log.Log
import com.bedalton.log.wIf

object PoseToAttLine {

    fun getAttLine(pose: Pose, part: Char, data: AttFileData): AttFileLine? {
        val line = getAttLine(pose, part, data.lines.size == 10)
            ?: return null
        return data.getOrNull(line)
    }

    fun getAttLine(pose: Pose, part: Char, possiblyC1e: Boolean): Int? {
        val tilt = pose[part]
            ?: return null

        val facing = if (part == 'a') {
            pose.headFacing
        } else {
            pose.bodyFacing
        }
        val facingInt = facing
            .int
            ?: pose.bodyFacing.int
            ?: pose.itLocation?.let { pose.bodyFacing.withIt(it) }?.int
            ?: return null

        // Check if is C1e
        val isC1e = pose.variant.isC1e || possiblyC1e

        // C1e has only one sprite for front and one for back
        if (isC1e) {
            if (pose.bodyFacing == PoseFacing.BACK || facing == PoseFacing.BACK) {
                return 9
            } else if (facing == PoseFacing.FRONT) {
                return 8
            }
        }

        if (tilt.int == null) {
            Log.wIf(LOG_DEBUG) { "No concrete tilt for part: $part"}
            return null
        }

        val offset = when (facingInt) {
            Facing.VIEWER_RIGHT -> 0
            Facing.VIEWER_LEFT -> 4
            Facing.FRONT -> 8
            Facing.BACK -> 12  // At this point it is already guaranteed to be C2e
            else -> throw PoseException("Cannot get ATT line with non-integer facing value")
        }

        // Calculate offset by facing int and add tilt
        return offset + tilt.int
    }

}