package com.bedalton.creatures.breed.render.internal

import com.bedalton.creatures.breed.render.files.BreedFileData
import kotlin.math.max


/**
 * Typical Body data folder names
 */
@Suppress("SpellCheckingInspection")
private val possibleAttFolders = listOf("bodydata", "att", "atts", "attachment", "attachments", "attachmentdata")

/**
 * Typical sprite folder names
 */
private val possibleSpriteFolders = listOf("sprite", "sprites", "image", "images")



/**
 * Contains information about the distance between two breed files (i.e. Att and Sprite)
 */
internal data class Distance(
    val path: BreedFileData,
    val partDistance: Int,
    val upDistance: Int,
    val downDistance: Int,
) {
    val computedDistance get() = upDistance + (downDistance * 2)
}

/**
 * Calculates the distance between an ATT file and a matching Sprite file
 */
internal fun filePathDistance(baseDistance: Int, spriteFile: BreedFileData, attFile: BreedFileData, attRoot: String?): Distance {
    val components1 = components(spriteFile.parentPath)
    val components2 = components(attFile.parentPath)
    var shared1 = ""
    var shared2 = ""
    var isAffiliated = false

    // If ATT is in root, prioritize it
    if (attRoot != null && attFile.path.lowercase().startsWith(attRoot.lowercase())) {
        return filePathDistance(baseDistance, attFile, attFile, null)
    }
    for (i in 0..max(components1.lastIndex, components2.lastIndex)) {
        isAffiliated = false
        val component1 = components1.getOrNull(i)?.lowercase()
            ?: break
        val component2 = components2.getOrNull(i)?.lowercase()
            ?: break
        if (component1 != component2 && !isPair(component1, component2)) {
            break
        }
        isAffiliated = true
        shared1 += components1[i] + '/'
        shared2 += components2[i] + '/'
    }

    if (isAffiliated) {
        return Distance(
            path = attFile,
            partDistance = baseDistance,
            upDistance = 0,
            downDistance = 0
        )
    }
    val up = spriteFile.path.substring(shared1.length).count { it == '/' || it == '\\' }
    val down = spriteFile.path.substring(shared2.length).count { it == '/' || it == '\\' }
    return Distance(path = attFile, partDistance = baseDistance, upDistance = up, downDistance = down)
}


/**
 * Checks if two folder components are a matching pair between expected Sprite and ATT folder names
 */
private fun isPair(component1: String, component2: String): Boolean {
    return if (component1.replace(" ", "") in possibleSpriteFolders) {
        component2.replace(" ", "") in possibleAttFolders
    } else if (component1.replace(" ", "") in possibleAttFolders) {
        component2.replace(" ", "") in possibleSpriteFolders
    } else {
        false
    }
}

/**
 * Splits a path along slash boundaries
 */
private fun components(path: String): List<String> {
    return path
        .replace("\\ ", " ")
        .replace('\\', '/')
        .split('/')
}
