package com.creaturesforge.application.ui

import com.bedalton.common.util.trySilent
import kotlinx.browser.document
import kotlinx.html.*
import kotlinx.html.dom.append
import org.w3c.dom.HTMLElement

@DslMarker
annotation class DialogDslMarker

@DialogDslMarker
class ModalDialog(
    initialAttributes: Map<String, String>,
    private val tagConsumer: TagConsumer<*>
): DIV(initialAttributes, tagConsumer) {


    private var mRoot: HTMLElement? = getRoot()
    private var mHeader: HEADER? = null
    private var mMain: SECTION? = null
    private var mFooter: FOOTER? = null


    fun header(work: HEADER.() -> Unit) {
        mHeader?.hidden = false
        mHeader?.work()
    }


    fun main(work: SECTION.() -> Unit) {
        mMain?.hidden = false
        mMain?.work()
    }

    fun footer(work: FOOTER.() -> Unit) {
        mFooter?.hidden = false
        mFooter?.work()
    }

    private fun getRoot(): HTMLElement {
        return document.body!!.append.div {
            this.role = "dialog"
            this.classes += "dialog"
            this.tabIndex = "-1"
            this.attributes["data-class"]
            header {
                this.classes += "dialog-header"
                this@ModalDialog.mHeader = this
                this.hidden = true
            }
            section {
                this.classes += "main"
                this.hidden = true
                this@ModalDialog.mMain = this
            }
            footer {
                this.classes += "footer"
                this@ModalDialog.mFooter = this
            }
        }
    }

    fun open() {
        mRoot?.hidden = false
    }

    fun close() {
        mRoot?.hidden = true
    }

    fun destroy() {

        val root = mRoot
            ?: return
        trySilent {
            root.parentElement?.removeChild(root)
            root.remove()
            Unit
        }
        mHeader = null
        mMain = null
        mFooter = null
    }
}