package com.bedalton.creatures.caos.collectors

import com.bedalton.common.ast.structs.HasRange
import com.bedalton.common.ast.structs.RangeWithIndex
import com.bedalton.common.ast.structs.stitch
import com.bedalton.creatures.caos.libs.CommandType
import com.bedalton.creatures.caos.libs.VariantCaosCommand
import com.bedalton.creatures.caos.libs.VariantCaosParameter
import kotlinx.serialization.SerialName
import kotlinx.serialization.Serializable
import kotlin.js.JsName

@Serializable
data class CommandCallJs (

    @SerialName("typeId")
    override val type: Int,

    @JsName("command")
    val command: VariantCaosCommand,

    @JsName("arguments")
    var arguments: Array<Argument>,

    @JsName("tokenTextRange")
    val tokenTextRange: RangeWithIndex,

    @JsName("inVariant")
    val inVariant: Boolean,

    override val textRange: RangeWithIndex,

    override val parameter: VariantCaosParameter?,

    override var inEqualityExpression: Boolean,

    override val containingCommand: CommandReference?,

    @JsName("tokens")
    val tokens: Array<CaosParserItem.CommandToken>,

    @JsName("callType")
    val callType: CommandType,

    @JsName("isRvalue")
    val isRvalue: Boolean = callType == CommandType.RVALUE,

    @JsName("isLvalue")
    val isLvalue: Boolean = callType == CommandType.LVALUE,

    @JsName("isCommand")
    val isCommand: Boolean = callType == CommandType.COMMAND,

    override val parserItem: CaosParserItem.CompoundCommandToken = CaosParserItem.CompoundCommandToken(tokens),

    override val text: String = listOf(*tokens, *arguments).stitch(),

    val commandString: String = command.command,

    override val parserIndexStart: Int?,

    override val parserIndexEnd: Int?,

    ): HasRange, Argument, CaosItem {
