//    )


    override fun equals(other: Any?): Boolean {
        if (this === other) return true
        if (other !is CommandCallJs) return false

        if (type != other.type) return false
        if (command != other.command) return false
        if (!arguments.contentEquals(other.arguments)) return false
        if (tokenTextRange != other.tokenTextRange) return false
        if (inVariant != other.inVariant) return false
        if (textRange != other.textRange) return false
        if (parameter != other.parameter) return false
        if (inEqualityExpression != other.inEqualityExpression) return false
        if (containingCommand != other.containingCommand) return false
        if (!tokens.contentEquals(other.tokens)) return false
        if (callType != other.callType) return false
        if (isRvalue != other.isRvalue) return false
        if (isLvalue != other.isLvalue) return false
        if (isCommand != other.isCommand) return false
        if (parserItem != other.parserItem) return false
        if (text != other.text) return false
        if (commandString != other.commandString) return false

        return true
    }

    override fun hashCode(): Int {
        var result = type
        result = 31 * result + command.hashCode()
        result = 31 * result + arguments.contentHashCode()
        result = 31 * result + tokenTextRange.hashCode()
        result = 31 * result + inVariant.hashCode()
        result = 31 * result + textRange.hashCode()
        result = 31 * result + (parameter?.hashCode() ?: 0)
        result = 31 * result + inEqualityExpression.hashCode()
        result = 31 * result + (containingCommand?.hashCode() ?: 0)
        result = 31 * result + tokens.contentHashCode()
        result = 31 * result + callType.hashCode()
        result = 31 * result + isRvalue.hashCode()
        result = 31 * result + isLvalue.hashCode()
        result = 31 * result + isCommand.hashCode()
        result = 31 * result + parserItem.hashCode()
        result = 31 * result + text.hashCode()
        result = 31 * result + commandString.hashCode()
        return result
    }
}