package com.bedalton.creatures.agents.pray.compiler

import com.bedalton.common.util.superUnescape
import com.bedalton.creatures.agents.pray.data.BlockWithTags
import com.bedalton.creatures.agents.pray.data.PrayBlock
import com.bedalton.creatures.agents.pray.data.Tag
import com.bedalton.creatures.agents.pray.internal.tok
import com.bedalton.creatures.agents.pray.parser.PRAY_BLOCK_COMPRESS_FLAG
import com.bedalton.io.bytes.ByteStreamWriter
import com.bedalton.io.bytes.Compressor


/**
 * Write the block header for the current pray block
 */
internal fun writeBlockHeader(writer: ByteStreamWriter, block: PrayBlock) {
//    Log.i { "Writing ${block.blockTag} block: \"${block.blockName}\" LINE: ${block.startLine}" }
    writer.writeUInt32(tok(block.blockTag))
    val name = block.blockName.padEnd(128, 0x00.toChar())
    writer.writeStringWithCreaturesEncoding(name)
}

/**
 * Write block header given the block tag and block name
 */
private fun writeBlockHeader(writer: ByteStreamWriter, blockTag: String, blockName: String) {
    writer.writeUInt32(tok(blockTag))
    val name = blockName.padEnd(128, 0x00.toChar())
    writer.writeStringWithCreaturesEncoding(name)
}

/**
 * Write a block with tags and data to the common byte writer
 */
internal fun writeBlock(
    writer: ByteStreamWriter,
    block: BlockWithTags,
    compress: Boolean,
    unescape: Boolean,
) {
    writeBlockHeader(writer, block)
    val contentBytes = ByteStreamWriter.writeBytes {
        val contentsWriter = this
        val tags = block.tags.map {
            if (it is Tag.StringTag && (it.value.contains("\\") || it.value.contains("\n")) && unescape) {
                it.copy(
                    value = superUnescape(it.value)
                )
            } else {
                it
            }
        }
        val intTags = stripDuplicateTags(tags.filterIsInstance<Tag.IntTag>())
            .sortedBy { it.tag }
        contentsWriter.writeUInt32(intTags.size)
        for (tag in intTags) {
            contentsWriter.writeUInt32(tag.tag.length)
            contentsWriter.writeStringWithCreaturesEncoding(tag.tag)
            contentsWriter.writeUInt32(tag.value)
        }
        val stringTags = stripDuplicateTags(tags.filterIsInstance<Tag.StringTag>())
            .sortedBy { it.tag }
        contentsWriter.writeUInt32(stringTags.size)
        for (tag in stringTags) {
            contentsWriter.writeUInt32(tag.tag.length)
            contentsWriter.writeStringWithCreaturesEncoding(tag.tag)
            val value = tag.value
            contentsWriter.writeUInt32(value.length)
            contentsWriter.writeStringWithCreaturesEncoding(value)
        }
    }
    val contentsFullLength = contentBytes.size
    val compressed = if (compress) Compressor.compress(contentBytes) else null
    val compressedLength = compressed?.size ?: contentsFullLength
    // write compressed length
    writer.writeUInt32(compressedLength)
    // Write uncompressed file length
    writer.writeUInt32(contentsFullLength)
    // Write 1 if compressed
    writer.writeUInt32(if (compressed != null) PRAY_BLOCK_COMPRESS_FLAG else 0)
    // Write bytes
    writer.write(compressed ?: contentBytes)
}


/**
 * Strip duplicate tags keeping only the last one as the official PrayBuilder.exe does
 */
private inline fun <reified T : Tag<*>> stripDuplicateTags(tags: List<T>): Array<T> {
    val keys = tags.map { it.tag }.toSet()
    val out: List<T> = keys.map { key ->
        tags.last { tag -> tag.tag == key }
    }
    return out.toTypedArray()
}