package com.creaturesforge.application.util

import kotlin.contracts.contract

internal fun String.withExtension(extension: String): String {
    if (extension.isBlank()) {
        return this
    }
    val withDot = if (extension[0] == '.') extension else ".$extension"
    return if (this.endsWith(withDot)) {
        this
    } else {
        this + withDot
    }
}

internal fun String.notStartsWith(prefix: String, ignoreCase: Boolean = false): Boolean {
    return !startsWith(prefix, ignoreCase)
}

internal fun String.notEndsWith(prefix: String, ignoreCase: Boolean = false): Boolean {
    return !endsWith(prefix, ignoreCase)
}


internal fun String.notStartsWith(prefix: Char, ignoreCase: Boolean = false): Boolean {
    return !startsWith(prefix, ignoreCase)
}

internal fun String.notEndsWith(prefix: Char, ignoreCase: Boolean = false): Boolean {
    return !endsWith(prefix, ignoreCase)
}

internal fun String?.isAutoNameNullOrBlank(): Boolean {

    contract {
        returns(false) implies (this@isAutoNameNullOrBlank != null)
    }
    return this.isNullOrBlank() || this.startsWith(':')
}

internal fun String?.nullIfAutoNameNullOrBlank(): String? {
    if (this.isNullOrBlank()) {
        return null
    }
    if (this.startsWith(':')) {
        return null
    }
    return this
}
