@file:Suppress("unused")

package com.bedalton.creatures.caos.libs

import com.bedalton.creatures.caos.exceptions.CaosException
import com.bedalton.creatures.caos.libs.CaosVariant.UNKNOWN
import kotlinx.serialization.Serializable
import kotlin.js.JsExport
import kotlin.js.JsName

@JsExport
@Serializable
sealed class CaosVariant(open val code: String, open val fullName: String, open val index: Int) {

    @JsName("C1")
    object C1 : CaosVariant("C1", "Creatures 1", 1)

    @JsName("C2")
    object C2 : CaosVariant("C2", "Creatures 2", 2)

    @JsName("CV")
    object CV : CaosVariant("CV", "Creatures Village", 3)

    @JsName("C3")
    object C3 : CaosVariant("C3", "Creatures 3", 4)

    @JsName("DS")
    object DS : CaosVariant("DS", "Docking Station", 5)

    @JsName("SM")
    object SM : CaosVariant("SM", "Sea Monkeys", 6)

    @JsName("UNKNOWN")
    object UNKNOWN : CaosVariant("??", "Unknown", -1)

    companion object {
        private val others:MutableList<CaosVariant> = mutableListOf()
        fun fromVal(variant: String): CaosVariant {
            return when (variant) {
                "C1" -> C1
                "C2" -> C2
                "CV" -> CV
                "C3" -> C3
                "DS" -> DS
                "SM" -> SM
                else -> others.firstOrNull { it.code == variant } ?: UNKNOWN
            }
        }
    }


    @JsName("isOld")
    val isOld: Boolean
        get() {
            return this in VARIANT_OLD
        }

    @Deprecated("Use isNew",
        replaceWith = ReplaceWith("isNew")
    )
    @JsName("isNotOld")
    val isNotOld: Boolean
        get() {
            return this !in VARIANT_OLD
        }


    @JsName("isNew")
    val isNew: Boolean
        get() {
            return this !in VARIANT_OLD
        }


    override fun toString(): String {
        return code
    }


    @JsName("compareTo")
    operator fun compareTo(version: Int): Int {
        return when {
            index - version < 0 -> -1
            index - version > 0 -> 1
            else -> 0
        }
    }

    override fun equals(other: Any?): Boolean {
        if (this === other) return true
        if (other !is CaosVariant) return false

        if (code != other.code)
            return false

        return true
    }

    override fun hashCode(): Int {
        return code.hashCode()
    }
}

fun CaosVariant?.assertNotNullOrUnknown() {
    if (this == null) {
        throw CaosException("Variant is null")
    }
    if (this == UNKNOWN) {
        throw CaosException("Variant type if CaosVariant.UNKNOWN")
    }
}

fun CaosVariant?.orElse(variant: CaosVariant): CaosVariant {
    return if (this == null || this == UNKNOWN) {
        variant
    } else {
        this
    }
}

fun CaosVariant.nullIfUnknown(): CaosVariant? = if (this == UNKNOWN) null else this

val VARIANT_OLD = listOf(CaosVariant.C1, CaosVariant.C2)