package com.bedalton.creatures.common.util

import kotlin.js.Date
import kotlin.math.floor

/**
 * Parses a creatures
 * Parse data in 'HH:mm dd MMM yyyy' format
 */
actual fun creaturesDateToUnixTime(timestamp: String): Double? {
    val isoDate = creaturesDateToISO(timestamp)
        ?: return null
    return floor(Date.parse(isoDate).toLong() / 1000.0)
}
