import com.bedalton.common.coroutines.mapAsync
import com.bedalton.common.exceptions.IOException
import com.bedalton.common.structs.Pointer
import com.bedalton.common.util.PathUtil
import com.bedalton.common.util.ensureEndsWith
import com.bedalton.log.LOG_VERBOSE
import com.bedalton.log.Log
import com.bedalton.log.iIf
import com.bedalton.vfs.internal.LOG_COMMON_FILES_TESTING
import kotlinx.coroutines.Dispatchers

suspend fun globInFilesList(files: Collection<String>, path: String?, pattern: String): List<String> {
    // Format actual path using current working directory if path is null or not absolute
    val actualPath: String =
        getAbsoluteGlobPath(null, path?.expandTildeIfNecessary(), pattern.expandTildeIfNecessary())

    val searchedSoFar = Pointer(0)
    val (globRegex, minimalFiles) = getGlobRegexOrMinimalFiles(
        pattern,
        actualPath,
    ) { globPattern ->
        globMinimal(files, globPattern, searchedSoFar)
    }

    minimalFiles?.let {
        return it
    }
    // Get the children recursively
    val children = getChildrenIn(files, actualPath)
    return children.mapAsync { aPath ->
        globFilesRecursive(children, aPath, globRegex!!, searchedSoFar)
    }.flatten()
}


private suspend fun globFilesRecursive(
    files: Collection<String>,
    path: String,
    pattern: Regex,
    searchedSoFar: Pointer<Int>
): List<String> {
    searchedSoFar.value++
    if (searchedSoFar.value > MAX_GLOBBED_FILES) {
        throw IOException("Glob cannot handle so many files; Max: $MAX_GLOBBED_FILES")
    }
    Log.iIf(LOG_COMMON_FILES_TESTING) { "Globbing: $path" }

    // Get children in this path
    val children = getChildrenIn(files, path)

    return when {
        // Run on children
        children.isNotEmpty() -> children.mapAsync(BackgroundDispatcher) {
            globFilesRecursive(children, it, pattern, searchedSoFar)
        }.flatten()

        // Run on Files
        (pattern.matches(path) && isFile(children, path)) -> {
            Log.iIf(LOG_COMMON_FILES_TESTING) { "Path matches: $path; Pattern: ${pattern.pattern}" }
            listOf(path)
        }
        // NOt a match
        else -> {
            Log.iIf(LOG_COMMON_FILES_TESTING) { "No Match: Path: $path; Pattern: ${pattern.pattern}" }
            emptyList()
        }
    }
}


private fun getChildrenIn(files: Collection<String>, directory: String): List<String> {
    val pathSeparator = pathSeparator(directory)
    val directoryLower = directory.lowercase().ensureEndsWith(pathSeparator)
    return files.filter { it.lowercase().startsWith(directoryLower) }
}

private fun isDirectory(files: Collection<String>, path: String): Boolean {
    val pathSeparator = pathSeparator(path)
    val withTail = path.ensureEndsWith(pathSeparator).lowercase()
    return files.any { it.lowercase().startsWith(withTail) }
}

private fun isFile(files: Collection<String>, path: String): Boolean {
    val pathSeparator = pathSeparator(path)
    val withTail = path.ensureEndsWith(pathSeparator).lowercase()
    return files.none { it.lowercase().startsWith(withTail) }
}


private suspend fun globSimple(
    files: Collection<String>,
    path: String,
    pattern: Regex,
    remaining: String?,
    searchedSoFar: Pointer<Int>
): List<String> {
    searchedSoFar.value++
    if (searchedSoFar.value > MAX_GLOBBED_FILES) {
        throw IOException("Glob cannot handle so many files; Max: $MAX_GLOBBED_FILES")
    }
    Log.iIf(LOG_VERBOSE) { "Globbing: $path; Pattern: ${pattern.pattern}; With remaining: $remaining" }
    // Get matching children
    val subFiles = getChildrenIn(files, path)

    return when {
        subFiles.isNotEmpty() -> {
            globSimpleChildren(
                files = files,
                path = path,
                pattern = pattern,
                remaining = remaining,
                searchedSoFar = searchedSoFar
            )
        }

        (pattern.matches(path) && !isDirectory(files, path)) -> {
            Log.iIf(LOG_COMMON_FILES_TESTING) { "Path matches: $path; Pattern: ${pattern.pattern}" }
            listOf(path)
        }

        else -> {
            Log.iIf(LOG_COMMON_FILES_TESTING) { "No Match: Path: $path; Pattern: ${pattern.pattern}" }
            emptyList()
        }
    }
}

private suspend fun globSimpleChildren(
    files: Collection<String>,
    path: String,
    pattern: Regex,
    remaining: String?,
    searchedSoFar: Pointer<Int>
): List<String> {
    val others = if (remaining != null) {
        Log.iIf(LOG_COMMON_FILES_TESTING) { "Globbing Child directory: $path" }
        val split = remaining.split(wildcardsRegex, limit = 2)
        Log.iIf(LOG_COMMON_FILES_TESTING) { "Glob Split: [${split.joinToString()}]" }
        if (split.size == 1) {
            files.filter {
                pattern.matches(it)
            }
        } else {
            val nextDirectory = PathUtil.combine(path, split[0])
            globSimple(files, nextDirectory, pattern, split[1], searchedSoFar)
        }
    } else {
        emptyList()
    }
    return if (path.matches(pattern) && !isDirectory(files, path)) {
        others + path
    } else {
        others
    }
}

private suspend fun globMinimal(files: Collection<String>, pattern: String, searchedSoFar: Pointer<Int>): List<String> {

    if (pattern.matches("^[^*]*[\\\\/]\\*$".toRegex())) {
        Log.iIf(LOG_COMMON_FILES_TESTING) { "Globing simple $pattern" }
        val directory = pattern.substringBefore('*')
        return getChildrenIn(files, directory).filter { isFile(files, it) }
    }

    // Create the regex to test all paths against
    val globRegex = globToRegex(pattern, true, setOf(RegexOption.IGNORE_CASE))

    getLastMatchesOrNull(
        files,
        pattern,
        globRegex
    )?.let {
        return it
    }

    // Split this path on the first glob pattern component
    val split = pattern.split(wildcardsRegex, limit = 2)

    // Glob children in path before wildcard, and search within those children
    Log.iIf(LOG_COMMON_FILES_TESTING) { "Globbing files parent: ${split[0]}; Remainder: ${split[1]} " }
    val path = split[0]
    val remainder = split[1]
    val children = getChildrenIn(files, split[0])
    return children.mapAsync(Dispatchers.Unconfined) { childPath ->
        globMinimalChildren(
            files,
            path,
            childPath,
            globRegex,
            remainder,
            searchedSoFar
        )
    }.flatten()
}

private fun getLastMatchesOrNull(
    files: Collection<String>,
    pattern: String,
    globRegex: Regex,
): List<String>? {
    // Check if variable path component is only at the end
    val lastMatch = "^([^*]*[\\\\/])(([^\\\\/]|\\\\[\\[\\]\$^.])*[*]([^\\\\/]|\\\\[\\[\\]\$^.])*)\$".toRegex()
    val matchesLast = lastMatch.matchEntire(pattern)
        ?.groupValues
        ?.drop(1)
        ?: return null

    // The glob variable is only at the end, so we can search ver simply
    Log.iIf(LOG_COMMON_FILES_TESTING) { "Glob pattern only in last path component: ${pattern}; Searching in: ${matchesLast[0]}" }
    val children = getChildrenIn(files, matchesLast[0])
    return children
        .filter {
            Log.iIf(LOG_COMMON_FILES_TESTING) { "Does glob match <$it>? ${globRegex.matches(it)}" }
            globRegex.matches(it) && isFile(children, it)
        }

}

private suspend fun globMinimalChildren(
    files: Collection<String>,
    path: String,
    childPath: String,
    globRegex: Regex,
    remainder: String?,
    searchedSoFar: Pointer<Int>
): List<String> {
    Log.iIf(LOG_COMMON_FILES_TESTING) { "Globbing single layer: ${path}; Child: $childPath" }
    // If child is a directory, search its children
    val subChildren = getChildrenIn(files, childPath)
    return if (subChildren.isNotEmpty()) {
        Log.iIf(LOG_COMMON_FILES_TESTING) { "Globbing child's children as this should be '*'; Child: $childPath" }
        getChildrenIn(subChildren, childPath).mapAsync {
            globSimple(subChildren, it, globRegex, remainder, searchedSoFar)
        }.flatten()

    } else if (globRegex.matches(childPath)) { // check if child file matches regex
        listOf(childPath)
    } else {
        emptyList()//globSimple(fileSystem, split[0], globRegex, split[1], searchedSoFar)
    }
}