package com.bedalton.creatures.agents.pray.compiler.internal

import com.bedalton.creatures.agents.pray.compiler.data.InlineFile

fun Collection<InlineFile>.unique(): List<InlineFile> {
    return distinctBy { it.outputFileName.text.lowercase() }
}

fun Collection<InlineFile>.toUniqueArray(): Array<InlineFile> {
    return distinctBy { it.outputFileName.text.lowercase() }.toTypedArray()
}

fun Array<InlineFile>.unique(): Array<InlineFile> {
    return distinctBy { it.outputFileName.text.lowercase() }.toTypedArray()
}