@file:Suppress("unused")

package com.bedalton.creatures.breed.render.files

import com.bedalton.common.util.like
import com.bedalton.common.util.normalized
import com.bedalton.common.util.nullIfEmpty
import com.bedalton.creatures.breed.render.support.pose.PoseRenderException
import com.bedalton.creatures.common.structs.GameVariant
import com.bedalton.creatures.common.structs.isC3DS
import com.bedalton.creatures.sprite.util.PaletteTransform


/**
 * Holds all breed files pertaining to a single part
 */
data class BreedPartFiles(
    val gameVariant: GameVariant,
    val part: Char,
    val files: List<BreedFileData>,
    val spriteRoot: String? = null,
    val attRoot: String? = null,
    val paletteTransform: PaletteTransform? = null,
    val closeMatchOnly: Boolean? = null,
) {

    private var mAllAttFiles: List<BreedFileData>? = null
    private var mAllSpriteFiles: List<BreedFileData>? = null

    // Filter files to just ATTs
    private val allAtts
        get() = mAllAttFiles ?: files.filter { it.extension like "att" }.also {
            mAllAttFiles = it
        }

    // Filter files to just variant breed sprites
    private val allSprites: List<BreedFileData>
        get() = mAllSpriteFiles ?: BreedFileUtil.variantSprites(gameVariant, files)
            .also { mAllSpriteFiles = it }

    // Get scoped body part files
    private var mInAnyRoot: List<BodyPartFiles>? = null
    private var mInRoot: List<BodyPartFiles>? = null

    val inAnyRoot: List<BodyPartFiles>
        get() = mInAnyRoot ?: getInAnyRootBodyPartFiles().also {
            mInAnyRoot = it
        }

    val inRoot: List<BodyPartFiles>
        get() = mInRoot ?: getInRootBodyPartFiles().also {
            mInRoot = it
        }

    fun isEmpty(): Boolean = files.isEmpty()

    private fun getInAnyRootBodyPartFiles(): List<BodyPartFiles> {
        return join(
            allSprites,
            allAtts
        )
    }

    private fun getInRootBodyPartFiles(): List<BodyPartFiles> {
        if (spriteRoot.isNullOrBlank() && attRoot.isNullOrBlank()) {
            return emptyList()
        }

        val attsInRoot = inRoot(attRoot, allAtts)
        val spritesInRoots = inRoot(spriteRoot, allSprites)

        val sameAtts = attsInRoot.size == allAtts.size
        val sameSprites = spritesInRoots.size == allSprites.size
        if (sameAtts && sameSprites) {
            // All ATTs and Sprites are already in root
            // So they will have been checked in the `onAnyRoots` calls
            return emptyList()
        }
        return join(
            spritesInRoots,
            attsInRoot
        )
    }

    private fun inRoot(root: String?, files: List<BreedFileData>): List<BreedFileData> {
        if (root == null) {
            return files
        }

        val rootNormalized = root.normalized()
        return files.filter { it.path.normalized().startsWith(rootNormalized) }
    }

    private fun join(
        spritesInRoots: List<BreedFileData>,
        attsInRoot: List<BreedFileData>,
    ): List<BodyPartFiles> {
        return spritesInRoots.mapNotNull { spriteFile ->
            BreedFileUtil.getData(
                gameVariant = gameVariant,
                part = spriteFile.part,
                spriteFile = spriteFile,
                bodyData = attsInRoot,
                attRoot = null,
                paletteTransform = paletteTransform,
                closeMatchOnly = closeMatchOnly
            )
        }.filter {
            it.attFile != null
        }
    }

    internal fun withPaletteTransform(
        paletteTransform: PaletteTransform?,
    ): BreedPartFiles {
        val parent = this
        return copy(
            paletteTransform = paletteTransform
        ).apply {
            this.mInRoot = parent.mInRoot?.map {
                it.copy(
                    paletteTransform = paletteTransform
                )
            }
            this.mInAnyRoot = parent.mInAnyRoot?.map {
                it.copy(
                    paletteTransform = paletteTransform
                )
            }
            this.mAllAttFiles = parent.mAllAttFiles
            this.mAllSpriteFiles = parent.mAllSpriteFiles
        }
    }

    internal fun withAttRoot(
        attRoot: String?,
    ): BreedPartFiles {
        return withRoots(
            spriteRoot = this.spriteRoot,
            attRoot = attRoot
        )
    }

    internal fun withSpriteRoot(
        spriteRoot: String?,
    ): BreedPartFiles {
        return withRoots(
            spriteRoot = spriteRoot,
            attRoot = this.attRoot
        )
    }

    @Suppress("MemberVisibilityCanBePrivate")
    internal fun withRoots(
        spriteRoot: String? = this.spriteRoot,
        attRoot: String? = this.attRoot,
    ): BreedPartFiles {
        val parent = this
        return copy(
            attRoot = attRoot,
            spriteRoot = spriteRoot
        ).apply {
            this.mInAnyRoot = parent.mInAnyRoot
            this.mAllAttFiles = parent.mAllAttFiles
            this.mAllSpriteFiles = parent.mAllSpriteFiles
        }
    }

    operator fun plus(other: BreedPartFiles?): BreedPartFiles {
        if (other == null) {
            return this.copy()
        }

        if (other.gameVariant != this.gameVariant) {
            if (!other.gameVariant.isC3DS || !this.gameVariant.isC3DS) {
                throw PoseRenderException("Cannot combine breed files with dissimilar game variants; This: <${this.gameVariant}>; Other: <${other.gameVariant}>")
            }
        }

        if (this.part != other.part) {
            throw PoseRenderException("Cannot combine disparate parts; This: <${this.part}>; Other: <${other.part}>")
        }

        val files = (this.files + other.files)
            .distinct()

        val out = BreedPartFiles(
            gameVariant = gameVariant,
            part = part,
            files = files,
            spriteRoot = other.spriteRoot ?: this.spriteRoot,
            attRoot = other.attRoot ?: this.attRoot,
            paletteTransform = other.paletteTransform ?: this.paletteTransform,
            closeMatchOnly
        )
        val thisInAnyRoot = this.inAnyRoot
        val otherInAnyRoot = other.inAnyRoot

        out.mInAnyRoot = (thisInAnyRoot + otherInAnyRoot).distinct()

        out.mAllAttFiles = (this.mAllAttFiles.orEmpty() + other.mAllAttFiles.orEmpty())
            .distinct()
            .nullIfEmpty()

        out.mAllSpriteFiles = (this.mAllSpriteFiles.orEmpty() + other.mAllSpriteFiles.orEmpty())
            .distinct()
            .nullIfEmpty()

        val sharedAttRoot = this.attRoot == null || this.attRoot == other.attRoot
        val sharedSpriteRoot = this.attRoot == null || this.spriteRoot == other.spriteRoot

        if (sharedAttRoot && sharedSpriteRoot) {
            val thisInRoot = this.inRoot
            val otherInRoot = other.inRoot
            out.mInRoot = (thisInRoot + otherInRoot)
                .distinct()
        }
        return out
    }

}


internal fun BodyPartFiles.filenamesToString(): String {
    val spriteFilename = spriteFile.filename
    val attFilename = attFile?.filename?.lowercase()
        ?: return spriteFilename
    return "[Sprite=$spriteFilename, ATT=$attFilename]"
}