package com.creaturesforge.application.compile

import com.bedalton.common.util.nullIfEmpty
import com.creaturesforge.application.state.*
import com.creaturesforge.application.util.getBreedFilesForSlot

internal data class CompileData(
    val projectFolder: String,
    val breedSlot: BreedSlot,
    val eggs: List<EggData>,
    val genomeGenus: Int,
    val maleGlyph: Glyph?,
    val femaleGlyph: Glyph?,
    val outputFile: String,
    val spriteFiles: List<Pair<String, String>>,
    val attFiles: List<Pair<String, String>>,
) {

    companion object {


        private val ALL_PARTS = "ABCDEFGHIJKLMN".toCharArray().toList()

        fun create(stateIn: ForgeState, glyphsNotNull: Boolean, outputFile: String): CompileData {

            val state = if (stateIn.eggMode == EggMode.SINGLE && stateIn.eggs.size > 1) {
                stateIn.copy(eggs = listOf(stateIn.selectedEgg))
            } else {
                stateIn
            }

            val missing = StateValidator.getMissing(state, glyphsNotNull)

            if (missing.isNotEmpty()) {
                throw MissingCompileParametersException(
                    missing,
                    "Cannot build compiler data. Missing fields: $missing"
                )
            }

            assertUniqueEggNames(state)

            assertUniqueGenomeNames(state)

            val outputBreedSlot = state.outputBreedSlot

            val attFiles = getBreedFilesForSlot(
                state.eggMode,
                state.attFiles,
                "att",
                state.attBreedSlot,
                state.outputBreedSlot
            ).orEmpty()

            val spriteFiles = getBreedFilesForSlot(
                state.eggMode,
                state.spriteFiles,
                "c16",
                state.spriteBreedSlot,
                state.outputBreedSlot
            ) ?: throw MissingCompileParametersException(
                    listOf("Sprites matching slot"),
                    "Cannot build compiler data. Missing fields: Sprite files matching slot"
                )

            return CompileData(
                projectFolder = state.projectFolder!!,
                breedSlot = outputBreedSlot ?: throw NullPointerException("Output breed slot cannot be null (in CompileData)"),
                eggs = if (state.eggMode == EggMode.SINGLE) {
                    listOf(state.selectedEgg)
                } else {
                    state.eggs
                },
                genomeGenus = state.genomeGenus,
                maleGlyph = state.maleGlyph,
                femaleGlyph = state.femaleGlyph,
                outputFile = outputFile,
                spriteFiles = spriteFiles,
                attFiles = attFiles
            )
        }

        private fun assertUniqueEggNames(state: ForgeState) {
            val eggNames = state.eggs.map { it.eggName }
            val conflicting = eggNames
                .filter { name ->
                    eggNames.count { name == it } > 1
                }
                .distinct()
                .nullIfEmpty()
                ?: return

            if (conflicting.size == 1) {
                throw DuplicateCompileValuesException("Duplicate egg name ${conflicting[0]}")
            } else {
                throw DuplicateCompileValuesException("Duplicate egg names $conflicting")
            }
        }

        private fun assertUniqueGenomeNames(state: ForgeState) {
            val eggs = state.eggs
            val allGenomes = eggs.flatMap {
                listOfNotNull(
                    it.baseGenomeFile,
                    it.motherGenomeFile,
                    it.fatherGenomeFile
                )
            }.distinct()

            val genomeFileNames = allGenomes.map { it.filename }
                .distinctBy { it.lowercase() }

            val duplicateNameErrors = mutableListOf<String>()

            for (fileName in genomeFileNames) {
                val fileNameLowercase = fileName.lowercase()

                val genomes = allGenomes.filter {
                    it.filename.lowercase() == fileNameLowercase
                }.distinct()

                val filePaths = genomes.map { it.filepath.lowercase() }
                    .distinct()
                val eggGenomeNames = eggs.map { egg ->
                    val fileNames = listOfNotNull(
                        egg.baseGenomeFile?.filename?.lowercase(),
                        egg.fatherGenomeFile?.filename?.lowercase(),
                        egg.motherGenomeFile?.filename?.lowercase()
                    )
                    egg to fileNames
                }

                if (filePaths.size > 1) {
                    val conflictingEggs =
                        eggGenomeNames.filter { fileNameLowercase in it.second }.map { it.first.eggName }
                    val error = fileName + " is defined in: " + conflictingEggs.joinToString("\n\t\t- ", "\n\t\t- ")
                    duplicateNameErrors.add(error)
                }
            }
            if (duplicateNameErrors.isNotEmpty()) {
                val formatted = duplicateNameErrors.joinToString("\n\t- ", "\n\t- ")
                throw DuplicateCompileValuesException("Conflicting genome filenames:$formatted")
            }
        }
    }


    data class AgeGenderStats(
        val gender: Int,
        val age: Int,
        val sprites: List<Char>,
        val atts: List<Char>,
        val shared: List<Char>?,
    ) {
        val missingAtts by lazy {
            val upper = atts.map { it.uppercaseChar() }
            ALL_PARTS.filter { it !in upper }.sorted()
        }
        val missingSprites by lazy {
            val upper = sprites.map { it.uppercaseChar() }
            ALL_PARTS.filter { it !in upper }.sorted()
        }
    }
}
