package com.bedalton.creatures.breed.render.support.pose

/**
 * Constant values for various Pose values
 * Used in situations where enums may not be available
 */
object PoseConstants {
    object Facing {
        const val BACK = 0
        const val FRONT = 1
        const val VIEWER_RIGHT = 2
        const val VIEWER_LEFT = 3
    }

    object Tilt {
        // DOWN
        const val DOWN = 0
        val DOWN_CHAR = DOWN.digitToChar()

        // STRAIGHT
        const val STRAIGHT = 1
        val STRAIGHT_CHAR = STRAIGHT.digitToChar()

        // UP
        const val UP = 2
        val UP_CHAR = UP.digitToChar()

        // FAR_UP
        const val FAR_UP = 3
        val FAR_UP_CHAR = FAR_UP.digitToChar()

        // NO_CHANGE
        val NO_CHANGE: Int? = null
        const val NO_CHANGE_CHAR = 'X'
    }

    object LeftRight {
        const val LEFT = 0
        const val RIGHT = 1
    }

    object EarsIndex {
        const val EARS_NORMAL = 0
        const val EARS_DROOPY = 1
        const val EARS_ANGRY = 2
        const val EARS_PRICKED = 3
    }

    object Mood {
        const val NORMAL = 0
        const val HAPPY = 1
        const val SAD = 2
        const val ANGRY = 3
        const val SCARED = 4
        const val SLEEPY = 5

        object CV {
            const val VERY_SLEEPY = 6
            const val VERY_HAPPY = 7
            const val MISCHIEVOUS = 8
            const val VERY_SCARED = 9
            const val ILL = 10
            const val HUNGRY = 11
        }
    }

    fun partName(part: Char): String? {
        return partNames[part]
    }


    val partNames by lazy {
        mapOf(
            'a' to "Head",
            'b' to "Body",
            'c' to "Left Thigh",
            'd' to "Left Shin",
            'e' to "Left Foot",
            'f' to "Right Thigh",
            'g' to "Right Shin",
            'h' to "Right Foot",
            'i' to "Left Upper Arm",
            'j' to "Left Forearm",
            'k' to "Right Upper Arm",
            'l' to "Right Lower Arm",
            'm' to "Tail Base",
            'n' to "Tail Tip",
            'o' to "Left Ear",
            'p' to "Right Ear",
            'q' to "Hair"
        )
    }
}
