package com.bedalton.creatures.sprite.util

import korlibs.image.bitmap.Bitmap32
import korlibs.image.color.RGBA


fun List<RGBA>.average(): RGBA {
    val count = size
    if (count == 0) {
        throw Exception("Cannot average empty color array")
    }
    var r = 0
    var g = 0
    var b = 0
    forEach {
        r += it.r
        g += it.g
        b += it.b
    }
    return RGBA(r / count, g / count, g / count, 255)
}

fun Bitmap32.getSafe(x: Int, y: Int): RGBA? {
    if (x in 0 until width) {
        if (y in 0 until height) {
            return get(x, y)
        }
    }
    return null
}


inline fun Bitmap32.each(callback: (x: Int, y: Int) -> Unit) {
    repeat(height) { y ->
        repeat(width) { x ->
            callback(x, y)
        }
    }
}

inline fun Bitmap32.transformCopy(callback: (x: Int, y: Int, rgba: RGBA) -> RGBA): Bitmap32 {
    val out = Bitmap32(width, height, true)
    repeat(height) { y ->
        repeat(width) { x ->
            out[x, y] = callback(x, y, get(x, y))
        }
    }
    return out
}



internal fun RGBA.isPureBlack(): Boolean {
    return r == 0 && g == 0 && b == 0
}