@file:Suppress("unused")

package com.creaturesforge.application.state

import com.bedalton.common.util.PathUtil
import com.bedalton.common.util.className
import com.bedalton.creatures.genetics.gene.AppearanceGene
import com.bedalton.creatures.genetics.gene.GenusGene
import com.bedalton.creatures.genetics.genome.Genome
import com.bedalton.creatures.genetics.genome.GenomeCompiler
import com.bedalton.creatures.genetics.parser.GenomeParser
import com.bedalton.log.LOG_DEBUG
import com.bedalton.log.Log
import com.bedalton.log.iIf
import com.bedalton.vfs.FileSystem
import com.bedalton.common.exceptions.rethrowCancellationException
import kotlinx.serialization.Serializable
import kotlinx.serialization.Transient

@Serializable
internal data class GenomeFile(
    val filename: String,
    val filepath: String
) {
    @Transient
    private var originalGenome: Genome? = null
    private var slot: BreedSlot? = null
    @Transient
    private var genomeForSlot: ByteArray? = null


    suspend fun fileExists(fs: FileSystem): Boolean {
        if (filepath.startsWith("resource:")) {
            return true
        }
        return fs.fileExists(filepath)
    }

    suspend fun gnoFile(fs: FileSystem): ByteArray? {
        val folder = PathUtil.getWithoutLastPathComponent(filepath)
            ?: return null
        val filenameWithoutExtension = PathUtil.getFileNameWithoutExtension(filepath)
            ?: return null
        val path = PathUtil.combine(folder, "$filenameWithoutExtension.gno")
        if (!addGnoSafe(path)) {
            return null
        }
        return try {
            if (fs.fileExists(path)) {
                fs.read(path)
            } else {
                null
            }
        } catch (e: Exception) {
            e.rethrowCancellationException()
            Log.iIf(LOG_DEBUG) {
                "Failed to read GNO file; ${e.className}${e.message?.let { ": $it"} ?: ""}\n${e.stackTraceToString()}"
            }
            null
        } catch (e: Error) {
            e.rethrowCancellationException()
            Log.iIf(LOG_DEBUG) {
                "Failed to read GNO file; ${e.className}${e.message?.let { ": $it"} ?: ""}\n${e.stackTraceToString()}"
            }
            null
        } catch (e: Throwable) {
            e.rethrowCancellationException()
            Log.iIf(LOG_DEBUG) {
                "Failed to read GNO file; ${e.className}${e.message?.let { ": $it"} ?: ""}\n${e.stackTraceToString()}"
            }
            null
        }
    }

    suspend fun getGenomeForSlot(fs: FileSystem, genomeGenus: Int, slot: BreedSlot): ByteArray {
        genomeForSlot?.let {
            if (this.slot == slot) {
                return it
            }
        }
        var originalGenome = originalGenome
        if (originalGenome == null) {
            val bytes = try {
                fs.read(filepath)
            } catch (e: Exception) {
                e.rethrowCancellationException()
                throw Exception("Failed to read genome bytes; ${e.className}${e.message?.let { ": $it" } ?: ""}",
                    e)
            }
            originalGenome = GenomeParser.parseGenome(bytes, true).also {
                this.originalGenome = it
            }
        }

        var appearanceGenus = slot.genus
        if (appearanceGenus >= 4) {
            appearanceGenus -= 4
        }
        val breed = slot.breed.lowercaseChar()
        if (breed !in 'a'..'z') {
            throw Exception("Invalid breed char; Expected value a..z; Found: $breed")
        }
        val genes = originalGenome.map {
            when (it) {
                is GenusGene -> it.copy(genus = genomeGenus)

                is AppearanceGene -> it.copy(
                    genus = appearanceGenus,
                    breed = breed
                )

                else -> it
            }
        }
        val genome = Genome(
            version = 3,
            genes = genes.toTypedArray()
        )

        this.slot = slot
        val out = try {
            GenomeCompiler.compile(genome)
        } catch (e: Exception) {
            e.rethrowCancellationException()
            throw Exception("Failed to compile genome with new breed slot; ${e.className}${e.message?.let { ": $it" } ?: ""}")
        }
        this.genomeForSlot = out
        return out
    }

}