package com.creaturesforge.application.ui.controls

import com.bedalton.common.coroutines.launchBackground
import com.bedalton.common.coroutines.launchMain
import com.bedalton.common.util.*
import com.bedalton.creatures.sprite.util.bytesToImage
import com.bedalton.io.bytes.toDataUri
import com.bedalton.log.*
import com.bedalton.state.simple.Dispatch
import com.creaturesforge.application.state.*
import com.creaturesforge.application.ui.fileOf
import com.creaturesforge.application.ui.openSingle
import com.creaturesforge.application.util.jsOb
import com.bedalton.common.exceptions.rethrowCancellationException
import com.creaturesforge.application.interop.writeAgentFilesToCache
import korlibs.image.format.PNG
import kotlinx.browser.window
import kotlinx.coroutines.await
import org.w3c.dom.HTMLButtonElement
import org.w3c.dom.HTMLElement
import org.w3c.dom.HTMLImageElement
import org.w3c.dom.HTMLInputElement
import org.w3c.dom.events.Event
import org.w3c.dom.events.MouseEvent
import tauri.os.platform


internal class GlyphSelect(
    root: HTMLElement,
): Validatable {

    private lateinit var placeholder: String

    private var projectRoot: String? = null

    private var events = true

    private var isAuto: Boolean = true

    private lateinit var state: ForgeState

    private val gender = root
        .getAttribute("data-glyph-gender")
        ?.capitalize()
        ?: throw Exception("Glyph gender attribute is null")


    private val male = (gender.lowercase() == "male")

    private val previewContainer = (root.querySelector(".glyph-preview-container") as HTMLElement).apply {
        addEventListener("click", {
            if (events) {
                button.click()
            }
        })
    }

    private val agentFilesButton = (root.querySelector(".glyph-agent-files-button") as HTMLElement).apply {
        addEventListener("click", { e: Event ->
            e.stopPropagation()
            e.stopImmediatePropagation()
            if (events) {
                selectAgentImage(e)
            }
        })
    }

    private val thumbnailImage: HTMLImageElement = (previewContainer.querySelector("img.placeholder") as HTMLImageElement).apply {
        style.setProperty("pointer-events", "none")
        addEventListener("error", {
            showPlaceholder()
        })
    }

    private val nameInput: HTMLInputElement = (root.querySelector("input[type='text']") as HTMLInputElement).apply {
        placeholder = this.getAttribute("placeholder") ?: "Output glyph name"
        onblur = {
            if (this.value.isBlank()) {
                this.value = ""
            }
            Unit
        }
    }
    private val frameInput: HTMLInputElement = (root.querySelector("input[type='number']") as HTMLInputElement).apply {
        oninput = {
            if (events) {
                onFrameChange()
            }
        }
    }

    private val button: HTMLButtonElement = (root.querySelector("button") as HTMLButtonElement)

    private lateinit var dispatch: Dispatch<FAction>
    private var mValue: Glyph? = null
    private var updateTimeout = -1

    init {
        if (gender.lowercase() != "male" && gender.lowercase() != "female") {
            throw Exception("Glyph gender attribute is invalid; Expected Male or Female; Actual: $gender")
        }
        ForgeStore.subscribe { state, dispatch ->
            this.state = state
            this.projectRoot = state.projectFolder
            this.dispatch = dispatch
            window.clearTimeout(updateTimeout)
            val currentEvents = events
            events = false
            val thisGlyph = if (male) state.maleGlyph else state.femaleGlyph
            events = currentEvents || events
            Log.i { "GlyphSelect fields on State Update: $thisGlyph" }
            updateTimeout = window.setTimeout({
                onGlyph(thisGlyph)
            }, 1)
            agentFilesButton.hidden = !state.virtual
        }
    }

    private fun initImage(glyph: Glyph?) {
        if (mValue == null) {
            Log.iIf(LOG_DEBUG) { "Previous ${gender.capitalize()} Glyph value is null; New Glyph: $glyph" }
        }
        if (this.mValue == glyph) {
            Log.iIf(LOG_VERBOSE) { "${gender.capitalize()} Glyph is the same" }
            return
        }
        mValue = glyph

        Log.i { "Initializing glyph" }
        launchBackground(capture = true) async@{
            try {
                initImageAsync(glyph)
            } catch (e: Throwable) {
                Log.e("Failed to init glyph; ${e.formatted(true)}")
            }
        }
    }

    private suspend fun initImageAsync(
        glyph: Glyph?
    ) {

        Log.i { "Glyph: initImageAsync" }
        this@GlyphSelect.events = false
        if (glyph is SpriteGlyph) {
            Log.i { "Is glyph sprite" }
            initFrameInput(glyph)
        } else {
            Log.i { "Is not glyph sprite" }
            frameInput.disabled = true
        }
        this@GlyphSelect.events = true

        val bitmap32 = when (glyph) {
            is SpriteGlyph -> glyph.getBitmap32()
            is BitmapGlyph -> glyph.getBitmap32()
            else -> null
        }
        if (bitmap32 == null) {
            Log.i { "Bitmap is null for Glyph: $glyph" }
            showPlaceholder()
            return
        }
        val dataURI = PNG.encode(bitmap32)
            .toDataUri("image/png")

        thumbnailImage.src = dataURI
        thumbnailImage.classList.remove("placeholder")
    }

    private fun showPlaceholder() {
        thumbnailImage.src = DEFAULT_IMAGE_URL
        thumbnailImage.classList.add("placeholder")
        this.nameInput.value = ""
    }

    init {
        nameInput.onkeyup = change@{ e ->
            val key = e.key.lowercase()
            if (key == "enter") {
                updateGlyphName()
            }
        }

        nameInput.onblur = {
            updateGlyphName()
        }
        button.addEventListener("click", { e ->
            Log.i("Selecting image")
            selectImage(e)
        })
    }

    private fun updateGlyphName() {
        events = false
        val newValue = nameInput.value
        if (newValue == mValue?.filename) {
            return
        }
        val newGlyph = mValue?.withName(newValue)
        if (newGlyph != mValue) {
            mValue = newGlyph
        }
        events = true
    }

    private suspend fun initFrameInput(newGlyph: SpriteGlyph) {
        if (frameInput.value.toIntOrNull() == newGlyph.frame && frameInput.max.isNotNullOrBlank()) {
            return
        }
        val max = newGlyph.frames.getData()?.size?.let { it - 1 }
        if (max == null) {
            frameInput.disabled = true
            frameInput.value = ""
            return
        }
        frameInput.disabled = false
        frameInput.min = "0"
        frameInput.max = "$max"
        if (newGlyph.frame !in 0..max) {
            frameInput.value = maxOf(10, max).toString()
        }
    }

    private fun selectImage(@Suppress("UNUSED_PARAMETER") e: Event?) {
        launchMain(capture = true) launch@{
            try {
                selectImageAsync()
            } catch (e: Exception) {
                Log.e("GlyphSelect::SelectImage->selectImageAsync() failed ${e.formatted(true)}")
            }
        }
    }


    private fun selectAgentImage(@Suppress("UNUSED_PARAMETER") e: Event?) {
        launchMain(capture = true) launch@{
            try {
                selectImageAsync(state.virtual)
            } catch (e: Exception) {
                Log.e("GlyphSelect::SelectImage->selectImageAsync() failed ${e.formatted(true)}")
            }
        }
    }

    private suspend fun selectImageAsync(agent: Boolean = false) {

        val defaultDirectory = defaultOpenDirectory(agent)

        val result = openSingle {
            this.title = "Select $gender Glyph"
            this.multiple = false
            this.defaultPath = defaultDirectory
            this.filters = arrayOf(
                jsOb {
                    this.name = "Images"
                    this.extensions = arrayOf(
                        "png",
                        "bmp",
                    )
                },
                jsOb {
                    this.name = "Sprites"
                    this.extensions = arrayOf(
                        "spr",
                        "s16",
                        "c16"
                    )
                }
            )
        } ?: return

        val file = fileOf(result)
            ?: return

        addFile(file)

        // Set Last directory
        val lastDirectory = PathUtil.getWithoutLastPathComponent(file)
            ?: file
        lastGlyphDirectory = lastDirectory
        ForgeConfig.setLastGlyphDirectory(projectRoot, lastDirectory)

        if (PathUtil.getExtension(file)?.lowercase() in listOf("spr", "s16", "c16")) {
            setSpriteGlyph(file)
        } else {
            setImageGlyph(file)
        }
    }

    private fun setSpriteGlyph(file: String) {
        val newGlyph = SpriteGlyph.create(
            filename = nameInput.value,
            frame = frameInput.value.toIntOrNull() ?: 9,
            sourceSprite = file,
            manual = true
        )
        dispatchGlyphChange(newGlyph)
        if (frameInput.value.nullIfEmpty().isNullOrBlank()) {
            frameInput.value = newGlyph.frame.toString()
        }
        frameInput.disabled = false
    }

    private suspend fun setImageGlyph(file: String) {
        val image = try {
            val bytes = vfs.read(file)
            bytesToImage(bytes)
        } catch (e: Exception) {
            e.rethrowCancellationException()
            Log.e { "Failed to load image at $file; ${e.className}:${e.message}\n${e.stackTraceToString()}" }
            return
        }
        events = false
        dispatchGlyphChange(
            BitmapGlyph(
                filename = nameInput.value,
                bitmap32 = image,
                manual = true
            )
        )
        frameInput.value = ""
        frameInput.disabled = true
        events = true
    }

    private fun dispatchGlyphChange(value: Glyph?) {
        if (mValue == value) {
            Log.i { "Glyph is unchanged for dispatch" }
            return
        }
        val oldEvents = events
        events = false
        dispatch(SetGlyphAction(male, value))
        try {
            initImage(value)
        } catch (e: Throwable) {
            Log.e("Failed to init image in dispatch glyph change")
        } finally {
            events = oldEvents || events
        }
    }

    private fun onFrameChange() {
        val value = mValue
            ?: return
        if (value !is SpriteGlyph) {
            return
        }
        val frame = frameInput.value
            .nullIfEmpty()
            ?.toIntOrNull()
        if (frame != null) {
            val updated = value.copy(frame = frame)
            dispatchGlyphChange(updated)
        }
    }

    private fun onGlyph(glyph: Glyph?) {
        if (glyph == null) {
            showPlaceholder()
            return
        }
        initImage(glyph)
        if (glyph.filename.startsWith(':')) {
            this.isAuto = true
            this.nameInput.setAttribute("placeholder", "auto: " + glyph.filename.substring(1))
        } else {
            if (this::placeholder.isInitialized) {
                this.nameInput.setAttribute("placeholder", placeholder)
            }
            this.isAuto = false
            if (this.nameInput.value != glyph.filename) {
                this.nameInput.value = glyph.filename
            }
        }
    }

    private suspend fun defaultOpenDirectory(agent: Boolean): String? {
        val projectRoot = projectRoot ?: state.projectFolder
        if (agent && projectRoot != null) {
            val vfs = vfs
            val files = vfs.getVirtualFileList()
            if (files.any { it.lowercase().endsWith(".c16") }) {
                val agentFiles = files.mapNotNull {
                    try {
                        val bytes = vfs.read(it)
                        it to bytes
                    } catch (_: dynamic) {
                        null
                    }
                }.toMap()
                writeAgentFilesToCache(projectRoot, agentFiles)?.let {
                    return it
                }
            }
        }
        return lastGlyphDirectory
            ?: ForgeConfig.getLastGlyphDirectory(projectRoot)
            ?: if (platform().await() == "linux") {
                "~/"
            } else {
                null
            }
    }

    override fun highlightErrors() {
        if (isValid()) {
            return
        }
        previewContainer.closest(".validatable-input-container")?.setAttribute("data-is-value", "false")
    }

    override fun isValid(): Boolean {
        return mValue != null
    }

    companion object {
        private var lastGlyphDirectory: String? = null
        private const val DEFAULT_IMAGE_URL = "./src/images/icons/folder_open.svg"
    }
}
