package com.creaturesforge.application.ui.pages

import com.creaturesforge.application.ui.html.body
import com.creaturesforge.application.ui.html.dataInt
import kotlinx.browser.window
import org.w3c.dom.HTMLElement

internal object PageButtons {

    private var currentPage by body.dataInt("current-page")

    fun init() {
        window.addEventListener("click", { e ->
            val pageButton = e.target.unsafeCast<HTMLElement>().closest(".page-button")
                ?: return@addEventListener
            val page = pageButton.getAttribute("data-for-page")?.toIntOrNull()
                ?: return@addEventListener
            Pages.validate(currentPage)
            currentPage = page
        })
    }
}