@file:Suppress("unused")

package com.bedalton.common.ast.collectors

import com.bedalton.common.ast.structs.PositionImpl
import com.bedalton.common.ast.structs.RangeWithIndex
import com.bedalton.common.ast.structs.RangeWithIndexImpl
import org.antlr.v4.kotlinruntime.ParserRuleContext
import org.antlr.v4.kotlinruntime.Token
import org.antlr.v4.kotlinruntime.misc.Interval
import kotlin.js.JsExport

@JsExport
interface ParserItemWithIndex {
    val currentParserIndex: Int
    val offsetParserItemIndex: Int? get() = null
    val offsetLine: Int? get() = null
    val offsetColumn: Int? get() = null
}

fun ParserItemWithIndex.toRange(
    start: Token,
    end: Token,
    parserIndex: Int = currentParserIndex,
): RangeWithIndex {
    return toRange(
        start,
        end,
        parserIndex,
        offsetParserItemIndex,
        offsetLine,
        offsetColumn
    )
}

fun toRange(
    start: Token,
    end: Token,
    parserItemIndex: Int,
    offsetParserItemIndex: Int? = null,
    offsetLine: Int? = null,
    offsetColumn: Int? = null,
): RangeWithIndex {
    return if (offsetParserItemIndex != null) {
        RangeWithIndexImpl.create(start, end, parserItemIndex, offsetParserItemIndex, offsetLine ?: 0, offsetColumn ?: 0)
    } else {
        RangeWithIndexImpl.create(start, end, parserItemIndex)
    }
}

fun ParserRuleContext.textRangeWithParserIndex(parserIndex: Int): RangeWithIndex {
    return RangeWithIndexImpl.create(
        this,
        parserIndex
    )
}

fun ParserRuleContext.textRangeWithoutParserIndex(): RangeWithIndex {
    return RangeWithIndexImpl.create(
        this,
        null
    )
}

fun Token.textRangeWithParserIndex(parserIndex: Int): RangeWithIndex {
    return RangeWithIndexImpl.create(
        startPoint(),
        endPoint(),
        startIndex,
        stopIndex,
        parserIndex
    )
}


fun Token.textRangeWithoutParserIndex(): RangeWithIndex {
    return RangeWithIndexImpl.create(
        startPoint(),
        endPoint(),
        startIndex,
        stopIndex,
        null
    )
}

val ParserRuleContext.trueText: String
    get() {
        val a: Int = start!!.startIndex
        val b: Int = stop!!.stopIndex
        val interval = Interval(a, b)
        return start!!.inputStream!!.getText(interval)
    }