/**
 * Creates a render function from the values given
 */
data class BreedRenderProvider(
    val variant: GameVariant,
    /**
     * The file sources to use when resolving breeds
     */
    val files: FileSystem,

    /**
     * The source roots within the file system
     */
    val sourceRoots: List<String>,

    /**
     * The breeds to use for each part
     */
    val partBreeds: Map<Char, BreedKey?>,
    /**
     * The sprite folder to prioritize associated sprite lookups in
     */
    val spriteRoot: String?,
    /**
     * The ATT folder to prioritize associated ATT lookups in
     */
    val attRoot: String?,

    /**
     * The default palette transformation to apply to all images
     */
    val paletteTransform: PaletteTransform? = null,

    /**
     * The breed to use when none has been set
     */
    val defaultBreed: BreedKey? = null,

    /**
     * Determines how a part should be rendered
     */
    val partVisibility: Map<Char, PartVisibility>? = null,

    /**
     * Whether to force an exact match, or allow matches with alternate ages or genders
     */
    val exactMatch: Boolean? = null,

    /**
     * The alpha transparency to apply to each ghost part 0.0 to 1.0
     */
    val ghostAlpha: Double? = null,

    /**
     * Whether to keep opaque pixels above the transparent ones for better visibility
     * If set to false, the opaque and transparent pixel opacity is averaged
     */
    val renderGhostPartsBelow: Boolean? = null,

    /**
     * Whether to use non-intersecting limb part z-order
     * C2e game engine can cause limbs to intersect as the limbs individual parts
     * share z-space with other limb's individual parts, meaning some parts of leg render
     * on top of and below the arms and vice-versa
     */
    val nonIntersectingLimbs: Boolean? = null,

    /**
     * Whether to trim transparent pixels around image
     */
    val trim: Boolean? = null,

    val recursive: Boolean? = null,

    val closeMatchOnly: Boolean? = null,

    val priorityBreedDirectories: Map<BreedKey, Pair<String?, String?>>,

    val defaultPadding: Int? = DEFAULT_PADDING,

    val defaultZoom: Double = DEFAULT_ZOOM,

    // Cache of resolved part breed to files
    private var cachedPartData: Map<Char, BodyPartFiles>? = null,

    private var mFiles: BreedFiles? = null
) {

    private var disposed = false
    private val filesListLock = Mutex(false)
    private val decompileLock = Mutex(false)
    private val renderInitLock = Mutex(false)


    // Whether tried to load part data, used to prevent re-lookup if already failed but value is null
    private var didTryLoadPartData: Boolean = false

    // Cache of part breed files decompiled to ATT object's and images
    private var cachedDecompiledData: Map<Char, ParsedBodyPartRenderData<Bitmap32>>? = null

    private var allFilesList: Set<BreedFileData>? = null

    private var mFilesList: Set<BreedFileData>? = null

    var onlyPartsToUpdate: Collection<Char>? = null

    private val id = nextId.incrementAndGet()

    private var disposables: MutableList<() -> Unit> = mutableListOf()

    init {
        if (sourceRoots.isEmpty()) {
            throw IOException("Source roots cannot be blank for breed renderer")
        }
        assertHasRequiredParts()
    }

    fun copyWithAge(age: Int): BreedRenderProvider {
        assertNotDisposed()
        return copyWithBreeds(
            partBreeds.entries.associate {
                it.key to it.value?.copy(
                    ageGroup = age
                )
            }
        )
            .apply {
                this.onlyPartsToUpdate = null
            }
    }

    suspend fun copyAlteringFiles(
        alter: (BreedFiles) -> BreedFiles,
    ): BreedRenderProvider {
        val parent = this
        return copy().apply {
            this.onlyPartsToUpdate = null
            this.cachedPartData = parent.cachedPartData
            this.didTryLoadPartData = false
            this.cachedDecompiledData = null
            this.mFilesList = null
            this.allFilesList = parent.allFilesList
            this.mutateFiles(alter)
        }
    }

    suspend fun mutateFiles(alter: (BreedFiles) -> BreedFiles) {
        val files = mFilesList ?: filesList()
        val oldFiles = mFiles ?: BreedFiles(
            gameVariant = variant,
            allFiles = files,
            spriteRoot = spriteRoot,
            attRoot = attRoot,
            paletteTransform = paletteTransform ?: this.paletteTransform,
            closeMatchOnly = closeMatchOnly ?: this.closeMatchOnly
        )
        this.mFilesList = null
        mFiles = alter(oldFiles)
    }

    fun copyWithBreeds(
        partBreeds: Map<Char, BreedKey?>,
        newFiles: List<String> = emptyList()
    ): BreedRenderProvider {
        return copyWithBreeds(
            defaultBreed = defaultBreed,
            partBreeds = partBreeds,
            newFiles = newFiles
        )
    }

    fun copyWithBreeds(
        defaultBreed: BreedKey?,
        partBreeds: Map<Char, BreedKey?>,
        newFiles: List<String> = emptyList()
    ): BreedRenderProvider {
        val toUpdate = partBreeds.keys.toSet()
//        val keys = (partBreeds.keys + this.partBreeds.keys)
//            .distinct()
//        val allParts = keys.associateWith {
//            partBreeds[it] ?: this.partBreeds[it]
//        }
        val allParts = partBreeds
        val parent = this
        return copy(
            defaultBreed = defaultBreed,
            partBreeds = allParts,
            sourceRoots = parent.sourceRoots + newFiles
        )
            .copyCacheFromMutating(parent)
            .apply {
                this.allFilesList = if (newFiles.isNotEmpty()) {
                    parent.allFilesList
                        ?.let {
                            newFiles.mapNotNull { BreedFileData.fromPath(it) }
                        }
                        ?.toSet()
                } else {
                    parent.allFilesList
                }
                this.onlyPartsToUpdate = toUpdate
            }
    }


    fun copyWithPaletteTransform(
        paletteTransform: PaletteTransform?,
    ): BreedRenderProvider {
        val parent = this
        return copy(
            paletteTransform = paletteTransform
        )
            .copyCacheFromMutating(parent)
            .apply {
                this.onlyPartsToUpdate = null
                this.allFilesList = parent.allFilesList
                this.didTryLoadPartData = parent.didTryLoadPartData
                this.cachedPartData = parent.cachedPartData
                    ?.entries
                    ?.associate {
                        it.key to it.value.copy(
                            paletteTransform = paletteTransform
                        )
                    }
                this.onlyPartsToUpdate = null
                this.mFiles = parent.mFiles?.withPaletteTransform(paletteTransform)

            }
    }

    fun copyCacheFromMutating(parent: BreedRenderProvider): BreedRenderProvider {
        this.onlyPartsToUpdate = parent.onlyPartsToUpdate
        this.cachedPartData = parent.cachedPartData
        this.didTryLoadPartData = false
        this.mFilesList = parent.mFilesList
        this.allFilesList = null
        this.mFiles = parent.mFiles
        return this
    }


    /**
     * List all usable breed files passed in
     */
    suspend fun filesList(partsToUpdate: Collection<Char>? = onlyPartsToUpdate): Set<BreedFileData> =
        filesListLock.withLock(this) {

            if (partsToUpdate.isNullOrEmpty()) {
                mFilesList?.nullIfEmpty()?.let {
                    return it
                }
            }

            val allFiles = this.allFilesList ?: sourceRoots
                .expandFileList(
                    files,
                    recursive
                )
                .toSet()
                .also {
                    allFilesList = it
                }

            val currentFiles = mFilesList
            val filter = if (currentFiles.isNotNullOrEmpty() && partsToUpdate.isNotNullOrEmpty()) {
                Log.iIf(LOG_DEBUG) { "Filtering files by parts to update: $partsToUpdate" }
                buildFilter(partsToUpdate)
            } else if (currentFiles.isNullOrEmpty()) {
                Log.iIf(LOG_DEBUG) { "Filtering for breeds as parts to update and current files are null or empty" }
                buildFilter(ALL_PARTS)
            } else {
                Log.iIf(LOG_DEBUG) { "Current files are not null or empty; ${currentFiles.toList("Current Files")}" }
                val partsMissingFiles = currentFiles.missingParts(ALL_REQUIRED_PARTS)
                if (partsMissingFiles.isEmpty()) {
                    Log.iIf(LOG_DEBUG) { "Current files represent all parts" }
                    return@withLock currentFiles
                }
                buildFilter(ALL_PARTS.toList())
            }

            val filteredFiles = allFiles.filter(filter)
                .nullIfEmpty()
                ?: return@withLock allFiles.also {
                    Log.iIf(LOG_DEBUG) { "Filtered files produced no result. Returning all files; FilesCount: ${allFiles.size}" }
                }

            val newPartsMissingFiles = filteredFiles.missingParts(partsToUpdate.orEmpty().toSet())
            if (newPartsMissingFiles.isNotEmpty()) {
                Log.iIf(LOG_DEBUG) { "Failed to find files for all updatable parts: $newPartsMissingFiles" }
            }

            // Combine new with old
            val newFileSet = (currentFiles?.filter { partsToUpdate == null || it.part !in partsToUpdate }.orEmpty()
                .toSet() + filteredFiles)

            // Ensure there are files for each body part (matching or not)
            val partsMissingFiles = newFileSet.missingParts(ALL_REQUIRED_PARTS)
            if (partsMissingFiles.isEmpty()) {
                Log.iIf(LOG_DEBUG) { "Breed files exist for all parts" }
                newFileSet
            } else {
                // Log missing part files message
                Log.wIf(LOG_DEBUG) {
                    "No files found for part: $partsMissingFiles;\n" +
                            newFileSet.toList("NewFiles") + '\n' +
                            allFilesList.toList("AllFiles")
                }
                allFiles
            }.also {
                mFilesList = it
            }
        }


    // Stringify a list of files
    fun Collection<BreedFileData>?.toList(listName: String): String {
        return listName + ":\n\t" + this?.joinToString("\n\t") { it.filename }
    }

    fun Collection<BreedFileData>.missingParts(parts: Set<Char> = ALL_REQUIRED_PARTS): Set<Char> {
        if (this.isEmpty() || parts.isEmpty()) {
            return parts
        }
        return parts.filter { part -> this.none { it.part == part && it.isAtt } }.toSet()
    }

    suspend fun actualFiles(): List<String>? {
        val data = toBreedPartData(coroutineContext, false)
            ?: return null
        return data.values.flatMap {
            listOfNotNull(
                it.spriteFile.path,
                it.attFile?.path
            )
        }
    }

    /**
     * Build a regex for possible files to process
     */
    private fun buildFilter(partsToUpdate: Collection<Char>): (fileData: BreedFileData) -> Boolean {

        val extensions = when (variant) {
            GameVariant.C1 -> setOf("spr", "att")
            GameVariant.C2 -> setOf("s16", "att")
            else -> setOf("c16", "att")
        }
        if (exactMatch ?: EXACT_MATCH_DEFAULT) {

            val breedsByPart = partsToUpdate.associateWith {
                partBreeds[it] ?: defaultBreed
            }
            return if (variant.isC2e) {
                filter@{ file ->
                    if (file.part !in partsToUpdate) {
                        return@filter false
                    }
                    val breed = breedsByPart[file.part]
                        ?: return@filter false
                    if (file.extension in extensions && file.genus == breed.genus && file.breed == breed.breed) {
                        true
                    } else if (file.isAtt) {
                        file.genus == 0 && breed.genus == 0 && file.breed == 'a' && (breed.breed == 'b' || breed.breed == 'c')
                    } else {
                        false
                    }
                }
            } else {
                filter@{
                    if (it.part !in partsToUpdate) {
                        return@filter false
                    }
                    val breed = breedsByPart[it.part]
                        ?: return@filter false
                    it.extension in extensions && it.genus == breed.genus && it.breed == breed.breed
                }
            }
        }


        val partsWithGenusByGenus = (0..7).associateWith { genus ->
            partBreeds.entries.mapNotNull {
                if (it.key in partsToUpdate && (it.value?.genus == (genus % 4))) {
                    it.key
                } else {
                    null
                }
            }
        }

        return { file ->
            if (file.extension in extensions) {
                file.part in partsWithGenusByGenus[file.genus]!!
            } else {
                false
            }
        }
    }

    /**
     * Fetches the actual part breed file path data to support rendering, caching values
     * Note: Does not cache values when given a palette transform
     * NOTE: Does not need mutex lock now, as it is only ever called by a single, locked method
     */
    private suspend fun toBreedPartData(
        context: CoroutineContext?,
        refresh: Boolean = false,
        paletteTransform: PaletteTransform? = null,
        closeMatchOnly: Boolean? = this.closeMatchOnly,
    ): Map<Char, BodyPartFiles>? {

        val coroutineContext = context ?: coroutineContext

        coroutineContext.ensureActive()

        val hasUpdateOnlyParts = onlyPartsToUpdate.isNullOrEmpty()
        // Return cache if possible and desired
        // onlyPartsToUpdate
        if (!refresh && (paletteTransform == null || this.paletteTransform == paletteTransform) && hasUpdateOnlyParts) {
            cachedPartData?.let {
                return it
            }
            if (didTryLoadPartData) {
                return null
            }
        }
        val outData = mutableMapOf<Char, BodyPartFiles>()
        // Parts that are missing (which will throw an error later)
        val missing = mutableListOf<Pair<Char, BreedKey?>>()

        fillOutData(
            coroutineContext = coroutineContext,
            outData = outData,
            missing = missing,
            closeMatchOnly = closeMatchOnly,
            paletteTransform = paletteTransform
        )

        Log.iIf(LOG_DEBUG) {
            val files = outData.values.joinToString("\n\t- ", transform = BodyPartFiles::filenamesToString)
            "PartPairs: \n\t-$files"
        }

        // If any required parts are missing, throw an exception
        if (missing.size > 0) {
            val missingFormatted = missing.joinToString { (part, key) -> "$part${key?.codeSafe ?: "{UNDEF}"}" }
            Log.iIf(LOG_DEBUG) {
                "Failed to locate all requested breed files. Missing Files: [$missingFormatted];\nFiles:\n\t" + mFilesList?.joinToString(
                    "\n\t"
                )
            }
            throw PoseRenderException("Failed to locate all requested breed files. Missing Files: [$missingFormatted]")
        }

        // Cache result if using the instance level palette
        if (!refresh || hasUpdateOnlyParts) {
            didTryLoadPartData = true
            cachedPartData = outData
        }

        // Return the path data for the parts
        return outData
    }

    /**
     * Fill map with parts and matching body part files
     */
    private suspend fun fillOutData(
        coroutineContext: CoroutineContext,
        outData: MutableMap<Char, BodyPartFiles>,
        missing: MutableList<Pair<Char, BreedKey?>>,
        closeMatchOnly: Boolean?,
        paletteTransform: PaletteTransform?,
    ) {
        coroutineContext.ensureActive()

        val cached: Map<Char, BodyPartFiles>? = cachedPartData
        val toUpdate = getPartsToUpdate(cached)

        val oldBreedFiles = if (toUpdate.isNullOrEmpty()) {
            mFiles
        } else {
            null
        }

        val breedFiles = oldBreedFiles ?: BreedFiles(
            gameVariant = variant,
            allFiles = filesList(toUpdate),
            spriteRoot = spriteRoot,
            attRoot = attRoot,
            paletteTransform = paletteTransform ?: this.paletteTransform,
            closeMatchOnly = closeMatchOnly ?: this.closeMatchOnly
        )

        mFiles = breedFiles

        breedFiles.assertHasSpritesAndAtts()

        // Get part data for the given breeds
        for (part in 'a'..'q') {
            coroutineContext.ensureActive()

            val breedKey = if (part in 'o'..'q') {
                partBreeds[part] ?: continue
            } else {
                partBreeds[part]?.let {
                    if (it.isNoneKey()) {
                        null
                    } else {
                        it
                    }
                } ?: defaultBreed
            }

            if (breedKey == null) {
                Log.e { "Breed key for part $part should not be null" }
                missing.add(Pair(part, null))
                continue
            }

            if (toUpdate != null && cached != null && part !in toUpdate) {
                val cachedPart: BodyPartFiles? = cached[part]
                if (cachedPart?.attFile != null) {
                    val cachedKey = cachedPart
                        .breedPartKey
                        .breedKey
                        .copyWithAgeGroup(null)
                        .copyWithGender(null)
                    if (cachedKey.isGenericMatchFor(breedKey)) {
                        outData[part] = cachedPart
                        continue
                    } else {
                        Log.wIf(LOG_DEBUG) { "Cached breed key does not match expected; Expected: ${breedKey.code}; Found: ${cachedPart.breedPartKey.code}" }
                    }
                }
            }
            if (breedKey.isNoneKey()) {
                Log.w { "Breed key for part $part is NoneKey" }
            }
            val data = getPartData(
                coroutineContext = coroutineContext,
                priorityDirectory = breedKey.let { priorityBreedDirectories[it] },
                files = breedFiles,
                part = part,
                breedKey = breedKey
            )

            // Make sure the required parts have a breed associated with them
            if (data == null) {
                // See if missing part is required
                if (part in 'a'..'l') {
                    // Main parts are always required
                    missing.add(Pair(part, breedKey))
                }
                continue
            }

            if (part == 'm' || part == 'n') {
                if (breedKey.genus != data.breedPartKey.genus || breedKey.breed != data.breedPartKey.breed) {
                    continue
                }
            }
            outData[part] = data
        }
    }

    private fun getPartsToUpdate(cached: Map<Char, BodyPartFiles>?): Set<Char>? {
        // Only need cached chars here
        val onlyUpdate = onlyPartsToUpdate
        onlyPartsToUpdate = null

        if (cached == null) {
            return null
        }

        // Return only what may have changed
        if (onlyUpdate.isNullOrEmpty()) {
            return null
        }

        // Get list of parts to update, taking account of what changed
        // and what is and is not cached
        val allParts = when (variant) {
            GameVariant.CV -> ALL_PARTS
            GameVariant.C1 -> "abcdefghijkl".toCharArray().toSet()
            else -> "abcdefghijklmn".toCharArray().toSet()
        }
        val notCached = allParts.filter { !cached.containsKey(it) }
        val toUpdate = (notCached + onlyUpdate)
        return toUpdate
            .map(Char::lowercaseChar)
            .toSet()
            .nullIfEmpty()
    }

    /**
     * Gets data for the breed of a given part
     */
    private fun getPartData(
        coroutineContext: CoroutineContext,
        priorityDirectory: Pair<String?, String?>?,
        files: BreedFiles,
        part: Char,
        breedKey: BreedKey,
    ): BodyPartFiles? {

        coroutineContext.ensureActive()

        // Get data if breed key exists for part
        return if (breedKey.isNoneKey()) {
            null
        } else if (exactMatch ?: EXACT_MATCH_DEFAULT) {
            // Find sprite and ATTs that match this file exactly
            BreedFileUtil.getBreedFileExactMatch(
                coroutineContext,
                files[part],
                breedKey,
                priorityDirectory?.first,
                priorityDirectory?.second,
                otherAges = true,
                otherGenders = true
            )
        } else {
            // Find a sprite matching exactly, falling back to alternate ages or genders
            BreedFileUtil.getBreedFileFuzzyMatch(
                coroutineContext,
                files[part],
                breedKey,
                priorityDirectory?.first,
                priorityDirectory?.second
            )
        }
    }

    /**
     * Decompiles files into usable ATT and Sprite frames, while caching values.
     * Note: Does not cache values when given a palette transform
     */
    private suspend fun decompiledData(
        coroutineContext: CoroutineContext,
        refresh: Boolean = false,
        paletteTransform: PaletteTransform?,
        closeMatchOnly: Boolean?,
    ): Map<Char, ParsedBodyPartRenderData<Bitmap32>>? = decompileLock.withLock {

        coroutineContext.ensureActive()

        if (!refresh && (paletteTransform == null || this.paletteTransform == paletteTransform) && onlyPartsToUpdate.isNullOrEmpty()) {
            cachedDecompiledData?.let {
                return it
            }
        }

        // Get file path data for the parts' breeds
        val rawData = toBreedPartData(
            coroutineContext,
            refresh = refresh,
            paletteTransform = paletteTransform ?: (if (refresh) this.paletteTransform else null),
            closeMatchOnly = closeMatchOnly ?: this.closeMatchOnly,
        ) ?: return null

        // Take file paths and load and parse them
        val dataNullable = rawData
            .map map@{ (part, data) ->
                val parsedPart = data.toParsedBodyPartRenderData(files)
                part to parsedPart?.copy(
                    visibility = (partVisibility?.get(part) ?: PartVisibility.VISIBLE)
                )
            }
            .toMap()

        val dataNotNull = dataNullable
            .entries
            .filter { it.value != null }
            .associate {
                it.key to (it.value ?: throw PoseRenderException(
                    "Failed to get parsed render data for ${it.key}",
                    NullPointerException()
                ))
            }
        val missing = dataNullable.filter { it.value == null }.map { it.key }
        if (missing.isNotEmpty()) {
            throw PoseRenderException("Failed to parse body part files for parts: $missing")
        }

        // If palette transform is null, cache values
        if (!refresh) {
            cachedDecompiledData = dataNotNull
        }

        // Returned parsed ATT and Sprite frames
        return dataNotNull
    }

    /**
     * Gets a renderer that renders given a pose data object
     * NOTE: Files are lazy loaded, so missing files will not fail until a render is requested
     */
    fun poseRenderer(
        padding: Int,
        defaultZoom: Int,
        paletteTransform: PaletteTransform? = null,
        closeMatchOnly: Boolean? = this.closeMatchOnly,
    ): PoseRenderer {
        return poseRenderer(
            padding = padding,
            trim = trim,
            defaultZoom = defaultZoom.toDouble(),
            paletteTransform = paletteTransform,
            closeMatchOnly = closeMatchOnly
        )
    }

    /**
     * Gets a renderer that renders given a pose data object
     * NOTE: Files are lazy loaded, so missing files will not fail until a render is requested
     */
    fun poseRenderer(
        padding: Int,
        trim: Boolean,
        defaultZoom: Int,
        paletteTransform: PaletteTransform? = null,
        closeMatchOnly: Boolean? = this.closeMatchOnly,
    ): PoseRenderer {
        return poseRenderer(
            padding = padding,
            trim = trim,
            defaultZoom = defaultZoom.toDouble(),
            paletteTransform = paletteTransform,
            closeMatchOnly = closeMatchOnly
        )
    }

    /**
     * Gets a renderer that renders given a pose data object
     * NOTE: Files are lazy loaded, so missing files will not fail until a render is requested
     */
    fun poseRenderer(
        padding: Int? = this.defaultPadding,
        trim: Boolean? = this.trim,
        defaultZoom: Double = this.defaultZoom,
        paletteTransform: PaletteTransform? = null,
        closeMatchOnly: Boolean? = this.closeMatchOnly,
    ): PoseRenderer {
        assertNotDisposed()
        // Support lazy load/parsing of breed files
        var dataCache: Map<Char, ParsedBodyPartRenderData<Bitmap32>>? = cachedDecompiledData
        var didTryCache = false

        disposables.add {
            dataCache?.values?.forEach { it.get = null }
            dataCache = null
        }

        val thePaletteTransform = this.paletteTransform

        return render@{ pose: Pose, zoom: Double? ->
            val refresh = thePaletteTransform != paletteTransform

//            Log.iIf(LOG_VERBOSE) { "Creating pose renderer; Refresh? $refresh" }
            // Get render data
            val data = renderInitLock.withLock {
                dataCache // Get data from cache
                // Try to load data if not already loaded
                    ?: if (didTryCache) {
                        // Already tried to load data, but failed, so just return null from render
                        return@render null
                    } else {
                        try {
                            decompiledData(
                                coroutineContext,
                                refresh = refresh,
                                paletteTransform = paletteTransform ?: (if (refresh) thePaletteTransform else null),
                                closeMatchOnly = closeMatchOnly ?: this.closeMatchOnly
                            )
                        } catch (e: Exception) {
                            if (e is NullPointerException) {
                                throw PoseRenderException("Failed to get decompiled data", e)
                            }
                            throw e
                        }
                            ?.apply {
                                didTryCache = true
                                dataCache = this
                            }
                            ?: return@render null.apply {
                                didTryCache = true
                                Log.eIf("debug") { "Failed to load decompiled render data" }
                            }
                    }
            }

            coroutineContext.ensureActive()

            // Render the pose
            Renderer.render(
                coroutineContext,
                pose = pose,
                data = data,
                nonIntersectingLimbs = nonIntersectingLimbs,
                zoom = zoom ?: defaultZoom,
                padding = padding ?: DEFAULT_PADDING,
                trim = trim ?: this.trim,
                ghostAlpha = ghostAlpha,
                opaqueWins = renderGhostPartsBelow
            )
        }
    }

    /**
     * Gets a renderer that renders given a pose data object
     * NOTE: Files are lazy loaded, so missing files will not fail until a render is requested
     */
    fun poseStringRenderer(
        padding: Int,
        defaultZoom: Int,
        paletteTransform: PaletteTransform? = null,
        closeMatchOnly: Boolean? = null,
    ): PoseStringRenderer {
        return poseStringRenderer(padding, trim, defaultZoom.toDouble(), paletteTransform, closeMatchOnly)
    }


    /**
     * Gets a renderer that renders given a pose data object
     * NOTE: Files are lazy loaded, so missing files will not fail until a render is requested
     */
    fun poseStringRenderer(
        padding: Int,
        trim: Boolean?,
        defaultZoom: Int,
        paletteTransform: PaletteTransform? = null,
        closeMatchOnly: Boolean? = null,
    ): PoseStringRenderer {
        assertNotDisposed()
        return poseStringRenderer(padding, trim, defaultZoom.toDouble(), paletteTransform, closeMatchOnly)
    }

    /**
     * Gets a renderer that renders given a pose data object
     * NOTE: Files are lazy loaded, so missing files will not fail until a render is requested
     */
    fun poseStringRenderer(
        padding: Int,
        trim: Boolean? = this.trim,
        defaultZoom: Double = this.defaultZoom,
        paletteTransform: PaletteTransform? = null,
        closeMatchOnly: Boolean? = this.closeMatchOnly,
    ): PoseStringRenderer {
        assertNotDisposed()
        val mutex = Mutex(false)
        // Support lazy load/parsing of breed files
        var dataCache: PoseRenderer? = null
        return render@{ poseString: String, zoom: Double? ->
            // Convert pose to string
            val pose = PoseStringUtil.fromPoseString(variant, poseString)
            val render = mutex.withLock {
                dataCache ?: poseRenderer(padding, trim, defaultZoom, paletteTransform, closeMatchOnly).apply {
                    dataCache = this
                }
            }
            render(pose, zoom)
        }
    }

    @Suppress("SpellCheckingInspection")
    private fun assertHasRequiredParts() {
        val hasParts = partBreeds.keys
        val missingParts = if (defaultBreed != null) {
            emptyList<BreedKey>()
        } else {
            ALL_REQUIRED_PARTS.filter { it !in hasParts }.toSet()
        }
        if (missingParts.isEmpty()) {
            return
        }
        val missing = mutableListOf<String>()
        if ('a' in missingParts) {
            missing.add("head")
        }
        if ('b' in missingParts) {
            missing.add("body")
        }
        "cdefgh".addMissing("legs", hasParts, missing)
        "ijkl".addMissing("arms", hasParts, missing)
        if (variant != GameVariant.C1) {
            "mn".addMissing("tail", hasParts, missing)
        }
        if (variant == GameVariant.CV) {
            "op".addMissing("ears", hasParts, missing)
            "q".addMissing("hair", hasParts, missing)
        }
        throw MissingPartBreedsException(
            message = "Render provider is missing breed definitions for $missing",
            missing = missing.toTypedArray(),
        )
    }

    fun dispose() {
        if (disposed) {
            return
        }
        cachedPartData = null
        allFilesList = null
        cachedDecompiledData = null
        mFilesList?.forEach(BreedFileData::clearCache)
        mFilesList = null
        mFiles = null
        disposables.forEach { it() }
        disposables.clear()
        gcCollect()

    }

    private fun assertNotDisposed() {
        if (disposed) {
            throw AlreadyDisposedDataCacheException()
        }
    }

    companion object {
        const val EXACT_MATCH_DEFAULT = true
        const val DEFAULT_PADDING = 0
        const val DEFAULT_ZOOM = 1.0
        const val DEFAULT_TRIM = false
        private val ALL_PARTS = PartChars.ALL_PARTS.toSet()
        private val ALL_REQUIRED_PARTS = "abcdefghijkl".toSet()

        private val nextId = KorAtomicInt(0)

    }
}

private val BREED_FILE_EXTENSIONS = listOf(
    "att",
    "spr",
    "s16",
    "c16"
)

val spriteFileRegex = ".+?\\.(${BREED_FILE_EXTENSIONS.joinToString("|")})$".toRegex(RegexOption.IGNORE_CASE)

private suspend fun List<String>.expandFileList(
    files: FileSystem,
    recursive: Boolean?,
): List<BreedFileData> {
    return mapAsync { root ->
        if (spriteFileRegex.matches(root) && files.isFile(root)) {
            listOf(root)
        } else if (files.isDirectory(root)) {
            files.listAllFiles(root, recursive ?: false)
        } else {
            emptyList()
        }
    }
        .flatten()
        .distinct()
        .mapNotNull { BreedFileData.fromPath(it) }
}

private suspend fun List<String>.expandFileList(
    files: FileSystem,
    recursive: Boolean?,
    pathRegex: Regex,
): List<String> {
    return mapAsync { root ->
        if (files.isFile(root)) {
            if (pathRegex.matches(root)) {
                listOf(root)
            } else {
                emptyList()
            }
        } else {
            files.listAllFiles(root, recursive ?: false) { path ->
                pathRegex.matches(path)
            }
        }
    }.flatten().distinct()
}


fun <T> ((pose: T, zoom: Double?) -> Bitmap32?).withZoom(zoom: Double? = null): suspend (T) -> Bitmap32? {
    return { pose ->
        this(pose, zoom)
    }
}

fun Collection<Char>.joinToString(): String {
    return this.joinToString { it.toString() }
}

fun String.addMissing(bodyPart: String, setParts: Set<Char>, listOfMissing: MutableList<String>) {
    val missingParts = this.toSet()
        .filterNotIn(setParts)
        .nullIfEmpty()
        ?: return
    if (missingParts.size == this.length) {
        listOfMissing.add(bodyPart)
    } else {
        listOfMissing.add("$bodyPart parts [${missingParts.joinToString()}]")
    }
}