package com.bedalton.creatures.genetics.genome

import com.bedalton.creatures.genetics.gene.Gene


inline fun <reified GeneT: Gene> Genome.genesOfType(): List<GeneT> {
    return genes.filterIsInstance<GeneT>()
}


val Genome.isC1 get() = version == Genome.C1_VERSION
val Genome.isC2 get() = version == Genome.C2_VERSION
val Genome.isC2e get() = version == Genome.C2E_VERSION