package com.creaturesforge.application.ui.pages

import com.bedalton.common.coroutines.launch
import com.bedalton.common.util.formatted
import com.bedalton.log.Log
import com.creaturesforge.application.interop.setEggModeInTauri
import com.creaturesforge.application.state.EggMode
import com.creaturesforge.application.state.ForgeConfig
import com.creaturesforge.application.state.ForgeStore
import com.creaturesforge.application.state.SetEggModeAction
import com.creaturesforge.application.ui.html.dataString
import com.creaturesforge.application.ui.pages.Pages.body
import kotlinx.coroutines.Job

internal object AppEggMode {

    private var mView by body.dataString("view")

    val eggModeOrDefault: EggMode
        get() = parseEggMode(mView, "")
            ?: ForgeConfig.getCachedEggMode()
            ?: throw Exception("Egg mode not set")


    suspend fun init() {

        val initialEggView = ForgeConfig.getLastEggMode(null, null)
            ?.also {
                Log.i("Config Egg Mode: ${it.name.lowercase()}")
            }
            ?: getEggModeNotNull()

        setEggMode(null, initialEggView, false)

        ForgeConfig.addOnInitialLoadListener {
            val cachedEggMode = it.getCachedEggMode()
            if (cachedEggMode != null && cachedEggMode != initialEggView) {
                setEggMode(null, cachedEggMode, false)
            }
        }

        var runOnce = false
        ForgeStore.subscribe { state, dispatch ->
            if (!runOnce) {
                runOnce = true
                dispatch(SetEggModeAction(initialEggView))
            } else if (eggModeOrDefault != state.eggMode) {
                setEggMode(state.projectFolder, state.eggMode, true)
            }
        }
    }

    fun setEggMode(eggMode: EggMode, updateConfig: Boolean = true) {
        setEggMode(null, eggMode, updateConfig)
    }

    fun setEggMode(projectRoot: String?, eggMode: EggMode, updateConfig: Boolean = true) {
        val changed = this.eggModeOrDefault != eggMode
        mView = toViewMode(eggMode)
        setEggModeInTauri(eggMode)
        Pages.validate()
        if (updateConfig && changed) {
            Job().launch {
                try {
                    ForgeConfig.setLastEggMode(projectRoot, eggMode)
                } catch (e: Exception) {
                    Log.e("setEggMode().launch() failed; ${e.formatted(true)}")
                }
            }
        }
    }

    suspend fun getEggModeNotNull(): EggMode {
        parseEggMode(mView, "")?.let {
            return it
        }
        ForgeConfig.getLastEggMode(null, null)?.let {
            return it
        }
        return EggMode.DEFAULT
    }

    internal fun parseEggMode(mode: String?, from: String?): EggMode? {
        if (mode == null) {
            return null
        }
        return EggMode.fromString(mode)
            ?: (if (from.isNullOrBlank()) {
                throw Exception("Cannot parse invalid view mode; Should be one of [simple, advanced]; Found: $mode; From: $from")
            } else {
                throw Exception("$from has invalid 'data-page-for' attribute; Should be one of [simple, advanced]; Found: $mode")
            })
    }

    private fun toViewMode(eggMode: EggMode): String {
        return when (eggMode) {
            EggMode.SINGLE -> "simple"
            EggMode.MULTI -> "advanced"
        }
    }


}