@file:Suppress("unused")

package com.bedalton.vfs

import com.bedalton.common.exceptions.IOException
import com.bedalton.common.util.PathUtil
import com.bedalton.common.util.isNotNullOrBlank
import com.bedalton.vfs.internal.isVirtualFileSystem

/**
 * Lists all files possibly filtering with function and/or in a specific sub-folder
 */
internal suspend fun listAllFilesDefaultPrivate(
    fileSystem: FileSystem,
    absolutePath: String,
    recursive: Boolean = false,
    filter: ((path: String) -> Boolean)? = null
): List<String> {
    assertAbsolutePath(
        absolutePath.expandTildeIfNecessary(),
        assertNotFileSystemRoot = !fileSystem.isVirtualFileSystem() && recursive
    )
    val files = fileSystem.getChildren(absolutePath.expandTildeIfNecessary(), recursive).orEmpty()
    return if (filter != null) {
        files.filter(filter)
    } else {
        files
    }
}


/**
 * Returns the first file in any source root that matches the filter function
 */
internal suspend inline fun findFirstPrivate(
    fileSystem: FileSystem,
    absolutePath: String,
    recursive: Boolean = true,
    crossinline filter: (path: String) -> Boolean
): String? {

    assertAbsolutePath(absolutePath, assertNotFileSystemRoot = !isVirtualFileSystem && recursive)


    // Find direct descendants
    val firstChildren = fileSystem.getChildrenNonRecursive(absolutePath)?.map { child ->
        if (!PathUtil.isAbsolute(child) && !fileSystem.isVirtualPathInVirtualFS(child)) {
            PathUtil.combine(absolutePath, child)
        } else {
            child
        }
    } ?: return null

    if (firstChildren.isEmpty()) {
        return null
    }

    // Check if any immediate child matches filter
    firstChildren.firstOrNull(filter)?.let {
        return it
    }

    // If not searching recursively, bail out now
    if (!recursive) {
        return null
    }

    // Which children to search next
    // This traverses children at the same rate
    var searchNext = firstChildren.filter { fileSystem.isDirectory(it) }

    // If there are child directories to check
    while (searchNext.isNotEmpty()) {
        // Establish which children's children need to be searched if a match is not found
        val searchNextTemp = mutableListOf<String>()

        // Next child directory to search
        for (childPath in searchNext) {
            // Search within child for children
            val secondaryChildren = fileSystem.getChildrenNonRecursive(childPath)?.map { child ->
                if (!PathUtil.isAbsolute(child) && !fileSystem.isVirtualPathInVirtualFS(child)) {
                    PathUtil.combine(childPath, child)
                } else {
                    child
                }
            } ?: continue

            // Check if any of this child's children match filter
            secondaryChildren.firstOrNull(filter)?.let {
                return it
            }
            // Add any child directories to be searched next
            searchNextTemp.addAll(secondaryChildren.filter { fileSystem.isDirectory(it) })
        }
        // Set search next to the new list
        searchNext = searchNextTemp
    }

    // Nothing was found, so return null
    return null
}

internal fun String.normalized() = this.lowercase().replace('\\', '/').let { PathUtil.combine(it) }


internal fun assertAbsolutePath(path: String, assertNotFileSystemRoot: Boolean = false, allowVFS: Boolean = false) {
    if (!VfsSwitches.pathsMustBeAbsolute) {
        return
    }
    val expandedPath = path.trim().expandTildeIfNecessary()
    if (expandedPath.isBlank()) {
        throw Exception("Path cannot be blank")
    }
    val isAbsolute = PathUtil.isAbsolute(expandedPath) ||
            isResourcePath(path) ||
            (allowVFS && isVirtualPath(expandedPath))

    if (!isAbsolute) {
        throw PathNotAbsoluteException(path)
    }

    if (assertNotFileSystemRoot) {
        if (path.trim() == "/" || path.trim() == "\\" || WINDOWS_DRIVE_ROOT.matches(path.trim())) {
            throw IOException("Cannot search for file(s) in unbounded file system root directory")
        }
    }
}