package com.bedalton.creatures.agents.pray.compiler.data

import com.bedalton.creatures.agents.util.internal.tok


// Regex for Sea Monkey Animation block tags
private val SEA_MONKEY_ANIMATION_TAG = "a[MF]..".toRegex()


@Deprecated(
    "Use makePrayBlock with tags val",
    replaceWith = ReplaceWith("makePrayBlock(startLine, blockTag, blockName, unescape, getTags())")
)
fun makePrayBlock(
    startLine: Int,
    blockTag: TextValue,
    blockName: TextValue,
    @Suppress("UNUSED_PARAMETER") safe: Boolean,
    unescape: Boolean,
    getTags: () -> Array<Tag<*>> = { emptyArray() }
): CompilerPrayBlock {
    return makePrayBlock(startLine, blockTag, blockName, unescape, getTags())
}

fun makePrayBlock(
    startLine: Int,
    blockTag: TextValue,
    blockName: TextValue,
    unescape: Boolean,
    tags: Array<Tag<*>>,
    linkWithFilenameReference: Boolean? = null
): CompilerPrayBlock {
    // Determine block type from block tag
    return when (tok(blockTag.text.uppercase())) {
        in NON_AGENT_TAG_BLOCKS -> CompilerGeneralBlockWithTags(startLine, blockTag, blockName, unescape, tags)
        // Starter families
        in FILE_BLOCKS -> CompilerPrayBlock.NotImplementedPrayBlock(startLine, blockTag.text, blockTag, blockName)
        in UNSUPPORTED_BLOCKS -> CompilerPrayBlock.NotImplementedPrayBlock(startLine, blockTag.text, blockTag, blockName)
        else -> {
            // Check if miscellaneous tag is SeaMonkey Animation
            if (SEA_MONKEY_ANIMATION_TAG.matches(blockTag.text)) {
                return CompilerPrayBlock.NotImplementedPrayBlock(
                    startLine = startLine,
                    commonName = "SeaMonkey Animation",
                    blockTag = blockTag,
                    blockName = blockName
                )
            }
            // Tag can be user defined agent tag
            CompilerAgentBlock(
                startLine = startLine,
                blockTag = blockTag,
                blockName = blockName,
                unescape,
                tags = tags,
                fullFilePath = "$blockTag::$blockName",
                linkWithFilenameReference = linkWithFilenameReference
            )
        }
    }
}
