@file:Suppress("unused")

package com.bedalton.creatures.sprite.compilers

import com.bedalton.creatures.sprite.util.ColorEncoding
import com.bedalton.creatures.sprite.util.PaletteTransform
import com.bedalton.creatures.sprite.util.SpriteType
import com.bedalton.creatures.sprite.util.SpriteType.*
import korlibs.image.bitmap.Bitmap32
import korlibs.image.color.RGB
import kotlin.js.JsExport


var programAlphaCutoff: Int = 100

interface SpriteCompiler {

    @Deprecated("Use compileFromImageBytes with keepBlack parameter",
        ReplaceWith("SpriteCompiler.compileSpriteFromImageBytes(images, false, colorEncoding, callback)",
            imports = ["bedalton.creatures.sprite.compilers.SpriteCompiler"]
            ))
    fun compileSpriteFromImageBytes(
        images: List<Pair<String, ByteArray>>,
        colorEncoding: ColorEncoding? = ColorEncoding.ENCODING_DEFAULT,
        callback: ((pass: Int, current: Int, total: Int) -> Boolean?)? = null,
    ): ByteArray

    fun compileSpriteFromImageBytes(
        images: List<Pair<String, ByteArray>>,
        keepBlack: Boolean = false,
        colorEncoding: ColorEncoding? = ColorEncoding.ENCODING_DEFAULT,
        callback: ((pass: Int, current: Int, total: Int) -> Boolean?)? = null,
    ): ByteArray {
        return compileSpriteFromImageBytes(
            images,
            keepBlack,
            colorEncoding,
            null,
            callback
        )
    }


    fun compileSpriteFromImageBytes(
        images: List<Pair<String, ByteArray>>,
        keepBlack: Boolean = false,
        colorEncoding: ColorEncoding? = ColorEncoding.ENCODING_DEFAULT,
        paletteTransform: PaletteTransform?,
        callback: ((pass: Int, current: Int, total: Int) -> Boolean?)? = null,
    ): ByteArray


    @Deprecated("Use compileFromLoadedImages with keepBlack parameter inserted into second position",
        ReplaceWith(
            "SpriteCompiler.compileSpriteFromLoadedImages(images, false, colorEncoding, callback)",
            imports = ["bedalton.creatures.sprite.compilers.SpriteCompiler"]
        )
    )
    fun compileSpriteFromLoadedImages(
        images: List<Bitmap32>,
        colorEncoding: ColorEncoding? = ColorEncoding.ENCODING_DEFAULT,
        callback: ((current: Int, total: Int) -> Boolean?)? = null,
    ): ByteArray

    fun compileSpriteFromLoadedImages(
        images: List<Bitmap32>,
        keepBlack: Boolean = false,
        colorEncoding: ColorEncoding? = ColorEncoding.ENCODING_DEFAULT,
        callback: ((current: Int, total: Int) -> Boolean?)? = null,
    ): ByteArray {
        return compileSpriteFromLoadedImages(
            images,
            keepBlack,
            colorEncoding,
            null,
            callback
        )
    }

    fun compileSpriteFromLoadedImages(
        images: List<Bitmap32>,
        keepBlack: Boolean = false,
        colorEncoding: ColorEncoding? = ColorEncoding.ENCODING_DEFAULT,
        paletteTransform: PaletteTransform?,
        callback: ((current: Int, total: Int) -> Boolean?)? = null,
    ): ByteArray

    companion object {

        private const val transparentBlack = 0

        private val solidBlack by lazy {
            var black = 0
            var i = 1
            while (black == 0) {
                black = RGB(0,0,0).pack(i, i, i, 0)
                i += 1
            }
            black
        }

        fun getBlack(keepBlack: Boolean): Int {
            return if (keepBlack) {
                solidBlack
            } else {
                transparentBlack
            }
        }

        fun getCompiler(type: String): SpriteCompiler {
            return getCompiler(SpriteType.fromString(type))
        }

        @Suppress("MemberVisibilityCanBePrivate")
        fun getCompiler(type: SpriteType): SpriteCompiler {
            return when (type) {
                SPR -> SprCompiler
                SPR_SET -> throw SpriteCompileException("Cannot compile multi-SPR files")
                S16 -> S16Compiler
                C16 -> C16Compiler
                BLK -> BLKCompiler
                PHOTO_ALBUM -> throw SpriteCompileException("Cannot compile photo album generically")
            }
        }
    }


}


class SpriteCompilerCancelledException(message: String, throwable: Throwable? = null) : Exception(message, throwable)

@JsExport
open class SpriteCompileException(message: String, throwable: Throwable? = null) : Exception(message, throwable)