package com.creaturesforge.application.prompts

import com.bedalton.common.util.trySilent
import com.creaturesforge.application.state.LoadAgentMiddleware
import com.creaturesforge.application.ui.html.body
import com.creaturesforge.application.ui.html.dataString
import com.creaturesforge.application.ui.html.get
import kotlinx.browser.document
import kotlinx.browser.window
import org.w3c.dom.HTMLButtonElement
import org.w3c.dom.HTMLDialogElement
import org.w3c.dom.HTMLElement


internal object EggProgress {

    private var lastProgress: Double = -1.0

    private var mLoadingEggData: String by body.dataString("loading-egg", "false")
        .default("false")

    private val loggerPanel: HTMLDialogElement by lazy {
        document.getElementById("egg-load-progress-logger")
            .unsafeCast<HTMLDialogElement>()
    }

    private val cancelButton: HTMLButtonElement by lazy {
        loggerPanel.get("#cancel-egg-load-button")
    }

    private val label: HTMLElement by lazy {
        loggerPanel.get("[data-role=\"log\"]")
    }

    private var timeout = -1

    init {
        initListeners()
    }


    private fun initListeners() {

        cancelButton.onclick = {
            setLoggerPanelStatus("false")
            LoadAgentMiddleware.cancelEggLoad()
        }

        loggerPanel.addEventListener("transitionend", {
            if (mLoadingEggData != "true" && loggerPanel.open) {
                loggerPanel.close()
            }
        });
    }



    private fun setLoggerPanelStatus(status: String) {
        if (mLoadingEggData == status) {
            return
        }

        if (status.lowercase() != "done" && status.lowercase() != "false") {
            openModal(true)
        }

        mLoadingEggData = status.lowercase()
    }

    private fun openModal(open: Boolean = true) {
        if (loggerPanel.open == open) {
            return
        }
        trySilent {
            if (open) {
                loggerPanel.showModal()
            } else {
                loggerPanel.close()
            }
        }
    }

    @Suppress("UNUSED_PARAMETER")
    internal fun logProgress(agentFileName: String, blockName: String, index: Int, total: Int?) {

        window.clearTimeout(timeout)

        if (total == null) {
            setLoggerPanelStatus("indeterminate")
            return
        }

        if (index == total) {
            setLoggerPanelStatus("done")
            return
        } else {
            setLoggerPanelStatus("true")
        }

        val progress = index / total.toDouble()

        if (lastProgress < 0 || lastProgress > progress) {
            setLoggerPanelStatus("true")
        }

        lastProgress = progress

        if (progress > 99) {
            setLoggerPanelStatus("done")
            return
        }

        if (index + 1 == total) {
            timeout = window.setTimeout({
                setLoggerPanelStatus("done")
            }, 400)
        }

        val progressString = progress.toInt().toString().padStart(3, ' ') + '%'
        label.innerText = progressString
    }

}
internal actual fun onOpenEggProgress(agentFileName: String, blockName: String, index: Int, total: Int?) {
    EggProgress.logProgress(agentFileName, blockName, index, total)
}