package com.bedalton.creatures.agents.pray.compiler.pray

import com.bedalton.creatures.agents.pray.compiler.SCRIPT_COUNT_TAG_REGEX
import com.bedalton.creatures.agents.pray.compiler.SCRIPT_TAG_REGEX
import com.bedalton.creatures.agents.pray.compiler.pray.validators.validateDependencies
import com.bedalton.creatures.agents.pray.compiler.pray.validators.validateTagDuplicates
import com.bedalton.creatures.agents.pray.compiler.data.Tag
import com.bedalton.creatures.agents.pray.compiler.data.TextValue

internal object PrayTagsValidator {
    /**
     * Validate Tags for things like duplicates, and dependencies
     */
    internal fun validateTags(
        fullFilePath: String,
        validationErrors: MutableList<PrayValidationError>,
        blockTag: TextValue,
        blockName: TextValue,
        tags: Array<Tag<*>>,
        ignoreCase: Boolean = true
    ) {
        // Find duplicates
        validateTagDuplicates(fullFilePath, validationErrors, blockTag, blockName, tags, ignoreCase)

        // Validate dependencies
        validateDependencies(fullFilePath, validationErrors, blockTag, blockName, tags)

        // Validate script tags in basic PRAY file
        validateScriptTags(fullFilePath, validationErrors, blockTag, blockName, tags)
    }

    @Suppress("MemberVisibilityCanBePrivate")
    fun validateScriptTags(
        fullFilePath: String,
        validationErrors: MutableList<PrayValidationError>,
        blockTag: TextValue,
        blockName: TextValue,
        tags: Array<Tag<*>>
    ) {
        val scriptCountTag = tags.filter { SCRIPT_COUNT_TAG_REGEX.matches(it.tag) }
        val scriptCount = scriptCountTag.filterIsInstance<Tag.IntTag>()
            .firstOrNull()
            ?.value
            ?: scriptCountTag.firstNotNullOfOrNull { it.value.toString().toIntOrNull() }
        val scriptTags = tags.filter { tag ->  SCRIPT_TAG_REGEX.matches(tag.tag) }
        if (scriptCountTag.isEmpty() && scriptTags.isEmpty())
            return
        for (tag in scriptCountTag.filterIsInstance<Tag.StringTag>() + scriptCountTag.filterIsInstance<Tag.LinkTag>()) {
            validationErrors.add(
                PrayValidationError.BlockValidationError(
                    blockTag,
                    blockName,
                    message = "Script Count tag should have integer value",
                    lineNumber = tag.valueRange.lineNumber,
                    startIndex = tag.valueRange.startIndex,
                    endIndex = tag.valueRange.endIndex,
                    fullFilePath = fullFilePath
                )
            )
        }
        if (scriptCountTag.isEmpty()) {
            val firstTag = scriptTags.minByOrNull {
                it.lineNumber
            }!!
            PrayValidationError.BlockValidationError(
                blockTag,
                blockName,
                message = "'Script Count' is required when including scripts",
                lineNumber = firstTag.tagRange.lineNumber,
                startIndex = firstTag.tagRange.startIndex,
                endIndex = firstTag.tagRange.endIndex,
                fullFilePath = fullFilePath
            )
        }
        if (scriptCount != null) {
            val scriptIndices = tags
                .mapNotNull { tag ->
                    SCRIPT_TAG_REGEX.matchEntire(tag.tag)
                        ?.groupValues
                        ?.getOrNull(1)
                        ?.toIntOrNull()
                }
                .toSet()
                .sorted()

            val missing = (1 .. scriptCount).filterNot {
                it in scriptIndices
            }

            if (missing.isNotEmpty()) {
                for (tag in scriptCountTag) {
                    validationErrors.add(
                        PrayValidationError.BlockValidationError(
                            blockTag,
                            blockName,
                            message = "Missing expected script $missing",
                            lineNumber = tag.valueRange.lineNumber,
                            startIndex = tag.valueRange.startIndex,
                            endIndex = tag.valueRange.endIndex,
                            fullFilePath = fullFilePath
                        )
                    )
                }
            }
            for (tag in scriptTags) {
                val index = SCRIPT_TAG_REGEX.matchEntire(tag.tag)
                    ?.groupValues
                    ?.getOrNull(1)
                    ?.toIntOrNull()
                val error = if (index == null) {
                    PrayValidationError.BlockValidationError(
                        blockTag,
                        blockName,
                        message = "Invalid script index type. Expected integer",
                        lineNumber = tag.tagRange.lineNumber,
                        startIndex = tag.tagRange.startIndex,
                        endIndex = tag.tagRange.endIndex,
                        fullFilePath = fullFilePath
                    )
                } else if (index == 0) {
                    PrayValidationError.BlockValidationError(
                        blockTag,
                        blockName,
                        message = "Invalid script index. Indices start at 1",
                        lineNumber = tag.tagRange.lineNumber,
                        startIndex = tag.tagRange.startIndex,
                        endIndex = tag.tagRange.endIndex,
                        fullFilePath = fullFilePath
                    )
                } else if (index > scriptCount) {
                    PrayValidationError.BlockValidationError(
                        blockTag,
                        blockName,
                        message = "Script index out of range. Expected scripts in range 1..$scriptCount",
                        lineNumber = tag.tagRange.lineNumber,
                        startIndex = tag.tagRange.startIndex,
                        endIndex = tag.tagRange.endIndex,
                        fullFilePath = fullFilePath
                    )
                } else {
                    continue
                }
                validationErrors.add(error)
            }
        }
    }

}