package com.creaturesforge.application.ui.controls

import com.bedalton.common.util.capitalize
import com.bedalton.common.util.isNotNullOrBlank
import com.bedalton.common.util.isNotNullOrEmpty
import com.bedalton.common.util.isNullOrEmpty
import com.bedalton.creatures.common.util.getGenusString
import com.bedalton.log.Log
import com.bedalton.state.simple.Dispatch
import com.creaturesforge.application.state.FAction
import com.creaturesforge.application.state.ForgeState
import com.creaturesforge.application.state.ForgeStore
import com.creaturesforge.application.state.SetBreedSlotAction
import com.creaturesforge.application.ui.html.optionsList
import kotlinx.browser.document
import kotlinx.browser.window
import org.w3c.dom.HTMLOptionElement
import org.w3c.dom.HTMLSelectElement
import org.w3c.dom.get

internal abstract class BreedSlot(private val select: HTMLSelectElement): Validatable {

    private lateinit var dispatch: Dispatch<FAction>
    private var lastSlots = 0

    private val noBreedsOption = (select.querySelector("option[value='']") as HTMLOptionElement?)
        ?: (document.createElement("option") as HTMLOptionElement).apply {
            this.value = ""
            this.innerText = ""
            this.disabled = true
            select.appendChild(this)
        }

    protected var selected: com.creaturesforge.application.state.BreedSlot? = null

    init {
        select.onchange = change@{
            onBreedSlotSelect()
        }

        showNoBreedOption(true)
        updateEmptyText(hasProjectRoot = false, hasSlots = false)
        ForgeStore.subscribe { state, dispatch ->
            this.dispatch = dispatch
            updateFromState(state)
        }
    }

    protected abstract fun getBreedSlots(state: ForgeState): Set<com.creaturesforge.application.state.BreedSlot>

    protected abstract fun getSelectedSlot(state: ForgeState): com.creaturesforge.application.state.BreedSlot?

    protected abstract fun hasProjectRoot(state: ForgeState): Boolean

    private fun updateFromState(state: ForgeState) {
        val slots = getBreedSlots(state)
        updateEmptyText(
            hasProjectRoot = hasProjectRoot(state),
            hasSlots = slots.isNotNullOrEmpty()
        )
        setBreedSlots(slots)
        selectSlot(getSelectedSlot(state))
    }

    private fun updateEmptyText(hasProjectRoot: Boolean, hasSlots: Boolean) {
        // Do not allow selection until project root has been selected
        select.disabled = !hasProjectRoot

        val targetText = when {
            hasProjectRoot && hasSlots -> SELECT_SLOT_TEXT
            hasProjectRoot -> NO_BREED_SLOTS_IN_PROJECT_TEXT
            else -> NO_PROJECT_TEXT
        }
        if (noBreedsOption.innerText != targetText) {
            noBreedsOption.innerText = targetText
        }
        showNoBreedOption(!hasSlots)
    }

    private fun selectSlot(slot: com.creaturesforge.application.state.BreedSlot?) {

        // Show slot placeholder text if needed
        showNoBreedOption(slot == null)

        if (slot == null) {
            setSelectedValue("")
            return
        }
        showNoBreedOption(false)
        ensureHasSlots(setOf(slot))
        setSelectedValue("${slot.genus}:${slot.breed}")
        this.selected = slot
    }

    private fun onBreedSlotSelect() {
        val selection = getSelection()
        val selectStringValue = selection!!.value

        if (selectStringValue.isBlank()) {
            return
        }
        val value = selectStringValue.split(':')

        if (value.size != 2) {
            Log.e { "Invalid breed slot value" }
            return
        }

        val genus = value.first().toIntOrNull()
        if (genus == null) {
            Log.e { "Genus value is not int. Found: ${value.first()}" }
            return
        }

        val breed = value.lastOrNull()?.singleOrNull()?.lowercaseChar()
        if (breed == null) {
            Log.e { "Breed value is not char: ${value.lastOrNull()}" }
            return
        }
        dispatch(getSetAction(genus, breed))
    }

    abstract fun getSetAction(genus: Int, breed: Char): FAction
    private fun setBreedSlots(slots: Set<com.creaturesforge.application.state.BreedSlot>) {
        this.lastSlots = 0
        val selected = select.value
        select.innerHTML = ""
        ensureHasSlots(slots)
        setSelectedValue(selected)
    }

    private fun setSelectedValue(value: String?) {
        if (value.isNullOrBlank()) {
            showNoBreedOption(true)
            select.value = ""
        } else {
            select.value = value.trim()
            showNoBreedOption(false)
        }

    }

    private fun ensureHasSlots(slots: Set<com.creaturesforge.application.state.BreedSlot>) {

        if (this.select.asDynamic() == null) {
            window.alert("Breed slot select is null")
            return
        }

        val options = select.optionsList()
            .toMutableList()

        val represented = options.map { it.value }

        val newSlots = slots.map { "${it.genus}:${it.breed}" }
            .filter { it !in represented }
            .toSet()

        // Make sure new slots are needed
        if (newSlots.isNullOrEmpty()) {
            showNoBreedOption(true)
        }

        // Create new option
        for (slot in newSlots) {
            val option = createOption(slot)
            options.add(option)
        }

        options.sortBy {
            if (it.value.isNotNullOrBlank()) {
                "x${it.value}"
            } else {
                "_"
            }
        }
        select.innerHTML = ""
        options.forEach(select::appendChild)
    }

    private fun createOption(slotKey: String): HTMLOptionElement {
        val option = (document.createElement("option") as HTMLOptionElement)
        option.value = slotKey
        val components = slotKey.split(':')
        val genus = getGenusString(components[0].toInt())!!
            .capitalize()
        val breed = components[1].uppercase()
        option.innerText = "$genus $breed"
        return option
    }

    private fun getSelection(): HTMLOptionElement? {
        val selection = select.selectedIndex
        if (selection >= 0) {
            return select.options[selection] as HTMLOptionElement?
        }
        return null
    }

    private fun showNoBreedOption(show: Boolean) {
        if (show) {
            noBreedsOption.setAttribute("aria-hidden", "false")
            noBreedsOption.removeAttribute("hidden")
            noBreedsOption.hidden = false
            if (this.noBreedsOption.parentElement == null) {
                select.appendChild(this.noBreedsOption)
            }
        } else {
            noBreedsOption.setAttribute("aria-hidden", "true")
            noBreedsOption.setAttribute("hidden", "hidden")
            noBreedsOption.hidden = true
//            noBreedsOption
//                .parentElement
//                ?.removeChild(noBreedsOption)

        }
    }

    override fun highlightErrors() {
        if (isValid()) {
            return
        }
        select.closest(".validatable-input-container")?.setAttribute("data-is-valid", "false")
    }

    companion object {
        private const val SELECT_SLOT_TEXT = "Select sprite breed slot"
        private const val NO_PROJECT_TEXT = "Select project root first ^^^^^"
        private const val NO_BREED_SLOTS_IN_PROJECT_TEXT = "No breed C16 files in sprites folder"
    }
}