package com.bedalton.common.structs

class MutableCaselessMap<V>() : CaselessMap<V>(), MutableMap<String, V> {

    constructor(original: Map<String, V>) : this() {
        putAll(original)
    }

    override fun clear() = map.clear()

    override fun remove(key: String): V? {
        val keyActual = getKey(key)
            ?: return null
        return map.remove(keyActual)
    }

    override fun putAll(from: Map<out String, V>) {
        val entries = from.entries.distinctBy { it.key.lowercase() }
        // Remove any entries that have similar or same keys
        // As this could lead to duplicated when compared case insensitively
        for ((key, entry) in entries) {
            remove(key)
            put(key, entry)
        }
    }

    operator fun set(key: String, value: V) {
        put(key, value)
    }

    override fun put(key: String, value: V): V? {
        val oldValue = getKey(key)?.let {
            // Remove existing entry if any for caseless key
            map.remove(it)
        }
        map[key] = value
        return oldValue
    }

}


