package com.bedalton.vfs

import com.bedalton.common.util.PathUtil

class Stats constructor(val path: String, private val fs: FileSystem = LocalFileSystem!!) {

    private var mExists: Boolean? = null

    private var mIsDirectory: Boolean? = null

    private var mIsFile: Boolean? = null

    suspend fun exists(): Boolean {
        mExists?.let {
            return it
        }
        return fs.fileExists(path).also {
            mExists = it
        }
    }

    suspend fun isFile(): Boolean {
        mIsFile?.let {
            return it
        }
        return fs.isFile(path).also {
            mIsFile = it
        }
    }

    suspend fun isDirectory(): Boolean {
        mIsDirectory?.let {
            return it
        }
        return fs.isDirectory(path).also {
            mIsDirectory = it
        }
    }

    val parentPath: String by lazy {
        PathUtil.getWithoutLastPathComponent(path) ?: "."
    }

    val parent: Stats by lazy {
        Stats(parentPath, fs)
    }

    val filename: String? by lazy {
        PathUtil.getLastPathComponent(path)
    }

    val filenameWithoutExtension: String? by lazy {
        PathUtil.getFileNameWithoutExtension(path)
    }

    val extension: String? by lazy {
        PathUtil.getExtension(path)
    }
}