@file:Suppress("unused")

package com.bedalton.state.simple

/**
 * A simple redux-like data store
 */
open class SimpleStore<State, Action>(
    initialState: State,
    private val reducers: List<Reducer<State, Action & Any>>,
    private val middleware: List<Middleware<State, Action & Any>>,
    private val onError: (action: String, e: Throwable) -> Unit = { _, e -> throw e },
) : Store<State, Action> {

    private val actions = mutableListOf<Action & Any>()
    private var inAction = false

    // Keep track of current state
    private var currentState: State = initialState

    // State change subscribers
    private val subscriptions = arrayListOf<Subscription<State, Action & Any>>()

    /**
     * Dispatch an action to middleware and reducers
     */
    private fun dispatch(action: Action & Any) {
        this.actions.add(action)
        if (!inAction) {
            try {
                dispatchNext()
            } catch (e: Throwable) {
                onError("dispatch[${action::class.simpleName}]", e)
            }
        }
    }

    private fun dispatchNext() {
        inAction = true
        val action = actions.removeFirstOrNull()
            ?: return
        val oldState = currentState
        val newAction = applyMiddleware(oldState, action)
        val newState = applyReducers(oldState, newAction)
        setState(newState)
        dispatchNext()
        inAction = false
    }

    private fun setState(newState: State) {
        if (newState == currentState) {
            return
        }
        this.currentState = newState
        subscriptions.forEach {
            try {
                it(newState, ::dispatch)
            } catch (e: Throwable) {
                onError("dispatchSetState", e)
            }
        }
    }


    private fun applyMiddleware(state: State, action: Action & Any): Action & Any {
        return try {
            next(0)(state, action, ::dispatch)
        } catch (e: Throwable) {
            onError("applyMiddleware", e)
            action
        }
    }

    private fun next(index: Int): Next<State, Action & Any> {
        if (index == middleware.size) {
            // Last link of the chain. It just returns the action as is.
            return { _, action, _ -> action }
        }
        return { state, action, dispatch ->
            try {
                middleware[index].invoke(state, action, dispatch, next(index + 1))
            } catch (e: Throwable) {
                onError("next[$index]", e)
                action
            }
        }
    }


    private fun applyReducers(current: State, action: Action & Any): State {
        var newState = current
        for ((i, reducer) in reducers.withIndex()) {
            try {
                newState = reducer(newState, action)
            } catch (e: Throwable) {
                onError("applyReducers[$i]", e)
            }
        }
        return newState
    }

    override fun subscribe(subscription: Subscription<State, Action & Any>): Unsubscribe {
        subscriptions.add(subscription)
        // notify subscription of the current state
        subscription(currentState, this::dispatch)
        return {
            unsubscribe(subscription)
        }
    }

    private fun unsubscribe(subscription: Subscription<State, Action & Any>) {
        subscriptions.remove(subscription)
    }
}