import com.bedalton.creatures.agents.pray.compiler.CompileResult
import com.bedalton.creatures.agents.pray.compiler.PrayCompilerTask
import com.bedalton.vfs.*
import kotlin.js.Promise


@JsExport
fun createPrayCompilerTask(
    inputFile: String,
    outputDirectory: String,
    subFoldersOnly: Boolean = true
): JsPrayCompilerTask {
    return JsPrayCompilerTask(inputFile, outputDirectory, false, subFoldersOnly)
}

@JsExport
fun createImmutablePrayCompilerTaskBuilder(
    inputFile: String,
    outputDirectory: String,
    subFoldersOnly: Boolean = true
): JsPrayCompilerTask {
    return JsPrayCompilerTask(inputFile, outputDirectory, pure = true, subFoldersOnly = subFoldersOnly)
}

expect class JsPrayCompilerTask(
    inputFile: String,
    outputDirectory: String,
    pure: Boolean,
    subFoldersOnly: Boolean
) : PrayCompilerTask {

    @Suppress("NON_EXPORTABLE_TYPE")
    fun compile(): Promise<CompileResult>
}