@file:Suppress("PropertyName")

package com.bedalton.log

internal expect val consoleColorEscapeSequence: String

expect object ConsoleColors: IConsoleColors

interface IConsoleColors {
    // Reset
    val RESET: String

    // Modifiers
    val BRIGHT: String
    val BOLD: String
    val DIM: String
    val UNDERLINE: String
    val BLINK: String
    val REVERSE: String
    val HIDDEN: String

    // Regular Colors
    val BLACK: String
    val RED: String
    val GREEN: String
    val YELLOW: String
    val BLUE: String
    val PURPLE: String
    val CYAN: String
    val WHITE: String


    // Background
    val BLACK_BACKGROUND: String
    val RED_BACKGROUND: String
    val GREEN_BACKGROUND: String
    val YELLOW_BACKGROUND: String
    val BLUE_BACKGROUND: String
    val PURPLE_BACKGROUND: String
    val CYAN_BACKGROUND: String
    val WHITE_BACKGROUND: String

    // Underline colors
    val UNDERLINE_BLACK: String
    val UNDERLINE_RED: String
    val UNDERLINE_GREEN: String
    val UNDERLINE_YELLOW: String
    val UNDERLINE_BLUE: String
    val UNDERLINE_PURPLE: String
    val UNDERLINE_CYAN: String
    val UNDERLINE_WHITE: String
}

expect fun enableCLIColors()

object DefaultConsoleColors: IConsoleColors {
    // Reset
    override val RESET = "$consoleColorEscapeSequence[0m" // Text Reset

    // Modifiers
    override val BRIGHT = "$consoleColorEscapeSequence[1m"
    override val BOLD = "$consoleColorEscapeSequence[1m"
    override val DIM = "$consoleColorEscapeSequence[2m"
    override val UNDERLINE = "$consoleColorEscapeSequence[4m"
    override val BLINK = "$consoleColorEscapeSequence[5m"
    override val REVERSE = "$consoleColorEscapeSequence[7m"
    override val HIDDEN = "$consoleColorEscapeSequence[8m"

    // Regular Colors
    override val BLACK = "$consoleColorEscapeSequence[30m" // BLACK
    override val RED = "$consoleColorEscapeSequence[31m" // RED
    override val GREEN = "$consoleColorEscapeSequence[32m" // GREEN
    override val YELLOW = "$consoleColorEscapeSequence[33m" // YELLOW
    override val BLUE = "$consoleColorEscapeSequence[34m" // BLUE
    override val PURPLE = "$consoleColorEscapeSequence[35m" // PURPLE
    override val CYAN = "$consoleColorEscapeSequence[36m" // CYAN
    override val WHITE = "$consoleColorEscapeSequence[38;5;15m" // WHITE


    // Background
    override val BLACK_BACKGROUND = "$consoleColorEscapeSequence[40m" // BLACK
    override val RED_BACKGROUND = "$consoleColorEscapeSequence[41m" // RED
    override val GREEN_BACKGROUND = "$consoleColorEscapeSequence[42m" // GREEN
    override val YELLOW_BACKGROUND = "$consoleColorEscapeSequence[43m" // YELLOW
    override val BLUE_BACKGROUND = "$consoleColorEscapeSequence[44m" // BLUE
    override val PURPLE_BACKGROUND = "$consoleColorEscapeSequence[45m" // PURPLE
    override val CYAN_BACKGROUND = "$consoleColorEscapeSequence[46m" // CYAN
    override val WHITE_BACKGROUND = "$consoleColorEscapeSequence[48;5;15m" // WHITE

    // Underline Colors
    override val UNDERLINE_BLACK = "$consoleColorEscapeSequence[4;30m"
    override val UNDERLINE_RED = "$consoleColorEscapeSequence[4;31m"
    override val UNDERLINE_GREEN = "$consoleColorEscapeSequence[4;32m"
    override val UNDERLINE_YELLOW = "$consoleColorEscapeSequence[4;33m"
    override val UNDERLINE_BLUE = "$consoleColorEscapeSequence[4;34m"
    override val UNDERLINE_PURPLE = "$consoleColorEscapeSequence[4;35m"
    override val UNDERLINE_CYAN = "$consoleColorEscapeSequence[4;36m"
    override val UNDERLINE_WHITE = "$consoleColorEscapeSequence[4;37m"
}