@file:Suppress("unused")

package com.bedalton.creatures.breed.render.support.att

import com.bedalton.creatures.common.structs.GameVariant
import com.bedalton.creatures.common.structs.isC2e
import com.bedalton.common.geometry.Point

/**
 * Holds all points in the line
 */
data class AttFileLine(val points: List<Point>) {
    operator fun get(index: Int): Point {
        return points[index]
    }

    fun getOrNull(index: Int): Point? {
        return points.getOrNull(index)
    }

    fun copyWithMovedPoint(point: Int, x: Int, y: Int): AttFileLine {
        return replaceInCopy(point) {
            Point(x, y)
        }
    }

    fun copyWithShiftedPoint(point: Int, offsetX: Int, offsetY: Int): AttFileLine {
        return replaceInCopy(point) { oldPoint ->
            Point(oldPoint.x + offsetX, oldPoint.y + offsetY)
        }
    }

    private inline fun replaceInCopy(point: Int, work: (old: Point) -> Point): AttFileLine {
        val points = points.alterInCopy(point, { Point(0, 0) }, work)
        return copy(
            points = points
        )
    }
}

/**
 * Holds data about the points in the ATT file by line
 */
data class AttFileData(val lines: List<AttFileLine>, val fileName: String? = null) {

    /**
     * Gets a specific line in an ATT file
     */
    operator fun get(index: Int): AttFileLine {
        return lines[index]
    }

    fun getOrNull(index: Int): AttFileLine? {
        return lines.getOrNull(index)
    }

    /**
     * Formats the ATT data object to proper ATT file text
     */
    fun toFileText(variant: GameVariant): String {
        return lines.toFileText(variant)
    }

    fun copyWithPointShifted(line: Int, point: Int, offsetX: Int, offsetY: Int): AttFileData {
        return replaceInCopy(line) { lineData ->
            lineData.copyWithShiftedPoint(point, offsetX, offsetY)
        }
    }

    fun copyWithMovedPoint(line: Int, point: Int, newX: Int, newY: Int): AttFileData {
        return replaceInCopy(line) { lineData ->
            lineData.copyWithMovedPoint(point, newX, newY)
        }
    }

    private inline fun replaceInCopy(line: Int, work: (old: AttFileLine) -> AttFileLine): AttFileData {
        val maxPoints = lines.maxOfOrNull { it.points.size } ?: 2
        val points = (0 until maxPoints).map { Point(0, 0) }
        val createLines: () -> AttFileLine = {
            AttFileLine(points)
        }
        return copy(
            lines = lines.alterInCopy(line, createLines, work)
        )
    }
}

/**
 * Formats the ATT data object to proper ATT file text
 */
internal fun List<AttFileLine>.toFileText(variant: GameVariant): String {
    val pointToString: (point: Int) -> ((point: Point) -> String) = if (variant.isC2e) {
        {
            pointToStringC2e
        }
    } else {
        val maxPoints = maxOf { it.points.size }
        val converters = (0 until maxPoints).map { i ->
            val xLength = maxOf { it.getOrNull(i)?.x?.toString()?.length ?: 0 }
            val yLength = maxOf { it.getOrNull(i)?.y?.toString()?.length ?: 0 }
            pointToStringC1e(xLength, yLength)
        };
        { point: Int ->
            converters[point]
        }
    }
    val out = StringBuilder()
    for (i in indices) {
        val line = get(i)
        val points = line.points
        for (pointI in points.indices) {
            if (pointI != 0) {
                out.append(' ')
            }
            out.append(pointToString(pointI)(points[pointI]))
        }
        out.append("\n")
    }
    return out.toString()
}

/**
 * Converts a point in the ATT file data object to an ATT file formatted string for Creatures 1/2
 */
private fun pointToStringC1e(xLength: Int, yLength: Int) = { point: Point ->
    "${point.x}".padStart(xLength, ' ') + " " + "${point.y}".padStart(yLength, ' ')
}

/**
 * Converts a point in the ATT file data object to an ATT file formatted string for Creatures 1/2
 */
private val pointToStringC2e = { point: Point ->
    "${point.x} ${point.y}"
}

private inline fun <T> Collection<T>.alterInCopy(index: Int, create: () -> T, work: (old: T) -> T): List<T> {
    return pad(index + 1, create).mapIndexed { i, item ->
        if (i == index) {
            work(item)
        } else {
            item
        }
    }
}

private inline fun <T> Collection<T>.pad(minimumSize: Int, create: () -> T): List<T> {
    if (this.size >= minimumSize) {
        return if (this is List) {
            this
        } else {
            this.toList()
        }
    }
    val list = this.toMutableList()
    while (list.size < minimumSize) {
        list.add(create())
    }
    return list
}