@file:Suppress("NON_EXPORTABLE_TYPE")
package com.bedalton.creatures.agents.pray.compiler.data

import com.bedalton.common.structs.ITuple
import com.bedalton.creatures.agents.pray.compiler.pray.PrayValidationError
import com.bedalton.creatures.agents.pray.data.PrayData
import kotlin.js.JsExport

/**
 * Data object for a parsed pray file
 */
@JsExport
data class CompilerPrayData(
    val language: TextValue?,
    val fullFilePath: String,
    val blocks: Array<CompilerPrayBlock>,
    val inlineFiles: Array<InlineFile>,
    val joinedFiles: Array<ITuple<String, CompilerPrayData>> = emptyArray(),
    val parseErrors: Array<PrayValidationError>,
    val unescape: Boolean,
) {

    @Suppress("unused")
    fun toCommonData(): PrayData {
        return PrayData(
            language?.text,
            fullFilePath,
            blocks = blocks.map { it.toCommonData() }.toTypedArray(),
            unescape
        )
    }

    override fun equals(other: Any?): Boolean {
        if (this === other) return true
        if (other !is CompilerPrayData) return false

        if (language != other.language) return false
        if (!blocks.contentEquals(other.blocks)) return false
        if (!inlineFiles.contentEquals(other.inlineFiles)) return false

        return true
    }

    override fun hashCode(): Int {
        var result = language.hashCode()
        result = 31 * result + blocks.contentHashCode()
        result = 31 * result + inlineFiles.contentHashCode()
        return result
    }

}