package com.creaturesforge.application.state


internal class MissingCompileParametersException(
    val missing: List<String>,
    message: String = defaultMessage(missing),
    throwable: Throwable? = null
): Exception(message, throwable) {
    
    companion object {
        internal fun defaultMessage(missing: List<String>): String {
            return "Missing compile parameters: $missing"
        }
    }
}