@file:Suppress("MemberVisibilityCanBePrivate")

package com.bedalton.creatures.agents.pray.compiler.pray

import com.bedalton.common.exceptions.CommonException
import kotlin.js.JsExport

@JsExport
open class PrayException(message:String, throwable: Throwable? = null) : CommonException(message, throwable)

class PrayInputException(message:String, throwable: Throwable? = null) : PrayException(message, throwable)

class PrayBlockNotImplementedException(
    val blockSimpleName:String,
    message:String = "$blockSimpleName PRAY blocks have not been implemented",
    throwable: Throwable? = null
) : PrayException(message, throwable)

open class PrayParseException(
    val lineNumber:Int,
    message: String,
    throwable: Throwable? = null
) : PrayException(message, throwable)

@JsExport
open class PrayParseValidationFailException(
    val lineNumber:Int,
    message: String,
    val errors:Array<PrayValidationError>,
    throwable: Throwable? = null
) : PrayException(message, throwable) {

    fun joinErrorsToString(delimiter: String, prefix: String = "", rootPath: String? = null): String {
        val files = errors.map { it.fullFilePath.lowercase() }.distinct()
        return if (rootPath != null && files.size > 1) {
            errors.joinToString(delimiter, prefix) { it.formatWithLineNumberRelativeTo(rootPath) }
        } else {
            errors.joinToString(delimiter, prefix, transform = PrayValidationError::formatWithLineNumber)
        }
    }
}

