package com.bedalton.creatures.caos.collectors.internal

import com.bedalton.common.ast.structs.inside
import com.bedalton.common.util.nullIfEmpty
import com.bedalton.creatures.caos.collectors.BlockRange
import com.bedalton.creatures.caos.collectors.CaosParserItem
import com.bedalton.creatures.caos.collectors.Script


internal fun scriptOffsetsToScriptsArray(
    scriptOffsets: Array<BlockRange>,
    items: Array<CaosParserItem>,
): Array<Script> {
    return scriptOffsets.mapNotNull script@{ range ->
        val scriptItems = items.filter { it.textRange inside range }
            .nullIfEmpty()
            ?.toTypedArray()
            ?: return@script null
        val command = (scriptItems.first().value as? String)?.trim()?.let { command ->
            when (command.uppercase()) {
                "SCRP" -> command
                "ISCR" -> command
                "RSCR" -> command
                else -> null
            }
        }
        Script(command, scriptItems, range)
    }.toTypedArray()
}
