package com.bedalton.creatures.caos.libs

import com.bedalton.creatures.caos.utils.caosSerializersModule
import kotlinx.serialization.json.Json


val caosJsonSerializer by lazy {
    Json {
        ignoreUnknownKeys = true
        serializersModule = caosSerializersModule
        encodeDefaults = true
        explicitNulls = true
        classDiscriminator = "json_type"
        isLenient = true
    }
}