package com.bedalton.creatures.agents.pray.compiler.data

import com.bedalton.common.structs.HasRange
import com.bedalton.creatures.agents.pray.compiler.*
import com.bedalton.creatures.agents.pray.compiler.SCRIPT_TAG_REGEX
import com.bedalton.creatures.agents.pray.compiler.getLinkFilenameReferenceText
import com.bedalton.creatures.agents.util.RelativeFileSystem
import kotlin.js.JsExport
import kotlin.js.JsName


internal typealias Tags = Array<Tag<*>>

@JsExport
sealed class Tag<T>(
    override val lineNumber: Int,
    open val originalLineNumber: Int,
    override val startIndex: Int,
    override val endIndex: Int,
    open val tagRange: TextValue,
    open val tag: String = tagRange.text,
    open val valueRange: TextValue,
    open val value: T,
): HasRange {

    abstract fun toPrayTag(): com.bedalton.creatures.agents.pray.data.Tag<*>

    data class StringTag(
        override val lineNumber: Int,
        override val originalLineNumber: Int,
        override val startIndex: Int,
        override val endIndex: Int,
        override val tagRange: TextValue,
        override val valueRange: TextValue,
        override val value: String
    ) : Tag<String>(
        lineNumber = lineNumber,
        originalLineNumber = originalLineNumber,
        startIndex = startIndex,
        endIndex = endIndex,
        tagRange = tagRange,
        valueRange = valueRange,
        value = value
    ) {

        @JsName("constructWithoutOriginalLineNumber")
        constructor(
            lineNumber: Int,
            startIndex: Int,
            endIndex: Int,
            tagRange: TextValue,
            value: TextValue,
        ) : this(
            lineNumber = lineNumber,
            originalLineNumber = lineNumber,
            startIndex = startIndex,
            endIndex = endIndex,
            tagRange = tagRange,
            valueRange = value,
            value = value.text
        )

        @JsName("constructWithValuesOnly")
        constructor(
            tag: String,
            value: String
        ) : this(
            lineNumber = -1,
            originalLineNumber = -1,
            startIndex = -1,
            endIndex = -1,
            tagRange = TextValue(tag, -1, -1, -1),
            valueRange = TextValue(value, -1, -1, -1),
            value = value
        )

        override fun toPrayTag(): com.bedalton.creatures.agents.pray.data.Tag.StringTag {
            return com.bedalton.creatures.agents.pray.data.Tag.StringTag(tag, value)
        }
    }

    data class LinkTag(
        override val lineNumber: Int,
        override val originalLineNumber: Int,
        override val startIndex: Int,
        override val endIndex: Int,
        override val tagRange: TextValue,
        override val valueRange: TextValue,
        override val value: String
    ) : Tag<String>(
        lineNumber = lineNumber,
        originalLineNumber = originalLineNumber,
        startIndex = startIndex,
        endIndex = endIndex,
        tagRange = tagRange,
        valueRange = valueRange,
        value = value
    ) {

        @JsName("constructWithoutOriginalLineNumber")
        constructor(
            lineNumber: Int,
            startIndex: Int,
            endIndex: Int,
            tagRange: TextValue,
            value: TextValue,
        ) : this(
            lineNumber = lineNumber,
            originalLineNumber = lineNumber,
            startIndex = startIndex,
            endIndex = endIndex,
            tagRange = tagRange,
            valueRange = value,
            value = value.text
        )

        internal suspend fun toStringTag(loader: RelativeFileSystem, linkWithFilenameReference: Boolean): StringTag {
            var text = loader.readAsText(value)
            if (linkWithFilenameReference && tagRange.text.matches(SCRIPT_TAG_REGEX) && getLinkFilenameReferenceFromCaosText(text) == null) {
                text = getLinkFilenameReferenceText(value) + text
            }
            return StringTag(
                lineNumber = lineNumber,
                originalLineNumber = originalLineNumber,
                startIndex = startIndex,
                endIndex = endIndex,
                tagRange = tagRange,
                valueRange = valueRange,
                value = text
            )
        }

        override fun toPrayTag(): com.bedalton.creatures.agents.pray.data.Tag.StringTag {
            return com.bedalton.creatures.agents.pray.data.Tag.StringTag(tag, value)
        }
    }
    /**
     * Tag object holding a string value
     */
    data class IntTag(
        override val lineNumber: Int,
        override val originalLineNumber: Int,
        override val startIndex: Int,
        override val endIndex: Int,
        override val tagRange: TextValue,
        override val valueRange: TextValue,
        override val value: Int,
    ) : Tag<Int>(
        lineNumber = lineNumber,
        originalLineNumber = originalLineNumber,
        startIndex = startIndex,
        endIndex = endIndex,
        tagRange = tagRange,
        valueRange = valueRange,
        value = value
    ), HasRange {
        @JsName("constructWithoutOriginalLineNumber")
        constructor(
            lineNumber: Int,
            startIndex: Int,
            endIndex: Int,
            tagRange: TextValue,
            value: TextValue,
            tagValue: Int,
        ) : this(
            lineNumber = lineNumber,
            originalLineNumber = lineNumber,
            startIndex = startIndex,
            endIndex = endIndex,
            tagRange = tagRange,
            valueRange = value,
            value = tagValue
        )
        @JsName("constructWithoutOriginalLineNumberOrLiteral")
        constructor(
            lineNumber: Int,
            startIndex: Int,
            endIndex: Int,
            tagRange: TextValue,
            value: TextValue
        ) : this(
            lineNumber = lineNumber,
            originalLineNumber = lineNumber,
            startIndex = startIndex,
            endIndex = endIndex,
            tagRange = tagRange,
            valueRange = value,
            value = value.text.trim().toInt()
        )

        @JsName("constructWithValuesOnly")
        constructor(
            tag: String,
            value: Int
        ) : this(
            lineNumber = -1,
            originalLineNumber = -1,
            startIndex = -1,
            endIndex = -1,
            tagRange = TextValue(tag, -1, -1, -1),
            valueRange = TextValue(value.toString(), -1, -1, -1),
            value = value
        )

        override fun toPrayTag(): com.bedalton.creatures.agents.pray.data.Tag.IntTag {
            return com.bedalton.creatures.agents.pray.data.Tag.IntTag(tag, value)
        }
    }
}
