package com.creaturesforge.application.ui

import com.bedalton.log.LOG_DEBUG
import com.bedalton.log.Log
import com.bedalton.log.iIf
import com.creaturesforge.application.util.JsArray
import com.creaturesforge.application.util.jsOb
import com.bedalton.common.exceptions.rethrowCancellationException
import kotlinx.coroutines.*
import tauri.dialog.*
import tauri.dialog.message
import kotlin.coroutines.resume
import kotlin.coroutines.resumeWithException
import kotlin.coroutines.suspendCoroutine

suspend fun openSingle(init: OpenDialogOptions.() -> Unit): String? {
    val options = jsOb(init)
    val fileOrFiles = open(options).await()
        ?: return null
    return fileOf(fileOrFiles)
}

suspend fun save(init: SaveDialogOptions.() -> Unit): String? {
    return suspendCancellableCoroutine<String?> { continuation ->
        val options = jsOb(init)
        try {
            save(options)
                .then {
                    continuation.resume(it)
                }
                .catch {
                    continuation.cancel(null)
                }
        } catch (e: Exception) {
            continuation.cancel(e)
            e.rethrowCancellationException()
        }
    }
}

suspend fun showMessageAndWait(message: String, init: (MessageDialogOptions.() -> Unit)? = null) {
    suspendCoroutine { continuation ->
        val options = if (init != null) {
            jsOb(init)
        } else {
            null
        }
        try {
            if (options != null) {
                message(message, options)
            } else {
                message(message)
            }.then { continuation.resume(Unit) }
        } catch (e: Exception) {
            continuation.resumeWithException(e)
        }
    }
}

internal fun message(message: String, init: (MessageDialogOptions.() -> Unit)? = null) {
    Log.iIf(LOG_DEBUG) { "Running TAURI message; WithContent: $message" }
    MainScope().launch {
        val options = if (init != null) {
            jsOb(init)
        } else {
            null
        }
        try {
            if (options != null) {
                message(message, options).await()
            } else {
                message(message).await()
            }
        } catch (e: Exception) {
            e.rethrowCancellationException()
        }
    }
}

internal fun fileOf(fileOrFiles: dynamic): String? {
    return when {
        jsTypeOf(fileOrFiles) == "string" -> fileOrFiles as? String
        JsArray.isArray(fileOrFiles) -> (fileOrFiles as? Array<String>)?.getOrNull(0)
        else -> null
    }
}