@file:Suppress("unused")

package com.bedalton.creatures.agents.pray.compiler.data

import com.bedalton.creatures.agents.pray.compiler.pray.PrayBlockNotImplementedException
import com.bedalton.creatures.agents.util.RelativeFileSystem
import com.bedalton.io.bytes.ByteStreamWriter
import kotlinx.coroutines.CoroutineScope
import kotlin.js.JsExport


/**
 * Generic Pray Block object
 */
@JsExport
sealed class CompilerPrayBlock(
    open val startLine: Int,
    open val blockTag: TextValue,
    open val blockName: TextValue,
) {

    internal abstract suspend fun write(coroutineScope: CoroutineScope, fs: RelativeFileSystem, writer: ByteStreamWriter, compression: Int)

    internal val label get() = "[$blockTag]->\"$blockName\""

    abstract fun toCommonData(): com.bedalton.creatures.agents.pray.data.PrayBlock

    class NotImplementedPrayBlock(
        startLine: Int,
        val commonName: String,
        blockTag: TextValue,
        blockName: TextValue,
    ) :
        CompilerPrayBlock(startLine, blockTag, blockName) {
        override suspend fun write(coroutineScope: CoroutineScope, fs: RelativeFileSystem, writer: ByteStreamWriter, compression: Int) {
            val error = if (commonName == blockTag.text)
                "Cannot write $blockTag block; Feature not implemented"
            else
                "Cannot write $commonName block (${blockTag.text}); Feature not implemented"
            throw PrayBlockNotImplementedException(error)
        }

        override fun toCommonData(): com.bedalton.creatures.agents.pray.data.PrayBlock {
            return com.bedalton.creatures.agents.pray.data.PrayBlock.NotImplementedPrayBlock(commonName, blockTag.text, blockName.text)
        }
    }

}



