@file:Suppress("unused", "MemberVisibilityCanBePrivate")

package com.bedalton.creatures.sprite.parsers

import com.bedalton.common.structs.AlreadyDisposedDataCacheException
import com.bedalton.common.structs.Tuple
import com.bedalton.creatures.sprite.util.ColorEncoding
import com.bedalton.creatures.sprite.util.ColorPalette
import com.bedalton.creatures.sprite.util.SpriteType
import com.bedalton.creatures.sprite.util.orThrow
import com.bedalton.io.bytes.ByteStreamReader
import com.bedalton.io.bytes.MemoryByteStreamReader
import com.bedalton.io.bytes.NotEnoughBytesException
import korlibs.image.bitmap.Bitmap32


/**
 * An object to hold BLK sprite data
 * Frames are parsed on demand by parent class
 */
class BlkSpriteFile(
    bytesBuffer: ByteStreamReader,
    progressChunkSize: Int? = null,
    progressCallback: ((current: Int, total: Int) -> Boolean?)? = null,
) : SpriteFile(SpriteType.BLK, true, null, progressChunkSize, progressCallback) {

    private var mCellsWide: Int = 0
    private var mCellsHigh: Int = 0

    val cellsWide get() = mCellsWide
    val cellsHigh get() = mCellsHigh

    override val allowAsync: Boolean get() = false



    private var mBytesBuffer: ByteStreamReader? = bytesBuffer

    private var mEncoding: ColorEncoding?  = null
    override val encoding: ColorEncoding
        get() = mEncoding ?: mBytesBuffer?.readAtPosition(0) {
            val flags = uInt32()
            (if (flags and 1L == 1L) ColorEncoding.X_565 else ColorEncoding.X_555).also {
                mEncoding = encoding
            }
        } ?: throw AlreadyDisposedDataCacheException("Cannot get encoding. Byte buffer already closed")

    private var mSize: Int? = null


    val progressCallback: ((index: Int) -> Boolean?)? by lazy {
        val theCallback = progressCallback
            ?: return@lazy null
        val totalCells = cellsWide * cellsHigh
        if (progressChunkSize == null || progressChunkSize <= 0) {
            { i: Int ->
                theCallback(i, totalCells)
            }
        } else {
            { i: Int ->
                if (i % progressChunkSize == 0 || (i + 1) == totalCells) {
                    theCallback(i + 1, totalCells)
                } else {
                    true
                }
            }
        }
    }

    override fun sizeInternal(): Int {
        mSize?.let {
            return it
        }
        val bytesBuffer = mBytesBuffer
            ?: throw SpriteParserException("Failed to get sprite frame count. File stream already closed")
        return SpriteParser.imagesCount("file.$extension", bytesBuffer)?.apply {
            mSize = this
        } ?: throw SpriteParserException("Failed to get sprite count from raw bytes")
    }


    override fun initFramesInternal(): List<SpriteFrameAsync> {
        val bytesBuffer = mBytesBuffer
            ?: throw SpriteParserException("Cannot initialize frames without data buffer")
        return bytesBuffer.readAtPosition(0) {
            initBlkFrames()
        }
    }

    /**
     * Close any internal streams, and release references
     */
    override fun closeInternal(): Boolean {
        return mBytesBuffer?.close()?.apply {
            mBytesBuffer = null
        } ?: true
    }

    private fun ByteStreamReader.initBlkFrames(): List<SpriteFrameAsync> {
        val totalBytes = size
        val flags = uInt32()
        mEncoding = if (flags and 1L == 1L) ColorEncoding.X_565 else ColorEncoding.X_555

        // Get number of cells wide/high
        val cellsWide = uInt16()
        val cellsHigh = uInt16()

        if (cellsWide == 0 || cellsHigh == 0) {
            throw SpriteParserException("BLK has no size; ByteStreamPosition: ${position()}")
        }
        // Set cells width/height for instance
        mCellsWide = cellsWide
        mCellsHigh = cellsHigh

        // Read total cells and validate
        val totalCells = uInt16()
        if (cellsWide * cellsHigh != totalCells) {
            throw SpriteParserException("Sprite cells width($cellsWide) x height($cellsHigh) do not match total cells($totalCells)")
        }
        val palette = encoding.toRgbWithTables(ColorPalette.OPAQUE_BLACK)
        var cancelled = false
        return (0 until totalCells).mapNotNull map@{ index ->
            if (cancelled) {
                return@map null
            }
            val offsetForData = uInt32() + 4
            if (offsetForData + CELL_BYTES_SIZE > totalBytes) {
                throw SpriteParserException("Invalid byte offset[$index]. Expected < ${totalBytes - CELL_BYTES_SIZE}. Found: $offsetForData")
            }
            val width = uInt16()
            if (width != BLOCK_SIZE) {
                throw SpriteParserException("BLK cell width invalid. Expected 128; Actual: $width")
            }
            val height = uInt16()
            if (height != BLOCK_SIZE) {
                throw SpriteParserException("BLK cell height invalid. Expected 128; Actual: $height")
            }

            var buffer: ByteStreamReader? = this.copyOfRange(offsetForData.toInt(), width * height * 2)

            SpriteFrameAsyncImpl(width, height, palette, true, { buffer?.close(); buffer = null }) {
                buffer.orThrow().parseBlkEx(
                    width = width,
                    height = height
                )
            }.also {
                if (progressCallback?.invoke(index) == false) {
                    cancelled = true
                }
            }
        }
    }

    companion object {
        const val BLOCK_SIZE = 128
        const val CELL_BYTES_SIZE = BLOCK_SIZE * BLOCK_SIZE * 2
        const val ASYNC_DEFAULT = false
        const val FLATTEN_BY_DEFAULT = true
        const val TRIM_BY_DEFAULT = true

        /**
         * Gets the size of this BLK in cells wide and high
         */
        @Deprecated(
            "Use ByteStreamReader equivalent instead",
            replaceWith = ReplaceWith("BlkSpriteFile.sizeInCells(MemoryByteStreamReader(byteArray))"),
            level = DeprecationLevel.WARNING
        )
        fun sizeInCells(byteArray: ByteArray): Tuple<Int, Int> {
            return sizeInCells(MemoryByteStreamReader(byteArray))
        }

        /**
         * Gets the size of this BLK in cells wide and high
         */
        fun sizeInCells(byteReader: ByteStreamReader): Tuple<Int, Int> {
            val totalBytes = byteReader.size
            if (totalBytes < 8) {
                throw NotEnoughBytesException("Too few bytes to determine BLK size in cells")
            }
            return byteReader.readAtPosition(4) {
                // Get number of cells wide/high
                val cellsWide = uInt16()
                val cellsHigh = uInt16()
                Tuple(cellsWide, cellsHigh)
            }
        }

        /**
         * Gets this BLK stitched from already parsed sprite frames
         */
        fun getStitched(
            cellsWide: Int,
            cellsHigh: Int,
            frames: List<Bitmap32>,
            progressCallback: ((current: Int, total: Int) -> Unit)?,
        ): Bitmap32 {
            return BlkParser.getStitched(cellsWide, cellsHigh, frames, progressCallback)
        }
    }
}

/**
 * The result of a blk sprite parse operation
 * Data returned is required to stitch an object together later
 */
class BlkParseResult(
    val imageData: List<Bitmap32>,
    val cellsWide: Int,
    val cellsHigh: Int,
)

private fun ByteStreamReader.parseBlkEx(width: Int, height: Int): PixelIndices {
    val image = IntArray(width * height) { 0 }
    for (y in 0 until height) {
        val offsetY = y * width
        for (x in 0 until width) {
            val pixel = uInt16()
            image[offsetY + x] = pixel
        }
    }
    return PixelIndices(width, height, image)
}