package com.bedalton.common.structs

import kotlinx.serialization.SerialName
import kotlinx.serialization.Serializable


expect interface ITuple<T1,T2> {
    val first:T1
    val second:T2
}

@Serializable
@SerialName("tuple")
data class Tuple<T1,T2>(
    override val first:T1,
    override val second:T2
) : ITuple<T1,T2>

expect interface IMutableTuple<T1,T2> {
    var first:T1
    var second:T2
}

@Serializable
@SerialName("mtuple")
data class MutableTuple<T1,T2>(
    override var first:T1,
    override var second:T2
) : IMutableTuple<T1,T2>


@Serializable
open class Pointer<T>(
    var value:T
) {
    override fun toString(): String {
        return value.toString()
    }

    override fun equals(other: Any?): Boolean {
        if (other == null) {
            return false
        }
        if (super.equals(other)) {
            return true
        }
        if (other is Pointer<*>) {
            return other.value == this.value
        }
        return this.value == other
    }

    override fun hashCode(): Int {
        return value?.hashCode() ?: 0
    }


}


expect interface HasSize {
    val width: Int
    val height: Int
}

@Serializable
data class Size(
    override val width: Int,
    override val height: Int
): HasSize