package com.creaturesforge.application.state

import com.bedalton.creatures.common.structs.BreedKey
import com.bedalton.log.Log
import com.bedalton.state.simple.Dispatch
import com.bedalton.state.simple.Next
import kotlinx.coroutines.GlobalScope
import kotlinx.coroutines.launch


internal fun filesListMiddleware(
    state: ForgeState,
    action: FAction,
    dispatch: Dispatch<FAction>,
    next: Next<ForgeState, FAction>,
): FAction {
    GlobalScope.launch {
        try {
            spriteFileMiddleware(state, action, dispatch)
        } catch (e: dynamic) {
            Log.e("Failed to run spriteFileMiddleware; ${e.formatted(true)}")
        }
        try {
            attFileMiddleware(state, action, dispatch)
        } catch (e: dynamic) {
            Log.e("Failed to run attFileMiddleware; ${e.formatted(true)}")
        }
    }
    return next(state, action, dispatch)
}

internal fun getPartsInFilesForBreedKey(breedKey: BreedKey, filenamesWithExtension: List<String>): List<Char> {
    val key = "[a-nA-N]${breedKey.code!!}\\.(att|c16)".toRegex(RegexOption.IGNORE_CASE)
    return filenamesWithExtension.filter(key::matches).map {
        it[0].uppercaseChar()
    }
}
