package com.bedalton.creatures.caos.validation.internal

import com.bedalton.creatures.caos.collectors.CaosParserItem
import com.bedalton.creatures.caos.libs.CaosLibs
import com.bedalton.creatures.caos.libs.ErrorTypes
import com.bedalton.creatures.caos.utils.token

internal fun addLooseParserItemErrors(
    looseParserItems: Array<CaosParserItem>,
    errors: MutableList<CaosParserItem.ErrorVal>
) {
    for (item in looseParserItems) {
        val error = if (item is CaosParserItem.ErrorVal) {
            item
        } else if (item is CaosParserItem.CommandToken) {
            if (item.value.length != 4 || CaosLibs.commands(intArrayOf(token(item.value)))?.first.isNullOrEmpty()) {
                CaosParserItem.ErrorVal(
                    textRange = item.textRange,
                    message = "Invalid input '${item.value}'",
                    type = ErrorTypes.GENERAL,
                    text = item.text
                )
            } else {
                CaosParserItem.ErrorVal(
                    textRange = item.textRange,
                    message = "Unexpected command token '${item.value}'",
                    type = ErrorTypes.GENERAL,
                    text = item.text
                )
            }
        } else {
            CaosParserItem.ErrorVal(
                textRange = item.textRange,
                message = "Unexpected value '${item.value}'",
                type = ErrorTypes.GENERAL,
                text = item.text
            )
        }
        errors.add(error)
    }
}