package com.bedalton.creatures.agents.pray.compiler.pray.validators

import com.bedalton.common.structs.HasRange
import com.bedalton.common.util.like
import com.bedalton.common.util.nullIfEmpty
import com.bedalton.creatures.agents.pray.compiler.pray.PrayValidationError
import com.bedalton.creatures.agents.pray.compiler.data.CompilerPrayBlock
import com.bedalton.creatures.agents.pray.compiler.data.Tag

// Helper lambda to add block validation errors to errors list
internal typealias AddError = (range: HasRange, message: String) -> Unit


internal fun addErrorLambda(fullFilePath: String, errors:MutableList<PrayValidationError>, block: CompilerPrayBlock): AddError {

    // Create add agent helper lambda
    return { range, message ->
        errors.add(
            PrayValidationError.BlockValidationError(
                blockTag = block.blockTag,
                blockName = block.blockName,
                lineNumber = range.lineNumber,
                startIndex = range.startIndex,
                endIndex = range.endIndex,
                message = message,
                fullFilePath = fullFilePath
            )
        )
    }
}

/**
 * Validates that "Agent Type" tag is '0' for inject-ability
 */
internal fun validateHasAgentType0(
    addError: AddError,
    tags: Array<Tag<*>>
) {
    val agentTypeTags = tags
        .filter { it.tag like "Agent Type" }
        .nullIfEmpty()
        ?: return
    for (tag in agentTypeTags) {
        if (tag is Tag.IntTag) {
            if (tag.value == 0)
                continue
            addError(
                tag,
                "!WARNAgent may not be injectable without \"Agent Type\" 0"
            )
        } else {
            addError(
                tag.valueRange,
                "\"Agent Type\" tag value should be an integer"
            )
        }
    }
}