package com.bedalton.creatures.genetics.parser

import com.bedalton.common.util.className
import com.bedalton.common.util.formatted
import com.bedalton.common.util.orElse
import com.bedalton.creatures.common.util.token
import com.bedalton.creatures.genetics.gene.Gene
import com.bedalton.creatures.genetics.genome.Genome
import com.bedalton.creatures.genetics.utils.trimTrailing
import com.bedalton.io.bytes.*

object GenomeParser {

    private val GENE_TOKEN = token("gene")
    private val GEXT_TOKEN = token("gext")
    private val GEND_TOKEN = token("gend")

    fun parseGenome(reader: ByteStreamReader, skipInvalidData: Boolean): Genome {
        val version = getVersion(reader)
        if (version == 1) {
            reader.setPosition(0)
        } else {
            reader.setPosition(4)
        }
        val genes = mutableListOf<Gene>()
        var previousGene: Gene? = null
        val geneOfTypeCount = mutableMapOf<String, Int>()
        var reachedEnd = false
        var geneIndex = 0
        try {
            var next: NextMagic?
            while (true) {
                val position = reader.position()
                next = reader.nextMagic()

                val valid = reachedEnd || (next != null && next.index == position)
                if (!valid && !skipInvalidData) {
                    throw throw InvalidGeneHeaderSequenceException(
                        "Expected gene magic: Expected <GENE> or <GEND>; Found: <${
                            reader.stringUTF8(
                                4
                            )
                        }> @ ${next?.index}; Position: $position"
                    )
                }
                if (next == null) {
                    break
                } else if (next.index != position) {
                    // If there was a previous gene, attach this trailing data to it
                    if (previousGene != null) {
                        val length = next.index - position
                        previousGene.unexpectedInvalidTrailingData =
                            (previousGene.unexpectedInvalidTrailingData ?: emptyList()) + reader.bytes(length)
                    }
                }

                // Delayed here to pick up any trailing data
                if (reachedEnd) {
                    break
                }
                reader.skip(4)
                when (next.token) {
                    GENE_TOKEN -> {
                        val gene = readGene(version, geneIndex++, reader)
                        genes.add(gene)
                        previousGene = gene
                        val kClass = gene.className
                            ?: continue
                        geneOfTypeCount[kClass] = geneOfTypeCount.getOrElse(kClass) { 0 } + 1
                    }

                    GEXT_TOKEN -> {
                        if (previousGene == null) {
                            throw GenomeParseException("Gene extra data (GEXT) found before any gene")
                        }
                    }

                    GEND_TOKEN -> {
                        if (!skipInvalidData && next.index != position && previousGene == null) {
                            throw GenomeParseException("Only invalid data found before genome end token")
                        }
                        reachedEnd = true
                    }
                }
            }
        } catch (e: InvalidGeneHeaderSequenceException) {
            if (geneOfTypeCount[previousGene?.className ?: ""].orElse(0) <= 1) {
                throw InvalidGeneHeaderSequenceException("Header failed after first time reading gene of type: ${previousGene?.typeName}::${previousGene?.subtypeName}]; ${e.formatted(true)}; ", e)
            } else {
                throw InvalidGeneHeaderSequenceException("Header failed after gene: ${previousGene?.typeName}::${previousGene?.subtypeName}]; Count of Gene: ${
                        geneOfTypeCount.getOrElse(
                            previousGene.className ?: ""
                        ) { 0 }
                    }", e
                )
            }
        }
        val originalSize = reader.size.toInt()
        return Genome(version, genes.toTypedArray(), originalSize)
    }

    fun parseGenome(bytes: ByteArray, skipInvalidData: Boolean = false): Genome {
        return ByteStreamReader.read(bytes) {
            parseGenome(this, skipInvalidData)
        }
    }

    @Suppress("unused")
    fun parseGenomeUsing(reader: ByteStreamReader, skipInvalidData: Boolean = false): Genome {
        val genome = parseGenome(reader, skipInvalidData)
        reader.close()
        return genome
    }

    private fun readGene(version: Int, geneIndex: Int, reader: ByteStreamReader): Gene {
        return when (val type = reader.uInt8()) {
            0 -> readBrainGene(version, reader, geneIndex)
            1 -> readBioChemicalGene(version, reader, geneIndex)
            2 -> readCreatureGene(version, reader, geneIndex)
            3 -> readOrgan(version, reader, geneIndex)
            else -> throw GenomeParseException("Invalid gene type: $type @ ${reader.position()-1L}")
        }.also {
            reader.trimTrailing(version)
        }
    }

    private fun getVersion(reader: ByteStreamReader): Int {
        val version = reader.readAtPosition(0) {
            val magic = string(4)
            if (magic == "gene") {
                1
            } else if (magic[0] == 'd' && magic[1] == 'n' && magic[2] == 'a') {
                magic[3].digitToInt()
            } else {
                throw InvalidGenomeFileHeaderException("Invalid genome header sequence. Expected <gene>, <dna2> or <dna3>; Found: $magic")
            }
        }
        return version
    }

    private fun hasNext(i: Int, reader: ByteStreamReader): Boolean {
        return when (val magic = reader.peakToken(i)) {
            GENE_TOKEN -> true
            GEND_TOKEN -> false
            GEXT_TOKEN -> false
            null -> false
            else -> throw InvalidGeneHeaderSequenceException(
                "Expected gene magic: Expected <GENE> or <GEND>; Found: <${
                    token(
                        magic
                    )
                }>"
            )
        }
    }

    private fun ByteStreamReader.nextMagic(): NextMagic? {
        val index = offsetToNextTokenOrNull(GENE_TOKEN, GEXT_TOKEN, GEND_TOKEN)
            ?: return null
        val token = peakToken(index.toInt())
            ?: return null
        return NextMagic(position() + index, token)
    }
}

data class NextMagic(val index: Long, val token: Int) {
    val tokenAsString: String by lazy { token(token) }
}