package com.bedalton.creatures.agents.pray.compiler.caos2pray

/**
 * Exception for errors in the Friendliness file format
 *
 * @property line line number in file where error occurred
 */
class FriendlinessParseException(
    val line: String,
    message: String = "Failed to parse tag friendliness.nice line '$line'",
    throwable: Throwable? = null
) : Caos2PrayException(message, throwable)