package com.creaturesforge.application.ui.pages

import com.bedalton.log.Log
import com.bedalton.state.simple.Dispatch
import com.creaturesforge.application.state.AddEgg
import com.creaturesforge.application.state.DeleteEgg
import com.creaturesforge.application.state.FAction
import com.creaturesforge.application.state.ForgeStore
import com.creaturesforge.application.ui.controls.ProjectRootInput
import com.creaturesforge.application.ui.controls.*
import com.creaturesforge.application.ui.html.*
import kotlinx.browser.window
import org.w3c.dom.HTMLButtonElement
import org.w3c.dom.HTMLElement
import org.w3c.dom.HTMLInputElement
import org.w3c.dom.HTMLSelectElement
import org.w3c.dom.events.KeyboardEvent

internal class Page(private val root: HTMLElement) : Validatable {

    val pageNumber by root.dataInt("page")

    private val viewMode by lazy {
        AppEggMode.parseEggMode(body.getAttribute("data-page-for"), "Page $pageNumber")
    }

    private var status by body.dataString("page-$pageNumber-status", "")
        .default("")

    private lateinit var dispatch: Dispatch<FAction>
    private var didInit = false
    private var validatables: List<Validatable> = emptyList()

    init {
        Log.i("Initializing page: $pageNumber")
        didInit = true
        ForgeStore.subscribe { _, dispatch ->
            this@Page.dispatch = dispatch
        }
        initControls()
        initListeners()
        Log.i("Initialized page: $pageNumber")
    }

    private fun initControls() {
        initGlyphControls()
        initGenomeControls()
        initProjectRootControls()
        initGenomeGenusSelects()
        initOutputSlotControls()
        initAttSlotControls()
        initAttRootControls()
        initSpriteSlotControls()
        initEggControls()
    }

    private fun initListeners() {
        root.addEventListener("blur", {
            validate()
        })
        root.addEventListener("keydown", { e ->
            if (e.unsafeCast<KeyboardEvent>().keyCode == 13) {
                validate()
            }
        })
    }

    fun isComplete(): Boolean {
        return validatables.all(Validatable::isValid)
    }

    fun validate() {
        if (isValid()) {
            onValid()
        } else {
            onInvalid()
        }
    }

    private fun onValid() {
        clearErrors()
        status = ""
    }

    private fun onInvalid() {
        highlightErrors()
        status = "error"
    }

    override fun isValid(): Boolean {
        if (viewMode != AppEggMode.eggModeOrDefault) {
            return true
        }
        return validatables.all(Validatable::isValid)
    }

    private fun initGlyphControls() {
        validatables += root
            .withRole<HTMLElement>("glyph")
            .map { select: HTMLElement ->
                GlyphSelect(select)
            }
    }

    private fun initGenomeControls() {
        validatables += root
            .querySelectorAll("[data-role='genome-control']")
            .map { element: HTMLElement ->
                GenomeControl(element)
            }
    }

    private fun initGenomeGenusSelects() {
        validatables += root
            .withRole<HTMLSelectElement>("genome-genus-select")
            .map { GenusSelect(it) }
    }


    private fun initProjectRootControls() {
        validatables += root
            .fromRole("project-root-control") {
                ProjectRootInput(it)
            }
    }

    private fun initSpriteSlotControls() {
        validatables += root.fromRole("sprite-breed-slot") {
            SpriteBreedSlot(it.unsafeCast<HTMLSelectElement>())
        }
    }

    private fun initOutputSlotControls() {
        validatables += root.fromRole("output-breed-slot") {
            OutputBreedSlot(it.unsafeCast<HTMLSelectElement>())
        }
    }

    private fun initAttSlotControls() {
        validatables += root.fromRole("att-breed-slot") {
            AttBreedSlot(it.unsafeCast<HTMLSelectElement>())
        }
    }

    private fun initAttRootControls() {
        validatables += root
            .fromRole("att-root-control") {
                AttRootInput(it)
            }
    }


    private fun initEggControls() {
        root.withRole<HTMLSelectElement>("egg-select")
            .forEach {
                EggSelect(it)
            }

        validatables += root.fromRole("egg-name-input") {
            EggNameInput(it as HTMLInputElement)
        }

        root.withRole<HTMLButtonElement>("egg-delete-button")
            .forEach {
                it.onclick = {
                    dispatch(DeleteEgg)
                }
            }

        root.withRole<HTMLButtonElement>("add-egg-button")
            .forEach {
                it.onclick = {
                    dispatch(AddEgg)
                }
            }
    }

    override fun highlightErrors() {
        validatables.forEach { it.highlightErrors() }
    }

    fun clearErrors() {
        root.querySelectorAll("[data-is-valid='false']").forEach<HTMLElement> {
            it.removeAttribute("data-is-valid")
        }
    }
}