package com.bedalton.vfs

import com.bedalton.vfs.internal.MD5
import com.bedalton.vfs.internal.toHexString
import kotlinx.coroutines.await
import kotlin.js.Promise


@JsExport
external interface JsFile {
    @JsName("name")
    val name: String
    @JsName("mimeType")
    val mimeType: String?
    @JsName("bytes")
    val bytes: Promise<ByteArray>
    @JsName("disposeExtra")
    val disposeExtra: (() -> Unit)?
}

internal class JsPromiseBasedFile(
    override val name: String,
    override val mimeType: String?,
    bytes: Promise<ByteArray>,
    private var disposeExtra: (() -> Unit)? = null
): MemoryFile() {

    private var mBytesPromise: Promise<ByteArray?>? = bytes

    private var mBytes: ByteArray? = null

    override suspend fun md5(): String {
        val bytes = read()
        return MD5.compute(bytes).toHexString()
    }

    override suspend fun read(): ByteArray {
        assertNotDisposed()

        mBytes?.let { return it }
        val bytesPromise = mBytesPromise
            ?: throw NullPointerException("File: $name was set to null bytes")
        val bytes = bytesPromise
            .await()
            ?: throw NullPointerException("File JSFile $name was created with null bytes")
        mBytes = bytes
        mBytesPromise = null
        return bytes
    }

    override fun disposeInternal() {
        disposeExtra?.invoke()
        disposeExtra = null
        mBytesPromise = null
        mBytes = null
    }
}

internal fun JsFile.toFile(): File {
    return JsPromiseBasedFile(
        name = name,
        mimeType = mimeType,
        bytes = bytes,
        disposeExtra = disposeExtra
    )
}