@file:Suppress("unused")

package com.bedalton.creatures.breed.render.support.render

import kotlinx.serialization.Serializable
import kotlin.js.JsExport
import kotlin.jvm.JvmStatic

@Serializable
@JsExport
enum class PartVisibility(val int: Int) {
    VISIBLE(1),
    GHOST(2),
    HIDDEN(3);
    companion object {
        @JvmStatic
        fun fromInt(int: Int): PartVisibility? {
            return when (int) {
                VISIBLE.int -> VISIBLE
                GHOST.int -> GHOST
                HIDDEN.int -> HIDDEN
                else -> return null
            }
        }
    }
}