package com.bedalton.common.ast.collectors

import com.bedalton.common.ast.structs.HasRange
import com.bedalton.common.ast.structs.Range
import com.bedalton.common.ast.structs.RangeWithIndex
import kotlin.js.JsExport

/**
 * Object of an item and its distance to a line and column
 */
@JsExport
data class Distanced<T : HasRange>(
    val item: T,
    val distance: Distance,
)

/**
 * Distance between two positions
 */
@JsExport
data class Distance(
    val lineOffset: Int,
    val columnOffset: Int,
)


/**
 * Gets an items distance from a given line and column
 * @param range
 * @param lineNumber
 * @param column
 */
fun getDistanceFromStart(range: RangeWithIndex, lineNumber: Int, column: Int): Distance {
    return Distance(
        lineOffset = lineNumber - range.start.line,
        columnOffset = if (lineNumber == range.start.line) {
            (column - range.start.character)
        } else {
            range.start.character
        }
    )
}

/**
 * Gets an items distance from a given line and column
 * @param range
 * @param lineNumber
 * @param column
 */
fun getDistanceFromEnd(range: RangeWithIndex, lineNumber: Int, column: Int): Distance {
    return Distance(
        lineOffset = lineNumber - range.end.line,
        columnOffset = if (lineNumber == range.end.line) {
            (column - range.end.character)
        } else {
            range.end.character
        }
    )
}

@Deprecated(
    "Use getDistanceFromStart(), getDistanceFromEnd(), or getDistanceFromNearestEdge()",
    replaceWith = ReplaceWith(
        "getDistanceFromNearestEdge(range, lineNumber, column)",
        imports = ["com.bedalton.common.ast.collectors.getDistanceFromNearestEdge"]
    )
)
fun getDistance(range: Range, lineNumber: Int, column: Int): Distance {
    return getDistanceFromNearestEdge(range, lineNumber, column)
}

fun getDistanceFromNearestEdge(range: Range, lineNumber: Int, column: Int): Distance {
    return getDistance(range, lineNumber, column, false)
}

fun getAbsoluteDistanceFromNearestEdge(range: Range, lineNumber: Int, column: Int): Distance {
    return getDistance(range, lineNumber, column, true)
}

fun getDistance(range: Range, lineNumber: Int, column: Int, absolute: Boolean): Distance {
    if (lineNumber == range.start.line) {
        if (column >= range.start.character) {
            if (lineNumber < range.end.line) {
                return Distance(0, 0)
            } else if (column <= range.end.character) {
                return Distance(0, 0)
            }
        }
    }

    val point = if (lineNumber == range.end.line) {
        // Means start line is less
        if (column <= range.end.character) {
            return Distance(0, 0)
        } else {
            range.end
        }
    } else {
        range.start
    }

    var characterDistance = if (lineNumber == point.line) {
        column - point.character
    } else {
        point.character
    }

    if (absolute && characterDistance < 0) {
        characterDistance *= -1
    }

    return Distance(
        lineOffset = lineNumber - point.line,
        columnOffset = characterDistance
    )
}
