package com.creaturesforge.application.util

import com.bedalton.common.coroutines.launch
import com.bedalton.common.util.trySilent
import com.bedalton.log.Log
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.CoroutineStart
import kotlinx.coroutines.Job


internal fun launchJob(
    start: CoroutineStart = CoroutineStart.DEFAULT,
    block: suspend (scope: CoroutineScope) -> Unit
): Job {
    val job = Job()
    job.launch(start, block)
    return job
}

internal fun launchCatching(
    start: CoroutineStart = CoroutineStart.DEFAULT,
    block: suspend (scope: CoroutineScope) -> Unit
): Job {
    val job = Job()
    trySilent {
        val scope = CoroutineScope(job)
        job.launch(start) {
            trySilent {
                block(scope)
            }
        }
    }
    return job
}