package com.bedalton.common.ast.structs

import kotlinx.serialization.Serializable
import org.antlr.v4.kotlinruntime.ParserRuleContext
import org.antlr.v4.kotlinruntime.Token
import org.antlr.v4.kotlinruntime.ast.Point
import kotlin.js.JsExport
import kotlin.js.JsName

/**
 * Concrete implementation of an RangeWithIndex which represents a range within a documents,
 * with the addition of its absolute start and end character indices within the file
 */
@Suppress("NON_EXPORTABLE_TYPE")
@JsExport
@Serializable
data class RangeWithIndexImpl(
    override val start: Position,
    override val end: Position,
    override val startIndex: Int,
    override val endIndex: Int,
    override val parserIndex: Int? = null,
) : RangeWithIndex {

    init {
        this.assertIsValid()
    }

    companion object {

        @JsName("__kotlin__only__withParserRuleContext")
        fun create(ctx: ParserRuleContext, parserIndex: Int? = null): RangeWithIndex {
            val start = ctx.start
            val stop = ctx.stop ?: start

            if (start != null && stop != null) {
                if (stop.line < start.line) {
                    return create(start, start)
                } else if (stop.line == start.line && stop.charPositionInLine <= start.charPositionInLine) {
                    return create(start, start)
                }
            }

            val position = ctx.getPositionSafe()

            val startPosition = position?.start
            if (start == null && startPosition == null) {
                throw NullPointerException("Start position cannot be null")
            }

            if (stop == null) {
                throw NullPointerException("Stop position cannot be null")
            }

            val stopPosition = furthestPoint(start, stop)

            val startIndex = (start?.startIndex ?: 0)

            val endIndex = maxOf((stop.stopIndex) - 1, startIndex)

            val startLine = (start?.line ?: startPosition?.line)
                ?: throw NullPointerException("Line cannot be null")
            val startColumn = minByWithNulls(start?.charPositionInLine, startPosition?.column)
                ?: throw NullPointerException("Start column cannot be null")

            val stopLine = stop.line
            val stopColumn = maxByWithNulls(stop.charPositionInLine, stopPosition.column, furthestChar(start, stop))
                ?: throw NullPointerException("stop column cannot be null")


            return RangeWithIndexImpl(
                startIndex = startIndex,
                endIndex = endIndex,
                start = PositionImpl(
                    line = startLine - 1,
                    character = startColumn.sub1OrZero(),
                ),
                end = PositionImpl(
                    line = stopLine - 1,
                    character = stopColumn.sub1OrZero()
                ),
                parserIndex = parserIndex
            )
        }

        @JsName("__kotlin__only__withStartEndTokens")
        fun create(start: Token, end: Token, parserIndex: Int? = null): RangeWithIndexImpl {
            return create(
                start,
                end,
                parserIndex,
                0,
                0,
                0
            )
        }

        @JsName("__kotlin__only__withStartEndTokensAndOffset")
        fun create(
            start: Token,
            end: Token,
            parserIndex: Int?,
            offsetIndex: Int,
            offsetLine: Int,
            offsetColumn: Int = 0,
        ): RangeWithIndexImpl {

            var endColumn = if (start.line == end.line) {
                end.charPositionInLine + (start.text?.length ?: (end.charPositionInLine - start.charPositionInLine))
            } else {
                end.charPositionInLine
            }

            if (end.line == start.line && endColumn == start.charPositionInLine || (endColumn-1) == start.charPositionInLine) {
                endColumn = maxByWithNulls(start.charPositionInLine + (end.stopIndex - start.startIndex), endColumn, start.endPoint()?.column) ?: end.charPositionInLine
            }

            if (end.line == 1) {
                endColumn += offsetColumn
            }

            val offsetStartIndex = start.startIndex + offsetIndex
            val offsetEndIndex = end.stopIndex + offsetIndex
            val startColumn = (start.charPositionInLine + (if (start.line == 1) offsetColumn else 0))

            if (start.line == end.line) {
                endColumn = maxOf(endColumn, startColumn, 0)
            }

            return RangeWithIndexImpl(
                startIndex = offsetStartIndex,
                endIndex = maxOf(offsetEndIndex, offsetStartIndex),
                start = PositionImpl(
                    line = (start.line - 1) + offsetLine,
                    character = startColumn.sub1OrZero()
                ),
                end = PositionImpl(
                    line = (end.line - 1) + offsetLine,
                    character = endColumn.sub1OrZero()
                ),
                parserIndex = parserIndex
            )
        }


        @JsName("__kotlin__only__withStartEndPointsAndOffset")
        fun create(
            start: Point,
            end: Point,
            startIndex: Int,
            endIndex: Int,
            parserIndex: Int?,
            offsetIndex: Int,
            offsetLine: Int,
            offsetColumn: Int = 0,
        ): RangeWithIndexImpl {

            val trueEnd = furthestPoint(start, end)!!

            val offsetStartIndex = startIndex + offsetIndex
            val offsetEndIndex = endIndex + offsetIndex
            return RangeWithIndexImpl(
                startIndex = offsetStartIndex,
                endIndex = maxOf(offsetEndIndex, offsetStartIndex),
                start = PositionImpl(
                    line = (start.line - 1) + offsetLine,
                    character = (start.column + (if (start.line == 1) offsetColumn else 0)).sub1OrZero()
                ),
                end = PositionImpl(
                    line = (trueEnd.line - 1) + offsetLine,
                    character = if (start.line == trueEnd.line) {
                        trueEnd.column + (if (trueEnd.line == 1) offsetColumn else 0)
                    } else {
                        trueEnd.column
                    }.sub1OrZero()
                ),
                parserIndex = parserIndex
            )
        }

        @JsName("__kotlin__only__withStartEndAntlrPointsAndOffset")
        fun create(
            start: Point,
            stop: Point?,
            startIndex: Int,
            stopIndex: Int,
            parserIndex: Int?,
        ): RangeWithIndexImpl {
            val stopNotNull = furthestPoint(stop, start)!!
            return RangeWithIndexImpl(
                startIndex = startIndex,
                endIndex = maxOf(stopIndex, startIndex),
                start = PositionImpl(
                    line = start.line - 1,
                    character = start.column.sub1OrZero()
                ),
                end = PositionImpl(
                    line = stopNotNull.line - 1,
                    character = if (stopNotNull.line == start.line) {
                        maxOf(0, start.column, stopNotNull.column)
                    } else {
                        stopNotNull.column
                    }.sub1OrZero()
                ),
                parserIndex = parserIndex
            )
        }
    }
}


fun minByWithNulls(vararg values: Int?): Int? {
    return values.filterNotNull().minOrNull()
}


fun maxByWithNulls(vararg values: Int?): Int? {
    return values.filterNotNull().maxOrNull()
}

fun Int.sub1OrZero(): Int {
    return if (this > 0) {
        this - 1
    } else {
        0
    }
}

fun furthestChar(start: Token?, end: Token?): Int {
    if (start != null && start.line == end?.line) {
        start.text?.length?.let {
            return start.charPositionInLine + it
        }
    }
    return furthestPoint(start, end).column
}

fun furthestPoint(start: Token?, end: Token?): Point {
    return furthestPoint(
        start?.startPoint(),
        start?.endPoint(),
        end?.endPoint(),
        end?.startPoint()
    ) ?: throw NullPointerException("No valid point data found in tokens")
}


fun furthestPoint(vararg points: Point?): Point? {
    val pointsNotNull = points.filterNotNull()

    if (pointsNotNull.isEmpty()) {
        return null
    }
    if (pointsNotNull.size == 1) {
        return points[0]
    }
    var currentPoint: Point = pointsNotNull.first()
    for (point in pointsNotNull.drop(1)) {
        if (point.line < currentPoint.line) {
            continue
        }
        if (point.line > currentPoint.line) {
            currentPoint = point
            continue
        }
        if (point.column > point.column) {
            currentPoint = point
        }
    }
    return currentPoint
}


fun ParserRuleContext.getPositionSafe(): org.antlr.v4.kotlinruntime.ast.Position? {
    val start = start
        ?: return null
    return try {
        position
    } catch (_: Throwable) {
        try {
            org.antlr.v4.kotlinruntime.ast.Position(start.startPoint(), start.startPoint())
        } catch (_: Exception) {
            null
        }
    }
}