package com.bedalton.creatures.agents.util.internal


private const val C3DS_REGEX = "(?:[Cc]3|[Dd][Ss])"
private val NAME_WITHOUT_TRAILING_C3_DS = "(<$C3DS_REGEX>|\\($C3DS_REGEX\\)|$C3DS_REGEX)$".toRegex(RegexOption.IGNORE_CASE)

internal fun nameWithoutC3DSTail(string: String): String {
    return NAME_WITHOUT_TRAILING_C3_DS.replace(string, "\$1")
}