@file:Suppress("unused")

package com.bedalton.common.ast.collectors

import com.bedalton.common.ast.structs.RangeWithIndex
import com.bedalton.common.ast.structs.TextWithRange
import kotlin.js.JsExport
import kotlin.js.JsName

@JsExport
interface ParseTreeItem : TextWithRange {
    /**
     * The range of this parser item in the document
     */
    override val textRange: RangeWithIndex

    /**
     * The interpreted value of its text in the document
     */
    @JsName("value")
    val value: Any

    /**
     * The original text in the document
     */
    override val text: String

    /**
     * The index of this or the starting sub-parser-item in the parse result
     */
    @JsName("parserIndexStart")
    val parserIndexStart: Int?
        get() = textRange.startIndex

    /**
     * The index of this or the last sub parser item in the containing parse result
     */
    @JsName("parserIndexEnd")
    val parserIndexEnd: Int?
        get() = textRange.endIndex
}