package com.bedalton.creatures.agents.pray.compiler

import com.bedalton.common.coroutines.checkCancelled
import com.bedalton.common.util.PathUtil
import com.bedalton.common.util.nullIfEmpty
import com.bedalton.creatures.agents.pray.compiler.data.CompilerPrayData
import com.bedalton.creatures.agents.pray.compiler.data.InlineFile
import com.bedalton.creatures.agents.pray.compiler.data.TAG_PRAY
import com.bedalton.creatures.agents.pray.compiler.internal.writeBlockHeader
import com.bedalton.creatures.agents.pray.compiler.pray.PrayDataValidator
import com.bedalton.creatures.agents.pray.compiler.pray.PrayParseValidationFailException
import com.bedalton.creatures.agents.util.RelativeFileSystem
import com.bedalton.io.bytes.ByteStreamWriter
import com.bedalton.io.bytes.Compressor
import com.bedalton.io.bytes.MemoryByteStreamWriter
import com.bedalton.log.LOG_PROGRESS
import com.bedalton.log.Log
import com.bedalton.log.iWith
import com.bedalton.vfs.FileNotFoundException
import com.bedalton.vfs.FileSystem
import kotlinx.coroutines.CancellationException
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.ensureActive
import kotlinx.coroutines.isActive

internal object PrayCompiler {


    /**
     * Compiles PRAY data to a byte array
     */
    suspend fun compile(
        coroutineScope: CoroutineScope,
        fileSystem: FileSystem,
        fileRoot: String,
        prayData: CompilerPrayData,
        subFoldersOnly: Boolean,
        compress: Int? = null,
        validate: Boolean = false,
    ): ByteArray {
        return compile(coroutineScope, RelativeFileSystem(fileSystem, fileRoot, subFoldersOnly), prayData, compress, validate)
    }

    /**
     * Compiles PRAY data to a byte array
     */
    suspend fun compile(
        coroutineScope: CoroutineScope,
        fs: RelativeFileSystem,
        prayData: CompilerPrayData,
        compress: Int? = null,
        validate: Boolean = false,
    ): ByteArray {
        if (validate) {
            val errors = PrayDataValidator.validate(coroutineScope, prayData.fullFilePath, prayData, fs)
                .filterNot { it.message.startsWith("**WARN") }
                .nullIfEmpty(true)
            if (errors != null) {
                throw PrayParseValidationFailException(
                    0,
                    "Cannot compile pray file. Errors exist",
                    errors.toTypedArray()
                )
            }
        }

        val bytes = MemoryByteStreamWriter()
        bytes.writeUInt32(TAG_PRAY)
        prayData.blocks.forEach {
            coroutineScope.checkCancelled()
            // Make sure coroutine has not been cancelled
            if (!coroutineScope.isActive) {
                throw CancellationException("Compilation cancelled")
            }
            it.write(coroutineScope, fs, bytes, compress ?: 0)
        }

        bytes.writeInlineFiles(coroutineScope, fs, prayData.inlineFiles, compress ?: 0)
        Log.iWith(LOG_PROGRESS, replace = true) { "Finalizing bytes..." }
        coroutineScope.checkCancelled()

        if (!coroutineScope.isActive) {
            coroutineScope.ensureActive()
            throw CancellationException("Compilation was cancelled")
        }
        return bytes.bytes
    }


    private suspend fun ByteStreamWriter.writeInlineFiles(
        coroutineScope: CoroutineScope,
        fs: RelativeFileSystem,
        inlineFiles: Array<InlineFile>,
        compress: Int
    ) {
        val inlineFilesCount = inlineFiles.size

        // Get logger format
        fun inlineFileNameFormat(inlineFile: InlineFile): String {
            return "${inlineFile.inputFileName} as ${inlineFile.outputFileName}"
        }

        // Get number padding length to line up output
        val indexNumberPadding = "$inlineFilesCount".length

        // Get comment to use in logging statement
        fun comment(i: Int, file: InlineFile): String {
            val index = (i + 1).toString().padStart(indexNumberPadding,' ')
            val inlineFilename = inlineFileNameFormat(file)
            return "Inlining file $index of $inlineFilesCount : $inlineFilename"
        }

        inlineFiles.distinctBy { it.outputFileName }.forEachIndexed { i, file ->
            val logComment = comment(i, file)
            writeInlineFile(coroutineScope, logComment, fs, this, file, compress)
        }
        if (!coroutineScope.isActive) {
            coroutineScope.ensureActive()
            throw CancellationException("Cancelled")
        }
    }

    /**
     * Write an inline file to the common byte writer
     */
    private suspend fun writeInlineFile(
        coroutineScope: CoroutineScope,
        inlineLog: String,
        fs: RelativeFileSystem,
        writer: ByteStreamWriter,
        inlineFile: InlineFile,
        compression: Int,
    ) {
        // Make sure coroutine has not been cancelled
        coroutineScope.checkCancelled()
        if (!coroutineScope.isActive) {
            return
        }
        val filename = PathUtil.getLastPathComponent(inlineFile.outputFileName.text) ?: inlineFile.outputFileName.text
        writeBlockHeader(writer, inlineFile.blockTag, filename)
        if (!fs.fileExists(inlineFile.inputFileName.text)) {
            throw FileNotFoundException("Failed to find inline file: ${inlineFile.inputFileName} on line: ${inlineFile.lineNumber}")
        }

        Log.iWith(LOG_PROGRESS, replace = true) { inlineLog }
        val bytes = fs.read(inlineFile.inputFileName.text)
        val compressedBytes = if (compression > 0) Compressor.compress(bytes, compression) else null
        // Write compressed length
        writer.writeUInt32(compressedBytes?.size ?: bytes.size)
        // Write uncompressed length
        writer.writeUInt32(bytes.size)
        // Write 1 if compression was used
        writer.writeUInt32(if (compressedBytes != null) 1 else 0)
        // Write bytes
        writer.write(compressedBytes ?: bytes)
    }

}


