package com.creaturesforge.application.ui

import com.bedalton.common.exceptions.rethrowCancellationException
import com.bedalton.state.simple.Dispatch
import com.bedalton.state.simple.Unsubscribe
import com.creaturesforge.application.compile.CompileData
import com.creaturesforge.application.state.*
import com.creaturesforge.application.state.ForgeState
import com.creaturesforge.application.state.ForgeStore
import com.creaturesforge.application.ui.controls.CompileButton
import com.creaturesforge.application.ui.html.BooleanAttributeOf
import com.creaturesforge.application.ui.html.hide
import com.creaturesforge.application.util.jsOb
import kotlinx.browser.document
import org.w3c.dom.*
import org.w3c.dom.events.Event

internal object ConfirmCompileModal {

    private lateinit var dispatch: Dispatch<FAction>
    private var unsubscribe: Unsubscribe? = null


    private val modal = (document.getElementById("compilation-report-modal") as HTMLDialogElement).apply {
    }

    private fun onClose(@Suppress("UNUSED_PARAMETER") e: Event? = null) {
        modal.removeEventListener("close", this::onClose)
        dispatch(CompileEggCancelledAction)
    }

    private val isOpened by BooleanAttributeOf("open", modal)
        .default(false)

    @Suppress("unused")
    private val cancelCompileButton by lazy {
        (modal.querySelector("#close-compilation-report") as HTMLButtonElement).apply {
            addEventListener("click", {
                close()
                dispatch(CompileEggCancelledAction)
            })
        }
    }

    private val compileButton by lazy {
        CompileButton((modal.querySelector("[data-id=\"compile-button\"]") as HTMLButtonElement))
    }

    private val verifyPanel by lazy {
        VerifyPanel(modal.querySelector(".compilation-report-items") as HTMLElement)
    }

    init {
        unsubscribe = ForgeStore.subscribe { _, dispatch ->
            this.dispatch = dispatch
            unsubscribe?.invoke()
        }
        modal.hide()
        modal.close()
    }

    fun close() {
        if (!isOpened) {
            return
        }
        ModalManager.close(modal)
    }

    suspend fun show(state: ForgeState) {
        val stats = try {
            state.stats.getData()
        } catch (e: Exception) {
            e.rethrowCancellationException()
            null
        } ?: emptyList()
        show(stats)
    }


    private fun show(stats: List<CompileData.AgeGenderStats>) {
        modal.removeEventListener("close", this::onClose)
        modal.addEventListener("close", this@ConfirmCompileModal::onClose, jsOb<AddEventListenerOptions>{
            this.once = true
        })
        verifyPanel.setStatus(stats)
        compileButton.showConfirmingText()
        ModalManager.show(modal, false)
    }

}