package com.creaturesforge.application.state

import com.bedalton.state.simple.Dispatch
import com.bedalton.state.simple.Next
import com.creaturesforge.application.ui.pages.AppEggMode

internal fun eggModeMiddleware(
    state: ForgeState,
    action: FAction,
    dispatch: Dispatch<FAction>,
    next: Next<ForgeState, FAction>,
): FAction {
    if (action is SetEggModeAction && state.eggMode != action.eggMode) {
        AppEggMode.setEggMode(state.projectFolder, action.eggMode, true)
    }
    return next(state, action, dispatch)
}