package com.bedalton.creatures.agents.pray.compiler.data

import com.bedalton.common.structs.HasRange
import kotlin.js.JsExport
import kotlin.js.JsName


@JsExport
data class TextValue(
    val text: String,
    override val lineNumber: Int,
    override val startIndex: Int,
    override val endIndex: Int,
): HasRange {
    @JsName("createWithInt")
    constructor(
        value: Int,
        lineNumber: Int,
        startIndex: Int,
        endIndex: Int
    ) : this (
        text = "$value",
        lineNumber,
        startIndex,
        endIndex
    )
    override fun toString(): String {
        return text
    }
}
