package com.creaturesforge.application.prompts

internal actual suspend fun showMessage(
    type: MessageType,
    title: String?,
    message: String,
) {
    com.bedalton.tauri.showMessageSuspending(message) {
        this.title = title
        this.type = type.name.lowercase()
    }
}

internal actual suspend fun showConfirmCancelDialog(
    type: MessageType,
    title: String?,
    message: String,
    okayButtonText: String?,
    cancelButtonText: String?,
): Boolean {
    return com.bedalton.tauri.showConfirmDialogSuspending(message) {
        this.title = title
        this.type = type.name.lowercase()
        this.okLabel = okayButtonText
        this.cancelLabel =  cancelButtonText
    }
}

internal actual suspend fun showYesNoDialog(
    type: MessageType,
    title: String?,
    message: String,
    yesButtonText: String?,
    noButtonText: String?,
): Boolean {
    return com.bedalton.tauri.showYesNoDialogSuspending(message) {
        this.title = title
        this.type = type.name.lowercase()
        this.okLabel = yesButtonText
        this.cancelLabel =  noButtonText
    }
}