@file:Suppress("unused")

package com.bedalton.log

@JsExport
actual external interface ILoggerObject {
    actual fun log(replace: Boolean, message: String, color: LoggerColor?)

    actual fun info(replace: Boolean, message: String, color: LoggerColor?)

    actual fun warning(message: String, color: LoggerColor?)

    actual fun error(message: String, color: LoggerColor?)

    actual fun getColorPrefix(color: LoggerColor?): String?

    actual fun logMemory()

    actual val prependLogType: Boolean?
}


fun createSingleFunctionLogger(logger: (level: String, message: String) -> Unit): ILoggerObject {
    return object: ILoggerObject {
        override fun log(replace: Boolean, message: String, color: LoggerColor?) {
            logger("log", message)
        }

        override fun info(replace: Boolean, message: String, color: LoggerColor?) {
            logger("info", message)
        }

        override fun warning(message: String, color: LoggerColor?) {
            logger("warning", message)
        }

        override fun error(message: String, color: LoggerColor?) {
            logger("error", message)
        }

        override fun getColorPrefix(color: LoggerColor?): String? {
            return null
        }

        override fun logMemory() {
            // Not available
        }

        override val prependLogType: Boolean?
            get() = null

    }
}


@JsExport
fun setLogger(logger: ILoggerObject) {
    Log.setLogger(logger)
}

@JsExport
fun setSingleFunctionLogger(logger: (level: String, message: String) -> Unit) {
    setLogger(createSingleFunctionLogger(logger))
}