package com.bedalton.common.geometry

import kotlinx.serialization.SerialName
import kotlinx.serialization.Serializable
import kotlin.js.JsExport
import kotlin.jvm.JvmStatic

expect interface IPoint {
    val x:Int
    val y:Int
}

@Serializable
@SerialName("point")
data class Point(
    override val x: Int,
    override val y: Int
) : IPoint {
}


expect interface IRect {
    val top:Int
    val bottom:Int
    val left:Int
    val right:Int
    val upperLeft: IPoint
    val lowerLeft: IPoint
    val upperRight: IPoint
    val lowerRight: IPoint
}

expect interface IVector2 {
    val x: Int
    val y: Int
}

@Serializable
@SerialName("vector2")
data class Vector2(
    override val x: Int,
    override val y: Int
): IVector2 {
    constructor(
        x: Long,
        y: Long
    ): this(x.toInt(), y.toInt())


    companion object {
        @JvmStatic
        val zero by lazy {
            Vector2(0,0)
        }
    }
}


@Serializable
@SerialName("rect")
data class Rect(
    override val top:Int,
    override val bottom:Int,
    override val left:Int,
    override val right:Int
) : IRect {

    override val upperLeft: Point by lazy {
        Point(left, top)
    }
    override val upperRight: Point by lazy {
        Point(right, top)
    }
    override val lowerLeft: Point by lazy {
        Point(left, bottom)
    }
    override val lowerRight: Point by lazy {
        Point(right, bottom)
    }
}


expect interface ILine {
    val start: IPoint
    val end: IPoint
}

@JsExport
data class Line(
    override val start: IPoint,
    override val end: IPoint
): ILine