package com.bedalton.creatures.agents.util

import com.bedalton.app.exitNativeWithError
import com.bedalton.common.util.className
import com.bedalton.common.coroutines.rethrowIfCancellationException
import com.bedalton.log.LOG_DEBUG
import com.bedalton.log.Log
import com.bedalton.log.iIf
import com.bedalton.vfs.ERROR_CODE__BAD_OUTPUT_FILE
import com.bedalton.vfs.LocalFileSystem
import com.bedalton.vfs.UnscopedFileSystem


val prayFileRegex = "^\\s*\\*#\\s*pray(\\s*|-|_)file\\s*[=\"']".toRegex(RegexOption.MULTILINE)
val cobFileRegex = "^\\s*\\*#\\s*cob(\\s*|-|_)file\\s*[=\"']".toRegex(RegexOption.MULTILINE)
val cobTagRegex = "^((c1|c2)[ \\-]name\\s*[=\"])|(thumbnail\\s*=)".toRegex(RegexOption.MULTILINE)
val prayTagRegex = "^(((c3|ds|[a-z]{4})-Name\\s*[\"'])|bioenergy|(agent\\s+(animation|sprite|bioenergy))|egg)".toRegex(RegexOption.MULTILINE)

/**
 * Tests text file for CAOS2Cob-ness
 * @return TRUE if is CAOS2Cob, false otherwise
 */
@Suppress("unused")
suspend fun isCaos2CobFile(inputFile: String, throwing: Boolean = true): Boolean {
    val fs = LocalFileSystem ?: UnscopedFileSystem()
    val text = try {
        fs.readTextWindowsCP1252(inputFile)
            .lowercase()
            .trim()
    } catch (e: Exception) {
        e.rethrowIfCancellationException()
        Log.iIf(LOG_DEBUG) {
            "Failed to read file for isCob; ${e.className}: ${e.message}; ${e.stackTraceToString()}"
        }
        return false
    }

    if (text.startsWith('*')) {
        val noLeadingAsterisks = text.trim('*', ' ', '\t')
        if (noLeadingAsterisks.startsWith("caos2cob")) {
            return true
        }
        if (noLeadingAsterisks.startsWith("caos2pray")) {
            return false
        }
    }

    if (prayFileRegex.containsMatchIn(text)) {
        return false
    }

    if (cobFileRegex.containsMatchIn(text)) {
        return true
    }

    if (throwing) {
        exitNativeWithError(
            ERROR_CODE__BAD_OUTPUT_FILE,
            "No output file specified in CAOS2Pray or CAOS2Cob directives; Use Pray-File for CAOS2Pray, or `COB-File` for CAOS2Cob"
        )
    }

    if (prayTagRegex.containsMatchIn(text)) {
        return false
    }
    return cobTagRegex.containsMatchIn(text)
}