package com.bedalton.creatures.sprite.util

import com.bedalton.common.structs.AlreadyDisposedDataCacheException
import com.bedalton.io.bytes.ByteStreamReader

internal fun ByteStreamReader?.orThrow(message: String = "Image stream already closed"): ByteStreamReader {
    if (this == null || this.closed) {
        throw AlreadyDisposedDataCacheException(message)
    }
    return this
}