@file:Suppress("unused")

package com.bedalton.vfs.internal

import com.bedalton.common.exceptions.rethrowCancellationException
import com.bedalton.common.util.formatted
import com.bedalton.log.Log
import com.bedalton.vfs.MOVED__FAILED
import com.bedalton.vfs.MOVED__FROM_FILE_DOES_NOT_EXIST
import com.bedalton.vfs.MOVED__OK
import com.bedalton.vfs.MOVED__TO_FILE_ALREADY_EXISTS
import kotlinx.coroutines.await
import tauri.fs.exists


internal actual suspend fun fileExistsInternal(filePath: String): Boolean {
    val path = resolveResourcePath(filePath)
        ?: filePath
    return try {
        exists(path).await()
    } catch (eRaw: dynamic) {
        val e = asTauriThrowable(eRaw)
        e.rethrowCancellationException()
        Log.e {
            "Failed to check file exists: ${e.formatted(true)}"
        }
        false
    }
}

internal actual suspend fun moveFile(fromPath: String, toPath: String, overwrite: Boolean): Int {
    if (!fileExistsInternal(fromPath)) {
        return MOVED__FROM_FILE_DOES_NOT_EXIST
    }
    if (!overwrite && fileExistsInternal(toPath)) {
        return MOVED__TO_FILE_ALREADY_EXISTS
    }
    return try {
        tauri.fs.renameFile(fromPath, toPath).await()
        if (fileExistsInternal(toPath)) {
            MOVED__OK
        } else {
            MOVED__FAILED
        }
    } catch (e: dynamic) {
        if (e is String) {
            val error = e as String
            if (error.lowercase().contains("scope")) {
                throw TauriError(error)
            }
        }
        if (e is Throwable) {
            e.unsafeCast<Throwable>().rethrowCancellationException()
        }
        MOVED__FAILED
    }
}

internal actual suspend fun resolveResourcePath(path: String): String? {
    return if (path.trim().lowercase().startsWith("resource:")) {
        tauri.path.resolveResource(path.trim().replace("^resource:/?".toRegex(RegexOption.IGNORE_CASE), "")).await()
    } else {
        null
    }
}