package com.bedalton.vfs

import com.bedalton.common.structs.DataCache
import com.bedalton.common.exceptions.IOException
import com.bedalton.common.util.className
import com.bedalton.io.bytes.toByteArray
import com.bedalton.vfs.internal.MD5
import com.bedalton.vfs.internal.toHexString
import org.khronos.webgl.ArrayBuffer
import org.w3c.files.FileReader
import kotlin.coroutines.resume
import kotlin.coroutines.resumeWithException
import kotlin.coroutines.suspendCoroutine


data class InputFile(
    override val name: String,
    private var file: org.w3c.files.File?
) : MemoryFile() {

    private var bytes: DataCache<ByteArray>? = DataCache {
        suspendCoroutine { continuation ->
            assertNotDisposed()
            val file = file
            if (file == null) {
                continuation.resumeWithException(IOException("File $name already disposed"))
                return@suspendCoroutine
            }
            val reader = FileReader()
            reader.onerror = { _ ->
                continuation.resumeWithException(Exception("Failed to read ${file.name}; onError called"))
            }
            reader.onload = { e ->
                try {
                    val array = e.target.asDynamic().result as ArrayBuffer
                    val bytes = array.toByteArray()
                    continuation.resume(bytes)
                } catch (err: Throwable) {
                    continuation.resumeWithException(err)
                }
                Unit
            }
            reader.readAsArrayBuffer(file)
        }
    }

    override val mimeType: String? by lazy {
        file?.type
    }

    /**
     * Read bytes from the file
     */
    override suspend fun read(): ByteArray {
        assertNotDisposed()
        val bytes = bytes
            ?: throw IOException("Bytes for $className[$name] is null")
        return bytes.getData()
            ?: throw IOException("File handle for $className[$name] is already disposed")
    }

    override fun disposeInternal() {
        file = null
        bytes?.dispose()
        bytes = null
        md5Cache?.dispose()
        md5Cache = null
    }

    private var md5Cache: DataCache<String>? = DataCache {
        val data = bytes
            ?.getData()
            ?: throw IOException("Cannot compute file MD5; File already disposed")
        MD5.compute(data).toHexString()
    }

    override suspend fun md5(): String {
        return md5Cache?.getData()
            ?: throw Exception("Cannot get MD5. File data cache already disposed")
    }

}