import com.bedalton.creatures.caos.collectors.internal.whitespaceToTokens
import com.bedalton.creatures.caos.libs.ErrorTypes.UNEXPECTED_CONTROL_TERMINATOR
import com.bedalton.creatures.caos.libs.ErrorTypes.UNTERMINATED_CONTROL_STATEMENT
