/**
 * Parses the smallest range possible based on enclosing scopes
 */
//@JsName("parseCaosNear")
fun parseCaosNear(
    variant: String,
    text: String,
    line: Int,
    character: Int,
    checkErrors: Boolean? = null,
    checkDelay: Int? = null,
    keepGoing: (() -> Boolean)? = null,
): ParseResult {
    // Ensure variant string is valid
    assertValidVariant(variant)

    // Get all containing scopes to try and narrow down the closest one to line/character
    val containingScopes = getScopeOffsets(text)
        .filter {
            inRange(
                it,
                line,
                character,
                ignoreColumn = true,
                soft = false
            ) && (it.end.line - it.start.line) > 1
        }
        .sortedByDescending { it.start.line shl 16 + it.start.character }
    // Wait
    var knock = 1
    for (scope in containingScopes) {
        // Get a slice of the script
        var scriptSlice = text.substring(scope.startIndex, scope.endIndex)
        if (scriptSlice.lowercase().endsWith("untl")) {
            scriptSlice += " 1 eq 1"
        }

        // Parse this subsection of script
        val result = parseCaos(
            variant = variant, text = scriptSlice,
            offsetIndex = scope.startIndex,
            offsetLine = scope.start.line,
            offsetColumn = scope.start.character,
            checkErrors = checkErrors,
            checkDelay = checkDelay,
            keepGoing = keepGoing
        )

        // Break out of the first block with control errors, keeping the next
        val controlErrors = result.controlStatementErrors.any {
            it.type == UNTERMINATED_CONTROL_STATEMENT || it.type == UNEXPECTED_CONTROL_TERMINATOR
        }
        if (controlErrors && knock-- > 0) {
            continue
        }
        return result
    }
    return parseCaos(
        variant = variant,
        text = text,
        offsetIndex = 0,
        offsetLine = 0,
        offsetColumn = 0,
        checkErrors = checkErrors,
        checkDelay = checkDelay,
        keepGoing = keepGoing
    )
}


/**
 * Parses CAOS within a given range.
 * Range is expanded to contain a complete control statement
 */
//@JsName("parseCaosWithin")
fun parseCaosWithin(
    variant: String,
    text: String,
    startLine: Int,
    startCharacter: Int,
    endLine: Int,
    endCharacter: Int,
    checkErrors: Boolean? = null,
    checkDelay: Int? = null,
    keepGoing: (() -> Boolean)? = null,
): ParseResult {

    // Ensure variant string is valid
    assertValidVariant(variant)

    val containingScopes = getScopeOffsets(text)
        .filter {
            (it.end.line - it.start.line) > 1 &&
                    inRange(it, startLine, startCharacter, ignoreColumn = true, soft = true) &&
                    inRange(it, endLine, endCharacter, ignoreColumn = true, soft = true)

        }
        .sortedByDescending { it.start.line shl 16 + it.start.character }
    // Wait
    var knock = 1
    for (scope in containingScopes) {
        val scriptSlice = text.substring(scope.startIndex, scope.endIndex)
        val result = parseCaos(
            variant = variant,
            text = scriptSlice,
            offsetIndex = scope.startIndex,
            offsetLine = scope.start.line,
            offsetColumn = scope.start.character,
            checkErrors = checkErrors,
            checkDelay = checkDelay,
            keepGoing = keepGoing
        )
        val controlErrors = result.controlStatementErrors.any {
            it.type == UNTERMINATED_CONTROL_STATEMENT || it.type == UNEXPECTED_CONTROL_TERMINATOR
        }

        // Break out of the first block with control errors, keeping the next
        if (controlErrors && knock-- > 0) {
            continue
        }
        return result
    }
    return parseCaos(
        variant,
        text,
        offsetIndex = 0,
        offsetLine = 0,
        offsetColumn = 0,
        checkErrors = checkErrors,
        keepGoing = keepGoing
    )
}

/**
 * Parses a CAOS file in its entirety
 */
//@JsName("parseCaos")
fun parseCaos(
    variant: String,
    text: String,
    keepGoing: (() -> Boolean)? = null,
): ParseResult {
    return parseCaos(
        variant = variant,
        text = text,
        offsetIndex = 0,
        offsetLine = 0,
        offsetColumn = 0,
        keepGoing = keepGoing
    )
}

/**
 * Parses CAOS using sub-ranges and offsets
 */
internal fun parseCaos(
    variant: String,
    text: String,
    offsetIndex: Int,
    offsetLine: Int,
    offsetColumn: Int,
    checkErrors: Boolean? = null,
    checkDelay: Int? = null,
    keepGoing: (() -> Boolean)? = null,
): ParseResult {
    if (text.isBlank()) {
        return ParseResult(
            variant,
            text,
            emptyArray(),
            emptyArray(),
            emptyArray(),
            emptyArray<Script>(),
            emptyArray(),
            emptyArray(),
            emptyArray(),
            emptyArray(),
            emptyArray(),
            emptyArray()
        )
    }

    // Create lexer
    val charStream = CharStreams.fromString(text)
    val lexer = CaosUniversalLexer(charStream)
    val tokenStream = CommonTokenStream(lexer.apply { reset() })
    val parser = CaosUniversalParser(tokenStream)

    // Create a check cancelled callback if needed
    // Check cancelled will throw an exception processing should stop as defined by keepGoing returning false
    val checkCancelled = createCheckCancelled(checkDelay, keepGoing)

    // Create tokenizer
    val collector = RawTokenizer(
        offsetIndex = offsetIndex,
        offsetLine = offsetLine,
        offsetColumn = offsetColumn,
        checkCancelled = checkCancelled
    )
    lexer.addErrorListener(collector)
    parser.addErrorListener(collector)

    // Try and parse the file
    try {
        val file = parser.file()
        ParseTreeWalker.DEFAULT.walk(collector, file)
    } catch (_: ParseCancelledException) {
        // Processing was terminated by keepGoing returning false
    }
    if (collector.items.isEmpty()) {
        Log.w("parseCaos()", "No tokens parsed")
    }

    val whitespace: List<WhitespaceItem> = tokenStream.getTokens(0, tokenStream.size() - 1)?.let { tokens ->
        if (variant.uppercase() == "C1" || variant.uppercase() == "C2") {
            tokens.filter { it.channel == CaosUniversalLexer.Channels.WHITESPACE_CHANNEL.id || it.channel == CaosUniversalLexer.Channels.COMMAS_CHANNEL.id }
        } else {
            tokens.filter { it.channel == CaosUniversalLexer.Channels.COMMAS_CHANNEL.id }
        }.flatMap(::whitespaceToTokens)
    } ?: emptyList()

    return parseTokens(
        variant = variant,
        text = text,
        items = (collector.items + whitespace).sortedBy { it.startIndex }.toTypedArray(),
        scriptOffsets = collector.scriptRanges,
        checkErrors = checkErrors,
        checkDelay = checkDelay,
        keepGoing = keepGoing
    )
}

