@file:Suppress("RegExpUnnecessaryNonCapturingGroup")

package com.bedalton.common.util

private val toSnakeOrKabobCaseRegex =
    "(?<=[a-zA-Z])[A-Z]|([_-]+[a-zA-Z])".toRegex()
private val toSnakeOrKabobCaseCombiningConsecutiveCapitalsRegex =
    "((?<=[a-zA-Z])(?:[A-Z]+)|(?:(?:(?:-+[a-zA-Z])+)(?![A-Za-z]))|(?:(?:^[a-z](?:-+[a-zA-Z])+)(?![A-Za-z])))".toRegex()

// TO Camel Case
private val toCamelCaseRegex = "[-_]+([a-zA-Z])".toRegex()
private val toCamelCaseCombiningSingleLettersRegex =
    "(^[a-z](?:[-_]+[a-z])+)|([-_]+[a-zA-Z](?:[-_]+[a-zA-Z])+)|[-_]+([A-Za-z])".toRegex()


fun String.toKabobCase(combineConsecutiveCapitals: Boolean = true): String {
    return toSnakeOrKabobCase('-', combineConsecutiveCapitals)
}

fun String.toSnakeCase(combineConsecutiveCapitals: Boolean = true): String {
    return toSnakeOrKabobCase('_', combineConsecutiveCapitals)
}

fun String.toCamelCase(
    combineSingleCharacters: Boolean = false
): String {
    return toCamelCaseRaw(combineSingleCharacters).decapitalize()
}

fun String.toCamelCaseUpperCaseFirst(
    combineSingleCharacters: Boolean = false
): String {
    return toCamelCaseRaw(combineSingleCharacters).capitalize()
}


private fun String.toCamelCaseRaw(
    combineSingleCharacters: Boolean = false
): String {
    return if (combineSingleCharacters) {
        toCamelCaseCombiningSingleLettersRegex
            .replace(this) replace@{ match ->
                val values = match.groupValues
                // Leading a-b-c -> abc
                values.getOrNull(1)
                    .nullIfEmpty()
                    ?.filter { it != '_' && it != '-' }
                    ?.lowercase()
                // non-leading -a-b-c -> Abc
                    ?: values.getOrNull(2)
                        .nullIfEmpty()
                        ?.filter { it != '_' && it != '-' }
                        ?.capitalize()
                    // anywhere -ab-cd -> AbCd
                    ?: return@replace values[3] // Only 3 options
                        .uppercase()
            }
    } else {
        return toCamelCaseRegex
            .replace(this) {
                it.groupValues[1].uppercase()
            }
    }
}


private fun String.toSnakeOrKabobCase(
    character: Char,
    combineConsecutiveCapitals: Boolean
): String {
    val regex = if (combineConsecutiveCapitals) {
        toSnakeOrKabobCaseCombiningConsecutiveCapitalsRegex
    } else {
        toSnakeOrKabobCaseRegex
    }

    return regex
        .replace(this) { match ->
            character + match.value
                .filterNot { it == '-' || it == '_' }
        }
        .lowercase()

}
