package com.bedalton.creatures.sprite.util

import korlibs.image.color.RGBA

/**
 * Palette that applies color transforms when getting
 */
internal class ColorPaletteTranslating(
    colorEncoding: ColorEncoding,
    override val size: Int,
    private val black: RGBA,
    transform: PaletteTransform? = null,
    private val colorByIndex: (i: Int) -> RGBA,
    private val rgb: (color: RGBA) -> RGBA = { it }
) : ColorPalette(colorEncoding, arrayOf(black), false) {

    private val cache = mutableMapOf<Int, RGBA>()

    private val translate by lazy {
        transform?.nullIfDefault()?.let { createC2eSwapAndRotateFunction(transform) } ?: { color: RGBA -> color }
    }

    override val indices: IntRange
        get() {
            return 0 until size
        }

    override val lastIndex: Int by lazy {
        size - 1
    }


    val blackish: RGBA by lazy {
        val int = kotlin.math.max(ColorEncoding.X_565.blackish, ColorEncoding.X_555.blackish)
        if (int == ColorEncoding.X_565.blackish) {
            ColorEncoding.X_565.toRgb(int)
        } else {
            ColorEncoding.X_555.toRgb(int)
        }
    }

    override operator fun get(index: Int): RGBA {
        if (index !in 0..65535) {
            throw IndexOutOfBoundsException("Color index $index is out of bounds. Expected integer in range 0..$lastIndex ")
        }
        cache[index]?.let {
            return it
        }
        if (index == 0) {
            return black
        }
        val colorDefault = colorByIndex(index)
        val color = translate(colorDefault)
        return rgb(color).let {
            if (it.r == 0 && it.g == 0 && it.b == 0) {
                blackish
            } else {
                it
            }
        }
    }

