    override val colors: List<RGBA> by lazy {
        indices.map map@{ i ->
            val colorDefault = colorByIndex(i)
            cache[i]?.let {
                return@map it
            }
            if (i == 0) {
                cache[0] = black
                return@map black
            }
            val color = translate(colorDefault)
            rgb(color).apply {
                cache[i] = this
            }
        }
    }
}