        writer
            .writeUInt8(sourceLobe)
            .writeUInt8(min)
            .writeUInt8(max)
            .writeUInt8(spread)
            .writeUInt8(fanout)
            .writeUInt8(minLTW)
            .writeUInt8(maxLTW)
