            .writeUInt8(strengthGain)
            .writeUInt8(strengthLoss)
            .writeSVRule(strengthGainRule)
            .writeSVRule(strengthLossRule)
            .writeSVRule(susceptibilityRule)
            .writeSVRule(relaxRule)
            .writeSVRulesIfNotNull(backPropagationRule)
            .writeSVRulesIfNotNull(forwardPropagationRule)
    }

