        internal fun fromReader(version: Int, reader: ByteStreamReader): OldDendriteInfo {
            val svLength = svLength(version)
            return OldDendriteInfo(
                sourceLobe = reader.uInt8(),
                min = reader.uInt8(),
                max = reader.uInt8(),
                spread = reader.uInt8(),
                fanout = reader.uInt8(),
                minLTW = reader.uInt8(),
                maxLTW = reader.uInt8(),
                minStrength = reader.uInt8(),
                maxStrength = reader.uInt8(),
                migrateFlag = reader.uInt8(),
