package com.bedalton.creatures.breed.render.files

import com.bedalton.common.util.gcCollect
import com.bedalton.creatures.breed.render.internal.assertConcrete
import com.bedalton.creatures.common.structs.BreedPartKey
import com.bedalton.vfs.FileSystem
import com.bedalton.vfs.Stats

@Suppress("unused")
data class BreedFileData(
    val path: String,
    val stats: Stats,
    val breedPartKey: BreedPartKey
) {

    val parentPath: String get() = stats.parentPath
    val parent: Stats get() = stats.parent
    val extension by lazy { stats.extension!!.lowercase() }
    val filename get() = stats.filename!!
    val filenameWithoutExtension get() = stats.filenameWithoutExtension!!

    val breedKey by lazy {
        breedPartKey.breedKey.also {
            it.assertConcrete("Breed file data")
        }
    }
    val part: Char get() = breedPartKey.part!!.lowercaseChar()
    val gender get() = breedPartKey.gender!!
    val ageGroup get() = breedPartKey.ageGroup!!
    val genus get() = breedPartKey.genus!!

    val breed get() = breedPartKey.breed!!

    val isAtt get() = extension == "att"

    val code get() = breedPartKey.code!!

    val isSprite by lazy {
        extension == "spr" || extension == "s16" || extension == "c16"
    }

    var data: ByteArray? = null

    init {
        breedPartKey.assertConcrete()
    }

    suspend fun exists() = stats.exists()

    suspend fun read(fs: FileSystem, refresh: Boolean = false): ByteArray {
        if (!refresh) {
            data?.let {
                return it
            }
        }
        val bytes = fs.read(path)
        data = bytes
        return bytes
    }

    fun clearCache() {
        data = null
    }

    override fun equals(other: Any?): Boolean {
        if (this === other) return true
        if (other == null || this::class != other::class) return false

        other as BreedFileData

        if (path != other.path) return false
        if (data != null) {
            if (other.data == null) return false
            if (!data.contentEquals(other.data)) return false
        } else if (other.data != null) return false

        return true
    }

    override fun hashCode(): Int {
        return path.hashCode()
    }

    companion object {

        fun fromPath(path: String): BreedFileData? {
            val stats = Stats(path)
            val filename = stats.filename
                ?: return null
            if (!BreedPartKey.isPartName(filename)) {
                return null
            }
            val breedPartKey = BreedPartKey.fromFileName(filename)
                ?: return null

            return BreedFileData(
                path,
                stats,
                breedPartKey
            )
        }
    }
}
