package gameVariant
import com.bedalton.creatures.common.structs.GameVariant
import com.bedalton.creatures.common.structs.like

@JsExport
@JsName("getGameVariantFromString")
fun getGameVariantFromString(code: String): GameVariant? {
    return GameVariant.fromString(code)
}


@JsExport
fun isGameVariantLike(variant: dynamic, other: dynamic): Boolean {
    val thisVariant = asKtGameVariant(variant)
        ?: throw Exception("Invalid game variant input <$variant>")
    val otherVariant = asKtGameVariant(other)
        ?: throw Exception("Invalid game variant input for other <$other>")
    return thisVariant.like(otherVariant)
}

@JsExport
fun isGameVariantNotLike(variant: dynamic, other: dynamic): Boolean {
    return !isGameVariantLike(variant, other)
}

@JsExport
fun asKtGameVariant(variant: dynamic): GameVariant? {
    @Suppress("USELESS_CAST")
    return when(variant) {
        is String -> GameVariant.fromString(variant as String)
        is GameVariant -> variant as GameVariant
        else -> {
            if (variant.code != null && variant.code is String) {
                GameVariant.fromString(variant.code as String)
            } else {
                null
            }
        }
    }
}