package com.creaturesforge.application.state

import com.bedalton.common.util.formatted
import com.bedalton.log.Log
import com.bedalton.log.eWith
import com.bedalton.vfs.*
import com.creaturesforge.application.util.LOG_CONSOLE
import com.bedalton.common.exceptions.rethrowCancellationException

private val additionalFiles = mutableListOf<String>()
private val virtualFiles = mutableMapOf<String, File>()
private var mScopedFileSystem: FileSystem? = null
private var scopedFileSystem: FileSystem
    get() = mScopedFileSystem ?: createFileSystem().apply {
        mScopedFileSystem = this
    }
    set(value) {
        mScopedFileSystem = value
    }

private var mVfs: FileSystemWithInputFiles? = null

internal val vfs: FileSystemWithInputFiles get() =
    mVfs ?: resetVfs()

internal fun resetVfs(): FileSystemWithInputFiles {
    val fs = createFileSystem()
    mScopedFileSystem = fs
    val vfs = FileSystemWithInputFiles(fs)
        .also {
            for ((fileName, file) in virtualFiles.entries) {
                it[fileName] = file
            }
        }
    mVfs = vfs
    return vfs
}

internal fun setVfsWithFiles(files: Map<String, File>) {
    val fs = UnscopedFileSystem()
    scopedFileSystem = fs
    mVfs = FileSystemWithInputFiles(fs)
        .also {
            for ((fileName, file) in virtualFiles.entries) {
                it[fileName] = file
            }
            for ((fileName, file) in files) {
                it[fileName] = file
            }
        }
}

internal fun addFile(filename: String, file: File) {
    virtualFiles[filename] = file
    mVfs?.set(filename, true, file)
}

internal fun addFile(filename: String, bytes: ByteArray) {
    val file = BinaryFile(
        filename,
        bytes
    )
    virtualFiles[filename] = file
    mVfs?.set(filename, true, file)
}

internal fun addFile(file: String) {
    additionalFiles.add(file)
}

internal suspend fun addGnoSafe(path: String): Boolean {
    return try {
        addGno(path)
    } catch (e: Exception) {
        e.rethrowCancellationException()
        Log.eWith(LOG_CONSOLE) { "Failed to add GNO file to Tauri safe list; ${e.formatted(false)}" }
        false
    } catch (e: Error) {
        e.rethrowCancellationException()
        Log.eWith(LOG_CONSOLE) { "Failed to add GNO file to Tauri safe list; ${e.formatted(false)}" }
        false
    } catch (e: Throwable) {
        e.rethrowCancellationException()
        Log.eWith(LOG_CONSOLE) { "Failed to add GNO file to Tauri safe list; ${e.formatted(false)}" }
        false
    }
}

internal expect fun createFileSystem(): UnscopedFileSystem

internal expect suspend fun addGno(path: String): Boolean