import com.bedalton.creatures.agents.pray.compiler.pray.PrayValidationError
import com.bedalton.vfs.LocalFileSystem
import kotlinx.coroutines.GlobalScope
import kotlinx.coroutines.asPromise
import kotlinx.coroutines.async
import kotlin.js.Promise

@JsExport
fun validatePrayFile(
    absolutePath: String,
    text: String,
    subFoldersOnly: Boolean
): Promise<Array<PrayValidationError>> {
    return GlobalScope.async {
        com.bedalton.creatures.agents.pray.compiler.pray.PrayDataValidator.validate(
            coroutineContext, LocalFileSystem!!, absolutePath, text, subFoldersOnly
        )
    }.asPromise()
}