package com.bedalton.creatures.breed.render.renderer


import com.bedalton.common.util.clamp
import com.bedalton.creatures.breed.render.internal.skip
import com.bedalton.creatures.common.structs.GameVariant
import com.bedalton.creatures.genetics.gene.PigmentBleedGene
import com.bedalton.creatures.genetics.gene.PigmentGene
import com.bedalton.creatures.genetics.genome.Genome
import com.bedalton.creatures.genetics.genome.genesOfType
import com.bedalton.creatures.sprite.util.PaletteTransform
import com.bedalton.log.LOG_VERBOSE
import com.bedalton.log.Log
import com.bedalton.log.eIf
import com.bedalton.log.iIf


fun Genome.getColorTransform(
    gender: Int = 0,
    age: Int = 0,
    geneVariant: Int? = null
): PaletteTransform {
    return getColorTransformFromGenome(
        variant(GameVariant.C3),
        this,
        gender = gender,
        age = age,
        geneVariant = geneVariant
    )
}

fun getColorTransformFromGenome(
    gameVariant: GameVariant,
    genome: Genome,
    gender: Int,
    age: Int,
    geneVariant: Int? = null
): PaletteTransform {
    val reds: MutableList<Int> = mutableListOf()
    val greens: MutableList<Int> = mutableListOf()
    val blues: MutableList<Int> = mutableListOf()
    var swap = 128
    var rotation = 128
    val isC1 = genome.version < 2

    // C1 and C2 do not change pigment with age
    val useAgeFilter = genome.version > 2
    var ageToCheck = age

    // Get pigment genes
//        val pigmentGenes = genome.genesOfType<PigmentGene>()

    // Used to break loops on C2e
    var setPigments = false

    val swaps = mutableListOf<Int>()
    val rotations = mutableListOf<Int>()
    // Run Pigment genes
    do {
        val ageFilter = if (useAgeFilter) ageToCheck else null
        for (gene in genome.genesOfType<PigmentGene>()) {
            if (skip(gene, defaultGender = gender, age = ageFilter, geneVariant = geneVariant)) {
                continue
            }
            setPigments = true
            val amount = gene.amount.clamp(0, 255)
            when (gene.color) {
                0 -> reds.add(amount)
                1 -> greens.add(amount)
                2 -> blues.add(amount)
                else -> Log.eIf(LOG_VERBOSE) { "Invalid color index ${gene.color}" }
            }

            if (isC1) {
                // Use C1 Gene extension which holds Swap and Rotate
                gene.extensionData?.let { extra ->
                    swap = ((swap * 0.5) + (extra.swap * 0.5)).toInt().clamp(0,255)
                    swaps.add(extra.swap)
                    rotation = ((rotation * 0.5) + (extra.rotation * 0.5)).toInt().clamp(0,255)
                    rotations.add(extra.rotation)
                }
            }
        }
        ageToCheck--
    } while (useAgeFilter && ageToCheck >= 0 && !setPigments)

    // Apply Bleed genes for non C1
    for (gene in genome.genesOfType<PigmentBleedGene>()) {
        // Pigment bleed gene does not work in C1
        // Use Pigment extra (GEXT) data instead
        if (isC1) {
            continue
        }

        // Skip if headers differ
        // Pigment bleed does not change with age
        if (skip(gene, defaultGender = gender, age = null, geneVariant = geneVariant)) {
            continue
        }

        swaps.add(gene.swap)
        rotations.add(gene.rotation)

        swap = (swap + gene.swap) / 2
        rotation = (rotation + gene.rotation) / 2
    }

    val average = { values: List<Int> ->
        (if (values.isEmpty()) {
            128
        } else {
            values.average().let {
                if (it.isNaN()) {
                    128
                } else {
                    it
                }
            }
        }).toInt().clamp(0, 255)
    }

//        Log.iIf(LOG_DEBUG) {"Red: [${reds.joinToString(",")}]; AverageExtension: ${average(reds)}; Average Calc: ${if (reds.isNotEmpty()) { reds.sum() / reds.size} else "NaN"}" }
//        Log.iIf(LOG_DEBUG) {"Green: [${greens.joinToString(",")}]; AverageExtension: ${average(greens)}; Average Calc: ${if (greens.isNotEmpty()) { greens.sum() / greens.size} else "NaN"}" }
//        Log.iIf(LOG_DEBUG) {"Blue: [${blues.joinToString(",")}]; AverageExtension: ${average(blues)}; Average Calc: ${if (blues.isNotEmpty()) { blues.sum() / blues.size} else "NaN"}" }


    return PaletteTransform(
        gameVariant,
        red = average(reds),
        green = average(greens),
        blue = average(blues),
        swap = swap.clamp(0, 255),
        rotation = rotation.clamp(0, 255)
    )
}