package com.bedalton.creatures.caos.collectors

import com.bedalton.creatures.caos.antlr.CaosWhitespaceLexer
import com.bedalton.creatures.caos.antlr.CaosWhitespaceParser
import com.bedalton.creatures.caos.collectors.internal.WhitespaceCollector
import org.antlr.v4.kotlinruntime.CharStreams
import org.antlr.v4.kotlinruntime.CommonTokenStream
import org.antlr.v4.kotlinruntime.tree.ParseTreeWalker


fun getWhitespace(text: String): Array<CaosParserItem> {
    val charStream = CharStreams.fromString(text)
    val lexer = CaosWhitespaceLexer(charStream)
    val tokenStream = CommonTokenStream(lexer)
    val parser = CaosWhitespaceParser(tokenStream)
    val walker = WhitespaceCollector()
    ParseTreeWalker.DEFAULT.walk(walker, parser.file())
    return walker.whitespace.toTypedArray()

}