package com.bedalton.creatures.agents.pray.compiler.caos2pray.internal

import com.bedalton.creatures.agents.pray.compiler.caos2pray.Caos2PrayCommands
import com.bedalton.creatures.agents.pray.compiler.caos2pray.CommandValue
import com.bedalton.creatures.agents.util.internal.ANY_PATH_SEPARATOR
import com.bedalton.creatures.agents.pray.compiler.data.InlineFile


/**
 * Convert inline commands into com.bedalton.creatures.pray.InlineFile objects
 */
internal fun processInline(commands: List<CommandValue>, fullFilePath: String): List<InlineFile> {
    val naturalInlines: List<InlineFile> = commands.filter { it.command == Caos2PrayCommands.INLINE }
        .map {
            InlineFile(
                lineNumber = it.lineNumber,
                startIndex = it.startIndex,
                endIndex = it.endIndex,
                blockTag = "FILE",
                outputFileName = it.values[0],
                inputFileName = it.values[1],
                containingFile = fullFilePath
            )
        }
    val attachmentInlines: Collection<InlineFile> = commands
        .filter { it.command == Caos2PrayCommands.ATTACH }
        .flatMap { command ->
            val lineNumber = command.lineNumber
            command.values.map { fileName ->
                InlineFile(
                    lineNumber = lineNumber,
                    startIndex = command.startIndex,
                    endIndex = command.endIndex,
                    blockTag = "FILE",
                    outputFileName = fileName.copy(
                        text = fileName.text.split(ANY_PATH_SEPARATOR).last(),
                    ),
                    inputFileName = fileName,
                    containingFile = fullFilePath
                )
            }
        }
    return naturalInlines + attachmentInlines
}

