@file:Suppress("unused")

package com.creaturesforge.application.ui.html

import com.bedalton.common.util.nullIfEmpty
import org.w3c.dom.HTMLOptionElement
import org.w3c.dom.HTMLOptionsCollection
import org.w3c.dom.HTMLSelectElement
import org.w3c.dom.get

internal fun HTMLSelectElement.optionsList(): List<HTMLOptionElement> {
    val options = (options.unsafeCast<HTMLOptionsCollection?>())
        ?: return emptyList()
    val length = options.length
    return (0 until length).map { i ->
        options[i] as HTMLOptionElement
    }
}


internal var HTMLSelectElement.intValue: Int?
    get() = value.nullIfEmpty()?.toInt()
    set(value) { this.value = value?.toString() ?: "" }

internal var HTMLSelectElement.intValueSafe: Int?
    get() = value.nullIfEmpty()?.toIntOrNull()
    set(value) { this.value = value?.toString() ?: "" }

