package com.bedalton.common.ast.serialization

import com.bedalton.common.ast.formatter.CaosFormatterOptions
import com.bedalton.common.ast.formatter.CaosFormatterOptionsBuilder
import kotlinx.serialization.KSerializer
import kotlinx.serialization.builtins.nullable
import kotlinx.serialization.builtins.serializer
import kotlinx.serialization.descriptors.SerialDescriptor
import kotlinx.serialization.descriptors.buildClassSerialDescriptor
import kotlinx.serialization.descriptors.element
import kotlinx.serialization.encoding.CompositeDecoder
import kotlinx.serialization.encoding.Decoder
import kotlinx.serialization.encoding.Encoder

object CaosFormatterOptionsSerializer: KSerializer<CaosFormatterOptions> {
    override val descriptor: SerialDescriptor by lazy {
        buildClassSerialDescriptor("CaosFormatterOptions") {
            element<Int>("tabSize")
            element<Boolean>("insertSpaces")
            element<Boolean?>("trimTrailingWhitespace")
            element<Boolean?>("insertFinalNewline")
            element<Boolean?>("trimFinalNewlines")
            element<Boolean?>("keepSameLine")
            element<Int?>("minBlankLines")
            element<Int?>("maxBlankLines")
            element<Boolean?>("indentComments")
            element<Int?>("continuationIndent")
            element<Boolean?>("spaceBetweenByteStingBrackets")
            element<String?>("newLineChar")
            element<Boolean?>("forceMinBlankLinesAfterComments")
        }
    }

    override fun deserialize(decoder: Decoder): CaosFormatterOptions {
        val descriptor = descriptor
        val o = decoder.beginStructure(descriptor)

        var tabSize: Int? = null
        var insertSpaces: Boolean? = null
        var trimTrailingWhitespace: Boolean? = null
        var insertFinalNewline: Boolean? = null
        var trimFinalNewlines: Boolean? = null
        var keepSameLine: Boolean? = null
        var minBlankLines: Int? = null
        var maxBlankLines: Int? = null
        var indentComments: Boolean? = null
        var continuationIndent: Int? = null
        var spaceBetweenByteStingBrackets: Boolean? = null
        var newLineChar: String? = null
        var forceMinBlankLinesAfterComments: Boolean? = null

        val nullableInt = Int.serializer().nullable
        val nullableBool = Boolean.serializer().nullable

        while (true) {
            when (val i = o.decodeElementIndex(descriptor)) {
                0 -> tabSize = o.decodeNullableSerializableElement(descriptor, i, nullableInt)
                1 -> insertSpaces = o.decodeNullableSerializableElement(descriptor, i,nullableBool)
                2 -> trimTrailingWhitespace = o.decodeNullableSerializableElement(descriptor, i, nullableBool)
                3 -> insertFinalNewline = o.decodeNullableSerializableElement(descriptor, i, nullableBool)
                4 -> trimFinalNewlines = o.decodeNullableSerializableElement(descriptor, i, nullableBool)
                5 -> keepSameLine = o.decodeNullableSerializableElement(descriptor, i, nullableBool)
                6 -> minBlankLines = o.decodeNullableSerializableElement(descriptor, i, nullableInt)
                7 -> maxBlankLines = o.decodeNullableSerializableElement(descriptor, i, nullableInt)
                8 -> indentComments = o.decodeNullableSerializableElement(descriptor, i, nullableBool)
                9 -> continuationIndent = o.decodeNullableSerializableElement(descriptor, i, nullableInt)
                10 -> spaceBetweenByteStingBrackets = o.decodeNullableSerializableElement(descriptor, i, nullableBool)
                11 -> newLineChar = o.decodeNullableSerializableElement(descriptor, i, String.serializer().nullable)
                12 -> forceMinBlankLinesAfterComments = o.decodeNullableSerializableElement(descriptor, i, nullableBool)
                CompositeDecoder.DECODE_DONE -> break
            }
        }

        o.endStructure(descriptor)

        return CaosFormatterOptionsBuilder()
            .withTabSize(tabSize)
            .withInsertSpaces(insertSpaces)
            .withTrimTrailingWhitespace(trimTrailingWhitespace)
            .withInsertFinalNewline(insertFinalNewline)
            .withTrimFinalNewlines(trimFinalNewlines)
            .withKeepSameLine(keepSameLine)
            .withMinBlankLines(minBlankLines)
            .withMaxBlankLines(maxBlankLines)
            .withIndentComments(indentComments)
            .withContinuationIndent(continuationIndent)
            .withSpaceBetweenByteStringBrackets(spaceBetweenByteStingBrackets)
            .withNewlineChar(newLineChar)
            .withForceMinBlankLinesAfterComments(forceMinBlankLinesAfterComments)

    }

    override fun serialize(encoder: Encoder, value: CaosFormatterOptions) {

        val nullableBool = Boolean.serializer().nullable
        val nullableInt = Int.serializer().nullable
        val descriptor = descriptor
        val o = encoder.beginStructure(descriptor)
        o.encodeNullableSerializableElement(descriptor, 0, nullableInt, value.tabSize)
        o.encodeNullableSerializableElement(descriptor, 1, nullableBool, value.insertSpaces)
        o.encodeNullableSerializableElement(descriptor, 2, nullableBool, value.trimTrailingWhitespace)
        o.encodeNullableSerializableElement(descriptor, 3, nullableBool, value.insertFinalNewline)
        o.encodeNullableSerializableElement(descriptor, 4, nullableBool, value.trimFinalNewlines)
        o.encodeNullableSerializableElement(descriptor, 5, nullableBool, value.keepSameLine)
        o.encodeNullableSerializableElement(descriptor, 6, nullableInt, value.minBlankLines)
        o.encodeNullableSerializableElement(descriptor, 7, nullableInt, value.maxBlankLines)
        o.encodeNullableSerializableElement(descriptor, 8, nullableBool, value.indentComments)
        o.encodeNullableSerializableElement(descriptor, 9, nullableInt, value.continuationIndent)
        o.encodeNullableSerializableElement(descriptor, 10, nullableBool, value.spaceBetweenByteStingBrackets)
        o.encodeNullableSerializableElement(descriptor, 11, String.serializer().nullable, value.newLineChar)
        o.encodeNullableSerializableElement(descriptor, 12, nullableBool, value.forceMinBlankLinesAfterComments)
        o.endStructure(descriptor)
    }
}