package com.bedalton.creatures.agents.pray.compiler.caos2pray

import com.bedalton.common.structs.Tuple
import com.bedalton.common.util.isNotNullOrBlank
import com.bedalton.common.util.nullIfEmpty
import com.bedalton.common.util.stripSurroundingQuotes
import com.bedalton.creatures.agents.cob.caos2cob.compiler.Caos2CobException
import com.bedalton.creatures.agents.pray.compiler.pray.PrayValidationError
import com.bedalton.creatures.agents.util.internal.*
import com.bedalton.creatures.agents.util.internal.line
import com.bedalton.creatures.agents.util.internal.startIndex
import com.bedalton.creatures.agents.util.internal.stopIndex
import com.bedalton.creatures.agents.util.internal.toCommandValueValue
import com.bedalton.creatures.agents.pray.compiler.data.Tag
import com.bedalton.creatures.agents.pray.compiler.data.TextValue
import com.bedalton.creatures.pray.parser.Caos2PrayParser
import com.bedalton.creatures.pray.parser.Caos2PrayParserBaseListener
import com.strumenta.kotlinmultiplatform.BitSet
import org.antlr.v4.kotlinruntime.*
import org.antlr.v4.kotlinruntime.atn.ATNConfigSet
import org.antlr.v4.kotlinruntime.dfa.DFA

/**
 * Parse tree walker for CAOS2Pray file
 *
 * @property fullFilePath absolute path to CAOS2Pray file
 * @property errors collection to add any errors to
 * @property isCaos2Cob if this file is a CAOS2Pray file
 */
internal class Caos2PrayWalker(
    private val fullFilePath: String,
    private val errors: MutableList<PrayValidationError>,
    private val isCaos2Cob: Boolean = false,
    private val recursiveJoin: Boolean = true,
    private val isJoin: Boolean = false,
) : Caos2PrayParserBaseListener(),
    ANTLRErrorListener {
    // Output pray file if found
    var prayFileName: String? = null
    // Agent name gleaned from {name}-Name commands. i.e. C3-Name, AGNT-Name, DS-Name, DSAG-Name
    val agentNames: MutableList<AgentName> = mutableListOf()
    // CAOS2Pray commands found
    val commands: MutableList<CommandValue> = mutableListOf()
    // CAOS2Pray tags found when parsing
    val tags: MutableList<Tag<*>> = mutableListOf()
    // Any code blocks found in this file
    val codeBlocks: MutableList<Tuple<Int, String>> = mutableListOf()

    /**
     * Called whenever a {name}-Name tag is encountered.
     * i.e. C3-Name, AGNT-Name, DS-Name, DSAG-Name
     *
     * @param ctx ANTLR parser context
     */
    override fun enterAgent(ctx: Caos2PrayParser.AgentContext) {
        super.enterAgent(ctx)
        // Get required agent name
        val agentNameCtx = ctx.findAgentName()
        if (agentNameCtx == null) {
            errors.add(PrayValidationError.GeneralError(
                lineNumber = ctx.line,
                startIndex = ctx.startIndex,
                endIndex = ctx.stopIndex,
                "Agent name missing in agent name tag",
                fullFilePath,
            ))
            return
        }

        // full text for agent name command
        val tag = agentNameCtx.text.uppercase()

        // Determine if Agent name conflicts with CAOS2 file variant
        val outOfVariant: Boolean = tag.replace("-", "") in listOf("C1NAME", "C2NAME") && !isCaos2Cob
                || tag.replace("-", "") !in listOf("C1NAME", "C2NAME") && isCaos2Cob

        // Throw exception if agent block tag does not match variant
        if (outOfVariant) {
            if (isCaos2Cob) {
                throw Caos2CobException("CAOS2Cob variant is invalid. Expected either C1-Name or C2-Name")
            } else {
                throw Caos2PrayException("CAOS2Pray variant is invalid. Agent must reference C3 or DS, not C1 or C2")
            }
        }

        // Determine actual block tag from shorthand
        val blockTag = when (tag) {
            "C1-Name" -> "_C1_"
            "C2-NAME" -> "_C2_"
            "DS-NAME" -> "DSAG"
            "C3-NAME" -> "AGNT"
            "SM-NAME" -> "LIVE"
            else -> {
                if (!isCaos2Cob && tag.length == 9 && tag.endsWith("-NAME"))
                    agentNameCtx.text.substring(0, tag.lastIndex - 4)
                else {
                    throw Caos2PrayParseException("Invalid value '$tag' parsed as agent name tag")
                }
            }
        }.let { adjustedTag ->
            // Create a PRAY tag using the resolved tag
            TextValue(
                lineNumber = agentNameCtx.line,
                startIndex = agentNameCtx.startIndex,
                endIndex = agentNameCtx.stopIndex,
                text = adjustedTag
            )
        }
        // Get tag value (i.e. agents actual name)
        val agentName = ctx.findC2pValue()?.toCommandValueValue()

        // If agent name is blank, add an error
        if (agentName == null) {
            val error = PrayValidationError.NoBlockError(
                lineNumber = agentNameCtx.line,
                startIndex = agentNameCtx.startIndex,
                endIndex = agentNameCtx.stopIndex,
                message = "Parse incomplete agent tag: $blockTag name is required",
                fullFilePath = fullFilePath
            )
            errors.add(error)
            return
        }

        // Add agent name to list
        agentNames.add(AgentName(ctx.start!!.line, blockTag, agentName))
    }

    /**
     * Enter "attach" command in parser
     */
    override fun enterAttach(ctx: Caos2PrayParser.AttachContext) {
        super.enterAttach(ctx)
        val children = ctx.findC2pValues()?.children
            ?: return
        commands.add(
            CommandValue(
                command = Caos2PrayCommands.ATTACH,
                lineNumber = ctx.line,
                startIndex = ctx.startIndex,
                endIndex = ctx.stopIndex,
                values = children.map {
                    val child = (it as ParserRuleContext)
                    TextValue(
                        text = child.originalStringValue!!,
                        lineNumber = ctx.line,
                        startIndex = child.startIndex,
                        endIndex = child.stopIndex
                    )
                }
            )
        )
    }

    /**
     * Enter "Depend" command in parser
     */
    override fun enterDepend(ctx: Caos2PrayParser.DependContext) {
        super.enterDepend(ctx)
        val children = ctx.findC2pValues()?.children
            ?: return
        commands.add(
            CommandValue(
                command = Caos2PrayCommands.DEPENDS,
                lineNumber = ctx.line,
                startIndex = ctx.startIndex,
                endIndex = ctx.stopIndex,
                values = children.map {
                    val child = (it as ParserRuleContext)
                    TextValue(
                        text = child.originalStringValue!!,
                        lineNumber = ctx.line,
                        startIndex = child.startIndex,
                        endIndex = child.stopIndex
                    )
                }
            )
        )
    }

    /**
     * Enter "inline" command in parser
     */
    override fun enterInline(ctx: Caos2PrayParser.InlineContext) {
        super.enterInline(ctx)
        val first = ctx.findC2pValue(0)?.toCommandValueValue() ?: return
        val second = ctx.findC2pValue(1)?.toCommandValueValue() ?: first
        commands.add(
            CommandValue(
                command = Caos2PrayCommands.INLINE,
                lineNumber = ctx.line,
                startIndex = ctx.startIndex,
                endIndex = ctx.stopIndex,
                values = listOf(first, second)
            )
        )
    }

    /**
     * Enter "link" command in parser
     */
    override fun enterLink(ctx: Caos2PrayParser.LinkContext) {
        super.enterLink(ctx)
        val children = ctx.findC2pValues()?.children
            ?: return
        commands.add(
            CommandValue(
                command = Caos2PrayCommands.LINK,
                lineNumber = ctx.start!!.line,
                startIndex = ctx.start!!.startIndex,
                endIndex = ctx.stop!!.stopIndex,
                values = children.map {
                    (it as ParserRuleContext).toCommandValueValue()
                }
            )
        )
    }


    /**
     * Enter "join" command in parser
     */
    override fun enterJoin(ctx: Caos2PrayParser.JoinContext) {
        super.enterJoin(ctx)
        if (!recursiveJoin && isJoin) {
            return
        }
        val children = ctx.findC2pValues()?.children
            ?: return
        commands.add(
            CommandValue(
                command = Caos2PrayCommands.JOIN,
                lineNumber = ctx.start!!.line,
                startIndex = ctx.start!!.startIndex,
                endIndex = ctx.stop!!.stopIndex,
                values = children.map {
                    (it as ParserRuleContext).toCommandValueValue()
                }
            )
        )
    }

    /**
     * Enter "RSCR" command in parser
     */
    override fun enterRscr(ctx: Caos2PrayParser.RscrContext) {
        super.enterRscr(ctx)
        val script = ctx.findC2pValue()
            ?: return
        val text = script.originalStringValue
            ?: return
        commands.add(
            CommandValue(
                command = Caos2PrayCommands.RSCR,
                lineNumber = ctx.start!!.line,
                startIndex = ctx.start!!.startIndex,
                endIndex = ctx.stop!!.stopIndex,
                values = listOf(
                    TextValue(
                        text = text,
                        lineNumber = script.line,
                        startIndex = script.start!!.startIndex,
                        endIndex = script.stop!!.stopIndex
                    )
                )
            )
        )
    }


    /**
     * Enter any tag in CAOS2Pray block
     */
    override fun enterTag(ctx: Caos2PrayParser.TagContext) {
        super.enterTag(ctx)
        // Get the tag name value
        val tagName = ctx.findTagName()
            ?.toCommandValueValue()
            ?: return

        // Determine line number
        val lineNumber = ctx.start!!.line

        // Determine tag value
        val value = ctx.findC2pValue()
            ?: return

        // If value is a number, add it to Int Tags
        if (value.findNumber()?.INT()?.text?.nullIfEmpty()?.toFloatOrNull() != null) {
            tags.add(
                Tag.IntTag(
                    lineNumber = lineNumber,
                    startIndex = value.startIndex,
                    endIndex = value.stopIndex,
                    tagRange = tagName,
                    value = (value.findNumber() ?: value).toCommandValueValue()
                )
            )
        } else if (value.text.isNotNullOrBlank()) {
            // Tag is empty, add it as a text tag
            tags.add(
                Tag.StringTag(
                    lineNumber = lineNumber,
                    startIndex = value.startIndex,
                    endIndex = value.stopIndex,
                    tagRange = tagName,
                    value = value.toCommandValueValue()
                )
            )
        } else {
            // Value is text, so add it as a String tag
            tags.add(
                Tag.StringTag(
                    lineNumber = lineNumber,
                    startIndex = value.startIndex,
                    endIndex = value.stopIndex,
                    tagRange = tagName,
                    value = TextValue(
                        lineNumber = value.line,
                        startIndex = value.startIndex,
                        endIndex = value.stop!!.stopIndex,
                        text = ""
                    )
                )
            )
        }
    }


    /**
     * Enter a removal script in the body of the CAOS file
     */
    override fun enterRemovalScript(ctx: Caos2PrayParser.RemovalScriptContext) {
        super.enterRemovalScript(ctx)
        // Tuple.first == 1 means removal script
        codeBlocks.add(Tuple(1, ctx.findBody()?.originalText!!))
    }

    /**
     * Enter pray file command, used for actual output file name
     */
    override fun enterPrayFile(ctx: Caos2PrayParser.PrayFileContext) {
        super.enterPrayFile(ctx)
        prayFileName = ctx.findC2pValue()?.text?.stripSurroundingQuotes(2)?.trim()
    }

    /**
     * Called every script
     * Adds non-removal scripts to codeBlocks list
     */
    override fun enterScript(ctx: Caos2PrayParser.ScriptContext) {
        super.enterScript(ctx)

        // ensure this script is not removal script which is handled specially
        if (ctx.findRemovalScript() != null) {
            return
        }
        // Tuple.first == 0 means NOT removal script
        codeBlocks.add(Tuple(0, ctx.originalText!!))
    }

    /**
     * ANTLR base error catch for ambiguous tree paths encountered
     */
    override fun reportAmbiguity(
        recognizer: Parser,
        dfa: DFA,
        startIndex: Int,
        stopIndex: Int,
        exact: Boolean,
        ambigAlts: BitSet,
        configs: ATNConfigSet,
    ) {

    }

    /**
     * ANTLR base error catch
     */
    override fun reportAttemptingFullContext(
        recognizer: Parser,
        dfa: DFA,
        startIndex: Int,
        stopIndex: Int,
        conflictingAlts: BitSet,
        configs: ATNConfigSet,
    ) {
    }

    /**
     * ANTLR base error catch
     */
    override fun reportContextSensitivity(
        recognizer: Parser,
        dfa: DFA,
        startIndex: Int,
        stopIndex: Int,
        prediction: Int,
        configs: ATNConfigSet,
    ) {
    }

    /**
     * ANTLR base error catch for all syntax errors.
     * Syntax errors are wrapped in PrayValidationError.SyntaxError objects and added to error list
     */
    override fun syntaxError(
        recognizer: Recognizer<*, *>,
        offendingSymbol: Any?,
        line: Int,
        charPositionInLine: Int,
        msg: String,
        e: RecognitionException?,
    ) {
        // Get the bad token if any
        val token = (offendingSymbol as? Token)

        // Construct error message
        val errorMessage = if (token != null) {
            "Failed to parse PRAY file. Unexpected input <${token.text}> at (${token.line}:${token.charPositionInLine})"
        } else {
            "Failed to parse PRAY file. $msg"
        }

        // Construct syntax error instance
        val error = PrayValidationError.SyntaxError(
            errorText = token?.text ?: offendingSymbol.toString(),
            message = errorMessage,
            lineNumber = line,
            startIndex = token?.startIndex ?: -1,
            endIndex = token?.stopIndex ?: -1,
            fullFilePath = fullFilePath
        )

        // Add error to error list
        errors.add(error)
    }
}