package com.bedalton.creatures.breed.render.support.pose

import kotlinx.serialization.Serializable
import kotlin.js.JsExport
import kotlin.js.JsName

/**
 * Enum for the direction a creature is facing
 * Includes POSE variable values like '?','!', and 'X'
 */
@Serializable
@JsExport
enum class PoseFacing(val int: Int?, val char: Char) {
    BACK(PoseConstants.Facing.BACK, '0'),
    FRONT(PoseConstants.Facing.FRONT, '1'),
    VIEWER_RIGHT(PoseConstants.Facing.VIEWER_RIGHT, '2'),
    VIEWER_LEFT(PoseConstants.Facing.VIEWER_LEFT, '3'),
    TOWARD_IT(null, '?'),
    AWAY_FROM_IT(null, '!'),
    NO_CHANGE(null, 'X');

    fun invert(): PoseFacing {
        return when (this) {
            BACK -> FRONT
            FRONT -> BACK
            VIEWER_LEFT -> VIEWER_RIGHT
            VIEWER_RIGHT -> VIEWER_LEFT
            TOWARD_IT -> AWAY_FROM_IT
            AWAY_FROM_IT -> TOWARD_IT
            NO_CHANGE -> NO_CHANGE
        }
    }

    fun withIt(it: PoseFacing): PoseFacing {
        return when (this) {
            TOWARD_IT -> it
            AWAY_FROM_IT -> it.invert()
            else -> this
        }
    }



    fun withItConcrete(it: PoseFacing?, default: PoseFacing): PoseFacing {
        return when (this) {
            TOWARD_IT -> it?.toConcrete(default) ?: default
            AWAY_FROM_IT -> it?.invert()?.toConcrete(default) ?: default
            NO_CHANGE -> default
            else -> this
        }
    }
    fun toConcrete(default: PoseFacing): PoseFacing {
        return when (this) {
            TOWARD_IT -> default
            AWAY_FROM_IT -> default
            NO_CHANGE -> default
            BACK -> this
            FRONT -> this
            VIEWER_RIGHT -> this
            VIEWER_LEFT -> this
        }
    }

    companion object {

        @JsName("fromChar")
        fun fromChar(char: String): PoseFacing? {
            if (char.length != 1) {
                throw PoseException("Cannot get pose facing from string '$char'. Value should be a single char")
            }
            return fromChar(char[0])
        }

        @Suppress("NON_EXPORTABLE_TYPE")
        @JsName("fromCharNonJS")
        fun fromChar(char: Char): PoseFacing? {
            return when (char.uppercaseChar()) {
                '0' -> BACK
                '1' -> FRONT
                '2' -> VIEWER_RIGHT
                '3' -> VIEWER_LEFT
                '?' -> TOWARD_IT
                '!' -> AWAY_FROM_IT
                'X' -> NO_CHANGE
                else -> null
            }
        }
    }
}

