package com.bedalton.creatures.common.structs

import com.bedalton.common.util.PathUtil
import com.bedalton.creatures.common.structs.BreedPartKey.Companion
import com.bedalton.creatures.common.structs.BreedPartKey.Companion.DEFAULT_ALLOW_Z
import kotlinx.serialization.Serializable

interface IBreedKey {
    val variant: GameVariant?
    val genus: Int?
    val gender: Int?
    val breed: Char?
    val ageGroup: Int?
}

@Serializable
@Suppress("unused")
data class BreedKey(
    override val variant: GameVariant? = null,
    override val genus: Int? = null,
    override val gender: Int? = null,
    override val breed: Char? = null,
    override val ageGroup: Int? = null
): IBreedKey {
    val code: String? by lazy {
        if (genus != null && gender != null && breed != null && ageGroup != null) {
            val first = ((gender - 1) * 4) + genus
            "$first$ageGroup$breed"
        } else {
            null
        }
    }

    fun copyWithVariant(variant: GameVariant?): BreedKey {
        return copy(
            variant = variant
        )
    }

    fun copyWithGender(gender: Int?): BreedKey {
        return copy(
            gender = gender
        )
    }


    fun copyWithGenus(genus: Int?): BreedKey {
        return copy(
            genus = genus
        )
    }

    fun copyWithBreed(breed: Char?): BreedKey {
        return copy(
            breed = breed?.lowercaseChar()
        )
    }


    fun copyWithAgeGroup(ageGroup: Int?): BreedKey {
        return copy(
            ageGroup = ageGroup
        )
    }


    val unreliableHash: Int
        get() {
            var result = genus ?: 0
            result = 31 * result + (gender ?: 0)
            result = 31 * result + (breed?.lowercase()?.hashCode() ?: 0)
            result = 31 * result + (ageGroup ?: 0)
            return result
        }

    fun distance(other: BreedKey?): Int? {
        if (other == null) {
            return null
        }

        var distance = 0

        // Look down and then up
        if (this.genus != null && other.genus != null) {
            distance += if (other.genus <= this.genus) {
                this.genus - other.genus
            } else {
                other.genus
            }
        }

        distance *= 256

        // Calculate distance based on breed
        if (breed != null && other.breed != null) {
            val otherBreed: Int = if (other.breed in '0'..'9') { other.breed - '0' } else { other.breed.lowercaseChar() - 'a' }
            val breed: Int = if (breed in '0'..'9') (breed - '0') else (breed.lowercaseChar() - 'a')
            distance += if (otherBreed <= breed) {
                breed - otherBreed
            } else {
                otherBreed
            }
        }

        // Calculate distance based on sex
        distance *= 2
        if (this.gender != null && other.gender != null && other.gender != this.gender) {
            distance += 1
        }

        // Distance by age
        distance *= 10
        if (this.ageGroup != null && other.ageGroup != null) {
            val otherAge = other.ageGroup
            distance += if (otherAge <= ageGroup) {
                ageGroup - otherAge
            } else {
                otherAge
            }
        }
        return distance
    }

    fun isGenericMatchFor(other: BreedKey?): Boolean {
        return isGenericMatch(this, other)
    }

    companion object {
        fun fromFileName(fileName: String, variant: GameVariant? = null): BreedKey? {
            if (!isPartName(fileName, variant))
                return null

            val chars = PathUtil.getFileNameWithoutExtension(fileName)?.lowercase()?.toCharArray()
                ?: return null

            return BreedKey(
                variant = variant,
                genus = ((chars[1] - '0') % 4),
                gender = if (chars[1] - '0' < 4) 1 else 2,
                ageGroup = (chars[2] - '0'),
                breed = chars[3],
            )
        }

        fun isPartName(fileName: String): Boolean {
            return mIsPartName(fileName, null, DEFAULT_ALLOW_Z)
        }

        fun isPartName(fileName: String, variant: GameVariant?): Boolean {
            return mIsPartName(fileName, variant, DEFAULT_ALLOW_Z)
        }

        fun isPartName(fileName: String, variant: GameVariant?, allowZ: Boolean): Boolean {
            return mIsPartName(fileName, variant, allowZ)
        }

        /**
         * Checks for a generic match, where a wild-card value is a null
         */
        fun isGenericMatch(val1: IBreedKey?, val2: IBreedKey?): Boolean {

            // If both null, then they are equal?
            if (val1 == null && val2 == null)
                return true

            // If one is null and not the other, cannot be equal
            if (val1 == null || val2 == null)
                return false

            if (val1 == val2)
                return true


            // Make sure if non-null variants are equal
            val val1Variant = val1.variant
            val val2Variant = val2.variant
            if (val1Variant != null && val2Variant != null && val1Variant.code != val2Variant.code) {
                if (val1Variant notLike val2Variant) {
                    return false
                }
            }

            // Make sure if non-null genus are equal
            if (val1.genus != null && val2.genus != null && val1.genus != val2.genus) {
                return false
            }

            // Make sure if non-null gender are equal
            if (val1.gender != null && val2.gender != null && val1.gender != val2.gender) {
                return false
            }

            // Make sure if non-null breed are equal
            if (val1.breed != null && val2.breed != null && val1.breed!!.lowercase() != val2.breed!!.lowercase()) {
                return false
            }

            // Make sure if non-null age-group are equal
            if (val1.ageGroup != null && val2.ageGroup != null && val1.ageGroup != val2.ageGroup) {
                return false
            }

            return true
        }
    }
}

@Serializable
@Suppress("unused")
data class BreedPartKey(
    val breedKey: BreedKey,
    val part: Char? = null,
): IBreedKey {

    override val variant: GameVariant? get() = breedKey.variant
    override val genus: Int? get() = breedKey.genus
    override val gender: Int? get() = breedKey.gender
    override val breed: Char? get() = breedKey.breed
    override val ageGroup: Int? get() = breedKey.ageGroup

    val code: String?
        get() = if (breedKey.code != null) {
            "${part ?: ""}${breedKey.code}"
        } else {
            null
        }

    operator fun get(index: Int): Char? {
        if (index !in 0..3)
            return null
        return when (index) {
            0 -> part?.lowercaseChar()
            1 -> if (genus == null || gender == null) null else '0' + (genus!! + ((gender!! - 1) * 4))
            2 -> ageGroup?.let { '0' + it }
            3 -> breed?.lowercaseChar()
            else -> null
        }
    }

    fun copyWithVariant(variant: GameVariant?): BreedPartKey {
        return copy(
            breedKey = breedKey.copy(
            variant = variant
            )
        )
    }

    fun copyWithGender(gender: Int?): BreedPartKey {
        return copy(
            breedKey = breedKey.copy(
            gender = gender
            )
        )
    }


    fun copyWithGenus(genus: Int?): BreedPartKey {
        return copy(
            breedKey = breedKey.copy(
            genus = genus
            )
        )
    }

    fun copyWithBreed(breed: Char?): BreedPartKey {
        return copy(
            breedKey = breedKey.copy(
            breed = breed?.lowercaseChar()
            )
        )
    }


    fun copyWithAgeGroup(ageGroup: Int?): BreedPartKey {
        return copy(
            breedKey = breedKey.copy(
                ageGroup = ageGroup
            )
        )
    }

    fun copyWithPart(part: Char?): BreedPartKey {
        return copy(
            part = part?.lowercaseChar()
        )
    }

    val unreliableHash: Int
        get() {
            var result = genus ?: 0
            result = 31 * result + (gender ?: 0)
            result = 31 * result + (breed?.lowercase()?.hashCode() ?: 0)
            result = 31 * result + (ageGroup ?: 0)
            result = 31 * result + (part?.lowercase()?.hashCode() ?: 0)
            return result
        }

    fun distance(other: BreedPartKey?): Int? {
        if (other == null) {
            return null
        }
        if (part != null && other.part != null && part != other.part) {
            return null
        }

        var distance = 0

        // Look down and then up
        if (this.genus != null && other.genus != null) {
            distance += if (other.genus!! <= this.genus!!) {
                this.genus!! - other.genus!!
            } else {
                other.genus!!
            }
        }

        distance *= 256

        // Calculate distance based on breed
        if (breed != null && other.breed != null) {
            val otherBreed: Int = if (other.breed in '0'..'9') { other.breed!! - '0' } else { other.breed!! - 'a' }
            val breed: Int = if (breed in '0'..'9') (breed!! - '0') else (breed!! - 'a')
            distance += if (otherBreed <= breed) {
                breed - otherBreed
            } else {
                otherBreed
            }
        }

        // Calculate distance based on sex
        distance *= 2
        if (other.gender != this.gender) {
            distance += 1
        }

        // Distance by age
        distance *= 10
        if (this.ageGroup != null && other.ageGroup != null) {
            val otherAge = other.ageGroup
            distance += if (otherAge!! <= ageGroup!!) {
                ageGroup!! - otherAge
            } else {
                otherAge
            }
        }
        return distance
    }


    companion object {
        const val VERSION: Int = 6
        const val DEFAULT_ALLOW_Z: Boolean = false

        fun fromFileName(fileName: String, variant: GameVariant? = null): BreedPartKey? {
            if (!isPartName(fileName, variant))
                return null

            val chars = PathUtil.getFileNameWithoutExtension(fileName)?.lowercase()?.toCharArray()
                ?: return null

            val breedKey = BreedKey(
                variant = variant,
                genus = ((chars[1] - '0') % 4),
                gender = if (chars[1] - '0' < 4) 1 else 2,
                ageGroup = (chars[2] - '0'),
                breed = chars[3],
            )
            return BreedPartKey(
                breedKey = breedKey,
                part = chars[0]
            )
        }

        fun isPartName(fileName: String): Boolean {
            return mIsPartName(fileName, null, DEFAULT_ALLOW_Z)
        }

        fun isPartName(fileName: String, variant: GameVariant?): Boolean {
            return mIsPartName(fileName, variant, DEFAULT_ALLOW_Z)
        }

        fun isPartName(fileName: String, variant: GameVariant?, allowZ: Boolean): Boolean {
            return mIsPartName(fileName, variant, allowZ)
        }

        /**
         * Checks for a generic match, where a wild-card value is a null
         */
        fun isGenericMatch(val1: BreedPartKey?, val2: BreedPartKey?): Boolean {

            // If both null, then they are equal?
            if (val1 == null && val2 == null)
                return true

            // If one is null and not the other, cannot be equal
            if (val1 == null || val2 == null)
                return false

            if (val1 == val2) {
                return true
            }

            if (!BreedKey.isGenericMatch(val1.breedKey, val2.breedKey)) {
                return false
            }

            // Make sure if non-null parts are equal
            if (val1.part != null && val2.part != null && val1.part.lowercase() != val2.part.lowercase()) {
                return false
            }
            return true
        }
    }
}

private fun mIsPartName(fileName: String, variant: GameVariant?, allowZ: Boolean): Boolean {
    val chars = PathUtil.getFileNameWithoutExtension(fileName)
        ?.lowercase()
        ?.toCharArray()
        ?: return false
    if (chars.size != 4) {
        return false
    }
    if (chars[0] !in 'a'..'q' && (allowZ && chars[0] != 'z')) {
        return false
    }
    if (chars[1] !in '0'..'7') {
        return false
    }
    if (chars[2] !in '0'..'9') {
        return false
    }
    return when (variant) {
        GameVariant.C1 -> chars[3] in '0'..'9'
        null -> chars[3] in 'a'..'z' || chars[3] in '0'..'9'
        else -> chars[3] in 'a'..'z'
    }
}
