@file:Suppress("unused")

package com.bedalton.creatures.agents.pray.data

import kotlin.js.JsExport


@JsExport
sealed class Tag<T>(
    open val tag: String,
    open val value: T,
) {
    data class StringTag(
        override val tag: String,
        override val value: String
    ) : Tag<String>(tag, value)

    /**
     * Tag object holding a string value
     */
    data class IntTag(
        override val tag: String,
        override val value: Int,
    ) : Tag<Int>(
        tag = tag,
        value = value
    )
}
