package com.creaturesforge.application.util

@Suppress("USELESS_CAST")
internal actual fun asThrowable(e: dynamic): Throwable {
    if (e is Throwable) {
        return e
    }
    if (e is String) {
        return TauriError(e as String)
    }
    val error = e.error ?: e
    if (error.message is String) {
        return TauriError(error.message as String)
    }
    return TauriError(JSON.stringify(error))
}

class TauriError(message: String, throwable: Throwable? = null) : Exception(message, throwable)


