internal const val agentScheme = "agent://"

internal fun isAgentScheme(path: String): Boolean {
    return path.lowercase().startsWith(agentScheme.lowercase())
}

internal var job: Job? = null

internal object LoadAgentMiddleware {

    internal fun cancelEggLoad(reason: String = "user cancelled") {
        job?.cancel(reason)
    }

    internal fun middleware(
        state: ForgeState,
        action: FAction,
        dispatch: Dispatch<FAction>,
        next: Next<ForgeState, FAction>,
    ): FAction {
        return if (action is OpenEggAction) {
            loadEggAgent(action.path, dispatch)
        } else {
            next(state, action, dispatch)
        }
    }

    private fun loadEggAgent(path: String, dispatch: Dispatch<FAction>): NoOp {


        PathUtil.getDirname(path)?.let {
            cacheAgentOpenDirectory(path)
        }

        job?.cancelIfRunning("Loading new egg")

        val thisJob = Job()
        job = thisJob

        val coroutineScope = CoroutineScope(thisJob)

//        coroutineScope.launch load@{
        GlobalScope.launch load@{
            val newState = try {
                loadFilesFromAgent(coroutineScope, filePath = path)
            } catch (e: EggParseException) {
                e.rethrowCancellationException()
                Log.e("Failed to load egg agent; ${e.formatted(true)}")
                showErrorMessage(e.formatted(false))
                return@load
            }

            job = null

            try {
                dispatch(SetStateAction(newState))
            } catch (e: Exception) {
                e.rethrowCancellationException()
                Log.e(e.formatted(true))
            }
        }
        return NoOp
    }

    private suspend fun loadFilesFromAgent(coroutineScope: CoroutineScope, filePath: String): ForgeState {
        val fs = vfs

        val bytes = try {
            onOpenEggProgress(PathUtil.getBasename(filePath) ?: "Agent File", "READ", 0, null)
            fs.read(filePath)
        } catch (e: Exception) {
            e.rethrowCancellationException()
            Log.e("Failed to read agent file: $filePath; ${e.formatted(true)}")
            throw EggParseException("Failed to read agent file: $filePath; ${e.formatted(false)}")
        }

        return loadFilesFromAgentBytes(coroutineScope, filePath, bytes)
    }

    private fun onBlockProgress(
        fileName: String,
        pass: Int,
        totalPasses: Int,
    ): (pass: Int, index: Int, total: Int, blockTag: String, blockName: String) -> Unit {
        return callback@{ blockPass: Int, index: Int, total: Int, blockTag: String, blockName: String ->
            if (total < 0) {
                Log.i("OnBlockProgress->Dismiss($blockPass, $index, $total, $blockTag, $blockPass)")
                onOpenEggProgress(fileName, "$blockTag[$blockName]", index, null)
                return@callback
            }
            Log.i("OnBlockProgress->Log($blockPass, $index, $total, $blockTag, $blockPass)")
            val thePass = pass + blockPass
            val totalFromAllPasses = total * totalPasses
            val indexInAllPasses = ((thePass * total) + index)
            onOpenEggProgress(fileName, "$blockTag[$blockName]", indexInAllPasses, totalFromAllPasses)
        }
    }

    private suspend fun loadFilesFromAgentBytes(
        coroutineScope: CoroutineScope,
        filePath: String,
        bytes: ByteArray,
    ): ForgeState {

        val fileName = PathUtil.getBasename(filePath) ?: "unknown.agents"

        val agentParseCallback = onBlockProgress(fileName, 0, 2)

        agentParseCallback(0, 0, -1, "Agent", fileName)

        val result = parsePrayAgentToMemory(
            coroutineScope,
            fileName,
            "",
            bytes,
            "EGGS,FILE",
            callback = agentParseCallback,
        )

        val totalBlocks = result.blocks.size
        val fileVfsProgress = onBlockProgress(fileName, 1, 2)
        val i = korAtomic(0)
        val files: Map<String, BinaryFile> = result.blocks
            .filterIsInstance<CompilerDataBlock>()
            .mapAsync(coroutineScope) {
                val blockName = it.blockName.text
                val data: ByteArray = it.data()!!
                val out = "$agentScheme$fileName/$blockName" to BinaryFile(blockName, data, "application/octet-stream")
                fileVfsProgress(0, i.incrementAndGet(), totalBlocks, it.blockTag.text, blockName)
                out
            }
            .toMap()

        onOpenEggProgress(fileName, "ALL", totalBlocks, totalBlocks)

        setVfsWithFiles(files)

//        val agentSchemeLength = agentScheme.length
        val genomes = files.keys
            .filter { it.lowercase().endsWith(".gen") }
//            .map { it.substring(agentSchemeLength) }
            .toSet()

        val eggsAndGlyphs = result.blocks.filterIsInstance<CompilerBlockWithTags>()
            .filter { it.blockTag.text == "EGGS" }
            .map { getEggBlock(it, genomes) }

        val glyphs = eggsAndGlyphs.map { it.second }

        val maleGlyphName = glyphs.map { it.first }.toSet().singleOrNull()
        val maleGlyph = getGlyph(maleGlyphName, files)

        val femaleGlyphName = glyphs.map { it.second }.toSet().singleOrNull()
        val femaleGlyph = getGlyph(femaleGlyphName, files)

        val eggs = eggsAndGlyphs.map { it.first }

        val spriteFiles = files.keys
            .filter { PathUtil.getExtension(it)?.lowercase() == "c16" }
            .filter { BreedKey.isPartName(it) }

        val spriteFileBreedKeys = spriteFiles.mapNotNull { BreedKey.fromFileName(it) }
            .filter { it.genus != null && it.breed != null }

        val slots = spriteFileBreedKeys.distinct()

        val primarySlot = slots.maxByOrNull { breedKey ->
            spriteFileBreedKeys.count { spriteKey ->
                BreedKey.isGenericMatch(
                    breedKey,
                    spriteKey
                )
            }
        }

        val breedSlot = if (primarySlot != null) {
            BreedSlot(primarySlot.genus!!, primarySlot.breed!!)
        } else {
            null
        }

        val path = "$agentScheme$fileName/"

        val attFiles = files.keys.filter { PathUtil.getExtension(it)?.lowercase() == "att" }

        val genus = eggs.firstNotNullOfOrNull { egg ->
            getGenomeGenus(egg, files)
        }

        return ForgeState(
            projectFolder = path,
            virtual = true,
            lastSaveDirectory = getWithoutLastPathComponent(filePath),
            lastFileName = getFileName(filePath),
            eggs = eggs,
            eggMode = EggMode.MULTI,
            selectedEgg = eggs.first(),
            breedSlot = breedSlot,
            spriteSlot = breedSlot,
            spriteRoot = path,
            spriteFiles = spriteFiles,
            attRoot = path,
            attFiles = attFiles,
            attSlot = null,
            additionalGenomes = genomes.mapNotNull map@{
                val label = getFileName(it)
                    ?: return@map null
                label to it
            }.toMap(),
            maleGlyph = maleGlyph,
            femaleGlyph = femaleGlyph,
            genomeGenus = genus ?: 0
        )
    }


    private fun getEggBlock(block: CompilerBlockWithTags, genomes: Set<String>): Pair<EggData, Pair<String?, String?>> {
        val eggName = block.blockName.text

        val stringTags = block.stringTags.associate { it.tag to it.value }

        val baseGenome = getGenome(stringTags["Genetics File"], genomes)?.let { file ->
            GenomeFile(getFileName(file) ?: file, file)
        }.also {
            Log.iIf(LOG_VERBOSE) { "Base Genome for ${block.blockName.text} is $it" }
        }

        val motherGenome = getGenome(stringTags["Mother Genetic File"], genomes)?.let { file ->
            GenomeFile(getFileName(file) ?: file, file)
        }

        val fatherGenome = getGenome(stringTags["Father Genetic File"], genomes)?.let { file ->
            GenomeFile(getFileName(file) ?: file, file)
        }

        val maleEggGlyph = stringTags["Egg Glyph File"]

        val femaleEggGlyph = stringTags["Egg Glyph File 2"]

        val egg = EggData(
            eggName = eggName,
            baseGenomeFile = baseGenome,
            fatherGenomeFile = fatherGenome,
            motherGenomeFile = motherGenome
        )
        return egg to Pair(maleEggGlyph, femaleEggGlyph)
    }

    private const val WILDCARD_REPLACEMENT = "@@::WILDCARD::@@"

    private fun getGenome(text: String?, genomes: Set<String>): String? {

        if (text == null) {
            return null
        }

        val fileNameLower = text
            .unescapePath()
            .ensureStartsWith("/")
            .lowercase()

        return (if (text.contains("*")) {
            genomes.firstOrNull { it.lowercase().endsWith(fileNameLower) }
        } else {
            val regex = getAgentGenomeRegex(text)
            genomes.firstOrNull(regex::matches)
        }).also { genome ->
            if (genome == null) {
                Log.iIf(LOG_DEBUG) {
                    "Genome not found for $text"
                }
            }
        }
    }

    private fun getAgentGenomeRegex(genomeWithWildcard: String): Regex {
        var regexString = Regex.escape(genomeWithWildcard.replace("*", WILDCARD_REPLACEMENT))
            .replace(WILDCARD_REPLACEMENT, ".*")
            .lowercase()
            .ensureEndsWith(".gen")
        regexString = ".*?/$regexString$"
        return regexString.toRegex(RegexOption.IGNORE_CASE)
    }

    private suspend fun getGlyph(file: String?, files: Map<String, BinaryFile>): SpriteGlyph? {
        if (file == null) {
            return null
        }
        val lowercase = file
            .lowercase()
            .ensureStartsWith('/')

        val data = files
            .entries
            .firstOrNull() { it.key.lowercase().endsWith(lowercase) }
            ?.value
            ?: return null.also {
                Log.iIf(LOG_DEBUG) { "Failed to find glyph for file: $file" }
            }
        Log.iIf(LOG_VERBOSE) { "Glyph file was found to be: ${data.name}" }
        return getGlyph(file, data.read())
    }

    private fun getGlyph(file: String, bytes: ByteArray): SpriteGlyph {
        return SpriteGlyph.create(getFileName(file) ?: file, 0, file, bytes)
    }

    private suspend fun getGenomeGenus(egg: EggData, files: Map<String, BinaryFile>): Int? {
        val genome = egg.baseGenomeFile?.filepath
            ?: return null.also {
                Log.iIf(LOG_DEBUG) { "Cannot get egg genus; Egg has no base genome" }
            }

        val lower = genome.lowercase()

        val genomeBytes = files.entries
            .firstOrNull { it.key.lowercase() == lower }
            ?.value
            ?.read()

        return if (genomeBytes != null) {
            try {
                GenomeParser.parseGenome(genomeBytes).genus()
            } catch (e: Exception) {
                e.rethrowCancellationException()
                Log.e("Failed to parse genome; ${e.formatted(true)}")
                null
            }
        } else {
            null
        }
    }
}

