    private var mEnableNamespaceLoggingInMain = false
    val enableNamespaceLoggingInMain get() = mEnableNamespaceLoggingInMain

    private val mNamespaceLoggerListeners = mutableListOf<NamespaceLoggerListener>()
    private val mNamespacedLoggerListeners = mutableMapOf<String, MutableList<NamespaceLoggerListener>>()

    val namespaceLoggerListeners get() = mNamespaceLoggerListeners
    val namespacedLoggerListeners get() = mNamespacedLoggerListeners
    /**
     * Allow sending logging statements with namespace prefix
     * to normal command line logging
     * i.e. "%{namespace}%{message}" with namespace surrounded with '%'
     * @param allow allow sending prefix logging messages to main logging
     */
    fun setEnableNamespaceLoggingInMain(allow: Boolean) {
        mEnableNamespaceLoggingInMain = allow
    }

    /**
     * Add logging listener to listen for namespaced messages
     * Best used if enableNamespaceLoggingInMain is false (default)
     *
     * @param listener
     */
    fun addNamespaceLoggerListener(listener: NamespaceLoggerListener) {
        mNamespaceLoggerListeners.add(listener)
    }

    fun removeNamespaceLoggerListener(listener: NamespaceLoggerListener) {
        mNamespaceLoggerListeners.remove(listener)
    }

    /**
     * Add logging listener to be called only when a specific namespace is used
     * Best used if enableNamespaceLoggingInMain is false (default)
     *
     * @param listener
     */
    fun addNamespacedLoggerListener(namespace: String, listener: NamespaceLoggerListener) {
        mNamespacedLoggerListeners[namespace]?.let {
            it.add(listener)
            return
        }
        mNamespacedLoggerListeners[namespace] = mutableListOf(listener)
    }

    /**
     * Remove listener from specific namespace
     *
     * @param namespace
     * @param listener
     */
    fun removeNamespacedLoggerListener(namespace: String, listener: NamespaceLoggerListener) {
        mNamespacedLoggerListeners[namespace]?.let {
            it.remove(listener)
            if (it.isEmpty()) {
                mNamespacedLoggerListeners.remove(namespace)
            }
        }
    }

    /**
     * Remove a logger listener from all namespaces it may have been registered with
     *
     * @param listener
     */
    fun removeNamespacedLoggerListenerFromAll(listener: NamespaceLoggerListener) {
        mNamespacedLoggerListeners.keys.forEach {
            removeNamespacedLoggerListener(it, listener)
        }
    }

    /**
     * Notifies all interested namespace logger listeners
     *
     * @param namespace
     * @param message
     * @param color
     * @receiver
     */
    inline fun notifyNamespaceListeners(namespace: String, message: () -> String, color: LoggerColor? = null) {
        contract {
            callsInPlace(message, InvocationKind.EXACTLY_ONCE)
        }
        notifyNamespaceListeners(namespace, message(), color)
    }

    /**
     * Notify all interested namespace listeners
     *
     * @param namespace
     * @param message
     * @param color
     */
    fun notifyNamespaceListeners(namespace: String, message: String, color: LoggerColor? = null) {
        // Notify general listeners
        notifyNamespaceListeners(namespaceLoggerListeners, namespace, message, color)

        // Notify scoped listeners
        namespacedLoggerListeners[namespace]?.also {
            notifyNamespaceListeners(it, namespace, message, color)
        }
    }

    /**
     * Notifies all namespace listeners in the given list
     *
     * @param listeners
     * @param namespace
     * @param message
     * @param color
     */
    fun notifyNamespaceListeners(
        listeners: List<NamespaceLoggerListener>,
        namespace: String,
        message: String,
        color: LoggerColor?,
    ) {
        for (notify in listeners) {
            notify(namespace, message, color)
        }
    }

