    /**
     * Formats a message with a given kind and classname
     * Kind being along the lines of info, error, warning
     */
    inline fun format(kind: String, className: String?, message: () -> String): String {
        contract {
            callsInPlace(message, InvocationKind.EXACTLY_ONCE)
        }
        return format(kind, className, message())
    }

    /**
     * Formats a message with a given kind and classname
     * Kind being along the lines of info, error, warning
     */
    fun format(kind: String, className: String?, message: String): String {
        val prependLog = (loggerObject.prependLogType ?: DefaultLoggerObject.prependLogType)
        val prefix = if (prependLog && !hasMode(LOG_NO_PRINT_PREFIX)) {
            "**${kind}** "
        } else {
            ""
        }
        return "$prefix${if (!className.isNullOrBlank()) "$className::" else ""}${message}"
    }

