    /**
     * Sets if a mode is active
     */
    @JvmStatic
    fun hasMode(mode: String): Boolean {
        return mode in modes
    }

    /**
     * Sets a mode state for this logger
     */
    @JvmStatic
    fun setMode(mode: String, active: Boolean) {
        val hasMode = mode in modes
        if (active == hasMode) {
            return
        }
        if (active) {
            modes.add(mode)
        } else {
            modes.remove(mode)
        }
    }

    /**
     * Set logger to use with the global Log object
     */
    @JvmStatic
