     */
    @JvmStatic
    fun useDefaultLogger() {
        mLoggerObject = DefaultLoggerObject
    }

    fun namespaceLogComponents(statement: String): Pair<String?, String> {
        return namespacePrefixRegex.matchEntire(statement)
            ?.groupValues
            ?.let {
                Pair(it[1], it[2])
            }
            ?: Pair(null, statement)
    }
