@Suppress("RegExpUnnecessaryNonCapturingGroup")
private val stackTraceRegex =
    "^\\s*java\\.lang\\.Exception(?:(\\s*at com\\.bedalton\\.log\\.Log[.\$][^\\n]*\\n)*)".toRegex(
        setOf(
            RegexOption.IGNORE_CASE,
            RegexOption.MULTILINE
        )
    )

fun shiftLogStackFromCallStack(stack: String): String {
    return stack.replace(stackTraceRegex, "")
}