package com.bedalton.creatures.sprite.util

import com.bedalton.creatures.sprite.parsers.PixelIndices
import com.bedalton.creatures.sprite.parsers.SpriteFrameAsync

fun SpriteFrameAsync.isTransparent(): Boolean {
    return !pixelIndices().pixels.any { it != PixelIndices.TRANSPARENT_BLACK }
}

fun SpriteFrameAsync.isPossiblyNeedsMirror(): Boolean {
    return width == height && isTransparent()
}


fun PixelIndices.isTransparent(): Boolean {
    return pixels.any { it != PixelIndices.TRANSPARENT_BLACK }
}

fun PixelIndices.isPossiblyNeedsMirror(): Boolean {
    return width == height && isTransparent()
}