@file:Suppress("unused", "MemberVisibilityCanBePrivate")

package com.bedalton.creatures.breed.render.renderer

import com.bedalton.common.structs.Size
import com.bedalton.creatures.breed.render.files.BodyPartFiles
import com.bedalton.creatures.breed.render.internal.commonLibSize
import com.bedalton.creatures.breed.render.support.pose.Pose
import com.bedalton.creatures.breed.render.support.render.ParsedBodyPartRenderData
import com.bedalton.creatures.breed.render.support.render.RenderOffsetUtil
import com.bedalton.creatures.breed.render.support.render.RenderOffsets
import com.bedalton.vfs.FileSystem
import korlibs.image.bitmap.Bitmap32
import kotlin.coroutines.CoroutineContext
import kotlin.coroutines.coroutineContext

object DataToOffsets {
    internal suspend fun getOffset(
        coroutineContext: CoroutineContext,
        fs: FileSystem,
        pose: Pose,
        data: List<BodyPartFiles>,
        nonIntersectLimbs: Boolean
    ): RenderOffsets<Bitmap32>? {
        return RenderOffsetUtil.getRenderOffsets(
            coroutineContext,
            pose,
            toParsedBodyPartRenderData(fs, data),
            nonIntersectLimbs,
            Bitmap32::commonLibSize
        )
    }
    suspend fun <ImageT> getOffset(
        pose: Pose,
        data: List<ParsedBodyPartRenderData<ImageT>>,
        nonIntersectLimbs: Boolean,
        trueSize: ((ImageT) -> Size)? = null
    ): RenderOffsets<ImageT>? {
        return getOffset(
            coroutineContext,
            pose,
            data,
            nonIntersectLimbs,
            trueSize
        )
    }

    suspend fun <ImageT> getOffset(
        context: CoroutineContext,
        pose: Pose,
        data: List<ParsedBodyPartRenderData<ImageT>>,
        nonIntersectLimbs: Boolean,
        trueSize: ((ImageT) -> Size)? = null
    ): RenderOffsets<ImageT>? {
        return RenderOffsetUtil.getRenderOffsets(
            coroutineContext = context,
            pose = pose,
            parts = data.associateBy {
                it.part
            },
            nonIntersectingLimbs = nonIntersectLimbs,
            trueSize = trueSize
        )
    }

    suspend fun <ImageT> getOffset(
        pose: Pose,
        data: Map<Char, ParsedBodyPartRenderData<ImageT>>,
        nonIntersectLimbs: Boolean,
        trueSize: ((ImageT) -> Size)? = null
    ): RenderOffsets<ImageT>? {
        return getOffset(
            coroutineContext,
            pose,
            data,
            nonIntersectLimbs,
            trueSize
        )
    }

    suspend fun <ImageT> getOffset(
        context: CoroutineContext,
        pose: Pose,
        data: Map<Char, ParsedBodyPartRenderData<ImageT>>,
        nonIntersectLimbs: Boolean,
        trueSize: ((ImageT) -> Size)? = null
    ): RenderOffsets<ImageT>? {
        return RenderOffsetUtil.getRenderOffsets(
            context,
            pose,
            data,
            nonIntersectLimbs,
            trueSize
        )
    }
}

internal suspend fun toParsedBodyPartRenderData(fs: FileSystem,data: List<BodyPartFiles>): Map<Char, ParsedBodyPartRenderData<Bitmap32>> {
    return data.mapNotNull {
        it.toParsedBodyPartRenderData(fs)?.let { data ->
            it.part to data
        }
    }.toMap()
}