package com.bedalton.creatures.agents.pray.compiler

/**
 * Compiler options which include an optional overriding name.
 * Name is meant to override one set in a CAOS2Pray or CAOS2Cob file
 */
actual external interface PrayCompileOptionsWithOverrideName : PrayCompileOptions {
    /**
     * Name to use instead of the one supplied in the pray file
     */
    actual val overrideAgentName: String?
}

actual val PrayCompileOptions.overrideAgentNameOrNull: String? get() {
    return asDynamic().overrideAgentName as String?
}