package com.bedalton.creatures.caos.validation.internal

import com.bedalton.common.ast.structs.inRange
import com.bedalton.creatures.caos.collectors.CaosParserItem
import com.bedalton.creatures.caos.collectors.CommandCall
import com.bedalton.creatures.caos.collectors.EQ_COMMAND_TOKEN
import com.bedalton.creatures.caos.libs.*

private val C1E_ANIMATION_BYTE_STRING = "\\[\\s*\\d+(\\s*\\d+)(\\s*[Rr])\\s*\\]".toRegex()

internal fun addVariantStringErrors(
    variant: CaosVariant,
    items: Array<CaosParserItem>,
    commandCalls: Array<CommandCall>,
    errors: MutableList<CaosParserItem.ErrorVal>,
    checkCancelled: () -> Unit,
) {
    val isOldVariant = variant.isOld
    val error = if (isOldVariant) {
        "Quote strings are invalid in $variant"
    } else {
        "Bracket strings are invalid in CV+ variants"
    }

    val badStrings = (if (isOldVariant) {
        items.filter { item ->
            checkCancelled()
            item.typeToken == TypeTokens.QUOTE_STRING
        }
    } else {
        items.filter { item ->
            checkCancelled()

            if (item.typeToken != TypeTokens.BRACKET_STRING && item.typeToken != TypeTokens.BYTE_STRING) {
                return@filter false
            }

            if (item.value != "" && item.typeToken == TypeTokens.BRACKET_STRING && !C1E_ANIMATION_BYTE_STRING.matches(item.text)) {
                return@filter true
            }

            val range = item.textRange
            val command = commandCalls.firstOrNull { inRange(
                it.textRange,
                range.start.line,
                range.start.character,
                ignoreColumn = false,
                soft = true
            ) }
                ?: return@filter false

            val expectedType = drillDownToParameter(command, range.start.line, range.start.character + 1)?.typeId
                ?: return@filter false

            if (expectedType == ValueType.BYTE_STRING.value || expectedType == ValueType.ANIMATION.value) {
                return@filter item.typeToken != TypeTokens.BYTE_STRING && (item.typeToken != TypeTokens.BRACKET_STRING || item.value.toString().trim() != "")
            }
            return@filter expectedType != ValueType.BYTE_STRING.value && expectedType != ValueType.ANIMATION.value
        }
    }).map {
        CaosParserItem.ErrorVal(
            textRange = it.textRange,
            message = error,
            type = ErrorTypes.OUT_OF_VARIANT,
            text = it.text
        )
    }
    errors.addAll(badStrings)

    if (isOldVariant) {
        val stringInEqErrors = commandCalls
            .filter { command ->
                checkCancelled()
                command.command.command.lowercase() == EQ_COMMAND_TOKEN
            }
            .flatMap { command ->
                command.arguments
                    .filter { argument ->
                        argument.type in stringLikeTypesAsInt
                    }
            }
            .map { argument ->
                CaosParserItem.ErrorVal(
                    textRange = argument.textRange,
                    message = STRINGS_IN_EQ_ERROR,
                    type = ErrorTypes.OUT_OF_VARIANT,
                    text = argument.text
                )
            }
        errors.addAll(stringInEqErrors)
    }
}

private val stringLikeTypesAsInt: List<Int> = listOf(
    ValueType.STRING.value,
    ValueType.C1_STRING.value,
    ValueType.HEXADECIMAL.value,
    ValueType.BYTE_STRING.value,
    ValueType.ANIMATION.value
)

private const val STRINGS_IN_EQ_ERROR = "Strings in equality statement are allowed in CV+ variants only"


private fun drillDownToParameter(command: CommandCall, line: Int, character: Int): VariantCaosParameter? {
    for ((i, arg) in command.arguments.withIndex()) {
        if (!inRange(arg.textRange, line, character, ignoreColumn = false, soft = true)) {
            continue
        }
        return if (arg is CommandCall) {
            drillDownToParameter(arg, line, character)
        } else {
            command.command.parameters[i]
        }
    }
    return null
}