package com.bedalton.creatures.agents.pray.compiler.internal

import com.bedalton.creatures.agents.pray.compiler.SCRIPT_TAG_REGEX
import com.strumenta.kotlinmultiplatform.BitSet
import com.bedalton.creatures.pray.parser.*
import org.antlr.v4.kotlinruntime.*
import org.antlr.v4.kotlinruntime.atn.ATNConfigSet
import org.antlr.v4.kotlinruntime.dfa.DFA
import org.antlr.v4.kotlinruntime.tree.ParseTreeWalker
import com.bedalton.creatures.agents.pray.compiler.data.CompilerPrayData
import com.bedalton.creatures.agents.pray.compiler.data.Tag
import com.bedalton.creatures.agents.pray.compiler.data.CompilerBlockWithTags

internal fun statParse(prayData: CompilerPrayData) : Map<String, Array<Int>> {
    return prayData.blocks
        .filterIsInstance<CompilerBlockWithTags>()
        .flatMap { block ->
            blockStats(block.stringTags).entries.map { (key, value) ->
                key to value
            }
        }
        .toMap()

}

internal fun blockStats(stringTags:Array<Tag.StringTag>) : Map<String, Array<Int>> {
    val mergedScripts = stringTags.filter { tag ->
        SCRIPT_TAG_REGEX.matches(tag.tag)
    }.joinToString("\n\n") {
        it.value
    }

    val charStream = CharStreams.fromString(mergedScripts)
    val lexer = StatLexer(charStream)
    val tokenStream = CommonTokenStream(lexer)
    val parser = StatParser(tokenStream)
    val walker = Walker()
    parser.addErrorListener(walker)
    ParseTreeWalker.DEFAULT.walk(walker, parser.file())
    return walker.map.map {
        it.key to it.value.toTypedArray()
    }.toMap()
}


private fun <R,T> push(map:MutableMap<R, MutableSet<T>>, key:R, value:T) {
    val list = map[key] ?: mutableSetOf<T>().apply {
        map[key] = this
    }
    list.add(value)
}


private class Walker : StatParserBaseListener(), ANTLRErrorListener {
    val map:MutableMap<String, MutableSet<Int>> = mutableMapOf()
    override fun enterConstruct(ctx: StatParser.ConstructContext) {
        super.enterConstruct(ctx)

        // Only gather family/genus/species literals
        val family = ctx.findFamily()?.INT()?.text
            ?: return
        val genus = ctx.findGenus()?.INT()?.text
            ?: return
        val species = ctx.findSpecies()?.INT()?.text
            ?: return
        val key = "$family $genus $species"
        if (map.containsKey(key))
            return
        map[key] = mutableSetOf()
    }

    override fun enterScript(ctx: StatParser.ScriptContext) {
        super.enterScript(ctx)
        // Only gather family/genus/species literals
        val family = ctx.findFamily()?.INT()?.text
            ?: return
        val genus = ctx.findGenus()?.INT()?.text
            ?: return
        val species = ctx.findSpecies()?.INT()?.text
            ?: return
        val event = ctx.findEvent()?.INT()?.text?.toIntOrNull()
            ?: return
        val key = "$family $genus $species"
        push(map, key, event)
    }

    override fun reportAmbiguity(
        recognizer: Parser,
        dfa: DFA,
        startIndex: Int,
        stopIndex: Int,
        exact: Boolean,
        ambigAlts: BitSet,
        configs: ATNConfigSet
    ) {

    }

    override fun reportAttemptingFullContext(
        recognizer: Parser,
        dfa: DFA,
        startIndex: Int,
        stopIndex: Int,
        conflictingAlts: BitSet,
        configs: ATNConfigSet
    ) {
    }

    override fun reportContextSensitivity(
        recognizer: Parser,
        dfa: DFA,
        startIndex: Int,
        stopIndex: Int,
        prediction: Int,
        configs: ATNConfigSet
    ) {
    }

    override fun syntaxError(
        recognizer: Recognizer<*, *>,
        offendingSymbol: Any?,
        line: Int,
        charPositionInLine: Int,
        msg: String,
        e: RecognitionException?
    ) {
        throw e ?: Exception("Invalid input '${(offendingSymbol as Token).text}' at $line:$charPositionInLine")
    }
}