@file:Suppress("unused", "MemberVisibilityCanBePrivate")

package com.bedalton.creatures.breed.render.files

import com.bedalton.common.coroutines.AlreadyDisposedException
import com.bedalton.common.structs.Size
import com.bedalton.creatures.breed.render.internal.assertConcrete
import com.bedalton.creatures.breed.render.internal.filePathDistance
import com.bedalton.creatures.breed.render.support.att.AttFileData
import com.bedalton.creatures.breed.render.support.att.AttFileParser
import com.bedalton.creatures.breed.render.support.render.ParsedBodyPartRenderData
import com.bedalton.creatures.common.structs.GameVariant
import com.bedalton.creatures.sprite.parsers.SpriteFrameAsync
import com.bedalton.creatures.sprite.parsers.SpriteFrameAsyncImpl
import com.bedalton.creatures.sprite.parsers.SpriteParserAsync
import com.bedalton.creatures.sprite.util.PaletteTransform
import com.bedalton.creatures.sprite.util.isPossiblyNeedsMirror
import com.bedalton.io.bytes.MemoryByteStreamReader
import com.bedalton.vfs.FileSystem
import korlibs.image.bitmap.Bitmap32
import kotlinx.coroutines.sync.Mutex
import kotlinx.coroutines.sync.withLock


data class BodyPartFiles(
    val gameVariant: GameVariant,
    val part: Char,
    val attFile: BreedFileData?,
    val spriteFile: BreedFileData,
    private val paletteTransform: PaletteTransform? = null,
) {


    private val lock = Mutex(false)
    private val attLock = Mutex(false)
    private val imagesLock = Mutex(false)

    // Breed key is prioritized on the sprite
    val breedPartKey get() = spritePartKey

    internal val distance by lazy {
        if (fileDistance != null && attFile != null) {
            filePathDistance(fileDistance!!, spriteFile, attFile, null)
        } else {
            null
        }
    }


    /**
     * The part key for this body part's sprite.
     * ATT and Sprite breed keys are separate as they may not match as ATTs are used across multiple breeds
     */
    private val spritePartKey by lazy {
        spriteFile.breedPartKey.also {
            it.assertConcrete("Breed file data")
        }
    }

    /**
     * The part key for this body part's ATT.
     * ATT and Sprite breed keys are separate as they may not match
     */
    private val attPartKey by lazy {
        attFile?.breedPartKey
    }

    /**
     * The distance between this sprite, and this body part
     */
    private val fileDistance by lazy {
        val attPartKey = attPartKey
            ?: return@lazy null
        val spritePartKey = spritePartKey
        spritePartKey.distance(attPartKey)
    }

    private var mTriedLoadImagesOnce = false
    private var mImages: List<SpriteFrameAsync>? = null

    suspend fun images(fs: FileSystem, lockKey: Any? = null): List<SpriteFrameAsync>? = imagesLock.withLock(lockKey) {
        val frames = loadIf(
            fs = fs,
            lastValue = mImages,
            path = spriteFile,
            loadedOnce = mTriedLoadImagesOnce
        ) { data ->
            val reader = MemoryByteStreamReader(data)
            val extension = spriteFile.extension
            val loader: List<SpriteFrameAsync> = SpriteParserAsync.parse(
                extension,
                reader,
                paletteTransform,
                4,
            ).apply {
                mImages = this
                mTriedLoadImagesOnce = true
            }
            loader
        }
        frames
    }

    var mTriedLoadAttOnce = false
    var mAtt: AttFileData? = null

    suspend fun att(fs: FileSystem, lockKey: Any? = null): AttFileData? = attLock.withLock(lockKey) lock@{
        if (attFile == null) {
            return@lock null
        }
        loadIf(
            fs = fs,
            lastValue = mAtt,
            path = attFile,
            loadedOnce = mTriedLoadAttOnce
        ) {
            val data = it.decodeToString()
            AttFileParser.parse(data)
        }.also {
            mTriedLoadAttOnce = true
            this.mAtt = it
        }
    }

    suspend fun <T> loadIf(
        fs: FileSystem,
        lastValue: T?,
        path: BreedFileData,
        loadedOnce: Boolean,
        transform: suspend (bytes: ByteArray) -> T?,
    ): T? {
        lastValue?.let {
            return it
        }
        if (loadedOnce) {
            return null
        }
        val data = path.read(fs)
        return transform(data)
    }


    private var parsedBodyPartRenderData: ParsedBodyPartRenderData<Bitmap32>? = null
    private var didTryLoadParsedBodyPartRenderDataOnce: Boolean = false

    /**
     * Creates a ParsedBodyPartRenderData object out of this internal data class
     * ParsedBodyPartRenderData is data that is already parsed and ready to render
     */
    suspend fun toParsedBodyPartRenderData(fs: FileSystem): ParsedBodyPartRenderData<Bitmap32>? =
        lock.withLock(this) lock@{

            // Get cached body part data if any
            parsedBodyPartRenderData?.let {
                return@lock it
            }

            // Check if tried to load already
            if (didTryLoadParsedBodyPartRenderDataOnce) {
                // load had failed previously (otherwise it would have been non-null earlier)
                return@lock null
            }

            // Mark load as attempted
            didTryLoadParsedBodyPartRenderDataOnce = true

            // Get images
            var frames: List<SpriteFrameAsync>? = images(fs, this)
                ?: return@lock null

            // Get ATTs
            val att = att(fs, this)
                ?: return@lock null

            var mirrorCache: MutableMap<Int, Bitmap32>? = mutableMapOf()
            // Construct part data
            (ParsedBodyPartRenderData(
                part = part,
                frameInfo = frames!!.map { Size(it.width, it.height) },
                attData = att,
                onDispose = {
                    parsedBodyPartRenderData
                    didTryLoadParsedBodyPartRenderDataOnce = false
                    frames = null
                    mImages?.forEach { it.dispose() }
                    mImages = null
                    mirrorCache = null
                }
            ) { i ->
                mirrorCache?.get(i)?.let {
                    return@ParsedBodyPartRenderData it
                }

                val framesNotNull = frames
                    ?: throw AlreadyDisposedException("Images already disposed in Body Part Sprites")

                val needsMirror = framesNotNull[i].isPossiblyNeedsMirror()
                if (needsMirror) {
                    val mirrored = getMirrored(framesNotNull, i)?.also { mirrored ->
                        mirrorCache?.set(i, mirrored)
                    }
                    mirrored ?: framesNotNull[i].image(false)
                } else {
                    framesNotNull[i].image(false)
                }
            }).apply {
                // cache value
                parsedBodyPartRenderData = this
            }
        }
}

private fun needsMirror(image: Bitmap32): Boolean {
    return image.width == image.height && isTransparent(image)
}

private fun isTransparent(image: Bitmap32): Boolean {
    return image.all { it.a == 0 }
}

private fun getMirrored(frames: List<SpriteFrameAsync>, poseSpriteIndex: Int): Bitmap32? {
    val mirroredIndex = when {
        poseSpriteIndex in 0..3 -> 4 + poseSpriteIndex
        poseSpriteIndex in 4..7 -> poseSpriteIndex - 4
        else -> return null
    }
    val frame = frames.getOrNull(mirroredIndex)
        ?: return null
    return frame.image().flipX().toBMP32IfRequired()
}