internal object PrayScriptParserUtil {
    suspend fun parse(
        coroutineScope: CoroutineScope,
        fs: RelativeFileSystem,
        prayFile: String,
        opts: PrayCompileOptions = PrayCompileOptionsImpl(),
    ): CompilerPrayData {

        val fileName = if (prayFile.contains('\n') || prayFile.contains('"') || prayFile.contains('*')) {
            // Without full file path, a filename is constructed that holds a hash of these contents
            // Hopefully should prevent using the same file contents more than once
            val firstFewCharactersMD5 = prayFile.substring(0, min(120, prayFile.length))
                .replace(NEWLINE_REGEX, "")
                .let {
                    MD5.compute(it.encodeToByteArray()).toHexString()
                }
            "StringContents::" + firstFewCharactersMD5 + MD5.compute(prayFile.encodeToByteArray()).toHexString()
        } else {
            prayFile
        }

        return parse(
            coroutineScope,
            fs,
            fileName,
            prayFile,
            opts
        )
    }

    suspend fun parse(
        coroutineScope: CoroutineScope,
        fs: RelativeFileSystem,
        fullFilePath: String,
        prayFile: String,
        opts: PrayCompileOptions = PrayCompileOptionsImpl()
    ): CompilerPrayData {


        val prayFileText = if (prayFile.contains('\n') || prayFile.contains("\"") || prayFile.contains("*")) {
            prayFile
        } else {
            if (!fs.fileExists(prayFile)) {
                throw FileNotFoundException("Failed to locate pray file at ${fs.path(prayFile)}")
            }
            fs.readAsText(prayFile)
        }

        val errors: MutableList<PrayValidationError> = mutableListOf()

        // Set up parser/walker
        val charStream = CharStreams.fromString(prayFileText)
        val lexer = PrayLexer(charStream)
        val tokenStream = CommonTokenStream(lexer)
        val parser = PrayParser(tokenStream)
        val walker = PrayFileWalker(fullFilePath, errors, opts.linkWithFilenameReferenceNotNull)
        parser.addErrorListener(walker)

        // Walk parse result
        ParseTreeWalker.DEFAULT.walk(walker, parser.file())
        var blocks = if (opts.mergeRscr) {
            walker.blocks.map { block ->
                combineRscr(coroutineScope, fs, block)
            }
        } else {
            walker.blocks
        }

        if (opts.generateScriptRemovers || opts.generateAgentRemovers) {
            blocks = blocks.map {
                if (it is CompilerBlockWithTags)
                    it.copyWithTags(tagsWithGeneratedRemovers(it.tags, opts))
                else
                    it
            }
        }

        if (opts.mergeScripts) {
            blocks = blocks.map { block ->
                mergeScriptInBlock(fs, block)
            }
        }

        return CompilerPrayData(
            language = walker.lang,
            fullFilePath = fullFilePath,
            blocks = blocks.toTypedArray(),
            inlineFiles = walker.inlineFiles.toUniqueArray(),
            parseErrors = errors.toTypedArray(),
            unescape = true
        )
    }

    private suspend fun mergeScriptInBlock(fs: RelativeFileSystem, block: CompilerPrayBlock): CompilerPrayBlock {
        if (block !is CompilerBlockWithTags)
            return block
        val tags = block.tags
        val unspecificTags = tags.filter { tag ->
            (tag is Tag.IntTag && !SCRIPT_COUNT_TAG_REGEX.matches(tag.tag)) || (tag is Tag.StringTag && !SCRIPT_TAG_REGEX.matches(
                tag.tag))
        }
        val specificTags = tags.filter {
            it !is Tag.IntTag && SCRIPT_TAG_REGEX.matches(it.tag)
        }.map { tag ->
            if (tag is Tag.LinkTag) {
                Tag.StringTag(
                    lineNumber = tag.lineNumber,
                    originalLineNumber = tag.lineNumber,
                    startIndex = tag.startIndex,
                    endIndex = tag.endIndex,
                    tagRange = tag.tagRange,
                    valueRange = tag.valueRange,
                    value = fs.readAsText(tag.value)
                )
            } else {
                tag
            }
        }
        val combinedScript = "* Pray compiler. Combine all Scripts\n\n" + specificTags
            .joinToString("\n\n") { tag ->
                "* Combining \"${tag.tag}\"\n" + tag.value
            }
        val combinedScriptTag = Tag.StringTag(
            lineNumber = -1,
            startIndex = -1,
            endIndex = -1,
            tagRange = TextValue(
                "Script 1",
                lineNumber = -1,
                startIndex = -1,
                endIndex = -1
            ),
            value = TextValue(
                text = combinedScript,
                lineNumber = 0,
                startIndex = -1,
                endIndex = -1
            )
        )
        val scriptCountTag = Tag.IntTag(
            lineNumber = -1,
            startIndex = -1,
            endIndex = -1,
            tagRange = TextValue(
                "Script Count",
                lineNumber = -1,
                startIndex = -1,
                endIndex = -1,
            ),
            value = TextValue(
                text = "1",
                lineNumber = 0,
                startIndex = -1,
                endIndex = -1
            ),
            tagValue = 1
        )

        return block.copyWithTags(
            (unspecificTags + scriptCountTag + combinedScriptTag).toTypedArray()
        )
    }
}

private class PrayFileWalker(
    private val fullFilePath: String,
    private val errors: MutableList<PrayValidationError>,
    private val linkWithFilenameReference: Boolean
) : PrayParserBaseListener(), ANTLRErrorListener {
    var lang: TextValue? = null
    var blockStart: Int = -1
    var blockTag: TextValue? = null
    var blockName: TextValue? = null
    val inlineFiles: MutableList<InlineFile> = mutableListOf()
    val blocks: MutableList<CompilerPrayBlock> = mutableListOf()
    val tags: MutableList<Tag<*>> = mutableListOf()


    override fun enterBlockHeader(ctx: PrayParser.BlockHeaderContext) {
        super.enterBlockHeader(ctx)
        closeBlock(ctx.start!!.line)
        blockStart = ctx.start!!.line
        blockTag = ctx.findBlockType()?.toCommandValueValue()
        blockName = ctx.findBlockName()?.toCommandValueValue()
    }

    override fun enterIntTag(ctx: PrayParser.IntTagContext) {
        super.enterIntTag(ctx)
        val tagName = ctx.findTagName()
            ?.toCommandValueValue()
            ?: return
        val tagValue = ctx.findTagIntValue()
            ?: return
        tags.add(Tag.IntTag(
            lineNumber = ctx.start!!.line,
            startIndex = ctx.startIndex,
            endIndex = ctx.stopIndex,
            tagRange = tagName,
            value = TextValue(
                value = tagValue.text.toInt(),
                lineNumber = tagValue.line,
                startIndex = tagValue.startIndex,
                endIndex = tagValue.stopIndex
            )
        ))
    }

    override fun enterStringTag(ctx: PrayParser.StringTagContext) {
        super.enterStringTag(ctx)
        val tagName = ctx.findTagName()
            ?.toCommandValueValue()
            ?: return
        val tagValue = ctx.findTagStringValue()
            ?: return
        val tagValueString = tagValue
            .text
            .trim()
            .stripSurroundingQuotes()
//
//        // Unescape string only if it proves to not be an actual path
//        val value = if (fs.fileExists(tagValueString)) {
//            tagValueString
//        } else {
//            tagValueString.superUnescape(' ', '"', '\'')
//        }
        tags.add(Tag.StringTag(
            lineNumber = ctx.start!!.line,
            startIndex = ctx.startIndex,
            endIndex = ctx.stopIndex,
            tagRange = tagName,
            value = TextValue(
                text = tagValueString.unescape(),
                lineNumber = tagValue.line,
                startIndex = tagValue.startIndex,
                endIndex = tagValue.stopIndex
            )
        ))
    }

    override fun enterInlineFile(ctx: PrayParser.InlineFileContext) {
        super.enterInlineFile(ctx)

        val inputFile = ctx.findInputFileName()
            ?.toCommandValueValue()
        val outputFile = ctx.findOutputFileName()
            ?.toCommandValueValue()
        if (inputFile == null || outputFile == null) {
            val range = ctx.toCommandValueValue()
            if (inputFile == null) {
                errors.add(
                    CommandError(
                        "INLINE",
                        errorRange = range,
                        commandRange = range,
                        message = "Inline file input file name is blank",
                        fullFilePath = fullFilePath
                    )
                )
            }
            if (inputFile == null) {
                errors.add(
                    CommandError(
                        "INLINE",
                        errorRange = range,
                        commandRange = range,
                        message = "Inline file output file name is blank",
                        fullFilePath = fullFilePath
                    )
                )
            }
            return
        }
        inlineFiles.add(
            InlineFile(
                lineNumber = ctx.line,
                startIndex = ctx.startIndex,
                endIndex = ctx.stopIndex,
                blockTag = ctx.BLOCK_TAG()!!.text,
                outputFileName = outputFile,
                inputFileName = inputFile,
                containingFile = fullFilePath
            )
        )
    }

    override fun enterLang(ctx: PrayParser.LangContext) {
        super.enterLang(ctx)
        lang = ctx.toCommandValueValue()
    }

    override fun enterLoaderTag(ctx: PrayParser.LoaderTagContext) {
        super.enterLoaderTag(ctx)
        val tagName = ctx.findTagName()
            ?.toCommandValueValue()

        if (tagName == null) {
            val errorRange: HasRange = ctx.toCommandValueValue()
            errors.add(
                CommandError(
                    "@",
                    commandRange = errorRange,
                    errorRange = errorRange,
                    message = "Tag name in link '@' command cannot be blank",
                    fullFilePath = fullFilePath
                )
            )
            return
        }
        val fileNameCtx = ctx.findInputFileName()
        val fileName = fileNameCtx?.toCommandValueValue()
        if (fileName == null) {
            val errorRange: HasRange = ctx.toCommandValueValue()
            errors.add(
                CommandError(
                    "@",
                    commandRange = errorRange,
                    errorRange = errorRange,
                    message = "File name in link '@' command cannot be blank",
                    fullFilePath = fullFilePath
                )
            )
            return
        }
        //?.text?.trim()?.stripSurroundingQuotes()
        //            ?: throw PrayParseException(ctx.start!!.line, "Script tag name is blank")
        val linkedFile = Tag.LinkTag(
            lineNumber = ctx.line,
            startIndex = ctx.startIndex,
            endIndex = ctx.stopIndex,
            tagRange = tagName,
            value = fileName
        )
        tags.add(linkedFile)
    }

    private fun closeBlock(line: Int) {
        val blockTag = blockTag
        if (blockTag == null || blockTag.text.isBlank()) {
            if (tags.isNotEmpty()) {
                errors.add(
                    NoBlockError(
                        lineNumber = line,
                        startIndex = -1,
                        endIndex = -1,
                        message = "No pray block defined, but tags were found anyways",
                        fullFilePath = fullFilePath
                    )
                )
            }
            return
        }
        val blockName = blockName
        if (blockName == null || blockName.text.isBlank()) {
            val error = NoBlockError(
                lineNumber = line,
                startIndex = -1,
                endIndex = -1,
                message = "Pray Block: ${blocks.size + 1} ($blockTag) is missing a block name value",
                fullFilePath = fullFilePath
            )
            errors.add(error)
            return
        }
        val blockTags = tags.toTypedArray()
        val block = makePrayBlock(
            startLine = blockStart,
            blockTag = blockTag,
            blockName = blockName,
            unescape = true,
            tags = blockTags,
            linkWithFilenameReference = linkWithFilenameReference
        )
        blockStart = -1
        blocks.add(block)
        tags.clear()
    }

    override fun exitFile(ctx: PrayParser.FileContext) {
        closeBlock(blockStart)
        super.exitFile(ctx)
    }

    override fun reportAmbiguity(
        recognizer: Parser,
        dfa: DFA,
        startIndex: Int,
        stopIndex: Int,
        exact: Boolean,
        ambigAlts: BitSet,
        configs: ATNConfigSet,
    ) {

    }

    override fun reportAttemptingFullContext(
        recognizer: Parser,
        dfa: DFA,
        startIndex: Int,
        stopIndex: Int,
        conflictingAlts: BitSet,
        configs: ATNConfigSet,
    ) {

    }

    override fun reportContextSensitivity(
        recognizer: Parser,
        dfa: DFA,
        startIndex: Int,
        stopIndex: Int,
        prediction: Int,
        configs: ATNConfigSet,
    ) {

    }

    override fun syntaxError(
        recognizer: Recognizer<*, *>,
        offendingSymbol: Any?,
        line: Int,
        charPositionInLine: Int,
        msg: String,
        e: RecognitionException?,
    ) {
        val token = (offendingSymbol as? Token)
        val errorMessage = if (token != null) {
            "Failed to parse PRAY file. Unexpected input <${token.text}> at (${token.line}:${token.charPositionInLine})"
        } else {
            "Failed to parse PRAY file. $msg"
        }
        val error = SyntaxError(
            errorText = token?.text ?: offendingSymbol.toString(),
            message = errorMessage,
            lineNumber = line,
            startIndex = token?.startIndex ?: -1,
            endIndex = token?.stopIndex ?: -1,
            fullFilePath = fullFilePath
        )
        errors.add(error)
    }

}

