package com.creaturesforge.application.prompts

internal enum class MessageType {
    INFO,
    WARNING,
    ERROR
}

internal expect suspend fun showMessage(
    type: MessageType,
    title: String?,
    message: String
)

internal expect suspend fun showYesNoDialog(
    type: MessageType,
    title: String? = null,
    message: String,
    yesButtonText: String? = null,
    noButtonText: String? = null,
): Boolean

internal suspend fun showMessage(
    type: MessageType,
    message: String
) {
    showMessage(type, null, message)
}

internal expect suspend fun showConfirmCancelDialog(
    type: MessageType,
    title: String? = null,
    message: String,
    okayButtonText: String? = null,
    cancelButtonText: String? = null,
): Boolean

internal suspend fun showInfoMessage(message: String) {
    showMessage(MessageType.INFO, message)
}

internal suspend fun showInfoMessage(title: String, message: String) {
    showMessage(MessageType.INFO, title, message)
}

internal suspend fun showWarningMessage(message: String) {
    showMessage(MessageType.WARNING, message)
}

internal suspend fun showWarningMessage(title: String, message: String) {
    showMessage(MessageType.WARNING, title, message)
}

internal suspend fun showErrorMessage(message: String) {
    showMessage(MessageType.ERROR, message)
}

internal suspend fun showErrorMessage(title: String, message: String) {
    showMessage(MessageType.ERROR, title, message)
}

internal expect fun onOpenEggProgress(agentFileName: String, blockName: String, index: Int, total: Int?)

