package com.bedalton.creatures.sprite.util

import com.bedalton.creatures.sprite.compilers.SprCompiler
import korlibs.image.color.RGBA
import korlibs.memory.clampUByte

/**
 * Holds information needed to decode sprite color shorts
 */
@Suppress("unused")
enum class ColorEncoding(
    val simpleName: String,
    val marker: Int,
    private val encodeBitMasks: Triple<Int, Int, Int>,
    internal val decodeBitMask: Triple<Int, Int, Int>,
    internal val bitShifts: Triple<Int, Int, Int>,
) {
    // Holds information needed to decode a pixel from a 555 short
    X_555(
        "555",
        0,
        Triple(0xF8, 0xF8, 0xF8),
        Triple(0x7C00, 0x03E0, 0x001F),
        Triple(7, 2, 3)
    ),

    // Holds information needed to decode a pixel from a 565 short
    X_565(
        "565",
        1,
        Triple(0xF8, 0xFC, 0xF8),
        Triple(0xF800, 0x07E0, 0x001F),
        Triple(8, 3, 3)
    ),


    C1(
        "C1",
        -1,
        Triple(-1, -1, -1),
        Triple(-1, -1, -1),
        Triple(-1, -1, -1)
    );

    private val table = mutableMapOf<Int, RGBA>()

    val int32OpaqueBlackColorTable by lazy {
        Int32Palette(this, true)
    }


    val int32TransparentBlackColorTable by lazy {
        Int32Palette(this, true)
    }

    // Converts red/green/blue values into a short
    val toInt: RgbToInt by lazy {
        if (marker == -1) {
            { red: Int, green: Int, blue: Int ->
                SprCompiler.getColorIndex(ColorPalette.C1TransparentBlack, red, green, blue, false)
            }
        } else {
            { red: Int, green: Int, blue: Int ->
                ((red and encodeBitMasks.first) shl bitShifts.first) or
                        ((green and encodeBitMasks.second) shl bitShifts.second) or
                        ((blue and encodeBitMasks.third) shr bitShifts.third)
            }
        }
    }

    val blackish: Int by lazy {
        if (marker == -1) {
            return@lazy SprCompiler.getColorIndex(ColorPalette.C1TransparentBlack, 0, 0, 1, true)
        }
        var i = 0
        var black: Int
        do {
            i++
            black = toInt(i, i, i)
        } while (black == 0 && i < 65535)
        black
    }

    val blackishRGBA by lazy {
        toRgb(blackish)
    }

    /**
     * Converts a Short to a solid rgb
     */
    val toRgb: (pixel: Int) -> RGBA by lazy {
        if (marker == -1) {
            val black = if (this == C1) {
                ColorPalette.TRANSPARENT_BLACK
            } else {
                ColorPalette.OPAQUE_BLACK
            }
            { pixel: Int ->
                if (pixel == 0) {
                    black
                } else {
                    ColorPalette.C1TransparentBlack[pixel]
                }
            }
        } else {
            { pixel: Int ->
                val red = (pixel and decodeBitMask.first) shr bitShifts.first
                val green = (pixel and decodeBitMask.second) shr bitShifts.second
                val blue = (pixel and decodeBitMask.third) shl bitShifts.third
                RGBA(red, green, blue, 255)
            }
        }
    }

    fun toRgbWithTables(keepBlack: Boolean): ColorPalette {
        val black = if (keepBlack) {
            RGBA(0, 0, 0, 255)
        } else {
            RGBA(0, 0, 0, 0)
        }
        return toRgbWithTables(black)
    }

    private val rgbTableWithTransparentBlack: ColorPalette by lazy {
        makeTable(ColorPalette.TRANSPARENT_BLACK)
    }

    private val rgbTableWithOpaqueBlack: ColorPalette by lazy {
        makeTable(ColorPalette.OPAQUE_BLACK)
    }

    fun toRgbWithTables(black: RGBA): ColorPalette {
        return defaultIfPureBlackValue(black) ?: makeTable(black)
    }

    private fun makeTable(black: RGBA): ColorPalette {
        val maxColorInclusive = if (marker == -1) 255 else 65535//(if (this == X_565) 65535 else 32677)
        val table: List<RGBA> = listOf(black) + (1..maxColorInclusive).map { color ->
            toRgb(color)
        }
        return ColorPalette(this, table.toTypedArray(), false)
    }

    private fun defaultIfPureBlackValue(black: RGBA): ColorPalette? {
        if (black.r == 0 && black.g == 0 && black.b == 0) {
            if (black.a == 0) {
                return rgbTableWithTransparentBlack
            } else if (black.a == 255) {
                return rgbTableWithOpaqueBlack
            }
        }
        return null
    }

    internal fun toRGBColorList(black: RGBA): List<RGBA> {
        val maxColorInclusive = 65535//(if (this == X_565) 65535 else 32677)
        return (0..maxColorInclusive).map { color ->
            if (color == 0) {
                black
            } else {
                toRgb(color)
            }
        }
    }

    fun rgbCached(): (pixel: Int) -> RGBA {
        return { pixel ->
            table[pixel] ?: toRgb(pixel).apply {
                table[pixel] = this
            }
        }
    }

    @Suppress("ConstPropertyName")
    companion object {

        const val x555: String = "555"
        const val x565: String = "565"
        val ENCODING_DEFAULT = X_565

        fun fromString(value: String): ColorEncoding {
            return when {
                value == x555 || value.endsWith("555") -> X_555
                value == x565 || value.endsWith("565") -> X_565
                else -> throw InvalidSpriteEncodingString(value)

            }
        }
    }

}


internal class InvalidSpriteEncodingString(
    @Suppress("MemberVisibilityCanBePrivate")
    val code: String,
    message: String = "Invalid sprite encoding value '$code'. " +
            "Expected value of '${ColorEncoding.x555}' or '${ColorEncoding.x565}'",
    throwable: Throwable? = null,
) : Exception(message, throwable)