package com.creaturesforge.application.state

import com.bedalton.common.exceptions.rethrowCancellationException
import com.bedalton.common.util.formatted
import com.bedalton.log.Log
import com.bedalton.state.simple.Dispatch
import com.bedalton.state.simple.Middleware
import com.bedalton.state.simple.Next
import kotlinx.coroutines.GlobalScope
import kotlinx.coroutines.launch
import kotlin.contracts.InvocationKind
import kotlin.contracts.contract


internal inline fun alwaysNextMiddleware(crossinline work: suspend (state: ForgeState, action: FAction, dispatch: Dispatch<FAction>) -> Unit): Middleware<ForgeState, FAction> {
    return { state: ForgeState, action: FAction, dispatch: Dispatch<FAction>, next: Next<ForgeState, FAction> ->
        GlobalScope.launch {
            work(state, action, dispatch)
        }
        next(state, action, dispatch)
    }
}

internal inline fun launchAndNext(actionName: String, next: () -> FAction, crossinline work: suspend () -> Unit): FAction {

    contract {
        callsInPlace(next, InvocationKind.EXACTLY_ONCE)
        callsInPlace(work, InvocationKind.EXACTLY_ONCE)
    }
    try {
        GlobalScope.launch {
            work()
        }
    } catch (e: Exception) {
        e.rethrowCancellationException()
        Log.e("Failed to $actionName; ${e.formatted()}")
    }
    return next()
}

internal fun launchNoOp(action: String, work: suspend () -> Unit): NoOp {
    try {
        GlobalScope.launch {
            work()
        }
    } catch (e: Exception) {
        e.rethrowCancellationException()
        Log.e("Failed to $action; ${e.formatted()}")
    }
    return NoOp
}
