package com.bedalton.common.exceptions

actual fun asThrowable(e: dynamic): Throwable  {
    if (e is Throwable) {
        return e.unsafeCast<Throwable>()
    }
    if (e is String) {
        return Exception(e.unsafeCast<String>())
    }
    val error = e.error ?: e
    if (error.message is String) {
        return Exception(error.message as String)
    }
    return Exception(JSON.stringify(error))
}
