package com.bedalton.creatures.caos.libs

import kotlinx.serialization.Serializable
import kotlin.js.JsExport
import kotlin.js.JsName

@JsExport
@JsName("Commands")
@Serializable
data class Commands(
    @JsName("commands")
    val commands:Array<VariantCaosCommand>,
    @JsName("rvalues")
    val rvalues:Array<VariantCaosCommand>,
    @JsName("lvalues")
    val lvalues:Array<VariantCaosCommand>
) {
    override fun equals(other: Any?): Boolean {
        if (this === other) return true
        if (other !is Commands) return false

        if (!commands.contentEquals(other.commands)) return false
        if (!rvalues.contentEquals(other.rvalues)) return false
        if (!lvalues.contentEquals(other.lvalues)) return false

        return true
    }

    override fun hashCode(): Int {
        var result = commands.contentHashCode()
        result = 31 * result + rvalues.contentHashCode()
        result = 31 * result + lvalues.contentHashCode()
        return result
    }
}