@file:Suppress("unused")

package com.bedalton.vfs

import com.bedalton.common.util.PathUtil
import com.bedalton.common.util.PathUtil.isAbsolute
import com.bedalton.common.util.toListOf
import com.bedalton.vfs.internal.isVirtualFileSystem

interface DirectoryWriter {
    suspend fun makeDirectory(path: String, recursive: Boolean): Boolean

    suspend fun deleteDirectory(path: String): Boolean

    suspend fun canDeleteDirectory(path: String): Boolean

    suspend fun canMakeDirectories(): Boolean

    suspend fun refresh(): Boolean {
        return true
    }
}

interface FileSystem : OutsideFileReader, OutsideFileWriter, DirectoryWriter {

    fun isVirtualFileSystem(): Boolean {
        return isVirtualFileSystem
    }

    suspend fun listAllFiles(
        path: String,
        recursive: Boolean = true,
        filter: ((path: String) -> Boolean)? = null
    ): List<String> {
        return listAllFilesDefaultPrivate(this, path.expandTildeIfNecessary(), recursive, filter)
    }

    suspend fun getChildrenNonRecursive(directory: String): List<String>?

    suspend fun findFirst(
        path: String,
        refresh: Boolean,
        recursive: Boolean = true,
        filter: (path: String) -> Boolean
    ): String? {
        return findFirstPrivate(this, path.expandTildeIfNecessary(), recursive, filter)
    }

    suspend fun moveFile(fromFile: String, toFile: String, overwrite: Boolean): Int

    @Deprecated(
        "Root directory scopes are no longer checked",
        replaceWith = ReplaceWith("true")
    )
    suspend fun accept(path: String): Boolean {
        return true
    }
}

suspend fun FileSystem.getChildren(directory: String, recursive: Boolean): List<String>? {
    val children = getChildrenNonRecursive(directory.expandTildeIfNecessary())?.map { child ->
        if (!isAbsolute(child) && isVirtualPathInVirtualFS(child)) {
            PathUtil.combine(directory, child)
        } else {
            child
        }
    } ?: return null
    if (!recursive) {
        return children
    }
    return children.flatMap { child ->
        if (isDirectory(child)) {
            getChildren(child, true).orEmpty() + child
        } else {
            child.toListOf()
        }
    }
}