@file:Suppress("unused")

package com.bedalton.creatures.agents.pray.compiler.data

import com.bedalton.common.structs.DataCache
import com.bedalton.creatures.agents.pray.compiler.internal.writeBlockBytes
import com.bedalton.creatures.agents.pray.compiler.internal.writeBlockHeader
import com.bedalton.creatures.agents.util.RelativeFileSystem
import com.bedalton.creatures.sprite.compilers.S16Compiler
import com.bedalton.creatures.sprite.parsers.SpriteParser
import com.bedalton.io.bytes.ByteStreamWriter
import com.bedalton.io.bytes.MemoryByteStreamReader
import korlibs.image.bitmap.Bitmap32
import korlibs.image.format.PNG
import kotlinx.coroutines.CoroutineScope


class CompilerPhotBlock(
    startLine: Int,
    blockTag: TextValue,
    blockName: TextValue,
    private val bytes: () -> ByteArray
) : CompilerPrayBlock(startLine, blockTag, blockName) {

    private val mFile by lazy {
        DataCache {
            SpriteParser.parse("PHOT.s16", MemoryByteStreamReader(bytes()), true)[0]
        }
    }

    private suspend fun image(): Bitmap32 {
        return mFile.getData()!!
    }

    suspend fun toBMP32(): Bitmap32 {
        return image()
    }

    suspend fun toPNG(): ByteArray {
        return PNG.encode(image())
    }

    override suspend fun write(coroutineScope: CoroutineScope, fs: RelativeFileSystem, writer: ByteStreamWriter, compression: Int) {
        writeBlockHeader(writer, this)
        writeBlockBytes(
            writer,
            S16Compiler.compileSpriteFromLoadedImages(listOf(image()), keepBlack = true),
            compression
        )
    }

    override fun toCommonData(): com.bedalton.creatures.agents.pray.data.PhotBlock {
        return com.bedalton.creatures.agents.pray.data.PhotBlock(
            blockTag = blockTag.text,
            blockName = blockName.text,
            bytes = bytes
        )
    }
}

