package com.creaturesforge.application.state

import com.bedalton.common.util.PathUtil
import com.bedalton.common.util.formatted
import com.bedalton.log.Log
import com.bedalton.state.simple.Dispatch
import com.bedalton.state.simple.Next
import com.creaturesforge.application.ui.ConfirmCompileModal
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.GlobalScope
import kotlinx.coroutines.Job
import kotlinx.coroutines.launch

internal fun preCompileMiddleware(
    state: ForgeState,
    action: FAction,
    dispatch: Dispatch<FAction>,
    next: Next<ForgeState, FAction>
): FAction {
    return when (action) {
        is RequestCompileWithVerificationAction -> {
            val coroutineScope = CoroutineScope(Job())
            coroutineScope.launch {
                try {
                    runVerifyCompile(state)
                } catch (e: Exception) {
                    Log.e("Failed to runVerifyCompile(); ${e.formatted(true)}")
                }
            }
            NoOp
        }

        is RequestCompileAction -> {
            val directory = PathUtil.getWithoutLastPathComponent(action.outputFile)
            if (directory != null) {
                GlobalScope.launch {
                    ForgeConfig.setLastAgentsSaveDirectory(state.projectFolder, directory)
                }
            }
            next(state, action, dispatch)
        }

        else -> {
            ConfirmCompileModal.close()
            next(state, action, dispatch)
        }
    }
}


private suspend fun runVerifyCompile(state: ForgeState) {
    ConfirmCompileModal.show(state)
}