@file:Suppress("unused")

package com.bedalton.common.util

internal fun Char.isPrintable(): Boolean = this in '\u0020'..'\u007e' || this in '\u00a1'..'\u00ff'

fun String.escape(): String {
	val out = StringBuilder()
	for (element in this) {
		when (element) {
			'\\' -> out.append("\\\\")
			'"' -> out.append("\\\"")
			'\n' -> out.append("\\n")
			'\r' -> out.append("\\r")
			'\t' -> out.append("\\t")
			in '\u0000'..'\u001f' -> {
				out.append("\\x")
				out.append(Hex.encodeCharLower(element.code.extract(4, 4)))
				out.append(Hex.encodeCharLower(element.code.extract(0, 4)))
			}

			else -> out.append(element)
		}
	}
	return out.toString()
}

fun String.unicodeEscape(): String {
	val out = StringBuilder()
	for (element in this) {
		when (element) {
			'\\' -> out.append("\\\\")
			'"' -> out.append("\\\"")
			'\n' -> out.append("\\n")
			'\r' -> out.append("\\r")
			'\t' -> out.append("\\t")
			else -> if (element.isPrintable()) {
				out.append(element)
			} else {
				out.append("\\u")
				out.append(Hex.encodeCharLower(element.code.extract(12, 4)))
				out.append(Hex.encodeCharLower(element.code.extract(8, 4)))
				out.append(Hex.encodeCharLower(element.code.extract(4, 4)))
				out.append(Hex.encodeCharLower(element.code.extract(0, 4)))
			}
		}
	}
	return out.toString()
}

fun String.unescape(): String {
	val out = StringBuilder()
	var n = 0
	while (n < this.length) {
		when (val c = this[n++]) {
			'\\' -> {
				when (val c2 = this[n++]) {
					'\\' -> out.append('\\')
					'"' -> out.append('\"')
					'n' -> out.append('\n')
					'r' -> out.append('\r')
					't' -> out.append('\t')
					'u' -> {
						val chars = this.substring(n, n + 4)
						n += 4
						out.append(chars.toInt(16).toChar())
					}
					else -> {
						out.append("\\$c2")
					}
				}
			}
			else -> out.append(c)
		}
	}
	return out.toString()
}

fun String?.unicodeQuote(): String = if (this != null) "\"${this.unicodeEscape()}\"" else "null"
fun String?.quote(): String = if (this != null) "\"${this.escape()}\"" else "null"

fun String.isQuoted(): Boolean = this.startsWith('"') && this.endsWith('"')
fun String.unquote(): String = if (isQuoted()) this.substring(1, this.length - 1).unescape() else this

val String?.quoted: String get() = this.quote()
val String.unquoted: String get() = this.unquote()



internal fun Int.mask(): Int = (1 shl this) - 1
internal fun Int.extract(offset: Int, count: Int): Int = (this ushr offset) and count.mask()