@file:Suppress("unused")

package com.creaturesforge.application.ui.html

import org.w3c.dom.Element


internal fun Element.string(attribute: String, defaultOnce: String?): StringAttributeOf {
    return StringAttributeOf(attribute, this, defaultOnce)
}

internal fun Element.dataString(name: String, defaultOnce: String? = null): StringAttributeOf {
    return StringAttributeOf("data-$name", this, defaultOnce)
}

internal fun Element.boolean(attribute: String, defaultOnce: Boolean? = null): BooleanAttributeOf {
    return BooleanAttributeOf(attribute, this, defaultOnce)
}

internal fun Element.dataBoolean(attribute: String, defaultOnce: Boolean? = null): BooleanAttributeOf {
    return BooleanAttributeOf("data-$attribute", this, defaultOnce)
}

internal fun Element.int(attribute: String, defaultOnce: Int? = null): IntAttributeOf {
    return IntAttributeOf(attribute, this, defaultOnce)
}

internal fun Element.dataInt(attribute: String, defaultOnce: Int? = null): IntAttributeOf {
    return IntAttributeOf("data-$attribute", this, defaultOnce)
}


