package com.creaturesforge.application.state


internal fun setAttFiles(state: ForgeState, action: SetAttFilesAction): ForgeState {
    var out = state.copy(
        attFiles = action.files
    )
    if (out.attSlot != null) {
        val available = out.getAvailableAttSlots()
        if (out.attSlot !in available) {
            out  = out.copy(
                attSlot = null
            )
        }
    }

    if (out.attRoot == out.projectFolder) {
        out = out.copy(attRoot = null)
    }

    return out
}