package com.creaturesforge.application.util

internal fun <K, V> MutableMap<K,MutableList<V>>.add(key: K, value: V) {
    if (contains(key)) {
        get(key)!!.add(value)
    } else {
        put(key, mutableListOf(value))
    }
}


internal fun <T> Collection<T>.asCopyReversed(): List<T> {
    val out =  ArrayList<T>(this)
    out.asReversed()
    return out
}

internal inline fun <reified T> Array<T>.asCopyReversed(): Array<T> {
    val lastIndex = lastIndex
    return Array(this.size) { i -> this[lastIndex - i] }
}