private const val HIDE_CLASSNAME = "hide-logger"

private class LoggerBubbleElement(
    private val logBubble: HTMLElement,
) {

    var timeoutHandle = -1
    var lastMessageType: String? = null

    private var hidden = logBubble.hidden || logBubble.classList.contains(HIDE_CLASSNAME)

    private var mDisabled = logBubble.hidden

    var disabled: Boolean
        get() = mDisabled
        set(value) {
            mDisabled = value
            if (disabled) {
                logBubble.hidden = true
            } else if (logBubble.hidden) {
                logBubble.hidden = false
            }
        }


    init {
        // Hide regardless as it is not meant to be seen unless logged to
        logBubble.classList.add(HIDE_CLASSNAME)
        logBubble.hidden = true
        hidden = true

        // Hide Logging bubble on click
        logBubble.addEventListener("click", this::onClick)
    }


    @Suppress("UNUSED_PARAMETER")
    private fun onClick(e: Event) {
        if (hidden) {
            return
        }
        logBubble.classList.add(HIDE_CLASSNAME)
        hidden = true
    }

    fun log(status: String, message: String, color: LoggerColor?) {
        if (disabled) {
            return
        }
        val (namespace, messageText) = Log.namespaceLogComponents(message)
        log(status, namespace, messageText, color)
    }

    fun log(status: String, namespace: String?, message: String, color: LoggerColor?) {
        if (disabled) {
            return
        }
        if (namespace == LOG_CONSOLE) {
            return
        }

        var messageText = message

        if (namespace == LOG_PROGRESS) {
            messageText = getProgressStatement(
                messageWithoutNamespace = messageText
            )
        }
        if (namespace == LOG_PROGRESS || namespace == LOG_STATUS || status.lowercase() == "error") {
            applyColor(color)
            setMessageType(status)
            logBubble.innerHTML = messageText
            if (hidden) {
                logBubble.hidden = false
                logBubble.classList.remove(HIDE_CLASSNAME)
                hidden = false
            }
            setHideLoggingBubbleTimeout(if (namespace == LOG_STATUS) SHOW_FOR * 8 else SHOW_FOR)
        }
    }

    fun setMessageType(status: String?) {
        logBubble.classList.remove("log-info", "log-error", "log-warning", "log-debug")
        if (lastMessageType != null && logBubble.classList.contains("log-$lastMessageType")) {
            logBubble.classList.remove("log-$lastMessageType")
        }
        lastMessageType = status
        if (status != null) {
            logBubble.classList.add("log-${status.lowercase()}")
        }
    }

    private fun hideLoggingBubbleActual() {
        if (hidden) {
            return
        }
        logBubble.classList.add(HIDE_CLASSNAME)
        hidden = true
    }


    private fun setHideLoggingBubbleTimeout(timeout: Int) {
        window.clearTimeout(timeoutHandle)
        timeoutHandle = window.setTimeout(this::hideLoggingBubbleActual, timeout)
    }

    fun applyColor(color: LoggerColor?) {
        logBubble.classList.remove(
            ("log-color-" + LoggerColor.BLACK.className).lowercase(),
            ("log-color-" + LoggerColor.BLUE.className).lowercase(),
            ("log-color-" + LoggerColor.CYAN.className).lowercase(),
            ("log-color-" + LoggerColor.GREEN.className).lowercase(),
            ("log-color-" + LoggerColor.MAGENTA.className).lowercase(),
            ("log-color-" + LoggerColor.RED.className).lowercase(),
            ("log-color-" + LoggerColor.WHITE.className).lowercase(),
            ("log-color-" + LoggerColor.YELLOW.className).lowercase(),
        )
        if (color != null) {
            logBubble.classList.add(("log-color-" + color.className).lowercase())
        }
    }

    companion object {
        private const val SHOW_FOR = 1000
        val inlineRegexForIndex = "^inlining\\s+file\\s+(\\d+)\\s*of\\s*(\\d+).*$".toRegex(RegexOption.IGNORE_CASE)
        //val inlineRegexForAllParts = "^inlining\\s*file\\s*(\\d+)\\s*of\\s*(\\d+)\\s*:?\\s*(.+?)\\s+as\\s+(.*?)$".toRegex(RegexOption.IGNORE_CASE)
//val inlineRegexRaw = "^([^:]+):(.*?) as (.*?)$".toRegex(RegexOption.IGNORE_CASE)


        private fun getProgressStatement(messageWithoutNamespace: String): String {
            val temp = inlineRegexForIndex.matchEntire(messageWithoutNamespace)
                ?.groupValues
                ?.nullIfEmpty()
                ?: return messageWithoutNamespace
            val index = temp[1].toInt()
            val count = temp[2].toInt()
            val padding = count.toString().length
            val percent = floor((index * 100.0) / count)
                .toInt()
                .toString()
                .padStart(3, ' ')
            val indexString = index.toString().padStart(padding, ' ')

            return "Inlining $percent%; $indexString of $count"
        }

    }
}


private val loggingBubbles: List<LoggerBubbleElement> by lazy {
    (document.querySelectorAll(".logger-bubble"))
        .toList<HTMLElement>()
        .map { logger ->
            LoggerBubbleElement(logger)
        }
}


val progressLogger by lazy {
    LoggerBuilder().apply {

        fun log(status: String, message: String, color: LoggerColor?) {
            loggingBubbles.forEach {
                it.log(status, message, color)
            }

            val (namespace, text) = Log.namespaceLogComponents(message)
            LoggerPanel.logToLoggerPanels(
                namespace = namespace,
                type = status,
                message = text
            )
        }

        Log.setEnableNamespaceLoggingInMain(false)

        Log.addNamespaceLoggerListener { namespace, messageWithoutNamespace, color ->

            if (namespace == LOG_PROGRESS) {
                val progress = getProgressPercentFromProgressMessage(messageWithoutNamespace)
                dispatchProgress(progress)
            }

            loggingBubbles.forEach {
                console.log("NamespaceLogInBubble: %s -> \"%s\"", namespace, messageWithoutNamespace)
                it.log("info", namespace, messageWithoutNamespace, color)
            }

            LoggerPanel.logToLoggerPanels(
                namespace = namespace,
                type = "info",
                message = messageWithoutNamespace
            )
        }

        this.withLog { _, message, color ->
            log("info", message, color)
        }
        this.error { message, color ->
            log("error", message, color ?: LoggerColor.RED)
            console.error(Log.namespaceLogComponents(message).second)

        }
        this.warning { message, color ->
            log("warning", message, color)
            console.warn(Log.namespaceLogComponents(message).second)
        }

        this.info { _, message, color ->
            log("info", message, color)
            console.info(Log.namespaceLogComponents(message).second)
        }
    }.build()
}

var lastProgress = -1

private val dispatchProgress: (progress: Double?) -> Unit by lazy {

    var dispatch: Dispatch<FAction>? = null

    var unsubscribe: Unsubscribe? = null

    unsubscribe = ForgeStore.subscribe { _, dispatchIn ->
        dispatch = dispatchIn
        unsubscribe?.invoke()
    }

    return@lazy progress@{ progress ->
        dispatch?.invoke(CompileEggProgress(progress))
    }
}


private fun getProgressPercentFromProgressMessage(messageWithoutNamespace: String): Double? {
    val temp = inlineRegexForIndex.matchEntire(messageWithoutNamespace)
        ?.groupValues
        ?.nullIfEmpty()
        ?: return null
    val index = temp[1].toInt()
    val count = temp[2].toInt()
    return floor((index * 100.0) / count)
}