package com.bedalton.vfs

import com.bedalton.common.coroutines.BackgroundDispatcher
import com.bedalton.common.coroutines.mapAsync
import com.bedalton.common.exceptions.rethrowCancellationException
import com.bedalton.common.util.formatted
import com.bedalton.io.bytes.suspendAsPromise
import com.bedalton.log.LOG_DEBUG
import com.bedalton.log.Log
import com.bedalton.log.eIf
import kotlinx.coroutines.GlobalScope
import kotlinx.coroutines.asPromise
import kotlinx.coroutines.async
import kotlin.js.Promise

internal fun toFileList(files: Map<String, File>): Promise<Array<JsFile>> = GlobalScope.async {
    val out: List<JsFile> = files.entries.mapAsync (BackgroundDispatcher) { (name, file) ->
        val out = js("{}").unsafeCast<MutableJsFile>()
        out.name = name
        out.mimeType = file.mimeType
        out.bytes = suspendAsPromise {
            try {
                file.read()
            } catch (e: Throwable) {
                e.rethrowCancellationException()
                Log.eIf(LOG_DEBUG) {
                    "Failed to read bytes in toFilesList; ${e.formatted()}"
                }
                throw e
            }
        }
        out.disposeExtra = {
            file.dispose()
        }
        out
    }
    out.toTypedArray()
}.asPromise()



private external interface MutableJsFile: JsFile {
    override var name: String
    override var mimeType: String?
    override var bytes: Promise<ByteArray>
    override var disposeExtra: (() -> Unit)?
}

