package com.bedalton.creatures.sprite.util

import kotlinx.coroutines.async
import kotlinx.coroutines.awaitAll
import kotlinx.coroutines.coroutineScope
import kotlinx.coroutines.launch

suspend fun <A> Array<A>.forEachAsync(f: suspend (A) -> Unit): Unit = coroutineScope {
   forEach { launch { f(it) } }
}

suspend fun <A> Iterable<A>.forEachAsync(f: suspend (A) -> Unit): Unit = coroutineScope {
    forEach { launch { f(it) } }
}

