package com.bedalton.common.ast.collectors

import kotlin.js.JsExport

@JsExport
fun getRelativeCursorPosition(parseTreeItem: ParseTreeItem, line: Int, character: Int): CursorPosition {
    val range = parseTreeItem.textRange
    val start = range.start
    val end = range.end
    if (line == start.line) {
        if (end.line == start.line) {
            return when {
                character == start.character -> CursorPosition.START
                character == end.character -> CursorPosition.END
                character < start.character -> CursorPosition.BEFORE
                character > end.character -> CursorPosition.AFTER
                character in start.character .. end.character -> CursorPosition.INSIDE
                else -> CursorPosition.INSIDE
            }
        } else {
            return when {
                character == start.character -> CursorPosition.START
                character < start.character -> CursorPosition.BEFORE
                else -> CursorPosition.INSIDE
            }
        }
    } else if (line == end.line) {
        return when {
            character == end.character -> CursorPosition.END
            character > end.character -> CursorPosition.AFTER
            else -> CursorPosition.INSIDE
        }
    } else if (line < start.line) {
        return CursorPosition.BEFORE
    } else if (line > end.line) {
        return CursorPosition.AFTER
    } else {
        return CursorPosition.INSIDE
    }
}