import com.bedalton.log.iWith
import kotlinx.coroutines.CoroutineScope

/**
 * Loads and parses a Pray/CAOS2Pray file
 * Used only for simple file validation and not compilation
 */
internal suspend fun getInputDataForValidationOnly(
    coroutineScope: CoroutineScope,
    fs: RelativeFileSystem,
    fileName: String,
    text: String
): Caos2PrayResult {
    if (!fs.fileExists(fileName))
        throw PrayInputException("Failed to locate file at '${fs.path(fileName)}'")
    if (fs.isDirectory(fileName)) {
        throw PrayInputException("Input must be a file. Directory given")
    }
    if (PathUtil.getExtension(fileName) like "cos") {
        Caos2PrayParserUtil.parse(coroutineScope, fs, text).apply {
            return this
        }
    }
    return try {
        Log.iWith(LOG_PROGRESS) { "Parsing as input file" }
        PrayScriptParserUtil.parse(coroutineScope, fs, fileName, text).let { data ->
            val outputFileName = PathUtil.getFileNameWithoutExtension(fileName) + ".agents"
            Caos2PrayResult(
                outputFileName,
                data
            ).apply {
                Log.iIf(LOG_PROGRESS) { "Input file was PRAY" }
            }
        }
    } catch (e: Exception) {
        e.rethrowIfCancellationException()
        val extension = PathUtil.getFileNameWithoutExtension(fileName)?.lowercase()

        if (e is PrayParseValidationFailException) {
            Log.e { "PRAY Parse failed with error: ${e.message}; Errors:\n\t-${e.errors.joinToString("\n\t-") { it.message }}" }
//            if (e.errors.none { it is PrayValidationError.SyntaxError })
                throw e
        }
        Log.e { "Error parsing PRAY. Error: ${e.className}(${e.message})" }
        if (extension == "txt" || extension == "ps")
            throw e
        e.printStackTrace()
        Caos2PrayParserUtil.parse(coroutineScope, fs, text).apply {
            Log.iWith(LOG_PROGRESS) { "Input file was CAOS2Pray" }
        }
    } catch (e: Caos2PrayParseException) {
        Log.e { "Failed to ascertain Pray file type. Error: ${e.message}" }
        e.printStackTrace()
        throw e
    } catch (e: Exception) {
        e.rethrowIfCancellationException()
        e.printStackTrace()
        throw e
    }
}

