package com.bedalton.creatures.breed.render.internal

import com.bedalton.common.util.nullIfEmpty
import com.bedalton.creatures.breed.render.renderer.MissingRenderValueException
import com.bedalton.creatures.common.structs.BreedKey
import com.bedalton.creatures.common.structs.BreedPartKey


internal fun BreedKey.assertConcrete(info: String? = null) {
    val missing = mutableListOf<String>()

    if (genus == null) {
        missing.add("genus")
    }
    if (breed == null) {
        missing.add("breed")
    }
    if (ageGroup == null) {
        missing.add("age")
    }
    if (gender == null) {
        missing.add("gender")
    }
    if (missing.isNotEmpty()) {
        val missingAsString = missing.joinToString()
        val infoString = info.nullIfEmpty()?.let { "\n\t- $it" }
        throw MissingRenderValueException(
            message = "Breed key is missing concrete values for [$missingAsString];$infoString\n\t- Key: $this",
            property = "breed key",
            missing = missingAsString
        )
    }
}

fun BreedKey.isConcrete(): Boolean {
    if (genus == null) {
        return false
    }
    if (breed == null) {
        return false
    }
    if (ageGroup == null) {
        return false
    }
    if (gender == null) {
        return false
    }
    return true
}

internal fun BreedPartKey.assertConcrete(info: String? = null) {

    val missing = mutableListOf<String>()

    if (genus == null) {
        missing.add("genus")
    }
    if (breed == null) {
        missing.add("breed")
    }
    if (ageGroup == null) {
        missing.add("age")
    }
    if (gender == null) {
        missing.add("gender")
    }
    if (part == null) {
        missing.add("part")
    }
    if (missing.isEmpty()) {
        return
    }
    val missingAsString = missing.joinToString()
    val infoString = info.nullIfEmpty()?.let { "\n\t- $it" }
    throw MissingRenderValueException(
        message = "Breed part key is missing concrete values for [$missingAsString];$infoString\n\t- Key: $this",
        property = "breed part key",
        missing = missingAsString
    )
}