package com.creaturesforge.application.state

internal enum class EggMode {
    SINGLE,
    MULTI;

    companion object {

        val DEFAULT = SINGLE

        fun fromString(eggMode: String?): EggMode? {
            return when (eggMode?.lowercase()) {
                "simple" -> SINGLE
                "single" -> SINGLE
                "advanced" -> MULTI
                "multi" -> MULTI
                else -> null
            }
        }
    }
}

internal fun EggMode.invert(): EggMode {
    return when (this) {
        EggMode.SINGLE -> EggMode.MULTI
        EggMode.MULTI -> EggMode.SINGLE
    }
}

internal operator fun EggMode.plus(other: EggMode): EggMode {
    return if (this == EggMode.MULTI || other == EggMode.MULTI) {
        EggMode.MULTI
    } else {
        EggMode.SINGLE
    }
}