package com.creaturesforge.application.compile

import com.bedalton.common.util.PathUtil
import com.bedalton.common.util.className
import com.bedalton.common.util.ensureNotEndsWith
import com.bedalton.common.util.nullIfEmpty
import com.bedalton.creatures.agents.pray.compiler.data.CompilerPrayData
import com.bedalton.creatures.agents.pray.compiler.data.PrayDataBuilder
import com.bedalton.log.*
import com.bedalton.vfs.BinaryFile
import com.bedalton.vfs.FileSystemWithInputFiles
import com.creaturesforge.application.state.*
import com.creaturesforge.application.util.LOG_STATUS
import com.bedalton.common.exceptions.rethrowCancellationException
import com.creaturesforge.application.util.withExtension


/**
 * Make a PrayData object to be compiled into a `.agents` file
 */
internal suspend fun makePrayFile(state: CompileData): CompilerPrayData {
    val fs = vfs

    val sprites = state.spriteFiles
    Log.iIf(LOG_VERBOSE) { "Adding ${sprites.size} sprites" }

    val atts = state.attFiles
    if (atts.isEmpty()) {
        Log.wWith(LOG_STATUS) { "No ATTs" }
    } else {
        Log.iWith(LOG_VERBOSE) { "Adding ${atts.size} ATTs" }
    }


    // Holder for support files that are not Sprite or Att
    val additionalFiles = mutableListOf<String>()
    Log.iIf(LOG_VERBOSE) { "Adding ${additionalFiles.size} additional files" }

    // Male Glyph
    val maleGlyph = state.maleGlyph
        ?: throw Exception("Cannot compile without male glyph")
    val maleGlyphFilename = addGlyphFile(additionalFiles, "male", maleGlyph)

    // Female Glyphs
    val femaleGlyph = state.femaleGlyph
        ?: throw Exception("Cannot compile without female glyph")
    val femaleGlyphFilename = addGlyphFile(additionalFiles, "female", femaleGlyph)

    // Create Pray Data block
    var prayBuilder = PrayDataBuilder()
        .withLanguage("en-GB")

    val eggs = EggFileNameUtil.fillInMissingGenomeFileNames(state.eggs)

    for ((i, egg) in eggs.withIndex()) {

        if (StateValidator.isEmpty(egg)) {
            continue
        }

        val eggName = egg.eggName
            ?.trim()
            ?.nullIfEmpty()
            ?.trimStart(':')
            ?.trim()
            ?: throw Exception("Cannot compile Egg[$i] without name")

        // Add genome files to files and vfs
        val genomeFile = addGenomeFile(fs, additionalFiles, egg.baseGenomeFile, state.genomeGenus, state.breedSlot)
            ?: throw Exception("Failed to convert and compile base genome")

        val motherGenome = addGenomeFile(fs, additionalFiles, egg.motherGenomeFile, state.genomeGenus, state.breedSlot)

        val fatherGenome = addGenomeFile(fs, additionalFiles, egg.fatherGenomeFile, state.genomeGenus, state.breedSlot)

        var eggBlock = prayBuilder
            .tagBlock("EGGS", eggName)
            .withIntTag("Agent Type", 0)
            .withStringTag("Egg Animation String", "0")
            .withStringTag("Egg Glyph File", maleGlyphFilename)
            .withStringTag("Egg Glyph File 2", femaleGlyphFilename)
            .withStringTag("Egg Gallery male", maleGlyphFilename.ensureNotEndsWith(".c16"))
            .withStringTag("Egg Gallery female", femaleGlyphFilename.ensureNotEndsWith(".c16"))
            .withStringTag("Genetics File", PathUtil.getFileNameWithoutExtension(genomeFile) ?: genomeFile)
            .withIntTag("Agent Type", 0)
            .withAttachments(sprites)
            .withAttachments(atts)
            .withAttachments(additionalFiles)

        // Add mother genome to block if any
        if (motherGenome != null) {
            eggBlock = eggBlock.withStringTag("Mother Genetic File", motherGenome)
        }
        // Add mother genome to block if any
        if (fatherGenome != null) {
            eggBlock = eggBlock.withStringTag("Father Genetic File", fatherGenome)
        }
        prayBuilder = eggBlock.build()
    }
    // Return build Pray data object
    return prayBuilder
        .build()
}

private suspend fun addGlyphFile(
    files: MutableList<String>,
    maleFemale: String,
    glyph: Glyph
): String {
    val filename = (PathUtil.getFileNameWithoutExtension(glyph.filename) ?: glyph.filename)
        .trim(' ', ':')
        .replace(":", "")
        .withExtension("c16")
    val bytes = glyph.getGlyphData()
        ?: throw Exception("Glyph data could not be compiled for $maleFemale glyph")
    val file = BinaryFile(
        filename,
        bytes
    )
    addFile(filename, file)
    files.add(filename)
    return filename
}

private suspend fun addGenomeFile(
    fs: FileSystemWithInputFiles,
    files: MutableList<String>,
    genomeFile: GenomeFile?,
    genus: Int,
    slot: BreedSlot,
): String? {
    if (genomeFile == null) {
        return null
    }
    if (genomeFile.filename.isBlank()) {
        Log.e { "Missing genome output filename" }
        return null
    }
    if (genomeFile.filepath.isBlank()) {
        Log.e { "Missing path to original genome file" }
        return null
    }
    val genomeBytes = try {
        genomeFile.getGenomeForSlot(fs, genus, slot)
    } catch (e: Exception) {
        e.rethrowCancellationException()
        Log.e {
            "Failed to get genome bytes: ${e.className}:${e.message}\n${e.stackTraceToString()}"
        }
        return null
    }
    val genomeName = if (genomeFile.filename.endsWith(".gen")) {
        PathUtil.getFileNameWithoutExtension(genomeFile.filename)!!
    } else {
        genomeFile.filename
    }.trim(' ', ':', ':')
    val genomeFileName = "$genomeName.gen"
    addFile(genomeFileName, genomeBytes)
    files.add(genomeFileName)

    // GNO
    val gnoBytes = genomeFile.gnoFile(fs)
    val gnoFileName = if (gnoBytes != null) "$genomeName.gno" else null
    if (gnoBytes != null) {
        addFile(gnoFileName!!, gnoBytes)
        files.add(gnoFileName)
    }

    return genomeFileName
}