package com.bedalton.common.ast.collectors

import com.bedalton.common.ast.structs.Range


/**
 * Checks if a given cursor is inside a matching pair of quotes.
 * Used to prevent completions in strings
 */
fun inQuotes(closestItem: ParseTreeItem, line: Int, character: Int): Boolean {
    return inQuotes(closestItem.text, closestItem.textRange, line, character)
}

internal fun inQuotes(text: String, textRange: Range, line: Int, character: Int): Boolean {
    if (!text.startsWith('"')) {
        return false
    }
    val start = textRange.start
    val end = textRange.end

    if (start.line == line) {
        return if (end.line != line) {
            true
        } else {
            val endQuote = if (text.endsWith('"')) 1 else 0
            (start.character < character && character <= end.character - endQuote)
        }
    } else if (start.line < line) {
        return if (end.line > line) {
            true
        } else {
            val endQuote = if (text.endsWith('"')) 1 else 0
            (character < end.character - endQuote)
        }
    } else if (start.line > line) {
        return false
    } else {
        return false
    }
}