package com.bedalton.creatures.caos.collectors.internal

import com.bedalton.creatures.caos.collectors.ParseCancelledException


/**
 * Creates a callback for stopping parsing if keepGoing() returns false
 * This is used to abort parsing if the caller no longer needs the result
 */
internal fun createCheckCancelled(
    checkDelay: Int? = null,
    keepGoing: (() -> Boolean)? = null,
): () -> Unit {
    if (keepGoing == null) {
        return { }
    }
    var cancelled = false
    var exception: Exception? = null
    var checkKicks = 0
    val checkDelayActual = checkDelay ?: 5
    return check@{
        if (checkKicks++ < checkDelayActual) {
            return@check
        }
        checkKicks = 0
        cancelled = cancelled || !keepGoing()
        if (cancelled) {
            throw (exception ?: ParseCancelledException().apply {
                exception = this
            })
        }
    }
}