package com.bedalton.creatures.agents.pray.compiler.caos2pray

import com.bedalton.creatures.agents.pray.compiler.NEWLINE_REGEX
import com.bedalton.common.util.stripSurroundingQuotes
import com.bedalton.common.coroutines.rethrowIfCancellationException
import com.bedalton.log.Log


private val whitespaceRegex = "\\s+".toRegex()

private val splitterRegex = "=|-?->".toRegex()

internal expect fun getTagShortcutFileData():String

/**
 * Helper for retrieving CAOS2Pray short tags.
 * Short tags such as "desc" for "Agent Description" or "anim" for "Agent Animation String"
 */
object Caos2PrayShortTags {

    /**
     * Parse short tags from the friendliness text file (provided by original CAOS2Pray compiler)
     *
     * @return
     */
    private fun parseShortTags(): Map<String, String> {

        // Read friendliness text file
        val friendlinessText = try {
            getTagShortcutFileData()
        } catch (e: Exception) {
            e.rethrowIfCancellationException()
            Log.e { "Friendliness.nice could not be loaded" }
            e.printStackTrace()
            return emptyMap()
        }

        // Split friendliness text file into lines
        val lines = try {
            friendlinessText.split(NEWLINE_REGEX)
        } catch (e: Exception) {
            e.rethrowIfCancellationException()
            Log.e { "Failed to split Friendliness.Nice with error: <${e.message}>" }
            e.printStackTrace()
            return emptyMap()
        }

        // Convert lines to friendliness tag map
        return lines
            .mapIndexedNotNull map@{ i, line ->
                try {
                    processLine(line)
                } catch (e: Error) {
                    Log.e { "Failed to process Friendliness.Nice line $i: <$line>; With Error: <${e.message}>" }
                    e.printStackTrace()
                    null
                } catch (e: Exception) {
                    e.rethrowIfCancellationException()
                    Log.e { "Failed to process Friendliness.Nice line $i: <$line>; With Exception: <${e.message}>" }
                    e.printStackTrace()
                    null
                }
            }
            .toMap()
    }

    /*
     * Cached short tag parse
     */
    val SHORT_TAGS:Map<String,String> by lazy {
        parseShortTags()
    }

    /**
     * Get full tag from short tag (i.e return "Agent Description" for "desc)
     *
     * @param key short tag
     * @return full official tag
     */
    operator fun get(key: String): String? = SHORT_TAGS[key]
}

/**
 * Break a line from friendliness.txt to a pair of (shortTag, fullTag)
 * @return Pair(short tag, full tag)
 */
private fun processLine(line:String) : Pair<String,String>? {
    // Return null if line is blank
    if (line.isBlank()) {
        return null
    }

    // Split line into components based on some possible delimiters
    val values = line.split(splitterRegex)

    // If line was split more than once, it is invalid
    if (values.size != 2) {
        throw FriendlinessParseException(
            line,
            "Invalid friendliness line formatting. Invalid number of capture groups in '$line'. Expected 2, found ${values.size}"
        )
    }

    // Cleanup short tag (friendly value)
    val friendlyValue = values[0].trim().lowercase().replace(whitespaceRegex, "").stripSurroundingQuotes().trim()

    // Cleanup official (actual value) value
    val actualValue = values[1].trim().stripSurroundingQuotes().trim()

    // Return tuple of Friendly to Actual
    return friendlyValue to actualValue
}

/**
 * Resolves short tag to an actual tag
 *
 * @param tag friendly (short) tag
 * @return actual official tag if found or tag parameter if not found
 */
internal fun resolveTag(tag:String) : String {

    val tagNormalize = tag
        .lowercase()
        .replace(whitespaceRegex, "")
        .stripSurroundingQuotes()

    return Caos2PrayShortTags[tagNormalize] ?: tag.stripSurroundingQuotes()
}

/**
 * Fallback string of original friendliness.txt
 */
internal val defaultShortTagText by lazy {
    """
        "anim" --> "Agent Animation String"
        "anim file" --> "Agent Animation File"
        "desc" --> "Agent Description"
        "anim start" --> "Agent Sprite First Image"
        "anim img" --> "Agent Sprite First Image"
        "anim image" --> "Agent Sprite First Image"
        "first image" --> "Agent Sprite First Image"
        "bioenergy" --> "Agent Bioenergy Value"
    """.trimIndent()
}