package com.creaturesforge.application.ui.controls

import com.creaturesforge.application.state.*
import org.w3c.dom.HTMLElement

internal class ProjectRootInput(element: HTMLElement): RootInput(element, "project") {

    override val openTitle: String = "Select GeneForge Project Root"

    override fun createSetterAction(path: String?): FAction {
        return SetProjectRootAction(path)
    }

    override fun getRootFromState(state: ForgeState): String? {
        return state.projectFolder
    }

    override suspend fun getLastRootFromConfig(projectRoot: String?): String? {
        return ForgeConfig.getLastProjectRoot()
    }

    override suspend fun onRootSet(projectRoot: String?, directory: String) {
        ForgeConfig.setLastProjectRoot(directory)
        resetVfs()
    }

}