package com.bedalton.creatures.caos.collectors.internal

import com.bedalton.common.ast.structs.PositionImpl
import com.bedalton.common.ast.structs.RangeWithIndexImpl
import com.bedalton.common.util.toListOf
import com.bedalton.creatures.caos.collectors.CaosParserItem
import org.antlr.v4.kotlinruntime.Token


internal fun whitespaceToTokens(it: Token): List<CaosParserItem.WhitespaceItem> {

    val newlineRegex = "\r?\n".toRegex()
    val whitespaces = it.text
        ?: return emptyList()
    val normalizedWhitespace = whitespaces.replace(newlineRegex, "\n")
    if (normalizedWhitespace.none { it == '\n' }) {
        val range = RangeWithIndexImpl.create(
            it,
            it,
            parserIndex = null
        )
        return CaosParserItem.Spaces(
            range,
            whitespaces
        ).toListOf()
    }
    if (normalizedWhitespace.all { it == '\n' }) {
        val range = RangeWithIndexImpl.create(
            it,
            it,
            parserIndex = null
        )
        return CaosParserItem.NewLine(
            range,
            whitespaces
        ).toListOf()
    }
    var start = it.startIndex
    var newline: Boolean? = null
    var startLine = it.line
    val string = StringBuilder()
    val out = mutableListOf<CaosParserItem.WhitespaceItem>()
    var startPositionInLine = it.charPositionInLine
    val endPoint = it.endPoint()
    var endPositionInLine = if (endPoint != null && it.line == it.endPoint()?.line) endPoint.column else  startPositionInLine
    val lastIndex = whitespaces.lastIndex
    for (i in whitespaces.indices) {
        val char = whitespaces[i]
        val charIsNewline = char == '\r' || char == '\n'
        if (newline == null) {
            newline = charIsNewline
        }
        if (charIsNewline != newline || i == lastIndex) {
            val whitespace = string.toString()
            val lines = whitespaces.replace("\r?\n".toRegex(), "\n").count()
            val range = RangeWithIndexImpl(
                start = PositionImpl(
                    startLine,
                    startPositionInLine
                ),
                end = PositionImpl(
                    startLine + lines,
                    endPositionInLine
                ),
                startIndex = start,
                endIndex = start + i,
            )
            startLine += lines
            val item = if (newline) {
                CaosParserItem.NewLine(
                    textRange = range,
                    value = whitespace
                )
            } else {
                CaosParserItem.Spaces(
                    textRange = range,
                    value = whitespace
                )
            }
            out.add(item)
            start = it.startIndex + i
            startPositionInLine = endPositionInLine
            string.clear()
        }
        string.append(char)
        if (char == '\n') {
            endPositionInLine = 0
        }
    }
    return out
}
