package com.creaturesforge.application.ui

import com.bedalton.common.util.isNotNullOrBlank
import com.creaturesforge.application.ui.html.getOrNull
import kotlinx.browser.document
import kotlinx.browser.window
import org.w3c.dom.HTMLElement
import org.w3c.dom.events.KeyboardEvent

private typealias LOG = (namespace: String?, type: String, message: String) -> Unit

internal class LoggerPanel private constructor(
    private val parent: HTMLElement,
    private val panel: HTMLElement = (parent.getOrNull("[data-role='log']") ?: parent),
    namespaces: List<String>,
    classes: String
) {
    private val allNamespaces = namespaces.any { it == "*" }
    private val namespacesLower = namespaces.map { it.lowercase() }

    private val classArray = classes.split(' ')
        .filter { it.isNotBlank() }
        .toTypedArray()

    init {
        init(parent)
        loggers.add(this::log)

        parent.querySelector(".close-log-button")?.addEventListener("click", {
            show(false)
        })
    }

    fun show(show: Boolean) {
        if (show) {
            show(parent)
        } else {
            hide(parent)
        }
    }

    fun log(namespace: String?, type: String, message: String) {
        if (!allNamespaces && (namespace == null || namespace.lowercase() !in namespacesLower)) {
            return
        }
        val logItem = createLogItem(
            type,
            message,
            classArray
        ).apply {
            if (namespace.isNotNullOrBlank()) {
                this.classList.add("log-namespace-$namespace")
            }
        }
        panel.appendChild(logItem)
    }



    @Suppress("MemberVisibilityCanBePrivate")
    companion object {

        private var currentPanel: HTMLElement? = null
        private var didInitKeyboardListener = false
        private val loggers = mutableListOf<LOG>()


        private val debugPanel: LoggerPanel by lazy {
            getLoggerPanelFromId(
                "debug-logger-panel",
                listOf("*"),
                true,
            )
        }

        private fun show(element: HTMLElement) {
            currentPanel?.apply {
                this.setAttribute("data-showing", "false")
                this.classList.add("hidden")
            }
            currentPanel = element
            element.setAttribute("data-showing", "true")
            element.classList.remove("hidden")
        }

        private fun hide(panel: HTMLElement?) {
            if (panel == null) {
                return
            }

            if (currentPanel == panel) {
                currentPanel = null
            }

            panel.setAttribute("data-showing", "false")
            panel.classList.add("hidden")
        }

        internal fun logToLoggerPanels(
            namespace: String?,
            type: String,
            message: String,
        ) {
            loggers.forEach { it(namespace, type, message) }
        }

        internal fun initLoggerPanels() {
            if (didInitKeyboardListener) {
                return
            }
            debugPanel.log(null,"info",  "initializing logger panel")
            ((document.getElementById("show-log-button") as HTMLElement)).apply {
                this.addEventListener("click", {
                    debugPanel.show(true)
                })
            }
            didInitKeyboardListener = true
            window.addEventListener("keyup", { e ->
                val event = e.unsafeCast<KeyboardEvent>()
                if (event.metaKey && event.key.lowercase() == "d") {
                    debugPanel.show(true)
                } else if (event.key.lowercase() == "escape") {
                    hide(currentPanel)
                }
                Unit
            }, true)
        }

        internal fun getLoggerPanelFromElement(
            panel: HTMLElement,
            namespaces: List<String>,
            classes: String = ""
        ): LoggerPanel {
            return LoggerPanel(
                panel,
                (panel.querySelector("[data-role='log']") ?: panel).unsafeCast<HTMLElement>(),
                namespaces,
                classes
            )
        }

        internal fun getLoggerPanelFromId(
            id: String,
            namespaces: List<String>,
            create: Boolean = false,
            classes: String = "",
            init: HTMLElement.() -> Unit = {}
        ): LoggerPanel {
            val panel = getLoggerPanelElement(
                id = id,
                create = create,
                init = init
            )
            return getLoggerPanelFromElement(panel, namespaces, classes)
        }

        private fun createLogItem(
            type: String,
            message: String,
            classes: Array<String>
        ): HTMLElement {
            val logItem = (document.createElement("p") as HTMLElement)
            logItem.classList.add("log-item", "log-${type.lowercase()}", *classes)
            logItem.innerText = message
            return logItem
        }


        private fun getLoggerPanelElement(
            id: String,
            create: Boolean,
            init: HTMLElement.() -> Unit
        ): HTMLElement {
            var panel = document.getElementById(id) as HTMLElement?
            if (panel == null && create) {
                panel = (document.createElement("article") as HTMLElement).apply {
                    this.classList.add("hidden")
                    this.classList.add("logger-panel")
                    this.id = id
                    this.setAttribute("data-role", "log")
                }
            } else if (panel == null) {
                throw Exception("Missing logger panel: #$id")
            }
            panel.init()
            return panel
        }

        private fun init(panel: HTMLElement) {
            val showing = !panel.classList.contains("hidden")
                    || panel.getAttribute("data-showing") == "true"
            panel.setAttribute("data-showing", showing.toString())
            if (showing && currentPanel == null) {
                panel.classList.remove("hidden")
                currentPanel = panel
            } else if (!showing) {
                panel.classList.add("hidden")
            }
        }
    }
}