@file:Suppress("unused")

package com.bedalton.creatures.agents.util

import com.bedalton.common.util.PathUtil
import com.bedalton.common.util.stripSurroundingQuotes
import com.bedalton.creatures.agents.cob.caos2cob.internal.Caos2CobImageUtil

enum class CobTagFormat(val formatDescriptor: String, val validate: (value:String) -> Boolean) {
    STRING("string", ::isString),
    NUMBER("number", ::isNumber),
    SINGLE_IMAGE("image or sprite file with array access like sprite[0].spr", ::isSingleImage),
    DATE("date in the format of 2011-12-03 or 2011-12-03T10:15:30", ::isDate),
    EMAIL("email", ::isEmail),
    URL("URL", ::isURL),
    FILE("file reference", ::isFile)
}

private fun isURL(value: String) = isString(value)

private fun isFile(value: String) = getFileNameWithArrayAccess(value.stripSurroundingQuotes()) != null

private fun isNumber(value: String): Boolean = POS_NEG_NUMBER_REGEX.matches(value)

private fun isString(value: String): Boolean = !POS_NEG_NUMBER_REGEX.matches(value)

private fun isEmail(value: String): Boolean {
    return emailRegex.matches(value.stripSurroundingQuotes())
}

private fun isSingleImage(value: String): Boolean {
    val fileName = getFileName(value.stripSurroundingQuotes())
        ?: return false

    val extension = PathUtil
        .getExtension(fileName)
        ?.lowercase()

    // Check is sprite extension is valid
    return extension in listOf("gif", "jpeg", "jpg", "png", "spr", "s16", "c16", "bmp")
}


private fun getFileName(path: String): String? {
    if (!path.contains('['))
        return path
    Caos2CobImageUtil.ARRAY_ACCESS_REGEX.matchEntire(path)?.groupValues?.let { groupValues ->
        return "${groupValues[1]}.${groupValues[2]}"
    }
    Caos2CobImageUtil.ARRAY_ACCESS_BEFORE_EXTENSION_REGEX.matchEntire(path)?.groupValues?.let { groupValues ->
        return "${groupValues[1]}.${groupValues[3]}"
    }
    return null
}

private val dateRegex = "\\d{4}-\\d{2}-\\d{2}(T\\d{1,2}:\\d{2}(:\\d{2}))?".toRegex()
private fun isDate(value: String): Boolean {
    return dateRegex.matches(value.trim())
}

val emailRegex = "[^@]+@[^.]+\\..+".toRegex()


private fun getFileNameWithArrayAccess(path: String): String? {
    if (path.isEmpty())
        return null
    if (!path.contains('['))
        return path
    Caos2CobImageUtil.ARRAY_ACCESS_REGEX.matchEntire(path)?.groupValues?.let { groupValues ->
        return "${groupValues[1]}.${groupValues[2]}"
    }
    Caos2CobImageUtil.ARRAY_ACCESS_BEFORE_EXTENSION_REGEX.matchEntire(path)?.groupValues?.let { groupValues ->
        return "${groupValues[1]}.${groupValues[3]}"
    }
    return null
}