@file:Suppress("unused")

package com.bedalton.creatures.breed.render.support.pose

import com.bedalton.creatures.breed.render.support.pose.PoseConstants.Facing.BACK
import com.bedalton.creatures.breed.render.support.pose.PoseConstants.Facing.FRONT
import com.bedalton.creatures.breed.render.support.pose.PoseConstants.Facing.VIEWER_LEFT
import com.bedalton.creatures.breed.render.support.pose.PoseConstants.Facing.VIEWER_RIGHT
import com.bedalton.creatures.breed.render.support.util.asChar
import com.bedalton.creatures.common.structs.GameVariant
import com.bedalton.creatures.common.structs.isC1e
import kotlinx.serialization.Serializable
import kotlin.js.JsExport
import kotlin.js.JsName
import kotlin.jvm.JvmStatic


/**
 * Body part tilt enum
 */
@Serializable
@JsExport
enum class Tilt(val int: Int?, val char: Char) {
    DOWN(PoseConstants.Tilt.DOWN, PoseConstants.Tilt.DOWN_CHAR),
    STRAIGHT(PoseConstants.Tilt.STRAIGHT, PoseConstants.Tilt.STRAIGHT_CHAR),
    UP(PoseConstants.Tilt.UP, PoseConstants.Tilt.UP_CHAR),
    FAR_UP(PoseConstants.Tilt.FAR_UP, PoseConstants.Tilt.FAR_UP_CHAR),
    NO_CHANGE(PoseConstants.Tilt.NO_CHANGE, PoseConstants.Tilt.NO_CHANGE_CHAR);

    internal val intOrDefault: Int get() = int ?: STRAIGHT.int!!

    internal fun intOrDefault(int: Int) = this.int ?: int


    /**
     * Gets the sprite for the body
     */
    fun getSpriteIndex(variant: GameVariant, bodyDirection: PoseFacing): Int {
        val bodyDirectionInt = bodyDirection.int
            ?: throw PoseException("Cannot get body sprite index without concrete direction facing. Direction: '${bodyDirection.char}'")
        return getSpriteIndex(variant, bodyDirectionInt, intOrDefault)
    }

    /**
     * Gets the sprite index for the body for its direction and tilt
     */
    private fun getSpriteIndex(variant: GameVariant, bodyDirection: Int, tilt: Int): Int {
        return if (variant.isC1e) {
            when (bodyDirection) {
                VIEWER_RIGHT -> tilt
                VIEWER_LEFT -> 4 + tilt
                FRONT -> 8
                BACK -> 9
                else -> throw PoseException("Cannot get body sprite index with non-numeric body direction")
            }
        } else {
            val base = when (bodyDirection) {
                VIEWER_RIGHT -> 0
                VIEWER_LEFT -> 4
                FRONT -> 8
                BACK -> 12
                else -> throw PoseException("Cannot get body sprite index with non-numeric body direction")
            }
            return base + tilt
        }
    }


    companion object {
        @Throws(PoseException::class)
        private fun fromInt(int: Int): Tilt? {
            return when (int) {
                DOWN.int -> DOWN
                STRAIGHT.int -> STRAIGHT
                UP.int -> UP
                FAR_UP.int -> FAR_UP
                else -> null
            }
        }

        @JvmStatic
        @Throws(PoseException::class)
        fun fromChar(char: String): Tilt? {
            if (char.length != 1) {
                throw PoseException("From char requires a single char value. Found: '$char'")
            }
            return fromChar(char[0])
        }

        @JvmStatic
        @Suppress("NON_EXPORTABLE_TYPE")
        @JsName("fromCharNoJS")
        @Throws(PoseException::class)
        fun fromChar(char: Char): Tilt? {
            if (char.uppercaseChar() == 'X') {
                return NO_CHANGE
            }
            val int = char.asChar().digitToIntOrNull()
                ?: return null
            return fromInt(int)
        }
    }
}