@file:Suppress("unused")

package com.bedalton.creatures.genetics.gene



import com.bedalton.creatures.genetics.gene.GeneConstants.GENE_SUBTYPE_NAME_BIOCHEMICAL_ORGAN
import com.bedalton.creatures.genetics.gene.GeneConstants.GENE_SUBTYPE_NAME_BRAIN_ORGAN
import com.bedalton.creatures.genetics.gene.GeneConstants.GENE_TYPE_NAME_BRAIN
import com.bedalton.creatures.genetics.gene.GeneConstants.GENE_TYPE_NAME_ORGAN
import com.bedalton.io.bytes.ByteStreamReader
import com.bedalton.io.bytes.ByteStreamWriter
import kotlinx.serialization.SerialName
import kotlinx.serialization.Serializable
import kotlin.js.JsExport
import kotlin.js.JsName

@JsExport
@Serializable
@SerialName("OrganGene")
data class OrganGene(
    // @ProtoNumber(1)
    @SerialName("version")
    override val version: Int,
    // @ProtoNumber(2)
    @SerialName("gene_type")
    override val geneType: Int,
    // @ProtoNumber(3)
    @SerialName("gene_subtype")
    override val geneSubType: Int,
    // @ProtoNumber(6)
    @SerialName("gene_index")
    override val geneIndex: Int,
    // @ProtoNumber(7)
    @SerialName("gene_index_of_type")
    override var geneIndexOfType: Int?,
    // @ProtoNumber(8)
    @SerialName("gene_header")
    override val geneHeader: GeneHeader = GeneHeader(version),
//    @ProtoNumber(12)
    @SerialName("clock_rate")
    val clockRate: Int,
//    @ProtoNumber(13)
    @SerialName("damage_rate")
    val damageRate: Int,
//    @ProtoNumber(14)
    @SerialName("life_force")
    val lifeForce: Int,
//    @ProtoNumber(15)
    @SerialName("biotick_start")
    val bioTickStart: Int,
//    @ProtoNumber(16)
    @SerialName("atp_damage_coefficient")
    val atpDamageCoefficient: Int,
    // @ProtoNumber(9)
    @SerialName("note")
    override val note: GeneNote? = null
) : Gene() {


    @JsName("builder")
    constructor(
        version: Int,
        geneType: Int,
        geneSubType: Int,
        geneIndex: Int,
        geneIndexOfType: Int? = null,
    ) : this(
        version = version,
        geneType = geneType,
        geneSubType = geneSubType,
        geneIndex = geneIndex,
        geneIndexOfType = geneIndexOfType,
        geneHeader = GeneHeader(version),
        clockRate = 0,
        damageRate = 0,
        lifeForce =  0,
        bioTickStart = 0,
        atpDamageCoefficient = 0,
        note = null
    )

    override val typeName: String
        get() = if (geneType == 0) GENE_TYPE_NAME_BRAIN else GENE_TYPE_NAME_ORGAN

    override val subtypeName: String
        get() = if (geneType == 0) {
            GENE_SUBTYPE_NAME_BRAIN_ORGAN
        } else {
            GENE_SUBTYPE_NAME_BIOCHEMICAL_ORGAN
        }

    override val description: String?
        get() = null


    override fun withGeneHeader(newHeader: GeneHeader): Gene {
        return copy(
            geneHeader = newHeader
        )
    }

    override fun withNote(newValue: GeneNote): Gene {
        return copy(
            note = newValue
        )
    }


    fun withClockRate(newValue: Int): OrganGene {
        return copy(
            clockRate = newValue
        )
    }

    fun withDamageRate(newValue: Int): OrganGene {
        return copy(
            damageRate = newValue
        )
    }

    fun withLifeForce(newValue: Int): OrganGene {
        return copy(
            lifeForce = newValue
        )
    }

    fun withBioTickStart(newValue: Int): OrganGene {
        return copy(
            bioTickStart = newValue
        )
    }

    fun withAtpDamageCoefficient(newValue: Int): OrganGene {
        return copy(
            atpDamageCoefficient = newValue
        )
    }

    override fun writeData(writer: ByteStreamWriter) {
        writer
            .writeUInt8(clockRate)
            .writeUInt8(damageRate)
            .writeUInt8(lifeForce)
            .writeUInt8(bioTickStart)
            .writeUInt8(atpDamageCoefficient)
    }


    override fun toJSON(): String {
        return json.encodeToString(serializer(), this)
    }

    companion object {
        internal fun fromReader(
            version: Int,
            type: Int,
            subType: Int,
            reader: ByteStreamReader,
            geneIndex: Int
        ) = OrganGene(
            version = version,
            geneType = type,
            geneSubType = subType,
            geneIndex = geneIndex,
            geneIndexOfType = reader.uInt8(),
            geneHeader = GeneHeader.fromReader(version, reader),
            clockRate = reader.uInt8(),
            damageRate = reader.uInt8(),
            lifeForce = reader.uInt8(),
            bioTickStart = reader.uInt8(),
            atpDamageCoefficient = reader.uInt8(),
            note = null
        )
    }
}
