    private val parts: MutableMap<Char, BreedKey?> = mutableMapOf()

    private var baseBreed: BreedKey? = null

    // The variant whose tint, swap and rotate to apply
    private var paletteTransformVariant: GameVariant? = null

    // Any kind of palette rendering transformations
    private var paletteTransform: PaletteTransform? = null

    // Age to apply to all parts. This overwrites all individual part ages
    private var age: Int? = null

    // Whether to force exact matches of breed parts, or allow fudging of age or gender
    private var exactMatch: Boolean? = null

    // Whether to force exact matches of breed parts, or allow fudging of age or gender
    private var closeAttMatchOnly: Boolean? = null

    // The sources to search for files in
    private var sourceRoots: MutableList<String> = sourceSets?.toMutableList() ?: mutableListOf()

    private var defaultZoom: Double = 1.0

    private var defaultGender: Int? = null

    private var ghost: Set<Char>? = null
    private var ghostAlpha: Double? = null
    private var renderGhostPartsBelow: Boolean? = null
    private var nonIntersectingLimbs: Boolean? = null
    private var trim: Boolean? = null
    private var recursive: Boolean? = null
    private var padding: Int? = null

    private var hidden: Set<Char>? = null

    private val priorityBreedDirectories = mutableMapOf<BreedKey, Pair<String?, String?>>()

    private val breedFiles = mutableMapOf<String, File>()

    private var genome: Genome? = null
    private var geneVariant: Int? = null

    private var applyPartsFromGenomeOnBuild: Boolean = false
    private var applyPaletteTransformFromGenomeOnBuild = false


    private val validBreedChars
        get() = if (gameVariant == GameVariant.C1) {
            '0'..'9'
        } else {
            'a'..'z'
        }

    constructor(builder: BreedRendererBuilder) : this(builder.gameVariant) {
        builder.parts.toMap(parts)
        baseBreed = builder.baseBreed
        paletteTransform = builder.paletteTransform
        age = builder.age
        exactMatch = builder.exactMatch
        sourceRoots = builder.sourceRoots.toMutableList()
        defaultZoom = builder.defaultZoom
        defaultGender = builder.defaultGender
        paletteTransformVariant = builder.paletteTransformVariant
        ghost = builder.ghost
        hidden = builder.hidden
        ghostAlpha = builder.ghostAlpha
        renderGhostPartsBelow = builder.renderGhostPartsBelow
        nonIntersectingLimbs = builder.nonIntersectingLimbs
        trim = builder.trim
        padding = builder.padding
        recursive = builder.recursive
        closeAttMatchOnly = builder.closeAttMatchOnly
        genome = builder.genome
        geneVariant = builder.geneVariant
        applyPartsFromGenomeOnBuild = builder.applyPartsFromGenomeOnBuild
        applyPaletteTransformFromGenomeOnBuild = builder.applyPaletteTransformFromGenomeOnBuild
        // Apply priority breed directories from builder
        builder.priorityBreedDirectories.toMap(priorityBreedDirectories)
    }

