    /**
     * Add a tint, swap and rotate transformation
     * Does not stack
     */
    fun withTintSwapAndRotate(
        red: Int?,
        green: Int?,
        blue: Int?,
        swap: Int?,
        rotation: Int?,
        throwOnInvalidValue: Boolean
    ): BreedRendererBuilder {
        if (throwOnInvalidValue) {
            validateTintSwapAndRotationThrowing(red, green, blue, swap, rotation)
        }
        paletteTransform = PaletteTransform(
            gameVariant = gameVariant,
            red = red?.bound(),
            green = green?.bound(),
            blue = blue?.bound(),
            swap = swap?.bound(),
            rotation = rotation?.bound()
        )
        return this
    }

    /**
     * Ensures that tint, swap and rotate values are within 0..255 boundaries
     */
    private fun validateTintSwapAndRotationThrowing(red: Int?, green: Int?, blue: Int?, swap: Int?, rotation: Int?) {
        val errors = mutableListOf<String>()
        val range = 0..255
        if ((red ?: 0) !in range) {
            errors.add("red: $red")
        }
        if ((green ?: 0) !in range) {
            errors.add("green: $green")
        }
        if ((blue ?: 0) !in range) {
            errors.add("blue: $blue")
        }
        if ((swap ?: 0) !in range) {
            errors.add("swap: $swap")
        }
        if ((rotation ?: 0) !in range) {
            errors.add("rotation: $rotation")
        }
        if (errors.isNotEmpty()) {
            throw RenderValueOutOfRangeException(
                "Tint values must be 0..255. Invalid Values: [${errors.joinToString()}]",
                "tint values",
                errors,
                "0", "255"
            )
        }
    }

