    /**
     * Sets the att directory to use for a given part
     */
    fun withBreedDirectory(breedKey: BreedKey, directory: String, isSpriteDirectory: Boolean): BreedRendererBuilder {
        val key = breedKey.copyWithAgeGroup(null)
        var out = this
        if (key.gender != 1) {
            out = withBreedDirectory(breedKey.copyWithGender(gender = 2), directory, isSpriteDirectory, true)
        }
        if (key.gender != 2) {
            out = withBreedDirectory(breedKey.copyWithGender(gender = 1), directory, isSpriteDirectory, true)
        }
        if (key.gender == null) {
            out = withBreedDirectory(breedKey, directory, isSpriteDirectory, false)
        }
        return out
    }

    private fun withBreedDirectory(breedKey: BreedKey, directory: String, isSpriteDirectory: Boolean, setOnlyIfNotSet: Boolean): BreedRendererBuilder {
        if (setOnlyIfNotSet && priorityBreedDirectories.containsKey(breedKey)) {
            return this
        }
        val existing = priorityBreedDirectories[breedKey]
        priorityBreedDirectories[breedKey] = if (isSpriteDirectory) {
            existing.withFirstAndNull(directory)
        } else {
            existing.withSecondAndNull(directory)
        }
        return this
    }

