    private fun char(charString: String): Char {
        val length = charString.length
        if (length == 0) {
            throw NotSingleCharException(
                "Char string cannot be blank",
                "char string",
                null
            )
        } else if (length > 1) {
            throw NotSingleCharException(
                "Char string must be a single letter/character only",
                "single char",
                charString,
            )
        } else {
            return charString[0]
        }
    }

    fun withRecursiveFileSearch(recursive: Boolean?): BreedRendererBuilder {
        this.recursive = recursive
        return this
    }

    fun getUseRecursiveFileSearch(): Boolean? {
        return this.recursive
    }

    /**
     * Genome overwrites values set for parts, pigment and bleed
     */
    fun withGenomeApplyAtBuild(genome: Genome?): BreedRendererBuilder {
        return withGenomeApplyAtBuild(genome, 0)
    }

    /**
     * Genome overwrites values set for parts, pigment and bleed
     */
    fun withGenomeApplyAtBuild(genome: Genome?, geneVariant: Int): BreedRendererBuilder {
        this.genome = genome
        this.geneVariant = geneVariant
        applyPartsFromGenomeOnBuild = true
        applyPaletteTransformFromGenomeOnBuild = true
        return this
    }

    /**
     * Apply genome values set for parts, pigment and bleed, overwriting existing values
     */
    fun withGenomeApplyNow(genome: Genome?, gender: Int, age: Int, geneVariant: Int = 0): BreedRendererBuilder {
        if (genome == null) {
            return this
        }
        this.genome = genome
        this.geneVariant = geneVariant
        var out = this.applyColorTransformFromGenome(genome, gender, age, geneVariant)
        out = out.applyPartsFromGenome(genome, gender, age, geneVariant)
        return out
    }

    fun getGenome(): Genome? {
        return this.genome
    }

    fun getGeneVariant(): Int? {
        return geneVariant
    }

    fun applyColorTransformFromGenome(genome: Genome, gender: Int, age: Int, geneVariant: Int = 0): BreedRendererBuilder {
        applyPaletteTransformFromGenomeOnBuild = false
        val transform = getColorTransformFromGenome(paletteTransformVariant ?: gameVariant, genome, gender, age, geneVariant)
        return withPaletteTransform(transform)
    }

    fun applyPartsFromGenome(genome: Genome, gender: Int, age: Int, selectedVariant: Int = 0): BreedRendererBuilder {
        applyPartsFromGenomeOnBuild = false
        return applyPartsFromGenomeActual(gameVariant, genome, gender, age, selectedVariant)
    }

    fun withBreedIfNotSet(breed: BreedKey, vararg parts: Char): BreedRendererBuilder {
        val setParts = this.parts.keys
        for (part in parts.filter { it.lowercaseChar() !in setParts }) {
            this.parts[part] = breed
        }
        return this
    }

    fun missingRequiredParts(): Array<String> {
        return missingRequiredParts(false)
    }

    fun missingRequiredParts(requireTail: Boolean): Array<String> {
        val missing = mutableListOf<String>()
        if (!hasHeadBreed()) {
            missing.add("head")
        }
        if (!hasBodyBreed()) {
            missing.add("body")
        }

        if (!hasLeftLegBreed()) {
            if (!hasRightLegBreed()) {
                missing.add("legs")
            } else {
                missing.add("left leg")
            }
        } else if (!hasRightLegBreed()) {
            missing.add("right leg")
        }


        if (!hasLeftArmBreed()) {
            if (!hasRightArmBreed()) {
                missing.add("arms")
            } else {
                missing.add("left arm")
            }
        } else if (!hasRightArmBreed()) {
            missing.add("right arm")
        }
        if (requireTail && !hasTailBreed()) {
            missing.add("tail")
        }
        return missing.toTypedArray()
    }


    fun toCLIOpts(withRoots: Boolean = false): String? {
        val out = StringBuilder("render-breed ")
        out.append(gameVariant.code).append(' ')

        val allParts = (parts.values + baseBreed).filterNotNull()

        // Age
        val actualAge = age
            ?: allParts.takeIfOne { it.ageGroup }
            ?: return null
        out.appendOpt("age", actualAge)

        // Gender
        val actualGender = defaultGender
            ?: allParts.takeIfOne { it.gender }
            ?: return null
        out.appendOpt("gender", actualGender)

        // Breed
        val oneBreed = parts.values.distinct().singleOrNull()
        if (oneBreed != null) {
            out.appendOpt("breed", oneBreed)
        } else {
            out.appendOpt("breed", baseBreed)
            out.appendOpt("head", parts['a'])
            out.appendOpt("body", parts['b'])
            out.appendOpt("legs", parts['c'] ?: parts['d'] ?: parts['e'] ?: parts['f'] ?: parts['g'] ?: parts['h'])
            out.appendOpt("arms", parts['i'] ?: parts['j'] ?: parts['k'] ?: parts['l'])
            out.appendOpt("tail", parts['m'] ?: parts['n'])
            out.appendOpt("hair", parts['q'])
        }

        // Palette
        out.appendTransform(paletteTransform)
        out.appendOpt("transform-variant", paletteTransformVariant)

        // Visibility
        out.appendOpt("hidden ", hidden)
        out.appendOpt("ghost", ghost)
        out.appendOpt("ghost-alpha", ghostAlpha)
        out.appendFlag("ghost-parts-below", renderGhostPartsBelow)


        out.appendOpt("padding", padding)
        out.appendFlag("trim", trim)
        out.appendFlag("no-intersect", nonIntersectingLimbs)

        // Files
        out.appendFlag("exact-match", exactMatch)
        if (withRoots) {
            for (source in sourceRoots) {
                out.append('"').append(source.escape()).append("\" ")
            }
        }

        // Return
        return out.toString().replace("\\s\\s+", " ").trim()
    }


