    fun hasBreed(vararg parts: Char): Boolean {
        return parts.all test@{ part ->
            val breed = this.parts[part]
            breed != null && breed != NONE_BREED
        }
    }

    /**
     * Checks if a breed is set for all parts, ignoring age and gender
     * NOTE: only checks breed char and genus, these are expected to be applied later
     */
    fun hasBreed(parts: Array<Char>): Boolean {
        return parts.all test@{ part ->
            val breed = this.parts[part]
            val breedIsSet = breed != null && breed != NONE_BREED
            val breedIsConcrete = breed?.breed != null && breed.genus != null
            if (breedIsSet && !breedIsConcrete) {
                Log.wIf(LOG_DEBUG) { "Breed for part: '$part' was set to non-concrete value; $breed" }
            } /*else if (!breedIsSet) {
                Log.iIf(LOG_DEBUG) { "Breed is not set for part: $part"}
            }*/
            breedIsSet && breedIsConcrete
        }
    }

    fun hasBreed(parts: List<Char>): Boolean {
        return parts.all test@{ part ->
            val breed = this.parts[part]
            breed != null && breed != NONE_BREED
        }
    }

