    companion object {

        fun build(builder: BreedRendererBuilder): BreedRenderProvider {
            val fs = UnscopedFileSystem()
            return build(fs, builder)
        }

        /**
         * Build the actual BreedRenderTask
         */
        fun build(fs: FileSystem, builder: BreedRendererBuilder): BreedRenderProvider {

            var task = builder
            val sourceRoots = task.sourceRoots
            if (sourceRoots.isEmpty()) {
                throw IOException("Source sets cannot be blank for build breed render provider")
            }

            val age = task.age ?: task.baseBreed?.ageGroup ?: task.parts.mapNotNull { it.value?.ageGroup }.singleOrNull()
            val gender = task.defaultGender ?: task.baseBreed?.gender ?: task.parts.mapNotNull { it.value?.gender }.singleOrNull()

            val genome = task.genome
            if (genome != null && (task.applyPartsFromGenomeOnBuild || task.applyPaletteTransformFromGenomeOnBuild)) {
                if (age == null) {
                    if (gender == null) {
                        throw MissingRenderValueException(
                            message = "Cannot build genome renderer without age and gender",
                            property = "genome renderer",
                            missing = arrayOf("age", "gender")
                        )
                    } else {
                        throw MissingRenderValueException(
                            message = "Cannot build genome renderer without age",
                            property = "genome renderer",
                            missing = "age"
                        )
                    }
                } else if (gender == null) {
                    throw MissingRenderValueException(
                        message = "Cannot build genome renderer without gender",
                        property = "genome renderer",
                        missing = "gender"
                    )
                }
                if (task.applyPaletteTransformFromGenomeOnBuild) {
                    task = task.applyColorTransformFromGenome(genome, gender, age)
                }
                if (task.applyPartsFromGenomeOnBuild) {
                    task = task.applyPartsFromGenome(genome, gender, age)
                }
            }
            val hidden = task.hidden?.map { it.lowercaseChar() }
            val ghost = task.ghost?.map { it.lowercaseChar() }

            fun BreedKey?.applyDefaults(): BreedKey? {
                var out = this
                    ?: return null
                if (age != null && out.ageGroup == null) {
                    out = out.copyWithAgeGroup(age)
                }
                if (gender != null && out.gender == null) {
                    out = out.copyWithGender(gender)
                }
                return out
            }

            val palette = task.paletteTransform?.copy(
                gameVariant = task.paletteTransformVariant ?: task.paletteTransform?.gameVariant ?: task.gameVariant,
            )
            return BreedRenderProvider(
                variant = task.gameVariant,
                files = fs,
                sourceRoots = sourceRoots,
                partBreeds = task.parts.mapValues { it.value.applyDefaults() },
                spriteRoot = null,
                attRoot = null,
                paletteTransform = palette,
                defaultBreed = task.baseBreed.applyDefaults(),
                exactMatch = task.exactMatch,
                partVisibility = ('a'..'q').associate { part ->
                    if (hidden?.contains(part) == true) {
                        part to PartVisibility.HIDDEN
                    } else if (ghost?.contains(part) == true) {
                        part to PartVisibility.GHOST
                    } else {
                        part to PartVisibility.VISIBLE
                    }
                },
                ghostAlpha = task.ghostAlpha,
                renderGhostPartsBelow = task.renderGhostPartsBelow,
                nonIntersectingLimbs = task.nonIntersectingLimbs,
                trim = task.trim,
                recursive = task.recursive,
                closeMatchOnly = task.closeAttMatchOnly,
                priorityBreedDirectories = task.priorityBreedDirectories,
                defaultPadding = task.padding,
                defaultZoom = task.defaultZoom,
            )
        }
    }
}


