package com.bedalton.creatures.caos.libs

import kotlinx.serialization.Serializable
import kotlin.js.JsExport
import kotlin.js.JsName

/**
 * Documentation object for a CAOS command parameter
 */
@JsExport
@JsName("ICaosParameter")
@Serializable
data class VariantCaosParameter(
    /**
     * Argument index within a command call
     */
    @JsName("index")
    val index: Int,
    /**
     * The human-readable name of this parameter
     */
    @JsName("name")
    val name: String,

    /**
     * The internal value type id
     */
    @JsName("typeId")
    val typeId: Int,

    /**
     * The human-readable type name
     */
    @JsName("type")
    val typeName: String,

    /**
     * The id of this parameters known values (if any)
     * This would be the id to the CHEMICALS values list for the chemical parameter for `CHEM`
     */
    @JsName("valuesListId")
    val valuesListId: Int? = null,

    /**
     * The name of the values list
     */
    @JsName("valuesListName")
    val valuesListName: String? = null,
) {
    internal constructor(parameter: CaosParameter, variant: String) : this(
        parameter.index,
        parameter.name,
        parameter.typeId,
        parameter.type.simpleName,
        valuesListId = parameter.valuesListIds?.get(variant),
        valuesListName = parameter.valuesListIds?.get(variant)?.let { valuesListId ->
            CaosLibs[variant].valuesList(valuesListId)?.name
        }
    )

    /**
     * The associated values list
     */
    @Suppress("unused")
    val valuesList: CaosValuesList?
        get() {
            return if (valuesListId != null) {
                getValuesList(valuesListId)
            } else {
                null
            }
        }
}