package com.bedalton.creatures.common.util

import kotlin.js.JsExport


/**
 * Takes a 4 character string and makes a DWORD token
 */
@Throws(CaosInvalidTokenLengthException::class)
fun token(token: String): Int {
    val chars = token.lowercase().toCharArray()
    if (chars.isEmpty() || chars.size > 4)
        throw CaosInvalidTokenLengthException(chars)
    return token(chars[0].code, chars[1].code, chars[2].code, chars[3].code)
}

/**
 * Takes a CAOS word token, and converts it back to a string
 */
fun token(token: Int): String {
    return "${(token shr 24).toChar()}${((token shr 16) and 0xFF).toChar()}${((token shr 8) and 0xFF).toChar()}${(token and 0xFF).toChar()}"
}

/**
 * Generate a token from 4 chars
 */
fun token(c1: Char, c2: Char, c3: Char, c4: Char): Int =
    token(c1.code, c2.code, c3.code, c4.code)

/**
 * Generate a token from 4 chars lowercased
 */
fun tokenFromLowerCase(c1: Char, c2: Char, c3: Char, c4: Char): Int =
    token(c1.lowercaseChar().code, c2.lowercaseChar().code, c3.lowercaseChar().code, c4.lowercaseChar().code)

/**
 * Generate a token from 4 bytes(as ints)
 */
fun token(a: Int, b: Int, c: Int, d: Int) = a shl 24 or (b shl 16) or (c shl 8) or d


/**
 * Exception thrown when a string of invalid length is passed to token(string) method
 */
@JsExport
open class CaosInvalidTokenLengthException(val chars:CharArray, message:String, throwable: Throwable? = null)
    : Exception(message, throwable) {
    internal constructor(chars:CharArray, throwable: Throwable? = null) : this(chars, "Invalid CAOS token length. Expected 4, found ${chars.size} in token: '${chars.joinToString("")}'", throwable)
}
