package com.bedalton.creatures.sprite.util

import com.bedalton.common.exceptions.IOException
import com.bedalton.common.util.PathUtil
import com.bedalton.common.util.joinToString
import korlibs.image.bitmap.Bitmap
import korlibs.image.bitmap.Bitmap32
import korlibs.image.format.BMP
import korlibs.image.format.GIF
import korlibs.image.format.JPEGInfo
import korlibs.image.format.PNG


/**
 * Converts bytes to an image, taking into account its filename
 * If decoding fails, re-runs using first few bytes to determine image type
 */
fun bytesToImage(bytes: ByteArray, fileName: String): Bitmap32 {
    return try {
        bytesToImageEx(bytes, fileName)
    } catch (_: Exception) {
        bytesToImage(bytes)
    }
}
/**
 * Converts bytes to an image, taking into account its filename
 */
private fun bytesToImageEx(bytes: ByteArray, fileName: String): Bitmap32 {
    return when (val extension = PathUtil.getExtension(fileName)?.lowercase()) {
        "png" -> PNG.decode(bytes).toBMP32IfRequired()
        "bmp" -> BMP.decode(bytes).toBMP32IfRequired()
        "jpeg", "jpg" -> JPEGInfo.decode(bytes).toBMP32IfRequired()
        "gif" -> GIF.decode(bytes).toBMP32IfRequired()
        else -> throw IOException("Unsupported image file type extension <${extension}>")
    }
}


/**
 * Converts bytes to a bitmap32, with image type determined by first few bytes
 */
fun bytesToImage(bytes: ByteArray): Bitmap32 {
    val header = bytes.slice(0 until 8).joinToString("") {
        (it.toInt() and 0xFF).toString(16).padStart(2, '0')
    }.uppercase()


    return when (header) {
        "89504E470D0A1A0A" -> PNG.decode(bytes).toBMP32IfRequired()
        "424D" -> BMP.decode(bytes).toBMP32IfRequired()
        "FFD8FFE0" -> JPEGInfo.decode(bytes).toBMP32IfRequired()
        "474946" -> GIF.decode(bytes).toBMP32IfRequired()
//      "49492A" -> TIFF.decode(bytes).toBMP32IfRequired()
        else -> throw IOException("Unexpected header bytes: $header")
    }
}