@file:Suppress("unused", "MemberVisibilityCanBePrivate")

package com.bedalton.io.bytes

import kotlin.jvm.JvmStatic
import kotlin.math.min

/**
 * Base class for writing bytes
 * Uses a lock to prevent overlapping access
 */
interface ByteStreamWriter {

    val position: Int
    val size: Long
    val bytes: ByteArray

    fun writeUInt8(byte: Int): ByteStreamWriter

    fun write(bytes: ByteArray): ByteStreamWriter

    fun writeUInt16(ushortArray: Array<Int>): ByteStreamWriter

    fun writeUInt16(valueIn: Int): ByteStreamWriter

    fun writeUInt16BE(valueIn: Int): ByteStreamWriter

    fun writeUInt32(valueIn: Int): ByteStreamWriter

    fun writeUInt32BE(valueIn: Int): ByteStreamWriter

    fun writeUInt64(valueIn: Long): ByteStreamWriter

    fun writeUInt64BE(valueIn: Long): ByteStreamWriter

    fun writeFloat(valueIn: Float): ByteStreamWriter

    fun writeDouble(valueIn: Double): ByteStreamWriter

    fun writeStringWithCreaturesEncoding(valueIn: String): ByteStreamWriter

    /**
     * Writes a single null byte
     */
    fun writeNullByte(): ByteStreamWriter {
        writeUInt8(0)
        return this
    }

    /**
     * Writes a string with a terminating null byte
     * Used for c style strings
     */
    fun writeNullTerminatedString(string: String): ByteStreamWriter {
        writeStringWithCreaturesEncoding(string)
        writeNullByte()
        return this
    }


    /**
     * Write SFC style string to the byte stream reader
     */
    fun writeSfcString(string: String): ByteStreamWriter {
        val length = string.length
        var writeNext = min(255, length)
        writeUInt8(writeNext)
        if (length >= 255) {
            writeNext = min(65535, length)
            writeUInt16(writeNext)
            if (length > 65535) {
                writeUInt32(length)
            }
        }
        write(string.encodeToWindowsCP1252EncodedBytes())
        return this
    }


    fun Boolean.asInt(): Int = if (this) 1 else 0


    private fun Boolean.asLong(): Long = if (this) 1L else 0L


    /**
     * Writes a bool as an uint8
     * Writes '1' if true or '0' if false
     */
    fun ByteStreamWriter.writeUInt8Bool(bool: Boolean): ByteStreamWriter {
        return writeUInt8(bool.asInt())
    }


    /**
     * Writes a bool as an uint16
     * Writes '1' if true or '0' if false
     */
    fun ByteStreamWriter.writeUInt16Bool(bool: Boolean): ByteStreamWriter {
        return writeUInt16(bool.asInt())
    }

    /**
     * Writes a bool as an uint32
     * Writes '1' if true or '0' if false
     */
    fun writeUInt32Bool(bool: Boolean): ByteStreamWriter {
        return writeUInt32(bool.asInt())
    }


    companion object {

        fun create(): ByteStreamWriter {
            return MemoryByteStreamWriter()
        }

        @JvmStatic
        inline fun writeBytes(work: ByteStreamWriter.() -> Unit): ByteArray {
            val buffer = MemoryByteStreamWriter()
            buffer.work()
            return buffer.bytes
        }
    }
}