package com.bedalton.creatures.sprite.util

import com.bedalton.creatures.common.structs.GameVariant
import kotlinx.serialization.Serializable
import kotlin.js.JsExport

@JsExport
@Serializable
data class PaletteTransform(
    val gameVariant: GameVariant,
    val red: Int? = null,
    val green: Int? = null,
    val blue: Int? = null,
    val swap: Int? = null,
    val rotation: Int? = null
) {

    val hasTransform by lazy {
        isNotDefault(red) || isNotDefault(green) || isNotDefault(blue) ||
                isNotDefault(swap) || isNotDefault(rotation)
    }

    val isDefault get() = !hasTransform

    private fun isNotDefault(value: Int?): Boolean {
        return value != null && value != 128
    }

    fun transform(encoding: ColorEncoding, keepBlack: Boolean): ColorPalette {
        return encoding.toRgbWithTables(keepBlack).transform(this, encoding, keepBlack)
    }
}

fun PaletteTransform?.nullIfDefault(): PaletteTransform? {
    return if (this == null || this.isDefault) {
        null
    } else {
        this
    }
}