package com.bedalton.creatures.caos.validation

import com.bedalton.common.ast.structs.sortValue
import com.bedalton.creatures.caos.collectors.CaosParserItem
import com.bedalton.creatures.caos.collectors.ParseResult
import com.bedalton.creatures.caos.collectors.parseCaos
import com.bedalton.creatures.caos.libs.CaosVariant
import com.bedalton.creatures.caos.libs.orElse
import com.bedalton.creatures.caos.utils.isCaos2

fun validateCaos(
    variant: String,
    caos: String,
    checkCancelled: () -> Unit = {}
): Array<CaosParserItem.ErrorVal> {
    val parseResult = parseCaos(variant,caos) {
        checkCancelled()
        true
    }
    return validateCaosParseResult(parseResult, checkCancelled)
}

fun validateCaosParseResult(
    result: ParseResult,
    checkCancelled: () -> Unit = {}
): Array<CaosParserItem.ErrorVal> {

    val variant = CaosVariant
        .fromVal(result.variant.uppercase())
        .orElse(CaosVariant.DS)

    return com.bedalton.creatures.caos.validation.internal.collectErrors(
        variant,
        result.caos2Comments.isCaos2,
        (result.items + result.whitespaceItems).sortedBy { it.textRange.sortValue }.toTypedArray(),
        result.commandCalls,
        result.looseTokens,
        checkCancelled
    )
}