@Serializable
internal sealed class Glyph {

    abstract val filename: String

    abstract val manual: Boolean

    @Transient
    private var glyphCache: Bitmap32? =  null

    abstract fun withName(newName: String): Glyph

    abstract suspend fun getGlyphData(): ByteArray?

    abstract suspend fun getBitmap32(): Bitmap32?


    fun Bitmap32.toGlyphSize(): Bitmap32 {
        glyphCache?.let {
            return it
        }
        if (width == height) {
            return this.resizedTo(
                width = TARGET_SIZE,
                height = TARGET_SIZE,
                smooth = true,
                blackIsTransparent = false,
                keepBlack = false,
                shrinkBlackBorder = true
            )
        }

        var out = this.trimWhitespace()
        val scale: Double = if (out.width == out.height) {
            NON_WHITESPACE_SIZE / out.width
        } else if (out.width > out.height) {
            NON_WHITESPACE_SIZE / width
        } else {
            NON_WHITESPACE_SIZE / height
        }
        out = out.scaleLinear(scale)
        val paddingX = floor((TARGET_SIZE - out.width) / 2.0).toInt()
        val paddingY = floor((TARGET_SIZE - out.height) / 2.0).toInt()
        val padded = Bitmap32(TARGET_SIZE, TARGET_SIZE).apply {
            out.copy(0, 0, this, paddingX, paddingY, out.width, out.height)
        }
        glyphCache = padded
        return padded
    }


    private fun Bitmap32.trimWhitespace(): Bitmap32 {
        var minX: Int? = null
        var maxX: Int? = null
        var minY: Int? = null
        var maxY: Int? = null
        repeat (height) { y ->
            repeat(width) { x ->
                if (get(x, y).a > 127) {
                    if (minX == null || x < minX!!) {
                        minX = x
                    }
                    if (maxX == null || x > maxX!!) {
                        maxX = x
                    }
                    if (minY == null || y < minY!!) {
                        minY = y
                    }
                    if (maxY == null || y > maxY!!) {
                        maxY = y
                    }
                }
            }
        }
        return copySliceWithBounds(
            minX ?: 0,
            minY ?: 0,
            maxX ?: width,
            maxY ?: height
        )
    }

    companion object {
        private const val TARGET_SIZE = 60
        private const val NON_WHITESPACE_SIZE = 52.0
    }
}


@Serializable
internal data class BitmapGlyph(
    override val filename: String,
    @Serializable(with = Bitmap32Serializer::class)
    private val bitmap32: Bitmap32,
    override val manual: Boolean = false
) : Glyph() {

    private val mBitmap: Bitmap32 by lazy {
        bitmap32.resizedTo(
            width = 60,
            height = 60,
            smooth = true,
            blackIsTransparent = false,
            keepBlack = false,
            shrinkBlackBorder = true
        )
    }

    private val data by lazy {
        DataCache {
            SpriteCompiler.getCompiler(SpriteType.C16)
                .compileSpriteFromLoadedImages(
                    images = listOf(mBitmap),
                    keepBlack = false,
                    colorEncoding = ColorEncoding.X_565
                )
        }
    }


    override suspend fun getBitmap32(): Bitmap32 {
        return bitmap32
    }


    override fun withName(newName: String): Glyph {
        return copy(
            filename = newName
        )
    }

    override suspend fun getGlyphData(): ByteArray? {
        return data.getData()
    }
}

@Serializable
internal sealed class GlyphWithFrame: Glyph() {
    abstract val frame: Int

    @Transient
    private val mRange = DataCache {
        0 .. (size() ?: 0)
    }

    abstract suspend fun size(): Int?

    abstract fun withFrame(frame: Int): GlyphWithFrame

    @Suppress("unused")
    suspend fun range(): IntRange {
        return mRange.getData()!!
    }
}

@Serializable(with = SpriteGlyphSerializer::class)
internal data class SpriteGlyph(
    override val filename: String,
    override val frame: Int,
    val spriteName: String,
    val frames: DataCache<List<SpriteFrameAsync>?>,
    override val manual: Boolean = false
) : GlyphWithFrame() {

    private var data: (() -> ByteArray?)? = null

    private var mImage: (() -> Bitmap32?)? = null

    override suspend fun  size(): Int? {
        return frames.getData()?.size
    }

    override suspend fun getBitmap32(): Bitmap32? {
        mImage?.let {
            return it()
        }

        val image = frames
            .getData()
            ?.getOrNull(frame)
            ?.image(keepBlack = false)
            ?.toGlyphSize()
        mImage = { image }
        return image
    }

    override suspend fun getGlyphData(): ByteArray? {
        data?.invoke()?.let {
            return it
        }
        val bytes = compile()
        data = { bytes }
        return bytes
    }

    private suspend fun compile(): ByteArray? {
        val frame = getBitmap32()
            ?: return null
        return SpriteCompiler.getCompiler(SpriteType.C16)
            .compileSpriteFromLoadedImages(
                images = listOf(frame),
                keepBlack = false,
                colorEncoding = ColorEncoding.X_565
            )
    }

    override fun withName(newName: String): Glyph {
        return copy(
            filename = newName
        )
    }

    override fun withFrame(frame: Int): SpriteGlyph {
        return copy(
            frame = frame
        )
    }

    companion object {

        fun create(
            filename: String,
            frame: Int,
            spriteName: String,
            sourceBytes: ByteArray,
            manual: Boolean = false,
        ): SpriteGlyph {
            return SpriteGlyph(
                filename = filename,
                frame = frame,
                spriteName = spriteName,
                frames = DataCache { getFrames(filename, MemoryByteStreamReader(sourceBytes)) },
                manual = manual,
            )
        }


        fun create(
            filename: String,
            frame: Int,
            sourceSprite: String,
            manual: Boolean = false
        ): SpriteGlyph {
            return SpriteGlyph(
                filename = filename,
                frame = frame,
                spriteName = sourceSprite,
                frames = DataCache { getFrames(sourceSprite) },
                manual = manual
            )
        }


        private suspend fun getFrames(sourceSprite: String): List<SpriteFrameAsync>? {
            val fs = vfs
            val stream =  try {
                fs.readAsStreamReader(sourceSprite)
            } catch (e: Exception) {
                e.rethrowCancellationException()
                Log.eIf(LOG_DEBUG) {
                    "Failed to read sprite glyph as bitmap; ${e.className}:${e.message?.let {": $it" } ?:  ""}\n${e.stackTraceToString()}"
                }
                return null
            }
            return getFrames(sourceSprite, stream)
        }

        private fun getFrames(sourceSprite: String, stream: ByteStreamReader): List<SpriteFrameAsync>? {
            val type = SpriteType.fromString(PathUtil.getExtension(sourceSprite) ?: "C16")
            return when (type) {
                SpriteType.C16 -> C16SpriteFile(
                    stream,
                    keepBlack = false,
                ).getAsyncFrames()

                SpriteType.SPR -> SprSpriteFile(
                    stream,
                    protoType = false,
                    palette = ColorPalette.C1TransparentBlack,
                    progressCallback = null
                ).getAsyncFrames()

                SpriteType.S16 -> S16SpriteFile(
                    stream,
                    keepBlack = false
                ).getAsyncFrames()
                else -> {
                    return null
                }
            }
        }
    }
}