package com.bedalton.vfs

import com.bedalton.common.util.PathUtil
import com.bedalton.io.bytes.ByteStreamReader
import com.bedalton.vfs.internal.FileSystemActions

abstract class UnscopedFileSystemBase : FileSystem {
    override suspend fun getChildrenNonRecursive(directory: String): List<String>? {
        val directoryExpanded = directory.expandTildeIfNecessary()
        return FileSystemActions.getChildrenNonRecursive(directoryExpanded)
    }

    override suspend fun delete(path: String): Boolean {
        val pathExpanded = path.expandTildeIfNecessary()

        if (!fileExists(pathExpanded)) {
            return true
        }
        if (isDirectory(pathExpanded)) {
            FileSystemErrors.throwDeletingAFolderNotAFile(pathExpanded)
        }
        return FileSystemActions.delete(pathExpanded)
    }

    override suspend fun fileExists(path: String): Boolean {
        val pathExpanded = path.expandTildeIfNecessary()
        return FileSystemActions.fileExists(pathExpanded)
    }

    override suspend fun isDirectory(path: String): Boolean {
        val pathExpanded = path.expandTildeIfNecessary()
        return FileSystemActions.isDirectory(pathExpanded)
    }

    override suspend fun md5(path: String): String? {
        val pathExpanded = path.expandTildeIfNecessary()

        assertFileExistsAndIsNotDirectory("md5", path, pathExpanded)
        return FileSystemActions.md5(pathExpanded)
    }

    override suspend fun read(path: String): ByteArray {
        val pathExpanded = path.expandTildeIfNecessary()
        assertFileExistsAndIsNotDirectory("read bytes", path, pathExpanded)
        return FileSystemActions.readBytes(pathExpanded)
    }

    override suspend fun read(path: String, offset: Long, length: Long): ByteArray? {
        val pathExpanded = path.expandTildeIfNecessary()
        assertFileExistsAndIsNotDirectory("read bytes", path, pathExpanded)
        return FileSystemActions.readBytes(pathExpanded, offset, length)
    }

    override suspend fun readTextUTF8(path: String): String {
        val pathExpanded = path.expandTildeIfNecessary()
        assertFileExistsAndIsNotDirectory("read text UTF-8", path, pathExpanded)
        return FileSystemActions.readTextWithUTF8Encoding(pathExpanded)
    }

    override suspend fun readTextWindowsCP1252(path: String): String {
        val pathExpanded = path.expandTildeIfNecessary()
        assertFileExistsAndIsNotDirectory("read text Windows CP1252", path, pathExpanded)
        return FileSystemActions.readTextWithWindowsCP1252Encoding(pathExpanded)
    }

    override suspend fun write(path: String, data: ByteArray, append: Boolean) {
        val pathExpanded = path.expandTildeIfNecessary()
        if (fileExists(pathExpanded) && isDirectory(pathExpanded)) {
            throw NotAFileException(pathExpanded, "Write failed. File <$path> is a directory")
        }
        ensureAndGetOutputDirectory(PathUtil.getWithoutLastPathComponent(pathExpanded)!!, true)
        FileSystemActions.write(pathExpanded, data, append)
    }

    override suspend fun makeDirectory(path: String, recursive: Boolean): Boolean {
        val pathExpanded = path.expandTildeIfNecessary()
        if (!canMakeDirectories()) {
            return false
        }

        if (FileSystemActions.fileExists(pathExpanded)) {
            if (!FileSystemActions.isDirectory(pathExpanded)) {
                throw NotADirectoryException(pathExpanded, "Cannot make directory. Path <$path> exists and is a file not a directory")
            }
            return true
        }
        return FileSystemActions.makeDirectory(pathExpanded, recursive)
    }

    override suspend fun deleteDirectory(path: String): Boolean {
        return false
    }

    override suspend fun readAsStreamReader(path: String): ByteStreamReader {
        val pathExpanded = path.expandTildeIfNecessary()
        assertFileExistsAndIsNotDirectory("read bytes as stream", path, pathExpanded)
        return FileSystemActions.readAsStreamReader(pathExpanded)
    }

    override suspend fun moveFile(fromFile: String, toFile: String, overwrite: Boolean): Int {
        val from = fromFile.expandTildeIfNecessary()
        val to = toFile.expandTildeIfNecessary()
        if (!fileExists(from)) {
            return MOVED__FROM_FILE_DOES_NOT_EXIST
        }
        if (fileExists(to) && !overwrite) {
            return MOVED__TO_FILE_ALREADY_EXISTS
        }
        return com.bedalton.vfs.internal.moveFile(from, to, overwrite)
    }

    private suspend fun assertFileExistsAndIsNotDirectory(action: String, path: String, pathExpanded: String) {
        if (!fileExists(pathExpanded)) {
            throw FileNotFoundException(pathExpanded, "Cannot ${action}. File: <$path> does not exist")
        }
        if (isDirectory(pathExpanded)) {
            throw NotAFileException(pathExpanded, "Cannot ${action}. File <$path> is a directory")
        }
    }
}


