package com.bedalton.log

import kotlin.js.JsExport


/**
 * Logging levels supported
 */
enum class LogLevel(val value: Int) {
    LOG_2(5),
    LOG_1(4),
    INFO(3),
    TRACE(3),
    WARN(2),
    ERROR(1);
}


/**
 * Short list of Log colors possible
 */
@JsExport
sealed class LoggerColor {
    object BLACK : LoggerColor()
    object RED : LoggerColor()
    object GREEN : LoggerColor()
    object YELLOW : LoggerColor()
    object BLUE : LoggerColor()
    object MAGENTA : LoggerColor()
    object CYAN : LoggerColor()
    object WHITE : LoggerColor()
}