package com.bedalton.creatures.genetics.parser

import com.bedalton.creatures.genetics.gene.GeneConstants.GENE_TYPE_ORGAN
import com.bedalton.creatures.genetics.gene.Gene
import com.bedalton.creatures.genetics.gene.OrganGene
import com.bedalton.io.bytes.ByteStreamReader

internal fun readOrgan(version: Int, reader: ByteStreamReader, geneIndex: Int): Gene {
    return when (val subtype = reader.uInt8()) {
        0 -> OrganGene.fromReader(version, GENE_TYPE_ORGAN, subtype, reader, geneIndex)
        else -> throw GenomeParseException("Failed to understand gene type: Organ(3)->[$subtype]")
    }
}

