@file:Suppress("unused", "MemberVisibilityCanBePrivate")

package com.bedalton.creatures.breed.render.support.pose

import com.bedalton.creatures.common.structs.GameVariant
import kotlin.js.JsExport
import kotlin.js.JsName

/**
 * Class to build a pose object by setting each part separately
 */
@JsExport
class PoseBuilder {
    private var variant: GameVariant

    @JsName("construct")
    constructor(variant: String, pose: Pose? = null) : this(GameVariant.fromString(variant)!!, pose)

    @JsName("constructWithoutPoseNoJS")
    constructor(variant: GameVariant) : this(variant, null)

    @JsName("constructNoJS")
    constructor(variant: GameVariant, pose: Pose?) {
        this.variant = variant
        this.setPose(pose)
    }

    private var headFacing: PoseFacing? = null
    private var head: Tilt? = null
    private var bodyFacing: PoseFacing? = null
    private var body: Tilt? = null
    private var leftThigh: Tilt? = null
    private var leftShin: Tilt? = null
    private var leftFoot: Tilt? = null
    private var rightThigh: Tilt? = null
    private var rightShin: Tilt? = null
    private var rightFoot: Tilt? = null
    private var leftUpperArm: Tilt? = null
    private var leftForearm: Tilt? = null
    private var rightUpperArm: Tilt? = null
    private var rightForearm: Tilt? = null
    private var tailBase: Tilt? = null
    private var tailTip: Tilt? = null
    private var mood: Mood? = null
    private var eyesClosed: Boolean? = null
    private var itLocation: PoseFacing? = null


    private fun setPose(pose: Pose?) {
        headFacing = pose?.headFacing
        head = pose?.head
        bodyFacing = pose?.bodyFacing
        body = pose?.body
        leftThigh = pose?.leftThigh
        leftShin = pose?.leftShin
        leftFoot = pose?.leftFoot
        rightThigh = pose?.rightThigh
        rightShin = pose?.rightShin
        rightFoot = pose?.rightFoot
        leftUpperArm = pose?.leftUpperArm
        leftForearm = pose?.leftForearm
        rightUpperArm = pose?.rightUpperArm
        rightForearm = pose?.rightForearm
        tailBase = pose?.tailBase
        tailTip = pose?.tailTip
        mood = pose?.mood
        eyesClosed = pose?.eyesClosed
        itLocation = pose?.itLocation
    }

    fun withHeadFacing(facing: PoseFacing?): PoseBuilder {
        headFacing = facing
        return this
    }

    fun withHead(tilt: Tilt?): PoseBuilder {
        head = tilt
        return this
    }

    @JsName("withMoodInt")
    fun withMood(int: Int): PoseBuilder {
        val mood = Mood.fromInt(int)
            ?: throw PoseException("Failed to locate mood with int value $int. Valid values are 0..4 for C1, 0..6 for C2,C3,DS and 0..11 for CV")
        return withMood(mood)
    }

    fun withMood(mood: Mood?): PoseBuilder {
        if (mood != null && !Mood.isValidForVariant(variant, mood)) {
            val moodName = mood.name.replaceFirstChar { it.uppercaseChar() }
            throw PoseException("Cannot set mood to $moodName; $moodName is not valid mood in ${variant.code}")
        }
        this.mood = mood
        return this
    }

    fun withEyesClosed(eyesClosed: Boolean?): PoseBuilder {
        this.eyesClosed = eyesClosed
        return this
    }

    fun withBody(tilt: Tilt?): PoseBuilder {
        body = tilt
        return this
    }

    fun withBodyFacing(facing: PoseFacing?): PoseBuilder {
        bodyFacing = facing
        return this
    }

    fun withLeftThigh(tilt: Tilt?): PoseBuilder {
        leftThigh = tilt
        return this
    }

    fun withLeftShin(tilt: Tilt?): PoseBuilder {
        leftShin = tilt
        return this
    }

    fun withLeftFoot(tilt: Tilt?): PoseBuilder {
        leftFoot = tilt
        return this
    }

    fun withRightThigh(tilt: Tilt?): PoseBuilder {
        rightThigh = tilt
        return this
    }

    fun withRightShin(tilt: Tilt?): PoseBuilder {
        rightShin = tilt
        return this
    }

    fun withRightFoot(tilt: Tilt?): PoseBuilder {
        rightFoot = tilt
        return this
    }

    fun withLeftUpperArm(tilt: Tilt?): PoseBuilder {
        leftUpperArm = tilt
        return this
    }

    fun withLeftForearm(tilt: Tilt?): PoseBuilder {
        leftForearm = tilt
        return this
    }

    fun withRightUpperArm(tilt: Tilt?): PoseBuilder {
        rightUpperArm = tilt
        return this
    }

    fun withRightForearm(tilt: Tilt?): PoseBuilder {
        rightForearm = tilt
        return this
    }

    fun withTailBase(tilt: Tilt?): PoseBuilder {
        tailBase = tilt
        return this
    }

    fun withTailTip(tilt: Tilt?): PoseBuilder {
        tailTip = tilt
        return this
    }

    fun withItLocation(direction: PoseFacing?): PoseBuilder {
        this.itLocation = direction
        return this
    }

    fun withPartPose(part: String, pose: String): PoseBuilder {
        if (part.isBlank()) {
            throw PoseException("Part string cannot blank and must be a single character 'a'..'n'")
        }

        if (part.trim().length != 1) {
            throw PoseException("Part string is expected to be 1 character 'a'..'n'. Found: '$part'")
        }

        val partChar = part[0].lowercaseChar();
        if (pose.isBlank() || pose.trim().length != 1) {
            throw PoseException(getPoseErrorMessage(partChar, pose))
        }
        var poseUpper = pose[0].uppercaseChar()
        var out = this

        if (partChar == 'a') {
            if (poseUpper == '4') {
                poseUpper = this.head?.int?.digitToChar() ?: PoseConstants.Tilt.STRAIGHT_CHAR
                out = out.withHeadFacing(PoseFacing.FRONT)
            } else if (poseUpper == '5') {
                poseUpper = this.head?.int?.digitToChar() ?: PoseConstants.Tilt.STRAIGHT_CHAR
                out = out.withHeadFacing(PoseFacing.BACK)
            } else {
                out = out.withHeadFacing(bodyFacing)
            }
        }

        val tilt = Tilt.fromChar(poseUpper)
            ?: throw PoseException(getPoseErrorMessage(partChar, pose))
        return out.withPartPoseInternal(partChar, tilt)
    }

    internal fun withPartPoseInternal(part: Char, pose: Tilt): PoseBuilder {
        val partLower = part.lowercaseChar()
        if (partLower !in 'a'..'n') {
            if (partLower == 'o' || partLower == 'p') {
                throw PoseException("Ear poses cannot be set manually")
            }
            if (partLower == 'q') {
                throw PoseException("Hair pose cannot be set manually")
            }
            throw PoseException("Invalid part char '$part'; Expected a part 'a'..'n'")
        }
        return when (part.lowercaseChar()) {
            'a' -> withHead(pose)
            'b' -> withBody(pose)
            'c' -> withLeftThigh(pose)
            'd' -> withLeftShin(pose)
            'e' -> withLeftFoot(pose)
            'f' -> withRightThigh(pose)
            'g' -> withRightShin(pose)
            'h' -> withRightFoot(pose)
            'i' -> withLeftUpperArm(pose)
            'j' -> withLeftForearm(pose)
            'k' -> withRightUpperArm(pose)
            'l' -> withRightForearm(pose)
            'm' -> withTailBase(pose)
            'n' -> withTailTip(pose)
            'o', 'p' -> throw PoseException("Ear poses are set automatically")
            'q' -> throw PoseException("Hair pose is set automatically")
            else -> throw PoseException("Invalid part char '$part'; Expected a part 'a'..'n'")
        }
    }

    fun build(): Pose {
        val default = Pose.defaultPose(variant)
        return Pose(
            variant = variant,

            // Head
            headFacing = headFacing ?: default.headFacing,
            head = head ?: default.head,
            mood = mood,
            eyesClosed = eyesClosed,

            // Body
            bodyFacing = bodyFacing ?: default.bodyFacing,
            body = body ?: default.body,

            // Left Leg
            leftThigh = leftThigh ?: default.leftThigh,
            leftShin = leftShin ?: default.leftShin,
            leftFoot = leftFoot ?: default.leftFoot,

            // Right Leg
            rightThigh = rightThigh ?: default.rightThigh,
            rightShin = rightShin ?: default.rightShin,
            rightFoot = rightFoot ?: default.rightFoot,

            // Left Arm
            leftUpperArm = leftUpperArm ?: default.leftUpperArm,
            leftForearm = leftForearm ?: default.leftForearm,

            // Right Arm
            rightUpperArm = rightUpperArm ?: default.rightUpperArm,
            rightForearm = rightForearm ?: default.rightForearm,

            // Tail
            tailBase = tailBase ?: default.tailBase,
            tailTip = tailTip ?: default.tailTip,

            // It
            itLocation = itLocation,
        )
    }

}

private fun getPoseErrorMessage(partChar: Char, pose: String): String {
    val range = when (partChar) {
        '0' -> "'3', '?', '!'"
        'a' -> "'5'"
        else -> "'3'"
    }
    val nonNullNonBlankText = if (pose.isEmpty()) {
        " non-null, not blank and"
    } else {
        ""
    }
    return "Part [$partChar] pose must be must be${nonNullNonBlankText} a single character: ['0'..$range, 'X]; Found: \"$pose\"";
}

fun PoseBuilder.withPartPose(part: Char, pose: Tilt): PoseBuilder {
    return withPartPoseInternal(part, pose)
}

fun PoseBuilder.withPartPose(part: Char, pose: Char): PoseBuilder {
    val tilt = Tilt.fromChar(pose)
        ?: throw PoseException(getPoseErrorMessage(part, pose.toString()))
    return withPartPoseInternal(part, tilt)
}