package com.bedalton.creatures.creature.common.core.structs

import kotlinx.serialization.SerialName
import kotlinx.serialization.Serializable
import kotlin.js.JsExport
import kotlin.js.JsName

@Serializable
@SerialName("ChemicalAmount")
@JsExport
data class ChemicalAmount(
    val chemical: Int = 0,
    val amount: Int = 0,
    val reverse: Boolean = false,
) {

    @JsName("constructWithFloat")
    constructor(chemical: Int, amount: Float, reverse: Boolean = false): this(
        chemical, (amount * 255).toInt(), reverse
    )

    val float: Float by lazy {
        amount / 255.0f
    }

    @JsName("withIntAmount")
    fun withAmount(newValue: Int): ChemicalAmount {
        return copy(
            amount = newValue
        )
    }

    @JsName("withFloatAmount")
    fun withAmount(amount: Float): ChemicalAmount {
        return copy(amount = (amount * 255.0).toInt())
    }

    fun withChemical(newValue: Int): ChemicalAmount {
        return copy(
            chemical = newValue
        )
    }
}


@JsExport
@SerialName("StimulusDriveAmount")
@Serializable
data class StimulusDrive(
    val drive: Int = 0,
    val amount: Int = 0,
    val silent: Boolean = false,
