    }

    @JsName("withIntAmount")
    fun withAmount(newValue: Int): StimulusDrive {
        return copy(
            amount = newValue
        )
    }

    @JsName("withFloatAmount")
    fun withAmount(amount: Float): StimulusDrive {
        return copy(amount = (amount * 255.0).toInt())
