package com.creaturesforge.application.ui.controls

import com.bedalton.common.util.ensureNotStartsWith
import com.bedalton.common.util.equalIgnoringOrder
import com.bedalton.common.util.isNotNullOrBlank
import com.bedalton.state.simple.Dispatch
import com.creaturesforge.application.state.*
import com.creaturesforge.application.state.ForgeState
import com.creaturesforge.application.state.ForgeStore
import com.creaturesforge.application.ui.html.optionsList
import kotlinx.browser.document
import kotlinx.browser.window
import org.w3c.dom.HTMLOptionElement
import org.w3c.dom.HTMLSelectElement


internal class EggSelect(private val select: HTMLSelectElement) {

    private lateinit var dispatch: Dispatch<FAction>

    private var eggs: Set<EggData> = emptySet()

    private var events = true

    init {
        select.onchange = change@{ e ->
            if (!events) {
                return@change e
            }
            onEggSelect()
        }

        ForgeStore.subscribe { state, dispatch ->
            this.dispatch = dispatch
            updateFromState(state)
        }
    }

    private fun updateFromState(state: ForgeState) {
        val oldEvents = events
        events = false
        setEggOptions(state.eggs.toSet())
        selectEgg(state.selectedEgg)
        events = oldEvents || events
    }

    private fun selectEgg(egg: EggData) {
        ensureHasEggs(setOf(egg))
        setSelectedValue(egg.id.toString())
    }

    private fun onEggSelect() {
        val eggIndex = select.value.toIntOrNull()
            ?: throw Exception("Egg select index is null")

        val egg = eggs.firstOrNull { it.id == eggIndex }
            ?: EggData()

        dispatch(SetSelectedEggAction(egg))
    }

    private fun setEggOptions(eggs: Set<EggData>) {
        if (this.eggs.equalIgnoringOrder(eggs)) {
            return
        }
        this.eggs = eggs
        val selected = select.value
        select.innerHTML = ""
        ensureHasEggs(eggs)
        setSelectedValue(selected)
    }

    private fun setSelectedValue(value: String) {
        select.value = value
    }

    private fun ensureHasEggs(slots: Set<EggData>) {

        if (this.select.asDynamic() == null) {
            window.alert("Breed slot select is null")
            return
        }

        val eggIds = eggs.map { it.id }

        val options = select.optionsList()
            .filter { it.value.toIntOrNull() in eggIds }
            .toMutableList()

        val represented = options.map { it.value.toIntOrNull() }

        val newEggs = slots
            .filter { it.id !in represented }
            .toSet()


        for (option in options) {
            val oldName = option.text
            val newName = eggs
                .first { it.id == option.value.toIntOrNull() }
                .displayName
                .ensureNotStartsWith(':')
                .trim()
            if (oldName != newName) {
                option.text = newName
            }
        }

        // Create new option
        for (egg in newEggs) {
            val option = createOption(egg)
            options.add(option)
        }

        options.sortBy {
            if (it.text.isNotNullOrBlank()) {
                "x${it.text.replace("\\s".toRegex(), "").lowercase()}"
            } else {
                "_"
            }
        }
        select.innerHTML = ""
        options.forEach(select::appendChild)
    }

    private fun createOption(egg: EggData): HTMLOptionElement {
        val option = (document.createElement("option") as HTMLOptionElement)
        option.value = egg.id.toString()
        option.innerText = egg
            .displayName
            .ensureNotStartsWith(':')
            .trim()
        return option
    }
}