package com.creaturesforge.application.state

import com.bedalton.common.util.formatted
import com.bedalton.log.Log
import com.bedalton.state.simple.Dispatch
import com.bedalton.state.simple.SimpleStore
import com.bedalton.state.simple.Unsubscribe
import com.bedalton.common.exceptions.rethrowCancellationException


internal object ForgeStore : SimpleStore<ForgeState, FAction>(
    initialState = ForgeState(virtual = false).ensureEgg(),
    reducers = getReducers(),
    middleware = getMiddleware(),
    onError = ::onError,
) {
    private lateinit var mDispatch: Dispatch<FAction>

    init {
        initStaticDispatcher()
    }

    fun dispatch(action: FAction) {
        mDispatch(action)
    }

    private fun initStaticDispatcher() {
        var unsubscribe: Unsubscribe? = null
        unsubscribe = subscribe { _, dispatch ->
            mDispatch = dispatch
            unsubscribe?.invoke()
            unsubscribe = null
        }
    }


}

private fun onError(action: String, e: Throwable) {
    e.rethrowCancellationException()
    Log.e("Store failure in $action;\n${e.formatted(true)}")
}