@file:Suppress("unused")

package com.bedalton.vfs

import com.bedalton.common.exceptions.IOException
import com.bedalton.common.util.PathUtil
import com.bedalton.common.util.isNotNullOrBlank


/**
 * Assert that a given path is both absolute and that it exists
 */
suspend fun FileSystem.assertIsAbsoluteAndExists(path: String, commonName: String = "File") {
    if (VfsSwitches.pathsMustBeAbsolute) {
        assertIsAbsolutePath(path, commonName)
    }
    if (!fileExists(path)) {
        throw FileNotFoundException(path, "$commonName does not exists; Path: \"$path\"")
    }
}

/**
 * Assert that a given path is absolute, exists and points to a directory
 */
suspend fun FileSystem.assertIsValidDirectory(path: String, commonName: String = "Path") {
    if (VfsSwitches.pathsMustBeAbsolute) {
        assertIsAbsoluteAndExists(path, commonName)
    }
    if (!isDirectory(path)) {
        throw NotADirectoryException("$commonName is not a directory; Path: \"$path\"")
    }
}

/**
 * Assert that a path is absolute, exists and points to a file
 */
suspend fun FileSystem.assertIsValidFile(path: String, commonName: String = "Path") {
    if (VfsSwitches.pathsMustBeAbsolute) {
        assertIsAbsoluteAndExists(path, commonName)
    }
    if (isDirectory(path)) {
        throw NotAFileException(path, "$commonName is not a file but a directory; Path: \"$path\"")
    }
}

/**
 * Asserts that a path is absolute
 */
fun assertIsAbsolutePath(path: String, commonName: String? = null) {
    if (!VfsSwitches.pathsMustBeAbsolute) {
        return
    }
    if (!PathUtil.isAbsolute(path) && !isResourcePath(path)) {
        throw if (commonName.isNotNullOrBlank()) {
            PathNotAbsoluteException("$commonName path \"$path\" is not absolute")
        } else {
            PathNotAbsoluteException(path)
        }
    }
}

/**
 * Checks if a path points to a file
 */
suspend fun FileSystem.isFile(path: String): Boolean {
    return fileExists(path) && !isDirectory(path)
}

/**
 * An exception to mark that a path was not absolute
 */
open class PathNotAbsoluteException(
    path: String,
    message: String? = null,
    throwable: Throwable? = null
): FileException(message(path, message), path, throwable) {
    companion object {
        private fun message(path: String, message: String?): String {
            return message ?: "Path \"$path\" is not absolute"
        }
    }
}

/**
 * Exception for path based errors
 */
open class FileException(
    val file: String,
    message: String,
    throwable: Throwable? = null
): IOException(message, throwable)


/**
 * Exception thrown when expecting a file, but finding something
 * Could be thrown if file does not exist, or points to a directory (maybe even symlink of file)
 */
open class NotAFileException(
    file: String,
    message: String? = null,
    throwable: Throwable? = null
): FileException(file, message(file, message), throwable) {
    companion object {
        private fun message(path: String, message: String?): String {
            return message ?: "Path \"$path\" is not a file"
        }
    }
}

/**
 * Exception thrown when expecting a directory, but finding something else
 * Could be thrown if directory does not exist, points to a file, or possibly points to a symlink
 */
open class NotADirectoryException(
    file: String,
    message: String? = null,
    throwable: Throwable? = null
): FileException(file, message(file, message), throwable) {
    companion object {
        private fun message(path: String, message: String?): String {
            return message ?: "Path \"$path\" is not a directory"
        }
    }
}