@file:Suppress("unused")

package com.bedalton.common.ast.collectors

import com.bedalton.common.ast.structs.PositionImpl
import com.bedalton.common.ast.structs.RangeWithIndex
import com.bedalton.common.ast.structs.RangeWithIndexImpl
import org.antlr.v4.kotlinruntime.CommonToken
import org.antlr.v4.kotlinruntime.ParserRuleContext
import org.antlr.v4.kotlinruntime.Token

fun CommonToken.toRange(
    offsetIndex: Int? = null,
    offsetLine: Int? = null,
    offsetColumn: Int? = null,
): RangeWithIndex {
    val startIndex = startIndex
    val startLine = line
    val startColumn = charPositionInLine
    val stopIndex = stopIndex
    val lines = text.orEmpty().split("\n")
    val endLine = startLine + lines.size - 1
    val stopColumn = if (lines.size > 1)
        lines.last().length
    else
        startColumn + text.orEmpty().length
    return RangeWithIndexImpl(
        startIndex = startIndex + (offsetIndex ?: 0),
        endIndex = stopIndex + (offsetIndex ?: 0),
        start = PositionImpl(
            line = startLine + (offsetLine ?: 0),
            character = startColumn + (offsetColumn ?: 0)
        ),
        end = PositionImpl(
            line = endLine + (offsetLine ?: 0),
            character = stopColumn + (if (startLine == endLine) (offsetColumn ?: 0) else 0)
        )
    )
}

private infix fun ParserRuleContext.to(other: ParserRuleContext): IntRange {
    val commandStart = start!!.startIndex
    val commandEnd = other.stop!!.stopIndex
    return commandStart..commandEnd
}

private infix fun ParserRuleContext.until(other: ParserRuleContext): IntRange {
    val commandStart = start!!.startIndex
    val commandEnd = other.stop!!.stopIndex
    return commandStart until commandEnd
}

private infix fun Token.to(other: Token): IntRange {
    val commandStart = startIndex
    val commandEnd = other.stopIndex
    return commandStart..commandEnd
}

private infix fun Token.until(other: Token): IntRange {
    val commandStart = startIndex
    val commandEnd = other.stopIndex
    return commandStart until commandEnd
}