internal class CommandWalker(
    private val lib: CaosLib,
    private val originalText: String,
    private val tokens: Array<CaosParserItem?>,
    private val checkCancelled: () -> Unit,
) {
    private val variant: String by lazy { lib.variantCode }
    private val closestByVariant = getClosestByVariantFilter(lib.variantCode)
    val commandCalls: Array<CommandCall> get() = mCommands.toTypedArray()
    val looseTokens: Array<CaosParserItem> get() = loose.toTypedArray()
    val comments = mutableListOf<CaosParserItem.Comment>()
    val caos2Comments = mutableListOf<CaosParserItem.Caos2Comment>()
    val equalityStatements
        get() = mCommands
            .filter { it.type == ValueType.CONDITION.value }
            .map {

                val start = it.arguments.getOrNull(0)?.textRange ?: it.textRange
                val last = it.arguments.lastOrNull()?.textRange ?: it.textRange
                val range = RangeWithIndexImpl(
                    startIndex = start.startIndex,
                    endIndex = last.endIndex + 1,
                    start = start.start,
                    end = last.end
                )
                EqualityStatement(
                    textRange = range,
                    first = it.arguments.getOrNull(0),
                    second = it.arguments.getOrNull(2),
                    eqToken = it.arguments.getOrNull(1)?.parserItem as? CaosParserItem.EqOp,
                    it.containingCommand,
                    it.parameter ?: CONDITION_PARAMETER,
                    originalText.substring(range.startIndex, range.endIndex).trim()
                )
            }
            .sortedBy { it.startIndex }
            .toTypedArray()

    val equalityStatementRanges
        get() = getEqualityStatementRanges(equalityStatements, tokens)
            .toTypedArray()

    private val stops = StopCommands[lib.variantCode]!!
    private val mCommands: MutableList<CommandCall> = mutableListOf()
    private val working: MutableList<CommandCall> = mutableListOf()
    private val waiting: MutableList<VariantCaosParameter> = mutableListOf()
    private val loose: MutableList<CaosParserItem> = mutableListOf()
    private var commandTokens: Array<Pair<Int, CommandToken>> = arrayOf()
    private var line = 0
    private var columnInLine: Int = 0
    private var textPositionInFile = 0
    private var tokenIndex = 0
    private var newline = true

    init {
        try {
            walk()
        } catch (_: ParseCancelledException) {

        }
        try {
            commandCalls.forEach(CommandCall::finalizeProperties)
        } catch (_: Exception) {

        }
        //Log.i(TAG, "Tokens: ${tokens.joinToString(" ") { it.value.toString() }}")
    }

    private fun walk() {
        val lastIndex = tokens.lastIndex
        while (tokenIndex <= lastIndex) {
            val token = tokens[tokenIndex]
            if (token == null) {
                Log.i("Token $tokenIndex is null ")
                continue
            }
            if (working.lastOrNull()?.done == false && line != token.textRange.start.line && token is CommandToken && !nextCommandValid(
                    token
                )
            ) {
                waiting.clear()
                working.clear()
                line = token.textRange.start.line
                if (popTokens()) {
                    continue
                }
            }
            if (token !is CaosParserItem.EqJoin) {
                while (waiting.firstOrNull() == EQ_JOIN) {
                    waiting.removeFirst()
                }
            }
            if (token is CommandToken) {
                if (waiting.firstOrNull()?.typeId == ValueType.TOKEN.value) {
                    val altered = CaosParserItem.TokenVal(
                        token.textRange,
                        value = token.value
                    )
                    tokens[tokenIndex] = altered
                    pushArgument(altered)
                } else {
                    pushCommandToken(token)
                }
            } else if (token is CaosParserItem.TokenVal) {
                when (waiting.firstOrNull()?.typeId) {
                    ValueType.TOKEN.value -> {
                        pushArgument(token)
                    }
                    ValueType.PICT_DIMENSION.value -> {
                        val altered = CaosParserItem.DdePictVal(
                            token.textRange,
                            value = Pair(token.value[0].code, token.value.getOrNull(2)?.code ?: -1),
                            token.text
                        )
                        tokens[tokenIndex] = altered
                        pushArgument(altered)
                    }
                    else -> {
                        pushArgument(token)
                        loose.add(token)
                    }
                }
            } else if (token is CaosParserItem.EqJoin) {
                if (waiting.firstOrNull() == EQ_JOIN) {
                    //waiting.removeFirstOrNull()
                    if (working.firstOrNull()?.command?.command == EQ_COMMAND_TOKEN) {
                        working.removeFirst()
                        done()
                    } else if (working.firstOrNull()?.done == true) {
                        done()
                    }
                    waiting.addAll(conditionParameters)
                    pushCommand(
                        createConditionCommandCall(
                            working.firstOrNull()?.let { CommandReference(it, mCommands.lastIndex) },
                            waiting.firstOrNull() ?: CONDITION_PARAMETER,
                            token.textRange
                        )
                    )
                } else {
                    loose.add(token)
                }
            } else if (token is CaosParserItem.Comment) {
                comments.add(token)
            } else if (token is CaosParserItem.Caos2Comment) {
                caos2Comments.add(token)
            } else if (token is CaosParserItem.IntVal && waiting.firstOrNull()?.typeId == ValueType.TOKEN.value) {
                val altered = CaosParserItem.TokenVal(
                    token.textRange,
                    token.text
                )
                tokens[tokenIndex] = altered
                pushArgument(altered)
            } else {
                if (!popTokens()) {
                    val altered: CaosParserItem = if (token is CaosParserItem.ByteStringVal) {
                        // If type is ByteString, but a string is expected
                        // Convert to C1 string
                        if (waiting.firstOrNull()?.typeId == ValueType.C1_STRING.value || waiting.firstOrNull()?.typeId == ValueType.STRING.value) {
                            CaosParserItem.C1eStringVal(
                                token.textRange,
                                value = token.value
                            )
                        } else {
                            token
                        }
                    } else if (token is CaosParserItem.C1eStringVal) {
                        // If type is C1 String, but a byte-string or animation is expected
                        // Convert to byte string
                        if (waiting.firstOrNull()?.typeId != ValueType.C1_STRING.value && BYTE_STRING_REGEX.matches(token.value.trim())) {
                            CaosParserItem.ByteStringVal(
                                token.textRange,
                                value = token.value
                            )
                        } else {
                            token
                        }
                    } else {
                        token
                    }
                    if (altered != token) {
                        tokens[tokenIndex] = altered
                    }
                    pushArgument(altered)
                }
            }
            newline = token.textRange.end.line != line
            line = token.textRange.end.line
            columnInLine = token.textRange.end.character
            textPositionInFile = token.textRange.endIndex
            tokenIndex++
            checkCancelled()
        }
        knock(null)
        finalize()
    }

    private fun popTokens(): Boolean {
        if (commandTokens.isEmpty())
            return false
        val temp = commandTokens.copyOf()
        val length = temp.size
        for (i in 0 until length) {
            commandTokens = emptyArray()
            for (j in i until length) {
                if (pushCommandToken(temp[j].second)) {
                    tokenIndex -= j - 1
                    commandTokens = emptyArray()
                    for (k in 0 until j) {
                        loose.add(temp[k].second)
                    }
                    val startToken = temp[j].second
                    line = startToken.textRange.end.line
                    columnInLine = startToken.textRange.end.character
                    return true
                }
            }
        }
        commandTokens = emptyArray()
        loose.addAll(temp.map { it.second })
        return false
    }

    private fun nextCommandValid(token: CommandToken): Boolean {
        val commandTokens = commandTokens.copyOf()
        /*
         * Clear unmatched tokens when they are on different lines. May cause false parsing errors,
         * But it would be weird to split command words onto different lines
         */
        if (token.textRange.start.line != line && commandTokens.isNotEmpty()) {
            //Log.i(TAG, "Tokens left on line change. Clearing tokens: [${commandTokens.joinToString { it.second.value }}]")
            loose.addAll(commandTokens.map { it.second })
            return false
        }
        return pushCommandTokenToList(token, false) != null
    }

    private fun pushCommandToken(token: CommandToken): Boolean {
        // Clear pending if it is a for sure start of a new command
        knock(token)
        /*
         * Clear unmatched tokens when they are on different lines. May cause false parsing errors,
         * But it would be weird to split command words onto different lines
         */
        if (token.textRange.start.line != line && commandTokens.isNotEmpty()) {
            //Log.i(TAG, "Tokens left on line change. Clearing tokens: [${commandTokens.joinToString { it.second.value }}]")
            loose.addAll(commandTokens.map { it.second })
            commandTokens = emptyArray()
        }

        // Get command if any from library
        val (newCommandTokens, command, tokensUsed) = pushCommandTokenToList(token, true)
            ?: return false

        commandTokens = newCommandTokens

        val commandType = getWaitingCommandType()

        val startToken = commandTokens.first().second.textRange
        val endToken = commandTokens[tokensUsed - 1].second.textRange
        val commandTokenRange = RangeWithIndexImpl(
            startIndex = startToken.startIndex,
            endIndex = endToken.endIndex,
            start = startToken.start,
            end = endToken.end,
            parserIndex = token.parserIndex
        )
        val theseTokens = if (tokensUsed < commandTokens.size) {
            commandTokens.sliceArray(0 until tokensUsed)
        } else {
            commandTokens
        }

        // Remove tokens matched to command
        commandTokens = if (tokensUsed < commandTokens.size) {
            commandTokens.sliceArray(tokensUsed until commandTokens.size)
        } else {
            arrayOf()
        }

        val parameter = waiting.firstOrNull()
        // Add command and parameters to waiting and working
        val commandJS = command.toVariantCommand(variant)
        val theseTokensArray = theseTokens.map { it.second }.toTypedArray()
        val commandCall = CommandCall(
            type = if (commandType == CommandType.LVALUE) ValueType.VARIABLE.value else command.returnTypeId,
            command = commandJS,
            tokenTextRange = commandTokenRange,
            inVariant = command.variants.indexOf(variant) >= 0,
            textRange = commandTokenRange,
            tokens = theseTokensArray,
            parameter = parameter,
            inEqualityExpression = working.firstOrNull()?.type == ValueType.CONDITION.value || parameter == EQ_JOIN || parameter == EQ_OP || parameter == EQ_FIRST_PARAM || parameter == EQ_SECOND_PARAM,
            containingCommand = working.firstOrNull()?.let { CommandReference(it, mCommands.lastIndex) },
            callType = commandType
        )
        //Log.i(TAG, "Variant:$variant, [${command.command}](${command.variants}); InVariant: ${commandCall.inVariant}")
        if (command.command == "SETV") {
            val nextToken = (tokens.getOrNull(tokenIndex + 1) as? CommandToken)?.value?.uppercase()
            if (nextToken in leftValueNoVar) {
                val altered: CommandCall = commandCall.copy(
                    command = commandJS.copy(
                        parameters = commandJS.parameters.dropLast(1).toTypedArray()
                    )
                )
                pushCommand(altered)
                addParameters(altered.command.parameters, commandTokenRange)
                return true
            }
        }

        pushCommand(commandCall)
        if (commandJS.parameters.isEmpty()) {
            done()
        } else {
            //Log.i(TAG, "Parameters for: ${commandJS.command} == [${commandJS.parameters.joinToString { it.name }}]")
            addParameters(commandJS.parameters, commandTokenRange)
        }
        return true
    }

    private fun pushCommandTokenToList(token: CommandToken, write: Boolean): Triple<Array<Pair<Int, CommandToken>>, CaosCommand, Int>? {
        val setTokens = if (write) {
            { value: Array<Pair<Int, CommandToken>> ->
                this.commandTokens = value
                value
            }
        } else {
            { value: Array<Pair<Int, CommandToken>> ->
                value
            }
        }
        var commandTokens: Array<Pair<Int, CommandToken>> = if (write) commandTokens else commandTokens.copyOf()
        // Append this new token to the running list
        commandTokens = setTokens(setTokens(commandTokens + Pair(token(token.value.lowercase()), token)))
        while (commandTokens.size > 3) {
            //Log.i(TAG, "Too many tokens in waiting pool... removing: '${commandTokens.first().second.value}'")
            val badCommand = commandTokens.first().second
            loose.add(badCommand)
            commandTokens = setTokens(commandTokens.sliceArray(1 until commandTokens.size))
        }

        // Get command type based on what is going on
        val commandType = getWaitingCommandType()

        // Find a matching command for tokens
        val commandSearchTokens = commandTokens.map { it.first }.toIntArray()

        // Command bias for commands where there are two commands with the same token
        val bias: ValueType = waiting.firstOrNull()
            ?.typeId
            ?.let { typeId -> ValueType.fromIntValue(typeId) }
            ?: ValueType.ANY

        // Get command if any from library
        val (command, tokensUsed) = lib[commandType][commandSearchTokens, bias]
        // Wait until all available token slots have been filled to make sure
        // fallback command does not return value before actual variant can
            ?: getFallback(commandType, commandSearchTokens)
            ?: return null

        return Triple(commandTokens, command, tokensUsed)
    }

    private fun addParameters(
        parameters: Array<VariantCaosParameter>,
        textRange: RangeWithIndex,
    ) {
        for (parameter in parameters.reversed()) {
            waiting.insertFront(parameter)
            if (parameter.typeId == ValueType.CONDITION.value) {
                pushCommand(
                    createConditionCommandCall(
                        working.firstOrNull()?.let { CommandReference(it, mCommands.lastIndex) },
                        waiting.firstOrNull() ?: CONDITION_PARAMETER,
                        textRange
                    )
                )
                waiting.insertFront(conditionParameters)
            }
        }
        //Log.i(TAG, "Parameters: [${waiting.joinToString { it.formatted }}]")
    }


