    private fun getWaitingCommandType(): CommandType {
        return when {
            waiting.isEmpty() -> CommandType.COMMAND
            waiting.firstOrNull()?.typeId == ValueType.VARIABLE.value -> CommandType.LVALUE
            else -> CommandType.RVALUE
        }
    }

    private fun done() {
        val token = tokens[tokenIndex]
        if (token == null) {
            Log.e("Token is null for done()")
            return
        }
        textPositionInFile = token.textRange.endIndex
        while (true) {
            val commandCall = working.removeFirstOrNull()
                ?: return
            if (!commandCall.done) {
                working.insertFront(commandCall)
                break
            }
        }
    }

    private fun knock(item: CommandToken?) {
        //Log.i(TAG, "Item: ${item?.value}(${token(item?.value ?: ",,,,")}) in Stops? ${token(item?.value ?: ",,,,") in stops}")
        if (item == null || item.token in stops && (working.isNotEmpty() || waiting.isNotEmpty())) {
//            Log.i(TAG, "Knocking all tokens at: '${item?.value}'")
            working.clear()
            waiting.clear()
            if (!popTokens()) {
                loose.addAll(commandTokens.map { it.second })
            }
        }
    }

    private fun pushCommand(commandCall: CommandCall) {
        mCommands.add(commandCall)
        val parameter = waiting.removeFirstOrNull()
        if (parameter != null) {
            //Log.i(TAG, "Command ${commandCall.command.command} is for parameter: ${parameter.name}")
            working.firstOrNull()?.let { workingCommand ->
                workingCommand.arguments += commandCall
                done()
            }
        } else if (!commandCall.command.isCommand) {
            Log.e(TAG, "L/RValue command '${commandCall.command.command}' pushed without parameter")
        } else {
            //Log.i(TAG, "Pushing command ${commandCall.command.command}")
        }
        working.insertFront(commandCall)
    }

    private fun pushArgument(item: CaosParserItem) {
        //Log.i(TAG, "Waiting: [${waiting.joinToString { it.formatted }}]")
        val parameter = waiting.removeFirstOrNull()
        if (parameter == null) {
            loose.add(item)
            return
        }

        val command: CommandCall = working.firstOrNull()
            ?: throw Exception("Parameters found in waiting without working command: [${waiting.joinToString { it.name }}]")

        command.arguments += ParserItemArgument(
            textRange = item.textRange,
            parameter = parameter,
            type = item.actualType,
            text = item.text,
            inEqualityExpression = working.firstOrNull()?.type == ValueType.CONDITION.value || parameter == EQ_JOIN || parameter == EQ_OP || parameter == EQ_FIRST_PARAM || parameter == EQ_SECOND_PARAM,
            parserItem = item,
            containingCommand = working.firstOrNull()?.let { CommandReference(it, mCommands.lastIndex) }
        ) as Argument
        //Log.i(TAG, "Command [${command.command.command}] Arguments: [${command.arguments.joinToString { it.text }}]")
        if (waiting.firstOrNull() == EQ_JOIN) {
            if (tokens.getOrNull(tokenIndex + 1) !is CaosParserItem.EqJoin) {
                waiting.removeFirstOrNull()
                if (working.firstOrNull()?.command?.command == EQ_COMMAND_TOKEN) {
                    done()
                } else {
                    done()
                }
            }
        } else if (command.done) {
            done()
        }
    }

    /**
     * Gets a fallback command from the other variants
     * Used to help find where a command is used out of variant
     * This helps parser recover
     */
    private fun getFallback(commandType: CommandType, commandSearchTokens: IntArray): Pair<CaosCommand, Int>? {
        var tempTokens = commandSearchTokens.copyOf()
        var result: Pair<CaosCommand, Int>? = null
        var i = 1
        while (tempTokens.size < 3) {
            result = lib[commandType][commandSearchTokens]
            if (result != null)
                break
            else {
                val next = tokens.getOrNull(tokenIndex + i++)
                if (next !is CommandToken || next.value.length != 4) {
                    break
                }
                tempTokens += token(next.value)
            }
        }
        if (result != null) {
            tokenIndex += i
        }

        return CaosLibs.commands(commandSearchTokens).filterByType(commandType)?.let { (commands, _) ->
            if (commands.isNotEmpty()) {
                closestByVariant(commands)?.let { command ->
                    Pair(command, commandSearchTokens.size)
                }
            } else {
                null
            }
        }
    }

    private fun finalize() {
        for (i in mCommands.indices) {
            val commandCall = mCommands[i]
            // Calculate new end if any
            val trueEnd = endEnd(commandCall)
            if (trueEnd != null) {
                commandCall.textRange = (commandCall.textRange as RangeWithIndexImpl).copy(
                    endIndex = trueEnd.endIndex,
                    end = trueEnd.end
                )
            }
        }
    }

    private fun endEnd(commandCall: CommandCall): RangeWithIndex? {
        val lastArgument = commandCall
            .arguments
            .nullIfEmpty()
            ?.maxByOrNull { it.endIndex }
            ?: return null
        return if (lastArgument !is CommandCall) {
            lastArgument.textRange
        } else {
            endEnd(lastArgument) ?: lastArgument.textRange
        }

    }


    companion object {
        private const val TAG = "CommandWalker"

        fun getEqualityStatementRanges(equalityStatementIn: Array<EqualityStatement>, tokens: Array<CaosParserItem?>): List<RangeWithIndex> {
            // Sort statements
            val equalityStatements = equalityStatementIn.sortedBy { it.startIndex }

            // If no statements, nothing to return
            if (equalityStatements.isEmpty()) {
                return emptyList()
            }

            // Sort Items and get only joins
            val joins = tokens
                .filterNotNull()
                .sortedBy { it.startIndex }
                .filterIsInstance<CaosParserItem.EqJoin>()
                .toMutableList()

            // List of calculated ranges
            val out = mutableListOf<RangeWithIndex>()

            // Index in eq statements list
            var i = 0


            while (i < equalityStatements.size) {
                val statement = equalityStatements[i++]

                // get the furthest eq item
                var last = statement.second
                    ?: statement.eqToken
                    ?: statement.first


                // If no eq item, skip add default range and continue
                if (last == null) {
                    out.add(statement.textRange)
                    continue
                }

                // Make sure joins come after the current eq statement
                // If not, the EQ statement is loose somewhere
                var join = joins.firstOrNull()
                while (join != null && join.startIndex < last.endIndex) {
                    joins.removeFirst()
                    join = joins.firstOrNull()
                }

                // If there are no joins left, simply add the eq statement's range
                if (join == null) {
                    out.add(statement.textRange)
                    continue
                }

                // Create starting range
                var range = statement.textRange

                // Loop through consecutive join+eq statement pairs
                join@while (join != null && last != null && isConsecutive(last, join)) {
                    joins.removeFirst()
                    val next = equalityStatements[i++]
                    range = statement.textRange + next.textRange
                    last = next.second ?: next.eqToken ?: next.first
                            ?: break@join
                    join = joins.firstOrNull()
                        ?: break@join
                }
                out.add(range)
            }
            return out
        }
    }

}



private fun isConsecutive(first: CaosItem, second: CaosItem): Boolean {
    val firstIndex = when(first) {
        is CaosParserItem -> first.parserIndexEnd
        is ParserItemArgument -> first.parserIndexEnd
        is CommandCall -> first.parserIndexEnd
        is EqualityStatement -> first.parserIndexEnd
        else -> first.textRange.parserIndex
    }
        ?: return false
    val secondIndex = when(second) {
        is CaosParserItem -> second.parserIndexStart
        is ParserItemArgument -> second.parserIndexStart
        is CommandCall -> second.parserIndexStart
        is EqualityStatement -> second.parserIndexStart
        else -> second.textRange.parserIndex
    }
        ?: return false
    return firstIndex + 1 == secondIndex
}


private val leftValueNoVar = listOf("PUHL", "PUPT", "CLS2")

private val BYTE_STRING_REGEX = "\\[\\s*(\\d\\s*)*R?\\s*\\]".toRegex()

private val NUMBER_REGEX = "^\\d+$".toRegex()
