expect suspend fun FileSystem.globFiles(pattern: String, path: String? = null): List<String>


suspend fun getAbsoluteGlobPath(fileSystem: FileSystem?, path: String?, pattern: String): String {

    val partial: String = (if (PathUtil.isAbsolute(pattern) || fileSystem?.isVirtualPathInVirtualFS(pattern) == true) {

        val normalized = pattern.replace("\\\\([^*\\[\\]])".toRegex(), "/$1")
        val parts = normalized
            .split('/')

        Log.iIf(LOG_COMMON_FILES_TESTING) { "Parts[${parts.size}] = [${parts.joinToString()}]" }
        val indexOfSplit = parts.indexOfFirst { it.contains('*') || it.contains('[') || it.contains(']') }
        parts.subList(0, indexOfSplit)
            .joinToString(""+pathSeparator(pattern))

    } else if (path != null) {
        // Path is specified
        if (!VfsSwitches.pathsMustBeAbsolute || PathUtil.isAbsolute(path) || fileSystem?.isVirtualPathInVirtualFS(path) == true) {
            // Path is absolute, so use it
            if (path.normalized().endsWith(pattern.normalized())) {
                path.substring(0, path.length - pattern.length)
            } else {
                path
            }
        } else {
            // Path is blank, so set to null so that it can be overwritten
            null
        }
    } else {
        null
    }) ?: throw PathNotAbsoluteException("Path: $path; Pattern: $pattern", "Cannot glob files without absolute path")

//    if (fileSystem != null && !fileSystem.accept(partial)) {
//        throw IOException("Cannot glob files outside allowed sources roots")
//    }

    return partial
}

internal const val MAX_GLOBBED_FILES = 4000
internal val wildcardsRegex = "((?:^|[\\\\/])[*]+([\\\\/]|\$))".toRegex()

/**
 * A very manual search through all possible paths matching up until this point
 */
internal suspend fun globPathsManual(fileSystem: FileSystem, pattern: String, path: String?): List<String> {
    // Format actual path using current working directory if path is null or not absolute
    val actualPath: String = getAbsoluteGlobPath(
        fileSystem,
        path?.expandTildeIfNecessary(),
        pattern.expandTildeIfNecessary()
    )

    val searchedSoFar = Pointer(0)
    val (globRegex, minimalFiles) = getGlobRegexOrMinimalFiles(
        pattern,
        actualPath,
    ) { globPattern ->
        globMinimal(fileSystem, globPattern, searchedSoFar)
    }

    minimalFiles?.let {
        return it
    }

    // Get the children recursively
    return fileSystem.getChildren(actualPath, false).orEmpty().mapAsync { aPath ->
        globFilesRecursive(fileSystem, aPath, globRegex!!, searchedSoFar)
    }.flatten()
}

private suspend fun globMinimal(fileSystem: FileSystem, pattern: String, searchedSoFar: Pointer<Int>): List<String> {
    if (pattern.matches("^[^*]*[\\\\/]\\*$".toRegex())) {
        Log.iIf(LOG_COMMON_FILES_TESTING) { "Globing simple $pattern" }
        val directory = pattern.substringBefore('*')
        return fileSystem.getChildrenNonRecursive(directory)?.filter { fileSystem.isFile(it) } ?: emptyList()
    }

    // Create the regex to test all paths against
    val globRegex = globToRegex(pattern, true, setOf(RegexOption.IGNORE_CASE))

    // Check if variable path component is only at the end
    val lastMatch = "^([^*]*[\\\\/])(([^\\\\/]|\\\\[\\[\\]\$^.])*[*]([^\\\\/]|\\\\[\\[\\]\$^.])*)\$".toRegex()
    val matchesLast = lastMatch.matchEntire(pattern)
        ?.groupValues
        ?.drop(1)

    // The glob variable is only at the end, so we can search ver simply
    if (matchesLast != null) {
        Log.iIf(LOG_COMMON_FILES_TESTING) { "Glob pattern only in last path component: ${pattern}; Searching in: ${matchesLast[0]}" }
        return fileSystem.getChildrenNonRecursive(matchesLast[0])
            ?.filter {
                Log.iIf(LOG_COMMON_FILES_TESTING) { "Does glob match <$it>? ${globRegex.matches(it) }" }
                globRegex.matches(it) && fileSystem.isFile(it)
            }
            ?: emptyList()
    }


    // Split this path on the first glob pattern component
    val split = pattern.split(wildcardsRegex, limit = 2)

    // Glob children in path before wildcard, and search within those children
    Log.iIf(LOG_COMMON_FILES_TESTING) { "Globbing files parent: ${split[0]}; Remainder: ${split[1]} " }
    return fileSystem.getChildrenNonRecursive(split[0]).orEmpty().mapAsync(Dispatchers.Unconfined) { childPath ->

        Log.iIf(LOG_COMMON_FILES_TESTING) { "Globbing single layer: ${split[0]}; Child: $childPath" }
        // If child is a directory, search its children
        if (fileSystem.isDirectory(childPath)) {
            Log.iIf(LOG_COMMON_FILES_TESTING) { "Globbing child's children as this should be '*'; Child: $childPath" }

            fileSystem.getChildrenNonRecursive(childPath).orEmpty().mapAsync {
                globSimple(fileSystem, it, globRegex, split[1], searchedSoFar)
            }.flatten()

        } else if (globRegex.matches(childPath)) { // check if child file matches regex
            listOf(childPath)
        } else {
            emptyList()//globSimple(fileSystem, split[0], globRegex, split[1], searchedSoFar)
        }
    }.flatten()
}

private suspend fun globFilesRecursive(fileSystem: FileSystem, path: String, pattern: Regex, searchedSoFar: Pointer<Int>): List<String> {
    searchedSoFar.value++
    if (searchedSoFar.value > MAX_GLOBBED_FILES) {
        throw IOException("Glob cannot handle so many files; Max: $MAX_GLOBBED_FILES")
    }
    Log.iIf(LOG_COMMON_FILES_TESTING) { "Globbing: $path" }
    return when {
        fileSystem.isDirectory(path) -> {
            fileSystem.getChildren(path, false).orEmpty().mapAsync(BackgroundDispatcher) {
                globFilesRecursive(fileSystem, it, pattern, searchedSoFar)
            }.flatten()
        }

        pattern.matches(path) && fileSystem.isFile(path) -> {
            Log.iIf(LOG_COMMON_FILES_TESTING) { "Path matches: $path; Pattern: ${pattern.pattern}" }
            listOf(path)
        }

        else -> {
            Log.iIf(LOG_COMMON_FILES_TESTING) { "No Match: Path: $path; Pattern: ${pattern.pattern}" }
            emptyList()
        }
    }
}

private suspend fun globSimple(fileSystem: FileSystem, path: String, pattern: Regex, remaining: String?, searchedSoFar: Pointer<Int>): List<String>  {
    searchedSoFar.value++
    if (searchedSoFar.value > MAX_GLOBBED_FILES) {
        throw IOException("Glob cannot handle so many files; Max: $MAX_GLOBBED_FILES")
    }
    Log.iIf(LOG_COMMON_FILES_TESTING) { "Globbing: $path; Pattern: ${pattern.pattern}; With remaining: $remaining" }
    return if (fileSystem.isDirectory(path)) {
        val others = if (remaining != null) {
            Log.iIf(LOG_COMMON_FILES_TESTING) { "Globbing Child directory: $path" }

            val split = remaining.split(wildcardsRegex, limit = 2)

            Log.iIf(LOG_COMMON_FILES_TESTING) { "Glob Split: [${split.joinToString()}]" }

            if (split.size == 1) {
                fileSystem.getChildrenNonRecursive(path)?.filter {
                    pattern.matches(it)
                } ?: emptyList()
            } else {
                val nextDirectory = PathUtil.combine(path, split[0])
                globSimple(fileSystem, nextDirectory, pattern, split[1], searchedSoFar)
            }
        } else {
            emptyList()
        }
        if (path.matches(pattern) && fileSystem.isFile(path)) {
            others + path
        } else {
            others
        }
    } else if (pattern.matches(path) && fileSystem.isFile(path)) {
        Log.iIf(LOG_COMMON_FILES_TESTING)  { "Path matches: $path; Pattern: ${pattern.pattern}" }
        listOf(path)
    } else {
        Log.iIf(LOG_COMMON_FILES_TESTING)  { "No Match: Path: $path; Pattern: ${pattern.pattern}" }
        emptyList()
    }
}

internal fun globToRegex(pattern: String, @Suppress("SameParameterValue") global: Boolean = false, options: Set<RegexOption> = setOf()): Regex {
    // The regexp we are building, as a string.
    var inGroup = false
    val out = StringBuilder()
    if (!global) {
        out.append('^')
    }
    var i = 0
    val length = pattern.length
    val lastIndex = length - 1
    while (i < length) {
        when (val c = pattern[i]) {
            '/',
            '$',
            '^',
            '+',
            '.',
            '(',
            ')',
            '=',
            '!',
            '|',
            -> out.append('\\').append(c)
            '\\' -> out.append("\\\\")
            '?' -> out.append('.')
            '[', ']' -> out.append(c)
            '{' -> {
                inGroup = true
                out.append('(')
            }

            '}' -> {
                inGroup = false
                out.append(')')
            }

            ',' -> {
                if (inGroup) {
                    out.append('|')
                } else {
                    out.append('\\').append(c)
                }
            }

            '*' -> {
                // Move over all consecutive "*"'s.
                // Also store the previous and next characters
                val prevChar = if (i > 0) pattern[i - 1] else null
                var starCount = 1
                while (i < lastIndex && pattern[i + 1] == '*') {
                    starCount++
                    i++
                }
                val nextChar = if (i < lastIndex) pattern[i + 1] else null
                val isGlobStar = starCount > 1 &&
                        (prevChar == null || prevChar == '/') &&
                        (nextChar == null || nextChar == '/')

                if (isGlobStar) {
                    out.append("((?:[^/]*(?:\\/|$))*)")
                    i++ // move over the "/"
                } else {
                    // it's not a globstar, so only match one path segment
                    out.append("([^/]*)")
                }
            }

            else -> out.append(c)
        }
        i++
    }
    if (!global) {
        out.append('$')
    }
    return out.toString().toRegex(options)
}

val globChars = listOf('[', ']', '{', '}', '*')

internal suspend fun getGlobRegexOrMinimalFiles(
    pattern: String,
    actualPath: String,
    globMinimal: suspend (globPattern: String) -> List<String>
): Pair<Regex?, List<String>?>  {
    val filePattern = if (pattern.startsWith(actualPath)) {
        pattern.substring(actualPath.length)
    } else {
        pattern
    }

    Log.iIf(LOG_COMMON_FILES_TESTING) { "GlobPathsManual: Path: $actualPath; Pattern: $filePattern" }

    // Make sure this is not the root path
    actualPath.appendPathSeparator().let {
        if (it == "//" || it == "\\" || "^[a-zA-Z]:[\\\\/]$".toRegex().matches(it)) {
            throw IOException("Cannot search from root path: $it")
        }
    }

    // Log output for initial testing
    // Make sure pattern is the last part of the pattern string
    val globPattern = PathUtil.combine(actualPath, filePattern)

    // Check if this has expanded paths
    val doubleStarRegex = "((?:^|[\\\\/])[*]{2,}([\\\\/]|\$))".toRegex()

    // If path is not double expanded, make a simpler search
    if (!doubleStarRegex.containsMatchIn(globPattern)) {
        Log.iIf(LOG_COMMON_FILES_TESTING) { "Doing simple glob on $globPattern" }
        return Pair(null, globMinimal(globPattern))
    }

    Log.iIf(LOG_COMMON_FILES_TESTING) { "Doing complex glob on $globPattern; Match: ${doubleStarRegex.containsMatchIn(globPattern)}" }
    // Create regex from glob pattern
    val globRegex = globToRegex(globPattern, true, setOf(RegexOption.IGNORE_CASE))
    Log.iIf(LOG_COMMON_FILES_TESTING) { "Path: $actualPath; Pattern: $pattern; GlobPattern: $globPattern" }
    return Pair(globRegex, null)
}