@file:Suppress("NON_EXPORTABLE_TYPE")

package com.bedalton.creatures.agents.pray.compiler.pray

import com.bedalton.common.structs.HasRange
import com.bedalton.common.util.PathUtil
import com.bedalton.common.util.ensureEndsWith
import com.bedalton.creatures.agents.pray.compiler.data.InlineFile
import com.bedalton.creatures.agents.pray.compiler.data.Tag
import com.bedalton.creatures.agents.pray.compiler.data.TextValue
import kotlin.js.JsExport
import kotlin.js.JsName

@JsExport
sealed class PrayValidationError : HasRange {

    abstract val message: String
    abstract override val lineNumber: Int
    abstract override val startIndex: Int
    abstract override val endIndex: Int
    abstract val fullFilePath: String

    open val formatWithLineNumber get() = errorMessageWithFileName(fullFilePath)

    open fun formatWithLineNumberRelativeTo(rootFile: String): String {
        val fileName = fileRelativePath(rootFile)
        return errorMessageWithFileName(fileName)
    }

    protected open fun fileRelativePath(rootFile: String): String {

        val rootDirectory = PathUtil.getDirname(rootFile)
            ?.ensureEndsWith(PathUtil.getPathSeparatorChar(rootFile))
            ?: ""

        return if (fullFilePath.lowercase().startsWith(rootDirectory.lowercase())) {
            if (fullFilePath.length <= rootDirectory.length) {
                // Should be impossible?
                PathUtil.getFileName(fullFilePath) ?: fullFilePath
            } else {
                fullFilePath.substring(rootDirectory.length)
            }
        } else {
            PathUtil.getFileName(fullFilePath) ?: fullFilePath
        }
    }

    private fun errorMessageWithFileName(fileName: String): String {
        return "$message @ $fileName Line #$lineNumber"
    }

    data class InvalidLanguage(
        val language: String?,
        override val message: String,
        override val lineNumber: Int,
        override val startIndex: Int,
        override val endIndex: Int,
        override val fullFilePath: String
    ) : PrayValidationError()


    open class BlockValidationError(
        @JsName("blockTag")
        open val blockTag: TextValue,
        @JsName("blockName")
        open val blockName: TextValue,
        override val lineNumber: Int,
        override val startIndex: Int,
        override val endIndex: Int,
        override val message: String,
        override val fullFilePath: String
    ) : PrayValidationError()

    open class GeneralError(
        override val lineNumber: Int,
        override val startIndex: Int,
        override val endIndex: Int,
        override val message: String,
        override val fullFilePath: String
    ) : PrayValidationError()


    open class NoBlockError(
        override val lineNumber: Int,
        override val startIndex: Int,
        override val endIndex: Int,
        override val message: String,
        override val fullFilePath: String,
    ) : PrayValidationError()

    data class DuplicateTagError(
        override val blockTag: TextValue,
        override val blockName: TextValue,
        val duplicateTag: Tag<*>,
        override val message: String,
        override val lineNumber: Int = duplicateTag.tagRange.lineNumber,
        override val startIndex: Int = duplicateTag.tagRange.startIndex,
        override val endIndex: Int = duplicateTag.tagRange.endIndex,
        override val fullFilePath: String,
    ) : BlockValidationError(
        blockTag = blockTag,
        blockName = blockName,
        lineNumber = duplicateTag.lineNumber,
        startIndex = startIndex,
        endIndex = endIndex,
        message = message,
        fullFilePath = fullFilePath
    )

    data class DependencyError(
        override val blockTag: TextValue,
        override val blockName: TextValue,
        override val message: String,
        override val lineNumber: Int,
        override val startIndex: Int,
        override val endIndex: Int,
        override val fullFilePath: String,
    ) : BlockValidationError(
        blockTag = blockTag,
        blockName = blockName,
        lineNumber = lineNumber,
        startIndex = startIndex,
        endIndex = endIndex,
        message = message,
        fullFilePath = fullFilePath
    )

    data class BlockNotImplementedError(
        override val lineNumber: Int,
        override val blockTag: TextValue,
        override val blockName: TextValue,
        override val startIndex: Int,
        override val endIndex: Int,
        override val fullFilePath: String,
    ) : BlockValidationError(
        blockTag = blockTag,
        blockName = blockName,
        lineNumber = lineNumber,
        startIndex = startIndex,
        endIndex = endIndex,
        message = "$blockTag PRAY blocks have not been implemented",
        fullFilePath = fullFilePath
    )

    data class InlineFileError(
        val inlineFile: InlineFile,
        val range: HasRange,
        override val message: String,
        override val fullFilePath: String,
    ) : PrayValidationError() {
        override val lineNumber: Int get() = range.lineNumber
        override val startIndex: Int get() = range.startIndex
        override val endIndex: Int get() = range.endIndex
    }

    data class CommandError(
        val command: String,
        val commandRange: HasRange,
        val errorRange: HasRange,
        override val message: String,
        override val fullFilePath: String,
    ) : PrayValidationError() {
        override val lineNumber: Int get() = errorRange.lineNumber
        override val startIndex: Int get() = errorRange.startIndex
        override val endIndex: Int get() = errorRange.endIndex
    }

    data class SyntaxError(
        override val lineNumber: Int,
        override val startIndex: Int,
        override val endIndex: Int,
        val errorText: String?,
        override val message: String,
        override val fullFilePath: String,
    ) : PrayValidationError()

    data class DuplicateAgentNameError(
        val blockTag: String,
        val blockName: String,
        override val lineNumber: Int,
        override val startIndex: Int,
        override val endIndex: Int,
        override val fullFilePath: String,
    ) : PrayValidationError() {
        override val message: String
            get() = "Duplicate agent name '$blockName'"
    }
}