package com.creaturesforge.application.state

import com.bedalton.common.util.PathUtil
import com.bedalton.common.util.equalIgnoringOrder
import com.bedalton.state.simple.Dispatch
import com.bedalton.vfs.FileSystem
import com.creaturesforge.application.util.asThrowable
import com.creaturesforge.application.util.isAttFile
import com.bedalton.common.exceptions.rethrowCancellationException

internal suspend fun attFileMiddleware(
    state: ForgeState,
    action: FAction,
    dispatch: Dispatch<FAction>,
) {

    val isAttFilesAction = action is SetProjectRootAction ||
            action is SetAttRootAction ||
            action is SetAttFilesAction ||
            action is RequestRefreshAction ||
            action is RequestAttFileListRefresh ||
            action is SetEggModeAction

    if (!isAttFilesAction) {
        return
    }

    val hasRoot = state.attRoot != null ||
            state.projectFolder != null ||
            action is SetAttRootAction ||
            action is SetProjectRootAction ||
            action is SetEggModeAction

    if (!hasRoot) {
        return
    }
    dispatchAttRootActions(state, action, dispatch)
}

private suspend fun dispatchAttRootActions(
    state: ForgeState,
    action: FAction,
    dispatch: Dispatch<FAction>,
) {
    val fs = vfs

    val root = getAttRoot(fs, state, action)
        ?: return

    dispatchSetAttRootActionIfNeeded(state, action, root, dispatch)

    dispatchSetAttFilesActionIfNeeded(fs, state, action, root, dispatch)

}

private fun dispatchSetAttRootActionIfNeeded(
    state: ForgeState,
    action: FAction,
    attRoot: String,
    dispatch: Dispatch<FAction>,
) {
    if (action is SetAttRootAction) {
        return
    }

    if (state.attRoot == attRoot) {
        return
    }

    dispatch(SetAttRootAction(attRoot))
}

private suspend fun dispatchSetAttFilesActionIfNeeded(
    fs: FileSystem,
    state: ForgeState,
    action: FAction,
    attRoot: String,
    dispatch: Dispatch<FAction>,
) {
    if (action is SetAttFilesAction) {
        return
    }

    if (action is SetAttRootAction && action.path == attRoot && state.attFiles != null) {
        return
    }

    val files = getAttFilesInRoot(fs, attRoot)

    if (state.attFiles != null && state.attFiles.equalIgnoringOrder(files)) {
        return
    }

    dispatch(SetAttFilesAction(files))
}

internal suspend fun getAttFilesInRoot(fs: FileSystem, attRoot: String): List<String> {
    return fs.listAllFiles(attRoot, false, filter = ::isAttFile)
}

private suspend fun getAttRoot(fs: FileSystem?, state: ForgeState, action: FAction): String? {

    if (action is SetAttRootAction) {
        return action.path
    }

    val projectRoot = when {
        action is SetProjectRootAction -> action.path
        action is SetEggModeAction && action.eggMode == EggMode.SINGLE -> state.projectFolder
        state.attRoot != null -> return state.attRoot
        state.projectFolder != null -> state.projectFolder
        else -> null
    } ?: return null

    val fsNotNull = fs ?: vfs

    return getAttFolder(fsNotNull, projectRoot)
}

private suspend fun getAttFolder(fs: FileSystem, projectFolder: String): String {
    val bodyDataPath = PathUtil.combine(projectFolder, "Body Data")
    return try {
        if (fs.fileExists(bodyDataPath) && fs.isDirectory(bodyDataPath)) {
            bodyDataPath
        } else {
            projectFolder
        }
    } catch (e: dynamic) {
        asThrowable(e).rethrowCancellationException()
        projectFolder
    }
}
