import com.bedalton.common.util.PathUtil
import com.bedalton.creatures.agents.pray.compiler.CompileResult
import com.bedalton.creatures.agents.pray.compiler.PrayCompilerTask
import com.bedalton.creatures.agents.pray.compiler.compilePrayFileToBytes
import com.bedalton.creatures.agents.pray.compiler.pray.PrayInputException
import com.bedalton.vfs.UnscopedFileSystem
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.GlobalScope
import kotlinx.coroutines.asPromise
import kotlinx.coroutines.async
import kotlin.js.Promise

@JsExport
actual class JsPrayCompilerTask actual constructor(
    inputFile: String,
    outputDirectory: String,
    pure: Boolean,
    private var subFoldersOnly: Boolean
) : PrayCompilerTask(inputFile, outputDirectory, pure) {


    @Suppress("NON_EXPORTABLE_TYPE", "unused")
    actual fun compile(): Promise<CompileResult> {
        val inputDirectory = PathUtil.getSelfOrParentDirectory(inputFile)
            ?: throw PrayInputException("Failed to determine input file parent directory")
        val fs = UnscopedFileSystem()
        return GlobalScope.async {
            compilePrayFileToBytes(CoroutineScope(coroutineContext), fs, this@JsPrayCompilerTask, subFoldersOnly = subFoldersOnly)
        }.asPromise()
    }

}