@file:Suppress("UNUSED_PARAMETER")

package com.creaturesforge.application.state

import com.bedalton.common.util.PathUtil
import com.bedalton.common.util.className
import com.bedalton.common.util.formatted
import com.bedalton.log.LOG_PROGRESS
import com.bedalton.log.Log
import com.bedalton.log.LoggerColor
import com.bedalton.log.iWith
import com.creaturesforge.application.ui.message
import com.creaturesforge.application.util.LOG_STATUS
import kotlinx.coroutines.CancellationException
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Job
import kotlinx.coroutines.launch

@Suppress("unused")
private val lastException: Pair<Double, CompileEggFailedAction>? = null

internal fun onCompileEggAction(action: CompileEggAction) {
    when (action) {
        is CompileEggStartedAction -> onCompileEggStartedAction(action)
        is CompileEggCompletedAction -> {
            CoroutineScope(Job()).launch {
                try {
                    onCompileEggCompletedAction(action)
                } catch (e: Exception) {
                    Log.e("Failed to run middleware on onCompileEggCompletedAction(); ${e.formatted(true)}")
                }
            }
        }
        is CompileEggFailedAction -> onCompileEggFailedAction(action)
        is CompileEggCancelledAction -> onCompileEggCancelledAction(action)
        is CompileEggProgress -> return
    }
}

private suspend fun onCompileEggCompletedAction(action: CompileEggCompletedAction) {
    val outputFile = PathUtil.getLastPathComponent(action.outputFile) ?: action.outputFile
    val compiled = vfs.fileExists(action.outputFile)
    if (compiled) {
        Log.iWith(LOG_STATUS, false, LoggerColor.GREEN) {
            "Compiled egg to $outputFile"
        }
    } else {
        val error = "Output egg file \"$outputFile\" does not exist after write"
        onCompileEggFailedAction(CompileEggFailedAction(error))
    }
}

private fun onCompileEggFailedAction(action: CompileEggFailedAction) {
    if (action.throwable is CancellationException || action.throwable is kotlin.coroutines.cancellation.CancellationException) {
        return
    }
    Log.e { "Failed to compile egg with error: ${action.throwable?.className}; ${action.message}${(action.throwable ?: Exception()).stackTraceToString()}" }
    message("Failed to compile egg with error: ${action.message}") {
        this.title = "Compilation Error"
        this.type = "error"
    }
}

private fun onCompileEggCancelledAction(action: CompileEggCancelledAction) {
    Log.iWith(LOG_STATUS, false) { "Cancelled compilation" }
}

private fun onCompileEggStartedAction(action: CompileEggStartedAction) {
    Log.iWith(LOG_PROGRESS, false) { "Starting compile" }
}