package com.bedalton.common.ast.formatter

import com.bedalton.common.ast.collectors.NewLineParseTreeItem
import com.bedalton.common.ast.collectors.ParseTreeItem
import com.bedalton.common.ast.collectors.SpaceParseTreeItem


fun ParseTreeItem.isWhitespace(): Boolean {
    return this is NewLineParseTreeItem || this is SpaceParseTreeItem
}