package com.bedalton.creatures.agents.pray.compiler

/**
 * Find script tags
 */
internal val SCRIPT_TAG_REGEX = "^Script\\s+(\\d+)$".toRegex(RegexOption.IGNORE_CASE)

internal val SCRIPT_COUNT_TAG_REGEX = "Script\\s+Count".toRegex()

/**
 * Finds all tags that will be replaced by generated tags in CAOS2Pray
 */
internal val GENERATED_TAGS_REGEX =
    "^(Script\\s+(\\d+|Count))|(Dependency\\s+(Count|(Category\\s+)?\\d+))$".toRegex(RegexOption.IGNORE_CASE)

/**
 * Find dependency declaration tags
 */
internal val DEPENDENCY_TAG_REGEX = "^Dependency\\s+(\\d+)$".toRegex(RegexOption.IGNORE_CASE)


/**
 * Finds tags for dependency categories
 */
internal val DEPENDENCY_CATEGORY_REGEX = "^Dependency\\s+Category\\s+(\\d+)$".toRegex(RegexOption.IGNORE_CASE)

internal val DEPENDENCY_COUNT_REGEX = "^Dependency\\s+Count\\s*$".toRegex(RegexOption.IGNORE_CASE)

/**
 * Finds all tags that have to do with dependencies
 */
internal val DEPENDENCY_DECLARATION_TAGS_REGEX =
    "^(Dependency\\s+Category|Dependency)\\s+(\\d+)$|^Dependency\\s+Count$".toRegex(RegexOption.IGNORE_CASE)

internal val REMOVER_SCRIPT_REGEX = "^Remove\\s+Script$".toRegex(RegexOption.IGNORE_CASE)


internal val NEWLINE_REGEX = "\\r?\\n".toRegex()