package com.bedalton.common.ast.serialization

import com.bedalton.common.ast.structs.HasRange
import com.bedalton.common.ast.structs.HasRangeImpl
import com.bedalton.common.ast.structs.RangeWithIndex
import kotlinx.serialization.KSerializer
import kotlinx.serialization.SerializationException
import kotlinx.serialization.descriptors.SerialDescriptor
import kotlinx.serialization.descriptors.buildClassSerialDescriptor
import kotlinx.serialization.encoding.CompositeDecoder
import kotlinx.serialization.encoding.Decoder
import kotlinx.serialization.encoding.Encoder

object HasRangeSerializer : KSerializer<HasRange> {
    override val descriptor: SerialDescriptor by lazy {
        buildClassSerialDescriptor("HasRange") {
            element("textRange", RangeSerializer.descriptor)
        }
    }

    override fun deserialize(decoder: Decoder): HasRange {
        val obj = decoder.beginStructure(descriptor)
        var textRange: RangeWithIndex? = null
        while (true) {
            when (val index = obj.decodeElementIndex(descriptor)) {
                0 -> textRange = obj.decodeSerializableElement(descriptor, index, RangeWithIndexSerializer)
                CompositeDecoder.DECODE_DONE -> break
                else -> error("Unexpected index: $index")
            }
        }
        obj.endStructure(descriptor)
        if (textRange == null) {
            throw SerializationException("Missing textRange in HasRange")
        }
        return HasRangeImpl(textRange)
    }

    override fun serialize(encoder: Encoder, value: HasRange) {
        val obj = encoder.beginStructure(descriptor)
        obj.encodeSerializableElement(descriptor, 0, RangeSerializer, value.textRange)
        obj.endStructure(descriptor)
    }

}