package com.bedalton.creatures.caos.formatter

import com.bedalton.common.ast.formatter.isWhitespace
import com.bedalton.common.ast.structs.RangeWithIndexImpl
import com.bedalton.common.ast.structs.end
import com.bedalton.common.ast.structs.start
import com.bedalton.creatures.caos.collectors.CaosParserItem
import kotlin.math.max
import kotlin.math.min



internal fun combine(first: CaosParserItem.NewLine, second: CaosParserItem.NewLine): CaosParserItem.NewLine {
    val firstText: String
    val secondText: String
    val min = if (first.textRange.startIndex < second.textRange.startIndex) {
        firstText = first.text
        secondText = second.text
        first.start
    } else {
        firstText = second.text
        secondText = first.text
        second.start
    }
    val max = if (first.textRange.endIndex < second.textRange.endIndex) {
        first.end
    } else {
        second.end
    }
    return CaosParserItem.NewLine(
        textRange = RangeWithIndexImpl(
            start = min,
            end = max,
            startIndex = min(first.textRange.startIndex, second.textRange.startIndex),
            endIndex = max(first.textRange.endIndex, second.textRange.endIndex),
        ),
        firstText + secondText
    )
}

fun CaosParserItem.isComment(): Boolean {
    return this is CaosParserItem.Comment || this is CaosParserItem.Caos2Comment
}

fun CaosParserItem?.isWhitespaceOrComment(): Boolean {
    return this?.isWhitespace() == true || this?.isComment() == true
}
