@file:Suppress("NON_EXPORTABLE_TYPE", "unused")

package com.bedalton.creatures.genetics.genome

import com.bedalton.creatures.common.structs.GameVariant
import com.bedalton.creatures.common.structs.isC2e
import com.bedalton.creatures.genetics.gene.Gene
import kotlinx.serialization.SerialName
import kotlinx.serialization.Serializable
import kotlinx.serialization.json.Json
import kotlin.js.JsExport
import kotlin.js.JsName

@JsExport
@Serializable
@SerialName("Genome")
data class Genome(
    // @ProtoNumber(1)
	@SerialName("version")
	val version: Int,
    // @ProtoNumber(2)
	@SerialName("genes")
	val genes: Array<Gene>,
    // @ProtoNumber(3)
	@SerialName("original_size")
	val originalSize: Int? = null
): Iterable<Gene> {

    val size: Int by lazy {
        genes.size
    }

    val geneCount: Int get() = size

    operator fun get(index: Int): Gene {
        return genes[index]
    }

    fun genesOfType(type: Int, subType: Int): Array<Gene> {
        return genes.filter { it.geneType == type && it.geneSubType == subType }
            .toTypedArray()
    }

    fun toJSON(): String {
        return json.encodeToString(serializer(), this)
    }

    @JsName("variantReturningC3OnC2e")
    fun variant(): GameVariant {
        return variant(GameVariant.C3)
    }

    @JsName("variantWithC2eConcreteVariant")
    fun variant(c2eVariant: GameVariant): GameVariant = when (version) {
        C1_VERSION -> GameVariant.C1
        C2_VERSION -> GameVariant.C2
        else -> if (c2eVariant.isC2e) {
            c2eVariant
        } else {
            throw Exception("Genome.variant() expects c2eVariant to be a C2e variant; Found: ${c2eVariant.code}")
        }
    }

    override fun iterator(): Iterator<Gene> {
        return genes.iterator()
    }

    override fun equals(other: Any?): Boolean {
        if (this === other) return true
        if (other !is Genome) return false

        if (version != other.version) return false
        if (!genes.contentEquals(other.genes)) return false
        if (originalSize != other.originalSize) return false

        return true
    }

    override fun hashCode(): Int {
        var result = version
        result = 31 * result + genes.contentHashCode()
        result = 31 * result + (originalSize ?: 0)
        return result
    }

    companion object {
        const val C1_VERSION = 1
        const val C2_VERSION = 2
        const val C2E_VERSION = 3

        internal val json by lazy {
            Json { ignoreUnknownKeys = true }
        }
    }
}
