package com.creaturesforge.application.util

import kotlinx.serialization.json.Json

internal val json = Json {
    prettyPrint = true
    ignoreUnknownKeys = true
    encodeDefaults = true
    explicitNulls = true
}

internal val jsonNoDefaults = Json {
    prettyPrint = false
    ignoreUnknownKeys = true
    encodeDefaults = false
    explicitNulls = false
}