package com.bedalton.creatures.caos.validation.internal

import com.bedalton.common.ast.structs.*
import com.bedalton.common.util.orElse
import com.bedalton.creatures.caos.collectors.CaosParserItem
import com.bedalton.creatures.caos.libs.CaosVariant
import com.bedalton.creatures.caos.libs.ErrorTypes


internal fun addWhitespaceErrors(
    caosVariant: CaosVariant,
    items: Array<CaosParserItem>,
    whitespaceItems: Array<CaosParserItem>,
    errors: MutableList<CaosParserItem.ErrorVal>,
) {
    if (caosVariant.isOld) {
        annotateWhitespaceC1e(
            items,
            whitespaceItems,
            errors
        )
    } else {
        annotateWhitespaceC2e(whitespaceItems, errors)
    }
}

private fun annotateWhitespaceC1e(
    items: Array<CaosParserItem>,
    whitespaceItems: Array<CaosParserItem>,
    errors: MutableList<CaosParserItem.ErrorVal>,
) {

    val itemsSorted = (items + whitespaceItems)
        .sortedBy { it.startIndex }

    val whitespacePositional = itemsSorted
        .mapIndexedNotNull { i, item ->
            if (item is CaosParserItem.WhitespaceItem) {
                Pair(i, item)
            } else {
                null
            }
        }

    val whitespaceErrors = whitespacePositional
        .mapNotNull { (i, item) ->
            annotateWhitespaceC1e(i, item, itemsSorted)
        }

    errors.addAll(whitespaceErrors)
}

private fun annotateWhitespaceC1e(
    i: Int,
    item: CaosParserItem.WhitespaceItem,
    items: List<CaosParserItem>,
): CaosParserItem.ErrorVal? {
    val before = if (i > 0) items[i - 1] else null
    val newlineBefore = before?.endLine.orElse(0) < item.startLine
    val after = if (i + 1 < items.size) items[i + 1] else null
    val newlineAfter = after?.endLine.orElse(item.endLine) > item.endLine
    return when {
        newlineAfter && item is CaosParserItem.Spaces -> CaosParserItem.ErrorVal(
            item.textRange,
            message = "Trailing whitespace is not allowed",
            type = ErrorTypes.WHITESPACE_ERROR,
            text = item.value
        )

        !newlineBefore && item is CaosParserItem.Spaces && item.value.length > 1 -> CaosParserItem.ErrorVal(
            item.textRange,
            message = "Only one space or comma allowed",
            type = ErrorTypes.WHITESPACE_ERROR,
            text = item.value
        )

        else -> null
    }
}

private fun annotateWhitespaceC2e(
    whitespaceItems: Array<CaosParserItem>,
    errors: MutableList<CaosParserItem.ErrorVal>,
) {
    val spaces = whitespaceItems
        .filterIsInstance<CaosParserItem.Spaces>()

    for (item in spaces) {
        val startIndex = item.startIndex
        val startLine = item.startLine
        val startCharacter = item.startCharacter
        val text = item.value
        for ((i, char) in text.withIndex()) {
            val error = annotateCommaC2e(i, startLine, startCharacter, startIndex, char)
                ?: continue
            errors.add(error)
        }
    }
}

private fun annotateCommaC2e(
    i: Int,
    startLine: Int,
    startCharacter: Int,
    startIndex: Int,
    char: Char,
): CaosParserItem.ErrorVal? {
    if (char != ',') {
        return null
    }
    val startPosition = PositionImpl(
        line = startLine,
        character = startCharacter + i
    )
    val endPosition = PositionImpl(
        line = startLine,
        character = startCharacter + i + 1
    )
    val range = RangeWithIndexImpl(
        start = startPosition,
        end = endPosition,
        startIndex = startIndex + i,
        endIndex = startIndex + i + 1
    )
    return CaosParserItem.ErrorVal(
        textRange = range,
        message = "Commas are allowed in C1e variants only",
        type = ErrorTypes.WHITESPACE_ERROR,
        text = ","
    )
}
