package com.bedalton.creatures.caos.validation.internal

import com.bedalton.common.ast.structs.RangeWithIndexImpl
import com.bedalton.common.ast.structs.empty
import com.bedalton.creatures.caos.collectors.Argument
import com.bedalton.creatures.caos.collectors.CaosParserItem
import com.bedalton.creatures.caos.collectors.CommandCall
import com.bedalton.creatures.caos.collectors.ConditionCommand
import com.bedalton.creatures.caos.libs.CaosVariant
import com.bedalton.creatures.caos.libs.ErrorTypes
import com.bedalton.creatures.caos.libs.ValueType
import com.bedalton.creatures.caos.libs.like


private val caos2ScriptDelimiters = "iscr|rscr".toRegex(RegexOption.IGNORE_CASE)


internal fun addCommandErrors(
    variant: CaosVariant,
    isCaos2: Boolean,
    commandCalls: Array<CommandCall>,
    errors: MutableList<CaosParserItem.ErrorVal>,
    checkCancelled: () -> Unit,
) {
    for (commandCall in commandCalls) {
        collectTypeErrors(commandCall, errors, checkCancelled)
        collectIncompleteCommandErrors(commandCall, errors, checkCancelled)
        outOfVariantCommandErrors(commandCall, isCaos2, errors, checkCancelled)
        collectOutOfVariantParameterErrors(variant, commandCall, errors, checkCancelled)
    }
}

private fun collectTypeErrors(
    call: CommandCall,
    errors: MutableList<CaosParserItem.ErrorVal>,
    checkCancelled: () -> Unit,
) {
    checkCancelled()
    for (i in 0 until call.arguments.size) {
        val argument = call.arguments[i]
        val parameter = call.command.parameters.getOrNull(i)
            ?: continue
        val parameterType = ValueType.fromIntValue(parameter.typeId)
        val argumentType = ValueType.fromIntValue(argument.type)
        if (parameterType like argumentType) {
            continue
        }
        val error = CaosParserItem.ErrorVal(
            argument.textRange,
            message = ErrorFormatter.typeMismatchError(
                call.command.command,
                parameter,
                actualType = argumentType.simpleName
            ),
            type = ErrorTypes.TYPE_ERROR,
            text = argument.text
        )
        errors.add(error)
    }
}

private fun outOfVariantCommandErrors(
    call: CommandCall,
    isCaos2: Boolean,
    errors: MutableList<CaosParserItem.ErrorVal>,
    checkCancelled: () -> Unit,
) {
    checkCancelled()
    if (call.inVariant) {
        return
    }
    if (isCaos2 && caos2ScriptDelimiters.matches(call.command.command)) {
        return
    }

    errors.add(
        CaosParserItem.ErrorVal(
            textRange = call.tokenTextRange,
            message = ErrorFormatter.outOfVariantError(
                call.command.command,
                ErrorFormatter.formatVariants(call.command.variants)
            ),
            type = ErrorTypes.OUT_OF_VARIANT,
            call.text
        )
    )
}


private fun collectIncompleteCommandErrors(
    call: CommandCall,
    errors: MutableList<CaosParserItem.ErrorVal>,
    checkCancelled: () -> Unit,
) {
    checkCancelled()
    if (call.arguments.size > call.command.parameters.size) {
        return
    }
    if (call.done) {
        return
    }
    if (call.missingParameters.size == 1 && call.command == ConditionCommand) {
        return
    }
    val range = if (call.arguments.isEmpty()) {
        call.tokenTextRange.let { if (it.empty()) call.textRange else it }
    } else {
        call.arguments.last().textRange.let { end ->
            RangeWithIndexImpl(
                startIndex = end.endIndex,
                endIndex = end.endIndex,
                start = end.end,
                end = end.end
            )
        }
    }
    val missingParameterString =
        call.missingParameters.joinToString { parameter -> "${parameter.name} (${parameter.typeName})" }
    val error = CaosParserItem.ErrorVal(
        textRange = range,
        message = "${call.command.command} is missing parameters [${missingParameterString}] (Index:${range.startIndex}, Line:${range.start.line},Column:${range.start.character})",
        type = ErrorTypes.INCOMPLETE_COMMAND_ERROR,
        text = call.text
    )
    errors.add(error)
}


private fun collectOutOfVariantParameterErrors(
    variant: CaosVariant,
    call: CommandCall,
    errors: MutableList<CaosParserItem.ErrorVal>,
    checkCancelled: () -> Unit,
) {
    checkCancelled()
    for (i in 0 until call.arguments.size) {
        val argument = call.arguments[i]
        val parameter = call.command.parameters.getOrNull(i)
            ?: continue
        val parameterType = ValueType.fromIntValue(parameter.typeId)
        val argumentType = ValueType.fromIntValue(argument.type)
        annotateByteStringVariantError(variant, argument, parameterType, argumentType, errors, checkCancelled)
    }
}


private fun annotateByteStringVariantError(
    variant: CaosVariant,
    argument: Argument,
    parameterType: ValueType,
    argumentType: ValueType,
    errors: MutableList<CaosParserItem.ErrorVal>,
    checkCancelled: () -> Unit,
) {
    checkCancelled()

    if (argument is CommandCall) {
        return
    }

    if (parameterType != ValueType.ANIMATION && parameterType != ValueType.BYTE_STRING) {
        return
    }

    if (argumentType != ValueType.ANIMATION && argumentType != ValueType.BYTE_STRING) {
        return
    }

    val textWithoutBrackets = argument.text.trim(' ', '[', ']').uppercase()

    val error = if (variant.isOld && textWithoutBrackets.contains(" ")) {
        CaosParserItem.ErrorVal(
            argument.textRange,
            "Animation strings cannot contain spaces in [C1, C2] variants",
            ErrorTypes.OUT_OF_VARIANT,
            argument.text,
            argumentType.value,
        )
    } else if (variant.isNew && textWithoutBrackets.endsWith('R')) {
        CaosParserItem.ErrorVal(
            argument.textRange,
            message = "Repeat char 'R' is invalid in CV+ variants. Use 255 instead",
            type = ErrorTypes.OUT_OF_VARIANT,
            text = argument.text,
            actualType = argumentType.value
        )
    } else {
        return
    }

    errors.add(error)
}