@file:Suppress("unused")
package com.bedalton.common.util

/**
 * Format a single precision decimal to a given number of places
 */
actual fun Float.toFixed(decimalPlaces:Int): String = this.asDynamic().toFixed(decimalPlaces) as String

/**
 * Format double precision number to a given number of places
 */
actual fun Double.toFixed(decimalPlaces: Int) : String = this.asDynamic().toFixed(decimalPlaces) as String

/**
 * Format a javascript number to a given number of places
 */
internal fun Number.fixed(decimalPlaces: Int) : String = this.toDouble().fixed(decimalPlaces)

/**
 * Compare an int to a JavaScript number
 */
operator fun Byte.compareTo(i: Number): Int {
    return this.compareTo(i.toByte())
}

/**
 * Compare an int to a JavaScript number
 */
operator fun Int.compareTo(i: Number): Int {
    return this.compareTo(i.toInt())
}

/**
 * Compare a long to a JavaScript number
 */
operator fun Long.compareTo(i: Number): Int {
    return this.compareTo(i.toLong())
}

/**
 * Compare a float to a JavaScript number type
 */
operator fun Float.compareTo(i: Number): Int {
    return this.compareTo(i.toFloat())
}

/**
 * Compare a double to a JavaScript number type
 */
operator fun Double.compareTo(i: Number): Int {
    return this.compareTo(i.toDouble())
}

/**
 * Compare a  JavaScript number to a byte
 */
operator fun Number.compareTo(i: Byte): Int {
    return this.toByte().compareTo(i)
}

/**
 * Compare a  JavaScript number to an int
 */
operator fun Number.compareTo(i: Int): Int {
    return this.toInt().compareTo(i)
}

/**
 * Compare a  JavaScript number to a long
 */
operator fun Number.compareTo(i: Long): Int {
    return this.toLong().compareTo(i)
}
/**
 * Compare a  JavaScript number to a float
 */
operator fun Number.compareTo(i: Float): Int {
    return this.toFloat().compareTo(i)
}

/**
 * Compare a  JavaScript number to a double
 */
operator fun Number.compareTo(i: Double): Int {
    return this.toDouble().compareTo(i)
}