package com.bedalton.creatures.caos.collectors.internal

import com.bedalton.common.ast.structs.RangeWithIndex
import com.bedalton.common.ast.structs.RangeWithIndexImpl
import com.bedalton.creatures.caos.collectors.*
import com.bedalton.creatures.caos.libs.CommandType
import com.bedalton.creatures.caos.libs.ValueType
import com.bedalton.creatures.caos.libs.VariantCaosParameter

internal val CONDITION_PARAMETER = VariantCaosParameter(
    index = 0,
    name = "{condition}",
    typeId = ValueType.CONDITION.value,
    typeName = ValueType.CONDITION.simpleName
)

internal val EQ_FIRST_PARAM = VariantCaosParameter(
    index = 0,
    name = "{first}",
    typeId = ValueType.ANY.value,
    typeName = "Any",
)

internal val EQ_SECOND_PARAM = VariantCaosParameter(
    index = 2,
    name = "{second}",
    typeId = ValueType.ANY.value,
    typeName = "Any"
)

internal val EQ_OP = VariantCaosParameter(
    index = 1,
    name = "{EQ}",
    typeId = ValueType.EQ_OP.value,
    typeName = "Any"
)

internal val EQ_JOIN = VariantCaosParameter(
    index = 1,
    name = "{AND|OR}",
    typeId = ValueType.CONDITION.value,
    typeName = ValueType.CONDITION.simpleName
)

internal val conditionParameters = listOf(
    EQ_FIRST_PARAM,
    EQ_OP,
    EQ_SECOND_PARAM,
    EQ_JOIN
)

internal fun createConditionCommandCall(
    containingCommand: CommandReference?,
    parameter: VariantCaosParameter,
    textRange: RangeWithIndex,
): CommandCall {
    val range = RangeWithIndexImpl(
        startIndex = textRange.endIndex,
        endIndex = textRange.endIndex,
        start = textRange.end,
        end = textRange.end,
        parserIndex = textRange.parserIndex
    )
    return CommandCall(
        ValueType.CONDITION.value,
        command = ConditionCommand,
        tokenTextRange = range,
        inVariant = true,
        textRange = range,
        inEqualityExpression = true,
        arguments = emptyArray(),
        parameter = parameter,
        containingCommand = containingCommand,
        tokens = listOfNotNull(
            CaosParserItem.CommandToken(
                textRange,
                EQ_COMMAND_TOKEN
            )
        ).toTypedArray(),
        callType = CommandType.RVALUE
    )
}
