package com.bedalton.creatures.caos.validation.internal

import com.bedalton.creatures.caos.collectors.CaosParserItem
import com.bedalton.creatures.caos.libs.CaosVariant
import com.bedalton.creatures.caos.libs.CaosVariant.C1
import com.bedalton.creatures.caos.libs.CaosVariant.C2
import com.bedalton.creatures.caos.libs.ErrorTypes


internal fun addVarErrors(
    variant: CaosVariant,
    items: Array<CaosParserItem>,
    errors: MutableList<CaosParserItem.ErrorVal>,
    checkCancelled: () -> Unit,
) {
    val variables = items.filterIsInstance<CaosParserItem.IndexedVar>()
    val getError = when (variant) {
        C1 -> VariableValidator.C1
        C2 -> VariableValidator.C2
        else -> VariableValidator.C2e
    }
    for (variable in variables) {
        checkCancelled()
        val error = getError(variable.type, variable.index)
            ?: continue
        errors.add(
            CaosParserItem.ErrorVal(
                textRange = variable.textRange,
                message = error,
                type = ErrorTypes.OUT_OF_VARIANT,
                text = variable.text
            )
        )
    }
}
