@file:Suppress("unused")

package com.bedalton.vfs

import JsArray
import com.bedalton.common.coroutines.AlreadyDisposedException
import com.bedalton.common.exceptions.asThrowable
import com.bedalton.common.exceptions.rethrowCancellationException
import com.bedalton.common.structs.mutableCaselessMapOf
import com.bedalton.common.structs.toMutableCaselessMap
import com.bedalton.common.util.PathUtil
import com.bedalton.common.util.ensureEndsWith
import com.bedalton.common.util.randomString
import com.bedalton.io.bytes.suspendAsPromise
import com.bedalton.io.bytes.toByteArray
import com.bedalton.log.LOG_DEBUG
import com.bedalton.log.Log
import com.bedalton.log.eIf
import com.bedalton.log.iIf
import kotlinx.coroutines.GlobalScope
import kotlinx.coroutines.launch
import org.khronos.webgl.ArrayBuffer
import kotlin.collections.component1
import kotlin.collections.component2
import kotlin.collections.set
import kotlin.js.Promise
import kotlin.js.Promise.Companion.resolve

@JsExport
class MemoryVFS(@Suppress("NON_EXPORTABLE_TYPE") files: Map<String, File>? = null) : VFS, InMemoryVFS {

    private var disposed = false
    private var normalized: Map<String, String>? = null

    @JsName("constructWithFiles")
    constructor(files: Array<JsFile>):  this(files.associate {
        it.name to it.toFile()
    })

    @JsName("constructWithFilesLambda")
    constructor(
        @Suppress("NON_EXPORTABLE_TYPE")
        files: suspend () -> Map<String, JsFile>
    ) : this(null) {
        GlobalScope.launch {
            val initialFiles = files()
            val normalized = initialFiles.entries.associate { (path, file) ->
                makeAbsolute(path) to file.toFile()
            }
            this@MemoryVFS.files.putAll(normalized)
        }
    }

    private val files: MutableMap<String, File> = files?.toMutableCaselessMap() ?: mutableCaselessMapOf()

    private val written: MutableMap<String, File> = mutableCaselessMapOf()


    @JsName("construct")
    constructor() : this(mapOf())

    private fun setFileBytes(fileName: String, disposeExisting: Boolean, bytes: ByteArray): InMemoryVFS {
        assertNotDisposed()
        val path = makeAbsolute(fileName)
        val file = BinaryFile(
            PathUtil.getLastPathComponent(fileName) ?: fileName,
            bytes
        )
        return setPrivate(path, disposeExisting, file)
    }

    private fun setFile(fileName: String, disposeExisting: Boolean, file: File): InMemoryVFS {
        return setPrivate(fileName, disposeExisting, file)
    }

    override operator fun set(fileName: String, disposeExisting: Boolean, file: dynamic): InMemoryVFS {
        return when {
            file is ByteArray -> setFileBytes(fileName, disposeExisting, file.unsafeCast<ByteArray>())
            file is File -> setPrivate(fileName, disposeExisting, file.unsafeCast<File>())
            isInputFile(file) -> setInputFile(fileName, disposeExisting, file.unsafeCast<org.w3c.files.File>())
            isJsFile(file) -> setPrivate(fileName, disposeExisting, file.unsafeCast<JsFile>().toFile())
            isJsBinaryFile(file) -> setFileBytes(fileName, disposeExisting, file.bytes.unsafeCast<ByteArray>())
            isJsBufferFile(file) -> setFileBytes(fileName, disposeExisting, file.bytes.unsafeCast<ArrayBuffer>().toByteArray())
            else -> throw ClassCastException("Cannot set file with non-file object: $file")
        }
    }

    private fun setInputFile(fileName: String, disposeExisting: Boolean, file: org.w3c.files.File): InMemoryVFS {
        val path = makeAbsolute(fileName)
        val basename = PathUtil.getLastPathComponent(path) ?: fileName
        val virtualFile = InputFile(basename, file)
        return setPrivate(path, disposeExisting, virtualFile)
    }


    private fun isJsFile(file: dynamic): Boolean {
        return (file?.bytes != null) && (file.name != null) && (jsTypeOf(file.bytes["then"]) != "undefined")
    }

    private fun isJsBufferFile(file: dynamic): Boolean {
        return (file?.bytes != null) && (file.name != null) && file.bytes is ArrayBuffer
    }

    private fun isJsBinaryFile(file: dynamic): Boolean {
        return (file?.bytes != null) && (file.name != null) && JsArray.isArray(file.bytes)
    }

    private fun isInputFile(file: dynamic): Boolean {
        return file != null && js("'File' in window && file instanceof File") as Boolean
    }

    private fun setPrivate(fileName: String, disposeExisting: Boolean, file: File): InMemoryVFS {
        assertNotDisposed()
        val path = makeAbsolute(fileName)
        if (disposeExisting) {
            files[path]?.dispose()
        }
        files[path] = file
        normalized = null
        return this
    }

    override operator fun get(fileName: String): Promise<ByteArray?> {
        assertNotDisposed()
        return suspendAsPromise promise@{
            val path = getKey(fileName)
                ?: return@promise null
            val file = files[path]
                ?: return@promise null
            file.read()
        }
    }

    override fun fileExists(filePath: String): Promise<Boolean> {
        assertNotDisposed()
        if (getKey(filePath) != null) {
            resolve(true)
        }
        val normalized =  normalizePathForCheck(filePath)
        val normalizedDir = normalized.ensureEndsWith('/')
        val exists= getAllNormalizedPaths().keys.any {
            it == normalized || it.startsWith(normalizedDir)
        }
        return resolve(exists)
    }

    override fun isDirectory(fileName: String): Promise<Boolean?> {
        assertNotDisposed()

        val filenameNormalized = normalizePathForCheck(fileName)
        val normalizedPaths = getAllNormalizedPaths()
        if (normalizedPaths.isEmpty()) {
            return resolve(false)
        }
        if (filenameNormalized in normalizedPaths) {
            return resolve(false)
        }
        val directoryNormalized = filenameNormalized.ensureEndsWith('/')
        val normalized = normalizedPaths.keys
        val isDirectory = normalized.any {
            it.startsWith(directoryNormalized)
        }
        return resolve(isDirectory)
    }

    override fun listChildren(directoryPath: String, recursive: Boolean): Promise<Array<String>?> {
        assertNotDisposed()
        val allChildren = (files.keys + written.keys)
        if (allChildren.isEmpty()) {
            return resolve(emptyArray())
        }
        val prefix = normalizePathForCheck(directoryPath).ensureEndsWith('/')
        val children = allChildren.distinct().filter {
            normalizePathForCheck(it).startsWith(prefix)
        }
        if (!recursive) {
            val regex = ("${Regex.escape(prefix)}[^/]+").toRegex(RegexOption.IGNORE_CASE)
            val directoryRegex = "($prefix[^/]+)/.+".toRegex(RegexOption.IGNORE_CASE)
            val directories = children.mapNotNull {
                directoryRegex.matchEntire(normalizePathForCheck(it))?.groupValues?.get(1)
            }.distinct()
            val childFiles = children.filter { normalizePathForCheck(it).matches(regex) }
            return resolve((childFiles + directories).distinct().sortedBy { it.lowercase() }.toTypedArray())
        }
        val prefixLength = prefix.length
        val folders = mutableSetOf<String>()
        for (child in children) {
            val parts = normalizePathForCheck(child)
                .substring(prefixLength)
                .split('/')
            if (parts.size == 1) {
                continue
            }
            val parent = parts.dropLast(1).joinToString("/")
            folders.add(parent)
        }
        val files = children.toTypedArray() + folders.toTypedArray()
        return resolve(files)
    }

    override fun readBytes(filePath: String): Promise<ByteArray?> {
        assertNotDisposed()
        return suspendAsPromise promise@{
            try {
                val path = getKey(filePath)
                    ?: return@promise null
                val file = files[path]
                    ?: return@promise null
                file.read()
            } catch (err: dynamic) {
                val e = asThrowable(err)
                e.rethrowCancellationException()
                Log.eIf(LOG_DEBUG) { "Failed to read files suspending; ${e.message}${e.stackTraceToString()}"}
                null
            }
        }
    }

    override fun writeBytes(filePath: String, bytes: ByteArray): Promise<Boolean> {
        assertNotDisposed()
        val file = BinaryFile(
            PathUtil.getLastPathComponent(filePath) ?: filePath,
            bytes
        )
        set(filePath, false, file)
        return resolve(true)
    }

    override fun makeDirectory(directoryPath: String, recursive: Boolean): Promise<Boolean> {
        assertNotDisposed()
        return resolve(true)
    }

    override fun deleteFile(filePath: String): Promise<Boolean> {
        assertNotDisposed()
        val actualPath = getKey(filePath)
            ?: return resolve(true)

        files.remove(actualPath)?.apply {
            dispose()
        }
        written.remove(actualPath)?.apply {
            dispose()
        }
        normalized = null
        return resolve(true)
    }

    override fun canDeleteDirectory(filePath: String): Promise<Boolean> {
        assertNotDisposed()
        return resolve(true)
    }

    override fun deleteDirectory(filePath: String): Promise<Boolean> {
        assertNotDisposed()
        deleteDirectory(filePath, files)
        deleteDirectory(filePath, written)
        normalized = null
        return resolve(true)
    }

    private fun deleteDirectory(directory: String, files: MutableMap<String, File>) {
        assertNotDisposed()
        val directoryNormalized = normalizePathForCheck(directory).ensureEndsWith('/')
        val keysToRemove = files.keys.filter { normalizePathForCheck(it).startsWith(directoryNormalized) }
        for (key in keysToRemove) {
            files[key]?.dispose()
            files.remove(key)
        }
        normalized = null
    }

    override fun canMakeDirectories(): Promise<Boolean> {
        assertNotDisposed()
        return resolve(true)
    }

    override fun getAppPath(directoryId: String): Promise<String?> {
        return resolve(null)
    }

    override fun move(fromPath: String, toPath: String, overwrite: Boolean): Promise<Int> {
        assertNotDisposed()

        val fromPathNormalize = getKey(fromPath)
            ?: return resolve(MOVED__FROM_FILE_DOES_NOT_EXIST)

        if (!overwrite && files.containsKey(toPath)) {
            return resolve(MOVED__TO_FILE_ALREADY_EXISTS)
        }

        // Move in main files
        val file = files.remove(fromPathNormalize)
            ?: return resolve(MOVED__FROM_FILE_DOES_NOT_EXIST)
        files[toPath] = file

        // Move in Written
        written.remove(fromPathNormalize)
        written[toPath] = file
        normalized = null
        return resolve(MOVED__OK)
    }

    override fun makeTempFile(prefix: String, suffix: String?): Promise<String?> {
        assertNotDisposed()
        val suffixNonNull = suffix?.let { "-$it" } ?: ""
        var knocks = 20
        normalized = null
        while (knocks-- > 0) {
            val tempFile = "/tmp/." + prefix + randomString(6) + suffixNonNull
            if (!files.containsKey(tempFile) && getKey(tempFile) == null) {
                return resolve(tempFile)
            }
        }
        return resolve(null)
    }

    override fun globFiles(pattern: String, path: String?): Promise<Array<String>?> {
        assertNotDisposed()
        return suspendAsPromise {
            globInFilesList(files.keys, path, pattern).toTypedArray()
        }
    }


    @Deprecated(
        "Root directory scopes are no longer checked",
        replaceWith = ReplaceWith("Promise.resolve(true)", "kotlin.js.Promise")
    )
    override fun accept(path: String): Promise<Boolean> {
        assertNotDisposed()
        return returnsTruePromise
    }

    override fun clearWritten() {
        written.clear()
        normalized = null
    }

    override fun getWritten(): Promise<Array<JsFile>> {
        assertNotDisposed()
        return toFileList(written)
    }

    override fun dispose() {
        if (disposed) {
            return
        }
        disposed = true
        reset(true)
    }

    /**
     * Resets files lists as needed, disposing of existing files if requested
     */
    override fun reset(disposeFiles: Boolean) {
        Log.iIf(LOG_DEBUG) { "Disposing of InMemoryVFS" }

        val files = files.values
        this.files.clear()
        if (disposeFiles) {
            for (file in files) {
                file.dispose()
            }
        }

        val written = written.values
        this.written.clear()
        if (disposeFiles) {
            for (file in written) {
                file.dispose()
            }
        }

        normalized = null
    }

    override fun allFilePaths(): Array<String> {
        return (files.keys + written.keys).distinct().toTypedArray()
    }

    private fun getKey(pathRaw: String): String? {
        val thisPath = normalizePathForCheck(pathRaw)
        return getAllNormalizedPaths()[thisPath]
    }

    private fun getAllNormalizedPaths(): Map<String, String> {
        normalized?.let {
            return it
        }
        val out = (files.keys + written.keys)
            .distinct()
            .map {
                normalizePathForCheck(it) to it
            }
            .distinctBy { it.first }
            .toMap()
        normalized = out
        return out
    }

    private fun String.normalized() = this.replace('\\', '/').let { PathUtil.combine(it) }

    private fun makeAbsolute(filepath: String): String {
        val path = filepath.normalized()
        return if (path.startsWith('/')) {
            path
        } else {
            "/$path"
        }
    }

    private fun normalizePathForCheck(fileName: String): String {
        return makeAbsolute(fileName).lowercase()
    }

    private fun assertNotDisposed() {
        if (disposed) {
            throw AlreadyDisposedException("InMemoryVFS already disposed")
        }
    }

}

