package com.bedalton.creatures.common.util

import com.bedalton.common.util.*
import com.bedalton.log.LOG_DEBUG
import com.bedalton.log.Log
import com.bedalton.log.eIf

/**
 * Parses a creatures
 * Parse data in 'HH:mm dd MMMM yyyy' format
 */
expect fun creaturesDateToUnixTime(timestamp: String): Double?

internal fun creaturesDateToISO(timestamp: String): String? {
    val parts = timestamp.split("(,?\\s+)|(,\\s*)".toRegex())

    // Get time in 24-hour format
    if (parts[0].length != 5) {
        Log.eIf(LOG_DEBUG) { "Hours:Minutes value '${parts[0]}' is invalid. Expected HH:mm" }
        return null
    }
    val time = parts[0].trim()

    // Get array offset if contains day of the week
    // If it does, the latter components will be offset by one
    val offset = if (parts[1].trim().lowercase() like Time.DAYS_OF_THE_WEEK) 1 else 0

    // Get day of the month
    val date = parts[1 + offset].trim()
    if (date.length != 2 || date.toIntOrNull().orElse(-1) !in 0..31) {
        Log.eIf(LOG_DEBUG) { "Date value '$date' is invalid. Should be two digit date 00-31" }
        return null
    }

    // Get month zero-indexed
    val monthIntPadded = getMonthIntFromString(parts[2 + offset].trim())?.toString()?.padStart(2, '0')
        ?: return null

    // Get year
    val year = parts[3 + offset].trim().padStart(4, '0')
    if (year.length != 4) {
        Log.eIf(LOG_DEBUG) { "Year value '$year' is invalid. Expected 4 digit year" }
        return null
    }

    // Combine parts into ISO string
    return "$year-$monthIntPadded-${date}T${time}"
}

fun creaturesDateToComponents(timestamp: String): DateComponents? {
    val parts = timestamp.split("(,?\\s+)|(,\\s*)".toRegex())

    // Get time in 24-hour format
    if (parts[0].length != 5) {
        Log.eIf(LOG_DEBUG) { "Hours:Minutes value '${parts[0]}' is invalid. Expected HH:mm" }
        return null
    }
    val timeRaw = parts[0].trim()
        .split(":")
    val (hour, minute) = if (timeRaw.size < 2) {
        Pair(0,0)
    } else {
        val hour = timeRaw[0].trim()
            .toIntOrNull()
            ?: return null
        val minute = "(\\d+).*".toRegex().matchEntire(timeRaw[1])
            ?.groupValues
            ?.getOrNull(1)
            ?.toIntOrNull()
            ?: return null
        Pair(hour, minute)
    }

    // Get array offset if contains day of the week
    // If it does, the latter components will be offset by one
    val offset = if (parts[1].trim().lowercase() like Time.DAYS_OF_THE_WEEK) 1 else 0

    // Get day of the month
    val date = parts[1 + offset].trim()
        .toIntOrNull()
        ?: return null

    if (date !in 0..31) {
        return null
    }

    // Get month zero-indexed
    val monthZeroIndexed = getMonthIntFromString(parts[2 + offset].trim())?.let { it - 1}
        ?: return null

    // Get year
    val year = parts[3 + offset].trim().toIntOrNull()
        ?: return null

    // Create date component from all parts
    return DateComponents(
        year,
        monthZeroIndexed,
        date,
        hour,
        minute
    )
}