package com.creaturesforge.application.state

import com.bedalton.common.util.PathUtil
import com.bedalton.common.util.nullIfEmpty
import com.bedalton.common.util.trySilent
import com.bedalton.log.LOG_DEBUG
import com.bedalton.log.Log
import com.bedalton.log.iIf
import com.creaturesforge.application.state.AutoNamesHelper.updateAutoNames
import com.creaturesforge.application.util.isAutoNameNullOrBlank
import com.creaturesforge.application.util.launchCatching
import korlibs.io.concurrent.atomic.korAtomic

internal fun alterActionReducer(state: ForgeState, action: FAction): ForgeState {

    if (action is ClearPreviousGenomesListFromProject) {
        return state.copy(
            additionalGenomes = emptyMap()
        ).also {
            ForgeConfig.pushProjectState(it, false)
        }
    }

    if (action !is AlterAction) {
        return state
    }

    val out = when (action) {

        is SetProjectRootAction -> {
            if (state.projectFolder == action.path) {
                return state
            }

            var out = ForgeConfig.getCachedProjectData(action.path)
                ?.let { cached ->
                    scrubCachedProjectState(cached, state.eggMode)
                }
                ?: ForgeState(
                    virtual = isAgentScheme(action.path ?: ""),
                    projectFolder = action.path,
                    eggMode = state.eggMode
                )
            out = out.copy(lastStateId = korAtomic(0))
            resetVfs()
            EggData.resetIdIndex(out.eggs)
            updateAutoNames(out)
        }

        is SetSpriteRootAction -> state.copy(
            spriteRoot = action.path
        )

        is SetSpriteFilesAction -> setSpriteFiles(state, action)

        is SetAttRootAction -> {
            if (action.path == state.projectFolder) {
                state.copy(attRoot = null)
            } else {
                state.copy(
                    attRoot = action.path
                )
            }
        }

        is SetAttFilesAction -> setAttFiles(state, action)

        is SetOutputFileAction -> state.copy(
            outputFile = action.path
        )

        is SetEggNameAction -> onSetEggName(state, action)

        is SetGlyphAction -> setThumbnail(state, action)

        is SetGenomeAction -> setGenome(state, action)

        is SetBreedSlotAction -> state.copy(
            breedSlot = action.slot
        )

        is SetSpriteSlotAction -> setSpriteBreedSlot(state, action)

        is SetAttSlotAction -> state.copy(
            attSlot = action.slot
        )

        is SetGenomeGenus -> {
            val out = state.copy(
                genomeGenus = action.genus
            )
            updateAutoNames(out)
        }

        is AddGenomeOptionAction -> {
            val additionGenomes = addGenome(state.additionalGenomes, action.genomeFile)
            state.copy(
                additionalGenomes = additionGenomes
            )
        }

        is SetSelectedEggAction -> state.copy(
            eggs = state.eggs.map {
                if (it.id == action.egg.id) {
                    action.egg
                } else {
                    it
                }
            },
            selectedEgg = action.egg
        )

        is UpdateEggAction -> updateEgg(state, action.egg)

        AddEgg -> {
            EggData.resetIdIndex(state.eggs)
            val newEgg = EggData()
            state.copy(
                eggs = state.eggs + newEgg,
                selectedEgg = newEgg
            ).let {
                updateAutoNames(it)
            }
        }

        DeleteEgg -> {
            val eggId = state.selectedEgg.id
            val eggs = state.eggs.filter { it.id != eggId }
                .nullIfEmpty()
                ?: listOf(EggData())
            EggData.resetIdIndex(eggs)
            val out = state.copy(
                eggs = eggs,
                selectedEgg = eggs.first()
            )
            updateAutoNames(out)
        }

        is SetEggModeAction -> {
            if (state.eggMode != action.eggMode) {
                state.copy(eggMode = action.eggMode)
            } else {
                state
            }
        }

        is OpenEggAction -> state

        is SetStateAction -> {
            EggData.resetIdIndex(action.state.eggs)
            action.state.copy(
                lastStateId = korAtomic(0)
            )
        }

        ResetStateAction -> {
            EggData.resetIdIndex(emptyList())
            ForgeState(
                virtual = false,
                eggMode = state.eggMode
            )
        }

        is ClearAllPreviousGenomesFromAllTime -> {
            state.copy(
                additionalGenomes = emptyMap()
            )
        }

        ClearPreviousGenomesListFromProject -> {
            state.copy(
                additionalGenomes = emptyMap()
            )
        }

    }

    val cache = action !is NoCacheConfigData

    if (cache) {
        ForgeConfig.pushProjectState(out, action !is ForceConfigCache)
    }

    Log.i { "Updated state to: ${out.stateId}" }

    return out
}


private fun setThumbnail(state: ForgeState, action: SetGlyphAction): ForgeState {
    return if (action.male) {
        state.copy(
            maleGlyph = action.glyph
        )
    } else {
        state.copy(
            femaleGlyph = action.glyph
        )
    }
}

private fun setGenome(state: ForgeState, action: SetGenomeAction): ForgeState {
    var egg = state.selectedEgg
    egg = when (action.gender) {
        0 -> egg.copy(
            baseGenomeFile = action.genomeFile
        )

        1 -> egg.copy(
            fatherGenomeFile = action.genomeFile
        )

        2 -> egg.copy(
            motherGenomeFile = action.genomeFile
        )

        else -> throw Exception("Invalid genome slot: ${action.gender}; Expected 0..2")
    }
    return updateEgg(state, egg)
}

private fun updateEgg(state: ForgeState, egg: EggData): ForgeState {
    val updatedEggs = state.eggs.map {
        if (it.id == egg.id) {
            egg
        } else {
            it
        }
    }
    val out = state.copy(
        eggs = updatedEggs,
        selectedEgg = getSelectedEgg(state, updatedEggs)
    )
    return updateAutoNames(out)
}

internal fun getSelectedEgg(state: ForgeState, eggs: List<EggData>): EggData {
    return eggs.firstOrNull { it.id == state.selectedEgg.id }
        ?: eggs.first()
}

internal fun setSpriteBreedSlot(state: ForgeState, action: SetSpriteSlotAction): ForgeState {
    val slot = action.slot

    Log.iIf(LOG_DEBUG) { "Setting Sprite Slot: $slot" }

    var out = state.copy(
        spriteSlot = slot
    )

    if (state.breedSlot == state.spriteSlot) {
        out = out.copy(breedSlot = null)
    }

    if (state.attSlot == state.spriteSlot) {
        out = out.copy(attSlot = null)
    }

    if (state.projectFolder == null) {
        return out
    }

    val spriteFiles = state.spriteFiles
        ?.nullIfEmpty()
        ?: return out

    if (state.maleGlyph == null || !state.maleGlyph.manual) {
        out = out.copy(
            maleGlyph = getHeadGlyph(
                spriteFiles,
                slot,
                male = true
            )
        )
    }

    if (state.femaleGlyph == null || !state.femaleGlyph.manual) {
        out = out.copy(
            femaleGlyph = getHeadGlyph(
                spriteFiles,
                slot,
                male = false
            )
        )
    }

    if (state.maleGlyph.hasAutoNameOrBlank() || state.femaleGlyph.hasAutoNameOrBlank()) {
        out = updateAutoNames(out)
    }

    return out
}

private fun Glyph?.hasAutoNameOrBlank(): Boolean {
    return this?.filename.isAutoNameNullOrBlank()
}

private fun getHeadGlyph(spriteFiles: List<String>, slot: BreedSlot, male: Boolean): Glyph? {
    if (spriteFiles.isEmpty()) {
        return null
    }
    val genus = if (male) slot.genus else slot.genus + 4
    val regex =
        "^.*?[\\\\/][Aa]$genus[0-7][${slot.breed.uppercaseChar()}${slot.breed.lowercaseChar()}](.[Cc]16)?$".toRegex()
    val files = spriteFiles.filter(regex::matches)
    val sprite = files.minByOrNull {
        val fileName = PathUtil.getFileNameWithoutExtension(it)!!
        when (fileName[2]) {
            '4' -> 0
            '3' -> 1
            '2' -> 2
            '5', '6' -> 3
            '1' -> 4
            else -> 5
        }
    } ?: return null

    return SpriteGlyph.create(
        "",
        9,
        sprite,
    )
}

private fun onSetEggName(state: ForgeState, action: SetEggNameAction): ForgeState {
    val name = action.name
    val egg = state.selectedEgg.copy(
        eggName = name
    )

    trySilent {
        cacheEggName(state, egg, name)
    }

    return updateEgg(state, egg)
}

private fun cacheEggName(state: ForgeState, egg: EggData, name: String?) {
    val projectRoot = state.projectFolder
        ?: return

    if (name.isAutoNameNullOrBlank()) {
        return
    }

    launchCatching {
        ForgeConfig.setDefaultEggName(projectRoot, state, egg, name)
    }
}

internal fun hasSlot(breedFiles: List<String>, slot: BreedSlot?): Boolean {
    if (slot == null) {
        return true
    }
    val slotRegex =
        "^.*[\\\\/][a-qA-Q][${slot.genus}${slot.genus + 4}][0-7]${slot.breed}(.c16)?$".toRegex(RegexOption.IGNORE_CASE)
    return breedFiles.any(slotRegex::matches)
}

private fun addGenome(genomes: Map<String, String>, genomeFile: String): Map<String, String> {
    val lowercase = genomeFile.lowercase()
    return if (genomeFile in genomes.values) {
        genomes
    } else if (genomes.values.any { it.lowercase() == lowercase }) {
        genomes.mapValues { (_, value) ->
            if (value.lowercase() == lowercase) {
                genomeFile
            } else {
                value
            }
        }
    } else {
        val all = genomes.values + genomeFile
        val shortest = PathUtil.shortestPathsPreservingOrder(all)
        all.indices.associate { i ->
            shortest[i] to all[i]
        }
    }
}

private fun scrubCachedProjectState(cached: ForgeState, eggMode: EggMode): ForgeState {

    var out = cached.copy(
        eggMode = cached.eggMode + eggMode,
        virtual = isAgentScheme(cached.projectFolder ?: ""),
        attFiles = null,
        spriteFiles = null,
        lastStateId = korAtomic(0),
    )

    EggData.resetIdIndex(out.eggs)

    if (out.spriteSlot == out.breedSlot) {
        out = out.copy(breedSlot = null)
    }

    if (out.spriteSlot == out.attSlot) {
        out = out.copy(attSlot = null)
    }

    if (out.maleGlyph?.manual == false) {
        out = out.copy(maleGlyph = null)
    }

    if (out.femaleGlyph?.manual == false) {
        out = out.copy(femaleGlyph = null)
    }

    return out
}