package com.bedalton.creatures.agents.pray.compiler.caos2pray.internal

import com.bedalton.common.util.pathSeparator
import com.bedalton.common.util.toArrayOf
import com.bedalton.creatures.agents.pray.compiler.NEWLINE_REGEX
import com.bedalton.creatures.agents.pray.compiler.caos2pray.CommandValue
import com.bedalton.creatures.agents.pray.compiler.pray.PrayValidationError
import com.bedalton.creatures.agents.pray.compiler.data.Tag
import com.bedalton.creatures.agents.pray.compiler.data.TextValue
import com.bedalton.creatures.agents.util.RelativeFileSystem

/**
 * Process all RSCR file values
 *
 * @param fs
 * @param fullFilePath
 * @param command
 * @param errors
 * @return
 */
internal suspend fun processRscr(
    fs: RelativeFileSystem,
    fullFilePath: String,
    command: CommandValue,
    errors: MutableList<PrayValidationError>,
): List<Tag.StringTag> {
    return command.values.mapNotNull map@{ fileName ->
        processRscrValue(
            fs,
            fullFilePath,
            command,
            fileName,
            errors
        )
    }
}

/**
 * Process RSCR file value
 *
 * @param fs
 * @param fullFilePath
 * @param command
 * @param fileName
 * @param errors
 * @return
 */
private suspend fun processRscrValue(
    fs: RelativeFileSystem,
    fullFilePath: String,
    command: CommandValue,
    fileName: TextValue,
    errors: MutableList<PrayValidationError>,
): Tag.StringTag? {
    if (!fs.fileExists(fileName.text)) {
        val error = PrayValidationError.CommandError(
            command = "RSCR",
            commandRange = command,
            errorRange = fileName,
            message = "Failed to find Removal script @ <${fs.path(fileName.text)}$pathSeparator$fileName>",
            fullFilePath = fullFilePath
        )
        errors.add(error)
        return null
    }
    val removalText = fs
        .readAsText(fileName.text)
        .replace(NEWLINE_REGEX, "\n")
    val removalScript = combineRemoverScripts(
        (if (removalText.trimStart().startsWith("rscr", ignoreCase = true)) {
            removalText.trimStart().substring(4).trimStart()
        } else {
            removalText
        }).toArrayOf()
    ).second
    return Tag.StringTag(
        lineNumber = command.lineNumber,
        startIndex = fileName.startIndex,
        endIndex = fileName.endIndex,
        tagRange = TextValue(
            "Remove script",
            lineNumber = command.lineNumber,
            startIndex = fileName.startIndex,
            endIndex = fileName.endIndex,
        ),
        value = TextValue(
            text = removalScript,
            lineNumber = fileName.lineNumber,
            startIndex = fileName.startIndex,
            endIndex = fileName.endIndex
        )
    )
}