package com.bedalton.creatures.breed.render.files

import com.bedalton.common.util.isNotNullOrBlank
import com.bedalton.creatures.breed.render.renderer.InvalidRenderValueException
import kotlin.js.JsExport

@JsExport
data class JsBreedKey(
    val genus: Int?,
    val gender: Int?,
    val ageGroup: Int?,
    val breed: String?
) {

    init {
        if (breed != null && breed.trim().length != 1) {
            throw InvalidRenderValueException(
                "Breed must be null or a single character string",
                "breed",
                breed,
                "single char"
            )
        }
    }

    val code: String? by lazy {
        if (genus != null && gender != null && breed != null && ageGroup != null) {
            val first = ((gender-1) * 4) + genus
            "$first$ageGroup$breed"
        } else {
            null
        }
    }
    fun isConcrete(): Boolean {
        return genus != null && gender != null && ageGroup != null && breed.isNotNullOrBlank()
    }
}

val JsBreedKey.breedChar: Char? get() = breed?.getOrNull(0)?.lowercaseChar()