package com.bedalton.creatures.agents.pray.compiler.pray.validators

import com.bedalton.creatures.agents.pray.compiler.data.Tag
import com.bedalton.common.util.*

/**
 * Validates that a tags with tag name have a file extension
 */
internal fun validateTagWithFileExtension(
    addError: AddError,
    tagName: String,
    extensions:List<String>,
    tags: Array<Tag<*>>
) {
    val targetTags = tags.filter { it.tag like tagName }
    for (tag in targetTags) {
        if (tag is Tag.StringTag) {
            if (tag.value.trim().isEmpty()) {
                addError(
                    tag.valueRange,
                    "\"$tagName\" tag should not be blank"
                )
                continue
            }
            val extension = PathUtil.getExtension(tag.value)?.nullIfEmpty()
            if (extension == null || extension !in extensions) {
                addError(
                    tag.valueRange,
                    "\"$tagName\" tag should include a file extension"
                )
            }
        } else {
            addError(
                tag.valueRange,
                "\"$tagName\" should have a string value"
            )
        }
    }
}

/**
 * Validates that a tags with tag name have a file extension
 */
@Suppress("unused")
internal fun validateTagWithFileExtension(
    addError: AddError,
    isTag: Tag<*>.()->Boolean,
    extensions:List<String>,
    tags: Array<Tag<*>>
) {
    val targetTags = tags.filter { it.isTag() }
    for (tag in targetTags) {
        if (tag is Tag.StringTag) {
            if (tag.value.trim().isEmpty()) {
                addError(
                    tag.valueRange,
                    "\"${tag.tag}\" tag should not be blank"
                )
                continue
            }
            val extension = PathUtil.getExtension(tag.value)?.nullIfEmpty()
            if (extension == null || extension !in extensions) {
                addError(
                    tag.valueRange,
                    "\"${tag.tag}\" tag should include a file extension"
                )
            }
        } else {
            addError(
                tag.valueRange,
                "\"${tag.tag}\" should have a string value"
            )
        }
    }
}

/**
 * Validates that a tags with a given tag name does not include a file extension
 */
internal fun validateTagWithFileWithoutExtension(
    addError: AddError,
    tagName: String,
    extensions: List<String>,
    tags: Array<Tag<*>>
) {
    val targetTags = tags.filter { it.tag like tagName }
    for (tag in targetTags) {
        if (tag is Tag.StringTag) {
            if (tag.value.trim().isEmpty()) {
                addError(
                    tag.valueRange,
                    "\"$tagName\" tag should not be blank"
                )
                continue
            }
            val extension = PathUtil.getExtension(tag.value)?.nullIfEmpty()
            if (extension != null && extension in extensions) {
                addError(
                    tag.valueRange,
                    "\"$tagName\" tag should not include a file extension"
                )
            }
        } else {
            addError(
                tag.valueRange,
                "\"$tagName\" should have a string value"
            )
        }
    }
}

