package com.bedalton.creatures.agents.pray.compiler.internal

import com.bedalton.common.coroutines.rethrowIfCancellationException
import com.bedalton.common.util.PathUtil
import com.bedalton.common.util.className
import com.bedalton.common.util.like
import com.bedalton.creatures.agents.pray.compiler.PrayCompileOptions
import com.bedalton.creatures.agents.pray.compiler.caos2pray.Caos2PrayParseException
import com.bedalton.creatures.agents.pray.compiler.caos2pray.Caos2PrayParserUtil
import com.bedalton.creatures.agents.pray.compiler.caos2pray.Caos2PrayResult
import com.bedalton.creatures.agents.pray.compiler.overrideAgentNameOrNull
import com.bedalton.creatures.agents.pray.compiler.pray.PrayInputException
import com.bedalton.creatures.agents.pray.compiler.pray.PrayParseValidationFailException
import com.bedalton.creatures.agents.pray.compiler.pray.PrayScriptParserUtil
import com.bedalton.creatures.agents.pray.compiler.pray.PrayValidationError
import com.bedalton.creatures.agents.util.RelativeFileSystem
import com.bedalton.log.LOG_PROGRESS
import com.bedalton.log.Log
import com.bedalton.log.iIf
import com.bedalton.log.iWith
import kotlinx.coroutines.CoroutineScope

/**
 * Loads and parses a Pray/CAOS2Pray file
 */
internal suspend fun getInputData(
    coroutineScope: CoroutineScope,
    fs: RelativeFileSystem,
    fileName: String,
    opts: PrayCompileOptions,
): Caos2PrayResult {
    if (!fs.fileExists(fileName) && !fileName.contains('\n') && !fileName.contains('\"')) {
        throw PrayInputException("Failed to locate file at '${fs.path(fileName)}'")
    }
    if (fs.isDirectory(fileName)) {
        throw PrayInputException("Input must be a file. Directory given")
    }
    if (PathUtil.getExtension(fileName) like "cos") {
        Caos2PrayParserUtil.parse(coroutineScope, fs, fileName, opts).apply {
            return this
        }
    }
    return try {
        Log.iWith(LOG_PROGRESS, replace = true) { "Parsing as input file" }
        PrayScriptParserUtil.parse(coroutineScope, fs, fileName, fileName, opts).let { data ->

            // Get override filename if any
            val overrideFileName = opts.overrideAgentNameOrNull

            // Get output file name from pray filename or override if defined
            val outputFileName = (overrideFileName ?: PathUtil.getFileNameWithoutExtension(fileName) ?: fileName)
                .let {
                    if (!it.endsWith(".agent") && !it.endsWith(".agents")) {
                        "$it.agents"
                    } else {
                        it
                    }
                }

            Caos2PrayResult(
                outputFileName,
                data
            ).apply {
                Log.iIf(LOG_PROGRESS) { "Input file was PRAY" }
            }
        }
    } catch (e: Exception) {
        e.rethrowIfCancellationException()
        if (e is PrayParseValidationFailException) {
            Log.e { "PRAY parsing failed. ${e.className}(${e.message})\n\t-${e.errors.joinToString("\n\t-") { it.message }}" }
            if (e.errors.none { it is PrayValidationError.SyntaxError })
                throw e
        } else {
            Log.e { "PRAY parsing failed. ${e.className}(${e.message})" }
            e.printStackTrace()
        }

        Caos2PrayParserUtil.parse(coroutineScope, fs, fileName, opts).apply {
            Log.iWith(LOG_PROGRESS) { "Input file was CAOS2Pray" }
        }
    } catch (e: Caos2PrayParseException) {
        Log.e { "Failed to ascertain Pray file type. Error: ${e.message}" }
        e.printStackTrace()
        throw e
    } catch (e: Exception) {
        e.rethrowIfCancellationException()
        if (e is PrayParseValidationFailException) {
            Log.e { "${e.message}; Errors:\n\t-${e.errors.joinToString("\n\t-") { it.message }}" }
        }
        Log.e { "PRAY and CAOS2Pray parsing failed. ${e.className}(${e.message})" }
        e.printStackTrace()
        throw e
    }
}