@file:Suppress("unused")

package com.bedalton.app

/**
 * Whether this application has been flagged as a CLI application
 * This is used internally to determine how to exit an application
 * This is the backing value
 * @default false
 */
private var mIsCLIPointer = false

/**
 * Whether this application has been flagged as a CLI application
 * This is used internally to determine how to exit an application
 * @default false
 */
@Deprecated("Use val com.bedalton.app.isCLI",
    replaceWith = ReplaceWith(
        "isCLI",
        imports = ["com.bedalton.app.isCLI"]
    )
)
val mIsCLI get() = isCLI

/**
 * Whether this application has been flagged as a CLI application
 * This is used internally to determine how to exit an application
 * @default false
 */
val isCLI get() = mIsCLIPointer

/**
 * Sets whether this app is a CLI app
 * This is used internally to determine how to exit an application
 */
fun setIsCLI(isCLI: Boolean) {
    mIsCLIPointer = isCLI
}

/**
 * Sets whether this app is a NOT a CLI app
 * isCLI value is used internally to determine how to exit an application
 */
val isNotCli get() = !isCLI


/**
 * Runs block only if application has been set to CLI
 */
fun <T> ifCli(work: () -> T): T? {
    if (isCLI) {
        return work()
    }
    return null
}

/**
 * Runs block only if application is not set as CLI
 */
fun <T> ifNotCli(work: () -> T): T? {
    if (isCLI) {
        return null
    }
    return work()
}
