/**
 * Parses a compiled PRAY file from bytes
 * @throws AgentFileDecompilerException
 */
suspend fun parsePrayAgentToMemory(
    coroutineScope: CoroutineScope,
    fileName: String,
    prefix: String,
    bytes: ByteArray,
    whitelist: String,
    inlineScripts: Boolean = DEFAULT_INLINE_SCRIPTS,
    callback: PrayBlockCallback? = null,
): PrayAgentParseResult {
    val reader = MemoryByteStreamReader(bytes)
    return parsePrayAgentToMemory(
        coroutineScope,
        fileName,
        prefix,
        reader,
        whitelist,
        inlineScripts = inlineScripts,
        callback
    )
}

