/**
 * Parses a compiled PRAY file from a byte stream reader
 * @throws AgentFileDecompilerException
 */
suspend fun parsePrayAgentToMemory(
    scope: CoroutineScope,
    fileName: String,
    prefix: String,
    reader: ByteStreamReader,
    whitelist: String,
    inlineScripts: Boolean = DEFAULT_INLINE_SCRIPTS,
    callback: PrayBlockCallback? = null,
): PrayAgentParseResult {
    val vfs = RelativeFileSystem(MemoryFileSystem(), "/", true)
    val blocks = parsePrayAgentBlocks(scope, reader, whitelist, callback)
    return PrayAgentParseResult(fileName, prefix, blocks, vfs, inlineScripts)
}