@file:Suppress("unused")

package com.bedalton.creatures.agents.util.internal

import com.bedalton.creatures.agents.util.InvalidTokenLengthException

internal fun tokBigEndian(token:String, lowercase:Boolean = false) : Int  {
    if (token.length != 4) {
        throw InvalidTokenLengthException(token)
    }
    val t = if (lowercase) token.lowercase() else token
    return (t[0].code shl 24) or (t[1].code shl 16) or (t[2].code shl 8) or t[3].code
}

internal fun tok(token:String, lowercase:Boolean = false) : Int  {
    if (token.length != 4) {
        throw InvalidTokenLengthException(token)
    }
    val t = if (lowercase) token.lowercase() else token
    return (t[3].code shl 24) or (t[2].code shl 16) or (t[1].code shl 8) or t[0].code
}

internal fun tok(token: Int) : Int  {
    return (token shr 24) or (token shr 16) or (token shr 8) or token
}