package com.bedalton.creatures.agents.pray.compiler.internal

import com.bedalton.creatures.agents.util.internal.tok
import com.bedalton.creatures.agents.pray.compiler.data.CompilerPrayBlock
import com.bedalton.io.bytes.ByteStreamWriter

/**
 * Write the block header for the current pray block
 */
internal fun writeBlockHeader(writer: ByteStreamWriter, block: CompilerPrayBlock) {
//    Log.i { "Writing ${block.blockTag} block: \"${block.blockName}\" LINE: ${block.startLine}" }
    writer.writeUInt32(tok(block.blockTag.text))
    val name = block.blockName.text.padEnd(128, 0x00.toChar())
    writer.writeStringWithCreaturesEncoding(name)
}


/**
 * Write block header given the block tag and block name
 */
internal fun writeBlockHeader(writer: ByteStreamWriter, blockTag: String, blockName: String) {
    writer.writeUInt32(tok(blockTag))
    val name = blockName.padEnd(128, 0x00.toChar())
    writer.writeStringWithCreaturesEncoding(name)
}