enum class SpriteType(
    @Suppress("MemberVisibilityCanBePrivate")
    val extensionCapitalized: String
) {
    SPR("SPR"),
    SPR_SET("SPR"),
    S16("S16"),
    C16("C16"),
    BLK("BLK"),
    PHOTO_ALBUM("Photo Album");

    val extension: String by lazy { extensionCapitalized.lowercase() }

    companion object {
        fun fromString(value: String): SpriteType {
            return when (value.uppercase()) {
                "SPR" -> SPR
                "S16" -> S16
                "C16" -> C16
                "BLK" -> BLK
                "PHOTO ALBUM", "PHOTO_ALBUM" -> PHOTO_ALBUM
                else -> throw InvalidSpriteTypeException(value)
            }
        }
    }
}


@Suppress("MemberVisibilityCanBePrivate")
class InvalidSpriteTypeException(
    val value: String,
    message: String = "Invalid sprite format: '$value'. Expected value in [SPR,S16,C16,BLK]",
    throwable: Throwable? = null,
) : Exception(message, throwable)

fun SpriteType.colorEncoding(bytesBuffer: ByteStreamReader): ColorEncoding? {
    return when (this) {
        SPR -> null
        else -> {
            return bytesBuffer.readAtPosition(0) {
                val buffer = int32()
                when {
                    buffer hasFlag  1 -> ColorEncoding.X_565
                    (buffer and 2) == 0 -> ColorEncoding.X_555
                    else -> throw Exception("File encoding not recognized Should be 0, 1 or 3. Flags: ('$buffer')")
                }
            }
        }
    }
}

fun SpriteType.colorEncoding(byteArray: ByteArray): ColorEncoding? {
    return when (this) {
        SPR -> null
        else -> {
            val buffer = toInt(byteArray.copyOfRange(0, 4))
                ?: throw Exception("Failed to get file encoding bytes")
            when {
                buffer hasFlag 1 -> ColorEncoding.X_565
                (buffer and 2) == 0 -> ColorEncoding.X_555
                else -> throw Exception("File encoding not recognized Should be 0, 1 or 3. Flags: ('$buffer')")
            }
        }
    }
}

val SpriteType.parserWithProgressChunkSize: (bytesBuffer: ByteStreamReader, keepBlack: Boolean, progressChunkSize: Int, progressCallback: ((current: Int, total: Int) -> Boolean?)?) -> List<Bitmap32>
    get() {
        return when (this) {
            SPR -> {
                { bytes: ByteStreamReader, keepBlack: Boolean, progressChunkSize, progressCallback: ((current: Int, total: Int) -> Boolean?)? ->
                    SprSpriteFile(bytes, keepBlack, progressChunkSize, progressCallback).frames()
                }
            }

            SPR_SET -> {
                { bytes: ByteStreamReader, keepBlack: Boolean, progressChunkSize, progressCallback: ((current: Int, total: Int) -> Boolean?)? ->
                    val trueCallback = progressCallbackWithIgnoredPass(progressCallback)
                    val files = SprSetDecompiler.decompileSets(bytes, keepBlack, progressChunkSize, trueCallback)
                        ?: throw SpriteParserException("Failed to parse multi-SPR sprite set file")
                    files.flatMap { it.frames() }
                }
            }

            S16 -> {
                { bytes: ByteStreamReader, keepBlack: Boolean, progressChunkSize, progressCallback: ((current: Int, total: Int) -> Boolean?)? ->
                    S16SpriteFile(bytes, keepBlack, null, progressChunkSize, progressCallback).frames()
                }
            }

            C16 -> {
                { bytes: ByteStreamReader, keepBlack: Boolean, progressChunkSize, progressCallback: ((current: Int, total: Int) -> Boolean?)? ->
                    C16SpriteFile(bytes, keepBlack, null, progressChunkSize, progressCallback).frames()
                }
            }

            BLK -> {
                { bytes: ByteStreamReader, _: Boolean, progressChunkSize, progressCallback: ((current: Int, total: Int) -> Boolean?)? ->
                    val trueCallback = progressCallbackWithIgnoredPass(progressCallback)
                    BlkParser.parse(bytes, progressChunkSize, trueCallback).toListOf()
                }
            }

            PHOTO_ALBUM -> {
                { bytes: ByteStreamReader, _: Boolean, progressChunkSize, progressCallback: ((current: Int, total: Int) -> Boolean?)? ->
                    val album = parsePhotoAlbumInternal(bytes, progressChunkSize, progressCallback)
                            ?: throw SpriteParserException("Failed to parse photo album")
                    album.photos.map { it.bitmap32 }
                }
            }
        }
    }

fun SpriteType.parserWithProgressChunkSizeAndPalette(): (bytesBuffer: ByteStreamReader, keepBlack: Boolean, palette: PaletteTransform, progressChunkSize: Int, progressCallback: ((current: Int, total: Int) -> Boolean?)?) -> List<Bitmap32> {
    return when (this) {
        SPR -> {
            { bytes: ByteStreamReader, keepBlack: Boolean, _: PaletteTransform, progressChunkSize, progressCallback: ((current: Int, total: Int) -> Boolean?)? ->
                SprSpriteFile(bytes, keepBlack, progressChunkSize, progressCallback).frames()
            }
        }

        SPR_SET -> {
            { bytes: ByteStreamReader, keepBlack: Boolean, _: PaletteTransform, progressChunkSize, progressCallback: ((current: Int, total: Int) -> Boolean?)? ->
                val trueCallback = progressCallbackWithIgnoredPass(progressCallback)
                val files = SprSetDecompiler.decompileSets(bytes, keepBlack, progressChunkSize, trueCallback)
                    ?: throw SpriteParserException("Failed to parse multi-SPR sprite set file")
                files.flatMap { it.frames() }
            }
        }

        S16 -> {
            { bytes: ByteStreamReader, keepBlack: Boolean, palette: PaletteTransform, progressChunkSize, progressCallback: ((current: Int, total: Int) -> Boolean?)? ->
                S16SpriteFile(bytes, keepBlack, palette, progressChunkSize, progressCallback).frames()
            }
        }

        C16 -> {
            { bytes: ByteStreamReader, keepBlack: Boolean, palette: PaletteTransform, progressChunkSize, progressCallback: ((current: Int, total: Int) -> Boolean?)? ->
                C16SpriteFile(bytes, keepBlack, palette, progressChunkSize, progressCallback).frames()
            }
        }

        BLK -> {
            throw SpriteParserException("Cannot parse BLK generically")
        }

        PHOTO_ALBUM -> {
            { bytes: ByteStreamReader, _: Boolean, _: PaletteTransform, progressChunkSize, progressCallback: ((current: Int, total: Int) -> Boolean?)? ->
                val album = parsePhotoAlbumInternal(bytes, progressChunkSize, progressCallback)
                        ?: throw SpriteParserException("Failed to parse photo album")
                album.photos.map { it.bitmap32 }
            }
        }
    }
}



