val SpriteType.parser: (bytesBuffer: ByteStreamReader, keepBlack: Boolean, progressCallback: ((current: Int, total: Int) -> Boolean?)?) -> List<Bitmap32>
    get() {
        val chunkSize = 1
        return when (this) {
            SPR -> {
                { bytes: ByteStreamReader, keepBlack: Boolean, progressCallback: ((current: Int, total: Int) -> Boolean?)? ->
                    SprSpriteFile(bytes, keepBlack, progressChunkSize = chunkSize, progressCallback = progressCallback).frames()
                }
            }

            SPR_SET -> {
                { bytes: ByteStreamReader, keepBlack: Boolean, progressCallback: ((current: Int, total: Int) -> Boolean?)? ->
                    val progressCallbackWithPass = progressCallbackWithIgnoredPass(progressCallback)
                    val files: List<SpriteFile> = SprSetDecompiler.decompileSets(bytes, keepBlack, progressChunkSize = chunkSize, progressCallback = progressCallbackWithPass)
                        ?: throw SpriteParserException("Failed to parse multi-SPR sprite set file")
                    files.flatMap { it.frames() }
                }
            }

            S16 -> {
                { bytes: ByteStreamReader, keepBlack: Boolean, progressCallback: ((current: Int, total: Int) -> Boolean?)? ->
                    S16SpriteFile(bytes, keepBlack, progressChunkSize = chunkSize, progressCallback = progressCallback).frames()
                }
            }

            C16 -> {
                { bytes: ByteStreamReader, keepBlack: Boolean, progressCallback: ((current: Int, total: Int) -> Boolean?)? ->
                    C16SpriteFile(bytes, keepBlack, progressChunkSize = chunkSize, progressCallback = progressCallback).frames()
                }
            }

            BLK -> {
                { bytes: ByteStreamReader, _: Boolean, progressCallback: ((current: Int, total: Int) -> Boolean?)? ->
                    BlkSpriteFile(bytes, progressChunkSize = chunkSize, progressCallback = progressCallback).frames()
                }
            }

            PHOTO_ALBUM -> {
                { bytes: ByteStreamReader, _: Boolean, progressCallback: ((current: Int, total: Int) -> Boolean?)? ->
                    val album = parsePhotoAlbumInternal(bytes, progressChunkSize = chunkSize, progressCallback = progressCallback)
                            ?: throw SpriteParserException("Failed to parse photo album")
                    album.photos.map { it.bitmap32 }
                }
            }
        }
    }
