package com.bedalton.common.ast.structs

import kotlinx.serialization.Serializable

/**
 * Represents programming const constructs like variables, classes, interfaces etc.
 * that appear in a document. Document symbols can be hierarchical, and they
 * have two ranges: one that encloses its definition and one that points to
 * its most interesting range, e.g. the range of an identifier.
 */
@Serializable
data class DocumentSymbolImpl(
    /**
     * The name of this symbol. Will be displayed in the user interface and therefore must not be
     * an empty string or a string only consisting of white spaces.
     */
    override val name: String,


    /**
     * The kind of this symbol.
     * @see SymbolKind
     */
    override val kind: Int,

    /**
     * The range enclosing this symbol not including leading/trailing whitespace
     * but everything else like comments. This information is typically used to
     * determine if the client's cursor is inside the symbol to reveal in the UI.
     */
    override val range: Range,

    /**
     * The range that should be selected and revealed when this symbol is being picked, e.g. the name of a function.
     * Must be contained by the `range`.
     */
    override val selectionRange: Range,

    /**
     * Children of this symbol, e.g. properties of a class.
     */
    override val children: Array<DocumentSymbol>,

    /**
     * More detail for this symbol, e.g. the signature of a function.
     */
    override val detail: String? = null,

    /**
     * Tags for this document symbol.
     * @see SymbolTag
     * @since 3.16.0
     */
    override val tags: Array<Int> = emptyArray(),
): DocumentSymbol {
    override fun equals(other: Any?): Boolean {
        if (this === other) return true
        if (other !is DocumentSymbolImpl) return false

        if (name != other.name) return false
        if (kind != other.kind) return false
        if (range != other.range) return false
        if (selectionRange != other.selectionRange) return false
        if (!children.contentEquals(other.children)) return false
        if (detail != other.detail) return false
        if (!tags.contentEquals(other.tags)) return false

        return true
    }

    override fun hashCode(): Int {
        var result = name.hashCode()
        result = 31 * result + kind
        result = 31 * result + range.hashCode()
        result = 31 * result + selectionRange.hashCode()
        result = 31 * result + children.contentHashCode()
        result = 31 * result + (detail?.hashCode() ?: 0)
        result = 31 * result + tags.contentHashCode()
        return result
    }
}