package com.bedalton.creatures.breed.render.files

import com.bedalton.creatures.breed.render.support.pose.PoseRenderException
import com.bedalton.creatures.common.structs.GameVariant
import com.bedalton.log.LOG_DEBUG
import com.bedalton.log.Log
import com.bedalton.log.eIf


@Suppress("MemberVisibilityCanBePrivate")
data class FileTypes(
    val gameVariant: GameVariant,
    val allFiles: Set<BreedFileData>,
) {

    private val extensions by lazy {
        allFiles.map { it.extension }.toSet()
    }

    val hasAtts get() = "att" in extensions

    val hasSprites by lazy { validSpriteExtensions.intersect(extensions).isNotEmpty() }

    private val validSpriteExtensions: Set<String>
        get() {
            return when (gameVariant) {
                GameVariant.C1 -> setOf("spr")
                GameVariant.C2 -> setOf("s16")
                else -> setOf("c16", "s16")
            }
        }

    internal fun assertHasSpritesAndAtts() {
        if (!hasSprites) {
            if (!hasAtts) {
                Log.eIf(LOG_DEBUG) {
                    "Files list contains no sprites or ATTs for ${gameVariant.code}\nFiles:\n\t" + allFiles.joinToString("\n\t") { it.path }
                }
                throw PoseRenderException("File list contains no ATTs or sprites for game ${gameVariant.code}")
            } else {
                Log.eIf(LOG_DEBUG) {
                    "Files list contains no ${gameVariant.code} sprites\nFiles:\n\t" + allFiles.joinToString("\n\t") { it.path }
                }
                throw PoseRenderException("File list contains no ${gameVariant.code} sprites")
            }
        } else if (!hasAtts) {
            Log.eIf(LOG_DEBUG) {
                "Files list contains no ATTs\nFiles:\n\t" + allFiles.joinToString("\n\t") { it.path }
            }
            throw PoseRenderException("File list contains no ATTs")
        }
    }
}