package com.bedalton.io.bytes.internal

import kotlinx.coroutines.CancellationException
import kotlinx.coroutines.ensureActive
import kotlin.coroutines.coroutineContext

internal fun Throwable.rethrowIfCancellationException() {
    if (this is CancellationException || this is kotlin.coroutines.cancellation.CancellationException) {
        throw this
    }
}


internal suspend fun checkCancelled() {
    // Make sure coroutine has not been cancelled
    coroutineContext.ensureActive()
}