@file:Suppress("DuplicatedCode", "unused")

package com.bedalton.tauri

import kotlinx.coroutines.await
import tauri.dialog.*
import tauri.dialog.ConfirmDialogOptions
import kotlin.js.Promise

/**
 * Gets a single file path from open dialog
 *
 * @param init open options building lambda
 * @return
 */
suspend fun openSingleSuspending(init: OpenDialogOptions.() -> Unit): String? {
    val options = js("{}").unsafeCast<OpenDialogOptions>()
    options.init()
    if (options.multiple == true) {
        error("Cannot get single file in openSingle(), with \"multiple\" set to TRUE in OpenDialogOptions ")
    }
    options.multiple = false
    return open(options).unsafeCast<Promise<String?>>().await()
}

/**
 * Gets multiple file paths from an open dialog
 *
 * @param init open options building lambda
 * @return
 */
suspend fun openMultipleSuspending(init: OpenDialogOptions.() -> Unit): Array<String>? {
    val options = js("{}").unsafeCast<OpenDialogOptions>()
    options.init()
    if (options.multiple == false) {
        error("Cannot get multiple files in openMultiple(), with \"multiple\" set to FALSE in OpenDialogOptions ")
    }
    options.multiple = true
    return open(options).unsafeCast<Promise<Array<String>?>>().await()
}

/**
 * Gets the save path from a save dialog
 *
 * @param init open options building lambda
 * @return
 */
suspend fun showSaveDialogSuspending(init: SaveDialogOptions.() -> Unit): String? {
    val options = js("{}").unsafeCast<SaveDialogOptions>()
    options.init()
    return save(options).await()
}

/**
 * Shows a message with an OK button
 * @param message message to display
 */
suspend fun showMessageSuspending(message: String) {
    return message(message).await()
}

/**
 * Shows a message dialog with an Ok button.
