class PrayDataBuilder {


    private var language: String = "en-GB"
    private val inlineFiles: MutableSet<InlineFile> = mutableSetOf()
    private val blocks = mutableListOf<CompilerPrayBlock>()


    fun withInlineFile(file: Pair<String, String>): PrayDataBuilder {
        val outputFileName = text(file.first)
        val inputPath = text(file.second)
        this.inlineFiles += InlineFile(
            blockTag = "FILE",
            outputFileName = outputFileName,
            inputFileName = inputPath,
            lineNumber = 0, startIndex = 0, endIndex = 0,
            containingFile = ""
        )
        return this
    }

    fun withInlineFile(file: InlineFile): PrayDataBuilder {
        this.inlineFiles += file
        return this
    }

    fun withBlock(block: CompilerPrayBlock): PrayDataBuilder {
        blocks += block
        return this
    }

    fun tagBlock(
        blockTag: String,
        blockName: String,
    ): BlockWithTagsBuilder<PrayDataBuilder> {
        return BlockWithTagsBuilder(
            blockTag,
            blockName
        ) { block, inlines ->
            this.blocks += block
            for (inline in inlines) {
                withInlineFile(inline)
            }
            this
        }
    }

    fun withLanguage(language: String, validate: Boolean = true): PrayDataBuilder {
        if (validate && !language.matches(languageRegex)) {
            throw Exception("Possibly invalid language detected expected format en-GB")
        }
        this.language = language
        return this
    }

    @Deprecated(
        "use build without FileSystem parameter",
        replaceWith = ReplaceWith("build()")
    )
    fun build(@Suppress("UNUSED_PARAMETER") fs: FileSystem): CompilerPrayData {
        return build()
    }

    fun build(): CompilerPrayData {
        return CompilerPrayData(
            language = text(language),
            fullFilePath = "vfs://pray.txt",
//            blocks = (blocks + inlineFiles.map { inlineFile ->
//                val filename =
//                    PathUtil.getLastPathComponent(inlineFile.outputFileName.text) ?: inlineFile.outputFileName.text
//                DataBlock(
//                    "FILE",
//                    text("FILE"),
//                    text(filename),
//                    data = fs.read(inlineFile.inputFileName.text)
//                )
//            }).toTypedArray(),
            blocks = blocks.toTypedArray(),
            inlineFiles = inlineFiles.toUniqueArray(),
            joinedFiles = emptyArray(),
            parseErrors = emptyArray(),
            false
        )
    }

    companion object {
        private val languageRegex = "[a-zA-Z]{2}(-[a-zA-Z]{2})?".toRegex()
    }
}


class BlockWithTagsBuilder<T> internal constructor(
    private val blockTag: String,
    private val blockName: String,
    private val onBuild: (CompilerBlockWithTags, Set<Pair<String, String>>) -> T,
) {
    private val scripts: MutableList<String> = mutableListOf()
    private val dependencies: MutableSet<String> = mutableSetOf()
    private val inline: MutableList<Pair<String, String>> = mutableListOf()
    private val attachments: MutableList<Pair<String, String>> = mutableListOf()
    private val stringTags: MutableMap<String, Tag<*>> = mutableMapOf()
    private val intTags: MutableMap<String, Tag<*>> = mutableMapOf()

    init {
        if (blockTag.length != 4) {
            throw Exception("Block tag must be exactly four characters long; Found: $blockTag; Length[${blockTag.length}]")
        }
    }


    fun withStringTag(tag: String, value: String): BlockWithTagsBuilder<T> {
        stringTags[tag] = Tag.StringTag(
            0, 0, 0, 0,
            TextValue(tag, 0, 0, 0),
            TextValue(
                value,
                0, 0, 0
            ),
            value
        )
        return this
    }

    fun withIntTag(tag: String, value: Int): BlockWithTagsBuilder<T> {
        intTags[tag] = Tag.IntTag(
            0, 0, 0, 0,
            TextValue(tag, 0, 0, 0),
            int(value),
            value
        )
        return this
    }

    fun withInlineFile(file: String): BlockWithTagsBuilder<T> {
        pushFile(file, inline)
        return this
    }

    fun withInlineFile(path: String, fileName: String?): BlockWithTagsBuilder<T> {
        pushFile(path, fileName, inline)
        return this
    }


    fun withInlineFiles(files: Iterable<String>): BlockWithTagsBuilder<T> {
        pushFiles(files, inline)
        return this
    }

    fun withInlineFiles(files: Map<String, String?>): BlockWithTagsBuilder<T> {
        pushFiles(files, inline)
        return this
    }

    fun withInlineFiles(files: List<Pair<String, String?>>): BlockWithTagsBuilder<T> {
        pushFiles(files, inline)
        return this
    }

    fun withAttachment(file: String): BlockWithTagsBuilder<T> {
        return withAttachment(file, null)
    }


    fun withAttachment(path: String, fileName: String?): BlockWithTagsBuilder<T> {
        pushFile(path, fileName, attachments)
        return this
    }

    fun withAttachments(files: Iterable<String>): BlockWithTagsBuilder<T> {
        var out = this
        for (file in files) {
            out = out.withAttachment(file)
        }
        return this
    }

    /**
     * Add map of attachments where Map is Map<FilePath, FileName?>
     *
     * @param files
     * @return
     */
    fun withAttachments(files: Map<String, String?>): BlockWithTagsBuilder<T> {
        pushFiles(files, attachments)
        return this
    }

    /**
     * Add attachments from List of Pair<FilePath, FileName?>
     *
     * @param files
     * @return
     */
    fun withAttachments(files: List<Pair<String, String?>>): BlockWithTagsBuilder<T> {
        pushFiles(files, attachments)
        return this
    }


    fun withDependency(file: String): BlockWithTagsBuilder<T> {
        this.dependencies.add(file)
        return this
    }


    fun withDependency(files: Iterable<String>): BlockWithTagsBuilder<T> {
        this.dependencies.addAll(files)
        return this
    }


    fun build(): T {
        withIntTag("Script Count", scripts.size)
        for ((i, script) in scripts.withIndex()) {
            withStringTag("Script $i", script)
        }
        val dependencies: Set<String> = dependencies + attachments.map { it.first }
        withIntTag("Dependency Count", dependencies.size)
        for ((iZero, dependency) in dependencies.withIndex()) {
            val i = iZero + 1
            val category = bestDependencyCategoryForFile(dependency)
                ?: throw Exception("Could not determine dependency category for <$dependency>")
            withStringTag("Dependency $i", PathUtil.getLastPathComponent(dependency) ?: dependency)
            withIntTag("Dependency Category $i", category)
        }
        val tags = (stringTags.values + intTags.values).toTypedArray()
        val block = CompilerGeneralBlockWithTags(
            startLine = 0,
            blockTag = text(blockTag),
            blockName = text(blockName),
            unescape = false,
            tags = tags
        )
        return onBuild(block, (inline + attachments).toSet())
    }

    fun pushFiles(filePaths: Iterable<String>, files: MutableList<Pair<String, String>>) {
        for (filePath in filePaths) {
            pushFile(filePath, null, files)
        }
    }

    /**
     * Push files with Map<FilePath, FileName?>
     *
     * @param filePaths Map<FilePath, FileName?>
     * @param files
     */
    fun pushFiles(filePaths: Map<String, String?>, files: MutableList<Pair<String, String>>) {
        for ((filePath, fileName) in filePaths) {
            pushFile(filePath, fileName, files)
        }
    }

    /**
     * Push files, with list of Pair<FilePath, FileName?>
     *
     * @param filePaths list of Pair<FilePath, FileName?>
     * @param files
     */
    fun pushFiles(filePaths: List<Pair<String, String?>>, files: MutableList<Pair<String, String>>) {
        for ((filePath, fileName) in filePaths) {
            pushFile(filePath, fileName, files)
        }
    }


    fun pushFile(filePath: String, files: MutableList<Pair<String, String>>) {
        pushFile(filePath, null, files)
    }

    fun pushFile(filePath: String, fileName: String?, files: MutableList<Pair<String, String>>) {
        val fileNameNotNull = fileName
            ?.nullIfEmpty()
            ?: PathUtil.getLastPathComponent(filePath).nullIfEmpty()
            ?: filePath
                .split("[/\\\\]".toRegex())
                .last()
                .nullIfEmpty()
            ?: throw IllegalArgumentException("Failed to get filename from filepath <$filePath>")
        files.add(Pair(fileNameNotNull, filePath))
    }
}


private fun text(value: String): TextValue {
    return TextValue(
        value,
        0, 0, 0
    )
}

private fun int(value: Int): TextValue {
    return TextValue(
        value,
        0, 0, 0
    )
}