package com.bedalton.creatures.breed.render.internal

import com.bedalton.creatures.sprite.util.PaletteTransform

actual fun dynamicToPaletteTransform(palette: Any?): PaletteTransform? {
    if (palette is PaletteTransform) {
        return palette
    }
    return com.bedalton.creatures.sprite.util.dynamicToPaletteTransform(palette.asDynamic())
}