package com.creaturesforge.application.interop

import JsArray
import com.bedalton.common.exceptions.asThrowable
import com.bedalton.common.exceptions.rethrowCancellationException
import com.bedalton.common.util.PathUtil
import com.bedalton.common.util.formatted
import com.bedalton.common.util.joinToString
import com.bedalton.log.Log
import kotlinx.coroutines.sync.Mutex
import kotlinx.coroutines.sync.withLock

private val hashMutex = Mutex()
private val written: MutableMap<String, CacheDirectory> = mutableMapOf()

private suspend fun createAgentCacheDirectory(): String? {
    return try {
        tauriAsync<String>("create_agent_cache_directory")
    } catch (eDynamic: dynamic) {
        val e = asThrowable(eDynamic)
        e.rethrowCancellationException()
        Log.e("Failed to create agent cache directory: " + e.formatted())
        null
    }
}

private suspend fun writeFileToCacheDirectory(path: String, bytes: ByteArray): Boolean {
    return try {
        tauriAsync<Boolean>("write_agent_cache_file") {
            this.path = path
            this.bytes = JsArray.from<dynamic>(bytes)
        }
    } catch (eDynamic: dynamic) {
        val e = asThrowable(eDynamic)
        e.rethrowCancellationException()
        Log.e("Failed to write file[$path] to cache directory: " + e.formatted())
        false
    }
}


internal suspend fun writeAgentFilesToCache(projectRoot: String, files: Map<String, ByteArray>): String? = hashMutex.withLock {
    val previous = written[projectRoot.lowercase()]
    val hashString = CacheDirectory.toHashString(files)
    if (previous != null) {
        if (previous.hashString == hashString) {
            return previous.cacheDirectory
        }
    }

    val cacheDirectory = createAgentCacheDirectory()
        ?: return null

    for ((virtualPath, bytes) in files) {
        val path = PathUtil.combine(cacheDirectory, virtualPath.split("/").last())
        if (!writeFileToCacheDirectory(path, bytes)) {
            return null
        }
    }

    written[projectRoot.lowercase()] = CacheDirectory(
        cacheDirectory,
        hashString,
        cacheDirectory
    )
    return cacheDirectory
}


private data class CacheDirectory(
    val projectRoot: String,
    val hashString: String,
    val cacheDirectory: String,
) {
    constructor(
        projectRoot: String,
        files: Map<String, ByteArray>,
        cacheDirectory: String
    ): this(projectRoot, toHashString(files), cacheDirectory)


    companion object {
        fun toHashString(files: Map<String, ByteArray>): String {
            return files.entries.sortedBy { it.key }.joinToString(";") { it.key + ":" + it.value.size + ":" + it.value.hashCode() }
        }
    }
}