@file:Suppress("unused")

package com.bedalton.creatures.agents.pray.compiler

import kotlin.js.JsExport
import kotlin.js.JsName

/**
 * Concrete implementation of the IPrayCompilerTask interface
 */
@JsExport
data class PrayCompilerTaskImpl(
    /**
     * Merge all scripts in pray files into one giant script
     */
    override val mergeScripts: Boolean,
    /**
     * Whether to validate PRAY file syntax and inline files references
     */
    override val validate: Boolean,
    /**
     * Absolute path to input pray file
     */
    override val inputFile: String,
    /**
     * Absolute output path for the compiled file
     */
    override val outputDirectory: String,
    /**
     * Whether to log information about classes and scripts in pray files
     */
    override val printStats: Boolean,

    /**
     * Whether to merge all removal scripts across all files into one massive removal script
     */
    override val mergeRscr: Boolean,

    /**
     * Create removers for all created agent classifiers
     * Parses new: (simp|comp|*) creation statements and generates a remover for that class
     */
    override val generateScriptRemovers: Boolean,
    /**
     * Create removers for all created agent classifiers
     * Parses new: (simp|comp|*) creation statements and generates a remover for that class
     */
    override val generateAgentRemovers: Boolean,

    /**
     * Whether to log compilation progress to the console
     */
    override val logProgress: Boolean,

    /**
     * PRAY source files for agents to be inlined into a single multi-agent bundle
     */
    override val joins: Array<String> = emptyArray(),

    /**
     * Whether the agent(s) in this PRAY file are to be combined into a single multi-agents bundle
     */
    override val isJoin: Boolean = false,

    /**
     * Level of GZIP compression to apply [0-9]; 0/null=None; 9=Max
     */
    override val compressionLevel: Int?,

    /**
     * Prefix Linked CAOS file tags with source filename
     */
    override val linkWithFilenameReference: Boolean? = null,

    /**
     * Whether to JOIN CAOS2Pray files recursively
     */
    override val recursiveJoins: Boolean? = null,

    /**
     * Override the CAOS2Pray supplied agent file name
     */
    override val overrideAgentName: String? = null,

) : IPrayCompilerTask,
    PrayCompileOptionsWithLinkWithFileName,
    PrayCompileOptionsWithRecursiveJoin,
    PrayCompileOptionsWithOverrideName
{

    @JsName("construct")
    constructor(
        mergeScripts: Boolean,
        validate: Boolean,
        inputFile: String,
        outputDirectory: String,
        printStats: Boolean,
        mergeRscr: Boolean,
        generateScriptRemovers: Boolean,
        generateAgentRemovers: Boolean,
        logProgress: Boolean,
        joins: Array<String> = emptyArray(),
        isJoin: Boolean = false,
        compressionLevel: Int?,
    ): this(
        mergeScripts = mergeScripts,
        validate = validate,
        inputFile = inputFile,
        outputDirectory = outputDirectory,
        printStats = printStats,
        mergeRscr = mergeRscr,
        generateScriptRemovers = generateScriptRemovers,
        generateAgentRemovers = generateAgentRemovers,
        logProgress = logProgress,
        joins = joins,
        isJoin = isJoin,
        compressionLevel = compressionLevel,
        linkWithFilenameReference = null,
        recursiveJoins = null,
        overrideAgentName = null
    )


    /**
     * Flag this pray task as producing an agent should be inlined into a single multi-agent bundle
     */
    override fun asJoin(): PrayCompilerTaskImpl {
        return copy(isJoin = true)
    }

    /**
     * List of pray files to inline as children in this single file multi-agent bundle
     */
    override fun withJoins(joins: Array<String>): PrayCompilerTaskImpl {
        return copy(joins = joins)
    }

    override fun equals(other: Any?): Boolean {
        if (this === other) return true
        if (other !is PrayCompilerTaskImpl) return false

        if (mergeScripts != other.mergeScripts) return false
        if (validate != other.validate) return false
        if (inputFile != other.inputFile) return false
        if (outputDirectory != other.outputDirectory) return false
        if (printStats != other.printStats) return false
        if (mergeRscr != other.mergeRscr) return false
        if (generateScriptRemovers != other.generateScriptRemovers) return false
        if (generateAgentRemovers != other.generateAgentRemovers) return false
        if (logProgress != other.logProgress) return false
        if (!joins.contentEquals(other.joins)) return false
        if (isJoin != other.isJoin) return false

        return true
    }

    override fun hashCode(): Int {
        var result = mergeScripts.hashCode()
        result = 31 * result + validate.hashCode()
        result = 31 * result + inputFile.hashCode()
        result = 31 * result + outputDirectory.hashCode()
        result = 31 * result + printStats.hashCode()
        result = 31 * result + mergeRscr.hashCode()
        result = 31 * result + generateScriptRemovers.hashCode()
        result = 31 * result + generateAgentRemovers.hashCode()
        result = 31 * result + logProgress.hashCode()
        result = 31 * result + joins.contentHashCode()
        result = 31 * result + isJoin.hashCode()
        return result
    }
}

