package com.bedalton.common.structs


fun <V> mutableCaselessMapOf(vararg pairs: Pair<String, V>): MutableMap<String, V> {
    val out = MutableCaselessMap<V>()
    for ((key, value) in pairs) {
        out[key] = value
    }
    return out
}

fun <V> caselessMapOf(vararg pairs: Pair<String, V>): Map<String, V> {
    return CaselessMap(pairs.toMap())
}

fun <V> Map<String, V>.toCaselessMap() = CaselessMap(this)
fun <V> Map<String, V>.toMutableCaselessMap() = MutableCaselessMap(this)