package com.bedalton.creatures.agents.pray.data

import com.bedalton.creatures.agents.pray.exceptions.PrayBlockWriteNotImplementedException
import com.bedalton.creatures.agents.pray.internal.*
import com.bedalton.io.bytes.ByteStreamWriter
import kotlin.js.JsExport

/**
 * Generic Pray Block object
 */
@JsExport
sealed class PrayBlock(
    open val blockTag: String,
    open val blockName: String,
) {

    internal abstract fun write(writer: ByteStreamWriter, compress: Boolean)

    internal val label get() = "[$blockTag]->\"$blockName\""


    class NotImplementedPrayBlock(
        val commonName: String,
        blockTag: String,
        blockName: String,
    ): PrayBlock(blockTag, blockName) {
        override fun write(writer: ByteStreamWriter, compress: Boolean) {
            val error = if (commonName == blockTag)
                "Cannot write $blockTag block; Feature not implemented"
            else
                "Cannot write $commonName block (${blockTag}); Feature not implemented"
            throw PrayBlockWriteNotImplementedException(error)
        }
    }

    companion object {
        fun makeBlock(
            blockTag: String,
            blockName: String,
            safe: Boolean,
            unescape: Boolean,
            getTags: () -> Array<Tag<*>> = { emptyArray() }
        ): PrayBlock {
            // Determine block type from block tag
            return when (tok(blockTag.uppercase())) {
                in NON_AGENT_TAG_BLOCKS -> GeneralBlockWithTags(blockTag, blockName, safe, unescape, getTags)
                // Starter families
                in FILE_BLOCKS -> NotImplementedPrayBlock(blockTag, blockTag, blockName)
                in UNSUPPORTED_BLOCKS -> NotImplementedPrayBlock(blockTag, blockTag, blockName)
                else -> {
                    // Check if miscellaneous tag is SeaMonkey Animation
                    if (SEA_MONKEY_ANIMATION_TAG.matches(blockTag)) {
                        return NotImplementedPrayBlock(
                            commonName = "SeaMonkey Animation",
                            blockTag = blockTag,
                            blockName = blockName
                        )
                    }
                    // Tag can be user defined agent tag
                    AgentBlock(
                        blockTag = blockTag,
                        blockName = blockName,
                        safe = safe,
                        unescape,
                        getTags = getTags
                    )
                }
            }
        }
    }
}