package com.bedalton.creatures.agents.pray.compiler.pray.validators

import com.bedalton.common.util.PathUtil
import com.bedalton.common.util.nullIfEmpty
import com.bedalton.creatures.agents.pray.compiler.DEPENDENCY_CATEGORY_REGEX
import com.bedalton.creatures.agents.pray.compiler.DEPENDENCY_TAG_REGEX
import com.bedalton.creatures.agents.pray.compiler.pray.*
import com.bedalton.creatures.agents.pray.compiler.pray.PrayValidationError.DependencyError
import com.bedalton.creatures.agents.pray.compiler.data.BlockDependency
import com.bedalton.creatures.agents.pray.compiler.data.Tag
import com.bedalton.creatures.agents.pray.compiler.data.TextValue

/**
 * Validates dependencies for existence and correctness
 */
internal fun validateDependencies(
    fullFilePath: String,
    validationErrors: MutableList<PrayValidationError>,
    blockTag: TextValue,
    blockName: TextValue,
    tags: Array<Tag<*>>,
) {
    // Get dependency count tag if any
    val dependencyCountResult = getDependencyCount(
        fullFilePath = fullFilePath,
        validationErrors = validationErrors,
        blockTag = blockTag,
        blockName = blockName,
        tags = tags
    )
    val dependencyCount = dependencyCountResult?.first

    // Find dependencies
    val dependencies = getBlockDependencies(tags)
        .sortedBy {
            it.index
        }

    val dependencyValueTypeErrors = tags.filterIsInstance<Tag.IntTag>().filter {
        DEPENDENCY_TAG_REGEX.matches(it.tag)
    }.map {
        DependencyError(
            blockTag,
            blockName,
            message = "Dependency tags should have a string value",
            lineNumber = it.valueRange.lineNumber,
            startIndex = it.valueRange.startIndex,
            endIndex = it.valueRange.endIndex,
            fullFilePath = fullFilePath
        )
    } + tags.filterIsInstance<Tag.StringTag>().filter {
        DEPENDENCY_CATEGORY_REGEX.matches(it.tag)
    }.map {
        DependencyError(
            blockTag,
            blockName,
            message = "Dependency categories should have an integer value",
            lineNumber = it.valueRange.lineNumber,
            startIndex = it.valueRange.startIndex,
            endIndex = it.valueRange.endIndex,
            fullFilePath = fullFilePath
        )
    }

    validationErrors.addAll(dependencyValueTypeErrors)

    // If no dependency count found, issue error if needed
    if (dependencyCountResult == null) {
        // There is no dependency count and no dependencies
        // Nothing to validate
        if (dependencies.isEmpty())
            return

        val item = dependencies.minByOrNull {
                listOfNotNull(it.fileName?.lineNumber, it.category?.lineNumber).minOrNull()!!
            }?.first
        // No validation count, but dependencies exist
        // com.bedalton.creatures.pray.Log missing dependency count error
        validationErrors.add(
            DependencyError(
                blockTag = blockTag,
                blockName = blockName,
                message = "Missing \"Dependency Count\" tag",
                lineNumber = item?.lineNumber ?: -1,
                startIndex = item?.startIndex ?: -1,
                endIndex = item?.endIndex ?: -1,
                fullFilePath = fullFilePath
            )
        )
    }

// Find the dependency indices that exist in tags
    val has: List<Int> = dependencies
        .map {
            it.index
        }
        .sorted()

// If Dependency count is not null, find any missing numbers in range of 1..(count)
    if (dependencyCount != null) {
        validateExpectedDependencyTagsExist(
            fullFilePath = fullFilePath,
            validationErrors = validationErrors,
            blockName = blockName,
            blockTag = blockTag,
            dependencyCountTag = dependencyCountResult.second,
            has = has.toSet()
        )
    }

// Find Duplicates in Dependency tags
    for (i in has.indices) {
        if (i > 0 && has[i - 1] == has[i]) {
            val item = has[i]
            val dependency = dependencies[i]
            validationErrors.add(
                DependencyError(
                    blockTag = blockTag,
                    blockName = blockName,
                    "Duplicate \"Dependency $item\" declaration",
                    lineNumber = dependency.lineNumber,
                    startIndex = dependency.first!!.tagRange.startIndex + 12,
                    endIndex = dependency.first!!.tagRange.endIndex - 1,
                    fullFilePath = fullFilePath
                )
            )
        }
    }

// Loop through dependencies looking for missing indices
    for (dependency in dependencies) {
        validateDependency(
            fullFilePath,
            validationErrors,
            blockTag,
            blockName,
            dependencyCount,
            dependency
        )
    }
}


/**
 * Gets the count of dependencies and adds errors as necessary
 */
private fun getDependencyCount(
    fullFilePath: String,
    validationErrors: MutableList<PrayValidationError>,
    blockTag: TextValue,
    blockName: TextValue,
    tags: Array<Tag<*>>,
): Pair<Int?, Tag.IntTag>? {
    val dependencyCountTags = tags.filter { it.tag.equals("Dependency Count", true) }
    // Validate dependency count is int value
    validationErrors.addAll(
        dependencyCountTags.filterIsInstance<Tag.StringTag>()
            .map { tag ->
                DependencyError(
                    blockTag,
                    blockName,
                    "Dependency Count tag found with string value, must be int",
                    lineNumber = tag.valueRange.lineNumber,
                    startIndex = tag.valueRange.startIndex,
                    endIndex = tag.valueRange.endIndex,
                    fullFilePath = fullFilePath
                )
            }
    )

    // Validate dependency int tags
    val intTags = dependencyCountTags.filterIsInstance<Tag.IntTag>()

    // Validate has value
    if (intTags.isEmpty()) {
        return null
    }

    // Validate only one tag
    if (dependencyCountTags.size > 1) {
        if (intTags.size > 1) {
            for (tag in intTags) {
                validationErrors.add(
                    DependencyError(
                        blockTag = blockTag,
                        blockName = blockName,
                        message = "Too many dependency count tags",
                        lineNumber = tag.lineNumber,
                        startIndex = tag.startIndex,
                        endIndex = tag.endIndex,
                        fullFilePath = fullFilePath
                    )
                )
            }
            // If multiple tags, check if same value
            // Return if tags are same value
            val values = intTags.map { it.value }.toSet()
            if (values.size != intTags.size)
                return null
        }
    }
    // Return the actual dependency count
    return Pair(intTags.first().value, intTags.first())
}

private fun validateDependency(
    fullFilePath: String,
    validationErrors: MutableList<PrayValidationError>,
    blockTag: TextValue,
    blockName: TextValue,
    dependencyCount: Int?,
    dependency: BlockDependency,
) {
    if (dependency.index < 1) {
        validationErrors.add(
            DependencyError(
                blockTag = blockTag,
                blockName = blockName,
                message = "Dependencies start at index 1",
                lineNumber = dependency.first!!.tagRange.lineNumber,
                startIndex = dependency.first!!.tagRange.startIndex,
                endIndex = dependency.first!!.tagRange.endIndex,
                fullFilePath = fullFilePath
            )
        )
    } else {
        validateDependencyNumberIsValid(
            fullFilePath,
            validationErrors = validationErrors,
            blockTag = blockTag,
            blockName = blockName,
            dependencyCount = dependencyCount,
            dependency = dependency
        )
    }

    if (dependency.category == null) {
        validationErrors.add(
            DependencyError(
                blockTag,
                blockName,
                "Missing dependency category ${dependency.index}",
                lineNumber = dependency.lineNumber,
                startIndex = dependency.fileName!!.tagRange.startIndex + 12,
                endIndex = dependency.fileName.tagRange.endIndex - 1,
                fullFilePath = fullFilePath
            )
        )
    } else {
        validateDependencyCategory(fullFilePath, validationErrors, blockTag, blockName, dependency)
    }
    if (dependency.fileName == null) {
        validationErrors.add(
            DependencyError(
                blockTag,
                blockName,
                "Missing associated \"Dependency ${dependency.index}\" tag",
                lineNumber = dependency.lineNumber,
                startIndex = dependency.category!!.tagRange.startIndex + 21,
                endIndex = dependency.category.tagRange.endIndex -1,
                fullFilePath = fullFilePath
            )
        )
    }

}

/**
 * Validates the category of a dependency
 * i.e. Makes sure sprites go into images and wave files into sound
 */
private fun validateDependencyCategory(
    fullFilePath: String,
    validationErrors: MutableList<PrayValidationError>,
    blockTag: TextValue,
    blockName: TextValue,
    dependency: BlockDependency,
) {
    if (dependency.category == null || dependency.fileName == null) {
        return
    }
    val category = dependency.category
    val categoryId = category.value

    if (dependency.fileName !is Tag.StringTag) {
        return
    }

    if (PathUtil.getFileName(dependency.fileName.value).nullIfEmpty() == null) {
        validationErrors.add(
            DependencyError(
                blockTag = blockTag,
                blockName = blockName,
                message = "Invalid dependency ${dependency.index}; No file extension provided for \"${dependency.fileName.value}\"",
                lineNumber = category.valueRange.lineNumber,
                startIndex = category.valueRange.startIndex,
                endIndex = category.valueRange.endIndex,
                fullFilePath = fullFilePath
            )
        )
        return
    }

    val shouldBe = bestDependencyCategoryForFile(dependency.fileName.value)
    val suggestion = if (shouldBe != null) {
        ". Did you mean Category $shouldBe (${CATEGORIES[shouldBe]})"
    } else {
        ""
    }
    if (categoryId !in VALID_CATEGORIES) {
        validationErrors.add(
            DependencyError(
                blockTag = blockTag,
                blockName = blockName,
                message = "Invalid dependency category for Dependency ${dependency.index} \"${dependency.fileName.value}\" was $categoryId $suggestion",
                lineNumber = category.valueRange.lineNumber,
                startIndex = category.valueRange.startIndex,
                endIndex = category.valueRange.endIndex,
                fullFilePath = fullFilePath
            )
        )
        return
    }
    if (shouldBe != null && shouldBe != categoryId) {
        validationErrors.add(
            DependencyError(
                blockTag = blockTag,
                blockName = blockName,
                message = "**WARN::${dependency.fileName} to be placed in ${CATEGORIES[categoryId]} folder$suggestion",
                lineNumber = category.valueRange.lineNumber,
                startIndex = category.valueRange.startIndex,
                endIndex = category.valueRange.endIndex,
                fullFilePath = fullFilePath
            )
        )
    }
}

/**
 * Ensure that all dependencies in range 1...(count) are accounted for
 */
private fun validateExpectedDependencyTagsExist(
    fullFilePath: String,
    validationErrors: MutableList<PrayValidationError>,
    blockTag: TextValue,
    blockName: TextValue,
    dependencyCountTag: Tag.IntTag,
    has: Set<Int>,
) {
    val dependencyCount = dependencyCountTag.value
    val valid = (1..dependencyCount).intersect(has.filter { it <= dependencyCount }.toSet())
    if (valid.size != dependencyCount) {
        val missing = (1..dependencyCount).filterNot { it in valid }
        if (missing.isNotEmpty()) {
            validationErrors.add(
                DependencyError(
                    blockTag,
                    blockName,
                    "Missing dependencies [${missing.joinToString(", ")}]",
                    lineNumber = dependencyCountTag.valueRange.lineNumber,
                    startIndex = dependencyCountTag.valueRange.startIndex,
                    endIndex = dependencyCountTag.valueRange.endIndex,
                    fullFilePath = fullFilePath
                )
            )
        }
    }
}

/**
 * Validates that dependency number is less than or equal to declared dependency count
 */
private fun validateDependencyNumberIsValid(
    fullFilePath: String,
    validationErrors: MutableList<PrayValidationError>,
    blockTag: TextValue,
    blockName: TextValue,
    dependencyCount: Int?,
    dependency: BlockDependency,
) {
    if (dependencyCount == null || dependency.index <= dependencyCount)
        return
    val lines = listOfNotNull(dependency.category, dependency.fileName)
    for (line in lines) {
        validationErrors.add(
            DependencyError(
                blockTag = blockTag,
                blockName = blockName,
                message =  "Dependency ${dependency.index} is out of bounds. Expected 1..$dependencyCount",
                lineNumber = line.tagRange.lineNumber,
                startIndex = line.tagRange.startIndex + (if (line == dependency.category) 21 else 12),
                endIndex = line.tagRange.endIndex - 1,
                fullFilePath = fullFilePath
            )
        )
    }
}